const DOMANDE = [{"id":1,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"La funzione legislativa è attribuita:","correct":"al Parlamento","wrong1":"alla Corte costituzionale","wrong2":"ai giudici","wrong3":"alla Corte di Cassazione"},{"id":2,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"La funzione esecutiva è attribuita:","correct":"al Governo","wrong1":"al Parlamento","wrong2":"alla Corte costituzionale","wrong3":"ai giudici"},{"id":3,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"La funzione giurisdizionale è attribuita:","correct":"ai giudici","wrong1":"al Parlamento","wrong2":"al Presidente della Repubblica","wrong3":"al governo"},{"id":4,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Gli elementi costitutivi dello Stato sono i seguenti:","correct":"popolo, territorio, sovranità","wrong1":"nazione, territorio, sovranità","wrong2":"popolo, nazione, sovranità","wrong3":"sudditi, territorio, sovranità"},{"id":5,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Il criterio in base al quale si acquista la cittadinanzadei genitori prende il nome di:","correct":"ius sanguinis","wrong1":"ius soli","wrong2":"ius postulandi","wrong3":"usus"},{"id":6,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Il criterio in base al quale si acquista la cittadinanzadel luogo di nascita prende il nome di:","correct":"ius soli","wrong1":"ius postulandi","wrong2":"usus","wrong3":"ius sanguinis"},{"id":7,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Il mare territoriale:","correct":"appartiene al territorio dello Stato","wrong1":"non appartiene al territorio dello Stato","wrong2":"appartiene al territorio dello Stato confinante","wrong3":"appartiene alla comunità internazionale"},{"id":8,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Lo spazio aereo sovrastante:","correct":"appartiene al territorio dello Stato","wrong1":"non appartiene al territorio dello Stato","wrong2":"appartiene al territorio dello Stato confinante","wrong3":"appartiene alla comunità internazionale"},{"id":9,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"La terraferma:","correct":"appartiene al territorio dello Stato","wrong1":"non appartiene al territorio dello Stato","wrong2":"appartiene al territorio dello Stato confinante","wrong3":"appartiene alla comunità internazionale"},{"id":10,"paragraph":"Principi costituzionali  - Il concetto di Stato","question":"Ai sensi dell'art. 1, co. 2 Cost. la sovranità appartiene:","correct":"al popolo","wrong1":"al Parlamento","wrong2":"al Governo","wrong3":"alla nazione"},{"id":11,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Ai sensi dell'art. 11 Cost., l'Italia ripudia la guerracome strumento di offesa alla libertà:","correct":"degli altri popoli","wrong1":"delle altre nazioni","wrong2":"degli altri Stati","wrong3":"delle altre genti"},{"id":12,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"L'art. 75 Cost. parla di referendum:","correct":"popolare","wrong1":"nazionale","wrong2":"statale","wrong3":"comunitario"},{"id":13,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Ai sensi dell'art. 101 Cost., la giustizia è amministratain nome:","correct":"del popolo","wrong1":"della nazione","wrong2":"della popolazione","wrong3":"della cittadinanza"},{"id":14,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Ai sensi dell'art. 9 Cost., la Repubblica tutela ilpatrimonio storico e artistico:","correct":"della nazione","wrong1":"del popolo","wrong2":"della popolazione","wrong3":"della cittadinanza"},{"id":15,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Ai sensi dell'art. 98 Cost., i pubblici impiegati sono alservizio esclusivo:","correct":"della nazione","wrong1":"del popolo","wrong2":"della popolazione","wrong3":"della cittadinanza"},{"id":16,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Il principio per cui la cittadinanza si acquista in virtùdei rapporti tra i cittadini e i loro discendenti prende ilnome di:","correct":"ius sanguinis","wrong1":"ius soli","wrong2":"status civitatis","wrong3":"ius excludendi"},{"id":17,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"Il principio che fa leva sul luogo di origine degliindividui in questione, attribuendo la cittadinanza achi nasca nel territorio dello Stato prende il nome di","correct":"ius soli","wrong1":"ius sanguinis","wrong2":"status civitatis","wrong3":"ius excludendi"},{"id":18,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"La complessiva posizione giuridica spettante alcittadino di uno Stato prende il nome di:","correct":"status civitatis","wrong1":"ius sanguinis","wrong2":"ius soli","wrong3":"ius excludendi"},{"id":19,"paragraph":"Principi costituzionali  - Lo Stato e le sue forme","question":"All'interno del territorio di riferimento la sovranitàstatale consiste nello:","correct":"ius excludendi alios","wrong1":"ius sanguinis","wrong2":"ius soli","wrong3":"ius gentium"},{"id":20,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"La Costituzione è entrata in vigore nel:","correct":"1948","wrong1":"1946","wrong2":"1942","wrong3":"1945"},{"id":21,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"Le leggi costituzionali si collocano al livello:","correct":"superprimario","wrong1":"primario","wrong2":"secondario","wrong3":"sub-secondario"},{"id":22,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"Le leggi ordinarie si collocano al livello:","correct":"primario","wrong1":"superprimario","wrong2":"secondario","wrong3":"sub-secondario"},{"id":23,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"I regolamenti governativi si collocano al livello:","correct":"secondario","wrong1":"superprimario","wrong2":"primario","wrong3":"sub-secondario"},{"id":24,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"I regolamenti ministeriali si collocano al livello:","correct":"secondario","wrong1":"superprimario","wrong2":"primario","wrong3":"sub-secondario"},{"id":25,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"La nostra Costituzione è:","correct":"rigida","wrong1":"flessibile","wrong2":"ottriata","wrong3":"breve"},{"id":26,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"La nostra Costituzione è:","correct":"votata","wrong1":"flessibile","wrong2":"ottriata","wrong3":"breve"},{"id":27,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"La nostra Costituzione è:","correct":"lunga","wrong1":"flessibile","wrong2":"ottriata","wrong3":"breve"},{"id":28,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"La nostra Costituzione è:","correct":"scritta","wrong1":"flessibile","wrong2":"ottriata","wrong3":"breve"},{"id":29,"paragraph":"Principi costituzionali - Il diritto e le sue fonti","question":"L'elemento oggettivo della consuetudine prende ilnome di:","correct":"diuturnitas","wrong1":"opinio iuris","wrong2":"usus","wrong3":"opinio iuris ac necessitatis"},{"id":30,"paragraph":"Principi costituzionali - La Costituzione repubblicana","question":"Il controllo sulla costituzionalità delle leggi èrimesso:","correct":"alla Corte costituzionale","wrong1":"Al Consiglio di Stato","wrong2":"Alla Corte costituzionale","wrong3":"Al CSM"},{"id":31,"paragraph":"Principi costituzionali - La Costituzione repubblicana","question":"Il potere costituente è attribuito:","correct":"al popolo","wrong1":"Alla Corte costituzionale","wrong2":"Al Governo","wrong3":"Al Presidente della Repubblica"},{"id":32,"paragraph":"Principi costituzionali - La Costituzione repubblicana","question":"Il 18 giugno 1946 fu eletto Capo provvisorio delloStato:","correct":"Enrico De Nicola","wrong1":"Giovanni Leone","wrong2":"Alcide De Gasperi","wrong3":"Luigi Einaudi"},{"id":33,"paragraph":"Principi costituzionali - La Costituzione repubblicana","question":"La Costituzione italiana è composta da:","correct":"139 articoli","wrong1":"138 articoli","wrong2":"120 articoli","wrong3":"111 articoli"},{"id":34,"paragraph":"Principi costituzionali - La funzione legislativa","question":"La funzione legislativa spetta:","correct":"al Parlamento","wrong1":"al Governo","wrong2":"al Presidente della Repubblica","wrong3":"alla Camera dei deputati"},{"id":35,"paragraph":"Principi costituzionali - La funzione legislativa","question":"La legge è fonte:","correct":"primaria","wrong1":"secondaria","wrong2":"subprimaria","wrong3":"atipica"},{"id":36,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Il potere di iniziativa legislativa non spetta:","correct":"al Presidente della Repubblica","wrong1":"al Governo","wrong2":"ai Consigli regionali","wrong3":"al CNEL"},{"id":37,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Per i disegni di legge in materia costituzionale ed elettorale si utilizza:","correct":"il procedimento normale","wrong1":"il procedimento misto","wrong2":"il procedimento decentrato","wrong3":"il procedimento aggravato"},{"id":38,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Per i disegni di legge in materia di delegazione legislativa si utilizza:","correct":"il procedimento normale","wrong1":"il procedimento misto","wrong2":"il procedimento decentrato","wrong3":"il procedimento aggravato"},{"id":39,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Nel procedimento di formazione della legge ordinaria statale al Presidente della Repubblica spetta:","correct":"la promulgazione","wrong1":"l'iniziativa","wrong2":"la sanzione","wrong3":"la pubblicazione"},{"id":40,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Se le Camere ritengono di non prestare ascolto ai rilievi del Presidente, e riapprovano nello stesso testo la legge rinviata:","correct":"il Presidente è obbligato a promulgare","wrong1":"si procede ad un ulteriore riesame","wrong2":"il Presidente scioglie le Camere","wrong3":"il procedimento si arresta"},{"id":41,"paragraph":"Principi costituzionali - La funzione legislativa","question":"Emanato il decreto di promulgazione, la legge viene pubblicata a cura:","correct":"del Ministro della Giustizia","wrong1":"del Presidente della Repubblica","wrong2":"del Presidente della Camera che ha approvato per ultima la legge","wrong3":"del Ministro dell'Interno"},{"id":42,"paragraph":"Principi costituzionali - La funzione legislativa","question":"La pubblicazione viene effettuata:","correct":"sulla Gazzetta Ufficiale","wrong1":"sul Bollettino Ufficiale","wrong2":"sulla Raccolta Ufficiale","wrong3":"sul Massimario della Cassazione"},{"id":43,"paragraph":"Principi costituzionali - La funzione legislativa","question":"La durata ordinaria del periodo di vacatio legis è di:","correct":"15 giorni","wrong1":"10 giorni","wrong2":"60 giorni","wrong3":"30 giorni"},{"id":44,"paragraph":"Principi costituzionali - Le antinomie","question":"I regolamenti ministeriali si collocano al livello:","correct":"sub-secondario","wrong1":"superprimario","wrong2":"primario","wrong3":"secondario"},{"id":45,"paragraph":"Principi costituzionali - Le antinomie","question":"Il brocardo lex posterior derogat legi priori indica il criterio:","correct":"cronologico","wrong1":"gerarchico","wrong2":"di specialità","wrong3":"di competenza"},{"id":46,"paragraph":"Principi costituzionali - Le antinomie","question":"Il brocardo lex superior derogat inferiori indica il criterio:","correct":"gerarchico","wrong1":"cronologico","wrong2":"di specialità","wrong3":"di competenza"},{"id":47,"paragraph":"Principi costituzionali - Le antinomie","question":"Il brocardo lex specialis derogat generali indica il criterio:","correct":"di specialità","wrong1":"cronologico","wrong2":"gerarchico","wrong3":"di competenza"},{"id":48,"paragraph":"Principi costituzionali - Le antinomie","question":"Il brocardo lex posterior generalis non derogat legi priori speciali è un'applicazione del criterio:","correct":"di specialità","wrong1":"cronologico","wrong2":"gerarchico","wrong3":"di competenza"},{"id":49,"paragraph":"Principi costituzionali - Le antinomie","question":"Quando la legge o gli atti ad essa equiparati violano una riserva di competenza prevista dalla Costituzione:","correct":"sono dichiarati incostituzionali e annullati","wrong1":"sono disapplicati","wrong2":"sono pienamente legittimi","wrong3":"restano temporaneamente in vigore"},{"id":50,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Ai sensi dell'art. 70 Cost., la funzione legislativa è attribuita:","correct":"al Parlamento","wrong1":"al Governo","wrong2":"alla magistratura","wrong3":"al popolo"},{"id":51,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Ai sensi dell'art. 77 Cost., i decreti-legge perdono efficacia se non sono convertiti in legge entro:","correct":"sessanta giorni","wrong1":"dieci giorni","wrong2":"venti giorni","wrong3":"trenta giorni"},{"id":52,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Il potere legislativo delegato al Governo è:","correct":"più circoscritto di quello esercitato dal Parlamento","wrong1":"più ampio di quello esercitato dal Parlamento","wrong2":"identico a quello esercitato dal Parlamento","wrong3":"più intenso di quello esercitato dal Parlamento"},{"id":53,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Nel corso della durata della delega legislativa:","correct":"il Parlamento non perde la possibilità di esercitare la funzione legislativa, potendo in qualunque momento revocare la delega","wrong1":"il Parlamento perde la possibilità di esercitare la funzione legislativa, potendo in qualunque momento revocare la delega","wrong2":"il Governo si sostituisce al Parlamento in tutte le sue funzioni","wrong3":"il Parlamento è spogliato del potere legislativo in materia"},{"id":54,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Il potere delegato del Governo:","correct":"ha una durata prefissata","wrong1":"non ha una durata prefissata","wrong2":"è illimitato","wrong3":"ha una durata di sessanta giorni"},{"id":55,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"La delegazione legislativa è conferita:","correct":"al Governo","wrong1":"ai singoli Ministri","wrong2":"al Presidente del Consiglio","wrong3":"ai comitati interministeriali"},{"id":56,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"La legge di delegazione deve essere sempre discussa e approvata:","correct":"dall'Assemblea plenaria di ciascuna Camera","wrong1":"dalla commissione in sede deliberante","wrong2":"solo dalla Camera dei deputati","wrong3":"solo dal Senato della Repubblica"},{"id":57,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"L'eventuale inosservanza della delega da parte del Governo comporta una responsabilità:","correct":"politica","wrong1":"civile","wrong2":"penale","wrong3":"contrattuale"},{"id":58,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"L'esercizio parziale della delega da parte del Governo è stato ritenuto:","correct":"ammissibile purché il suo contenuto non sia tale da porsi in contrasto con i principi ed i fini della legge di delegazione","wrong1":"inammissibile","wrong2":"sempre ammissibile","wrong3":"inesistente"},{"id":59,"paragraph":"Principi costituzionali - Gli atti avente forza di legge","question":"Il testo del decreto adottato dal Governo deve essere trasmesso al Presidente della Repubblica per l'emanazione:","correct":"almeno venti giorni prima della scadenza del termine","wrong1":"almeno cinque giorni prima della scadenza del termine","wrong2":"almeno dieci giorni prima della scadenza del termine","wrong3":"almeno quindici giorni prima della scadenza del termine"},{"id":60,"paragraph":"Principi costituzionali - La riserva di legge","question":"Gli atti deliberati dal Parlamento secondo il procedimento disciplinato dagli artt. 70 ss. Cost. prendono il nome di:","correct":"legge ordinaria","wrong1":"decreto-legge","wrong2":"decreto legislativo","wrong3":"regolamenti"},{"id":61,"paragraph":"Principi costituzionali - La riserva di legge","question":"La legge ordinaria:","correct":"è in grado di resistere all'abrogazione e alla modificazione da parte di fonti ad essa subordinate","wrong1":"è in grado di resistere all'abrogazione e alla modificazione da parte di fonti ad essa sovraordinate","wrong2":"è immodificabile","wrong3":"è sottratta al controllo di conformità alla Costituzione da parte della Corte Costituzionale"},{"id":62,"paragraph":"Principi costituzionali - La riserva di legge","question":"Le leggi di autorizzazione rientrano nella categoria:","correct":"delle leggi meramente formali","wrong1":"dei decreti-legge","wrong2":"dei decreti legislativi","wrong3":"dei regolamenti"},{"id":63,"paragraph":"Principi costituzionali - La riserva di legge","question":"Le leggi di approvazione rientrano nella categoria:","correct":"delle leggi meramente formali","wrong1":"dei decreti-legge","wrong2":"dei decreti legislativi","wrong3":"dei regolamenti"},{"id":64,"paragraph":"Principi costituzionali - La riserva di legge","question":"Il principio nullum crimen, nulla poena sine lege esprime:","correct":"la legalità in senso sostanziale","wrong1":"la legalità in senso formale","wrong2":"una riserva di legge relativa","wrong3":"una riserva di legge costituzionale"},{"id":65,"paragraph":"Principi costituzionali - La riserva di legge","question":"Il principio di legalità è considerato uno dei pilastri dello:","correct":"Stato di diritto","wrong1":"Stato assoluto","wrong2":"Stato di polizia","wrong3":"Stato totalitario"},{"id":66,"paragraph":"Principi costituzionali - La riserva di legge","question":"Ai sensi dell'art. 111 Cost., la giurisdizione si attua mediante il giusto processo regolato:","correct":"dalla legge","wrong1":"dai giudici","wrong2":"dalla magistratura","wrong3":"dalla Costituzione"},{"id":67,"paragraph":"Principi costituzionali - La riserva di legge","question":"Quando è esclusa la possibilità di disciplinare una determinata materia con fonti di grado secondario si parla di riserva di legge:","correct":"assoluta","wrong1":"relativa","wrong2":"costituzionale","wrong3":"implicita"},{"id":68,"paragraph":"Principi costituzionali - La riserva di legge","question":"Quando l'intervento della legge è previsto solo per definire le caratteristiche fondamentali della disciplina, lasciando spazio alle fonti secondarie per definirla compiutamente si parla di riserva di legge:","correct":"relativa","wrong1":"assoluta","wrong2":"costituzionale","wrong3":"implicita"},{"id":69,"paragraph":"Principi costituzionali - La riserva di legge","question":"Quando non è espressamente prevista dalla Costituzione si parla di riserva di legge:","correct":"implicita","wrong1":"relativa","wrong2":"assoluta","wrong3":"costituzionale"},{"id":70,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"Uno Stato in cui a determinate comunità territoriali (le Regioni) vengono riconosciute sfere di autonomie variamente articolate si definisce:","correct":"Stato regionale","wrong1":"Stato nazionale","wrong2":"Stato federale","wrong3":"Stato assoluto"},{"id":71,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"Uno Stato in cui al governo centrale si contrappongono diversi governi locali, dotati al loro interno di poteri sovrani autonomi ed esclusivi si definisce:","correct":"Stato federale","wrong1":"Stato nazionale","wrong2":"Stato regionale","wrong3":"Stato assoluto"},{"id":72,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"L'art. 5 Cost. afferma il principio di:","correct":"unità","wrong1":"trasparenza","wrong2":"buon andamento","wrong3":"eguaglianza"},{"id":73,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"La Sardegna è:","correct":"una Regione a statuto speciale","wrong1":"una Regione a statuto ordinario","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":74,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"La Sicilia è:","correct":"una Regione a statuto speciale","wrong1":"una Regione a statuto ordinario","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":75,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"La Valle d'Aosta è:","correct":"una Regione a statuto speciale","wrong1":"una Regione a statuto ordinario","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":76,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"Il Trentino-Alto Adige è:","correct":"una Regione a statuto speciale","wrong1":"una Regione a statuto ordinario","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":77,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"Il Friuli Venezia Giulia è:","correct":"una Regione a statuto speciale","wrong1":"una Regione a statuto ordinario","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":78,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"L'Abruzzo è:","correct":"una Regione a statuto ordinario","wrong1":"una Regione a statuto speciale","wrong2":"una Provincia","wrong3":"una Città metropolitana"},{"id":79,"paragraph":"Principi costituzionali - Le fonti del diritto regionale","question":"La suddivisione della potestà legislativa tra Stato e Regioni è definita dall'articolo:","correct":"117 Cost.","wrong1":"5 Cost.","wrong2":"114 Cost.","wrong3":"118 Cost."},{"id":80,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti sono fonti di livello:","correct":"secondario","wrong1":"superprimario","wrong2":"primario","wrong3":"sub-secondario"},{"id":81,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I caratteri dei regolamenti sono:","correct":"generalità, innovatività, astrattezza","wrong1":"concretezza, specialità, innovatività","wrong2":"generalità, innovatività, concretezza","wrong3":"specialità, innovatività, astrattezza"},{"id":82,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"La disciplina dei regolamenti governativi è contenuta nella legge:","correct":"400/1988","wrong1":"241/1990","wrong2":"300/1970","wrong3":"190/2014"},{"id":83,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti:","correct":"non possono derogare alla legge ordinaria","wrong1":"possono derogare alla Costituzione","wrong2":"possono contenere sanzioni penali","wrong3":"possono regolare istituti fondamentali dell'ordinamento"},{"id":84,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti:","correct":"non possono derogare alla Costituzione","wrong1":"possono derogare alla Costituzione","wrong2":"possono contenere sanzioni penali","wrong3":"possono regolare istituti fondamentali dell'ordinamento"},{"id":85,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"Il parere emanato dal Consiglio di Stato è:","correct":"obbligatorio ma non vincolante","wrong1":"obbligatorio e vincolante","wrong2":"facoltativo e vincolante","wrong3":"facoltativo ma non vincolante"},{"id":86,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti sono sottoposti al visto e alla registrazione:","correct":"della Corte dei conti","wrong1":"del Consiglio di Stato","wrong2":"del Guardasigilli","wrong3":"della Cassazione"},{"id":87,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti emanati nelle materie in cui manchi la disciplina da parte di leggi o di atti aventi forza di legge prendono il nome di:","correct":"regolamenti indipendenti","wrong1":"regolamenti di esecuzione","wrong2":"regolamenti di attuazione","wrong3":"regolamenti di riordino"},{"id":88,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"I regolamenti per la disciplina delle materie non coperte da riserva assoluta di legge, per le quali la legge determina le norme generali regolatrici della materia prendono il nome di:","correct":"regolamenti delegati","wrong1":"regolamenti di esecuzione","wrong2":"regolamenti di attuazione","wrong3":"regolamenti di riordino"},{"id":89,"paragraph":"Principi costituzionali - I regolamenti: una categoria eterogenea","question":"Il fenomeno per il quale i regolamenti sono autorizzati in via legislativa a derogare alle leggi previgenti o anche a sostituirsi ad esse, nelle materie non coperte da riserva di legge prende il nome di:","correct":"delegificazione","wrong1":"semplificazione","wrong2":"delegazione legislativa","wrong3":"decretazione d'urgenza"},{"id":90,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Le limitazioni di sovranità sono previste dall'art.:","correct":"11 Cost.","wrong1":"1 Cost.","wrong2":"2 Cost.","wrong3":"117 Cost."},{"id":91,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Il Trattato di Maastricht è stato sottoscritto nel:","correct":"1992","wrong1":"1950","wrong2":"1987","wrong3":"2001"},{"id":92,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"I trattati istitutivi costituiscono:","correct":"il diritto originario","wrong1":"il diritto derivato","wrong2":"il diritto internazionale","wrong3":"il diritto penale"},{"id":93,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"I regolamenti rientrano nel:","correct":"diritto derivato","wrong1":"diritto originario","wrong2":"diritto internazionale","wrong3":"diritto penale"},{"id":94,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Le direttive rientrano nel:","correct":"diritto derivato","wrong1":"diritto originario","wrong2":"diritto internazionale","wrong3":"diritto penale"},{"id":95,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Le decisioni hanno portata:","correct":"concreta","wrong1":"generale","wrong2":"astratta","wrong3":"assoluta"},{"id":96,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Le raccomandazioni rientrano:","correct":"negli atti non legislativi","wrong1":"negli atti legislativi","wrong2":"nei fatti giuridici","wrong3":"nei fatti illeciti"},{"id":97,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"I pareri rientrano:","correct":"negli atti non legislativi","wrong1":"negli atti legislativi","wrong2":"nei fatti giuridici","wrong3":"nei fatti illeciti"},{"id":98,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"Le raccomandazioni sono prive di:","correct":"efficacia vincolante","wrong1":"forma scritta","wrong2":"valore legale","wrong3":"destinatari"},{"id":99,"paragraph":"Principi costituzionali - Le istituzioni comunitarie e le loro fonti","question":"I pareri sono privi di:","correct":"efficacia vincolante","wrong1":"forma scritta","wrong2":"valore legale","wrong3":"destinatari"},{"id":100,"paragraph":"Principi costituzionali - Il Governo","question":"Il Governo è il titolare del potere:","correct":"esecutivo","wrong1":"legislativo","wrong2":"giudiziario","wrong3":"giurisdizionale"},{"id":101,"paragraph":"Principi costituzionali - Il Governo","question":"L'adozione di decreti-legge e decreti legislativi rientra nell'attività:","correct":"legislativa eccezionale","wrong1":"regolamentare","wrong2":"amministrativa","wrong3":"politico-costituzionale"},{"id":102,"paragraph":"Principi costituzionali - Il Governo","question":"La forma tipica degli atti posti in essere dal Governo è:","correct":"il decreto","wrong1":"la legge","wrong2":"l'ordinanza","wrong3":"la sentenza"},{"id":103,"paragraph":"Principi costituzionali - Il Governo","question":"La scelta programmatica dei modi e degli strumenti attraverso cui si dovrà svolgere concretamente l'attività di governo prende il nome di funzione:","correct":"di indirizzo politico","wrong1":"normativa","wrong2":"regolamentare","wrong3":"legislativa eccezionale"},{"id":104,"paragraph":"Principi costituzionali - Il Governo","question":"Gli atti di indirizzo politico del Governo sono:","correct":"insindacabili","wrong1":"sindacabili","wrong2":"impugnabili","wrong3":"ricorribili"},{"id":105,"paragraph":"Principi costituzionali - Il Governo","question":"A seguito dell'adesione del nostro Paese alle comunità europee si parla di Stato:","correct":"regolatore","wrong1":"imprenditore","wrong2":"assoluto","wrong3":"totalitario"},{"id":106,"paragraph":"Principi costituzionali - Il Governo","question":"La cura e la rappresentanza degli interessi dello Stato in ambito internazionale spettano:","correct":"al Governo","wrong1":"al Parlamento","wrong2":"alla Camera dei deputati","wrong3":"al Senato della Repubblica"},{"id":107,"paragraph":"Principi costituzionali - Il Governo","question":"I trattati internazionali che sono di natura politica, o prevedono arbitrati o regolamenti giudiziari, o importano variazioni del territorio od oneri alle finanze o modificazioni di leggi sono autorizzati con:","correct":"legge","wrong1":"regolamento","wrong2":"decreto","wrong3":"decreto ministeriale"},{"id":108,"paragraph":"Principi costituzionali - Il Governo","question":"I decreti-legge perdono efficacia sin dall'inizio, se non sono convertiti in legge entro:","correct":"sessanta giorni","wrong1":"dieci giorni","wrong2":"venti giorni","wrong3":"trenta giorni"},{"id":109,"paragraph":"Principi costituzionali - Il Governo","question":"Gli atti di alta amministrazione sono:","correct":"sindacabili, in quanto atti amministrativi","wrong1":"insidacabili","wrong2":"inoppugnabili","wrong3":"irrevocabili"},{"id":110,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Le esternazioni atipiche:","correct":"hanno forma orale e dunque non sono soggette a controfirma","wrong1":"sono soggette a controfirma","wrong2":"possono essere soggette a controfirma","wrong3":"hanno forma scritta ma non sono soggette a controfirma"},{"id":111,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Le esternazioni atipiche:","correct":"provvisorio","wrong1":"definitivo","wrong2":"inderogabile","wrong3":"assoluto"},{"id":112,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Il CSM è presieduto:","correct":"dal Presidente della Repubblica","wrong1":"dal Primo Presidente della Corte di Cassazione","wrong2":"dal Presidente del Consiglio di Stato","wrong3":"dal Presidente del Consiglio dei Ministri"},{"id":113,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Il Presidente della Repubblica può nominare:","correct":"cinque senatori a vita","wrong1":"tre senatori a vita","wrong2":"due senatori a vita","wrong3":"quattro senatori a vita"},{"id":114,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Il Presidente della Repubblica nomina:","correct":"cinque giudici della Corte Costituzionale","wrong1":"sette giudici della Corte Costituzionale","wrong2":"nove giudici della Corte Costituzionale","wrong3":"quattro giudici della Corte Costituzionale"},{"id":115,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Negli atti formalmente presidenziali, ma sostanzialmente governativi:","correct":"la volontà dominante è quella dell'esecutivo","wrong1":"la volontà dominante è quella del Presidente della Repubblica","wrong2":"deve esservi il necessario assenso con parità di poteri del Presidente della Repubblica e del Ministro","wrong3":"può anche non esservi la controfirma"},{"id":116,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Negli atti formalmente e sostanzialmente presidenziali:","correct":"la volontà dominante è quella del Presidente della Repubblica","wrong1":"la volontà dominante è quella dell'esecutivo","wrong2":"deve esservi il necessario assenso con parità di poteri del Presidente della Repubblica e del Ministro","wrong3":"può anche non esservi la controfirma"},{"id":117,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Negli atti sostanzialmente complessi:","correct":"deve esservi il necessario assenso con parità di poteri del Presidente della Repubblica e del Ministro","wrong1":"la volontà dominante è quella dell'esecutivo","wrong2":"la volontà dominante è quella del Presidente della Repubblica","wrong3":"può anche non esservi la controfirma"},{"id":118,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Gli atti che hanno valore legislativo e gli altri indicati dalla legge:","correct":"sono controfirmati anche dal Presidente del Consiglio dei ministri","wrong1":"non richiedono la controfirma","wrong2":"sono controfirmati esclusivamente dal Ministro proponente","wrong3":"sono validi anche in assenza di controfirma"},{"id":119,"paragraph":"Principi costituzionali - Poteri e responsabilità del Presidente della Repubblica","question":"Il Presidente della Repubblica:","correct":"non è responsabile degli atti compiuti nell'esercizio delle sue funzioni, tranne che per alto tradimento o per attentato alla Costituzione","wrong1":"è sempre responsabile degli atti compiuti nell'esercizio delle sue funzioni","wrong2":"è responsabile solo dal punto di vista penale degli atti compiuti nell'esercizio delle sue funzioni","wrong3":"non è mai responsabile degli atti compiuti nell'esercizio delle sue funzioni"},{"id":120,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Può essere eletto Presidente della Repubblica ogni cittadino che abbia compiuto:","correct":"cinquanta anni d'età","wrong1":"quaranta anni d'età","wrong2":"sessanta anni d'età","wrong3":"sessantacinque anni d'età"},{"id":121,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Il Presidente della Repubblica è eletto:","correct":"dal Parlamento in seduta comune dei suoi membri","wrong1":"dalla Camera dei deputati","wrong2":"dal Senato della Repubblica","wrong3":"dal corpo elettorale"},{"id":122,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Dopo il terzo scrutinio:","correct":"è sufficiente la maggioranza assoluta","wrong1":"occorre la maggioranza di due terzi dell'assemblea","wrong2":"occorre la maggioranza di tre quinti dell'assemblea","wrong3":"occorre la maggioranza di tre quarti dell'assemblea"},{"id":123,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"In caso di impedimento, le funzioni del Presidente della Repubblica sono esercitate:","correct":"dal Presidente del Senato","wrong1":"dal Presidente del Consiglio","wrong2":"dal Presidente della Camera","wrong3":"dal Vice Presidente della Repubblica"},{"id":124,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Il Presidente della Repubblica dura in carica:","correct":"sette anni","wrong1":"cinque anni","wrong2":"quattro anni","wrong3":"nove anni"},{"id":125,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Le dimissioni del Presidente della Repubblica sono:","correct":"irrevocabili","wrong1":"revocabili","wrong2":"ritirabili","wrong3":"annullabili"},{"id":126,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Le dimissioni del Presidente della Repubblica:","correct":"non richiedono la controfirma ministeriale né la motivazione","wrong1":"non richiedono la controfirma ministeriale ma richiedono la motivazione","wrong2":"richiedono la controfirma ministeriale ma non la motivazione","wrong3":"richiedono la controfirma ministeriale e la motivazione"},{"id":127,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Gli ex Presidenti della Repubblica divengono:","correct":"senatori a vita","wrong1":"giudici costituzionali","wrong2":"consiglieri di Stato","wrong3":"ministri senza portafoglio"},{"id":128,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"La possibilità della rielezione del Presidente della Repubblica:","correct":"è deducibile dal silenzio della Costituzione","wrong1":"è espressamente esclusa dalla Costituzione","wrong2":"è vietata dalla Costituzione","wrong3":"è espressamente prevista dalla Costituzione"},{"id":129,"paragraph":"Principi costituzionali - Il Presidente della Repubblica nel nostro sistema costituzionale","question":"Il Parlamento in seduta comune è diretto:","correct":"dal Presidente della Camera","wrong1":"dal Presidente del Consiglio","wrong2":"dal Presidente della Repubblica uscente","wrong3":"dal Presidente del Senato"},{"id":130,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Lo Statuto Albertino rifletteva una visione del giudice quale:","correct":"mero funzionario, chiamato ad applicare una volontà altrui, quella del legislatore","wrong1":"creatore del diritto","wrong2":"libero interprete del diritto","wrong3":"giudice-legislatore"},{"id":131,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Ai sensi dell'art. 101 Cost., la giustizia è amministrata in nome:","correct":"del popolo","wrong1":"della legge","wrong2":"della legge","wrong3":"del Parlamento"},{"id":132,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"I giudici sono soggetti soltanto:","correct":"alla legge","wrong1":"al popolo","wrong2":"al Governo","wrong3":"al Governo"},{"id":133,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"I magistrati si distinguono fra loro:","correct":"soltanto per diversità di funzioni","wrong1":"per gerarchia","wrong2":"per grado di giudizio","wrong3":"per sede"},{"id":134,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Le nomine dei magistrati hanno luogo:","correct":"per concorso","wrong1":"per designazione","wrong2":"per cooptazione","wrong3":"per elezione"},{"id":135,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Fanno eccezione alla regola del concorso:","correct":"i giudici onorari","wrong1":"i giudici straordinari","wrong2":"i giudici amministrativi","wrong3":"i giudici militari"},{"id":136,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Non possono essere istituiti:","correct":"giudici straordinari o giudici speciali","wrong1":"giudici militari o giudici straordinari","wrong2":"giudici speciali o giudici contabili","wrong3":"giudici straordinari o giudici tributari"},{"id":137,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Alla luce del disposto dell'art. 102 Cost., nel nostro ordinamento:","correct":"sono fatte salve alcune giurisdizioni speciali preesistenti alla Costituzione","wrong1":"non esistono giudici speciali","wrong2":"possono essere istituiti nuovi giudici speciali","wrong3":"sono ammesse solo le cc.dd. sezioni specializzate"},{"id":138,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"Il Consiglio di Stato rientra tra:","correct":"le giurisdizioni speciali","wrong1":"le giurisdizioni ordinarie","wrong2":"le giurisdizioni straordinarie","wrong3":"le sezioni specializzate"},{"id":139,"paragraph":"Principi costituzionali - La funzione giurisdizionale","question":"L'istituzione di giudici straordinari violerebbe:","correct":"il principio della precostituzione del giudice naturale","wrong1":"il principio dell'inamovibilità dei magistrati","wrong2":"il principio della ragionevole durata del processo","wrong3":"il principio della corrispondenza tra chiesto e pronunciato"},{"id":140,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"Il sistema italiano di giustizia costituzionale è un sistema:","correct":"accentrato","wrong1":"diffuso","wrong2":"ristretto","wrong3":"aperto"},{"id":141,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"La Corte costituzionale agisce:","correct":"in via successiva","wrong1":"in via preventiva","wrong2":"in via diretta","wrong3":"su sollecitazione del Presidente del Consiglio"},{"id":142,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"I 15 giudici della Corte costituzionale:","correct":"derivano da una designazione mista","wrong1":"sono eletti dal popolo","wrong2":"sono eletti dal CSM","wrong3":"sono eletti dal Parlamento in seduta comune"},{"id":143,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"Tra le garanzie della funzione di giudice costituzionale figura:","correct":"l’incompatibilità","wrong1":"l'ineleggibilità","wrong2":"la non punibilità per i reati comuni","wrong3":"la riservatezza"},{"id":144,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"La Corte è comunque legittimata ad operare:","correct":"in presenza di 11 giudici","wrong1":"in presenza di 5 giudici","wrong2":"in presenza di 10 giudici","wrong3":"qualora manchi il solo presidente"},{"id":145,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"L'accesso alla Corte costituzionale avviene:","correct":"in via incidentale e in via diretta","wrong1":"in via diretta","wrong2":"in via incidentale","wrong3":"su proposta del Presidente del Consiglio"},{"id":146,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"Il procedimento in via incidentale sorge:","correct":"per iniziativa di un giudice","wrong1":"per iniziativa del Pubblico ministero","wrong2":"per iniziativa delle parti","wrong3":"per iniziativa del Presidente della Camera"},{"id":147,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"Il giudizio in via diretta coinvolge:","correct":"lo Stato e le Regioni","wrong1":"solo lo Stato","wrong2":"solo le Regioni","wrong3":"il CSM"},{"id":148,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"La Corte costituzionale è da considerarsi organo:","correct":"impolitico","wrong1":"politico","wrong2":"rappresentativo","wrong3":"plebiscitario"},{"id":149,"paragraph":"Principi costituzionali - La Corte Costituzionale: ruolo e funzioni del giudice delle leggi","question":"Il fatto che la verifica compiuta dalla Corte costituzionale avvenga sempre su leggi (o atti equiparati) già in vigore fa sì che il sindacato di legittimità sia:","correct":"successivo","wrong1":"accentrato","wrong2":"principale","wrong3":"incidentale"},{"id":150,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Le disposizioni concernenti la Corte Costituzionale sono contenute negli artt.:","correct":"134-137 Cost.","wrong1":"01-12 Cost.","wrong2":"41-43 Cost.","wrong3":"138-139 Cost."},{"id":151,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"La ratio del nostro sistema di giustizia costituzionale è da ravvisare principalmente:","correct":"nella tutela delle minoranze","wrong1":"nella concorrenza","wrong2":"nella trasparenza","wrong3":"nella superiorità della Costituzione"},{"id":152,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Il sindacato di legittimità costituzionale rimesso alle assemblee parlamentari ha natura:","correct":"politica","wrong1":"giurisdizionale","wrong2":"giudiziaria","wrong3":"amministrativa"},{"id":153,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Il sindacato di legittimità costituzionale rimesso alle assemblee parlamentari ha natura:","correct":"autonomo","wrong1":"eteronomo","wrong2":"eterodiretto","wrong3":"eterogeneo"},{"id":154,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Nei sistemi di sindacato accentrato il controllo di legittimità costituzionale è attribuito:","correct":"ad un organo ad hoc","wrong1":"ai giudici comuni","wrong2":"ai giudici ordinari","wrong3":"alle Regioni"},{"id":155,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Nei sistemi di sindacato diffuso il controllo di legittimità costituzionale è attribuito:","correct":"ai giudici comuni","wrong1":"ad un organo ad hoc","wrong2":"alla Corte Costituzionale","wrong3":"ad un tribunale costituzionale"},{"id":156,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Il sistema di sindacato di legittimità costituzionale vigente in Italia è di tipo:","correct":"accentrato","wrong1":"diffuso","wrong2":"politico","wrong3":"preventivo"},{"id":157,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"La prima udienza pubblica della Corte Costituzionale si è tenuta nel:","correct":"1956","wrong1":"1948","wrong2":"1950","wrong3":"1953"},{"id":158,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"La proposta formulata da Nitti era quella di riservare il sindacato sulla legittimità costituzionale delle leggi:","correct":"alla Corte di Cassazione","wrong1":"al Consiglio di Stato","wrong2":"ad un tribunale costituzionale","wrong3":"alla Corte dei conti"},{"id":159,"paragraph":"Principi costituzionali - Il sindacato di legittimità costituzionale","question":"Le dichiarazioni di illegittimità costituzionale sono efficaci:","correct":"erga omnes","wrong1":"limitatamente alle parti del giudizio","wrong2":"incidenter tantum","wrong3":"inter partes"},{"id":160,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Nel quadro del Titolo V, la tutela dell'ambiente rientra:","correct":"nella competenza esclusiva dello Stato","wrong1":"nella competenza esclusiva delle Regioni","wrong2":"nelle materie di competenza concorrente tra Stato e Regioni","wrong3":"nelle materie non espressamente riservate alla legislazione dello Stato"},{"id":161,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Nel quadro del Titolo V, la valorizzazione dei beni culturali e ambientali rientra:","correct":"nelle materie di competenza concorrente tra Stato e Regioni","wrong1":"nella competenza esclusiva dello Stato","wrong2":"nella competenza esclusiva delle Regioni","wrong3":"nelle materie non espressamente riservate alla legislazione dello Stato"},{"id":162,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Lo Stato presuppone una pluralità di soggetti organizzati che prende il nome di:","correct":"popolo","wrong1":"sudditi","wrong2":"nazione","wrong3":"corpo elettorale"},{"id":163,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"L'art. 9 Cost. parla di:","correct":"nazione","wrong1":"popolo","wrong2":"corpo elettorale","wrong3":"cittadini"},{"id":164,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Secondo Crisafulli, per nazione si intende:","correct":"la sintesi delle generazioni passate, presenti e future","wrong1":"la generazione attuale","wrong2":"le generazioni future","wrong3":"le generazioni passate"},{"id":165,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Il concetto di corpo elettorale esprime:","correct":"una parte del popolo","wrong1":"un insieme maggiore di quello relativo al popolo","wrong2":"un concetto identico a quello di popolo","wrong3":"un concetto uguale a quello di nazione"},{"id":166,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Il concetto di popolo esprime:","correct":"un insieme maggiore di quello relativo al corpo elettorale","wrong1":"una parte del corpo elettorale","wrong2":"un concetto identico a quello di corpo elettorale","wrong3":"un concetto uguale a quello di nazione"},{"id":167,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Le cd. norme precettive sono:","correct":"ad applicazione immediata","wrong1":"ad applicazione differita","wrong2":"norme penali","wrong3":"non vincolanti"},{"id":168,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Le cd. norme programmatiche sono:","correct":"ad applicazione differita","wrong1":"ad applicazione immediata","wrong2":"norme penali","wrong3":"non giuridiche"},{"id":169,"paragraph":"Principi costituzionali - La tutela dell'ambiente nella Costituzione","question":"Quando si parla di norme ad applicazione immediata si fa riferimento a:","correct":"norme precettive","wrong1":"norme programmatiche","wrong2":"norme penali","wrong3":"norme non giuridiche"},{"id":170,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"Secondo un'interpretazione sistematica dell'art. 9 Cost., per nazione si intende:","correct":"la sintesi delle generazioni passate, presenti e future","wrong1":"la generazione attuale","wrong2":"le generazioni future","wrong3":"le generazioni passate"},{"id":171,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"La promozione della ricerca scientifica e tecnica è prevista:","correct":"dall'art. 9 Cost.","wrong1":"dall'art. 33 Cost.","wrong2":"dall'art. 32 Cost.","wrong3":"dall'art. 34 Cost."},{"id":172,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"Ai sensi dell'art. 34 Cost., l'istruzione inferiore è impartita per almeno:","correct":"otto anni","wrong1":"dieci anni","wrong2":"cinque anni","wrong3":"nove anni"},{"id":173,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"L'istituzione delle scuole private è resa possibile dal principio:","correct":"pluralista","wrong1":"di concorrenza","wrong2":"di solidarietà","wrong3":"di leale cooperazione"},{"id":174,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"Il diritto allo studio rientra nei:","correct":"rapporti etico-sociali","wrong1":"rapporti civili","wrong2":"rapporti economici","wrong3":"rapporti politici"},{"id":175,"paragraph":"Principi costituzionali - La tutela dei beni culturali e l'istruzione","question":"Le scuole che assicurano prestazioni didattiche equivalenti alle scuole statali sono dette:","correct":"paritarie","wrong1":"dell'obbligo","wrong2":"pubbliche","wrong3":"private"},{"id":176,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"Gli articoli della Costituzione dedicati ai rapporti economici sono:","correct":"gli artt. 35-47","wrong1":"gli artt. 92-100","wrong2":"gli artt. 48-54","wrong3":"gli artt. 83-91"},{"id":177,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"La libertà di iniziativa economica è disciplinata dall'articolo:","correct":"41 Cost.","wrong1":"43 Cost.","wrong2":"92 Cost.","wrong3":"83 Cost."},{"id":178,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"L'iniziativa economica privata non può svolgersi in contrasto con:","correct":"l’utilità sociale","wrong1":"i pubblici poteri","wrong2":"l'ordine pubblico","wrong3":"l'indirizzo del Governo"},{"id":179,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"Dal tenore letterale del terzo comma dell'art. 41 Cost. si evince una visione dello Stato:","correct":"imprenditore","wrong1":"regolatore","wrong2":"assoluto","wrong3":"regionale"},{"id":180,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"La visione dello Stato ricavabile dalla nuova Costituzione economica è quella di uno Stato:","correct":"regolatore","wrong1":"imprenditore","wrong2":"autarchico","wrong3":"assoluto"},{"id":181,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"L'Autorità Garante della Concorrenza e del Mercato è stata istituita nel:","correct":"1990","wrong1":"1948","wrong2":"1970","wrong3":"2001"},{"id":182,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"Le Autorità amministrative indipendenti sono indipendenti soprattutto:","correct":"dal Governo e dal suo indirizzo politico","wrong1":"dalla magistratura","wrong2":"dagli enti locali","wrong3":"dagli organi ausiliari"},{"id":183,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"L'AGCM è:","correct":"un'autorità amministrativa indipendente","wrong1":"un Ministero senza portafoglio","wrong2":"un ente pubblico economico","wrong3":"una società a partecipazione pubblica"},{"id":184,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"L'AGCOM è:","correct":"un'autorità amministrativa indipendente","wrong1":"un Ministero senza portafoglio","wrong2":"un ente pubblico economico","wrong3":"una società a partecipazione pubblica"},{"id":185,"paragraph":"Principi costituzionali - La libertà di iniziativa economica privata","question":"L'AEEG è:","correct":"un'autorità amministrativa indipendente","wrong1":"un Ministero senza portafoglio","wrong2":"un ente pubblico economico","wrong3":"una società a partecipazione pubblica"},{"id":186,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"La corte costituzionale adotta una decisione di inammissibilità:","correct":"quanto non entra nel merito della questione di legittimità costituzionale","wrong1":"quando entra nel merito della questione di legittimità costituzionale","wrong2":"quando decide collegialmente","wrong3":"quando si rifiuta di decidere"},{"id":187,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"La Corte adotta una sentenza di rigetto quando:","correct":"dichiara non fondata la questione di legittimità costituzionale","wrong1":"dichiara fondata la questione di legittimità costituzionale","wrong2":"dichiara la questione inammissibile","wrong3":"restituisce gli atti al giudice a quo"},{"id":188,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"La decisione di rigetto:","correct":"ha effetti inter partes","wrong1":"ha effetti erga omnes","wrong2":"consente al giudice di riproporre la questione nello stesso stato e grado del giudizio","wrong3":"produce effetti limitati nel tempo"},{"id":189,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Con le sentenze di accoglimento la Corte costituzionale dichiara:","correct":"fondata la questione di legittimità costituzionale","wrong1":"non fondata la questione di legittimità costituzionale","wrong2":"inammissibile la questione","wrong3":"parzialmente fondata la questione"},{"id":190,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Una sentenza di accoglimento produce:","correct":"effetti retroattivi","wrong1":"effetti pro futuro","wrong2":"effetti limitati nel tempo","wrong3":"effetti abrogativi"},{"id":191,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"La sentenza di accoglimento:","correct":"ha effetti erga omnes","wrong1":"ha effetti inter partes","wrong2":"ha effetti indiretti","wrong3":"ha effetti solo nei confronti del giudice a quo"},{"id":192,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Una sentenza additiva è una particolare decisione:","correct":"di accoglimento","wrong1":"di rigetto","wrong2":"di inammissibilità","wrong3":"retroattiva"},{"id":193,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Con una sentenza sostitutiva la corte dichiara:","correct":"l'illegittimità di una disposizione di legge o di atto avente forza di legge nella parte in cui prevede qualcosa anziché un'altra","wrong1":"l'illegittimità di una disposizione di legge o di atto avente forza di legge nella parte in cui prevede qualcosa","wrong2":"l'illegittimità di una disposizione di legge o di atto avente forza di legge","wrong3":"la legittimità di una disposizione di legge o di atto avente forza di legge"},{"id":194,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Oggetto di una sentenza interpretativa è:","correct":"l'interpretazione della disposizione operata dal giudice a quo","wrong1":"la disposizione sollevata dal giudice può","wrong2":"un atto avente forza di legge","wrong3":"un atto del governo"},{"id":195,"paragraph":"Principi costituzionali - La tipologia delle decisioni della Corte Costituzionale","question":"Il diritto vivente è:","correct":"è il diritto che risulta dall'interpretazione giurisprudenziale consolidata di determinate disposizioni di legge da parte dei giudici comuni","wrong1":"il diritto applicato dalla Corte costituzionale","wrong2":"il diritto applicato alla pubblica amministrazione","wrong3":"il diritto applicato dai cittadini"},{"id":196,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Il Governo di sollevare la questione di legittimità costituzionale di una legge regionale anche su proposta:","correct":"della Conferenza Stato-città","wrong1":"del CNEL","wrong2":"del Consiglio di Stato","wrong3":"del CIPE"},{"id":197,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Il procedimento di legittimità costituzionale in via principale è un giudizio:","correct":"successivo","wrong1":"preventivo","wrong2":"preliminare","wrong3":"anticipato"},{"id":198,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Nel procedimento di legittimità costituzionale in via principale la questione:","correct":"la questione può essere sollevata facoltativamente dalle parti","wrong1":"è sempre sollevata dalle parti","wrong2":"è obbligatoriamente sollevata dalle parti","wrong3":"è sollevata ex officio dalle parti"},{"id":199,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Nel procedimento di legittimità costituzionale in via principale il termine per la notifica del ricorso è di:","correct":"60 giorni","wrong1":"10 giorni","wrong2":"20 giorni","wrong3":"30 giorni"},{"id":200,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"I conflitti di attribuzione sono previsti a tutela:","correct":"della divisione dei poteri e del pluralismo democratico","wrong1":"della funzione giurisdizionale","wrong2":"del potere esecutivo","wrong3":"della funzione legislativa"},{"id":201,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Allorché un soggetto rivendichi un'attribuzione che ritenga usurpata da altro soggetto si parla di:","correct":"vindicatio potestatis","wrong1":"rei vindicatio","wrong2":"ius in re aliena","wrong3":"actio finium regundorum"},{"id":202,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Nel caso di errore in iudicando i conflitti di attribuzione:","correct":"non sono ammissibili","wrong1":"sono previsti in alternativa ai rimedi giurisdizionali consueti","wrong2":"sono previsti in via subordinata ai rimedi giurisdizionali consueti","wrong3":"sono previsti insieme ai rimedi giurisdizionali consueti"},{"id":203,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Non rientra nella nozione di potere dello Stato:","correct":"il CNEL","wrong1":"il Presidente della Repubblica","wrong2":"il Parlamento","wrong3":"il Governo"},{"id":204,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Non rientra nella nozione di potere dello Stato:","correct":"l’AGCM","wrong1":"il Presidente della Repubblica","wrong2":"il Parlamento","wrong3":"il Governo"},{"id":205,"paragraph":"Principi costituzionali - Le attribuzioni della Corte Costituzionale","question":"Non rientra nella nozione di potere dello Stato:","correct":"l’AGCOM","wrong1":"il Presidente della Repubblica","wrong2":"il Parlamento","wrong3":"il Governo"},{"id":206,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"L'amministrazione dispone di poteri che derivano:","correct":"dalla legge","wrong1":"dalla volontà politica del partito del Sindaco o del Ministro o comunque dal rappresentante legale p.t.","wrong2":"dalla prassi","wrong3":"dalla volontà dei cittadini più saggi"},{"id":207,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"I poteri che l'amministrazione esercita entrano in azione nel momento in cui:","correct":"la norma autorizza ed impone il loro esercizio","wrong1":"secondo la prassi è giusto esercitare quel potere","wrong2":"i cittadini si recano alle urne","wrong3":"c'è l'esito del referendum confermativo"},{"id":208,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"Se il sindaco accerta la realizzazione di opere senza permesso di costruire:","correct":"ordina la demolizione dell'opera","wrong1":"fa finta di nulla","wrong2":"contatta la proprietà dell'opera e propone una sanatoria a spese dei cittadini","wrong3":"contatta la proprietà dell'opera e propone una sanatoria a spese della proprietà"},{"id":209,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"L'interesse tutelato dal potere amministrativo è:","correct":"pubblico","wrong1":"privato ma di una cerchia ristretta di cittadini","wrong2":"privato ma relativo alle aziende","wrong3":"privato"},{"id":210,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"La persona soggetta al potere amministrativo può ottenere l'invalidazione dell'atto quando:","correct":"non soddisfa l'interesse pubblico che la legge riconosce all'autorità che lo adotta","wrong1":"vi è un capriccio politico","wrong2":"non viene soddisfatto l'interesse privato contrapposto","wrong3":"non è soddisfatto l'interesse pubblico che la legge riconosce all'autorità che non lo ha adottato"},{"id":211,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"Il Prefetto non può:","correct":"sostituirsi al Governo o al Parlamento né violare i principi costituzionali","wrong1":"sostituirsi al Parlamento ma può sostituirsi al Governo","wrong2":"sostituirsi al Parlamento ma può violare i principi costituzionali se previsti all'atto di nomina","wrong3":"sostituirsi al Governo ma può sostituirsi al Parlamento"},{"id":212,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"Il Sindaco può adottare:","correct":"provvedimenti contingibili ed urgenti, motivati, nel rispetto dell'ordinamento giuridico","wrong1":"provvedimenti contingibili ed urgenti nel rispetto dell'ordinamento giuridico, anche privi di motivazione","wrong2":"solo provvedimenti urgenti anche contra legem","wrong3":"solo provvedimenti urgenti"},{"id":213,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"La predeterminazione legislativa del contenuto degli atti:","correct":"esclude che l'amministrazione possa aggiungere un contenuto agli atti diverso da quello previsto dallo schema legislativo","wrong1":"ammette la possibilità che l'amministrazione possa aggiungere un contenuto agli atti diverso da quello previsto dallo schema legislativo","wrong2":"riserva all'amministrazione un potere discrezionale enorma, anche che possa aggiungere qualunque contenuto agli atti diverso da quello previsto dallo schema legislativo","wrong3":"dà la possibilità all'amministrazione di seguire uno schema legislativo proprio"},{"id":214,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"L'art. 2 della legge n. 241/90 stabilisce che:","correct":"se il procedimento debba essere iniziato d'ufficio, la pubblica amministrazione ha il dovere di concluderlo mediante un provvedimento espresso","wrong1":"se il procedimento debba essere iniziato d'ufficio, la pubblica amministrazione può concluderlo anche senza provvedimento espresso, in quanto rientra tra le proprie facoltà","wrong2":"se il procedimento debba essere iniziato d'ufficio, la pubblica amministrazione può concluderlo anche senza provvedimento espresso, pagando poi un'ammenda","wrong3":"se il procedimento debba essere iniziato d'ufficio, la pubblica amministrazione deve concluderlo con provvedimento privo di motivazione"},{"id":215,"paragraph":"Diritto amministrativo - Il potere amministrativo","question":"Il ricorso al contratto da parte dell'amministrazione è:","correct":"possibile solo nei casi previsti dalla legge","wrong1":"possibile ma solo per prendere tempo","wrong2":"impossibile","wrong3":"impossibile direttamente ma possibile mediante ricorso dell'amministrazione immediatamente superiore gerarchicamente"},{"id":216,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il diritto amministrativo si occupa:","correct":"di garantire il benessere della collettività organizzata, col minor sacrificio possibile per gli interessi individuali","wrong1":"di assicurare la certezza delle relazioni interprivate","wrong2":"di evitare che i cittadini si facciano giustizia da sé","wrong3":"di tutelare l'amministrazione dalla pretese dei cittadini"},{"id":217,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il potere amministrativo tutela:","correct":"l’interesse pubblico","wrong1":"l'interesse privato","wrong2":"l'interesse corporativo","wrong3":"l'interesse economico della pubblica amministrazione"},{"id":218,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il potere amministrativo può vincere le resistenze dei privati:","correct":"sì, purché sia esercitato nel rispetto della legge e per la finalità per cui è stato attribuito","wrong1":"sempre","wrong2":"mai","wrong3":"solo quando è esercitato dall'amministrazione statale"},{"id":219,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il processo di giuridicizzazione del potere è:","correct":"il processo di progressivo assoggettamento del potere amministrativo ad un sistema di regole, che ha in un giudice il suo controllore","wrong1":"il percorso di progressiva affermazione della supremazia del potere amministrativo rispetto alla legge","wrong2":"il compimento del disegno costituzionale della appartenenza al popolo della sovranità","wrong3":"l'affermazione della superiorità dell'individuo rispetto alla collettività"},{"id":220,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"I caratteri del potere giuridicizzato sono:","correct":"legalità, articolazione, funzionalizzazione, doverosità e sindacabilità","wrong1":"legalità, giustiziabilità e discrezionalità","wrong2":"insindacabilità, imperatività e garanzia","wrong3":"legalità, doverosità, discrezionalità e trasparenza"},{"id":221,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Per tripolarità del diritto amministrativo si intende:","correct":"la caratteristica del diritto amministrativo per cui ogni fattispecie di esercizio del potere coinvolge almeno tre elementi","wrong1":"la riconducibilità del diritto amministrativo a tre differenti branche del diritto","wrong2":"la impossibilità di ricondurre il diritto amministrativo al binomio: diritto pubblico-diritto privato","wrong3":"nessuna delle precedenti"},{"id":222,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"La discrezionalità amministrativa è:","correct":"la possibilità per l'amministrazione di assumere decisioni che implichino gradi differenziati di tutela e di sacrificio dell'interesse pubblico e degli interessi privati coinvolti in una determinata vicenda amministrativa","wrong1":"la libertà dell'amministrazione di esercitare il potere, libera da condizionamenti esterni","wrong2":"la possibilità che ha l'amministrazione di scegliere le finalità da perseguire nello svolgimento della propria attività","wrong3":"la capacità dell'amministrazione di agire secondo il diritto privato"},{"id":223,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il procedimento amministrativo consiste:","correct":"nella sede in cui l'amministrazione acquisisce gli elementi di fatto e di diritto rilevanti per la fattispecie, tra i quali vi è il punto di vista dei destinatari della decisione","wrong1":"in un insieme di norme e principi che rendono più spedita l'azione amministrativa","wrong2":"nella sede in cui l'amministrazione acquisisce gli elementi di fatto e di diritto rilevanti per la propria decisione, senza però interloquire con i soggetti privati","wrong3":"nell'insieme delle regole che definiscono la priorità strategica dell'amministrazione"},{"id":224,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Il diritto amministrativo è:","correct":"una branca del diritto pubblico","wrong1":"una branca del diritto civile","wrong2":"una branca del diritto costituzionale","wrong3":"un ibrido fra diritto civile e diritto pubblico"},{"id":225,"paragraph":"Diritto amministrativo - Profili generali del diritto amministrativo","question":"Per provvedimento ampliativo si intende:","correct":"un provvedimento che attribuisce al privato una qualche utilità non già ricompresa nella sua sfera giuridica","wrong1":"un provvedimento che amplia gli obiettivi della pubblica amministrazione","wrong2":"un provvedimento che delega al privato l'esercizio del potere amministrativo","wrong3":"un provvedimento che sottrae al cittadino, a favore dell'amministrazione, un qualche bene o utilità"},{"id":226,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Una delle caratteristiche del potere amministrativo è:","correct":"la discrezionalità","wrong1":"la scelta del Sindaco","wrong2":"la scelta dei consiglieri comunali","wrong3":"la scelta dei Ministri"},{"id":227,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Il vincolo può essere:","correct":"stabilito dalla pubblica amministrazione e, sovente, da un organo diverso rispetto a quello chiamato a decidere in uno stadio successivo","wrong1":"stabilito solo dalla politica","wrong2":"stabilito eccezionalmente dalla pubblica amministrazione","wrong3":"stabilito dal giudice, adito in via preventiva"},{"id":228,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Se compie un atto discrezionale l'amministrazione deve compiere un'attività di:","correct":"integrazione valutando il potere affidato dalla legge alla stessa e la decisione che la stessa può adottare","wrong1":"integrazione spiegando le motivazioni della decisione anche se contra legem","wrong2":"rinvio della decisione di un altro organo per assumere un parere","wrong3":"rinvio della decisione ad altro organo per delegare la decisione"},{"id":229,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Il procedimento per il riconoscimento di notevole interesse non è:","correct":"né immediato né scontato","wrong1":"ad esito scontato","wrong2":"immediato","wrong3":"immediato ma scontato"},{"id":230,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Il presupposto della discrezionalità coincide con la presenza di un fatto che deve essere:","correct":"valutato, apprezzato, ponderato","wrong1":"solamente apprezzato","wrong2":"solamente valutato","wrong3":"apprezzato e valutato"},{"id":231,"paragraph":"Diritto amministrativo - La discrezionalità","question":"L'amministrazione nel compiere una scelta discrezionale analizza:","correct":"concetti giuridici indeterminati, adattandoli al caso concreto","wrong1":"concetti giuridici","wrong2":"i casi concreti senza l'ausilio delle norme","wrong3":"ciò che politicamente è meglio fare"},{"id":232,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Talvolta la decisione o scelta può non esserci se «le risultanze dell'istruttoria» conducono:","correct":"ad una scelta obbligata","wrong1":"alle dimissioni del Sindaco","wrong2":"alle dimissioni del Segretario comunale o Generale","wrong3":"al rimpasto politico"},{"id":233,"paragraph":"Diritto amministrativo - La discrezionalità","question":"La discrezionalità coincide:","correct":"con la ponderazione comparativa dell'interesse primario e degli interessi secondari","wrong1":"con la volontà di scelta senza ponderazione","wrong2":"con la volontà di scelta senza ponderazione né ripercussioni","wrong3":"nell'esercizio di un potere amministrativo da svolgere anche andando contro la legge"},{"id":234,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Mediante il potere discrezionale può essere sciolto ad esempio un consiglio comunale:","correct":"perché a seguito di indagini e/o condanne sono provate le infiltrazioni mafiose in quell'ente","wrong1":"per colpire un consiglio comunale inefficiente","wrong2":"perché non è stato approvato il bilancio consuntivo entro il 31 gennaio","wrong3":"perché non è stato approvato il bilancio consuntivo entro il 28 febbraio"},{"id":235,"paragraph":"Diritto amministrativo - La discrezionalità","question":"Il giudice amministrativo spesso è chiamato a sindacare i provvedimenti discrezionali lesivi:","correct":"dell'interesse legittimo dei destinatari","wrong1":"dell'interesse legittimo degli organi superiori","wrong2":"del diritto soggettivo delle Associazioni di categoria","wrong3":"del diritto soggettivo delle aziende con sede legale in quel luogo"},{"id":236,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"La nozione di persona giuridica:","correct":"è comune al diritto pubblico e al diritto privato","wrong1":"riguarda solo il diritto privato","wrong2":"riguarda solo il diritto pubblico","wrong3":"riguarda piccoli aspetti del diritto privato e tutto il diritto pubblico"},{"id":237,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"La differenza fra la persona giuridica pubblica e quella privata:","correct":"va ravvisata nei distinti fini che perseguono: infatti la prima persegue fini appartenenti alla collettività di persone, mentre la seconda persegue fini prevalentemente privati","wrong1":"va ravvisata nei distinti fini che perseguono: infatti la prima non persegue fini appartenenti alla collettività di persone, mentre la seconda persegue fini prevalentemente privati","wrong2":"va ravvisata nei distinti fini che perseguono: infatti la prima persegue fini appartenenti alla collettività di persone, mentre la seconda non persegue fini prevalentemente privati","wrong3":"va ravvisata nei distinti fini che perseguono: infatti la prima non persegue fini appartenenti alla collettività di persone, mentre la seconda non persegue fini prevalentemente privati"},{"id":238,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Le categorie che permettono di considerare unitariamente la pubblica amministrazione sono:","correct":"persona giuridica, organo, ufficio","wrong1":"organo, ufficio","wrong2":"persona giuridica, ufficio","wrong3":"organo, persona giuridica"},{"id":239,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"I fini che devono perseguire le persone giuridiche pubbliche vengono stabiliti dalle leggi sulla pubblica amministrazione che:","correct":"stabiliscono fini da raggiungere o interessi pubblici da tutelare; conferiscono poteri necessari per il raggiungimento degli stessi","wrong1":"non stabiliscono fini da raggiungere o interessi pubblici da tutelare; non conferiscono poteri necessari per il raggiungimento degli stessi","wrong2":"non stabiliscono fini da raggiungere o interessi pubblici da tutelare ma conferiscono poteri necessari per il raggiungimento degli stessi","wrong3":"non stabiliscono fini da raggiungere o interessi pubblici da tutelare; non conferiscono poteri necessari per il raggiungimento degli stessi"},{"id":240,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"I poteri che vengono attribuiti a ciascun ente vengono distribuiti:","correct":"fra gli organi in virtù delle rispettive competenze","wrong1":"fra gli Uffici","wrong2":"fra i Dirigenti","wrong3":"fra i capi reparto"},{"id":241,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Le varie attribuzioni di un ente vengono ripartite in base a vari criteri:","correct":"criterio della materia; criterio dei destinatari; criteri territoriali; criterio della dimensione","wrong1":"criterio della materie e dei destinatari","wrong2":"criterio della dimensione","wrong3":"criteri territoriali"},{"id":242,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Dopo l'avvento del d.lgs.267/2000 anche i dirigenti:","correct":"sono considerati organi","wrong1":"sono considerati rimovibili","wrong2":"sono considerati non rimovibili","wrong3":"vengono rinnovati ogni mese"},{"id":243,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Gli organi vengono classificati in virtù dell'attività svolta, pertanto esistono organi di:","correct":"amministrazione attiva, consultiva e di controllo","wrong1":"consultiva","wrong2":"controllo","wrong3":"consultiva e di controllo"},{"id":244,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Quando ad essere assente è la persona fisica che ricopre l'organo:","correct":"subentra un suo vice in caso di assenza o impedimento del titolare","wrong1":"subentra il dirigente","wrong2":"non subentra nessuno","wrong3":"subentra il responsabile del procedimento"},{"id":245,"paragraph":"Diritto amministrativo - L'organizzazione amministrativa","question":"Il rapporto che intercorre fra la persona fisica e l'ente pubblico influisce:","correct":"sul regime della responsabilità","wrong1":"sulla fiducia","wrong2":"sulla valutazione della performance","wrong3":"sulla durata del rapporto di lavoro"},{"id":246,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Si configura una discrezionalità tecnica quando:","correct":"il giudizio richiesto all'autorità amministrativa deve essere espresso tenendo conto di conoscenze specialistiche","wrong1":"i tecnici prendono decisioni al posto della magistratura","wrong2":"i tecnici prendono decisioni al posto della politica","wrong3":"il giudizio richiesto all'autorità amministrativa deve essere espresso dall'intelligenza artificiale"},{"id":247,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"I problemi della discrezionalità tecnica:","correct":"riguardano la fase dell'accertamento dei presupposti della decisione, e quindi il momento che precede la stessa","wrong1":"si scontrano con la volontà della magistratura di tener conto solo della loro volontà","wrong2":"Sono attinenti ai problemi di equilibrio politico della maggioranza di governo","wrong3":"Riguardano la fase successiva alla decisione presa"},{"id":248,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Quando ad essere impugnato è un provvedimento discrezionale il giudice analizza:","correct":"non solo il contenuto dell'atto ma il modo in cui l'amministrazione è pervenuta alla sua adozione","wrong1":"il contenuto dell'atto","wrong2":"il contenuto dell'atto, se firmato con firma autografa o digitale","wrong3":"se è stato notificato nei termini"},{"id":249,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"L'accertamento dei fatti e dei presupposti per l'esercizio del potere amministrativo è rimesso:","correct":"all'istruttoria","wrong1":"alla magistratura","wrong2":"alla magistratura dopo aver udito il consulente tecnico d'ufficio","wrong3":"al giudice amministrativo in sede di merito"},{"id":250,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Il giudice amministrativo chiamato a giudicare una decisione amministrativa tecnica:","correct":"non si sostituisce all'autorità amministrativa, ma valuta la legittimità della decisione anche alla luce di un criterio di attendibilità tecnica","wrong1":"dichiara la sua incompetenza e la rinvia al giudice ordinario","wrong2":"si sostituisce all'autorità amministrativa e può anche ribaltare la decisione","wrong3":"si sostituisce all'autorità amministrativa in quanto il processo amministrativo assicura una tutela piena ed effettiva agli interessi dei privati"},{"id":251,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Il provvedimento è vincolato quando:","correct":"non ammette alternative e l'amministrazione non dispone di alcun potere di scelta","wrong1":"ammette alternative","wrong2":"l'amministrazione dispone di un potere di scelta limitato alla valutazione dei presupposti dell'atto","wrong3":"l'amministrazione deve solo verificare l'opportunità del provvedimento"},{"id":252,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Non è ipotizzabile per l'atto vincolato il vizio:","correct":"di eccesso di potere","wrong1":"di violazione di legge","wrong2":"di motivazione carente","wrong3":"non rispetto del principio di legalità"},{"id":253,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Al concetto di merito fa riferimento:","correct":"il Codice del processo amministrativo","wrong1":"il Codice dell'ambiente","wrong2":"il Codice penale","wrong3":"il Codice del procedimento amministrativo"},{"id":254,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Il vizio di legittimità:","correct":"è sindacabile dal giudice amministrativo","wrong1":"non è sindacabile dal giudice amministrativo","wrong2":"è sindacabile solo dal giudice contabile","wrong3":"è sindacabile solo dal giudice tributario"},{"id":255,"paragraph":"Diritto amministrativo - Discrezionalità tecnica e attività vincolata","question":"Il vizio di merito:","correct":"non è sindacabile dal giudice amministrativo al di fuori delle ipotesi, eccezionali, previste dalla legge","wrong1":"non è mai sindacabile dal giudice amministrativo","wrong2":"è sindacabile dal giudice amministrativo","wrong3":"è sindacabile dal giudice amministrativo, ad eccezioni delle ipotesi tassative nelle quali è escluso"},{"id":256,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Gli atti di una pubblica amministrazione sono:","correct":"il risultato di un'attività svolta per il perseguimento di un fine collettivo","wrong1":"un insieme di atti del Sindaco o del vertice dell'Amministrazione","wrong2":"una modalità di risoluzione delle controversie","wrong3":"il risultato di un'attività svolta per il perseguimento di un fine privato"},{"id":257,"paragraph":"Diritto amministrativo - Fini e interessi","question":"L'interesse può essere:","correct":"privato, collettivo, generale pubblico","wrong1":"privato e collettivo","wrong2":"solo pubblico","wrong3":"pubblico e collettivo"},{"id":258,"paragraph":"Diritto amministrativo - Fini e interessi","question":"L'interesse pubblico si differenzia da tutti gli altri perché:","correct":"viene previsto da una norma, da una politica o da una misura pubblica","wrong1":"viene previsto da atti privati","wrong2":"riguarda un fatto privato del dirigente preposto","wrong3":"viene previsto solo da politiche"},{"id":259,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Gli interessi generali e gli interessi pubblici:","correct":"non possono essere considerati come interessi più elevati rispetto a quelli privati di ogni individuo.","wrong1":"possono essere considerati come interessi più elevati ma solo rispetto a quelli privati di ogni individuo.","wrong2":"possono essere considerati come interessi più elevati rispetto a quelli privati di ogni individuo.","wrong3":"sono superiori anche rispetto alla legge"},{"id":260,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Gli interessi pubblici non possono moltiplicarsi all'infinito:","correct":"ma incontrano un primo vincolo che discende dalle costituzioni ove vengono disciplinati norme e principi che vincolano il legislatore","wrong1":"ma non hanno vincoli","wrong2":"incontrano il vincolo che discende non dalle costituzioni","wrong3":"ma incontrano un primo vincolo che discende dalle costituzioni ove vengono disciplinati norme e principi che non vincolano il legislatore"},{"id":261,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Le norme contenute nel Trattato di Roma istitutivo dalla Comunità economica europea e le norme modificative contenute nei trattati successivi:","correct":"hanno il rango di norme costituzionali","wrong1":"non hanno il rango di norme costituzionali","wrong2":"hanno il rango di fonti primarie","wrong3":"hanno il rango di fonti secondarie"},{"id":262,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Il finanziamento pubblico delle attività economiche:","correct":"è ammesso a condizione che rispetti la disciplina europea sugli aiuti di Stato","wrong1":"è sempre ammesso, salvo che non serva a finanziare attività illegali","wrong2":"è ammesso a condizione che non alteri l'equilibrio del mercato","wrong3":"è ammesso solo in favore di soggetti che non operano in regime di monopolio"},{"id":263,"paragraph":"Diritto amministrativo - Fini e interessi","question":"La nozione europea di impresa:","correct":"prescinde dallo status giuridico del soggetto e dalle modalità di finanziamento","wrong1":"non prescinde dallo status giuridico del soggetto","wrong2":"non prescinde dalle modalità di finanziamento","wrong3":"prescinde dallo status giuridico del soggetto ma non dalle modalità di finanziamento"},{"id":264,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Lo Stato italiano è impegnato a sostenere una politica economica ispirata:","correct":"ai principi di libera concorrenza e di un'economia di mercato aperta","wrong1":"non ai principi di libera concorrenza e di un'economia di mercato aperta","wrong2":"solo ai principi di un'economia di mercato aperta","wrong3":"alla libertà assoluta"},{"id":265,"paragraph":"Diritto amministrativo - Fini e interessi","question":"Il denaro che lo Stato e gli enti pubblici utilizzano per soddisfare gli interessi pubblici presuppone:","correct":"il diritto di imposizione fiscale per acquisire le risorse che consentono di soddisfare i vari interessi pubblici","wrong1":"l'obbligo di imposizione fiscale per acquisire le risorse che consentono di soddisfare i vari interessi pubblici","wrong2":"l'obbligo di imposizione fiscale per acquisire le risorse che consentono di soddisfare i vari interessi privati","wrong3":"il diritto di imposizione fiscale per acquisire le risorse che consentono di soddisfare i vari interessi privati"},{"id":266,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"La funzione legislativa:","correct":"è suddivisa fra Stato e Regioni","wrong1":"appartiene solo allo Stato","wrong2":"è suddivisa tra lo Stato, le Regioni ed i comuni","wrong3":"appartiene solo alle Regioni"},{"id":267,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"La riserva di legge disposta dalla Costituzione nell'organizzazione dell'attività amministrativa:","correct":"non si riferisce solo alle leggi in senso formale, ma anche agli atti aventi forza di legge","wrong1":"si riferisce solo alle leggi in senso formale","wrong2":"si riferisce solo agli atti aventi forza di legge","wrong3":"si riferisce solo alle fonti secondarie"},{"id":268,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"La principale fonte di disciplina della pubblica amministrazione, che rispecchia i principi stabiliti dalla Costituzione:","correct":"è rappresentata dalle leggi statali, regionali, dai regolamenti, dalle norme europee, e dalle convenzioni internazionali","wrong1":"è rappresentata solo dalle leggi statali","wrong2":"è rappresentata dalle convenzioni internazionali","wrong3":"è rappresentata essenzialmente dalle leggi regionali"},{"id":269,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"L'art. 97 della Costituzione:","correct":"determina, in primo luogo, un vincolo per la potestà legislativa statale e regionale stabilendo il contenuto minimo della legge che riguarda l'organizzazione amministrativa; stabilisce anche due limiti di carattere finalistico in base ai quali la legge deve assicurare il buon andamento e l'imparzialità dell'amministrazione","wrong1":"non stabilisce alcun vincolo","wrong2":"stabilisce solo due limiti di carattere finalistico in base ai quali la legge deve assicurare il buon andamento e l'imparzialità dell'amministrazione","wrong3":"determina solo un vincolo per la potestà legislativa statale e regionale stabilendo il contenuto minimo della legge che riguarda l'organizzazione amministrativa"},{"id":270,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"La materia dei regolamenti governativi è disciplinata:","correct":"dalla legge 400/1988","wrong1":"dalla legge 241/1990","wrong2":"dalla legge 190/2012","wrong3":"dalla legge 124/2016"},{"id":271,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"L'art. 17 della legge n. 400/88 prevede:","correct":"cinque specie di regolamenti","wrong1":"tre specie di regolamenti","wrong2":"due specie di regolamenti","wrong3":"quattro specie di regolamenti"},{"id":272,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"Con la modifica prevista dalla legge costituzionale 1/1999 è venuta meno la riserva al Consiglio regionale della potestà regolamentare. Attualmente spetta:","correct":"alla Regione attribuire tale potestà al Consiglio o alla Giunta","wrong1":"alla Regione attribuire tale potestà ai Sindaci","wrong2":"alla Regione attribuire tale potestà ai Sindaci delle Città Metropolitane","wrong3":"alla Regione attribuire tale potestà ai Prefetti"},{"id":273,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"Ogni Regione ha uno statuto che, nel rispetto della Costituzione, ne determina:","correct":"la forma di governo ed i principi fondamentali di organizzazione e funzionamento","wrong1":"il numero di imposte","wrong2":"il numero di sindaci","wrong3":"il numero di Prefetti"},{"id":274,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"Lo Statuto, nelle regioni a statuto ordinario, viene approvato:","correct":"dal Consiglio regionale","wrong1":"dalla Giunta","wrong2":"dal Presidente","wrong3":"dal Consiglio dei Ministri"},{"id":275,"paragraph":"Diritto amministrativo - Funzioni e fonti","question":"Gli Statuti regionali delle Regioni a statuto speciale:","correct":"hanno rango di legge costituzionale","wrong1":"non hanno rango di legge costituzionale","wrong2":"hanno rango di fonte primaria","wrong3":"hanno rango di fonte secondaria"},{"id":276,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"I poteri amministrativi possono essere classificati in base al criterio:","correct":"dell'interesse pubblico da soddisfare","wrong1":"dato dal Ministero della Pubblica Amministrazione","wrong2":"dell'interesse privato da soddisfare","wrong3":"dell'interesse politico da soddisfare"},{"id":277,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"In base all'interesse del privato è possibile distinguere fra:","correct":"poteri restrittivi o ablatori e poteri ampliativi","wrong1":"poteri restrittivi e ablatori","wrong2":"poteri ampliativi e favorevoli","wrong3":"poteri repressivi e ablativi"},{"id":278,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"La tutela degli interessi legittimi è affidata:","correct":"alla giustizia amministrativa","wrong1":"agli organismi di mediazione","wrong2":"alla Corte d'Appello, sezione Lavoro","wrong3":"alla giustizia ordinaria"},{"id":279,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"In passato la dottrina e giurisprudenza dominante hanno sostenuto che la tutela dell'interesse pubblico:","correct":"è occasionale e indiretta","wrong1":"è diretta","wrong2":"non è diretta e non è occasionale","wrong3":"è diretta ma occasionale"},{"id":280,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"La nozione di interesse legittimo include:","correct":"sia i c.d. diritti affievoliti ossia quei diritti degradati ad interessi; sia i c.d. diritti in attesa di espansione e quindi in attesa di un provvedimento favorevole","wrong1":"solo i c.d. diritti affievoliti ossia quei diritti degradati ad interessi","wrong2":"solo i c.d. diritti in attesa di espansione e quindi in attesa di un provvedimento favorevole","wrong3":"i c.d. diritti affievoliti ossia quei diritti degradati ad interessi ma non i c.d. diritti in attesa di espansione e quindi in attesa di un provvedimento favorevole"},{"id":281,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"L'interesse legittimo nasce:","correct":"già al momento dell'avvio del procedimento e quando l'atto conclusivo che verrà adottato comincia a prendere forma","wrong1":"al momento della decisione","wrong2":"al momento del rigetto o dell'accoglimento dell'istanza","wrong3":"dopo aver presentato il ricorso"},{"id":282,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"Con la partecipazione del privato al procedimento:","correct":"questi può produrre documenti e sostenere argomenti che possono suggerire all'amministrazione di non adottare un provvedimento sfavorevole","wrong1":"questi può solo produrre documenti nei termini indicati dall'amministrazione, che sono tassativi","wrong2":"questi non può comunque produrre documenti e sostenere argomenti che possono suggerire all'amministrazione di non adottare un provvedimento sfavorevole","wrong3":"questi può solo sostenere argomenti verbalmente che possono suggerire all'amministrazione di non adottare un provvedimento sfavorevole"},{"id":283,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"Le forme di controllo che il titolare dell'interesse può esercitare sono:","correct":"due","wrong1":"tre","wrong2":"quattro","wrong3":"cinque"},{"id":284,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"A fine anni '90 la Corte di Cassazione ed il legislatore hanno riconosciuto il diritto di risarcimento del danno da lesione:","correct":"dell'interesse legittimo","wrong1":"del diritto ad un buon livello di vita","wrong2":"delle aspettative qualificate","wrong3":"del diritto soggettivo"},{"id":285,"paragraph":"Diritto amministrativo - Poteri amministrativi e situazioni giuridiche","question":"Il risarcimento del danno può essere chiesto dal privato al giudice amministrativo:","correct":"quando abbia subito un danno ingiusto derivante dall'illegittimo esercizio del potere amministrativo o dal mancato esercizio di quello obbligatorio","wrong1":"entro 10 anni","wrong2":"entro 15 anni","wrong3":"entro 180 giorni"},{"id":286,"paragraph":"Diritto amministrativo - Il procedimento amministrativo","question":"Con la Legge n. 241/1990:","correct":"sono stati generalizzati alcuni dei principi elaborati dalla giurisprudenza; il legislatore inoltre si è fatto carico dei problemi connessi all'inesistenza di una disciplina unitaria del procedimento amministrativo","wrong1":"il legislatore è andato contro la giurisprudenza affermando principi innovativi","wrong2":"sono stati generalizzati alcuni dei principi affermatisi sotto il vigore dello Statuto albertino","wrong3":"il legislatore si è fatto carico di creare una disciplina unitaria sulla materia, escludendo però alcuni settori come la tutela della salute, l'ambiente e il paesaggio"},{"id":287,"paragraph":"Diritto amministrativo - Il procedimento amministrativo","question":"I destinatari della comunicazione di avvio del procedimento sono:","correct":"i destinatari del provvedimento finale; coloro che per legge devono intervenire; coloro che dal provvedimento finale potrebbero ricevere un pregiudizio","wrong1":"i destinatari del provvedimento finale","wrong2":"le rappresentanze sindacali, se presenti nell'Amministrazione","wrong3":"i cittadini del luogo in cui si producono gli effetti della decisione, che ne vengono notiziati mediante pubblicazione"},{"id":288,"paragraph":"Diritto amministrativo - Il procedimento amministrativo","question":"L'iniziativa procedimentale può essere:","correct":"di parte e d'ufficio","wrong1":"sempre e solo di parte","wrong2":"politica","wrong3":"pubblica o privata"},{"id":289,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Le fonti terziarie sono:","correct":"atti provenienti dall'amministrazione che vincolano la successiva attività provvedimentale della pubblica amministrazione o quella dei privati","wrong1":"atti provenienti dai privati","wrong2":"atti provenienti da altri poteri pubblici","wrong3":"atti che non vincolano la successiva attività"},{"id":290,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Le circolari sono atti che:","correct":"permettono agli organi di vertice di un apparato (ministro, dirigente generale, sindaco, etc) di illustrare il contenuto di una legge recente","wrong1":"permettono agli organi di vertice di un apparato (ministro, dirigente generale, sindaco, etc) di illustrare il contenuto di un articolo non recente","wrong2":"permettono agli organi di staff di un apparato (capo di gabinetto, ufficio legislativo) di illustrare il contenuto di una legge recente","wrong3":"permettono agli organi di vertice di un apparato (ministro, dirigente generale, sindaco, etc) di illustrare il contenuto di una legge in corso di adozione"},{"id":291,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Il Trattato di Roma ha creato una organizzazione composta dalle seguenti istituzioni:","correct":"Consiglio, Commissione e Parlamento","wrong1":"Commissione e Consiglio","wrong2":"Parlamento e Commissione","wrong3":"Consiglio e Parlamento"},{"id":292,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"La legge interna in contrasto con la legge comunitaria si deve considerare:","correct":"costituzionalmente illegittima per violazione dell'art. 11 della Cost.","wrong1":"costituzionalmente legittima","wrong2":"comunitariamente illegittima, ma legittima per il diritto nazionale","wrong3":"costituzionalmente illegittima per violazione dell'art. 1 della Cost."},{"id":293,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Le fonti derivate elencate dall'art. 288 TFUE sono:","correct":"il regolamento, la direttiva, la decisione e la raccomandazione","wrong1":"Il regolamento e la direttiva","wrong2":"Il regolamento e la raccomandazione","wrong3":"la raccomandazione e la decisione"},{"id":294,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Se la Direttiva riguarda i rapporti fra soggetti privati:","correct":"è necessaria la trasposizione nel diritto interno affinché fra le parti possano crearsi diritti ed obblighi","wrong1":"non è necessaria la trasposizione nel diritto interno affinché fra le parti possano crearsi diritti ed obblighi","wrong2":"è necessaria una legge affinché fra le parti possano crearsi diritti ed obblighi","wrong3":"è necessaria una circolare affinché fra le parti possano crearsi diritti ed obblighi"},{"id":295,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Le norme internazionali:","correct":"sono suddivise in due grandi categorie: convenzionali e consuetudinarie","wrong1":"non hanno suddivisioni in categorie","wrong2":"sono suddivise in due grandi categorie: convenzionali e abitudinarie","wrong3":"sono suddivise in due grandi categorie: abitudinarie e consuetudinarie"},{"id":296,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"La giurisprudenza:","correct":"non è fonte del diritto","wrong1":"è fonte del diritto","wrong2":"non è fonte del diritto amministrativo, ma solo del diritto costituzionale","wrong3":"è fonte del diritto amministrativo"},{"id":297,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Il diritto amministrativo:","correct":"non ha un codice con tutte le sue leggi","wrong1":"ha un codice con tutte le sue leggi","wrong2":"non ha nulla di scritto ma si basa solo sui casi pratici, anche se non conformi alla legge","wrong3":"ha un codice ma non viene seguito"},{"id":298,"paragraph":"Diritto amministrativo - Le fonti terziarie, sovranazionali e il ruolo della giurisprudenza","question":"Per costruire il corpus di principi la giurisprudenza:","correct":"ha attribuito un contenuto più ampio a formule legislative estremamente sintetiche; ha fatto tesoro del contributo dottrinale per l'elaborazione di alcune categorie","wrong1":"ha attribuito solo un contenuto più ampio a formule legislative estremamente sintetiche","wrong2":"ha fatto tesoro solo del contributo dottrinale per l'elaborazione di alcune categorie","wrong3":"si affida a giudici privati nominati"},{"id":299,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"Il concetto di pubblica amministrazione si caratterizza per un perimetro molto ampio perché include, tra l'altro:","correct":"comuni, province, città metropolitane e regioni","wrong1":"solo i comuni","wrong2":"comuni, province e regioni","wrong3":"comuni e regioni perché le province sono state abolite"},{"id":300,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"Il Presidente del Consiglio:","correct":"assicura l'unità di indirizzo politico ed amministrativo","wrong1":"assicura il funzionamento della Presidenza della Repubblica","wrong2":"scioglie il Parlamento","wrong3":"ha poteri illimitati in caso di emergenza"},{"id":301,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"Gli organi che, nel linguaggio del diritto costituzionale, vengono associati all'idea di Stato sono:","correct":"il Governo, Il Parlamento e il Capo dello Stato","wrong1":"il Governo ed il Parlamento","wrong2":"il Capo dello Stato ed il Governo","wrong3":"il Parlamento ed il Capo dello Stato"},{"id":302,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"I ministri sono responsabili:","correct":"collegialmente degli atti del Consiglio dei ministri ed individualmente degli atti dei dicasteri","wrong1":"solo collegialmente degli atti del Consiglio dei ministri","wrong2":"solo individualmente degli atti dei dicasteri","wrong3":"non sono mai responsabili nell'esercizio delle loro funzioni"},{"id":303,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"La disciplina costituzionale del rapporto fra Ministro e dirigente è contenuta oltre che nell'art. 95 della Cost. anche:","correct":"negli articoli 97 e 28 Cost.","wrong1":"nell'art. 138 Cost.","wrong2":"nell'art. 2 Cost.","wrong3":"negli articoli 9 e 10 Cost."},{"id":304,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"La carriera dirigenziale è attualmente suddivisa in:","correct":"dirigenti di prima e di seconda fascia","wrong1":"dirigenti generale e superiori","wrong2":"dirigente generali; dirigente superiori; primi dirigenti","wrong3":"dirigenti di prima, seconda e terza fascia"},{"id":305,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"Ai Dirigenti spetta:","correct":"l'adozione degli atti amministrativi che impegnano l'amministrazione verso l'esterno, oltre che la gestione finanziaria, amministrativa e tecnica mediante autonomi poteri di spesa","wrong1":"la gestione finanziaria","wrong2":"l'adozione di atti amministrativi che non comportino spese","wrong3":"solo la gestione finanziaria, amministrativa e tecnica mediante autonomi poteri di spesa"},{"id":306,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"In base al quadro normativo definito dal D.lgs. 300/1999 i Ministeri si suddividono:","correct":"in due gruppi","wrong1":"in tre gruppi","wrong2":"in un gruppo solo","wrong3":"in quattro gruppi"},{"id":307,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"L'organo di consulenza del Ministero delle infrastrutture e dei trasporti è:","correct":"il Consiglio Superiore dei lavori pubblici","wrong1":"il Consiglio Superiore dei trasporti","wrong2":"il Consiglio dei lavori pubblici","wrong3":"il Consiglio dei Geometri"},{"id":308,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione statale","question":"Organizzazione periferica dello Stato significa:","correct":"che a livello periferico lo Stato opera mediante propri organi, che fanno capo a singoli Ministeri","wrong1":"che a livello periferico lo Stato opera attraverso i comuni e le province","wrong2":"che a livello periferico lo Stato opera attraverso i comuni, le province e le città metropolitane","wrong3":"che a livello periferico lo Stato opera attraverso i comuni, le province, le città metropolitane e le regioni"},{"id":309,"paragraph":"Diritto amministrativo - Il silenzio assenso fra amministrazioni e Conferenza di servizi","question":"L'ente chiamato al rilascio dell'assenso (nulla osta, concerto), dopo aver ricevuto la richiesta dall'organo competente ad emettere il provvedimento, dispone di un termine:","correct":"di 30 giorni","wrong1":"di 60 giorni","wrong2":"di 20 giorni","wrong3":"di 10 giorni"},{"id":310,"paragraph":"Diritto amministrativo - Il silenzio assenso fra amministrazioni e Conferenza di servizi","question":"In caso di più pareri, concerti, nulla osta, l'Amministrazione procedente:","correct":"è tenuta ad indire una conferenza di servizi","wrong1":"è tenuta ad indire un referendum","wrong2":"è tenuta ad arrestare il procedimento fino all'acquisizione, da parte dell'interessato, degli atti di assenso preliminari","wrong3":"è tenuta a concludere il procedimento apponendo al provvedimento finale una clausola risolutiva legata al buon esito delle procedure parallele di acquisizione degli atti di assenso"},{"id":311,"paragraph":"Diritto amministrativo - Il silenzio assenso fra amministrazioni e Conferenza di servizi","question":"Nel caso in cui, in seno alla conferenza di servizi, vengano espressi uno o più dissensi non superabili:","correct":"l'amministrazione procedente, se i dissensi non sono superati, conclude negativamente la conferenza, rigettando la domanda e chiedendo un parere alla Presidenza del Consiglio dei Ministri","wrong1":"l'amministrazione procedente, se i dissensi sono superabili, conclude negativamente la conferenza rigettando la domanda, comunicando l'esito della conferenza al privato","wrong2":"l'amministrazione procedente, se i dissensi non sono superati, conclude negativamente la conferenza, rigettando la domanda e chiedendo un parere all'Unione Europea","wrong3":"l'amministrazione procedente, se i dissensi non sono superabili, conclude negativamente la conferenza rigettando la domanda, comunicando l'esito della conferenza al privato"},{"id":312,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Prima del 1993 i cittadini:","correct":"eleggevano il Consiglio comunale che poi nominava il Sindaco","wrong1":"eleggevano il Sindaco","wrong2":"eleggevano il Presidente della Provincia","wrong3":"Eleggevano i segretari comunali"},{"id":313,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Con la legge n. 81 del 1993:","correct":"i cittadini eleggono direttamente il Sindaco","wrong1":"i cittadini eleggono direttamente il segretario comunale","wrong2":"i cittadini eleggono direttamente il vice Sindaco","wrong3":"i cittadini eleggono direttamente gli Assessori comunali"},{"id":314,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"La plurifunzionalità dei Comuni è sancita:","correct":"dall'art. 13 del Dlgs 267/2000","wrong1":"dall'art. 1 della legge 241/1990","wrong2":"dall'art. 13 della legge 241/1990","wrong3":"dall'art. 13 del Dlgs 175/2016"},{"id":315,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Le funzioni del comune possono derivare:","correct":"da leggi regionali nelle materie in cui le Regioni dispongono di competenze concorrenti o esclusive e da leggi statali","wrong1":"da leggi regionali soltanto","wrong2":"rigorosamente da leggi sovranazionali","wrong3":"dalla Costituzione"},{"id":316,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Gli organi dei comuni sono:","correct":"Consiglio comunale, Giunta e Sindaco","wrong1":"Consiglio Comunale","wrong2":"Giunta e Sindaco","wrong3":"Sindaco"},{"id":317,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Lo statuto viene approvato con il voto favorevole:","correct":"dei 2/3 dei consiglieri","wrong1":"della maggioranza semplice dei consiglieri","wrong2":"della maggioranza assoluta dei consiglieri","wrong3":"all'unanimità dei consiglieri"},{"id":318,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"La giunta è convocata:","correct":"dal Sindaco","wrong1":"dal segretario comunale","wrong2":"dal Consiglio comunale","wrong3":"dal consiglio dei cittadini"},{"id":319,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"Il Consiglio è:","correct":"è l'organo di indirizzo politico-amministrativo ed ha competenza limitatamente a: statuti, regolamenti, programmi, piani finanziari, bilanci","wrong1":"è l'organo di controllo del Sindaco","wrong2":"è l'organo di controllo della Giunta","wrong3":"si occupa di convocare la Giunta"},{"id":320,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"La gestione associata di funzioni da parte di un Consorzio:","correct":"serve per agevolare la cooperazione fra i Comuni più piccoli che non dispongono delle risorse necessarie umane e materiali","wrong1":"serve per diminuire le poltrone","wrong2":"serve per diminuire gli stipendi","wrong3":"serve per risparmiare sui Dirigenti"},{"id":321,"paragraph":"Diritto amministrativo - L'assetto positivo. L'amministrazione locale e regionale","question":"In origine il controllo sugli atti degli enti locali veniva svolto:","correct":"dalle Regioni tramite il CO.RE.CO.","wrong1":"dalla Prefettura","wrong2":"dalla Provincia","wrong3":"dal consiglio dei segretari comunali"},{"id":322,"paragraph":"Diritto amministrativo - Partecipazione del privato e accesso ai documenti amministrativi","question":"L'amministrazione ha l'obbligo di valutare le memorie e i documenti depositati dagli interessati:","correct":"ove siano pertinenti","wrong1":"in ogni caso","wrong2":"ove siano necessari","wrong3":"ove siano stati previamente trasmessi e valutati positivamente da parte delle amministrazioni preposte alla tutela ambientale o paesaggistico-territoriale o della salute dei cittadini"},{"id":323,"paragraph":"Diritto amministrativo - Partecipazione del privato e accesso ai documenti amministrativi","question":"Il diritto di accesso introdotto dalla l. n. 241 del 1990:","correct":"viene riconosciuto a chiunque vi abbia interesse per la tutela di situazioni giuridicamente rilevanti","wrong1":"si esercita mediante esame ed estrazione di copia di documenti, informazioni o dati di cui sia stata omessa la loro pubblicazione","wrong2":"viene riconosciuto a chiunque, allo scopo di favorire forme diffuse di controllo sul perseguimento delle funzioni istituzionali e sull'utilizzo delle risorse pubbliche e di promuovere la partecipazione al dibattito pubblico","wrong3":"viene riconosciuto a chiunque, allo scopo di favorire un controllo generalizzato dell'operato delle pubbliche amministrazioni"},{"id":324,"paragraph":"Diritto amministrativo - Partecipazione del privato e accesso ai documenti amministrativi","question":"L'Adunanza Plenaria del Consiglio di Stato n. 10 del 2020 ha chiarito:","correct":"che la pubblica amministrazione ha il potere-dovere di esaminare l'istanza di accesso agli atti e ai documenti pubblici, formulata in modo generico o cumulativo dal richiedente senza riferimento ad una specifica disciplina","wrong1":"che la pubblica amministrazione ha il potere-dovere di esaminare l'istanza di accesso agli atti e ai documenti pubblici, solo se formulata in modo preciso e, comunque, non cumulativo dal richiedente","wrong2":"che la pubblica amministrazione ha il potere-dovere di esaminare l'istanza di accesso agli atti e ai documenti pubblici, solo se formulata con riferimento alla disciplina dell'accesso ai sensi della l. n. 241 del 1990","wrong3":"che, contro il diniego di accesso ritenuto illegittimo dal richiedente, sono previste diverse forme di tutela: in particolare, il ricorso al Tribunale amministrativo regionale"},{"id":325,"paragraph":"Diritto amministrativo - Fasi del procedimento e semplificazione","question":"Se l'amministrazione non provvede a fissare autonomamente il termine, il procedimento deve concludersi:","correct":"entro trenta giorni","wrong1":"entro sessanta giorni","wrong2":"entro novanta giorni","wrong3":"entro il termine assegnato dal giudice su ricorso dell'interessato"},{"id":326,"paragraph":"Diritto amministrativo - Fasi del procedimento e semplificazione","question":"Il silenzio assenso dell'amministrazione:","correct":"è una misura avverso l'inerzia dell'amministrazione ed equivale ad accoglimento della domanda se si protrae oltre il termine di conclusione del procedimento previsto dalla legge","wrong1":"è una misura avverso l'inerzia dell'amministrazione, che tuttavia non equivale ad accoglimento della domanda, perché l'amministrazione può sempre provvedere anche oltre la conclusione del procedimento previsto dalla legge, senza incontrare alcuna preclusione","wrong2":"serve ad evitare all'Amministrazione di doversi pronunciare su istanze manifestamente ammissibili e fondate","wrong3":"è una misura avverso l'inerzia dell'amministrazione che può provocare la sostituzione del responsabile del procedimento"},{"id":327,"paragraph":"Diritto amministrativo - Fasi del procedimento e semplificazione","question":"Il provvedimento finale può essere preceduto o sostituito:","correct":"da un accordo tra amministrazione e privato","wrong1":"da un provvedimento semplificato","wrong2":"da un provvedimento di accoglimento","wrong3":"da un provvedimento semplificato ma di diniego"},{"id":328,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Gli enti pubblici sono stati costituiti:","correct":"non solo per erogare servizi dello Stato, ma anche per gestire servizi gestiti fino alla loro istituzione da soggetti privati inclusi ad un certo punto nella sfera pubblica","wrong1":"solo per erogare servizi dello Stato e per gestire servizi gestiti fino alla loro istituzione da soggetti privati inclusi ad un certo punto nella sfera pubblica","wrong2":"solo per erogare servizi dello Stato","wrong3":"solo per gestire servizi gestiti fino alla loro istituzione da soggetti privati"},{"id":329,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"L'ente pubblico si differenzia dall'ente locale perché:","correct":"monofunzionale poiché cura un solo interesse pubblico, nonostante lo stesso faccia capo ad un vasto numero di soggetti","wrong1":"monofunzionale poiché cura un solo interesse privato","wrong2":"non è eletto dal corpo elettorale","wrong3":"non ha poteri di nomina della Giunta"},{"id":330,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Il problema della responsabilità ministeriale nell'ente pubblico non territoriale è stato risolto dalla legge n. 14/1978 che ha istituito:","correct":"un controllo parlamentare sulle nomine degli enti pubblici","wrong1":"un controllo parlamentare sugli appalti pubblici","wrong2":"un potere di veto dell'ente locale","wrong3":"un controllo dell'ente locale di riferimento"},{"id":331,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"La Costituzione:","correct":"sottopone gli enti pubblici ai quali lo Stato contribuisce in via ordinaria al controllo della Corte dei conti","wrong1":"non prevede forme di controllo sugli enti pubblici","wrong2":"prevede sugli enti pubblici un controllo di tipo giurisdizionale","wrong3":"sottopone gli enti pubblici al controllo del CNEL"},{"id":332,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Le Aziende e le Amministrazioni autonome continuano ad essere organi:","correct":"del rispettivo Ministero","wrong1":"della Regione dove si trova la sede legale","wrong2":"del comune dove risiede il Presidente","wrong3":"del comune dove si trova la sede legale"},{"id":333,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Il D.lgs. 300/1999 prevede l'istituzione di:","correct":"undici agenzie","wrong1":"dodici agenzie","wrong2":"dieci agenzie","wrong3":"un numero illimitato di agenzie"},{"id":334,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Gli enti pubblici economici si distinguono:","correct":"in enti di disciplina di settore ed enti imprenditoriali che svolgono direttamente l'attività economica di produzione di beni e servizi","wrong1":"in enti di disciplina di settore ed enti non imprenditoriali che svolgono però attività economica di produzione di beni e servizi","wrong2":"in enti di disciplina di settore ed enti imprenditoriali che non svolgono però attività economica di produzione di beni e servizi","wrong3":"in enti pubblici e privati"},{"id":335,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Gli enti pubblici economici sono di regola sprovvisti:","correct":"di poteri amministrativi","wrong1":"dei bilanci","wrong2":"di poteri inerenti l'organizzazione per l'assunzione di nuovo personale","wrong3":"di poteri circa il dialogo con gli utenti"},{"id":336,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Gli enti pubblici si sono sviluppati soprattutto durante gli anni:","correct":"settanta del secolo scorso","wrong1":"ottanta del secolo scorso","wrong2":"novanta del secolo scorso","wrong3":"venti del secolo scorso"},{"id":337,"paragraph":"Diritto amministrativo - Gli enti pubblici","question":"Vengono esclusi dal processo di ridimensionamento:","correct":"gli enti pubblici che gestiscono la previdenza sociale, gli enti che svolgono funzioni essenziali per difesa, sicurezza e salute pubblica e quelli che svolgono compiti di rilevanza costituzionale","wrong1":"solo gli enti che gestiscono la previdenza sociale","wrong2":"solo gli enti che svolgono compiti di rilevanza costituzionale","wrong3":"solo gli enti che gestiscono la previdenza sociale e quelli che svolgono compiti di rilevanza costituzionale"},{"id":338,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Il grande numero degli enti pubblici economici previsti dal nostro ordinamento si è scontrato:","correct":"con il divieto di aiuti di Stato sancito dall'attuale art. 107 del TFUE","wrong1":"con il proliferare delle Città Metropolitane","wrong2":"con gli Statuti delle Regioni ordinarie","wrong3":"con il numero sempre maggiore dei Ministeri"},{"id":339,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Lo Stato italiano per rispettare il patto di stabilità siglato a Maastricht nel 1992:","correct":"ha dovuto ridurre il debito pubblico mediante dismissione del patrimonio","wrong1":"ha prodotto maggiore debito","wrong2":"ha assunto molto personale per far fronte a quanto stabilito nel patto di stabilità","wrong3":"ha ridotto il numero dei parlamentari"},{"id":340,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"La trasformazione di enti pubblici in società per azioni:","correct":"è stato il modo per dismettere la parte più cospicua del capitale di proprietà pubblica","wrong1":"è stato il modo per dismettere la parte più cospicua del capitale di proprietà privata","wrong2":"è stato il modo per aumentare il patrimonio dello Stato","wrong3":"è stato il modo per diventare un Paese economicamente florido, il primo al mondo"},{"id":341,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"L'IRI (Istituto per la ricostruzione industriale):","correct":"fu creato a seguito della crisi economica del 1929/1933","wrong1":"fu creato da Crispi a fine ottocento","wrong2":"fu creato da Giolitti nel 1901","wrong3":"fu creato con l'introduzione dell'euro"},{"id":342,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"L'IRI aveva potere direzionale su gran parte delle:","correct":"imprese private italiane","wrong1":"imprese private europee","wrong2":"imprese pubbliche europee","wrong3":"imprese pubbliche italiane"},{"id":343,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"L'ENI (Ente nazionale idrocarburi):","correct":"fu creato nel 1953 seguendo il modello dell'IRI","wrong1":"fu creato a seguito dell'Unità d'Italia","wrong2":"fu creato quotando in Borsa l'IRI","wrong3":"fu creato a seguito della Guerra del Golfo per avere potere direzionale sulle imprese italiane del settore"},{"id":344,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Il Ministero delle partecipazioni statali emana:","correct":"direttive nei confronti degli enti di gestione","wrong1":"direttive nei confronti di tutte le imprese private europee","wrong2":"leggi inerenti il funzionamento degli enti pubblici del Medio Oriente","wrong3":"regolamenti amministrativi riguardanti le modifiche del trattato di Maastricht"},{"id":345,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Le imprese a partecipazione statale avevano l'obbligo:","correct":"di destinare una quota non inferiore al 40% agli investimenti nel Mezzogiorno","wrong1":"di destinare una quota non inferiore al 50% agli investimenti nei Paesi del Medio Oriente","wrong2":"di destinare una quota non inferiore al 50% agli investimenti nel Mezzogiorno","wrong3":"di destinare una quota non inferiore al 40% agli investimenti nei Paesi Baltici"},{"id":346,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Il Ministero delle partecipazioni statali:","correct":"viene soppresso nel 1993 a seguito del referendum popolare","wrong1":"viene soppresso nel 2022 a seguito delle elezioni politiche","wrong2":"viene soppresso nel 1992 a seguito del referendum popolare","wrong3":"è stato soppresso nel 1992 ma è stato istituito nuovamente a seguito della volontà del legislatore di investire nell'economia acquistando nuove imprese private"},{"id":347,"paragraph":"Diritto amministrativo - La crisi del sistema degli enti pubblici e le società in mano pubblica","question":"Il D.LGS. 175/2016 persegue come finalità:","correct":"l'efficiente gestione delle partecipazioni pubbliche, la tutela della concorrenza e la razionalizzazione della spesa pubblica","wrong1":"il proliferare di nuove partecipazioni pubbliche","wrong2":"il proliferare di nuove aziende private","wrong3":"quella di stabilire regole per gli investimenti esteri in Italia"},{"id":348,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Le Autorità Amministrative entrano nel nostro ordinamento giuridico:","correct":"negli anni novanta del secolo scorso","wrong1":"negli anni sessanta del secolo scorso","wrong2":"negli anni settanta del secolo scorso","wrong3":"negli anni ottanta del secolo scorso"},{"id":349,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Lo schema organizzativo dell'attività amministrativa è stato preceduto da un sistema che in passato si basava sull'intervento pubblico nell'economia che avveniva:","correct":"in due modi: attraverso il monopolio pubblico di determinate attività economiche ed attraverso il controllo amministrativo del mercato","wrong1":"mediante l'acquisto di tutte le imprese private","wrong2":"solo mediante il controllo amministrativo del mercato","wrong3":"senza regole"},{"id":350,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Una indicazione sulle imprese che erogano servizi pubblici essenziali in situazione di monopolio:","correct":"è prevista anche dall'art. 43 della Costituzione","wrong1":"non è prevista nel nostro ordinamento giuridico","wrong2":"è ricavabile solo dal TFUE","wrong3":"è prevista dalla legge sul conflitto d'interessi"},{"id":351,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Attraverso il controllo amministrativo del mercato i pubblici poteri stabiliscono:","correct":"regole di accesso al mercato e un intenso sistema di controlli amministrativi sull'osservanza delle regole","wrong1":"soltanto regole di accesso al mercato","wrong2":"le sanzioni in merito solo al sistema di controlli","wrong3":"che nessun fondo privato può investire nel nostro Paese"},{"id":352,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Il Trattato di Roma enuncia principi in contrasto con i precedenti assetti legislativi ed amministrativi:","correct":"ossia la libera circolazione di fattori produttivi e che le imprese che gestiscono servizi pubblici sono obbligate ad osservare le regole sulla concorrenza a meno che la loro osservanza non pregiudichi l'adempimento della missione loro affidata","wrong1":"ossia solo la libera circolazione di fattori produttivi","wrong2":"ossia la libera circolazione di fattori produttivi senza regole","wrong3":"che le imprese che gestiscono servizi pubblici sono obbligate ad osservare le regole sulla concorrenza senza eccezioni"},{"id":353,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"Secondo i principi comunitari gli aiuti di Stato sono:","correct":"misure distorsive per eccellenza della concorrenza","wrong1":"misure che salvaguardano la concorrenza","wrong2":"misure che regolano la concorrenza","wrong3":"misure che disciplinano le regole comunitarie sulla concorrenza, a tutela degli investitori"},{"id":354,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"La CONSOB (Commissione nazionale per le società e la borsa):","correct":"è un'Autorità Amministrativa italiana","wrong1":"si occupa di Assicurazioni e di sinistri","wrong2":"non è un'Autorità Amministrativa italiana","wrong3":"è una Commissione parlamentare"},{"id":355,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"L'indipendenza delle Autorità Amministrative Indipendenti:","correct":"è anche garantita dalla durata lunga del mandato, pari a 7 anni, degli amministratori, non rinnovabile","wrong1":"è anche garantita dalla durata lunga del mandato, pari a 10 anni, degli amministratori, non rinnovabile","wrong2":"è anche garantita dalla durata lunga del mandato, pari a 15 anni, degli amministratori, non rinnovabile","wrong3":"è anche garantita dalla durata lunga del mandato, pari a 5 anni, degli amministratori, non rinnovabile"},{"id":356,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"La principale funzione della Banca d'Italia è:","correct":"il potere di emettere carta moneta e di stabilire il tasso ufficiale di sconto","wrong1":"controllare le singole operazioni bancarie italiane","wrong2":"dare l'assenso all'acquisto di nuove aziende private da parte dei pubblici poteri","wrong3":"controllare l'operato delle Assicurazioni italiane"},{"id":357,"paragraph":"Diritto amministrativo - Le autorità amministrative indipendenti","question":"L'Autorità per le garanzie nelle telecomunicazioni:","correct":"è stata istituita con legge 249/1997 al fine anche di vigilare affinché il sistema dell'editoria e radiotelevisivo sia informato ai principi di pluralismo, obiettività, completezza e imparzialità dell'informazione","wrong1":"è stata istituita con legge 241/1990 al fine anche di vigilare affinché il sistema dell'editoria e radiotelevisivo sia informato ai principi di pluralismo, obiettività, completezza e imparzialità dell'informazione","wrong2":"è stata istituita con legge 241/1990 al fine anche di vigilare affinché il sistema radiotelevisivo rispetti i principi solo di pluralismo","wrong3":"è stata istituita con legge 249/1997 e soppressa nel 2020"},{"id":358,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"L'organizzazione amministrativa ha necessità di utilizzare strumenti di raccordo. È necessario ricorrere al raccordo poiché:","correct":"il ricorso al criterio della competenza spesso non riesce a risolvere il coordinamento fra le attività delle varie amministrazioni","wrong1":"il ricorso al criterio della competenza è a lui collegato","wrong2":"le Pubbliche Amministrazioni per coordinarsi utilizzano lo strumento degli articoli di stampa","wrong3":"non si trovano gli accordi tra enti sovracomunali diversi"},{"id":359,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"La Conferenza dei Servizi:","correct":"è uno strumento di raccordo","wrong1":"è una Conferenza pubblica dove i Sindaci espongono alla collettività il loro programma","wrong2":"è una Conferenza pubblica dove i Sindaci ed i Presidenti di Regione espongono alla collettività il loro programma","wrong3":"è una Conferenza pubblica dove il Governo espone alla collettività il suo programma"},{"id":360,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"L'accordo fra enti pubblici è utile per:","correct":"agevolare grandi iniziative imprenditoriali","wrong1":"agevolare i partiti di governo","wrong2":"agevolare il Sindaco del comune più grande","wrong3":"agevolare le Comunità Montane"},{"id":361,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"La legge n. 662/1996:","correct":"disciplina varie tipologie di accordi","wrong1":"disciplina la Conferenza dei Servizi","wrong2":"disciplina la S.C.I.A.","wrong3":"disciplina il patto di stabilità"},{"id":362,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"Nella materia dei beni culturali:","correct":"la tutela è riservata allo Stato, alla valorizzazione dell'ambiente concorrono le regioni, se sono proprietari anche gli enti locali hanno una loro competenza","wrong1":"la tutela è riservata solo allo Stato","wrong2":"la tutela è riservata solo al comune","wrong3":"la tutela è riservata solo alla regione"},{"id":363,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"I conflitti di competenza fra Stato, Regioni ed enti locali:","correct":"si risolvono con gli accordi e/o con la conferenza Stato/Regioni","wrong1":"si risolvono con le dimissioni del Sindaco","wrong2":"si risolvono solo all'interno della Conferenza Stato/Regioni, istituita appositamente","wrong3":"si risolvono con un referendum popolare"},{"id":364,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"La gerarchia è una relazione:","correct":"interna dell'ente","wrong1":"esterna dell'ente ma non visibile","wrong2":"interna dell'ente ma visibile all'esterno","wrong3":"esterna dell'ente"},{"id":365,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"La direzione:","correct":"Consiste in una relazione interna ad uno stesso apparato: come quella fra organo politico e dirigenza burocratica","wrong1":"è l'Ufficio del Direttore","wrong2":"Rappresenta il punto d'ingresso di un Ente","wrong3":"è il rapporto che intercorre tra Direttore ed ente"},{"id":366,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"Il controllo di legittimità:","correct":"può anche essere preventivo","wrong1":"è successivo alla promulgazione","wrong2":"è sempre precedente all'emanazione di un atto","wrong3":"è successivo all'emanazione di un atto"},{"id":367,"paragraph":"Diritto amministrativo - Il coordinamento fra amministrazioni ed il sistema dei controlli","question":"Negli ultimi anni ha cominciato ad assumere importanza il controllo che i cittadini possono svolgere sull'operato delle amministrazione pubbliche. L'art. 1 del D.lgs.33/2013 ha sancito:","correct":"il principio dell'accessibilità totale delle informazioni concernenti l'organizzazione e le attività delle pubbliche amministrazioni che hanno l'obbligo di pubblicare sui siti istituzionali documenti e informazioni concernenti l'organizzazione dell'attività","wrong1":"il controllo dei cittadini sull'operato di un ente attraverso il referendum abrogativo di quell'ente","wrong2":"il controllo dei cittadini sull'operato di un ente attraverso la richiesta di elezioni anticipate","wrong3":"il principio dell'accessibilità totale delle informazioni concernenti l'organizzazione e le attività delle pubbliche amministrazioni che però non hanno l'obbligo di pubblicare sui siti istituzionali documenti e informazioni concernenti l'organizzazione dell'attività"},{"id":368,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"Le retribuzioni dei dipendenti:","correct":"devono essere sottoposte al vaglio della Corte dei Conti","wrong1":"devono essere sottoposte al vaglio del Consiglio dei Ministri","wrong2":"devono essere sottoposte al vaglio della Presidenza della Repubblica","wrong3":"devono essere sottoposte al vaglio solo della CGIL"},{"id":369,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"Il reclutamento di dipendenti pubblici avviene:","correct":"mediante concorso pubblico","wrong1":"mediante chiamata diretta","wrong2":"mediante invio della candidatura via pec","wrong3":"mediante selezione privata"},{"id":370,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"La giurisdizione in una procedura concorsuale è:","correct":"del giudice amministrativo in quanto la procedura è pubblicistica","wrong1":"del giudice ordinario in quanto la procedura è privata","wrong2":"del giudice ordinario anche se la procedura è pubblicistica","wrong3":"del giudice contabile in quanto la procedura è pubblicistica e comporta oneri per la pubblica amministrazione"},{"id":371,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"Per snellire le modalità di reclutamento del personale pubblico dal 2022 sono previsti anche:","correct":"l'utilizzo di strumenti informatici e digitali","wrong1":"modi diversi per il reclutamento quale la chiamata diretta","wrong2":"modalità di reclutamento diverse quale la candidatura che avviene mediante l'invio di una raccomandata con ricevuta di ritorno","wrong3":"l'utilizzo delle segnalazioni da inviare mediante raccomandata con ricevuta di ritorno"},{"id":372,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"I rapporti di lavoro dei dipendenti pubblici ora sono disciplinati:","correct":"dal codice civile e dalle leggi civili","wrong1":"dal codice sul processo amministrativo","wrong2":"dalla legge sul procedimento amministrativo","wrong3":"dalla legge che determina l'attività, l'ordinamento e la potestà regolamentare del Governo della Repubblica Italiana"},{"id":373,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"In caso di svolgimento di mansioni superiori il dipendente pubblico:","correct":"ha solo diritto al trattamento economico previsto per la qualifica superiore, ma non ha diritto all'inquadramento nella qualifica superiore","wrong1":"ha diritto all'inquadramento nella qualifica superiore","wrong2":"ha solo diritto al trattamento economico previsto per la qualifica superiore ed al diritto all'inquadramento nella qualifica superiore","wrong3":"non ha alcun diritto"},{"id":374,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"Il licenziamento disciplinare è previsto per:","correct":"falsa attestazione della presenza in servizio","wrong1":"vera attestazione della presenza in servizio","wrong2":"valutazione della performance positiva","wrong3":"valutazione della performance negativa"},{"id":375,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"I dirigenti sono divisi:","correct":"in due fasce, prima e seconda","wrong1":"in un una fascia unica, dei dirigenti","wrong2":"in tre fasce, prima, seconda e terza fascia","wrong3":"in quattro fasce, prima, seconda, terza e quarta"},{"id":376,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"Tra gli obblighi dei dirigenti vi sono:","correct":"osservare le direttive dell'organo politico e raggiungere gli obiettivi prefissati","wrong1":"seguire le indicazioni delle sigle sindacali","wrong2":"osservare soltanto le indicazioni della magistratura tributaria","wrong3":"raggiungere il livello superiore entro tre anni"},{"id":377,"paragraph":"Diritto amministrativo - Il personale delle Pubbliche Amministrazioni","question":"La responsabilità dirigenziale viene sanzionata:","correct":"in due modi, ossia il mancato rinnovo dell'incarico dirigenziale ed il recesso dell'amministrazione dal rapporto di lavoro","wrong1":"in un modo soltanto, ossia con il trasferimento del dirigente in altro Ufficio","wrong2":"in due modi, ossia con il trasferimento temporaneo del dirigente in altro Ufficio e con l'obbligo di ripetere il concorso pubblico","wrong3":"in due modi, ossia con il trasferimento temporaneo del dirigente in altro Ufficio e con l'obbligo di ripetere il concorso pubblico entro 12 mesi"},{"id":378,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"Ogni amministrazione per lo svolgimento dei suoi compiti si avvale:","correct":"delle risorse umane e delle risorse materiali a loro volta suddivisi in beni propri e beni sui quali la pubblica amministrazione vanta un titolo giuridico diverso dalla proprietà","wrong1":"solo delle risorse umane","wrong2":"delle risorse umane e delle risorse economiche che arrivano dalle offerte dei cittadini","wrong3":"delle risorse economiche che arrivano dalle offerte dei fedeli per i cammini religiosi"},{"id":379,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"I beni pubblici della pubblica amministrazione:","correct":"Hanno come tratto comune il fatto di essere destinati al pubblico servizio","wrong1":"Hanno come tratto comune il fatto di essere destinati al servizio privato","wrong2":"Hanno come tratto comune il fatto di essere destinati al servizio personale del proprio custode","wrong3":"non sono inalienabili"},{"id":380,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"I beni che possono appartenere solo allo Stato, quali lidi, spiagge, rade, fiumi, torrenti, laghi ed acque pubbliche:","correct":"sono i beni demaniali","wrong1":"sono soltanto i beni che possono essere ceduti ai privati","wrong2":"sono i beni disponibili","wrong3":"sono i beni privati"},{"id":381,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"Negli anni novanta, a seguito della trasformazione di Enti pubblici in società per azioni, gli enti privati costituiti hanno perseguito:","correct":"come scopo la gestione e la vendita di tali beni","wrong1":"come scopo l'inalienabilità di tali beni","wrong2":"come scopo solo la vendita di tali beni","wrong3":"come scopo solo la gestione di tali beni, cercando di far diminuirne il valore"},{"id":382,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"A seguito della trasformazione di Enti pubblici in società per azioni, il trasferimento dei beni al nuovo ente:","correct":"ha determinato come effetto la perdita della demanialità","wrong1":"ha determinato come effetto l'acquisizione della demanialità","wrong2":"ha determinato il bilancio negativo di tali enti","wrong3":"ha determinato il depauperamento sostanziale del patrimonio pubblico"},{"id":383,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"La Costituzione fa distinzione fra entrate:","correct":"patrimoniali e tributarie","wrong1":"patrimoniali e giuridiche","wrong2":"tributarie e giuridiche","wrong3":"di cassa e di spesa"},{"id":384,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"Per le spese pubbliche:","correct":"non esiste una disciplina costituzionale","wrong1":"esiste una disciplina costituzionale","wrong2":"esiste una disciplina solo regionale","wrong3":"esiste una disciplina solo locale"},{"id":385,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"Il patto di stabilità e crescita ha imposto:","correct":"l'equilibrio della finanza pubblica degli Stati membri che rappresenta una condizione in grado di garantire la crescita economica","wrong1":"che le Regioni non hanno potere di spesa senza l'avallo dell'Assemblea dei Sindaci","wrong2":"che le Province depotenziate non hanno potere di spesa senza l'avallo dell'Assemblea dei Sindaci","wrong3":"l'equilibio della finanza pubblica solo per i comuni degli Stati membri che rappresenta una condizione in grado di garantire la crescita economica"},{"id":386,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"Per attuare il fiscal compat la legge cost. 1/2012 ha modificato:","correct":"gli art. 81, 97 e 119 cost","wrong1":"la legge sul procedimento amministrativo","wrong2":"gli art. 1,2 e 3 cost","wrong3":"la legge Delrio, la n. 56/2014"},{"id":387,"paragraph":"Diritto amministrativo - I beni pubblici e le procedure di spesa","question":"La procedura di spesa si suddivide in:","correct":"quattro fasi: impegno, liquidazione, ordinazione e pagamento","wrong1":"tre fasi: ordinazione, liquidazione e pagamento","wrong2":"due fasi: impegno e pagamento","wrong3":"tre fasi: impegno, liquidazione e pagamento"},{"id":388,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"La dottrina amministrativistica, soprattutto francese e italiana, distingue:","correct":"l'attività giuridica dall'attività sociale dello Stato e degli enti pubblici","wrong1":"le attività autoritative impositive da quelle autoritative consensuali","wrong2":"i servizi pubblici locali da quelli territoriali","wrong3":"i servizi pubblici essenziali da quelli soltanto eventuali"},{"id":389,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"Quando la Pubblica Amministrazione eroga un servizio:","correct":"non esercita, di norma, un potere autoritativo","wrong1":"esercita un potere autoritativo","wrong2":"non esercita un potere autoritativo, in quanto la Pubblica Amministrazione in nessun caso può esercitarlo","wrong3":"chiede al cittadino, senza nessun caso di esenzione, un corrispettivo in denaro"},{"id":390,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"La definizione che la dottrina amministrativistica francese ha fornito di servizio pubblico è:","correct":"ogni attività la cui esplicazione deve essere assicurata, regolata e controllata dai governanti in quanto indispensabile alla realizzazione e allo sviluppo dell'interdipendenza sociale e che è di natura tale da non poter essere completamente realizzata se non con l'intervento della forza di governo","wrong1":"ogni attività la cui esplicazione deve essere assicurata, regolata e controllata dai governanti in quanto indispensabile alla realizzazione e allo sviluppo sociale e che è di natura tale da poter essere completamente realizzata anche da un'impresa privato","wrong2":"quelle particolarissime attività la cui esplicazione deve essere erogata, soltanto in alcuni casi, dai governanti","wrong3":"ogni esercizio di pubblico potere indispensabile alla realizzazione e allo sviluppo economico e che è di natura tale da dover essere completamente realizzato con l'intervento della forza di governo"},{"id":391,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"Municipalizzare un servizio vuol dire:","correct":"che il Comune si riserva di produrre quel servizio, o in forma di concessione ad un'impresa o direttamente","wrong1":"che lo deve erogare la polizia municiaple","wrong2":"che il servizio è erogato all'interno del Municipio","wrong3":"privatizzare un servizio che prima era gestito a livello regionale"},{"id":392,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"La Costituzione indica alcuni \"servizi specifici\" senza però definirli \"servizi\" e, tra questi, vi è:","correct":"la previdenza sociale","wrong1":"la facoltà di emanare leggi","wrong2":"la possibilità di privatizzare un servizio","wrong3":"il Servizio Sanitario Nazionale"},{"id":393,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"Un servizio può essere definito \"pubblico\":","correct":"anche se è gestito da un'impresa privata","wrong1":"soltanto se è gestito dallo Stato o da un Ente","wrong2":"solo quando è gratuito","wrong3":"se è un servizio gratuito per tutti i cittadini, anche stranieri"},{"id":394,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"Il modello dell'impresa:","correct":"è applicabile soltanto ad alcuni servizi sociali, per altri è escluso per definizione","wrong1":"è applicabile a tutti i servizi","wrong2":"non è mai applicabile ai servizi","wrong3":"è imposto per alcuni servizi"},{"id":395,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"A livello locale sono state sperimentate essenzialmente due forme di gestione del servizio:","correct":"la gestione indiretta a mezzo di appalto e la gestione a mezzo di azienda municipalizzata","wrong1":"la gestione indiretta a mezzo di impresa pubblica locale e la gestione a mezzo di azienda municipalizzata","wrong2":"la gestione indiretta a mezzo di appalto e la gestione a mezzo di Amministrazione periferica","wrong3":"la gestione appaltata e la gestione non appaltata"},{"id":396,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"Vi sono due elementi che qualificano un servizio come \"pubblico\":","correct":"il dovere per l'Amministrazione di esplicare l'attività e l'impossibilità che un soggetto diverso dal potere pubblico possa erogare quel servizio","wrong1":"la spesa di denaro pubblico e l'erogazione attraverso un Ente","wrong2":"l'accessibilità a tutti i cittadini (anche stranieri) e la gratuità","wrong3":"la presenza di cariche politiche all'interno dell'impresa e la spesa di denaro pubblico"},{"id":397,"paragraph":"Diritto amministrativo - Servizi pubblici: profili generali","question":"I servizi pubblici che non sono ritenuti essenziali (art. 43 Costituzione):","correct":"non sono suscettibili di nazionalizzazione, quindi non possono essere riservati ai pubblici poteri","wrong1":"sono suscettibili di nazionalizzazione, quindi possono essere riservati ai pubblici poteri","wrong2":"sono riservati allo Stato","wrong3":"sono riservati ai Comuni"},{"id":398,"paragraph":"Diritto amministrativo - Servizi pubblici locali e servizi sociali","question":"In seguito alla sent. 195/2012 della Corte costituzionale:","correct":"la disciplina dei servizi pubblici locali è rimasta affidata alla disciplina del diritto U.E.","wrong1":"la materia dei servizi pubblici locali è rimasta priva di disciplina legislativa","wrong2":"ha continuato a trovare applicazione il d.l. n. 138/2011","wrong3":"la materia è rimasta regolata dalla Costituzione"},{"id":399,"paragraph":"Diritto amministrativo - Servizi pubblici locali e servizi sociali","question":"Il d.lgs. n. 201 del 2022:","correct":"reca il riordino della disciplina dei servizi pubblici locali, introducendo disposizioni di carattere generale che si integrano con le normative di settore","wrong1":"ha profondamente innovato la disciplina dei servizi pubblici locali","wrong2":"reca il riordino della disciplina dei servizi sociali","wrong3":"introduce, per la prima volta, il principio di sussidiarietà"},{"id":400,"paragraph":"Diritto amministrativo - Servizi pubblici locali e servizi sociali","question":"Gli enti del terzo settore:","correct":"sono enti che, previa iscrizione nel registro unico nazionale, esercitano attività di interesse generale senza scopo di lucro","wrong1":"sono enti che esercitano attività di impresa","wrong2":"sono enti che esercitano attività di interesse generale con scopo di lucro","wrong3":"sono enti iscritti nel Registro delle Imprese"},{"id":401,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Le amministrazioni pubbliche possono stipulare:","correct":"tutti i contratti, anche atipici, finalizzati al soddisfacimento delle proprie finalità istituzionali","wrong1":"i soli contratti previsti dalla legge, non disponendo di autonomia negoziale","wrong2":"contratti con prestazioni sinallagmatiche e di durata, insuscettibili di revisione","wrong3":"tutti i contratti previsti dall'ordinamento, purché a titolo oneroso"},{"id":402,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Nello scegliere il proprio contraente, le amministrazioni:","correct":"devono attenersi a criteri oggettivi, finalizzati ad assicurare il buon andamento e l'imparzialità","wrong1":"hanno la stessa libertà dei soggetti privati","wrong2":"devono sempre preferire il contraente che propone il prezzo più basso","wrong3":"devono favorire le grandi imprese, in quanto più affidabili"},{"id":403,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Il principio del risultato:","correct":"condiziona l'esercizio della discrezionalità dell'amministrazione e costituisce criterio interpretativo prioritario delle regole del codice dei contratti pubblici","wrong1":"si riferisce alla dimensione processuale, impendendo al giudice l'adozione delle decisioni più sfavorevoli per l'interesse pubblico","wrong2":"è un corollario del principio di imparzialità","wrong3":"è sempre subordinato al principio della concorrenza, che rappresenta la fondamentale ratio della disciplina dell'evidenza pubblica"},{"id":404,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"La trasparenza:","correct":"tende ad assicurare la massima semplicità e celerità nella corretta applicazione delle regole del codice e ne assicura la piena verificabilità","wrong1":"è strumentale ad assicurare il favor partecipationis","wrong2":"tende a facilitare la verificabilità della decisione dell'amministrazione","wrong3":"tende ad assicurare la rapidità della decisione dell'amministrazione"},{"id":405,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Il principio della fiducia:","correct":"serve a responsabilizzare i funzionari, contrastando la c.d. \"paura della firma\"","wrong1":"è recessivo rispetto all'esigenza di garantire l'efficienza dell'azione amministrativa","wrong2":"non si applica alle procedure sottoposte alla vigilanza dell'Autorità nazionale anticorruzione","wrong3":"esonera l'amministrazione dal verificare la veridicità delle dichiarazioni rese dagli operatori economici in sede di gara"},{"id":406,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Non costituisce colpa grave ai fini della responsabilità dei funzionari per gli atti da loro compiuti nell'ambito di una procedura di evidenza pubblica:","correct":"la violazione di norme di diritto che sia stata determinata dall'adesione a orientamenti giurisprudenziali prevalenti o a pareri di autorità competenti","wrong1":"la violazione degli autovincoli amministrativi, salvo che ne sia derivata l'esclusione del concorrente","wrong2":"l'introduzione nel bando di gara di cause di esclusione non previste dal codice dei contratti pubblici, se non risulta che sono discriminatorie","wrong3":"la palese violazione delle regole di prudenza e di perizia"},{"id":407,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"La tutela dell'affidamento:","correct":"presuppone che il concorrente aggiudicatario non potesse agevolmente rilevare, in base alla diligenza professionale da lui esigibile, l'illegittimità del provvedimento di aggiudicazione annullato","wrong1":"sussiste in tutti i casi in cui l'operatore economico sia stato danneggiato da un atto illegittimo dell'amministrazione","wrong2":"sussiste nei confronti del solo aggiudicatario che abbia subito l'annullamento dell'aggiudicazione","wrong3":"sussiste nei soli confronti del concorrente illegittimamente escluso"},{"id":408,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Per il principio della tassatività delle cause di esclusione:","correct":"le cause di esclusione dalle procedure di gara sono solo quelle previste dal codice dei contratti pubblici, senza possibilità per l'amministrazione di introdurne di ulteriori","wrong1":"l'amministrazione è tenuta a stabilire nel bando o nell'avviso indittivo della gara le cause di esclusione dei concorrenti, senza possibilità di integrarle in un secondo momento","wrong2":"sanziona con l'annullabilità le cause di esclusione atipiche, cioè che non hanno una base normativa primaria o secondaria","wrong3":"rende illegittima un'esclusione che, pur essendo prevista dalla legge, non è stata recepita espressamente dal bando o dall'avviso indittivo della gara"},{"id":409,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Il principio di auto-organizzazione:","correct":"prevede che l'amministrazione possa, motivando in ordine alle ragioni di convenienza, optare per la produzione in proprio di beni e di servizi, anche mediante affidamento in favore di società in house","wrong1":"prevede che l'amministrazione possa ricorrere alla propria stessa organizzazione per la produzione di beni e servizi, solo quando non sia possibile reperirli sul mercato","wrong2":"prevede che l'amministrazione possa affidare direttamente ad altre amministrazioni la produzione di beni e servizi","wrong3":"prevede che l'amministrazione possa sempre recedere da un contratto, quando risulti più conveniente autoprodurre i beni e i servizi che ne formavano oggetto"},{"id":410,"paragraph":"Diritto amministrativo - I principi generali del Codice dei Contratti pubblici","question":"Il principio di conservazione dell'equilibrio contrattuale:","correct":"trova applicazione alla generalità dei contratti pubblici, consentendone la rinegoziazione al verificarsi di circostanze straordinarie e imprevedibili che abbiano modificato in misura rilevante l'equilibrio originario del rapporto","wrong1":"trova applicazione ai soli contratti non aleatori, tra cui la concessione di servizi","wrong2":"non si applica, di regola, agli appalti di lavori, salvo che non si verifichi un aumento medio del costo dei materiali, per come risultante dai dati Istat, superiore al 30%","wrong3":"opera a tutela delle piccole e medie imprese, non potendo trovare applicazione per appalti superiori alla soglia comunitaria, in quanto si presume che il contraente abbia gli strumenti per far fronte alle alterazioni determinate da circostanze imprevedibili al momento della stipula"},{"id":411,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Il partenariato pubblico -privato:","correct":"è un genus rispetto a figure contrattuali quali la concessione, la locazione finanziaria, il contratto di disponibilità","wrong1":"è una species rispetto alla più ampia categoria delle concessioni","wrong2":"è un accordo procedimentale","wrong3":"è un contratto di concessione di servizi"},{"id":412,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Il partenariato pubblico - privato si distingue:","correct":"in contrattuale e istituzionale","wrong1":"in pubblico o privato","wrong2":"in qualificato o non qualificato","wrong3":"con negoziazione o senza negoziazione"},{"id":413,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"La concessione si differenzia dall'appalto:","correct":"perché vi è una traslazione in capo al concessionario del rischio operativo","wrong1":"perché è onerosa","wrong2":"perché non vi è una traslazione in capo al concessionario del rischio operativo","wrong3":"perchè è stipulato per iscritto a pena di nullità"},{"id":414,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"La durata della concessione:","correct":"è commisurata al valore della concessione","wrong1":"non può essere in alcun caso prorogata","wrong2":"può essere illimitata e indeterminata in ipotesi eccezionali","wrong3":"deve essere superiore al periodo di tempo necessario al recupero degli investimenti"},{"id":415,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"La finanza di progetto:","correct":"è un capitolo \"interno\" alla concessione","wrong1":"può essere solo ad iniziativa pubblica","wrong2":"può essere sia ad iniziativa privata che pubblica","wrong3":"è un raggruppamento temporaneo di imprese"},{"id":416,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"La locazione finanziaria:","correct":"è una species del partenariato pubblico privato","wrong1":"è un genus rispetto al partenariato pubblico - privato","wrong2":"è un genus rispetto alle concessioni","wrong3":"è una species del contratto di disponibilità"},{"id":417,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contratto di disponibilità:","correct":"consiste nella \"messa a disposizione\" di un'opera - che, per l'intera durata del contratto, resta di proprietà privata - a fronte di un corrispettivo da parte dell'ente pubblico","wrong1":"consiste nella messa a disposizione di un'opera - che, per l'intera durata del contratto, resta di proprietà privata - a fronte di un corrispettivo da parte del privato","wrong2":"consiste in un contratto autonomo caratterizzato dal coinvolgimento della società di leasing","wrong3":"consiste in un'operazione di finanziamento diretta a sostenere un progetto capace di generre flussi di cassa sufficienti a remunerare l'investimento"},{"id":418,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contratto di disponibilità:","correct":"non ha trovato spesso applicazione perchè le stesse esigenze si possono realizzare con la concessione","wrong1":"è stato introdotto per la prima volta nel Codice Appalti del 2023","wrong2":"è la forma di partenariato pubblico - privata più applicata","wrong3":"non ha trovato spesso applicazione perché le stesse esigenze si possono realizzare con la finanza di progetto"},{"id":419,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contraente generale:","correct":"è una species dei contratti a prestazione complessa aventi ad oggetto servizi globali","wrong1":"è il genus del global service","wrong2":"è il genus delle concessioni e del partenariato pubblico - privato","wrong3":"è il genus dei contratti a prestazione complessa aventi ad oggetto servizi globali"},{"id":420,"paragraph":"Diritto amministrativo - Contratti pubblici: tipologie contrattuali e soglie","question":"Ai contratti sopra soglia:","correct":"si applicano le norme contenute nelle direttive comunitarie recepite a livello nazionale dal Codice dei contratti pubblici","wrong1":"non si applica la L. n. 241 del 1990","wrong2":"non si applicano le norme contenute nelle direttive comunitarie recepite a livello nazionale dal Codice dei contratti pubblici","wrong3":"non si applicano le disposizioni del Codice appalti"},{"id":421,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"Le amministrazioni aggiudicatrici si distinguono in:","correct":"amministrazioni centrali; amministrazioni subcentrali; organismo di diritto pubblico","wrong1":"amministrazioni centrali; enti aggiudicatori; joint venture","wrong2":"amministrazioni centrali; enti aggiudicatori; imprese pubbliche","wrong3":"amministrazioni centrali; enti aggiudicatori; stazioni appaltanti qualificate"},{"id":422,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"La nozione di organismo di diritto pubblico:","correct":"è una definizione funzionale i cui parametri sono i tre requisiti cumulativamente previsti dalla legge","wrong1":"comprende tutti i soggetti che esercitano un'attività economica, con la sola eccezione degli enti pubblici economici","wrong2":"va intesa in senso ampio, escludendo i soli soggetti che non perseguono un fine di lucro","wrong3":"va intesa in senso ampio, comprenendo tutti i soggetti che, indipendentemente dalla forma che assumono, sono abilitati alla realizzazione di lavori e alla fornitura di beni e servizi sul mercato"},{"id":423,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"Non è un requisito per la qualificazione di organismo di diritto pubblico:","correct":"il vincolo di scopo","wrong1":"la capacità giuridica","wrong2":"la circostanza che sia istituito per soddisfare esigenze di interesse generale, attraverso lo svolgimento di un'attività priva di carattere industriale o commerciale","wrong3":"la sottoposizione ad una influenza pubblica"},{"id":424,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"Il sistema di qualificazione delle stazioni appaltanti:","correct":"ha natura \"aperta\"","wrong1":"non è disciplinato né dal codice appalti né dagli allegati al Codice","wrong2":"è a numero chiuso","wrong3":"è gestito da Consip"},{"id":425,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"Tutte le stazioni appaltanti possono:","correct":"procedere direttamente e autonomamente all'affidamento di lavori d'importo pari o inferiore a 500.000 euro","wrong1":"procedere direttamente e autonomamente all'affidamento di lavorid'importo pari o inferiore a 1.000.00 euro","wrong2":"procedere direttamente all'acquisizione di forniture e servizi di importo superiore alle soglie previste per gli affidamenti diretti","wrong3":"procedere direttamente e autonomamente all'affidamento di lavorid'importo pari o inferiore a 750.000 euro"},{"id":426,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"L'Anac:","correct":"è l'autorità nazionale preposta a vigilare i contratti pubblici contrastando e prevenendo la corruzione","wrong1":"è l'autorià preposta a garantire la libera concorrenza del mercato","wrong2":"è l'autorità preposta alla vigilanza degli intermediari finanziari, sui mercati e sugli emittenti quotati","wrong3":"è l'autorità preposta a garantirela vigilanza sulle attività di trattamento dei dati personali"},{"id":427,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"L'Anac è in via esclusiva titolare:","correct":"della Banca dati nazionale dei contratti pubblici","wrong1":"del Repertorio nazionale dei dati territoriali","wrong2":"dell'indice delle Publiche Amministrazioni","wrong3":"del registro delle imprese"},{"id":428,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"All'Anac spettano funzioni:","correct":"di regolazione; di ispezione; di vigilanza; di raccomandazione; sanzionatorie; di amministrazione attiva","wrong1":"di regolazione; di ispezione; di vigilanza; di raccomandazione; sanzionatorie; di amministrazione attiva; di aggiudicazione","wrong2":"esclusivamente di vigilanza sui contratti pubblici","wrong3":"esclusivamente di vigilanza e regolazione sui contratti pubblici"},{"id":429,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"Il RUP:","correct":"il RUP svolge tutti i compiti relativi alle procedure di programmazione, progettazione, affidamento ed esecuzione previste dal Codice, non specificatamente attribuiti ad altri organi o soggetti","wrong1":"è un soggetto nominato tra i consiglieri di stato","wrong2":"non è responsabile di tutto l'intervento pubblico, ma solo di uno o più procedimenti","wrong3":"cessa le sue funzioni nella fase esecutiva della vicenda contrattuale"},{"id":430,"paragraph":"Diritto amministrativo - Contratti pubblici: ambito di applicazione soggettivo e altri soggetti","question":"La figura del direttore dell'esecuzione:","correct":"è soggetto diverso dal RUP in caso di interventi particolarmente complessi sotto il profilo tecnologico","wrong1":"coincide sempre con quella del RUP","wrong2":"è un soggetto nominato tra i consiglieri di stato","wrong3":"svolge tutti i compiti relativi alle procedure di programmazione, progettazione, affidamento previste dal Codice"},{"id":431,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"Tra gli obiettivi principali delle teorie manageriali, vi è quello di:","correct":"modernizzare e adattare le pratiche burocratiche tradizionali al contesto in evoluzione della pubblica amministrazione","wrong1":"massimizzare i profitti della PA","wrong2":"promuovere la competizione tra gli enti pubblici","wrong3":"mantenere lo status quo e resistere al cambiamento organizzativo"},{"id":432,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"Le teorie manageriali contribuiscono a:","correct":"incoraggiare il coinvolgimento e la responsabilizzazione dei dipendenti pubblici","wrong1":"limitare la trasparenza delle operazioni governative per aumentare l'efficienza","wrong2":"ridurre la collaborazione inter-agenzia per semplificare la catena di comando","wrong3":"centralizzare il processo decisionale nelle mani di un ristretto gruppo di dirigenti"},{"id":433,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"La Progressive Public Administration si sviluppa a partire da:","correct":"gli anni '70","wrong1":"gli anni '20","wrong2":"gli anni '90","wrong3":"gli anni '50"},{"id":434,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"I principi fondamentali del Progressive Public Administration includono:","correct":"la partecipazione cittadina attiva, la trasparenza e l'accountability","wrong1":"la partecipazione cittadina attiva, la resilienza e la flessibilità","wrong2":"l'innovazione e la digitalizzazione","wrong3":"l'accountability e la flessibiiltà"},{"id":435,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"L'accountability si riferisce a:","correct":"la responsabilità che gli attori pubblici devono avere verso i cittadini e le istituzioni","wrong1":"l'autorità esclusiva degli attori pubblici di determinare le priorità politiche senza necessità di giustificazione","wrong2":"l'abilità di agire indipendentemente senza dover rendere conto delle decisioni prese e delle risorse utilizzate","wrong3":"la libertà degli attori pubblici di modificare le leggi e regolamenti senza coinvolgimento o supervisione esterna"},{"id":436,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"Una delle principali critiche alla PPA riguarda:","correct":"la sua tendenza a focalizzarsi esclusivamente sui risultati, trascurando l'importanza dei processi e dei valori pubblici","wrong1":"la sua tendenza a focalizzarsi esclusivamente sui processi, mai sui risultati","wrong2":"la sua tendenza a focalizzarsi esclusivamente sui valori pubblici","wrong3":"la sua tendenza a focalizzarsi esclusivamente sul processo, trascurando i valori pubblici"},{"id":437,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"L' NPM è criticato perché il suo approccio orientato al mercato può contribuire a:","correct":"un'eccessiva commercializzazione dei servizi pubblici, mettendo a rischio l'accesso universale e la qualità dei servizi","wrong1":"un incremento della centralizzazione decisionale, diminuendo l'autonomia delle singole entità governative","wrong2":"un rafforzamento delle strutture burocratiche tradizionali, riducendo l'innovazione nel settore pubblico","wrong3":"una maggiore dipendenza dalle decisioni politiche a breve termine, influenzando negativamente la pianificazione e le politiche a lungo termine"},{"id":438,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"L'obiettivo della NPG è quello di:","correct":"centralizzare le decisioni amministrative per garantire una maggiore efficienza operativa e una migliore allocuzione delle risorse","wrong1":"intensificare il controllo governativo sulle economie locali per assicurare una distribuzione uniforme delle risorse","wrong2":"ridurre il coinvolgimento diretto dei cittadini nelle fasi di pianificazione per accelerare il processo decisionale","wrong3":"promuovere la partecipazione dei cittadini e delle organizzazioni della società civile nella definizione delle politiche pubbliche e nella loro implementazione"},{"id":439,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"Uno dei principali punti deboli della NPG riguarda:","correct":"la scarsa attenzione alla dimensione democratica e alla partecipazione dei cittadini","wrong1":"la centralizzazione eccessiva del potere","wrong2":"l'incremento dei costi operativi","wrong3":"una valutazione troppo rigorosa e sistematica degli impatti delle politiche pubbliche"},{"id":440,"paragraph":"La digitalizzazione della PA - Le teorie manageriali della PA","question":"Indicare quale delle seguenti affermazioni è vera:","correct":"mentre il NPM si basa su principi di managerialismo e competizione, la NPG adotta approcci più inclusivi e orientati alla governance condivisa","wrong1":"mentre la NPG si basa su principi di managerialismo e competizione, il NPM adotta approcci più inclusivi e orientati alla governance condivisa.","wrong2":"sia NPM che NPG si basano su principi di managerialismo e competizione","wrong3":"sia NPM che NPG adottano approcci inclusivi e orientati alla governance condivisa"},{"id":441,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"Indicare la risposta corretta:","correct":"Le IPN sono un sottoinsieme del SPA","wrong1":"le AP sono un sottoinsieme delle IPL","wrong2":"le AP sono un sottoinsieme delle IPN","wrong3":"Le IPN sono un sottoinsieme delle AP"},{"id":442,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"Le IPN e le IPL :","correct":"hanno diverso ambito territoriale di controllo e operatività","wrong1":"hanno lo stesso ambito territoriale di controllo e operatività","wrong2":"hanno lo stesso ambito territoriale di controllo, ma diverso ambito territoriale di operatività","wrong3":"hanno lo stesso ambito territoriale di operatività, ma diverso ambito territoriale di controllo"},{"id":443,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"Nelle IPN:","correct":"lo Stato detiene una partecipazione di minoranza","wrong1":"lo Stato detiene una partecipazione di maggioranza","wrong2":"lo Stato detiene tutto il Capitale","wrong3":"lo Stato non possiede partecipazioni"},{"id":444,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"Un esempio di IPL è:","correct":"ATM","wrong1":"ENI","wrong2":"una qualsiasi entità localo, come comuni e province","wrong3":"FERROVIE DELLO STATO"},{"id":445,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"La nozione giuridica di AP che si trova nel decreto legislativo 30 marzo 2001, n. 165 sottolinea:","correct":"l'eterogeneità degli organismi in termini di funzioni svolte","wrong1":"l'eterogenità degli organismi in termini di distribuzione territoriale","wrong2":"l'omogeneità degli organismi in termini di funzioni svolte","wrong3":"l'omogeneità degli organismi in termini di distribuzione territoriale"},{"id":446,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"L'elemento che accomuna gli enti di AP risiede nella circostanza che sono tutti:","correct":"chiamati a svolgere funzioni di interesse generale","wrong1":"chiamati a svolgere le stesse funzioni","wrong2":"chiamati a svolgere le funzioni di tutela ambientale","wrong3":"chiamati a svolgere le funzioni di difesa territoriale"},{"id":447,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"Il sistema delle AP si classifica in:","correct":"4 livelli","wrong1":"2 livelli","wrong2":"3 livelli","wrong3":"5 livelli"},{"id":448,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"La Amministrazione Periferica è un ente di livello:","correct":"nazionale","wrong1":"locale","wrong2":"regionale","wrong3":"provinciale"},{"id":449,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"La Amministrazione Periferica:","correct":"non comprende la Presidenza del Consiglio dei Ministri, nè dei ministeri","wrong1":"comprende la Presidenza del Consiglio dei Ministri e dei ministeri","wrong2":"comprende i Ministeri, ma non la Presidenza dei Ministri","wrong3":"comprende la Presidenza del Consiglio dei Ministri, ma non i ministeri"},{"id":450,"paragraph":"La digitalizzazione della PA - Introduzione al sistema della PA in Italia","question":"La Amministrazione Centrale:","correct":"comprende la Presidenza del Consiglio dei Ministri e dei ministeri","wrong1":"comprende i Ministeri, ma non la Presidenza dei Ministri","wrong2":"comprende la Presidenza del Consiglio dei Ministri, ma non i ministeri","wrong3":"non comprende la Presidenza del Consiglio dei Ministri, nè dei ministeri"},{"id":451,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"La Legge n. 142 del 1990 ha agisce secondo tre linee:","correct":"ordinamento delle autonomie locali; decentramento amministrativo; introduzione di logiche di consultazione dei cittadini","wrong1":"regolarmento del sistema pensionistico nazionale; recentramento amministrativo; introduzione di logiche di consultazione dei cittadin","wrong2":"ordinamento delle autonomie locali; accentramento amministrativo; introduzione di logiche di consultazione dei cittadinI","wrong3":"ordinamento delle autonomie locali; decentramento amministrativo; privacy dei cittadini"},{"id":452,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"La Legge n. 241 del 1990 agisce secondo tre linee:","correct":"garantire ai cittadini l'accesso alle informazioni amministrative; Stabilire nuovi principi di buon andamento e imparzialità; Introdurre nuove regole in materia di procedimento amministrativo","wrong1":"garantire ai cittadini l'accesso alle informazioni amministrative; Stabilire principi di relatività amministrativa; Introdurre nuove regole in materia di procedimento amministrativo","wrong2":"ordinare le autonomie locali; Stabilire nuovi principi di buon andamento e imparzialità; Consolidare le vecchie procedure amministrative","wrong3":"garantire la protezione dei dati personali dei cittadini; introdurre nuove sanzioni per la violazione della privacy; limitare l'accesso alle informazioni amministrative."},{"id":453,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"La Legge n. 59 del 1997 ha introdotto riforme focalizzate su:","correct":"decentralizzazione, semplificazione e innovazione digitale","wrong1":"centralizzazione, semplificazione e innovazione digitale","wrong2":"decentralizzazione, complessificazione e innovazione digitale","wrong3":"decentralizzazione, semplificazione e resistenza al cambiamento"},{"id":454,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Secondo la Riforma Brunetta ogni amministrazione per la trasparenza e l'integrità deve elaborare:","correct":"un Programma triennale","wrong1":"un Programma trimestrale","wrong2":"un Programma annuale","wrong3":"un Programma quinquennale"},{"id":455,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Tra i principali diritti di cui dispone il cittadino in seguito all'entrata in vigore del CAD NON rientra:","correct":"diritto al portafoglio digitale","wrong1":"diritto alla propria identità digitale","wrong2":"diritto a comunicare e partecipare digitalmente","wrong3":"diritto al proprio domicilio digitale"},{"id":456,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Il principio del \"digital first\" stabilisce:","correct":"che le PA devono adottare un modello efficiente per la gestione dei documenti digitali","wrong1":"che le PA devono privilegiare i documenti cartacei","wrong2":"la creazione di regole e procedure complesse che ostacolano l'accesso ai servizi digitali da parte dei cittadini","wrong3":"la digitalizzazione dei processi amministrativi senza considerare la conservazione a lungo termine dei documenti"},{"id":457,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Il Decreto «Misure urgenti per la semplificazione e l'innovazione digitale» NON mira a:","correct":"introdurre restrizioni sull'uso delle tecnologie digitali all'interno delle pubbliche amministrazione","wrong1":"favorire la diffusione di servizi pubblici in rete, agevolarne e semplificarne l'accesso da parte di cittadini e imprese","wrong2":"digitalizzazione finalizzata a semplificazioni delle procedure, miglioramento dell'efficienza e abbattimento di numerosi costi","wrong3":"diritto a innovare per le imprese che beneficiano di procedure semplificate per sperimentare progetti innovativi"},{"id":458,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Tra le semplificazioni che il Decreto introduce per il cittadino NON rientra:","correct":"accesso selezionato e non unificato tramite SPID o CIE","wrong1":"app IO come Canale Unico","wrong2":"autocertificazione e Presentazione di Istanze","wrong3":"accesso facilitato per persone con disabilità"},{"id":459,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Tra le semplificazioni che il Decreto introduce per la PA NON rientra:","correct":"standardizzazione delle procedute Offline","wrong1":"comunicazione Online tra PA e Cittadini","wrong2":"supporto alla Trasformazione Digitale","wrong3":"migrazione al Cloud Nazionale"},{"id":460,"paragraph":"La digitalizzazione della PA - Le premesse normative","question":"Tra le semplificazioni che il Decreto introduce per le imprese NON rientra:","correct":"complessificazione della procedura di iscrizione al Registro delle Imprese","wrong1":"utilizzo della Posta Elettronica Certificata","wrong2":"modifiche alla Piattaforma \"Incentivi.gov\":","wrong3":"modifiche al Contributo Statale \"Nuova Sabatini\":"},{"id":461,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"SEC è un acronimo per:","correct":"Sistema Europeo dei Conti economici","wrong1":"Sistema Europeo dei Conti numerari","wrong2":"Sistema Estero dei Conti economici","wrong3":"Sistema Esteso dei Conti economici"},{"id":462,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Il SEC 2010 rispetto al precedente SEC 95 NON:","correct":"conferma le già presenti le regole delle spese pubbliche","wrong1":"introduce nuovi standard per la valutazione di alcune attività economiche","wrong2":"migliora la classificazione delle unità istituzionali","wrong3":"aggiorna le regole sulla registrazione delle entrate"},{"id":463,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Il SEC 2010 classifica le unità istituzionali in diversi settori in base alla loro:","correct":"funzione economica principale","wrong1":"forma giuridica","wrong2":"strategia decisionale","wrong3":"competenza territoriale"},{"id":464,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Tra le unità istituzionali definite dal SEC 2010 NON rientrano:","correct":"le società non finanziarie","wrong1":"le famiglie","wrong2":"i corpi diplomatici","wrong3":"le imprese individuali"},{"id":465,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Secondo il SEC 2010, le AP:","correct":"producono beni e servizi non di mercato per il consumo individuale o collettivo","wrong1":"producono beni e servizi non di mercato per il consumo individuale","wrong2":"erogano servizi non di mercato per il consumo individuale o collettivo","wrong3":"producono beni e servizi di mercato per il consumo collettivo"},{"id":466,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Le pubbliche amministrazioni:","correct":"possono conseguire profitti ma non possono distribuire utili","wrong1":"possono distribuire utili","wrong2":"non generano profitto","wrong3":"non reinvestono le ricchezze generate"},{"id":467,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Le pubbliche amministrazioni svolgono funzioni:","correct":"esecutive, fiscali e legislative","wrong1":"fiscali e legislative","wrong2":"legislative ed esecutive","wrong3":"solo fiscali"},{"id":468,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Le Amministrazioni centrali:","correct":"assicurano la governance del territorio nazionale","wrong1":"non collaborano","wrong2":"comprendono solo gli organi costituzionali","wrong3":"assicurano la governance del territorio locale"},{"id":469,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Secondo il SEC 2010 il settore delle AP, è suddiviso in:","correct":"4 sottosettori","wrong1":"2 sottosettori","wrong2":"3 sottosettori","wrong3":"5 sottosettori"},{"id":470,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche nel SEC 2010","question":"Gli Enti di Previdenza e Assistenza Sociale:","correct":"erogano prestazioni sociali obbligatorie","wrong1":"erogano prestazioni sociali non obbligatorie","wrong2":"non erogano le pensioni","wrong3":"non eroga servizi di previdenza per i dipendenti"},{"id":471,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Il sistema aziendale è dato dall' unione di tre sotto sistemi, tra cui NON rientra:","correct":"il marchio","wrong1":"organizzazione","wrong2":"gestione","wrong3":"patrimonio"},{"id":472,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Il sistema aziendale deve essere capace di anticipare e adattarsi ai mutamenti dello scenario, per questo viene definito come un sistema:","correct":"dinamico","wrong1":"responsabile","wrong2":"unitario","wrong3":"unico"},{"id":473,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Le aziende pubbliche:","correct":"tendono a focalizzarsi su obiettivi sociali","wrong1":"perseguono sempre lo scopo di profitto","wrong2":"non sono di proprietà dello Stato","wrong3":"sono partecipate al 100% dallo Stato"},{"id":474,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Il finanziamento delle aziende pubbliche proviene principalmente:","correct":"dal bilancio dello Stato","wrong1":"dall'erogazione sul mercato dei servizi prodotti","wrong2":"dallo scambio sul mercato dei beni prodotti","wrong3":"da donazioni"},{"id":475,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Il sistema aziendale deve essere libero di definire i suoi obiettivi strategici, per questo è definito:","correct":"autonomo","wrong1":"aperto","wrong2":"dinamico","wrong3":"unico"},{"id":476,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Le aziende pubbliche:","correct":"sono strumenti attraverso cui il governo può attuare politiche pubbliche","wrong1":"operano sotto stretta supervisione dell'ente politico nazionale","wrong2":"necessitano di operare con margini di profitto maggiori rispetto alle aziende private","wrong3":"non giocano mai un ruolo significativo nel mercato del lavoro locale o nazionale"},{"id":477,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Il soggetto giuridico si riferisce a:","correct":"una persona fisica o giuridica che possieda la capacità di avere diritti e doveri giuridici","wrong1":"una persona fisica che possieda la capacità di avere diritti e doveri giuridici","wrong2":"una persona giurdicia che possieda la capacità di avere diritti e doveri giuridici","wrong3":"una persona fisica o giuridica che possieda la volontà di gestire un'azienda"},{"id":478,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Un'azienda pubblica con soggetto giuridico pubblico:","correct":"deve sottoporre le sue decisioni di spesa a processi burocratici governativi","wrong1":"possiede un'autonomia finanziaria significativa","wrong2":"non è soggetta a scrutinio pubblico","wrong3":"persegue uno scopo di lucro orientato, in base ai bisogni dell'organo politico"},{"id":479,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"Un'azienda pubblica con soggetto economico pubblico:","correct":"gode di un' autonomia operativa e finanziaria significativa","wrong1":"non è responsabile per le proprie performance finanziarie","wrong2":"non è responsabile per le proprie performance operative","wrong3":"non è mai competitiva sul mercato"},{"id":480,"paragraph":"La digitalizzazione della PA - Il concetto di azienda","question":"L'azienda è tenuta a rispondere con appositi strumenti di comunicazione e linguaggi specifici per i risultati conseguiti, per questo è definita come un sistema:","correct":"responsabile","wrong1":"aperto","wrong2":"autonomo","wrong3":"dinamico"},{"id":481,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Tra le forme di collaborazione individuate dal TUEL NON rientrano:","correct":"le associazioni di categoria","wrong1":"le comunità montane","wrong2":"i consorzi","wrong3":"la fusione di comuni"},{"id":482,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Nella Convenzione, i Comuni:","correct":"devono definire gli scopi e la durata dell'accordo, le forme di consultazione degli enti contraenti, i loro rapporti finanziari e i reciproci obblighi e garanzie","wrong1":"non sono tenuti a stabilire la durata dell'accordo né a formulare obblighi reciproci, permettendo così una gestione più flessibile e meno vincolata delle collaborazioni","wrong2":"possono liberamente decidere di non stabilire gli scopi specifici o la durata dell'accordo, lasciando indeterminate le forme di consultazione e i rapporti finanziari tra gli enti contraenti","wrong3":"devono definire gli scopi e la durata dell'accordo, ma non le forme di consultazione degli enti contraenti, i loro rapporti finanziari e i reciproci obblighi e garanzie"},{"id":483,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Al Consorzio, oltre ai Comuni, possono partecipare:","correct":"enti pubblici autorizzati dalle legge alle quali sono soggetti","wrong1":"enti privati","wrong2":"enti pubblici","wrong3":"enti pubblici autorizzati dalle legge alle quali sono soggetti"},{"id":484,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"La Gestione Associata è un:","correct":"processo di agglomerazione tra Comuni che non porta alla nascita di un nuovo ente","wrong1":"processo di agglomerazione tra Comuni che porta alla nascita di un nuovo ente","wrong2":"processo di fusione tra Comuni che porta alla nascita di un nuovo ente","wrong3":"processo di fusione tra Comuni che può portare anche alla nascita di due nuovi enti"},{"id":485,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"L'Accordo di programma ha per oggetto:","correct":"realizzazione lavori e progetti","wrong1":"la gestione in comune di funzioni comunali","wrong2":"l'erogazione di servizi pubblici","wrong3":"la vendita di beni prodotti"},{"id":486,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"La fusione dei comuni può coinvolgere:","correct":"solo i comuni confinanti","wrong1":"solo i comuni della stessa provincia","wrong2":"solo i comuni della stessa regione","wrong3":"tutit i comuni indistintamente"},{"id":487,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Nella fusione per incorporazione, il comune incorporante:","correct":"succede in tutti i rapporti giuridici del Comune incorporato","wrong1":"non avviene alcuna transizione legale nè amministrativa","wrong2":"perde la sua identità legale","wrong3":"viene inglobato da uno dei comuni confinanti"},{"id":488,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Nell'Unione di comuni, lo Statuto definisce:","correct":"le modalità operative del processo di unione","wrong1":"le ragioni del processo di unione","wrong2":"i vantaggi del processo di unione","wrong3":"i dettagli dei comuni coinvolti"},{"id":489,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"Il presidente dell'Unione è nominato:","correct":"tra i sindaci dei Comuni membri, al fine di garantire una leadership informata e direttamente responsabile davanti agli elettori locali","wrong1":"da un ente sovranazionale, senza la necessità di essere uno dei sindaci dei Comuni membri, per assicurare una supervisione esterna e indipendente","wrong2":"tra i cittadini dei Comuni membri, non necessariamente limitata ai sindaci, per promuovere un'approccio più democratico e meno istituzionale","wrong3":"esclusivamente dai consigli regionali, al di fuori dei sindaci dei Comuni membri, per evitare conflitti di interesse e garantire una governance imparziale"},{"id":490,"paragraph":"La digitalizzazione della PA - Le forme di collaborazione istituzionale tra Comuni","question":"L'Unione di comuni:","correct":"si forma dall'accordo di due o più Comuni che decidono di associarsi per gestire insieme determinate funzioni e servizi","wrong1":"è un organismo informale che emerge spontaneamente tra Comuni vicini senza un accordo formale, per scambiarsi occasionalmente servizi e funzioni","wrong2":"opera indipendentemente da qualsiasi accordo tra i Comuni membri, concentrando i suoi sforzi esclusivamente su progetti temporanei e non su una gestione congiunta stabile di funzioni e servizi","wrong3":"si forma unicamente per scopi consultivi, senza alcuna autorità decisionale o amministrativa, limitando la sua attività a fornire raccomandazioni ai Comuni membri"},{"id":491,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Il regolamento eIDAS:","correct":"definisce e regola i servizi elettronici cosiddetti «fiduciari»","wrong1":"fornisce una risposta efficace alle sfide in materia di sicurezza delle reti e dei sistemi informativi","wrong2":"definisce e regola i sistemi di privacy","wrong3":"regola i sistemi di pagamento elettronici"},{"id":492,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"La terza Direttiva sui Sistemi di Pagamento (PSD3):","correct":"non è ancora entrato in vigore","wrong1":"è entrato in vigore nel 2021","wrong2":"è entrato in vigore nel 2023","wrong3":"è entrato in vigore nel 2019"},{"id":493,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Tra gli obblighi del titolare al trattamento riconosciuti dal regolamento GDPR NON rientra:","correct":"la ricezione dei dati personali in un formato strutturato","wrong1":"la nomina dei responsabili per il trattamento e la protezione dei dati","wrong2":"la tenuta dei registri","wrong3":"la trasparenza nel fornire l'informativa richiesta"},{"id":494,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Tra le sfide cui vuole rispondere l'i2010 e-government action plan NON rientra:","correct":"creare sistema di condivisione interna delle informazioni, impedendo la circolazione dei dati oltre il territorio europeo","wrong1":"modernizzare i servizi pubblici e renderli più efficaci","wrong2":"rispondere alle richieste delle imprese che vorrebbero meno burocrazia e più efficienza","wrong3":"fornire servizi di migliore qualità e più sicuri alla popolazione"},{"id":495,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Tra gli obiettivi che l'i2010 e-government action plan si prefigge rientra:","correct":"estendere i benefici dell'eGovernment a livello di Unione Europea (UE) consentendo economie di scala","wrong1":"garantire l'e-government, eventualmente anche ostacolando il mercato interno nazionale","wrong2":"selezionare coloro che possono accedere ai servizi online in base a prefissati requisiti","wrong3":"rallentare il processo di transizione digitale"},{"id":496,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Tra i termini chiave utilizzati nell'i2010 e-government action plan rientra:","correct":"e-accessibility","wrong1":"e-integration","wrong2":"e-concentration","wrong3":"e-cooperation"},{"id":497,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"La prima Digital Agenda individua come priorità per l'Europa una crescita:","correct":"intelligente, sostenibile, inclusiva","wrong1":"lenta, sostenibile, inclusiva","wrong2":"intelligente, sostenibile, esclusiva","wrong3":"intelligente, cooperativa, inclusiva"},{"id":498,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"L'impegno con la Digital Agenda Europe 2010-2020 per il decennio si fonda:","correct":"da un lato sul superamento delle barriere all'avanzamento tecnologico; dall'altro sull'incentivo di investimenti per lo sviluppo di reti infrastrutturali","wrong1":"da un lato sul superamento delle barriere all'avanzamento tecnologico; dall'altro sull'incentivo di investimenti per l'alfabetizzazione","wrong2":"solo sul superamento delle barriere all'avanzamento tecnologico","wrong3":"sull'incremento di ricerca e sviluppo"},{"id":499,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"La seconda DAE 2020- 2030 delinea per il decennio:","correct":"quattro obiettivi","wrong1":"cinque obiettivi","wrong2":"due obiettivi","wrong3":"tre obiettivi"},{"id":500,"paragraph":"La digitalizzazione della PA - Il quadro di riferimento europeo","question":"Indicare quale dei seguenti obiettivi NON è previsto nel nuovo action Plano 2018-2022:","correct":"l'apertura del mercato dei pagamenti anche a parti terze","wrong1":"la diffusione di \"punti di contatto unici\" tra cittadini ed interlocutori pubblici","wrong2":"la riduzione di adempimenti burocratici nella fase di accesso e utilizzo dei servizi online","wrong3":"l'incremento della quantità e della qualità degli open governmnet data"},{"id":501,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Il principio Digital First implica:","correct":"la progettazione dei servizi pensando alla loro erogazione principalmente attraverso canali digitali","wrong1":"la progettazione dei servizi pensando alla loro erogazione principalmente attraverso soluzioni on site","wrong2":"l'implementazione di soluzioni volte a ridurre i costi e migliorare la qualità dei servizi","wrong3":"la promozione della cultura digitale"},{"id":502,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Tra gli aspetti su cui si concentra il piano di crescita digitale contenuto nell' agenda digitale NON rientra:","correct":"la definizione di un modello strategico di evoluzione dell'ICT","wrong1":"l'adozione del principio Digital First","wrong2":"il coordinamento di iniziative di trasformazione digitale","wrong3":"la modernizzazione della pubblica amministrazione"},{"id":503,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Tra le piattaforme abilitanti identificate nel piano di crescita digitale rientra:","correct":"Piattaforma per la Scuola Digitale","wrong1":"Piattaforma per l'intrattenimento Digitale","wrong2":"Sistema di Monitoraggio Digitale","wrong3":"Piattaforma di Closed Data"},{"id":504,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Per \"Italia Login\" si intende:","correct":"un portale digitale unico dal quale accedere a informazioni e servizi pubblici pertinenti","wrong1":"un' infrastruttura tecnologica che generi intelligenza","wrong2":"una serie coordinata di programmi e azioni volte a migliorare le conoscenze e le competenze digitali dei manager","wrong3":"una serie coordinata di programmi e azioni volte a migliorare le conoscenze e le competenze digitali dei cittadini"},{"id":505,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Il modello strategico classifica le sfide organizzative e tecnologiche che le amministrazioni devono affrontare in tre macroaree:","correct":"processi, applicazioni e tecnologie","wrong1":"processi, strutturee tecnologie","wrong2":"processi, applicazionie definizioni","wrong3":"processi, proceduree tecnologie"},{"id":506,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Indicare quale tra le seguenti opzioni NON rappresenta un principio guida del Piano Triennale:","correct":"cyber security","wrong1":"digital identity only","wrong2":"openness","wrong3":"cloud first"},{"id":507,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Il PNRR prevede:","correct":"7 missioni","wrong1":"6 missioni","wrong2":"4 missioni","wrong3":"3 missioni"},{"id":508,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Indicare quale tra le seguenti affermazioni è falsa. La transizione 5.0 green","correct":"vuole consentire alle imprese di accedere a incentivi più consistenti per progetti di rinnovazione e sviluppo sostenibile","wrong1":"si concentra su misure incentrate sulla sostenibilità ambientale","wrong2":"prevede l'introduzione di incentivi differenziati basati sui risparmi energetici e l'estensione dei limiti massimi di investimento ammissibili","wrong3":"vuole favorire la conversione delle attività produttive verso pratiche più eco-friendly."},{"id":509,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Indicare quale tra le seguenti affermazioni è falsa. La transizione 5.0 formazione","correct":"vuole consentire alle imprese di accedere a incentivi più consistenti per progetti di rinnovazione e sviluppo sostenibile","wrong1":"contribuisce al raggiungimento degli obiettivi di transizione ecologica e innovazione","wrong2":"mira ad introdurre incentivi per le spese formative legate agli investimenti","wrong3":"vuole garantire che la formazione sia erogata da soggetti qualificati"},{"id":510,"paragraph":"La digitalizzazione della PA - Il percorso italiano","question":"Indicare quale tra le seguenti affermazioni è falsa. La transizione 5.0 tetto scaglioni:","correct":"contribuisce agli investimenti in nuove categorie di software dedicati al monitoraggio energetico e alla gestione aziendale","wrong1":"evidenzia l'aumento significativo del tetto massimo degli investimenti agevolabili","wrong2":"consente alle imprese di accedere a incentivi più consistenti per progetti di rinnovazione","wrong3":"consente alle imprese di accedere a incentivi più consistenti per progetti di sviluppo sostenibile"},{"id":511,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Nel nostro paese il termine Industria 4.0 si è diffuso a partire dal:","correct":"2016","wrong1":"2013","wrong2":"2019","wrong3":"2022"},{"id":512,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"La simulazione:","correct":"utilizza sistemi simulativi per analizzare e migliorare i processi produttivi","wrong1":"permette la produzione di oggetti tridimensionali a partire da modelli virtuali","wrong2":"è una branca dell'informatica che si occupa della progettazione di componenti tecnic","wrong3":"è un tipo di realtà digitale"},{"id":513,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"L' Internet of Things:","correct":"si riferisce all'interconnessione degli oggetti dotati di sensori che possono raccogliere i dati","wrong1":"è una branca dell'informatica che si occupa della progettazione di componenti tecnic","wrong2":"è una tecnologia che supporta la raccolta e l'analisi di enormi quantità","wrong3":"consente alle aziende di visualizzare e simulare i processi industrial"},{"id":514,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Il termine Industria 5.0 è stato coniato nel:","correct":"2015","wrong1":"2016","wrong2":"2024","wrong3":"2007"},{"id":515,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"La Society 5.0 NON è:","correct":"un modello imprenditoriale basato sui robot","wrong1":"un modello che bilancia lo sviluppo economico con la risoluzione dei problemi socio-ambientali","wrong2":"un modello che utilizza la tecnologia per migliorare la qualità della vita.","wrong3":"un modello imprenditoriale giapponese"},{"id":516,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Indica quali delle seguenti affermazioni è vera:","correct":"l'Industria 4.0 mira all'utilizzo della tecnologia per la massimizzazione del profitto, mentre l'Industria 5.0 introduce indicatori che valutano il progresso verso il benessere","wrong1":"l'Industria 4.0 mira al progresso verso il benessere del dipendente, mentre l'Industria 5.0 mira alla massimizzazione del profitto","wrong2":"l'Industria 4.0 si basa sui concetti di resilienza e sostenibilità","wrong3":"l'Industria 5.0 si concentra principalmente sull'efficienza"},{"id":517,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Le tre principali caratteristiche dell'Industria 5.0 sono:","correct":"umanocentricità; sostenibilità; resilienza","wrong1":"umanocentricità; flessibilità; resilienza","wrong2":"umanocentricità; sostenibilità; complessità","wrong3":"umanocentricità; adattabilità; resistenza"},{"id":518,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Indicare quale delle seguenti affermazioni è errata:","correct":"per una digitalizzazione efficace è sufficiente investire in nuovi macchinari","wrong1":"la digitalizzazione può anche promuovere l'inclusione","wrong2":"le tecnologie digitali permettono una gestione più efficace delle emergenze sanitarie","wrong3":"le tecnologie digitali possono facilitare l'accesso ai servizi pubblici"},{"id":519,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"I principali vantaggi derivanti dall'implementazione di tecnologie digitali nella PA sono:","correct":"incremento dell'accountability e della trasparenza, miglioramento dell'efficienza operativa, personalizzazione e adattabilità dei servizi pubblici","wrong1":"incremento dell'accountability e della trasparenza","wrong2":"miglioramento dell'efficienza operativa","wrong3":"personalizzazione e adattabilità dei servizi pubblici"},{"id":520,"paragraph":"La digitalizzazione della PA - Il contesto socio-economico e le tecnologie emergenti","question":"Le sfide principali affrontate dai governi nell'integrazione delle tecnologie digitali nella PA sono:","correct":"sfide tecniche e risorse, vincoli di capacità e barriere culturali, mancanza di standard comuni e quadri giuridici adeguati","wrong1":"sfide tecniche e risorse","wrong2":"vincoli di capacità e barriere culturali","wrong3":"mancanza di standard comuni e quadri giuridici adeguati"},{"id":521,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"I quattro principali punti di intervento del Digital Compass 2030 NON riguardano:","correct":"espansione delle reti sociali governative","wrong1":"competenze digitali e professionisti ICT","wrong2":"infrastrutture digitali sostenibili","wrong3":"trasformazione digitale delle imprese"},{"id":522,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Tra gli obiettivi del Digital Compass 2030, vi è quello di:","correct":"garantire che almeno l'80% della popolazione possieda competenze digitali di base","wrong1":"garantire che almeno il 20% della popolazione possieda competenze digitali di base","wrong2":"triplicare la quota Europea nella produzione mondiale di semiconduttori","wrong3":"sviluppare il terzo computer con capacità di accelerazione quantistica"},{"id":523,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Tra gli obiettivi di trasformazione digitale previsti dal Digital Compass 2030, vi è quello di:","correct":"far sì che oltre il 90% delle piccole e medie imprese (PMI) raggiunga almeno un livello base di intensità digitale","wrong1":"far sì che oltre il 40% delle piccole e medie imprese (PMI) raggiunga almeno un livello base di intensità digitale","wrong2":"far sì che oltre il 10% delle piccole e medie imprese (PMI) raggiunga almeno un livello base di intensità digitale","wrong3":"far sì che oltre il 100% delle piccole e medie imprese (PMI) raggiunga almeno un livello base di intensità digitale"},{"id":524,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Tra gli obiettivi di digitalizzazione dei servizi pubblici del Digital Compass 2030, vi è quello di:","correct":"convertire i servizi pubblici per il 100% online","wrong1":"convertire i servizi pubblici per il 70% online","wrong2":"assicurare che almeno tutti i cittadini tra i 18 e i 65 anni di età siano identificati digitalmente","wrong3":"assicurare che almeno tutti i cittadini tra i 18 e i 65 anni di età abbiano accesso alla cartella clinica elettronica"},{"id":525,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Il diritto digitale che prevede le persone al centro:","correct":"sottolinea che le tecnologie digitali dovrebbero proteggere i diritti umani, sostiene la democrazia, garantisce che tutti gli operatori digitali agiscano in modo responsabile e sicuro","wrong1":"sottolinea che le tecnologie digitali dovrebbero proteggere i diritti umani","wrong2":"sostiene la democrazia","wrong3":"garantisce che tutti gli operatori digitali agiscano in modo responsabile e sicuro"},{"id":526,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Il diritto digitale che prevede solidarietà e inclusione:","correct":"richiede l'estensione massima dei servizi pubblici digitali e condizioni di lavoro eque","wrong1":"non implica l'accesso universale ad internet","wrong2":"ambisce all'accesso ad internet di una specifica parte della popolazione","wrong3":"richiede l'estensione massima dei servizi pubblici digitali e condizioni di lavoro eque, non implica l'accesso universale ad internet, ambisce all'accesso ad internet di una specifica parte della popolazione"},{"id":527,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Tra i diritti digitali rientra quello di:","correct":"partecipazione","wrong1":"equità","wrong2":"resilienza","wrong3":"individualità"},{"id":528,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Nel ranking 2022 del DESI, l'Italia si trova alla posizione numero:","correct":"18","wrong1":"23","wrong2":"27","wrong3":"16"},{"id":529,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"L'acronimo GOL sta per:","correct":"Garanzia di Occupabilità dei Lavoratori","wrong1":"Garanzia Organizzativa del Lavoro","wrong2":"Gestione Operativa del Lavoro","wrong3":"Garanzia Operativa Lavorativa"},{"id":530,"paragraph":"La digitalizzazione della PA - Il decennio digitale: come si posiziona l'Italia","question":"Indicare quale delle seguenti dimensioni NON compone il DESI:","correct":"efficienza digitale","wrong1":"capitale umano","wrong2":"connettività","wrong3":"servizi pubblici digitali"},{"id":531,"paragraph":"La digitalizzazione della PA - I nomi a dominio: regolazione tecnica","question":"Come si può definire il domain name:","correct":"l'indirizzo alfanumerico di identificazione di un dispositivo collegato a Internet","wrong1":"ientificativo costituito da 4 byte (8 bit) rappresentati da una sequenza di 4 blocchi di numeri decimali, separati da punti, che possono assumere un valore da 0 a 255","wrong2":"indica la nazionalità del dominio o la categoria di appartenenza","wrong3":"ente che assegna nomi a dominio a livello internazionale e sovrintende alla gestione e all'identificazione di criteri uniformi per la risoluzione delle controversie"},{"id":532,"paragraph":"La digitalizzazione della PA - I nomi a dominio: regolazione tecnica","question":"Il Second Level Domain (SLD) del nome a dominio:","correct":"è l'elemento liberamente scelto dall'utente, un nome unico ed esclusivo nella rete Internet, fondamentale per individuare e distinguere il nome a dominio","wrong1":"indica la nazionalità del dominio","wrong2":"indica la la categoria di appartenenza","wrong3":"è l'indirizzo IP"},{"id":533,"paragraph":"La digitalizzazione della PA - I nomi a dominio: regolazione tecnica","question":"In Italia, per l'assegnazione dei nomi a dominio all'interno del country code ccTLD.it, la Registration Authority è:","correct":"Registro del ccTLD.it o Registro .it","wrong1":"ICANN (Internet Corporation of Assigned Names and Numbers)","wrong2":"Autorità per le Garanzie nelle Comunicazioni","wrong3":"Il Garante per la protezione dei dati personali"},{"id":534,"paragraph":"La digitalizzazione della PA - I nomi a dominio: tutela giuridica","question":"I nomi a dominio come segni distintivi da quale normativa sono tutelati:","correct":"codice della proprietà industriale (d.lgs. 30/2005)","wrong1":"codice dell'amministrazione digitale (d.lgs. 82/2005)","wrong2":"regolamento europeo 2016/679","wrong3":"legge 633/1941"},{"id":535,"paragraph":"La digitalizzazione della PA - I nomi a dominio: tutela giuridica","question":"Quale tra queste discipline normative non viene in gioco a tutela dei nomi a dominio:","correct":"pubblica amministrazione digitale","wrong1":"proprietà industriale","wrong2":"diritto al nome","wrong3":"proprietà intellettuale"},{"id":536,"paragraph":"La digitalizzazione della PA - I nomi a dominio: tutela giuridica","question":"Il cybersquatting o domain grabbing:","correct":"consiste nell'accaparrare nomi a dominio corrispondenti a marchi o nomi altrui non ancora registrati, solitamente noti, con le finalità di rivendere a maggior costo a chi ne ha interesse, ottenendo così un indebito vantaggio e di porre in essere atti di concorrenza sleale, traendo indebito vantaggio dalla confusione fra segni e dallo sviamento della clientela","wrong1":"si verifica laddove i titolari di marchi registrati approfittino della loro posizione per ottenere a loro favore nomi legittimamente assegnati ad altri o sui quali comunque non sono i soli a vantare diritti","wrong2":"consiste nell'utilizzo del titolo di un'opera altrui o di una testata giornalistica","wrong3":"significa l'utilizzazione indebita del nome altrui, idonea ad arrecare un pregiudizio al titolare"},{"id":537,"paragraph":"La digitalizzazione della PA - L'evoluzione del diritto nell'era digitale","question":"Cosa si intende per data society:","correct":"la società contemporanea, che è intimamente pervasa dai dati finendo per coinvolgere e plasmare l'uomo stesso come un data subject","wrong1":"il codice informatico, ossia le regole informatiche (non giuridiche)","wrong2":"condizioni d'uso, termini di servizio e policy delle piattaforme digitali","wrong3":"il corpus di norme giuridiche poste dal legislatore in materia di informatica e tecnologie digitali"},{"id":538,"paragraph":"La digitalizzazione della PA - L'evoluzione del diritto nell'era digitale","question":"Con lex informatica si intende:","correct":"il codice informatico, ossia le regole informatiche (non giuridiche)","wrong1":"il corpus di norme giuridiche poste dal legislatore in materia di informatica e tecnologie digitali","wrong2":"condizioni d'uso, termini di servizio e policy delle piattaforme digitali","wrong3":"le regole contenute nel Codice dell'amministrazione digitale (d.lgs. 82/2005)"},{"id":539,"paragraph":"La digitalizzazione della PA - L'evoluzione del diritto nell'era digitale","question":"Soft law significa:","correct":"un sistema di regole non precettive e non vincolanti, comunque caratterizzato da un diverso grado di persuasività, ossia in grado di svolgere effettivamente una funzione di orientamento e di indirizzo nei confronti dei loro destinatari, sebbene non suscettibili di attuazione giudiziaria","wrong1":"condizioni d'uso, termini di servizio e policy delle piattaforme digitali","wrong2":"il codice informatico, ossia le regole informatiche (non giuridiche)","wrong3":"un sistema di regole giuridiche vincolanti, dotate di piena obbligatorietà in senso giuridico, suscettibili in caso di violazione di applicazione giudiziaria"},{"id":540,"paragraph":"La digitalizzazione della PA - I regolamenti europei dedicati alle tecnologie digitali","question":"Al fine di garantire una disciplina complessivamente sostenibile la regolazione europea relativa alla dimensione digitale quali esigenze mira a garantire:","correct":"prevedibilità e certezza del diritto, da una parte, ma anche flessibilità e adattabilità all'evoluzione e ai cambiamenti della tecnologia, dall'altra","wrong1":"soltanto flessibilità e adattabilità all'evoluzione e ai cambiamenti della tecnologia, rinunciando a certezza e prevedibilità in considerazione dello specifico oggetto di regolazione","wrong2":"esclusivamente prevedibilità e certezza del diritto","wrong3":"a fini di sostenibilità si sceglie di rinviare la disciplina giuridica completamente agli Stati membri, che possono regolare al riguardo in modo autonomo"},{"id":541,"paragraph":"La digitalizzazione della PA - I regolamenti europei dedicati alle tecnologie digitali","question":"Il regolamento UE 2018/1807 è dedicato a:","correct":"i dati non personali","wrong1":"i dati personali","wrong2":"i dati misti","wrong3":"i dati di tipo aperto (open data)"},{"id":542,"paragraph":"La digitalizzazione della PA - I regolamenti europei dedicati alle tecnologie digitali","question":"Il gatekeeper cui si applica il regolamento UE 2022/1925 (Digital Markets Act) è:","correct":"impresa che ha un forte impatto sul mercato interno, fornisce un servizio di piattaforma di base che costituisce un punto di accesso importante affinché gli utenti commerciali raggiungano gli utenti finali e gode di una posizione consolidata e durevole o è prevedibile la acquisisca","wrong1":"qualsiasi impresa che svolge attività di intermediazione online","wrong2":"il soggetto che esercita un'attività imprenditoriale di prestatore di servizi della società dell'informazione, offrendo in particolare servizi intermediari, quali connessione, trasmissione e memorizzazione dei dati","wrong3":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo che, singolarmente o insieme ad altri, determina le finalità e i mezzi del trattamento di dati personali"},{"id":543,"paragraph":"La digitalizzazione della PA - Il mondo digitale nella nuvola: il Cloud Computing","question":"Quale tra i seguenti non è un modello di distribuzione del cloud computing:","correct":"Performance as a Service (PaaS)","wrong1":"Software as a Service (SaaS)","wrong2":"Platform as a Service (PaaS)","wrong3":"Infrastructure as a Service (IaaS)"},{"id":544,"paragraph":"La digitalizzazione della PA - Il mondo digitale nella nuvola: il Cloud Computing","question":"Quale direttiva europea rileva in materia di cloud computing:","correct":"direttiva (UE) 2019/770","wrong1":"direttiva (UE) 2019/1024","wrong2":"direttiva 95/46/CE","wrong3":"direttiva 96/9/CE"},{"id":545,"paragraph":"La digitalizzazione della PA - Il mondo digitale nella nuvola: il Cloud Computing","question":"Quale tra i seguenti non rientra tra gli aspetti giuridici particolarmente problematici per quanto attiene al cloud computing:","correct":"aspetti contrattuali","wrong1":"data protection","wrong2":"data governance","wrong3":"diritto di accesso"},{"id":546,"paragraph":"La digitalizzazione della PA - La Dichiarazione europea sui diritti e i principi digitali per il decennio digitale","question":"La Dichiarazione europea sui diritti e i principi digitali per il decennio digitale che valore ha:","correct":"natura dichiarativa e, in quanto tale, non incide sul contenuto delle norme giuridiche o sulla loro applicazione","wrong1":"si tratta di un atto normativo vincolante e prescrittivo","wrong2":"il valore di un regolamento europeo","wrong3":"ha la capacità di disapplicare norme giuridiche degli Stati membri che non siano conformi"},{"id":547,"paragraph":"La digitalizzazione della PA - La Dichiarazione europea sui diritti e i principi digitali per il decennio digitale","question":"Con trasformazione digitale antropocentrica si intende:","correct":"le persone devono essere al centro della trasformazione digitale e la tecnologia dovrebbe essere al servizio","wrong1":"la tecnologia deve essere al centro della trasformazione digitale","wrong2":"la tecnologia deve sostituire l'uomo nei suoi compiti e nelle sue attività","wrong3":"la trasformazione digitale si pone come fine da perseguire e non più come strumento nelle mani dell'uomo"},{"id":548,"paragraph":"La digitalizzazione della PA - La Dichiarazione europea sui diritti e i principi digitali per il decennio digitale","question":"La Dichiarazione europea tratta il profilo della cibersicurezza:","correct":"la Dichiarazione esplicita l'impegno di proteggere gli interessi di persone, imprese e istituzioni pubbliche dai rischi di cibersicurezza","wrong1":"no la Dichiarazione europea non fa riferimenti alla cubersicurezza","wrong2":"il profilo della cibersicurezza non è oggetto della Dichiarazione, in quanto emerso successivamente nella riflessione e nel dibattito pubblico","wrong3":"la Dichiarazione europea esplicitamente dichiara di non occuparsi di profili di cibersicurezza, rinviando al riguardo a una diversa Dichiarazione europea"},{"id":549,"paragraph":"La digitalizzazione della PA - Società algoritmica, sovranità digitale e piattaforme digitali","question":"Il web 2.0 si caratterizza per essere:","correct":"web attivo e sociale con servizi e applicazioni che garantiscono alto livello di interazione sito-utente","wrong1":"web statico con servizi offerti in modo unilaterale all'utente","wrong2":"Internet of Everythings che vede integrazione piena con la realtà, ubiquità, realtà aumentata, web smart","wrong3":"web emotivo con interfacce che rispondono alle emozioni e con dati e identità sotto il controllo dell'utente"},{"id":550,"paragraph":"La digitalizzazione della PA - Società algoritmica, sovranità digitale e piattaforme digitali","question":"Il modello europeo di sovranità digitale si caratterizza per:","correct":"sovranità regolatoria, tutela dei diritti digitali e scarsa produzione industriale di tecnologie digitali","wrong1":"dominio del mercato da parte delle aziende Big Tech, limitato intervento normativo e cooperazione pubblico/privato","wrong2":"controllo diretto, totale e pervasivo dello Stato, piattaforme interne autoctone e sorveglianza di massa sugli utenti","wrong3":"blocco di grandi piattaforme esterne, controllo diretto e pervasivo dello Stato e limitato intervento normativo"},{"id":551,"paragraph":"La digitalizzazione della PA - Società algoritmica, sovranità digitale e piattaforme digitali","question":"Tra i casi in cui Meta può sospendere o disabilitare definitivamente l'accesso ai prodotti o l'account dell'utente non rientra:","correct":"in caso in cui l'utente utilizza anche prodotti di altre piattaforme","wrong1":"violazione in modo chiaro, grave o ripetuto delle condizioni o policy di Meta","wrong2":"obbligo per Meta di sospendere o eliminare account per motivi legali","wrong3":"violazione in modo ripetuto dei diritti altrui, quali i diritti di proprietà intellettuale di altri utenti"},{"id":552,"paragraph":"La digitalizzazione della PA - Capitalismo della sorveglianza: Datagate, Cambridge Analytica e il caso Trump","question":"Il caso Datagate è emerso grazie alle rivelazioni di:","correct":"Edward Joseph Snowden","wrong1":"Donald Trump","wrong2":"Christopher Wylie","wrong3":"Cambridge Analytica"},{"id":553,"paragraph":"La digitalizzazione della PA - Capitalismo della sorveglianza: Datagate, Cambridge Analytica e il caso Trump","question":"Nel caso che l'ha riguardata (anche detto Facebookgate) Cambridge Analytica quali operazioni ha compiuto che hanno determinato il clamore della vicenda:","correct":"profilazione con la finalità di realizzare campagne di comunicazione capaci di influenzare, condizionare e manipolare gli utenti in occasioni quali la campagna per il referendum sulla Brexit","wrong1":"operazioni di censura preventiva","wrong2":"test della personalità a fini accademici","wrong3":"diffamazione"},{"id":554,"paragraph":"La digitalizzazione della PA - Capitalismo della sorveglianza: Datagate, Cambridge Analytica e il caso Trump","question":"Quale regolamento dopo il caso Trump ha posto obblighi di diligenza, trasparenza e motivazione in capo a tutti gli intermediari e le piattaforme online:","correct":"Digital Services Act","wrong1":"Digital Markets Act","wrong2":"Artficial Intelligence Act","wrong3":"General Data Protection Regulation"},{"id":555,"paragraph":"La digitalizzazione della PA - Il dato personale tra protezione giuridica e valorizzazione economica","question":"Il dato personale è:","correct":"qualsiasi informazione riguardante una persona fisica, identificata o identificabile, direttamente o indirettamente con particolare riferimento a un identificativo come il nome, un numero di identificazione, dati relativi all'ubicazione, un identificativo online o a uno o più elementi caratteristici dell'identità fisica, fisiologica, genetica, psichica, economica, culturale o sociale","wrong1":"il dato ottenuto da un trattamento tecnico specifico relativi alle caratteristiche fisiche, fisiologiche o comportamentali di una persona fisica che ne consente o conferma l'identificazione univoca, quali l'immagine facciale o i dati dattiloscopici","wrong2":"il dato personale attinente alla salute fisica o mentale di una persona fisica, compresa la prestazione di servizi di assistenza sanitaria, che rivela informazioni relative al suo stato di salute","wrong3":"il dato che, in origine o a seguito di trattamento, non può essere riferito ad una persona fisica identificata o identificabile"},{"id":556,"paragraph":"La digitalizzazione della PA - Il dato personale tra protezione giuridica e valorizzazione economica","question":"In relazione ai dati personali il framework giuridico di riferimento quali istanze persegue:","correct":"sia le istanze di protezione e controllo, sia le istanze di circolazione e apertura","wrong1":"esclusivamente le istanze di protezione e controllo","wrong2":"esclusivamente le istanze di circolazione e apertura","wrong3":"esclusivamente le istanzi negoziali del mercato"},{"id":557,"paragraph":"La digitalizzazione della PA - Il dato personale tra protezione giuridica e valorizzazione economica","question":"Ai sensi della direttiva UE 2019/770 e del relativo d.lgs. 206/2005:","correct":"le norme a tutela del consumatore si applicano anche nel caso in cui, anziché un prezzo, a fronte di un contenuto o servizio digitale il consumatore fornisce o si impegni a fornire dati personali all'operatore economico","wrong1":"le norme a tutela del consumatore si applicano solo nel caso in cui, anziché un prezzo, a fronte di un contenuto o servizio digitale il consumatore fornisce o si impegni a fornire dati personali all'operatore economico (non si applicano pertanto se fornisce un prezzo)","wrong2":"si vieta l'applicazione delle norme a tutela del consumatore nel caso in cui, anziché un prezzo, a fronte di un contenuto o servizio digitale il consumatore fornisce o si impegni a fornire dati personali all'operatore economico","wrong3":"le norme a tutela del consumatore non si applicano nel caso in cui, anziché un prezzo, a fronte di un contenuto o servizio digitale il consumatore fornisce o si impegni a fornire dati personali all'operatore economico"},{"id":558,"paragraph":"La digitalizzazione della PA - La giurisprudenza sulla commerciabilità dei dati personali","question":"Secondo le sentenze del caso AGCM versus Facebook le normative in materia di tutela dei dati personali e di tutela del consumatore in che rapporto si pongono:","correct":"complementarietà quali tutele multilivello","wrong1":"reciproca esclusione","wrong2":"prevale in ogni caso la normativa a tutela del consumatore","wrong3":"si applica esclusivamente la normativa in matera di data protection"},{"id":559,"paragraph":"La digitalizzazione della PA - La giurisprudenza sulla commerciabilità dei dati personali","question":"Tra gli aspetti negativi della commerciabilità dei dati personali non rientra il seguente profilo:","correct":"maggiore autonomia di scelta del soggetto e possibilità di azionare anche tutele della disciplina consumeristica","wrong1":"le caratteristiche del diritto (assoluto, indisponibile, imprescrittibile) creano un argine alla qualifica come bene di scambio","wrong2":"il diritto alla protezione dei dati personali non ha contenuto omogeneo e meramente individuale ed è volto in via strumentale a tutelare interessi eterogenei","wrong3":"stretto rapporto tra il dato personale e la persona con la sua identità, che non gli permette di compierne atti di disposizione"},{"id":560,"paragraph":"La digitalizzazione della PA - La giurisprudenza sulla commerciabilità dei dati personali","question":"Nella direzione della valorizzazione economica dei dati personali le norme in materia di tutela dei dati personali e di tutela del consumatore di cosa si occupano reciprocamente:","correct":"le norme sui dati personali regolano in via sostanziale il mercato dei dati stessi, stabilendo se e quando il loro scambio è ammesso; le norme a tutela dei consumatori regolano le modalità di tale scambio, garantendo trasparenza e accordando determinati rimedi","wrong1":"le norme a tutela dei dati personali non si applicano facendo prevalere la normativa in materia di tutela del consumatore","wrong2":"le norme a tutela dei consumatori regolano in via sostanziale il mercato dei dati stessi, stabilendo se e quando il loro scambio è ammesso; le norme a tutela dei dati personali regolano le modalità di tale scambio, garantendo trasparenza e accordando determinati rimedi","wrong3":"si applica esclusivamente la normativa in matera di data protection"},{"id":561,"paragraph":"La digitalizzazione della PA - Metaverso e metaversi","question":"Il metaverso può essere definito come:","correct":"uno spazio digitale virtuale multidimensionale, condiviso, persistente e interattivo, in cui gli utenti possono interagire tra loro e con l'ambiente mediante avatar digitali","wrong1":"asset o unità digitale unica e indivisibile basata sulla tecnologia blockchain che funge da certificato digitale di autenticità o proprietà di un bene, volto a identificare in modo univoco, insostituibile e non replicabile la proprietà di un prodotto digitale o di un'utilità.","wrong2":"sistemi tecnologici che si vanno ad integrare con la percezione umana per aumentare lo spettro di percezione, introducendo elementi di realtà digitale nell'ambiente reale.","wrong3":"\"catena di blocchi\", registro o libro mastro digitale in cui i dati, inseriti per mezzo della crittografia asimmetrica, sono allocati in blocchi, accompagnati da hash e timestamp , tra loro concatenati attraverso la validazione temporale e il richiamo dell'hash del blocco precedente in quello successivo"},{"id":562,"paragraph":"La digitalizzazione della PA - Metaverso e metaversi","question":"Il Non-Fungible Token (NFT) è:","correct":"asset o unità digitale unica e indivisibile basata sulla tecnologia blockchain che funge da certificato digitale di autenticità o proprietà di un bene, volto a identificare in modo univoco, insostituibile e non replicabile la proprietà di un prodotto digitale o di un'utilità","wrong1":"sistemi tecnologici che si vanno ad integrare con la percezione umana per aumentare lo spettro di percezione, introducendo elementi di realtà digitale nell'ambiente reale.","wrong2":"uno spazio digitale virtuale multidimensionale condiviso, persistente e interattivo, in cui gli utenti possono interagire tra loro e con l'ambiente mediante avatar digitali.","wrong3":"\"catena di blocchi\", registro o libro mastro digitale in cui i dati, inseriti per mezzo della crittografia asimmetrica, sono allocati in blocchi, accompagnati da hash e timestamp , tra loro concatenati attraverso la validazione temporale e il richiamo dell'hash del blocco precedente in quello successivo ."},{"id":563,"paragraph":"La digitalizzazione della PA - Metaverso e metaversi","question":"Non rientra tra i problemi sollevati specificamente dal metaverso:","correct":"diritto di accesso a Internet","wrong1":"protezione dei dati personali","wrong2":"tutela della proprietà intellettuale","wrong3":"possibili condotte illecite, reati e responsabilità penale"},{"id":564,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"Le decisioni assunte dai rappresentanti eletti:","correct":"vengono operativamente implementate da parte dell'apparato amministrativo","wrong1":"sono spesso ignorate o sostituite da quelle del personale amministrativo durante la fase di implementazione","wrong2":"sono frequentemente intraprese in modo indipendente dall'apparato amministrativo","wrong3":"vengono poi formalmente ratificate senza un effettivo scrutinio democratico"},{"id":565,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"La definizione degli obiettivi strategici di un' APT:","correct":"è prerogativa dei rappresentanti eletti e dei loro delegati, riflettendo così le scelte dell'ente economico aziendale","wrong1":"è spesso lasciata alla discrezione esclusiva dei tecnici e dei consulenti esterni, senza coinvolgimento diretto dei rappresentanti eletti o dei loro delegati","wrong2":"è assunta spesso in modo indipendente da enti sovranazionali, senza considerare le preferenze e le decisioni dei rappresentanti locali eletti e dei loro delegati","wrong3":"è frequentemente determinata dalle pressioni del mercato o delle associazioni di categoria"},{"id":566,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"La missione, la visione e le strategie di governance delle APT:","correct":"sono di competenza esclusiva degli organi politici","wrong1":"sono determinate principalmente dalle influenze del settore privato e dai loro interessi economici, piuttosto che dagli organi politici","wrong2":"sono spesso delegate a consulenti esterni o a comitati tecnici, minimizzando il ruolo degli organi politici nella definizione di tali direttive","wrong3":"sono il risultato di negoziati con enti sovrannazionali o organizzazioni internazionali"},{"id":567,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"L'elemento territoriale:","correct":"non è solo una delimitazione geografica, ma è il fulcro attorno al quale si costruiscono e si esercitano le potestà pubbliche delle APT","wrong1":"rappresenta unicamente una delimitazione geografica, senza influenzare significativamente le decisioni o le potestà pubbliche esercitate dalle APT","wrong2":"richiede l'applicazione di politiche nazionali uniformi che non tengono conto delle specificità locali","wrong3":"è considerato marginale nelle strategie delle APT, che basano le loro decisioni principalmente su dinamiche economiche globali piuttosto che su considerazioni geografiche locali"},{"id":568,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"Indicare la risposta più adatta:","correct":"molte APT godono di autonomia fiscale, che include la capacità di riscuotere imposte, tasse e altri introiti locali","wrong1":"molte APT sono strettamente regolate dal governo centrale e non dispongono della capacità di riscuotere imposte","wrong2":"molte APT godono di autonomia fiscale, che include la capacità di riscuotere imposte, tasse e altri introiti locali, ma non di autonomia amministrativa","wrong3":"a maggior parte delle APT non ha effettiva capacità di implementare tassazioni o di generare introiti significativi, risultando così fortemente dipendenti da sovvenzioni governative per qualsiasi operazione finanziaria."},{"id":569,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"Le APT:","correct":"si configurano come enti produttori di servizi pubblici","wrong1":"non si occupano direttamente della produzione di servizi pubblici essenziali","wrong2":"agiscono principalmente come enti di regolamentazione e non come produttori diretti di servizi pubblici","wrong3":"non sono coinvolte nell'operatività quotidiana di servizi pubblici"},{"id":570,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"In Italia:","correct":"le competenze sono spesso sovrapposte tra il governo centrale e le Regioni","wrong1":"le competenze sono nettamente divise e non si verifica alcuna sovrapposizione tra il governo centrale e le Regioni","wrong2":"le Regioni hanno solo funzioni consultive o simboliche senza alcuna autorità decisionale reale","wrong3":"Le Regioni operano con piena indipendenza dal governo centrale, senza alcuna intersezione o condivisione di competenze"},{"id":571,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"La riforma del 2001:","correct":"ha segnato il passaggio da un modello centralizzato a uno più decentralizzato","wrong1":"ha rafforzato il modello centralizzato esistente in Italia","wrong2":"non ha introdotto significativi cambiamenti nella governance italiana","wrong3":"ha aumentato il controllo del governo centrale su aree che erano tradizionalmente delegate alle autorità regionali e comunali"},{"id":572,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"Il fulcro della riforma costituzionale del 2001 è stato:","correct":"l'introduzione e l'accentuazione del principio di sussidiarietà verticale","wrong1":"il rafforzamento del controllo centrale, limitando l'applicazione del principio di sussidiarietà verticale e concentrando maggior potere nelle mani del governo nazionale","wrong2":"il passaggio verso una maggiore standardizzazione delle politiche amministrative su tutto il territorio nazionale, senza differenziazioni locali","wrong3":"la centralizzazione delle funzioni amministrative senza delegare significative competenze ai livelli governativi inferiori"},{"id":573,"paragraph":"La digitalizzazione della PA - Le amministrazioni pubbliche territoriali e la riforma del 2001","question":"Indicare la risposta più adatta:","correct":"la competenza nella gestione delle risorse e nell'amministrazione pubblica non è uniforme","wrong1":"competenza nella gestione delle risorse e nell'amministrazione pubblica è uniformemente distribuita tra tutti gli enti locali","wrong2":"tutti gli enti locali affrontano significative carenze nel personale qualificato e nei sistemi di gestione, risultando in una gestione delle risorse uniformemente inefficace e poco efficace su tutto il territorio nazionale","wrong3":"le variazioni regionali, la competenza nella gestione delle risorse e nell'amministrazione pubblica è stata standardizzata grazie a interventi statali"},{"id":574,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"L'individuazione degli atti da sottoporre all'esame della Corte dei conti per un periodo determinato è effettuata:","correct":"Con deliberazione motivata delle Sezioni Riunite","wrong1":"Con deliberazione motivata del Presidente della Corte dei conti","wrong2":"Con deliberazione motivata del Procuratore Generale","wrong3":"Con deliberazione motivata del Consiglio di Presidenza"},{"id":575,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Il controllo a fini di riesame ha a oggetto singoli atti di notevole rilievo:","correct":"Finanziario","wrong1":"Giuridico","wrong2":"Politico","wrong3":"Istituzionale"},{"id":576,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Gli atti da sottoporre all'esame della Corte dei conti sono individuati:","correct":"Per categorie ed amministrazioni statali","wrong1":"Mediante sorteggio","wrong2":"Mediante campionamento statistico","wrong3":"Mediante rotazione"},{"id":577,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Gli atti adottati dalle amministrazioni a seguito del riesame:","correct":"Sono trasmessi alla Corte dei conti","wrong1":"Sono trasmessi al Ministro","wrong2":"Sono trasmessi al Presidente del Consiglio dei Ministri","wrong3":"Sono trasmessi al Parlamento"},{"id":578,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Ove la Corte dei conti rilevi l'illegittimità degli atti trasmessile a seguito di esame:","correct":"Ne dà avviso al Ministro","wrong1":"Ne dà avviso al Governo","wrong2":"Ne dà avviso al Presidente del Consiglio dei Ministri","wrong3":"Ne dà avviso al Parlamento"},{"id":579,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"La Corte dei conti può richiedere il riesame di atti ritenuti non conformi a legge:","correct":"Di amministrazioni territoriali","wrong1":"Di amministrazioni non territoriali","wrong2":"Di tutte le amministrazioni sia territoriali che non territoriali","wrong3":"Soltanto delle amministrazioni dello Stato"},{"id":580,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Gli atti adottati dalle amministrazioni non territoriali a seguito del riesame:","correct":"Sono trasmessi alla Corte dei conti","wrong1":"Sono trasmessi al Ministro competente per materia","wrong2":"Sono trasmessi al Presidente del Consiglio dei Ministri","wrong3":"Sono trasmessi al Parlamento"},{"id":581,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"Ove la Corte dei conti rilevi l'illegittimità degli atti delle amministrazioni non territoriali trasmessile a seguito di riesame:","correct":"Ne dà avviso all'organo generale di direzione dell'ente","wrong1":"Ne dà avviso al Presidente del Consiglio dei Ministri","wrong2":"Ne dà avviso al Ministro competente per materia","wrong3":"Ne dà avviso al Parlamento"},{"id":582,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"La Corte dei conti svolge il controllo successivo sulla gestione:","correct":"Del bilancio delle amministrazioni pubbliche","wrong1":"Del bilancio delle sole amministrazioni pubbliche statali","wrong2":"Del bilancio delle sole amministrazioni pubbliche statali e regionali ordinarie","wrong3":"Del bilancio delle sole amministrazioni pubbliche statali e non territoriali"},{"id":583,"paragraph":"Contratti della PA - Controlli sulla gestione della Corte dei Conti","question":"La Corte dei conti nell'ambito del controllo successivo sulla gestione, non verifica:","correct":"La legittimità di ogni atto gestionale","wrong1":"La legittimità della gestione","wrong2":"La regolarità della gestione","wrong3":"Il funzionamento dei controlli interni"},{"id":584,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione il rapporto di servizio rilevante ai fini del radicamento della giurisdizione della Corte dei conti:","correct":"Può investire anche un soggetto estraneo alla pubblica amministrazione","wrong1":"Non può investire un soggetto estraneo alla pubblica amministrazione","wrong2":"Può investire soltanto un soggetto estraneo alla pubblica amministrazione","wrong3":"Può investire soltanto un soggetto intraneo alla pubblica amministrazione"},{"id":585,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione il rapporto di servizio rilevante ai fini del radicamento della giurisdizione della Corte dei conti:","correct":"Può essere dato anche da una relazione esclusivamente funzionale","wrong1":"Può essere dato esclusivamente da una relazione organica","wrong2":"Non può essere dato da una relazione organica","wrong3":"Può essere dato esclusivamente da una relazione funzionale"},{"id":586,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione ai fini del radicamento della giurisdizione della Corte dei conti:","correct":"Rileva la natura giuridica dell'atto di investitura","wrong1":"Non rileva la natura giuridica dell'atto di investitura","wrong2":"È richiesta la natura giuridica pubblica dell'atto di investitura","wrong3":"Non è ammessa la natura giuridica pubblica dell'atto di investitura"},{"id":587,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione ai fini del radicamento della giurisdizione della Corte dei conti l'atto di investitura non può essere:","correct":"Una dichiarazione politica","wrong1":"Un provvedimento","wrong2":"Una convenzione","wrong3":"Un contratto"},{"id":588,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione ai fini del radicamento della giurisdizione della Corte dei conti l'investitura rilevante:","correct":"È anche quella di fatto","wrong1":"È soltanto quella di diritto","wrong2":"È soltanto quella diritto pubblico","wrong3":"Non può avere natura privatistica"},{"id":589,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione ai fini del radicamento della giurisdizione della Corte dei conti la gestione del denaro:","correct":"Non deve necessariamente avvenire secondo moduli contabili di tipo pubblico","wrong1":"Deve avvenire secondo moduli contabili di tipo esclusivamente pubblico","wrong2":"Deve avvenire secondo moduli contabili di tipo esclusivamente privato","wrong3":"Deve avvenire secondo moduli contabili di tipo esclusivamente armonizzato"},{"id":590,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio delle Sezioni Unite della Cassazione la concessione:","correct":"È idonea a radicare la giurisdizione della Corte dei conti","wrong1":"È idonea a radicare la giurisdizione della Corte dei conti soltanto se il concessionario è una società in house","wrong2":"È idonea a radicare la giurisdizione della Corte dei conti soltanto se il concessionario è una società pubblica","wrong3":"Non è idonea a radicare la giurisdizione della Corte dei conti"},{"id":591,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al più recente approccio sancito dalle Sezioni Unite della Cassazione giurisdizione della Corte dei conti:","correct":"Prescinde dalla natura pubblica del soggetto responsabile","wrong1":"Presuppone la natura pubblica del soggetto responsabile","wrong2":"Esclude la natura privata del soggetto responsabile","wrong3":"Esclude la natura pubblica del soggetto responsabile"},{"id":592,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al codice civile l'esercizio dell'azione sociale di responsabilità da parte del socio:","correct":"Non è obbligatorio quand'anche in presenza di danni","wrong1":"È obbligatorio in presenza di danni","wrong2":"È vietato in presenza di danni","wrong3":"È precluso al socio pubblico"},{"id":593,"paragraph":"Contratti della PA - La giurisdizione contabile sulle esternalizzazioni societarie e sui privati percettori di contributi finalizzati","question":"In base al codice civile l'esercizio dell'azione sociale di responsabilità da parte del socio:","correct":"È ammesso anche per colpa lieve","wrong1":"È ammesso soltanto per negligenza inescusabile","wrong2":"È ammesso soltanto per dolo","wrong3":"È ammesso soltanto per colpa grave"},{"id":594,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Il fatto dannoso:","correct":"Incorpora un nesso di causalità tra condotta e danno","wrong1":"Consiste nella sola condotta illecita","wrong2":"Consiste nel solo danno erariale","wrong3":"Prescinde dal nesso di causalità tra condotta e danno"},{"id":595,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Tra i criteri di individuazione del soggetto pubblico danneggiato vi è quello:","correct":"Della natura pubblica delle risorse delle quali si avvale per lo svolgimento della sua attività","wrong1":"Della forma giuridica pubblica","wrong2":"Della veste giuridica di diritto pubblico","wrong3":"Della natura privata delle risorse delle quali si avvale per lo svolgimento della sua attività"},{"id":596,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Tra i criteri di individuazione del soggetto pubblico danneggiato vi è quello:","correct":"Dello svolgimento di una funzione o servizio pubblico volto al soddisfacimento di pubblici interessi","wrong1":"Dell'essere un soggetto privato concessionario di un servizio pubblico","wrong2":"Del reperimento di fondi di provenienza privata","wrong3":"Della limitazione dell'operatività su una determinata area territoriale"},{"id":597,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Il danno erariale:","correct":"Può avere natura non patrimoniale","wrong1":"Ha necessariamente natura patrimoniale","wrong2":"Non può avere natura patrimoniale","wrong3":"Può avere natura patrimoniale soltanto a determinate condizioni"},{"id":598,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Il danno erariale:","correct":"Non costituisce oggetto di tipizzazione legislativa salve alcune fattispecie espressamente previste dal legislatore","wrong1":"è configurabile nelle sole fattispecie individuate espressamente dalla legge","wrong2":"Non costituisce oggetto di tipizzazione legislativa","wrong3":"Non è necessario per la configurazione della responsabilità amministrativa in presenza di condotta illecita"},{"id":599,"paragraph":"Contratti della PA - Il fatto dannoso","question":"La natura risarcitoria della responsabilità amministrativa comporta la sua finalizzazione:","correct":"Al ripristino per equivalente pecuniario della originaria integrità del patrimonio pubblico leso","wrong1":"Alla punizione del condannato con una condanna il cui importo può anche superare il valore del danno cagionato","wrong2":"Alla estromissione del condannato dai pubblici uffici","wrong3":"Alla estromissione del condannato dai pubblici uffici che comportano gestione di denaro pubblico"},{"id":600,"paragraph":"Contratti della PA - Il fatto dannoso","question":"La cognizione della Corte dei conti:","correct":"è estesa anche a fattispecie di responsabilità sanzionatoria espressamente previste dal legislatore","wrong1":"è limitata alla sola responsabilità di natura risarcitoria","wrong2":"è limitata alla sola responsabilità di natura sanzionatoria","wrong3":"Ha natura sanzionatoria generalizzata"},{"id":601,"paragraph":"Contratti della PA - Il fatto dannoso","question":"La responsabilità sanzionatoria innanzi alla Corte dei conti:","correct":"è configurabile nei soli casi nei quali la legge espressamente la prevede","wrong1":"è configurabile ogni qualvolta sia accertato un danno erariale","wrong2":"è sempre configurabile in presenza di danni erariali di particolare gravità","wrong3":"è sempre configurabile in presenza di dolo"},{"id":602,"paragraph":"Contratti della PA - Il fatto dannoso","question":"Il potere riduttivo dell'addebito:","correct":"Può essere esercitato anche quando la Corte abbia riconosciuto la compensatio lucri cum damno","wrong1":"Non può essere esercitato quando la Corte abbia riconosciuto la compensatio lucri cum damno","wrong2":"Deve essere esercitato quando la Corte abbia riconosciuto la compensatio lucri cum damno","wrong3":"Non può essere esercitato quando la Corte abbia riconosciuto la compensatio lucri cum damno, salvo che in presenza di determinate condizioni stabilite dalla legge"},{"id":603,"paragraph":"Contratti della PA - Il fatto dannoso","question":"La compensatio lucri cum damno impone al Giudice contabile di tenere conto, a scomputo dell'addebito:","correct":"Dei vantaggi comunque conseguiti dall'amministrazione di appartenenza, da altra amministrazione o dalla comunità amministrata","wrong1":"Dei vantaggi comunque conseguiti dalla sola amministrazione di appartenenza","wrong2":"Dei vantaggi comunque conseguiti da altre amministrazioni, esclusa quella di appartenenza","wrong3":"Dei vantaggi comunque conseguiti da terzi privati"},{"id":604,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"La Costituzione riconosce alla Corte dei conti funzioni di:","correct":"Controllo preventivo","wrong1":"Controllo concomitante","wrong2":"Controllo legislativo","wrong3":"Controllo costituzionale"},{"id":605,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"La Costituzione riconosce alla Corte dei conti funzioni di controllo:","correct":"Di legittimità","wrong1":"Di qualità","wrong2":"Di quantità","wrong3":"Di serietà"},{"id":606,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Il controllo di legittimità della Corte dei conti concerne gli atti:","correct":"Governativi","wrong1":"Parlamentari","wrong2":"Di rilevanza costituzionale","wrong3":"Di rilevanza nazionale"},{"id":607,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Sono soggetti a controllo preventivo di legittimità:","correct":"Gli atti non aventi forza di legge","wrong1":"Gli atti aventi forza di legge","wrong2":"Gli atti aventi forza di legge costituzionale","wrong3":"Gli atti aventi forza di legge regionale"},{"id":608,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Sono soggetti a controllo preventivo di legittimità:","correct":"I provvedimenti emanati a seguito di deliberazione del Consiglio dei Ministri","wrong1":"I provvedimenti emanati a seguito di deliberazione del Consiglio regionale","wrong2":"Le proposte di provvedimento messe all'ordine del giorno del Consiglio dei Ministri","wrong3":"I provvedimenti emanati a seguito di deliberazione del Consiglio regionale delle sole Regioni a statuto ordinario"},{"id":609,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Non sono soggetti a controllo preventivo di legittimità gli atti del Presidente del Consiglio dei Ministri aventi a oggetto:","correct":"La definizione del programma politico","wrong1":"La definizione delle piante organiche","wrong2":"Il conferimento di incarichi di funzioni dirigenziali","wrong3":"Le direttive generali di indirizzo dell'azione amministrativa"},{"id":610,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Non sono soggetti a controllo preventivo di legittimità gli:","correct":"Atti normativi a rilevanza interna","wrong1":"Atti normativi a rilevanza esterna","wrong2":"Atti dei Ministri aventi a oggetto la definizione delle piante organiche","wrong3":"Atti dei Ministri aventi a oggetto il conferimento di incarichi di funzioni dirigenziali"},{"id":611,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Non sono soggetti a controllo preventivo di legittimità gli:","correct":"Atti di programmazione non comportanti spese","wrong1":"Atti di programmazione comportanti spese","wrong2":"Atti dei Ministri aventi a oggetto le direttive generali di indirizzo dell'azione amministrativa","wrong3":"Provvedimenti dei comitati interministeriali di riparto o assegnazione fondi"},{"id":612,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Non sono soggetti a controllo preventivo di legittimità gli:","correct":"Atti generali attuativi di norme comunitarie","wrong1":"Provvedimenti dispositivi del demanio","wrong2":"Provvedimenti dispositivi del patrimonio immobiliare","wrong3":"Atti specifici attuativi di norme comunitarie"},{"id":613,"paragraph":"Contratti della PA - Il controllo preventivo di legittimità della Corte dei Conti","question":"Non sono soggetti a controllo preventivo di legittimità i decreti che approvano contratti:","correct":"Delle aziende autonomie","wrong1":"Attivi delle Amministrazioni dello Stato","wrong2":"Di appalto d'opera se di importo superiore alla soglia comunitaria","wrong3":"Passivi se di importo superiore a un decimo della soglia comunitaria"},{"id":614,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"La personalità della responsabilità amministrativa si esprime, tra l'altro:","correct":"Nel principio di intrasmissibilità agli eredi dell'obbligazione risarcitoria","wrong1":"Nel principio di trasmissibilità agli eredi dell'obbligazione risarcitoria","wrong2":"Nel principio di trasmissibilità contrattuale a soggetti terzi dell'obbligazione risarcitoria","wrong3":"Nel principio di trasmissibilità contrattuale a soggetti terzi dell'obbligazione risarcitoria anche per fatti concludenti"},{"id":615,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"La personalità della responsabilità amministrativa si esprime, tra l'altro:","correct":"Nel potere del Collegio giudicante riduttivo dell'addebito","wrong1":"Nel potere del Pubblico ministero riduttivo dell'addebito","wrong2":"Nel potere del Collegio giudicante di far gravare l'addebito su soggetti terzi","wrong3":"Nel potere del Collegio giudicante accrescitivo dell'addebito"},{"id":616,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"La personalità della responsabilità amministrativa si esprime, tra l'altro:","correct":"Nella accentuazione dell'elemento psicologico espresso almeno dalla colpa grave","wrong1":"Nella accentuazione dell'elemento psicologico espresso almeno dalla colpa lieve","wrong2":"Nella accentuazione dell'elemento psicologico espresso almeno dal dolo","wrong3":"Nell'esclusione dell'elemento psicologico in ragione del carattere oggettivo della responsabilità"},{"id":617,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"La personalità della responsabilità amministrativa si esprime, tra l'altro:","correct":"Nella regola della responsabilità parziaria","wrong1":"Nella regola della responsabilità oggettiva","wrong2":"Nella eccezione della responsabilità parziaria","wrong3":"Nella regola della responsabilità solidale"},{"id":618,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"La personalità della responsabilità amministrativa si esprime, tra l'altro:","correct":"Nella limitazione del principio di solidarietà passiva ai soli casi di dolo e illecito","wrong1":"Nella estensione generalizzata del principio di solidarietà passiva","wrong2":"Nella esclusione del principio di solidarietà passiva nei casi di dolo","wrong3":"Nella esclusione del principio di solidarietà passiva nei casi di illecito arricchimento"},{"id":619,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"L'obbligazione risarcitoria derivante da responsabilità amministrativa si trasmette agli eredi:","correct":"In caso di illecito arricchimento del dante causa e di conseguente indebito","wrong1":"Sempre","wrong2":"Mai","wrong3":"In caso di illecito arricchimento degli eredi, anche se non dipendente"},{"id":620,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"Il potere riduttivo dell'addebito:","correct":"Spetta al Collegio giudicante","wrong1":"Spetta al Pubblico Ministero","wrong2":"Spetta al Collegio giudicante ma può essere esercitato soltanto su parere favorevole","wrong3":"Spetta al Collegio giudicante ma può essere esercitato soltanto su richiesta congiunta"},{"id":621,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"Il potere riduttivo dell'addebito:","correct":"Non è oggetto di limiti quantitativi fissati dalla legge","wrong1":"Può essere esercitato all'interno di un limite massimo stabilito dalla legge","wrong2":"Può essere esercitato all'interno di un limite massimo e di un limite minimo stabilito dalla legge","wrong3":"Non può essere esercitato al di sotto di un limite minimo stabilito dalla legge"},{"id":622,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"Il potere riduttivo dell'addebito:","correct":"Non è oggetto di predeterminazione legislativa dei casi in cui è esercitabile","wrong1":"Può essere esercitato soltanto nei casi in cui la legge espressamente lo consente","wrong2":"Può essere esercitato soltanto nei casi in cui la legge espressamente lo consente e nei casi analoghi","wrong3":"Non può essere esercitato nei casi in cui la legge espressamente lo vieta"},{"id":623,"paragraph":"Contratti della PA - Personalità della responsabilità amministrativo-contabile","question":"Il potere riduttivo dell'addebito:","correct":"Può essere esercitato anche nei casi di dolo","wrong1":"Non può essere esercitato nei casi di dolo","wrong2":"Deve essere obbligatoriamente esercitato nei casi di colpa lieve","wrong3":"Deve essere obbligatoriamente esercitato nei casi di colpa grave"},{"id":624,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"Fino agli anni '90 i soggetti pubblici erano in prevalenza:","correct":"pubbliche amministrazioni dotate di poteri autoritativi e soggette al diritto amministrativo e alla contabilità pubblica","wrong1":"enti in forma societaria","wrong2":"pubbliche amministrazioni soggette al diritto amministrativo e alla contabilità aziendale","wrong3":"pubbliche amministrazioni soggette al diritto amministrativo ma che potevano optare per la contabilità aziendale"},{"id":625,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"Tra i principali fenomeni che hanno concorso a modificare l'assetto organizzativo e istituzionale del soggetto pubblico vi sono:","correct":"le privatizzazioni","wrong1":"la riforma del diritto societario","wrong2":"la privatizzazione del pubblico impiego","wrong3":"la riforma della s.r.l."},{"id":626,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"Nello scorso millennio la giurisdizione di responsabilità della Corte dei conti riguardava:","correct":"soltanto le pubbliche amministrazioni ma non anche le società pubbliche e gli enti pubblici economici salvo che per i soli poteri autoritativi esercitati","wrong1":"soltanto le pubbliche amministrazioni e gli enti pubblici economici ma non anche le società pubbliche","wrong2":"soltanto le pubbliche amministrazioni e le società pubbliche ma non anche gli enti pubblici economici","wrong3":"soltanto le pubbliche amministrazioni ma non anche le società pubbliche e gli enti pubblici economici"},{"id":627,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"In passato la giurisdizione di responsabilità della Corte dei conti era radicata in base:","correct":"alla soggezione dell'ente danneggiato alle regole di contabilità pubblica e alla sussistenza di un rapporto di pubblico impiego con il soggetto danneggiante","wrong1":"alla soggezione dell'ente danneggiato alle regole di contabilità pubblica","wrong2":"alla natura pubblica delle risorse impiegate dall'ente danneggiato","wrong3":"alla natura pubblica delle finalità perseguite dall'ente danneggiato"},{"id":628,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"Ora la giurisdizione di responsabilità della Corte dei conti è radicata in base:","correct":"alla natura pubblica delle risorse impiegate e delle finalità istituzionali perseguite dall'ente danneggiato e all'incardinamento funzionale del soggetto danneggiante nell'assetto organizzativo attraverso cui la PA persegue le proprie finalità istituzionali","wrong1":"alla soggezione dell'ente danneggiato alle regole di contabilità pubblica","wrong2":"alla soggezione dell'ente danneggiato alle regole di contabilità pubblica e alla sussistenza di un rapporto di pubblico impiego con il soggetto danneggiante","wrong3":"lla natura pubblica delle risorse impiegate"},{"id":629,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"Nel nostro ordinamento la responsabilità amministrativa:","correct":"non può derivare soltanto dal fatto che le risorse finanziarie utilizzate sono pubbliche, essendo necessario che il responsabile sia parte di un rapporto di servizio con una PA","wrong1":"può derivare anche soltanto dal fatto che le risorse finanziarie utilizzate sono pubbliche","wrong2":"non può sussistere se il soggetto riceve finanziamenti pubblici","wrong3":"può riguardare soltanto i dipendenti pubblici"},{"id":630,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"In base all'approccio sancito dalle Sezioni Unite della Cassazione nella sentenza 19667/2003 la responsabilità amministrativa:","correct":"prescinde dalla natura pubblica o privata del titolo giuridico del rapporto","wrong1":"presuppone la natura pubblica del titolo giuridico del rapporto","wrong2":"presuppone la natura pubblica del soggetto","wrong3":"esclude la natura privata del soggetto"},{"id":631,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"In base all'approccio sancito dalle Sezioni Unite della Cassazione nella sentenza 19667/2003 la responsabilità amministrativa:","correct":"prescinde dalla natura autoritativa dell'attività svolta","wrong1":"presuppone la natura autoritativa dell'attività svolta","wrong2":"esclude la natura privata dell'attività svolta","wrong3":"esclude la natura autoritativa dell'attività svolta"},{"id":632,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"In base all'approccio sancito dalle Sezioni Unite della Cassazione nella sentenza 19667/2003 la responsabilità amministrativa tra i criteri di discrimine tra la giurisdizione ordinaria e quella contabile vi è:","correct":"la qualità del soggetto passivo","wrong1":"la veste giuridica del soggetto attivo","wrong2":"la qualità sia del soggetto attivo che del soggetto passivo","wrong3":"la qualità del soggetto attivo"},{"id":633,"paragraph":"Contratti della PA - La giurisdizione contabile su enti pubblici economici e società a partecipazione pubblica","question":"In base all'approccio sancito dalle Sezioni Unite della Cassazione nella sentenza 19667/2003 la responsabilità amministrativa tra i criteri di discrimine tra la giurisdizione ordinaria e quella contabile vi è:","correct":"la natura pubblica delle risorse finanziarie di cui si avvale il soggetto passivo","wrong1":"la natura privata delle risorse finanziarie di cui si avvale il soggetto passivo","wrong2":"la natura privata delle risorse finanziarie di cui si avvale il soggetto attivo","wrong3":"la natura pubblica delle risorse finanziarie di cui si avvale il soggetto attivo"},{"id":634,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Quale delle seguenti azioni non ha attinenza con la strategia di contrasto alla corruzione adottata dal legislatore italiano:","correct":"collaborare con le autorità internazionali per la repressione dei reati di corruzione internazionale","wrong1":"creare un contesto sfavorevole alla corruzione","wrong2":"aumentare la capacità di rilevare casi di corruzione","wrong3":"ridurre le opportunità che si manifestino casi di corruzione"},{"id":635,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Il primo Piano Nazionale Anticorruzione è stato approvato nel:","correct":"2013","wrong1":"1992","wrong2":"1946","wrong3":"2000"},{"id":636,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Il Piano Nazionale Anticorruzione:","correct":"fornisce indirizzi e supporto alle amministrazioni pubbliche per la prevenzione della corruzione sul piano locale","wrong1":"disciplina le modalità dell'accesso civico alle informazioni in possesso delle amministrazioni","wrong2":"contiene i principi per la repressione della corruzione","wrong3":"attua le direttive della Corte Costituzionale in materia di prevenzione della corruzione"},{"id":637,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Nei comuni con popolazione inferiore ai 5.000 abitanti, per consentire il migliore esercizio delle funzioni di RPCT:","correct":"può essere prevista, con provvedimento motivato, la figura del referente del RPCT","wrong1":"è prevista una deroga al divieto di rinnovo dell'incarico di RPCT","wrong2":"il segretario comunale può delegare le funzioni di RPCT ad un assessore","wrong3":"le funzioni di segretario comunale non possono essere esercitate in convenzione"},{"id":638,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Il Piano Nazionale Anticorruzione 2019 contiene, tra l'altro:","correct":"nuove indicazioni metodologiche per la gestione dei rischi corruttivi, che sostituiscono quelle contenute nel P.N.A. 2013","wrong1":"modifiche alle competenze dei segretari comunali in materia di prevenzione della corruzione","wrong2":"specifiche indicazioni operative in materia di prevenzione delle violazioni del codice degli appalti","wrong3":"una nuova disciplina del reato di abuso d'ufficio"},{"id":639,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Le situazioni rilevanti ai fini della prevenzione della corruzione:","correct":"sono più ampie delle fattispecie penali disciplinate nel Titolo II, Capo I, del codice penale","wrong1":"riguardano specifiche condotte poste in essere nell'ambito degli uffici pubblici","wrong2":"corrispondono alle fattispecie di reato contemplate dal codice penale in materia di repressione della corruzione","wrong3":"coincidono con il reato di cui all'art. 323 del codice penale"},{"id":640,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Ai sensi del P.N.A. del 2013, la prevenzione della corruzione riguarda:","correct":"tutte le situazioni in cui, nel corso dell'attività amministrativa, si rischi l'abuso da parte di un soggetto del potere a lui affidato al fine di ottenere vantaggi privati","wrong1":"le situazioni che sono riconducibili al reato di corruzione","wrong2":"tutte le situazioni in cui si rischi la compromissione degli obiettivi stabiliti nel Piano della performance dell'amministrazione","wrong3":"le condotte che non assumono rilevanza sul piano penale"},{"id":641,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Il Piano Triennale di Prevenzione della Corruzione (PTPC) è un documento programmatico predisposto:","correct":"da ogni pubblica amministrazione","wrong1":"dai comuni","wrong2":"dalle amministrazioni centrali dello Stato","wrong3":"dall'ANAC"},{"id":642,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Il Piano Triennale di Prevenzione della Corruzione (PTPC) ha ad oggetto:","correct":"il complesso delle misure anticorruzione obbligatorie per legge nonché delle misure specifiche adottate secondo le peculiarità di ciascuna amministrazione","wrong1":"esclusivamente le misure anticorruzione obbligatorie per legge","wrong2":"il complesso delle misure per prevenire il rischio che vengano commessi reati di corruzione nell'ambito degli uffici pubblici","wrong3":"esclusivamente le misure specifiche adottate da ciascuna amministrazione in funzione delle sue peculiarità"},{"id":643,"paragraph":"Contratti della PA - La legge n. 190/2012 e gli strumenti di prevenzione della corruzione","question":"Ai fini dell'aggiornamento del PTPC non bisogna tenere conto:","correct":"dei risultati dell'azione amministrativa in termini di perseguimento dei target di efficacia fissati nel Piano degli obiettivi","wrong1":"di eventuali modifiche alla disciplina normativa in materia di prevenzione della corruzione","wrong2":"dell'emersione di nuovi fattori di rischio rispetto a quelli considerati in fase di predisposizione del precedente PTPC","wrong3":"di cambiamenti normativi e regolamentari che modificano le attribuzioni dell'Amministrazione"},{"id":644,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"L'art. 54-bis del d.lgs. n. 165 del 2001, introdotto dall'art. 1, comma 51, della legge n. 190/2012, rubricato \"Tutela del dipendente pubblico che segnala illeciti\", prescrive:","correct":"di tutelare l'anonimato del dipendente segnalante e vieta discriminazioni nei suoi confronti","wrong1":"di tutelare esclusivamente l'anonimato del dipendente segnalante","wrong2":"il divieto di discriminazioni nei confronti del dipendente segnalante senza tutelarne l'anonimato","wrong3":"anche la tutela del dirigente che riceve la segnalazione"},{"id":645,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"La figura del dipendente che segnala illeciti è fondamentale ai fini del più efficace contrasto ai fenomeni corruttivi poiché:","correct":"operando all'interno dell'organizzazione amministrativa ha maggiori opportunità di venire a conoscenza di condotte illecite","wrong1":"si presume che l'unico modo per prevenire la corruzione sia la delazione","wrong2":"vale la regola della presunzione di colpevolezza dell'incolpato","wrong3":"ha contatti diretti con i collaboratori e consulenti esterni dell'amministrazione"},{"id":646,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"L'art. 54-bis del d.lgs. n. 165 del 2001 vieta qualsiasi provvedimento dal quale possano derivare, direttamente o indirettamente:","correct":"effetti negativi sul rapporto e sulle condizioni di lavoro del dipendente che segnala illeciti","wrong1":"improprie promozioni di dipendenti","wrong2":"rotazioni di personale non autorizzate","wrong3":"nomine al vertice degli uffici di dipendenti senza requisiti"},{"id":647,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"Al fine di rafforzare la tutela del dipendente che segnala illeciti, l'art. 54-bis del d.lgs. n. 165 del 2001 impone all'amministrazione che adotta una misura punitiva nei suoi confronti:","correct":"di dimostrare che la misura discriminatoria o ritorsiva adottata è stata motivata da ragioni estranee alla segnalazione","wrong1":"di dimostrare di essere in buona fede","wrong2":"di dimostrare di non aver adottato mai misure discriminatorie in precedenza","wrong3":"di comunicare la misura adottata all'ANAC"},{"id":648,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"Nell'ambito del procedimento disciplinare, l'identità del dipendente che segnala illeciti:","correct":"non può essere rivelata, fatta esclusione per l'ipotesi in cui la contestazione sia fondata, in tutto o in parte, sulla segnalazione e la conoscenza dell'identità del segnalante sia indispensabile per la difesa dell'incolpato","wrong1":"può essere rivelata","wrong2":"non può essere rivelata","wrong3":"può essere rivelata solo su autorizzazione del dirigente dell'ufficio a cui è assegnato"},{"id":649,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"La segnalazione dell'illecito può essere effettuata da parte del dipendente:","correct":"al Responsabile della prevenzione della corruzione e della trasparenza, all'ANAC e Autorità Giudiziaria ordinaria e contabile","wrong1":"esclusivamente all'ANAC","wrong2":"al solo Responsabile della prevenzione della corruzione e della trasparenza","wrong3":"all'organo di indirizzo politico dell'amministrazione"},{"id":650,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"Qualora l'ANAC accerti l'adozione di una misura discriminatoria nei confronti del dipendente che segnala illeciti, fermi restando gli altri profili di responsabilità, l'ANAC applica al responsabile che ha adottato tale misura:","correct":"una sanzione amministrativa pecuniaria da 5.000 a 30.000 euro","wrong1":"un reclamo verbale","wrong2":"la sanzione disciplinare del licenziamento","wrong3":"una sanzione amministrativa di importo non inferiore a 10.000 euro"},{"id":651,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"L'attività di formazione in materia di prevenzione della corruzione è erogata dall'amministrazione:","correct":"prioritariamente al personale maggiormente coinvolto nei processi a rischio corruzione","wrong1":"ai dipendenti con rapporto di lavoro a tempo pieno","wrong2":"a tutti i dipendenti, esclusi quelli di categoria A e B","wrong3":"ai dipendenti a tempo indeterminato"},{"id":652,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"La rotazione dei dirigenti e dei funzionari nei settori particolarmente esposti alla corruzione è misura applicabile:","correct":"a tutte le amministrazioni pubbliche di cui all'art. 1, comma 2, del d.lgs. 30 marzo 2001, n. 165","wrong1":"alle sole pubbliche amministrazioni centrali","wrong2":"esclusivamente a comuni, province e regioni","wrong3":"a tutte le pubbliche amministrazioni"},{"id":653,"paragraph":"Contratti della PA - Misure generali di prevenzione del rischio: segnalazione di illeciti da parte dei dipendenti, formazione e rotazione del personale","question":"Nei casi in cui la rotazione è oggettivamente non praticabile, specie all'interno di amministrazioni di piccole dimensioni, il P.N.A. 2019 prescrive:","correct":"l'adozione di misure alternative, per evitare che il soggetto non sottoposto a rotazione abbia il controllo esclusivo dei processi","wrong1":"il controllo su tutti gli atti dei dipendente da parte dell'organo di indirizzo politico-amministrativo","wrong2":"il controllo su tutti gli atti dei dipendente da parte del RPCT","wrong3":"di ricorrere a misure sanzionatorie più repressive in caso di violazioni del PTPC"},{"id":654,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Non costituisce espressione del principio di trasparenza dell'azione amministrativa, ai sensi della legge n. 241/90, l'obbligo dell'amministrazione:","correct":"di assicurare la rotazione del personale","wrong1":"di rendere noto il termine entro cui deve essere concluso il procedimento","wrong2":"di motivazione dei provvedimenti amministrativi","wrong3":"di comunicare il nominativo del responsabile del procedimento"},{"id":655,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"L'obbligo, previsto dall'art. 10-bis della legge n. 241/90, di comunicare tempestivamente agli istanti, prima della formale adozione di un provvedimento negativo, i motivi che ostano all'accoglimento della domanda:","correct":"consente la presentazione di osservazioni scritte e/o documenti, del cui mancato accoglimento deve essere data ragione nella motivazione del provvedimento finale","wrong1":"è espressione del principio di legalità dell'azione amministrativa","wrong2":"ha la sola finalità di consentire la presentazione di osservazioni che l'amministrazione non ha l'obbligo di valutare","wrong3":"ha una finalità meramente informativa, senza possibilità per l'istante di intervenire nel procedimento"},{"id":656,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Il diritto di accesso ai documenti amministrativi è il diritto degli interessati:","correct":"di prendere visione e di estrarre copia di documenti amministrativi","wrong1":"di prendere solo visione dei documenti amministrativi","wrong2":"di conoscere da quale ufficio dell'amministrazione sono detenuti i documenti amministrativi","wrong3":"di ottenere la correzione di documenti amministrativi erronei"},{"id":657,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Il diritto di accesso ai documenti amministrativi ha la finalità:","correct":"di assicurare l'imparzialità e la trasparenza dell'attività della pubblica amministrazione e di favorire la partecipazione dei cittadini alla funzione pubblica e il controllo sulla stessa","wrong1":"di assicurare la trasparenza dell'azione amministrativa","wrong2":"di assicurare l'imparzialità dell'azione amministrativa","wrong3":"di favorire la partecipazione dei cittadini alla funzione pubblica"},{"id":658,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Ai fini dell'esercizio del diritto di accesso:","correct":"deve esistere un interesse giuridicamente rilevante del richiedente ed un rapporto di strumentalità tra tale interesse e la documentazione di cui si chiede l'accesso","wrong1":"è sufficiente che l'interessato abbia la cittadinanza italiana","wrong2":"non è rischiesto alcun requisito in capo all'interessato","wrong3":"deve esistere un interesse astratto del richiedente"},{"id":659,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Le istanze di accesso preordinate ad un generico controllo sull'attività amministrativa:","correct":"non sono mai ammesse","wrong1":"sono ammesse solo nei casi espressamente individuati dalla legge n. 241/90","wrong2":"sono sempre ammesse","wrong3":"sono ammesse quando il richiedente ha rapporti di collaborazione con la pubblica amministrazione"},{"id":660,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Non rientrano tra le ipotesi di esclusione dei diritto di accesso ai sensi dell'art. 24 della legge n. 241/90:","correct":"i documenti contenenti dati sensibili","wrong1":"l'attività della pubblica amministrazione diretta all'emanazione di atti normativi, amministrativi generali, di pianificazione e di programmazione","wrong2":"nei procedimenti selettivi, nei confronti dei documenti amministrativi contenenti informazioni di carattere psicoattitudinale relativi a terzi","wrong3":"i dicumenti relativi ai procedimenti tributari"},{"id":661,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Ai sensi della legge n. 241/90 deve essere comunque garantito ai richiedenti l'accesso ai documenti amministrativi la cui conoscenza:","correct":"sia necessaria per curare o per difendere i propri interessi giuridici","wrong1":"sia preordinata a controllare la correttezza dell'operato della pubblica amministrazione","wrong2":"sia preordinata a controllare la legittimità dell'operato della pubblica amministrazione","wrong3":"serva a consentire una effettiva partecipazione al dibattito pubblico"},{"id":662,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"L'art. 10 del d.lgs. n. 267/2000, oltre ad affermare che tutti gli atti amministrativi degli enti locali sono pubblici, sancisce:","correct":"un più ampio diritto di accesso alle informazioni di cui è in possesso l'amministrazione locale, concernenti le attività da essa svolte o poste in essere da enti, aziende ed organismi che esercitano funzioni di competenza comunale o provinciale","wrong1":"un più ampio diritto di accesso alle informazioni di cui è in possesso l'amministrazione locale, riconosciuto ai soli consiglieri comunali","wrong2":"che l'accesso agli atti debba avvenire senza la richiesta di alcun costo di copia","wrong3":"che l'omessa pubblicazione comporta l'applicazione di una sanzione pecuniaria amministrativa di importo compreso tra 1.000 e 5.000 euro"},{"id":663,"paragraph":"Contratti della PA - Il principio di trasparenza nella L. 241/1990","question":"Avverso il diniego di accesso ai sensi della legge n. 241/9, non è contemplata la seguente forma di tutela:","correct":"ricorso al Prefetto","wrong1":"ricorso al difensore civico se il diniego proviene da un'amministrazione locale o regionale","wrong2":"ricorso alla Commissione per l'accesso ai documenti amministrativise se il diniego proviene da un'amministrazione nazionale,","wrong3":"ricorso al Tribunale Amministrativo Regionale"},{"id":664,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Il d.lgs. 33/2013 disciplina gli obblighi di «pubblicazione», intendendo con tale espressione la pubblicazione nei siti istituzionali delle pubbliche amministrazioni:","correct":"dei documenti, delle informazioni e dei dati concernenti l'organizzazione e l'attività delle pubbliche amministrazioni","wrong1":"dei documenti, delle informazioni e dei dati concernenti l'organizzazione delle pubbliche amministrazioni","wrong2":"dei documenti, delle informazioni e dei dati concernenti l'attività delle pubbliche amministrazioni","wrong3":"di qualsiasi informazione riguardante la pubblica amministrazione e i suoi organi politici"},{"id":665,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Il d.lgs. 33/2013 tutela anche la qualità delle informazioni riportate nei siti istituzionali prevedendo che le amministrazioni devono assicurarne:","correct":"l'integrità, il costante aggiornamento, la completezza, la tempestività, la semplicità di consultazione, la comprensibilità, l'omogeneità, la facile accessibilità, la conformità ai documenti originali, l'indicazione della loro provenienza e la riutilizzabilità","wrong1":"l'integrità, il costante aggiornamento, la completezza e la tempestività","wrong2":"la semplicità di consultazione, la comprensibilità, l'omogeneità, la facile accessibilità","wrong3":"l'integrità, il costante aggiornamento, la completezza, la tempestività, la semplicità di consultazione, la comprensibilità, l'economicità, la facile accessibilità, la conformità ai documenti originali, l'indicazione della loro provenienza e la reperibilità"},{"id":666,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Nella sezione denominata «Amministrazione Trasparente» dei siti web istituzionali delle amministrazioni sono contenuti:","correct":"i dati, le informazioni e i documenti che vanno pubblicati ai sensi della normativa vigente","wrong1":"i documenti i cui effetti legali si producono solo a seguito della pubblicazione","wrong2":"i dati relativi agli organi politico-amministrativi","wrong3":"i provvedimenti amministrativi soggetti ad obbligo di pubblicità"},{"id":667,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Con riferimento agli organi di indirizzo politico-amministrativo, nella sezione «Amministrazione Trasparente» non devono essere pubblicati:","correct":"i dati relativi all'assunzione di altre cariche - presso enti pubblici o privati - ovvero di eventuali incarichi senza oneri a carico della finanza pubblica e i relativi compensi a qualsiasi titolo corrisposti","wrong1":"i compensi di qualsiasi natura connessi all'assunzione della carica","wrong2":"la copia dell'ultima dichiarazione dei redditi","wrong3":"l'attestazione concernente le variazioni della situazione patrimoniale intervenute nell'anno precedente"},{"id":668,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Tra i seguenti dati non sono soggetti ad obbligo di pubblicazione nella sezione «Amministrazione Trasparente»:","correct":"l'elenco degli enti pubblici per i quali l'amministrazione abbia il potere di nomina dell'amministratore delegato","wrong1":"l'elenco degli enti pubblici istituiti, vigilati e finanziati dall'amministrazione","wrong2":"l'elenco degli enti di diritto privato controllati dall'amministrazione","wrong3":"l'elenco delle partecipazioni dell'amministrazione in società di diritto privato"},{"id":669,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"I tempi di pagamento dell'amministrazione relativi agli acquisti di beni, servizi e forniture:","correct":"rientrano tra i dati soggetti ad obbligo di pubblicazione ai sensi del d.lgs. n. 33/2013","wrong1":"non rientrano tra i dati soggetti ad obbligo di pubblicazione","wrong2":"sono soggetti ad obbligo di pubblicazione solo nel caso in cui il loro conteggio medio superi i 30 giorni","wrong3":"sono soggetti ad obbligo di pubblicazione solo nel caso in cui il loro conteggio medio superi i 90 giorni"},{"id":670,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Il Responsabile per la prevenzione della corruzione e della trasparenza segnala i casi di mancato o ritardato adempimento degli obblighi di pubblicazione:","correct":"all'organo di indirizzo politico, all'Organismo indipendente di valutazione (OIV), all'Autorità nazionale anticorruzione e, nei casi più gravi, all'ufficio di disciplina","wrong1":"all'organo di indirizzo politico e all'Autorità nazionale anticorruzione","wrong2":"esclusivamente all'organo di indirizzo politico-amministrativo","wrong3":"all'ufficio di disciplina"},{"id":671,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"L'inadempimento degli obblighi di pubblicazione previsti dalla normativa vigente e il rifiuto, il differimento e la limitazione dell'accesso civico, sono sempre valutati:","correct":"ai fini della corresponsione della retribuzione di risultato e del trattamento accessorio collegato alla performance individuale dei responsabili","wrong1":"ai fini della corresponsione della retribuzione di risultato","wrong2":"ai fini della corresponsione del trattamento accessorio collegato alla performance individuale","wrong3":"ai soli fini della redazione di apposita relazione di monitoraggio da parte del Responsabile per la prevenzione della corruzione e della trasparenza"},{"id":672,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"Ai sensi dell'art. 47, comma 1, del d.lgs. n. 33/2013, la mancata o incompleta comunicazione della situazione patrimoniale complessiva al momento dell'assunzione in carica del titolare dell'incarico politico, di amministrazione, di direzione o di governo:","correct":"comporta l'applicazione, da parte dell'ANAC, di una sanzione amministrativa pecuniaria da 500 a 10.000 euro a carico del responsabile della mancata comunicazione","wrong1":"non comporta l'applicazione di sanzioni","wrong2":"comporta l'applicazione, da parte dell'ANAC, dela sanzione disciplinare della sospensione dal servizio da uno a tre mesi carico del responsabile della mancata comunicazione","wrong3":"comporta l'applicazione, da parte dell'ANAC, di una sanzione amministrativa pecuniaria di importo non specificato a carico del responsabile della mancata comunicazione"},{"id":673,"paragraph":"Contratti della PA - Trasparenza ed obblighi di pubblicazione","question":"In caso di mancata pubblicazione dei dati relativi alla ragione sociale e alla misura della partecipazione dell'amministrazione negli enti pubblici da essa finanziati, l'ANAC","correct":"applica una sanzione amministrativa consistente nella decurtazione dal 30 al 60 per cento dell'indennità di risultato nei confronti del responsabile della pubblicazione, ovvero nella decurtazione dal 30 al 60 per cento dell'indennità accessoria percepita dal responsabile della trasparenza","wrong1":"applica una sanzione amministrativa consistente nella decurtazione dal 30 al 60 per cento dell'indennità di risultato nei confronti del responsabile della pubblicazione","wrong2":"applica una sanzione amministrativa consistente nella decurtazione dal 30 al 60 per cento dell'indennità accessoria percepita dal responsabile della trasparenza","wrong3":"può applicare solo la sanzione del rimprovero verbale a carico del responsabile"},{"id":674,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"Con il codice di comportamento interno ciascuna amministrazione:","correct":"integra e specifica le previsioni del codice di comportamento governativo, adattandolo alla sua organizzazione e al contesto ambientale in cui opera","wrong1":"ratifica il codice di comportamento nazionale","wrong2":"approva, con propria delibera, il codice di comportamento nazionale, aggiungendo i soli riferimenti alla denominazione e alle competenze dell'amministrazione","wrong3":"adatta il codice di comportamento nazionale alla sua organizzazione"},{"id":675,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"I principi stabiliti nel codice di comportamento nazionale:","correct":"devono essere rigorosamente rispettati, nel loro contenuto, dal codice interno adottato da ciascuna amministrazione","wrong1":"sono modificabili dal codice interno","wrong2":"sono modificabili dal codice di comportamento interno solo nei casi previsti dall'art. 54 del d.lgs. n. 165/2001","wrong3":"devono essere rispettati dai codici interni solo se si tratta di amministrazioni centrali"},{"id":676,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"Ai sensi del novellato art. 54 del d.lgs. n. 165/2001 il codice di comportamento nazionale è approvato al fine di assicurare:","correct":"la qualità dei servizi, la prevenzione dei fenomeni di corruzione, il rispetto dei doveri costituzionali di diligenza, lealtà, imparzialità e servizio esclusivo alla cura dell'interesse pubblico","wrong1":"la prevenzione della corruzione","wrong2":"l'efficienza della pubblica amministrazione, la qualità dei servizi e il rispetto del principio di imparzialità nell'esercizio dell'attività amministrativa","wrong3":"i principi costituzionali di legalità e di buon andamento dell'amministrazione"},{"id":677,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"In attuazione dell'art. 54 del d.lgs. n. 165/2001, il Codice di comportamento dei dipendenti pubblici sancisce che la violazione dei doveri in esso contenuti, compresi quelli relativi all'attuazione del Piano di prevenzione della corruzione, è sempre fonte di:","correct":"responsabilità disciplinare","wrong1":"responsabilità civile","wrong2":"responsabilità amministrativa e contabile","wrong3":"responsabilità penale"},{"id":678,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"Il codice di comportamento interno è adottato:","correct":"dall'organo di indirizzo politico-amministrativo dell'amministrazione, su proposta del responsabile per la prevenzione della corruzione e della trasparenza","wrong1":"dall'organo di indirizzo politico-amministrativo dell'amministrazione, su proposta del segretario comunale","wrong2":"dal consiglio comunale","wrong3":"dal sindaco, su proposta del responsabile per la prevenzione della corruzione e della trasparenza"},{"id":679,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"La procedura di formazione del codice interno è aperta alla partecipazione:","correct":"dei dipendenti e degli stakeholder","wrong1":"dei soli dipendenti","wrong2":"dei rappresentanti dell'organo di indirizzo politico dell'amministrazione","wrong3":"dei collaboratori esterni dell'amministrazione"},{"id":680,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"Al fine di assicurare una procedura partecipata di formazione e aggiornamento del codice interno, l'amministrazione:","correct":"procede alla pubblicazione, sul proprio sito web istituzionale, di un avviso pubblico, con invito a far pervenire proposte ed osservazioni entro il termine fissato","wrong1":"convoca in una seduta congiunta i dipendenti e gli stakeholder","wrong2":"organizza un'apposita seduta di consiglio comunale aperta alla partecipazione di tutti i cittadini","wrong3":"definisce un calendario di incontri, presieduti dal RPCT, aperti alla partecipazione dei dipendenti e dei cittadini interessati"},{"id":681,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"All'ufficio procedimenti disciplinari competono, oltre alle tipiche funzioni disciplinari connesse alla violazione del codice di comportamento:","correct":"l'aggiornamento del codice, l'esame delle segnalazioni di violazione dei codici, la raccolta delle condotte illecite accertate e sanzionate ?","wrong1":"l'aggiornamento del codice","wrong2":"l'audizione dei componenti dell'organo di indirizzo politico per raccogliere le proposte di modifica del codice","wrong3":"il monitoraggio sull'applicazione del codice e la raccolta delle condotte illecite accertate e sanzionate"},{"id":682,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"Le norme del codice di comportamento dei dipendenti pubblici si applicano, oltre che ai dipendenti:","correct":"in quanto compatibili, anche a tutti i collaboratori o consulenti dell'amministrazione, ai titolari di incarichi negli uffici di diretta collaborazione delle autorità politiche, ai collaboratori di imprese esecutrici di lavori, forniture e servizi dell'amministrazione","wrong1":"ai componenti degli organi di indirizzo politico-amministrativo","wrong2":"a tutti i collaboratori o consulenti dell'amministrazione, ai titolari di incarichi negli uffici di diretta collaborazione delle autorità politiche, ai collaboratori di imprese esecutrici di lavori, forniture e servizi dell'amministrazione","wrong3":"ai collaboratori e consulenti contrattualizzati dall'amministrazione, in quanto compatibili"},{"id":683,"paragraph":"Contratti della PA - Il Codice di comportamento dei dipendenti pubblici","question":"L'art. 3 del d.P.R. n. 62/2013, rubricato «principi generali», individua, in sintesi, i principali doveri di comportamento del dipendente pubblico. Tra essi non rientra la disposizione secondo cui il dipendente:","correct":"rispetta i principi di buon andamento, proporzionalità, trasparenza, equità e ragionevolezza e agisce in posizione di imparzialità, astenendosi in caso di conflitto di interessi","wrong1":"osserva la Costituzione, servendo la Nazione con disciplina ed onore e conformando la propria condotta ai principi di buon andamento e imparzialità dell'azione amministrativa","wrong2":"svolge i propri compiti nel rispetto della legge, perseguendo l'interesse pubblico senza abusare della posizione o dei poteri di cui è titolare","wrong3":"rispetta i principi di integrità, correttezza, buona fede, proporzionalità, obiettività, trasparenza, equità e ragionevolezza e agisce in posizione di indipendenza e imparzialità, astenendosi in caso di conflitto di interessi"},{"id":684,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4 del d.P.R. n. 62/2013 stabilisce un divieto assoluto per i dipendenti di chiedere o sollecitare, per sé o per altri, regali o altre utilità:","correct":"indipendentemente dal valore che abbiano","wrong1":"fatta eccezione per quelli di modico valore","wrong2":"fatta eccezione per quelli di valore inferiore a 150 euro","wrong3":"con l'esclusione dei regali donati in occasione di particolari eventi"},{"id":685,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4, comma 2, del d.P.R. n. 62/2013, prevede che il dipendente non accetta, per sé o per altri, regali o altre utilità:","correct":"salvo quelli d'uso di modico valore effettuati occasionalmente nell'ambito delle normali relazioni di cortesia e nell'ambito delle consuetudini internazionali","wrong1":"salvo quelli d'uso di modico valore","wrong2":"salvo quelli di modico valore effettuati occasionalmente nell'ambito delle normali relazioni di cortesia e nell'ambito delle consuetudini internazionali","wrong3":"salvo quelli d'uso di modico valore effettuati nell'ambito delle normali relazioni di cortesia e nell'ambito delle consuetudini internazionali"},{"id":686,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4, comma 5, del d.P.R. n. 62/2013 precisa che i regali o le altre utilità di modico valore sono quelli:","correct":"di valore non superiore, in via orientativa, a 150 euro, anche sotto forma di sconto","wrong1":"di valore non superiore a 150 euro","wrong2":"di valore non superiore, in via orientativa, a 500 euro, anche sotto forma di sconto","wrong3":"di valore non superiore, in via orientativa, a 150 euro"},{"id":687,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4, comma 5, del d.P.R. n. 62/2013 precisa inoltre che i codici di comportamento adottati dalle singole amministrazioni possono prevedere limiti inferiori rispetto al modico valore del regalo o altra utilità fissato dal codice nazionale:","correct":"anche fino all'esclusione della possibilità di riceverli","wrong1":"senza tuttavia poter escludere la possibilità di riceverli","wrong2":"anche fino all'esclusione della possibilità di riceverli, qualora si tratti di comuni con popolazione inferiore a 5.000 abitanti","wrong3":"senza tuttavia poter oltrepassare il limite di 50 euro di valore"},{"id":688,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4, comma 6, del d.P.R. n. 62/2013 prevede che il dipendente non accetta incarichi di collaborazione da soggetti privati:","correct":"che abbiano, o abbiano avuto nel biennio precedente, un interesse economico significativo in decisioni o attività inerenti all'ufficio di appartenenza","wrong1":"che abbiano, o abbiano avuto nel triennio precedente, un interesse economico significativo in decisioni o attività inerenti all'ufficio di appartenenza","wrong2":"che abbiano un interesse economico significativo in decisioni o attività inerenti all'ufficio di appartenenza","wrong3":"che siano a lui legati da rapporti di parentela o affinità"},{"id":689,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 4, comma 5, del d.P.R. n. 62/2013 prevede anche il dipendente che abbia indebitamente ricevuto regali o altre utilità deve:","correct":"metterli immediatamente a disposizione dell'amministrazione per la restituzione o per essere devoluti a fini istituzionali","wrong1":"metterli immediatamente a disposizione dell'amministrazione o rimborsarne il valore","wrong2":"metterli immediatamente a disposizione dell'amministrazione","wrong3":"devolverli in beneficenza o metterli a disposizione dell'amministrazione"},{"id":690,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"Per garantire il rispetto, da parte dei dipendenti, del divieto di chiedere o ricevere regali o altre utilità, l'art. 4, comma 7, del d.P.R. n. 62/2013 attribuisce al responsabile dell'ufficio il compito di:","correct":"vigilare sulla corretta applicazione della norma, al fine di preservare il prestigio e l'imparzialità dell'amministrazione","wrong1":"sanzionare sul piano disciplinare i dipendenti inadempienti","wrong2":"formare adeguatamente i dipendenti sui doveri di comportamento previsti dalla norma","wrong3":"informare tempestivamente il RPCT"},{"id":691,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"La posizione giuridica del responsabile dell'ufficio che svolge attività di vigilanza sul rispetto, da parte dei dipendenti, del divieto di chiedere o ricevere regali:","correct":"è soggetta alla tutela prevista dall'art. 54 bis della legge 165/2001, relativo al dipendente che segnala illeciti","wrong1":"non è soggetta ad alcuna tutela","wrong2":"è tutelata dal RPCT","wrong3":"è soggetta ad una particolare tutela, disciplinata con apposito regolamento adottato dall'organo di indirizzo dell'amministrazione"},{"id":692,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"L'art. 5 del d.P.R. n. 62/2013 prescrive che il dipendente debba comunicare tempestivamente al responsabile dell'ufficio di appartenenza la propria adesione o appartenenza ad associazioni od organizzazioni:","correct":"i cui ambiti di interessi possano interferire con lo svolgimento dell'attività dell'ufficio, a prescindere dal loro carattere riservato o meno","wrong1":"i cui ambiti di interessi possano interferire con lo svolgimento dell'attività dell'ufficio, salvo che si tratti di associazioni o organizzazioni aventi carattere riservato","wrong2":"la cui attività, nel biennio precedente, ha richiesto l'attivazione di rapporti con l'ufficio di appartenenza del dipendente","wrong3":"la cui attività si svolge presso locali di proprietà dell'amministrazione di appartenenza del dipendente"},{"id":693,"paragraph":"Contratti della PA - Norme sulla percezione di regali e la partecipazione ad associazioni e organizzazioni","question":"Nelle Linee guida in materia di Codici di comportamento l'ANAC suggerisce di prevedere nei codici interni l'attribuzione alle amministrazioni del potere di adottare specifiche disposizioni per prevenire la possibilità che l'adesione all'associazione/organizzazione possa determinare situazioni di conflitto di interessi, tra cui non menziona:","correct":"la formazione dei dipendenti","wrong1":"l'assegnazione ad altro ufficio","wrong2":"l'obbligo di astensione","wrong3":"la rotazione"},{"id":694,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"L'espropriazione è quel procedimento amministrativo volto:","correct":"A privare della proprietà privata o di altro diritto reale un cittadino, dietro pagamento di un indennizzo e per ragioni di pubblico interesse","wrong1":"A privare della proprietà privata o di altro diritto reale un cittadino, senza pagamento di un indennizzo e senza ragioni di pubblico interesse","wrong2":"Esclusivamente a privare della proprietà privataun cittadino, dietro pagamento di un indennizzo e per ragioni di pubblico interesse","wrong3":"A privare della proprietà privata o di altro diritto reale un cittadino, senza pagamento di un indennizzo e per ragioni di pubblico interesse"},{"id":695,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"L'espropriazione è quel provvedimento amministrativo ascrivibile tra:","correct":"I provvedimenti ablatori","wrong1":"I provvedimenti autorizzatori","wrong2":"I provvedimenti concessori","wrong3":"I provvedimenti sanzionatori"},{"id":696,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"L'espropriazione trova il proprio fondamento costituzionale:","correct":"Nell'art. 42","wrong1":"Nell'art. 117","wrong2":"Nell'art. 18","wrong3":"Nell'art. 1"},{"id":697,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"L'obbligo di indennizzo in caso di espropriazione è:","correct":"Previsto direttamente in Costituzione","wrong1":"Previsto unicamente nel Testo Unico in materia di espropriazione","wrong2":"Rimesso alla discrezionalità di ciascun legislatore regionale ai sensi dell'art. 117 Cost.","wrong3":"Rimesso alla discrezionalità dell'amministrazione in ragione delle possibilità di cassa di ciascuna"},{"id":698,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"Il Testo Unico in materia di esproprio, riconosce che l'espropriazione possa avvenire:","correct":"Anche in favore di cittadini privati, laddove essi intendano realizzare opere di pubblica utilità","wrong1":"Solo in favore di amministrazioni statali","wrong2":"Solo in favore di amministrazioni locali","wrong3":"Solo in favore di amministrazioni di polizia"},{"id":699,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"Le parti del procedimento espropriativo sono:","correct":"A) l'autorità espropriante; B) il beneficiario dell'espropriazione; C) il promotore dell'espropriazione e D) l'espropriato","wrong1":"A) l'autorità espropriante; B) il beneficiario dell'espropriazione e C) l'espropriato","wrong2":"A) l'autorità espropriante; B) il promotore dell'espropriazione e C) l'espropriato","wrong3":"A) l'autorità espropriante ed B) l'espropriato"},{"id":700,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"Nell'ambito del procedimento espropriativo si distinguono le seguenti fasi e precisamente:","correct":"A) la fase dell'apposizione del vincolo preordinato all'esproprio; b) la fase della dichiarazione di pubblica utilità; c) la fase della determinazione, anche in via provvisoria, dell'indennità di esproprio; d) il decreto d'esproprio","wrong1":"A) la fase dell'apposizione del vincolo preordinato all'esproprio; b) la fase della dichiarazione di pubblica utilità; c) la fase della determinazione, anche in via provvisoria, dell'indennità di esproprio","wrong2":"A) la fase dell'apposizione del vincolo preordinato all'esproprio e b) quella di esproprio","wrong3":"A) la fase della dichiarazione di pubblica utilità; B) la fase della determinazione, anche in via provvisoria, dell'indennità di esproprio; C) il decreto d'esproprio"},{"id":701,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"Il vincolo preordinato all'esproprio:","correct":"Ha durata di cinque anni e può essere reiterato previa corresponsione di un indennizzo in favore del proprietario","wrong1":"Ha durata di cinque anni e non può essere reiterato","wrong2":"Ha durata di tre anni e può essere reiterato previa corresponsione di un indennizzo in favore del proprietario","wrong3":"Ha durata di sei anni e può essere reiterato previa corresponsione di un indennizzo in favore del proprietario"},{"id":702,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"La dichiarazione di pubblica utilità:","correct":"Consiste nell'accertamento che una determinata opera presenta una finalità di interesse pubblico","wrong1":"Consiste nell'accertamento che una determinata opera presenta una finalità di interesse pubblico, a seguito di accertamenti operati di concerto dal CNEL e dal Ministero dello Sviluppo Economico","wrong2":"Consiste nell'accertamento che una determinata opera presenta una presumibile finalità di interesse pubblico","wrong3":"Consiste nell'accertamento che una determinata opera presenta una potenziale finalità di interesse pubblico"},{"id":703,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"Se l'espropriazione ha ad oggetto un'area non edificabile:","correct":"L'indennità va commisurata al valore agricolo, operando, poi delle distinzioni a seconda che l'area sia o meno effettivamente coltivata","wrong1":"L'indennità va commisurata al valore venale del bene, incrementato dal 5%","wrong2":"L'indennità va commisurata al valore venale del bene, senza distinguere a seconda che l'area sia o meno effettivamente coltivata.","wrong3":"L'indennità va commisurata al valore venale del bene, operando, poi delle distinzioni a seconda che l'area sia o meno effettivamente coltivata."},{"id":704,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"La Retrocessione ricorre quando:","correct":"L'opera non sia stata in tutto o in parte realizzata","wrong1":"Il privato abbia presentato a tal fine un'offerta vantaggiosa alla p.a. e questa abbia accettato","wrong2":"Il privato abbia presentato a tal fine un'offerta vantaggiosa alla p.a. e questa abbia accettato, sentita la ragioneria competente","wrong3":"Il privato abbia presentato a tal fine un'offerta vantaggiosa alla p.a. e questa abbia accettato, previo ottenimento di perizia di stima favorevole"},{"id":705,"paragraph":"Contratti della PA - L'espropriazione per pubblica utilità","question":"L'occupazione appropriativa ricorre quando l'autorità utilizza un bene immobile:","correct":"Per scopi di interesse pubblico, modificato in assenza di un valido ed efficace provvedimento di esproprio o dichiarativo della pubblica utilità","wrong1":"Per scopi di interesse privato, modificato in assenza di un valido ed efficace provvedimento di esproprio o dichiarativo della pubblica utilità","wrong2":"Per scopi non di interesse pubblico, in presenza di un valido ed efficace provvedimento di esproprio o dichiarativo della pubblica utilità","wrong3":"Per scopi non di interesse pubblico, modificato in assenza di un valido ed efficace provvedimento di esproprio o dichiarativo della pubblica utilità"},{"id":706,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"Il negozio giuridico è:","correct":"una dichiarazione di volontà diretta a produrre effetti giuridici che l'ordinamento riconosce e tutela","wrong1":"è una dichiarazione che può avere effetti solo risolutivi","wrong2":"una dichiarazione di scienza diretta a produrre effetti naturali","wrong3":"un atto giuridico in senso stretto"},{"id":707,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"La nozione del negozio giuridico è stata originariamente elaborata e quindi nasce in:","correct":"Germania","wrong1":"Francia","wrong2":"Italia","wrong3":"Inghilterra"},{"id":708,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"\"Le parti possono liberamente determinare il contenuto del contratto nei limiti imposti dalla legge\" è una forma del principio di:","correct":"autonomia contrattuale","wrong1":"autonomia patrimoniale","wrong2":"libera manifestazione del pensiero","wrong3":"libertà della forma"},{"id":709,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"La scelta se concludere o meno il contratto:","correct":"trova un limite negli obblighi di contrarre di fonte legale","wrong1":"non è in alcun modo limitata dall'ordinamento giuridico","wrong2":"è limitata sono per gli atti a titolo gratuiti","wrong3":"trova un limite negli obblighi di contrarre di fonte consuetudinaria"},{"id":710,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"Il potere di esprimere liberamente la propria personalità secondo la propria volontà e determinazione:","correct":"è una declinazione del principio dell'autonomia privata","wrong1":"è una declinazione del principio della autonomia patrimoniale","wrong2":"trova un limite negli obblighi di contrarre di fonte consuetudinaria","wrong3":"è limitato sono per gli atti a titolo gratuiti"},{"id":711,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"Quale tra i seguenti non è un riferimento costituzione della autonomia negoziale:","correct":"il diritto alla salute","wrong1":"il principio della libertà di iniziativa economica privata","wrong2":"il principio di uguaglianza","wrong3":"il dovere inderogabile di solidarietà sociale"},{"id":712,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"L'art. 41 della Costituzione è stato modificato:","correct":"con legge costituzionale del 2022","wrong1":"con legge costituzionale del 2001","wrong2":"con legge costituzionale del 2003","wrong3":"con legge costituzionale del 2021"},{"id":713,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"L'Unione Europea:","correct":"ha riconosciuto la centralità della autonomia privata quale principio generale del diritto comunitario, fondato sia sulla libertà del singolo sia sulla libertà di impresa","wrong1":"non interviene sul mercato unico","wrong2":"non adotta normative che impattano sulla autonomia privata","wrong3":"non riconosce la centralità della autonomia privata quale principio generale del diritto comunitario, fondato sia sulla libertà del singolo sia sulla libertà di impresa"},{"id":714,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"La libertà contrattuale nelle pronunce della Corte di Giustizia:","correct":"fa parte dei principi generali del diritto comunitario","wrong1":"non fa parte dei principi generali del diritto comunitario","wrong2":"è materia rimessa alla esclusiva autonomia normativa dei singoli Stati","wrong3":"è materia rimessa alla esclusiva elaborazione delle Corti dei singoli Stati"},{"id":715,"paragraph":"Contratti della PA - Nozioni introduttive: fondamenti e limiti dell'autonomia negoziale","question":"È un obiettivo strategico delle Istituzioni Europee:","correct":"solo la libertà di stabilimento, solo la libera circolazione delle merci e delle attività economiche, solo la libera circolazione delle merci e delle attività economiche e la coesione territoriale","wrong1":"solo la libertà di stabilimento","wrong2":"solo la libera circolazione delle merci e delle attività economiche","wrong3":"solo la libera circolazione delle merci e delle attività economiche e la coesione territoriale"},{"id":716,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Il negozio giuridico:","correct":"è una manifestazione di volontà rivolta ad uno scopo pratico che consiste nel costituire, modificare o estinguere una situazione giuridicamente rilevante; è lo strumento principale per mezzo del quale si attua nel diritto privato l'autonomia dei soggetti","wrong1":"può essere solo a titolo gratuito","wrong2":"è una manifestazione di volontà rivolta ad uno scopo pratico che consiste nel costituireuna situazione giuridicamente rilevante","wrong3":"è una dichiarazione di scienza rivolta ad uno scopo pratico che consiste modificare o estinguere una situazione giuridicamente rilevante"},{"id":717,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Il negozio presuppone l'esistenza:","correct":"di uno o più soggetti che lo pongono in essere e di un oggetto","wrong1":"solo della capacità giuridica di chi lo pone in essere","wrong2":"solo di un oggetto","wrong3":"solo di uno o più soggetti che lo pongono in essere"},{"id":718,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Sono requisiti soggettivi del negozio:","correct":"capacità giuridica, di agire, legittimazione","wrong1":"solo la legittimazione","wrong2":"solo la capacità di agire","wrong3":"solo la capacità giuridica"},{"id":719,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Sono requisiti oggettivi del negozio:","correct":"possibilità, leità, determinatezza o determinabilità","wrong1":"capacità giuridica, di agire, legittimazione,","wrong2":"solo la possibilità","wrong3":"solo la liceità"},{"id":720,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Affinché il negozio sia valido ed efficace:","correct":"occorre che esso sia posto in essere da chi abbia la capacità di agire","wrong1":"occorre che sia posto in essere da chi abbia la capacità naturale","wrong2":"non occorre che esso sia posto in essere da chi abbia la capacità di agire","wrong3":"occorre che esso sia posto in essere da chi abbia la capacità di intendere e di volere"},{"id":721,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"I requisiti soggettivi:","correct":"debbono esistere al momento della conclusione del negozio","wrong1":"non assumono rilevanza ai fini della validità del contratto","wrong2":"debbono sussistere al momento in cui il negozio comincia a produrre effetti","wrong3":"attengo all'oggetto del contratto"},{"id":722,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Per poter assumere rilevanza giuridica, deve essere dichiarata:","correct":"la volontà","wrong1":"la ragione","wrong2":"la riserva mentale","wrong3":"la capacità giuridica"},{"id":723,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Sono elementi accidentali:","correct":"quelli che gli autori del negozio sono liberi di apporre o meno, con l'avvertenza, però, che una volta apposti, essi diventano essenziali, cioè, diventano parte integrante della struttura dell'atto","wrong1":"quelli che gli autori del negozio sono liberi di apporre o meno, e che anche se apposti non diventano parte integrante della struttura dell'atto","wrong2":"quelli previsti ai fini della validità del negozio","wrong3":"gli elementi naturali"},{"id":724,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"La volontà negoziale:","correct":"deve essere portata all'esterno, cioè, dichiarata ad altri individui","wrong1":"è elemento accidentale del negozio","wrong2":"è elemento essenziale solo quando prescritto dalla legge","wrong3":"rileva ai fini della validità solo quando è illecita"},{"id":725,"paragraph":"Contratti della PA - La volontà nel negozio giuridico e nel contratto:","question":"Nel contratto, la volontà:","correct":"diventa accordo consenso","wrong1":"è elemento accidentale","wrong2":"è sempre irrilevante","wrong3":"si presume voluta ad substantiam"},{"id":726,"paragraph":"Contratti della PA - La forma del contratto","question":"I contratti posso essere distinti, quanto alla produzione degli effetti, in:","correct":"costitutivi, modificativi ed estintivi","wrong1":"solo risolutivi","wrong2":"modificativi ed estintivi","wrong3":"costitutivi ed estintivi"},{"id":727,"paragraph":"Contratti della PA - La forma del contratto","question":"La forma è:","correct":"lo strumento mediante il quale la volontà delle parti e l'intero contratto dalle stesse concluso viene manifestata all'esterno","wrong1":"sempre un elemento essenziale del contratto","wrong2":"definita espressamente nel codice civile","wrong3":"definita espressamente nella relazione al codice civile"},{"id":728,"paragraph":"Contratti della PA - La forma del contratto","question":"Nel nostro ordinamento:","correct":"vige il principio della libertà della forma","wrong1":"non vige il principio della libertà della forma","wrong2":"il principio della libertà della forma vale solo per i contratti verbali","wrong3":"il principio della libertà della forma vale solo per i contratti a titolo gratuiti"},{"id":729,"paragraph":"Contratti della PA - La forma del contratto","question":"Il principio della libertà della forma:","correct":"è espressione dell'autonomia privata","wrong1":"non è espressione dell'autonomia privata","wrong2":"è espressione del diritto alla libera manifestazione del pensiero","wrong3":"è espressamente definito nel codice civile"},{"id":730,"paragraph":"Contratti della PA - La forma del contratto","question":"La forma scritta, che si concretizza in un documento, quando richiesta dalla legge \"sotto pena di nullità\":","correct":"può assumere la veste della scrittura privata e dell'atto pubblico","wrong1":"può assumere solo la veste della scrittura privata","wrong2":"può assumere solo la veste dell'atto pubblico","wrong3":"può assumere solo la veste della scrittura privata"},{"id":731,"paragraph":"Contratti della PA - La forma del contratto","question":"L'atto pubblico , richiesto sotto pena di nullità per taluni contratti (es. la donazione ):","correct":"l'atto pubblico è il documento redatto, con le richieste formalità, da un notaio o da altro pubblico ufficiale autorizzato ad attribuirgli pubblica fede nel luogo dove l'atto è formato","wrong1":"consiste nella redazione per iscritto ad opera di un notaio di un documento e non richiede alla fine della redazione del documento che lo stesso sia sottoscritto anche dai testimoni se questi hanno partecipato all'atto","wrong2":"non fa a piena prova, fino a querela di falso delle dichiarazioni delle parti, ivi contenute","wrong3":"fa piena prova, fino a querela di falso, solo dei fatti che il pubblico ufficiale attesta avvenuti in sua presenza o da lui compiuti"},{"id":732,"paragraph":"Contratti della PA - La forma del contratto","question":"La vendita di cosa futura:","correct":"è assoggettata alla forma scritta ad substantiam","wrong1":"non è assoggettata alla forma scritta ad substantiam","wrong2":"è assoggettata alla forma scritta solo ad probationem","wrong3":"è assoggettata alla forma scritta solo per la sual risoluzione"},{"id":733,"paragraph":"Contratti della PA - La forma del contratto","question":"La differenza tra forma essenziale e probatoria consiste nel fatto che:","correct":"qualora non venga osservata la forma essenziale, il contratto è nullo ossia non produce gli effetti suoi propri; qualora non venga osservata la forma probatoria il contratto è tuttavia valido e può produrre tutti gli effetti suoi propri, ma se dovessero sorgere delle contestazioni tra le parti esso non potrebbe venire provato a mezzo di testimoni","wrong1":"qualora non venga osservata la forma probatoria, il contratto è nullo ossia non produce gli effetti suoi propri;qualora non venga osservata la forma essenziale il contratto è tuttavia valido e può produrre tutti gli effetti suoi propri, ma se dovessero sorgere delle contestazioni tra le parti esso non potrebbe venire provato a mezzo di testimoni","wrong2":"qualora non venga osservata la forma essenziale, il contratto produce comunque effetti;qualora non venga osservata la forma probatoria il contratto è nullo ossia non produce gli effetti suoi propri","wrong3":"qualora non venga osservata la forma probatoria il contratto è nullo; qualora non venga osservata la forma essenziale il contratto è efficace"},{"id":734,"paragraph":"Contratti della PA - La forma del contratto","question":"La forma volontaria:","correct":"si presume voluta ad substantiam","wrong1":"rende sempre annullabile il contratto","wrong2":"rende sempre nullo il contratto","wrong3":"si presume voluta ad probationem"},{"id":735,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"L'oggetto del contratto:","correct":"è da riferire alla prestazione, ovvero al contenuto del negozio, non al bene in sé","wrong1":"è il bene dedotto","wrong2":"deve essere solo giuridicamente possibile","wrong3":"non è tra i requisiti essenziale del contratto individuati dall'art. 1325 c.c."},{"id":736,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"L'oggetto del contratto deve essere:","correct":"possibile, lecito, determinato o determinabile","wrong1":"solo possibile","wrong2":"solo lecito","wrong3":"solo determinato"},{"id":737,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"Una prestazione che ha ad oggetto beni o attività che non possono essere dedotti in un rapporto giuridico:","correct":"è giuridicamente impossibile","wrong1":"è materialmente impossibile","wrong2":"è illecita","wrong3":"è sempre determinabile"},{"id":738,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"L'impossibilità che rileva ai fini della invalidità del contratto:","correct":"assoluta (o oggettiva) o relativa (o soggettiva)","wrong1":"puè essere solo oggettiva","wrong2":"può essere solo soggettiva","wrong3":"può essere solo assoluta"},{"id":739,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"Il requisito della possibilità:","correct":"deve essere valutato solo al momento dell'efficacia del negozio, al momento della produzione degli effetti e non della sua stipulazione","wrong1":"deve essere valutato solo al momento della sua stipulazione","wrong2":"non è richiesto dalla legge ai fini della validità del negozio","wrong3":"attiene solo alla possibilità giuridica"},{"id":740,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"L'impossibilità dell'oggetto:","correct":"va valutata in modo oggettivo","wrong1":"non rileva ai fini della valutazione di illiceità dell'oggetto","wrong2":"va valutata in modo soggettivo","wrong3":"non riguarda l'astratta realizzabilità dell'impegno assunto dalle parti"},{"id":741,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"È lecito l'oggetto che:","correct":"non è contrario a norme imperative, all'ordine pubblico o al buon costume","wrong1":"è possibile e determinato","wrong2":"non è contrario a norme imperative","wrong3":"non è contrario al buon costume"},{"id":742,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"La mancanza dei requisiti di abitabilità:","correct":"non rileva ai fini della valutazione di illiceità dell'oggetto","wrong1":"è illiceità dell'oggetto","wrong2":"è illiceità della causa","wrong3":"è impossibilità dell'oggetto"},{"id":743,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"L'oggetto è determinato:","correct":"quando è indicato dalle parti nella qualità e nella quantità in modo esauriente","wrong1":"se non è contrario a norme imperative, all'ordine pubblico o al buon costume","wrong2":"quando è indicato dalle parti nella quantità in modo esauriente","wrong3":"quando è indicato dalle parti nella qualità in modo esauriente"},{"id":744,"paragraph":"Contratti della PA - L'oggetto del contratto","question":"La prestazione dedotta nel contratto:","correct":"può essere dalle parti congiuntamente rimessa alla determinazione di un terzo","wrong1":"può essere determinata solo per relationem","wrong2":"non può essere dalle parti congiuntamente rimessa alla determinazione di un terzo","wrong3":"può essere rimessa alla determinazione di un terzo solo nei casi previsti dalla legge"},{"id":745,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Gli elementi accidentali:","correct":"sono tutte quelle clausole che le parti sono libere di apporre o meno al contratto al fine di precisarne le modalità o modificarne gli effetti","wrong1":"sono gli elementi naturali del negozio","wrong2":"sono necessari ai fini della validità del negozio","wrong3":"sono accordo e causa"},{"id":746,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"La condizione:","correct":"è un avvenimento futuro e incerto al verificarsi del quale le parti fanno dipendere l'efficacia o la cessazione degli effetti","wrong1":"è un avvenimento futuro e certo al al verificarsi del quale le parti fanno dipendere l'efficacia o la risoluzione del contratto intesa come cessazione degli effetti","wrong2":"è sempre un elemento essenziale del contratto","wrong3":"è un avvenimento certo al al verificarsi del quale le parti fanno dipendere l'efficacia"},{"id":747,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"La condicio iuris:","correct":"costituisce un presupposto legale di efficacia","wrong1":"è un elemento accidentale del negozio","wrong2":"è un avvenimento futuro e certo al al verificarsi del quale le parti fanno dipendere l'efficacia o la risoluzione del contratto intesa come cessazione degli effetti","wrong3":"è un elemento naturale del negozio"},{"id":748,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Se l'evento dedotto nella condizione dipende dalla volontà del contraente:","correct":"la condizione è potestativa","wrong1":"la condizione è mista","wrong2":"la condizione è causale","wrong3":"la condizione è legale"},{"id":749,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Quella la cui verificazione dipende per parte dal caso, per parte dalla volontà di una delle parti è una condizione:","correct":"mista","wrong1":"casuale","wrong2":"legale","wrong3":"potestativa"},{"id":750,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"L'alienazione di un diritto o l'assunzione di un obbligo subordinata ad una condizione sospensiva che la faccia dipendere dalla mera volontà dell'alienante o da quella del debitore:","correct":"è nulla","wrong1":"è valida ed efficace","wrong2":"è efficace quando l'evento dedotto nella condizione si verifica","wrong3":"è inesistente"},{"id":751,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Quella apposta al negozio contrattuale nell'esclusivo interesse di una sola delle parti:","correct":"è una condizione unilaterale","wrong1":"è una condizione meramente potestativa","wrong2":"è una condizione mista","wrong3":"è una condizione causale"},{"id":752,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"La finzione di avveramento della condizione:","correct":"vale solo per la condizione casuale o mista","wrong1":"vale solo per la condizione legale","wrong2":"vale solo per la condizione potestativa","wrong3":"vale solo per la condizione meramente potestativa"},{"id":753,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Il termine può essere:","correct":"iniziale o finale","wrong1":"solo iniziale","wrong2":"solo finale","wrong3":"apposto solo nei negozi a titolo gratuito"},{"id":754,"paragraph":"Contratti della PA - Elementi accidentali del contratto: la condizione, il termine e il modo (o onere)","question":"Il modus:","correct":"è un peso, una limitazione dell'attribuzione a titolo gratuito, rispetto alla quale a carico del beneficiario graverà l'onere di farne un certo uso o di impiegare","wrong1":"può essere apposto anche ai negozi a titolo oneroso","wrong2":"è un avvenimento futuro e certo al al verificarsi del quale le parti fanno dipendere l'efficacia o la risoluzione del contratto intesa come cessazione degli effetti","wrong3":"è una condizione causale"},{"id":755,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"Nella formazione del consenso contrattuale le parti devono:","correct":"attenersi ad un contegno di correttezza","wrong1":"comportarsi bene","wrong2":"attenersi ad un contegno di intelligenza","wrong3":"attenersi ad un contegno di adempimento"},{"id":756,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"La responsabilità in caso di recesso ingiustificato dalle trattative prevista dall'art. 1337 c.c., comporta:","correct":"il dovere di attenersi alla buona fede precontrattuale, al fine di evitare di coinvolgere l'altra parte in trattative inutili","wrong1":"solo un obbligo giudiziale a contrarre","wrong2":"un obbligo a contrarre","wrong3":"la possibilità per la parte diligente a rispettare il contratto"},{"id":757,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"Per la giurisprudenza a Sezioni Unite n. 6596/2011 la natura della responsabilità precontrattuale è:","correct":"responsabilità di tipo contrattuale da contatto sociale, in considerazione del fatto che le parti sono indubbiamente entrate in contatto durante le trattative","wrong1":"di tipo extracontrattuale","wrong2":"contrattuale ed aquiliana allo stesso tempo","wrong3":"un tertium genus di responsabilità"},{"id":758,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"La responsabilità precontrattuale tutela:","correct":"il solo interesse negativo a non essere coinvolti in trattative senza alcuna utilità","wrong1":"sanziona la lesione dell'interesse, in questo caso positivo, a ricevere la prestazione dovuta","wrong2":"lo stesso interesse che tutela quella contrattuale","wrong3":"l'interesse positivo a non essere coinvolti in trattative senza alcuna utilità"},{"id":759,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"La responsabilità precontrattuale della Pubblica Amministrazione:","correct":"è ammessa da parte della giurisprudenza di legittimità","wrong1":"non è ammissibile","wrong2":"è esclusa per legge","wrong3":"è ammessa solo per gli interesse nazionali"},{"id":760,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"Il profilo oggettivo della responsabilità precontrattuale:","correct":"ha ad oggetto la fase di formazione del contratto interessante la proposta e l'accettazione ed anche tutta la fase delle trattative che la precedono","wrong1":"non comprende anche tutte le trattative infruttuose","wrong2":"non comprende la fase di formazione del contratto interessante la proposta e l'accettazione","wrong3":"ha ad oggetto la sola fase di formazione del contratto interessante la proposta e l'accettazione"},{"id":761,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"Il profilo soggettivo della responsabilità precontrattuale:","correct":"è esteso il suo ambito di operatività della responsabilità precontrattuale anche nei confronti dei terzi, quali un mediatore, un agente o un rappresentante che hanno inciso in maniera rilevante nel processo di formazione del contratto","wrong1":"ha ad oggetto la sola fase di formazione","wrong2":"ha ad oggetto tutta la fase delle trattative che la precedono","wrong3":"è escluso nei confronti dei terzi, quali un mediatore, un agente o un rappresentante che hanno inciso in maniera rilevante nel processo di formazione del contratto."},{"id":762,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"La responsabilità precontrattuale attiene:","correct":"non soltanto il contratto invalido, ma anche quello valido","wrong1":"soltanto il contratto invalido","wrong2":"soltanto il contratto annullabile","wrong3":"soltanto il contratto nullo"},{"id":763,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"Le ipotesi di responsabilità precontrattuale:","correct":"Oltre alle ipotesi ex artt. 1337 e 1338 c.c. vi sono specifici obblighi di buona fede nella fase precontrattuale, da considerare sotto il profilo della lealtà","wrong1":"Sono solo quelle previste dall'art. 1337 c.c.","wrong2":"Sono solo quelle previste dall'art. 1338 c.c.","wrong3":"Sono solo quelle previste dall'art. 1337 e 1338 c.c."},{"id":764,"paragraph":"Contratti della PA - Trattatvie, buona fede e responsabilità precontrattuale","question":"La Suprema Cass. civile, sez. II, sentenza n. 4715 del 14.02.2022., in riferimento all'art. 1337 c.c., ha statuito:","correct":"che tale disposizione non si riferisce esclusivamente all'ipotesi di abbandono ingiustificato delle trattative o di conclusione di un contratto invalido o inefficace, ma ha valore di clausola generale che assume rilievo anche nel caso in cui il contratto concluso sia valido ma risulti pregiudizievole per la parte danneggiata dall'altrui comportamento scorretto","wrong1":"che tale disposizione si riferisce esclusivamente all'ipotesi di abbandono ingiustificato delle trattative o di conclusione di un contratto invalido o inefficace, ma ha valore di clausola generale che assume rilievo anche nel caso in cui il contratto concluso sia valido ma risulti pregiudizievole per la parte danneggiata dall'altrui comportamento scorretto","wrong2":"il risarcimento non deve essere comparato al minor vantaggio o al maggior aggravio economico determinato dal contegno scorretto di una delle parti","wrong3":"è fondamentaleche la violazione del dovere di buona fede sia intervenuto cronologicamente a valle della conclusione del contratto, salvo la prova di ulteriori danni collegati a tale comportamento da un rapporto consequenziale e diretto."},{"id":765,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"La nascita del vincolo contrattuale:","correct":"essere preceduta da vincoli di vario tipo e natura e che, quindi, incidono nella formazione del contratto","wrong1":"non può essere preceduta da vincoli di vario tipo","wrong2":"può derivare solo da una formazione istantanea del consenso","wrong3":"può derivare solo da una formazione progressiva del consenso"},{"id":766,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"Durante le trattative e nelle fasi relative alla formazione del contratto:","correct":"le parti devono comportarsi secondo buona fede (art. 1337), salvo incorrere in responsabilità precontrattuale","wrong1":"il comportamento assunto dalle parti non assume mai rilevanza giuridica","wrong2":"le parti devono comportarsi secondo buona fede (art. 1337), salvo incorrere in responsabilità extracontrattuale","wrong3":"le parti devono comportarsi secondo buona fede (art. 1337), salvo incorrere in responsabilità contrattuale"},{"id":767,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"La cd. minuta:","correct":"rientra tra gli accordi preparatori che nelle trattative particolarmente elaborate possono precedere la formazione del consenso","wrong1":"vincola alla conclusione del contratto","wrong2":"non assuma mai rilevanga giuridica","wrong3":"può rilevare solo ai fini della responsabilità contrattuale"},{"id":768,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"Il patto con il quale le parti convengono che una di esse rimanga vincolata alla propria dichiarazione e l'altra, c.d. opzionario o oblato, abbia facoltà di accettarla o meno, entro un certo termine:","correct":"opzione","wrong1":"prelazione","wrong2":"contratto preliminare","wrong3":"contratto imposto"},{"id":769,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"L'opzione:","correct":"può essere anche a titolo oneroso","wrong1":"può essere solo a titolo gratuito","wrong2":"può essere solo a titolo onerso","wrong3":"è identica all'stituto della proposta irrevocabile"},{"id":770,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"L'opzione consiste:","correct":"nel contratto attraverso cui una parte si obbliga a tener ferma la proposta e l'altra ha la facoltà di accettarla o meno","wrong1":"in un contratto con cui le parti si obbligano alla stipulazione di un contratto definitivo","wrong2":"nella volontà del proponente di mantenere ferma la proposta","wrong3":"in un onere a carico del proponente di mantenere ferma la proposta"},{"id":771,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"Se il proponente revoca la proposta dopo che si era obbligato a mantenerla ferma per un certo tempo, e si era obbligato a non revocarla o dichiarandola senz'altro ferma:","correct":"la revoca è senza effetto","wrong1":"la revoca produce effetto solo nei confronti dei terzi","wrong2":"la revoca è nulla","wrong3":"la revoca è annullabile su istanza degli interessati"},{"id":772,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"La prelazione consiste:","correct":"nell'attribuzione ad un soggetto del diritto ad essere preferito ad altri a parità di condizioni ove si decida di concludere un determinato contratto","wrong1":"nel patto con il quale le parti convengono che una di esse rimanga vincolata alla propria dichiarazione e l'altra, c.d. opzionario o oblato, abbia facoltà di accettarla o meno, entro un certo termine:","wrong2":"in una proposta destinata a mantenersi stabile per il tempo fissato dal proponente","wrong3":"in un contratto a formazione progressiva"},{"id":773,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"La prelazione:","correct":"non è espressamente definita nel codice civile","wrong1":"è espressamente definita e disciplinata nel codice civile","wrong2":"è espressamente definita e disciplinata nel codice del consumatore","wrong3":"è istituto di elaborazione giurisprudenziale"},{"id":774,"paragraph":"I contratti della PA - Vincoli nella formazione dei contratti","question":"Oggetto del contratto preliminare:","correct":"è l'obbligo di concludere il contratto definitivo","wrong1":"è l'oggetto dedotto nel rapporto contrattuale","wrong2":"è il vincolo assunto da una sola parte","wrong3":"è il vincolo assunto da entrambe le parti"},{"id":775,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Il contratto preliminare è un contratto con cui:","correct":"le parti si obbligano a stipulare un futuro contratto definitivo delineato nei suoi elementi essenziali","wrong1":"le parti si obbligano a stipulare un futuro contratto definitivo non delineato nei suoi elementi essenziali, ma secondari","wrong2":"le parti si obbligano a stipulare un futuro contratto definitivo delineato in ogni suo elemento","wrong3":"le parti si obbligano a stipulare un futuro contratto definitivo non delineato in alcun elemento"},{"id":776,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Viene definito compromesso:","correct":"Il preliminare improprio","wrong1":"Il contratto preliminare","wrong2":"Il preliminare unilaterale","wrong3":"Il preliminare di preliminare"},{"id":777,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Se c'è discordanza tra il contenuto di un contratto preliminare e quello di un contratto definitivo:","correct":"è il contenuto del definitivo a prevalere, a meno che le parti non manifestino espressamente la volontà di far salve talune clausole del preliminare","wrong1":"è sempre il contenuto del definitivo a prevalere sul preliminare","wrong2":"è sempre il contenuto del preliminare a prevalere sul definitivo","wrong3":"è il contenuto del preliminare a prevalere, a meno che le parti non manifestino espressamente la volontà di far salve talune clausole del definitivo"},{"id":778,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Ai sensi dell'art. 1351 c.c.:","correct":"il contratto preliminare deve essere stipulato nella stessa forma che la legge prevede per il contratto definitivo","wrong1":"il contratto preliminare deve essere sempre stipulato in forma scritta","wrong2":"per il contratto preliminare vige sempre il principio della libertà della forma","wrong3":"è il contratto definitivo a doversi uniformare alla forma che la legge prevede per il contratto preliminare"},{"id":779,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Il preliminare di preliminare è:","correct":"un'intesa scritta che contiene una clausola che vincola a concludere un contratto preliminare","wrong1":"un'intesa verbale fra parte promissoria acquirente e venditore","wrong2":"un'intesa avente sempre valore di contratto definitivo","wrong3":"un atto nullo poiché mancante della funzione economico sociale del contratto"},{"id":780,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Nel contratto preliminare a effetti anticipati:","correct":"le parti anticipano sin dalla stipulazione del contratto preliminare alcuni effetti del definitivo","wrong1":"le parti anticipano sin dalla stipulazione del contratto preliminare tutti gli effetti del definitivo","wrong2":"le parti anticipano sin dalla stipulazione del contratto preliminare di preliminare gli effetti del contratto preliminare","wrong3":"le parti posticipano al contratto definitivo tutti gli effetti del contratto preliminare"},{"id":781,"paragraph":"I contratti della PA - Il contratto preliminare","question":"Per la Cassazione a Sezioni Unite, sent. n. 7930 del 2008, il contratto preliminare a effetti anticipati è:","correct":"un contratto misto","wrong1":"un contratto preliminare","wrong2":"un preliminare di preliminare","wrong3":"un contratto definitivo"},{"id":782,"paragraph":"I contratti della PA - Il contratto preliminare","question":"L'esecuzione in forma specifica dell'obbligo di concludere il contratto definitivo:","correct":"può essere emessa se il contratto preliminare contiene tutti gli elementi per delineare il contenuto di quello definitivo e se la parte che l'ha richiesta ha eseguito la prestazione o ha fatto offerta all'altro contraente","wrong1":"può essere emessa in ogni caso","wrong2":"può essere emessa se il contratto preliminare contiene alcuni elementi per poter delineare il contenuto di quello definitivo","wrong3":"può essere emessa se il contratto definitivo contiene tutti gli elementi"},{"id":783,"paragraph":"I contratti della PA - Il contratto preliminare","question":"La trascrizione del contratto preliminare:","correct":"è opponibile nei confronti dei terzi","wrong1":"è opponibile nei confronti dell'altro contraente","wrong2":"non è mai opponibile","wrong3":"è opponibile nei confronti del contratto definitivo"},{"id":784,"paragraph":"I contratti della PA - Il contratto preliminare","question":"La trascrizione del contratto preliminare ha effetto:","correct":"fino ad un anno dalla data prevista per la stipula del definitivo, e comunque non oltre i tre anni dalla data di stipula del preliminare","wrong1":"fino a che il diritto non è prescritto, secondo i termini ordinari di prescrizione","wrong2":"fino a tre anni dalla data previta per il contratto definitivo","wrong3":"fino ad un anno dalla stpula del preliminare"},{"id":785,"paragraph":"I contratti della PA - La rappresentanza","question":"La rappresentanza volontaria:","correct":"non è ammessa in tutti i negozi cosiddetti personalissimi","wrong1":"non è ammessa nei negozi patrimonialli","wrong2":"è ammessa solo nei negozi personalissimi","wrong3":"non è ammessa nel nostro nostro ordinamento"},{"id":786,"paragraph":"I contratti della PA - La rappresentanza","question":"La rappresentanza è indiretta quando:","correct":"il rappresentante agisce solo per conto ma non nel nome del rappresentato","wrong1":"il rappresentante agisce solo nel nome del rappresentato","wrong2":"il rappresentante agisce solo nel nome ma non per conto rappresentato","wrong3":"il rappresentante agisce per conto e non nel nome del rappresentato"},{"id":787,"paragraph":"I contratti della PA - La rappresentanza","question":"Si ha rappresentanza volontaria:","correct":"quando una persona conferisce a un'altra mediante un atto unilaterale, detto procura, il potere di rappresentarla, cioè di agire in suo nome e per suo conto, in questo caso, quindi, il rappresentato, anziché agire direttamente, delega un altro soggetto, rappresentante appunto, a compiere atti in sua vece","wrong1":"quando si ha rappresentanza organica","wrong2":"quando le parti concordemente decidono che l'una rappresenti l'altra senza che perciò sia necessaria la spendita del nome","wrong3":"quando la legge stessa indica che una persona è chiamata ad agire in nome e per conto di un'altra"},{"id":788,"paragraph":"I contratti della PA - La rappresentanza","question":"La procura:","correct":"è un negozio unilaterale","wrong1":"è un contratto a titolo gratuito","wrong2":"è un contratto a titolo oneroso","wrong3":"è un negozio a formazione progressiva"},{"id":789,"paragraph":"I contratti della PA - La rappresentanza","question":"La procura:","correct":"può essere revocabile o irrevocabile","wrong1":"può essere solo irrevocabile","wrong2":"può essere revocabile","wrong3":"è negozio bilaterale"},{"id":790,"paragraph":"I contratti della PA - La rappresentanza","question":"La forma della procura:","correct":"deve essere la stessa forma prescritta dalla legge per il negozio che il rappresentante ha il potere di concludere","wrong1":"non necessariamente deve essere la stessa forma prescritta dalla legge per il negozio che il rappresentante ha il potere di concludere","wrong2":"è sempre verbale","wrong3":"è sempre scritta"},{"id":791,"paragraph":"I contratti della PA - La rappresentanza","question":"La differenza tra procura e mandato consiste nel fatto che:","correct":"la procura è un negozio unilaterale costitutivo di poteri per il rappresentante, il mandato è un contratto, quindi negozio bilaterale, costitutivo di obblighi per le parti ed è destinato a regolare rapporti interni tra rappresentante e rappresentato","wrong1":"il mandato è un negozio unilaterale costitutivo di poteri per il rappresentante, ila procura è un contratto, quindi negozio bilaterale, costitutivo di obblighi per le parti ed è destinato a regolare rapporti interni tra rappresentante e rappresentato","wrong2":"la procura è un negozio bilaterale costitutivo di poteri per il rappresentante, il mandato è un negozio unilaterale","wrong3":"la procura è un negozio bilaterale costitutivo di poteri per il rappresentante, il mandato è un negozio unilaterale, costitutivo di obblighi per le parti ed è destinato a regolare rapporti interni tra rappresentante e rappresentato"},{"id":792,"paragraph":"I contratti della PA - La rappresentanza","question":"Per il rappresentante la legge richiede:","correct":"la capacità di intendere e di volere","wrong1":"la capacità di intendere e di volere e la capacità di agire","wrong2":"solo la capacità di agire","wrong3":"non riechiede una specifica capacità"},{"id":793,"paragraph":"I contratti della PA - La rappresentanza","question":"Vi è abuso di potere se:","correct":"il rappresentante persegua l'interesse proprio o di un terzo in via esclusiva","wrong1":"esiste un danno patrimoniale attuale del dominus","wrong2":"il rappresentante persegua con l'interesse proprio quello di terzo in anche in via non esclusiva","wrong3":"il rappresentante persegua l'interesse proprio o di un terzo anche in via non esclusiva"},{"id":794,"paragraph":"I contratti della PA - La rappresentanza","question":"Si ha eccesso e difetto di potere:","correct":"quando il rappresentante abbia oltrepassato i limiti conferitigli con la procura","wrong1":"quando chi contrae come rappresentante non ha poteri","wrong2":"quando il rappresentante agisce nell'interesse del rappresentato","wrong3":"quando il rappresentante crea un danno patrimoniale al rappresentato"},{"id":795,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"La regolamentazione del tempo e dello spazio dell'accordo:","correct":"è necessaria se lo scambio avviene tra persone distanti","wrong1":"è necessaria se lo scambio avviene tra persone presenti","wrong2":"non è necessaria se lo scambio avviene tra persone distanti","wrong3":"è opportuna se lo scambio avviene tra persone distanti"},{"id":796,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"La disciplina della proposta e dell'accettazione è contenuta:","correct":"nell'art. 1326 c.c.","wrong1":"nell'art. 1327 c.c.","wrong2":"nell'art. 1325 c.c.","wrong3":"nell'art. 1333 c.c."},{"id":797,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"L'oblato è:","correct":"il destinatario della proposta","wrong1":"l'emittente la proposta","wrong2":"la controparte","wrong3":"il terzo"},{"id":798,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"Se la proposta è incompleta:","correct":"vale come invito ad offrire","wrong1":"è inefficace","wrong2":"si ha per mai formulata","wrong3":"è nulla"},{"id":799,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"La proposta con oggetto determinabile:","correct":"è per relationem","wrong1":"è incompleta","wrong2":"vale come invito ad offrire","wrong3":"non manifesta l'intenzione di obbligarsi"},{"id":800,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"Secondo la dottrina prevalente la natura giuridica della proposta è:","correct":"un atto prenegoziale recettizio","wrong1":"un negozio giuridico unilaterale","wrong2":"un atto giuridico in senso stretto","wrong3":"un atto prenegoziale"},{"id":801,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"L'accettazione parziale rende:","correct":"indefinito l'oggetto del consenso","wrong1":"indefinite le prestazioni","wrong2":"indefinita la causa","wrong3":"indefinito l'oggetto"},{"id":802,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"Il potere di accettazione dell'oblato è:","correct":"un diritto potestativo","wrong1":"un interesse legittimo","wrong2":"un diritto soggettivo","wrong3":"una prerogativa tutelata"},{"id":803,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"La revoca è considerata:","correct":"un atto prenegoziale","wrong1":"un diritto soggettivo","wrong2":"un negozio giuridico unilaterale","wrong3":"un atto in senso stretto"},{"id":804,"paragraph":"I contratti della PA - La formazione del contratto e gli atti prenegoziali","question":"Il sistema di perfezionamento del contratto, nell'ipotesi in cui le parti si trovino in luoghi diversi, previsto dal codice civile è quello:","correct":"della presunzione di conoscenza","wrong1":"della ricezione","wrong2":"della spedizione","wrong3":"dell'emissione"},{"id":805,"paragraph":"I contratti della PA - La nullità del contratto","question":"La nullità è:","correct":"è uno strumento di controllo normativo","wrong1":"lo scopo di dare rilievo a interessi del contratto","wrong2":"è uno strumento di controllo pattizio","wrong3":"ha lo scopo di negare rilievo a interessi che siano coerenti con determinati principi dell'ordinamento."},{"id":806,"paragraph":"I contratti della PA - La nullità del contratto","question":"Ciò che distingue un atto invalido da un atto inesistente è:","correct":"la possibilità o meno di ricondurlo ad una fattispecie legale","wrong1":"la possibilità di annullarlo o renderlo nullo","wrong2":"il primo è nullo il secondo annullabile","wrong3":"non vi è alcuna differenza essendo gli stessi gli effetti di caducazione dell'atto"},{"id":807,"paragraph":"I contratti della PA - La nullità del contratto","question":"Il primo comma dell'art. 1418 c.c. prevede:","correct":"la nullità del contratto quando è contrario a norme imperative, salvo che la legge disponga diversamente","wrong1":"l'annullabilità quando il contratto è contrarip a norme imperative","wrong2":"l'annullabilità del contratto per difetto degli elementi essenziali","wrong3":"la nullità del contratto quando è contrario a norme di legge discrezionali"},{"id":808,"paragraph":"I contratti della PA - La nullità del contratto","question":"Le nullità indicate nel primo comma dell'art. 1418 c.c. sono:","correct":"nullità virtuali","wrong1":"Il comma si riferisce alle c.d. nullità strutturali","wrong2":"nullità in cui la legge individua un tipo ma rimanda alle norme imperative violate","wrong3":"nullità che incidono sugli elementi costitutivi del negozio"},{"id":809,"paragraph":"I contratti della PA - La nullità del contratto","question":"Il secondo comma dell'art. 1418 c.c. fa riferimento:","correct":"alle nullità strutturali","wrong1":"alle annullabilità strutturali","wrong2":"alle nullità virtuali","wrong3":"alle nullità testuali"},{"id":810,"paragraph":"I contratti della PA - La nullità del contratto","question":"Il terzo comma dell'art. 1418 c.c. si riferisce:","correct":"alle nullità testuali","wrong1":"alle nullità virtuali","wrong2":"alle nullità strutturali","wrong3":"alle annullabilità strutturali"},{"id":811,"paragraph":"I contratti della PA - La nullità del contratto","question":"Il contratto nullo:","correct":"non può produrre alcun effetto","wrong1":"può produrre alcun effetto","wrong2":"può produrre alcun effetto solo parziali","wrong3":"non può produrre alcun effetto salvo diversa pattuizione delle parti"},{"id":812,"paragraph":"I contratti della PA - La nullità del contratto","question":"La sentenza con cui si dichiara la nullità ha natura:","correct":"di mero accertamento","wrong1":"costitutiva","wrong2":"identica a quella prevista per l'azione di annullamento","wrong3":"abrogativa, andando a cancellare gli effetti del contratto"},{"id":813,"paragraph":"I contratti della PA - La nullità del contratto","question":"Il contratto nullo:","correct":"non può essere convalidato, salvo che la legge disponga altrimenti (art. 1423 c.c.)","wrong1":"può essere sempre convalidato","wrong2":"è per sua natira convalidabile per il principi di conservazione degli effetti del contratto","wrong3":"la convalida non è mai ammissibile"},{"id":814,"paragraph":"I contratti della PA - La nullità del contratto","question":"La nullità parziale:","correct":"è la nullità di una sola clausola del contratto, ovvero della nullità nei contratti plurilaterali, ossia nei contratti con più di due parti","wrong1":"comporta la nullità dell'intero contratto","wrong2":"è stata dichiarata costituizionalmente illegittima","wrong3":"la nullità del contratto per sua natura comporta la caducazione dell'intero contratto e, quindi, l'ipotesi di nullità parziale prevista dalla dottrina è negata dalla giurisprudenza"},{"id":815,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Forme di invalidità negoziale sono:","correct":"l'ordinamento ricomprende le due ipotesi della nullità e dell'annullabilità","wrong1":"le nullità e le inesistenze","wrong2":"l'ordinamento ricomprende le due ipotesi tassative solo di nullità","wrong3":"esclusivamente l'annullabilità"},{"id":816,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Tra le caratteristiche dell'annullabilità non rientra:","correct":"l'irretroattività della pronuncia di annullamento","wrong1":"legittimazione relativa","wrong2":"rinunziabilità","wrong3":"la prescrittibilità dell'azione"},{"id":817,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Rientrano nella nozione di incapacità a contrarre:","correct":"tanto l'incapacità legale (minore età, interdizione giudiziale e legale, inabilitazione), quanto l'incapacità naturale (incapacità di intendere e di volere)","wrong1":"solo l'incapacità legale","wrong2":"esclusivamente l'incapacità naturale)","wrong3":"solo i casi di incapacità di intendere e di volere, altre forme sono contra ius"},{"id":818,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Al fine dell'invalidità del negozio per incapacità naturale:","correct":"non è necessaria la prova che il soggetto, nel momento del compimento dell'atto, versava in uno stato patologico tale da far venir meno, in modo totale e assoluto, le facoltà psichiche, essendo sufficiente accertare che tali facoltà erano perturbate al punto da impedire al soggetto una seria valutazione del contenuto e degli effetti del negozio, e quindi il formarsi di una volontà cosciente","wrong1":"è necessaria la prova che il soggetto, nel momento del compimento dell'atto, versava in uno stato patologico tale da far venir meno, in modo totale e assoluto, le facoltà psichiche, essendo sufficiente accertare che tali facoltà erano perturbate al punto da impedire al soggetto una seria valutazione del contenuto e degli effetti del negozio, e quindi il formarsi di una volontà cosciente","wrong2":"non è sufficiente accertare che tali facoltà erano perturbate al punto da impedire al soggetto una seria valutazione del contenuto e degli effetti del negozio, e quindi il formarsi di una volontà cosciente","wrong3":"è che il soggetto, nel momento del compimento dell'atto, versava in uno stato patologico tale da far venir meno, in modo totale e assoluto, le facoltà psichiche"},{"id":819,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Il contratto non è annullabile, se il minore:","correct":"ha con raggiri occultato la sua minore età, ma la semplice dichiarazione da lui fatta di essere maggiorenne non è di ostacolo all'impugnazione del contratto","wrong1":"ha dichiarato di essere maggiorenne","wrong2":"ha espresso il desiderio che il contratto non sia annullabile","wrong3":"con la semplice dichiarazione di essere maggiorenne è creduta senza controlli dalla controparte"},{"id":820,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"L'errore è causa di annullamento del contratto quando:","correct":"è essenziale ed è riconoscibile dall'altro contraente","wrong1":"solo se essenziale","wrong2":"solo se riconoscibile","wrong3":"non è essenziale, ma al contempo riconoscibile dall'altro contraente."},{"id":821,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Per errore comune si intende:","correct":"quello in cui siano incorsi entrambi i contraenti ed avente (per entrambi) il medesimo contenuto","wrong1":"quel particolare errore che integra un doppio errore asimmetrico, e va risolta in termini di dissenso palese","wrong2":"ricorre nell'ipotesi in cui i contraenti sono incorsi ciascuno in un diverso errore","wrong3":"quello in cui sia incorso solo uno dei contraenti ed avente per entrambi i contraenti il medesimo contenuto"},{"id":822,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"L'annullabilità, al contrario della nullità, è:","correct":"è caratterizzata da prescrittibilità, relatività, sanabilità e irrilevabilità d'ufficio","wrong1":"imprescrittibilità, assoluta, insanabile e irrilevabile d'ufficio","wrong2":"imprescrittibilità, assoluta, insanabile e irrilevabile d'ufficio","wrong3":"è caratterizzata da imprescrittibilità, relatività, sanabilità e irrilevabilità d'ufficio"},{"id":823,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Legittimato ad agire per l'annullamento del contratto:","correct":"il soggetto nel cui interesse è stata prevista l'annullabilità ovvero chi potrà ottenere un effetto favorevole, patrimoniale o non, dalla sentenza che accolga la sua azione","wrong1":"solo il Pubblico Ministero","wrong2":"solo il giudice","wrong3":"solo chi ha causato l'annullabilità"},{"id":824,"paragraph":"I contratti della PA - L'annullabilità del contratto","question":"Il contratto annullabile:","correct":"può essere convalidato dal contraente al quale spetta l'azione di annullamento, mediante un atto che contenga la menzione del contratto e del motivo di annullabilità, e la dichiarazione che s'intende convalidarlo","wrong1":"non può essere convalidato dal contraente al quale spetta l'azione di annullamento, mediante un atto che contenga la menzione del contratto e del motivo di annullabilità, e la dichiarazione che s'intende convalidarlo","wrong2":"non può essere convalidato, se il contraente al quale spettava l'azione di annullamento vi ha dato volontariamente esecuzione conoscendo il motivo di annullabilità.","wrong3":"non è in alcun modo convalidabile"},{"id":825,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Le amministrazioni pubbliche possono stipulare:","correct":"tutti i contratti, anche atipici, finalizzati al soddisfacimento delle proprie finalità istituzionali","wrong1":"i soli contratti previsti dalla legge, non disponendo di autonomia negoziale","wrong2":"contratti con prestazioni sinallagmatiche e di durata, insuscettibili di revisione","wrong3":"tutti i contratti previsti dall'ordinamento, purché a titolo oneroso"},{"id":826,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Nello scegliere il proprio contraente, le amministrazioni:","correct":"devono attenersi a criteri oggettivi, finalizzati ad assicurare il buon andamento e l'imparzialità","wrong1":"hanno la stessa libertà dei soggetti privati","wrong2":"devono sempre preferire il contraente che propone il prezzo più basso","wrong3":"devono favorire le grandi imprese, in quanto più affidabili"},{"id":827,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Il principio del risultato:","correct":"condiziona l'esercizio della discrezionalità dell'amministrazione e costituisce criterio interpretativo prioritario delle regole del codice dei contratti pubblici","wrong1":"si riferisce alla dimensione processuale, impendendo al giudice l'adozione delle decisioni più sfavorevoli per l'interesse pubblico","wrong2":"è un corollario del principio di imparzialità","wrong3":"è sempre subordinato al principio della concorrenza, che rappresenta la fondamentale ratio della disciplina dell'evidenza pubblica"},{"id":828,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"La trasparenza:","correct":"tende ad assicurare la massima semplicità e celerità nella corretta applicazione delle regole del codice e ne assicura la piena verificabilità","wrong1":"è strumentale ad assicurare il favor partecipationis","wrong2":"tende ad assicurare la rapidità della decisione dell'amministrazione","wrong3":"tende a facilitare la verificabilità della decisione dell'amministrazione"},{"id":829,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Il principio della fiducia:","correct":"serve a responsabilizzare i funzionari, contrastando la c.d. \"paura della firma\"","wrong1":"è recessivo rispetto all'esigenza di garantire l'efficienza dell'azione amministrativa","wrong2":"non si applica alle procedure sottoposte alla vigilanza dell'Autorità nazionale anticorruzione","wrong3":"esonera l'amministrazione dal verificare la veridicità delle dichiarazioni rese dagli operatori economici in sede di gara"},{"id":830,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Non costituisce colpa grave ai fini della responsabilità dei funzionari per gli atti da loro compiuti nell'ambito di una procedura di evidenza pubblica:","correct":"la violazione di norme di diritto che sia stata determinata dall'adesione a orientamenti giurisprudenziali prevalenti o a pareri di autorità competenti","wrong1":"la violazione degli autovincoli amministrativi, salvo che ne sia derivata l'esclusione del concorrente","wrong2":"l'introduzione nel bando di gara di cause di esclusione non previste dal codice dei contratti pubblici, se non risulta che sono discriminatorie","wrong3":"la palese violazione delle regole di prudenza e di perizia"},{"id":831,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"La tutela dell'affidamento:","correct":"presuppone che il concorrente aggiudicatario non potesse agevolmente rilevare, in base alla diligenza professionale da lui esigibile, l'illegittimità del provvedimento di aggiudicazione annullato","wrong1":"sussiste in tutti i casi in cui l'operatore economico sia stato danneggiato da un atto illegittimo dell'amministrazione","wrong2":"sussiste nei confronti del solo aggiudicatario che abbia subito l'annullamento dell'aggiudicazione","wrong3":"sussiste nei soli confronti del concorrente illegittimamente escluso"},{"id":832,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Per il principio della tassatività delle cause di esclusione:","correct":"le cause di esclusione dalle procedure di gara sono solo quelle previste dal codice dei contratti pubblici, senza possibilità per l'amministrazione di introdurne di ulteriori","wrong1":"l'amministrazione è tenuta a stabilire nel bando o nell'avviso indittivo della gara le cause di esclusione dei concorrenti, senza possibilità di integrarle in un secondo momento","wrong2":"sanziona con l'annullabilità le cause di esclusione atipiche, cioè che non hanno una base normativa primaria o secondaria","wrong3":"rende illegittima un'esclusione che, pur essendo prevista dalla legge, non è stata recepita espressamente dal bando o dall'avviso indittivo della gara"},{"id":833,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Il principio di auto-organizzazione:","correct":"prevede che l'amministrazione possa, motivando in ordine alle ragioni di convenienza, optare per la produzione in proprio di beni e di servizi, anche mediante affidamento in favore di società in house","wrong1":"prevede che l'amministrazione possa ricorrere alla propria stessa organizzazione per la produzione di beni e servizi, solo quando non sia possibile reperirli sul mercato","wrong2":"prevede che l'amministrazione possa affidare direttamente ad altre amministrazioni la produzione di beni e servizi","wrong3":"prevede che l'amministrazione possa sempre recedere da un contratto, quando risulti più conveniente autoprodurre i beni e i servizi che ne formavano oggetto"},{"id":834,"paragraph":"I contratti della PA - I principi generali del Codice dei Contratti Pubblici","question":"Il principio di conservazione dell'equilibrio contrattuale:","correct":"trova applicazione alla generalità dei contratti pubblici, consentendone la rinegoziazione al verificarsi di circostanze straordinarie e imprevedibili che abbiano modificato in misura rilevante l'equilibrio originario del rapporto","wrong1":"trova applicazione ai soli contratti non aleatori, tra cui la concessione di servizi","wrong2":"non si applica, di regola, agli appalti di lavori, salvo che non si verifichi un aumento medio del costo dei materiali, per come risultante dai dati Istat, superiore al 30%","wrong3":"opera a tutela delle piccole e medie imprese, non potendo trovare applicazione per appalti superiori alla soglia comunitaria, in quanto si presume che il contraente abbia gli strumenti per far fronte alle alterazioni determinate da circostanze imprevedibili al momento della stipula"},{"id":835,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"L'istituto della rescissione risponde ad una esigenza:","correct":"di equità nelle contrattazioni, in ossequio alla quale si impone che prestazioni e controprestazioni siano in equilibrio tra di loro","wrong1":"di non equità nelle contrattazioni","wrong2":"che prestazioni e controprestazioni non richiedano un equilibrio tra di loro","wrong3":"di contrattazioni che possono essere eque o non eque"},{"id":836,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"Costituisce principio fondamentale dei contratti a prestazioni corrispettive quello:","correct":"della corrispondenza e stabilità tra prestazione e controprestazione, sia in fase genetica che funzionale","wrong1":"della corrispondenza e stabilità tra prestazione e controprestazione solo nella fase genetica","wrong2":"della corrispondenza e stabilità tra prestazione e controprestazione solo nella fase funzionale","wrong3":"della stabilità tra prestazione e controprestazione, ma non anche della corrispondenza che è richiesta solo in fase di trattazione"},{"id":837,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"Lo stato di pericolo è una prima ipotesi di rescissione e richiede:","correct":"deve essere non solo noto alla controparte ma questa deve anche trarne un lucro","wrong1":"è identica alla nozione di cui all'art. 54 c.p.","wrong2":"può essere ignoto alla controparte","wrong3":"sussiste indipendentemente dal fatto che la controparte ne trae un lucro"},{"id":838,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"L'art. 1447 c.c. è:","correct":"norma eccezionale e come tale non è possibile un'applicazione analogica","wrong1":"può essere applicata ad ipotesi non previste dal legislatore","wrong2":"è suscettibile di interpretazione analogica","wrong3":"è norma ordinaria"},{"id":839,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"La risoluzione:","correct":"non rappresenta una ipotesi di invalidità negoziale","wrong1":"comporta che il contratto non è valido","wrong2":"rappresenta una ipotesi di invalidità negoziale","wrong3":"nel contratto invalido interviene una turbativa"},{"id":840,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"La distinzione tra risoluzione giudiziale e risoluzione legale consiste:","correct":"si deve al fatto che la prima presuppone l'intervento del giudice, la seconda invece opera automaticamente","wrong1":"si deve al fatto che la prima è stragiudiziale e la seconda legale","wrong2":"solo la prima è ipso iure","wrong3":"solo la seconda richiede l'intervento di un giudice"},{"id":841,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"La risoluzione per inadempimento:","correct":"ben può essere richiesta dal contraente che ha inizialmente chiesto giudizialmente l'adempimento","wrong1":"non può essere richiesta dal contraente che ha inizialmente chiesto giudizialmente l'adempimento","wrong2":"si identifica con la cd. manutenzione del contratto","wrong3":"si identifica nella cd. eccezione di inadempimento"},{"id":842,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"L'inadempimento, per giustificare la risoluzione, deve essere:","correct":"di non scarsa importanza","wrong1":"di scarsa importanza","wrong2":"di qualunque natura","wrong3":"anche di scarsa importanza"},{"id":843,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"Ai sensi dell'art. 1256 c.c.:","correct":"l'obbligazione si estingue se l'impossibilità perdura fino a quando, in relazione al titolo dell'obbligazione o alla natura dell'oggetto, il debitore non può più essere ritenuto obbligato a eseguire la prestazione ovvero il creditore non ha più interesse a conseguirla","wrong1":"l'obbligazione si estingue se l'impossibilità è solo temporanea","wrong2":"l'impossibilità idonea ad estinguere l'obbligazione, ex art. 1256 c.c., deve intendersi in senso relativo","wrong3":"l'impossibilità consiste consiste nella sopravvenienza di una causa, imputabile al debitore, che impedisce definitivamente l'adempimento"},{"id":844,"paragraph":"I contratti della PA - La rescissione e la risoluzione del contratto","question":"La risoluzione per eccessiva onerosità sopravvenuta:","correct":"scatta quando la prestazione per una delle parti sia divenuta eccessivamente onerosa a causa del verificarsi di avvenimenti straordinari ed imprevedibili che non possono rientrare, in quanto tale, nella normale incertezza economica di un assetto contrattuale (cd. alea del contratto)","wrong1":"scatta quando la prestazione per una delle parti sia divenutaonerosa a causa del verificarsi di avvenimenti che rientrano nell' alea del contratto","wrong2":"scatta quando la prestazione per una delle parti sia divenuta eccessivamente onerosa a causa del verificarsi di avvenimenti che rientrano nell'alea del contratto","wrong3":"scatta quando non si è rispettato il termine essenziale in modo sopravvenuto"},{"id":845,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Il legislatore con le norme sull'interpretazione:","correct":"ha attribuito rilevanza primaria all'individuazione dell'assetto di interessi concordato dalle parti","wrong1":"ha attribuito rilevanza primaria all'ntegrazione del contratto","wrong2":"ha inteso disattere la comune intenzione delle parti","wrong3":"ha inteso disciplinare solo i negozi a contenuto patrimoniale"},{"id":846,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Se il dato letterale è considerato inequivoco:","correct":"il giudice, preso atto del contenuto del contratto, non può operare alcuna interpretazione conservativa","wrong1":"il giudice deve sempre operare una interpretazione estensiva","wrong2":"il giudice deve sempre operare una interpretazione evolutiva","wrong3":"il giudice può sempre operare una interpretazione conservativa"},{"id":847,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Le norme codicistiche che regola interpretazione del contratto:","correct":"sono sempre vincolanti per l'interprete","wrong1":"sono vincolanti solo in forza di una sentenza","wrong2":"non sono mai vincolanti per l'interprete","wrong3":"sono vincolanti per l'interprete son nel caso in cui il contratto risulti oscuro"},{"id":848,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Le norme di interpretazione soggettiva:","correct":"sono dirette a cercare la comune intenzione delle parti","wrong1":"sono dirette a cercare il significato letterale proprio delle parole","wrong2":"sono volte a identificare il significato obiettivo delle clausole contrattuali","wrong3":"sono ispirate al principio di equità"},{"id":849,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"In applicazione del criterio sistematico:","correct":"le clausole contrattuali vanno interpretate le une per mezzo delle altre attribuendo a ciascuna di esse il senso che risulta dall'atto complessivamente considerato","wrong1":"le clausole vanno interpretate secondo il loro significato obiettivo","wrong2":"le clausole vanno interpretate secondo esi e equità","wrong3":"le clausole vanno interpretate secondo il principio in clasi non fit interpretatio"},{"id":850,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Ai sensi dell'art. 1367:","correct":"nel dubbio, il contratto o le singole clausole devono interpretarsi nel senso che possano avere un qualche effetto","wrong1":"le clausole vanno interpretate sempre secondo buona fede","wrong2":"le clausole vanno interpretate secondo il loro significato obiettivo","wrong3":"nel dubbio, il contratto o le singole clausole devono interpretarsi nel senso che non abbiano effetto"},{"id":851,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Le clausole inserite nelle condizioni generali di contratto o in moduli o formulari predisposti da uno dei contraenti s'interpretano, nel dubbio:","correct":"a favore dell'altro","wrong1":"a favore di entrambi","wrong2":"secondo il criterio evolutivo","wrong3":"secondo il criterio sistematico"},{"id":852,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"L'interpretazione evolutiva:","correct":"è quella fissata da norme che fissano all'interprete lo scopo al quale deve mirare nello svolgimento della sua attività","wrong1":"è quella secondo cui le clausole contrattuali vanno interpretate le une per mezzo delle altre attribuendo a ciascuna di esse il senso che risulta dall'atto complessivamente considerato","wrong2":"è anche detta secondo equità","wrong3":"è anche detta sistematica"},{"id":853,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Il contratto:","correct":"obbliga le parti non solo a quanto è nel medesimo espresso ma anche a tutte le conseguenze che ne derivano secondo la legge, o, in mancanza, secondo gli usi e l'equità","wrong1":"obbliga le parti solo a tutte le conseguenze che ne derivano secondo la legge, o, in mancanza, secondo gli usi e l'equità","wrong2":"obbliga le parti solo a quanto è nel medesimo espresso","wrong3":"obbliga le parti solo a quanto ne deriva secondo equità"},{"id":854,"paragraph":"I contratti della PA - Interpretazione e integrazione del contratto","question":"Al primo posto tra le fonti di integrazione vi è:","correct":"la legge","wrong1":"l'equità","wrong2":"gli usi negoziali","wrong3":"il contratto"},{"id":855,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Il partenariato pubblico -privato:","correct":"è un genus rispetto a figure contrattuali quali la concessione, la locazione finanziaria, il contratto di disponibilità","wrong1":"è una species rispetto alla più ampia categoria delle concessioni","wrong2":"è un accordo procedimentale","wrong3":"è un contratto di concessione di servizi"},{"id":856,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Il partenariato pubblico - privato si distingue:","correct":"in contrattuale e istituzionale","wrong1":"in pubblico o privato","wrong2":"in qualificato o non qualificato","wrong3":"con negoziazione o senza negoziazione"},{"id":857,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"La concessione si differenzia dall'appalto:","correct":"perché vi è una traslazione in capo al concessionario del rischio operativo","wrong1":"perché è onerosa","wrong2":"perché non vi è una traslazione in capo al concessionario del rischio operativo","wrong3":"perchè è stipulato per iscritto a pena di nullità"},{"id":858,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"La durata della concessione:","correct":"è commisurata al valore della concessione","wrong1":"non può essere in alcun caso prorogata","wrong2":"può essere illimitata e indeterminata in ipotesi eccezionali","wrong3":"deve essere superiore al periodo di tempo necessario al recupero degli investimenti"},{"id":859,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"La finanza di progetto:","correct":"è un capitolo \"interno\" alla concessione","wrong1":"può essere solo ad iniziativa pubblica","wrong2":"può essere sia ad iniziativa privata che pubblica","wrong3":"è un raggruppamento temporaneo di imprese"},{"id":860,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"La locazione finanziaria:","correct":"è una species del partenariato pubblico privato","wrong1":"è una species del contratto di disponibilità","wrong2":"è un genus rispetto alle concessioni","wrong3":"è un genus rispetto al partenariato pubblico - privato"},{"id":861,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contratto di disponibilità:","correct":"consiste nella \"messa a disposizione\" di un'opera - che, per l'intera durata del contratto, resta di proprietà privata - a fronte di un corrispettivo da parte dell'ente pubblico","wrong1":"consiste nella messa a disposizione di un'opera - che, per l'intera durata del contratto, resta di proprietà privata - a fronte di un corrispettivo da parte del privato","wrong2":"consiste in un contratto autonomo caratterizzato dal coinvolgimento della società di leasing","wrong3":"consiste in un'operazione di finanziamento diretta a sostenere un progetto capace di generre flussi di cassa sufficienti a remunerare l'investimento"},{"id":862,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contratto di disponibilità:","correct":"non ha trovato spesso applicazione perchè le stesse esigenze si possono realizzare con la concessione","wrong1":"è stato introdotto per la prima volta nel Codice Appalti del 2023","wrong2":"è la forma di partenariato pubblico - privata più applicata","wrong3":"non ha trovato spesso applicazione perché le stesse esigenze si possono realizzare con la finanza di progetto"},{"id":863,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Il contraente generale:","correct":"è una species dei contratti a prestazione complessa aventi ad oggetto servizi globali","wrong1":"è il genus del global service","wrong2":"è il genus delle concessioni e del partenariato pubblico - privato","wrong3":"è il genus dei contratti a prestazione complessa aventi ad oggetto servizi globali"},{"id":864,"paragraph":"I contratti della PA - Contratti pubblici: tipologie contrattuali e soglie","question":"Ai contratti sopra soglia:","correct":"si applicano le norme contenute nelle direttive comunitarie recepite a livello nazionale dal Codice dei contratti pubblici","wrong1":"non si applica la L. n. 241 del 1990","wrong2":"non si applicano le norme contenute nelle direttive comunitarie recepite a livello nazionale dal Codice dei contratti pubblici","wrong3":"non si applicano le disposizioni del Codice appalti"},{"id":865,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"Le amministrazioni aggiudicatrici si distinguono in:","correct":"amministrazioni centrali; amministrazioni subcentrali; organismo di diritto pubblico","wrong1":"amministrazioni centrali; enti aggiudicatori; joint venture","wrong2":"amministrazioni centrali; enti aggiudicatori; imprese pubbliche","wrong3":"amministrazioni centrali; enti aggiudicatori; stazioni appaltanti qualificate"},{"id":866,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"La nozione di organismo di diritto pubblico:","correct":"è una definizione funzionale i cui parametri sono i tre requisiti cumulativamente previsti dalla legge","wrong1":"comprende tutti i soggetti che esercitano un'attività economica, con la sola eccezione degli enti pubblici economici","wrong2":"va intesa in senso ampio, escludendo i soli soggetti che non perseguono un fine di lucro","wrong3":"va intesa in senso ampio, comprenendo tutti i soggetti che, indipendentemente dalla forma che assumono, sono abilitati alla realizzazione di lavori e alla fornitura di beni e servizi sul mercato"},{"id":867,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"Non è un requisito per la qualificazione di organismo di diritto pubblico:","correct":"il vincolo di scopo","wrong1":"la capacità giuridica","wrong2":"la circostanza che sia istituito per soddisfare esigenze di interesse generale, attraverso lo svolgimento di un'attività priva di carattere industriale o commerciale","wrong3":"la sottoposizione ad una influenza pubblica"},{"id":868,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"Il sistema di qualificazione delle stazioni appaltanti:","correct":"ha natura \"aperta\"","wrong1":"non è disciplinato né dal codice appalti né dagli allegati al Codice","wrong2":"è a numero chiuso","wrong3":"è gestito da Consip"},{"id":869,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"Tutte le stazioni appaltanti possono:","correct":"procedere direttamente e autonomamente all'affidamento di lavori d'importo pari o inferiore a 500.000 euro","wrong1":"procedere direttamente e autonomamente all'affidamento di lavorid'importo pari o inferiore a 1.000.00 euro","wrong2":"procedere direttamente all'acquisizione di forniture e servizi di importo superiore alle soglie previste per gli affidamenti diretti","wrong3":"procedere direttamente e autonomamente all'affidamento di lavorid'importo pari o inferiore a 750.000 euro"},{"id":870,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"L'Anac:","correct":"è l'autorità nazionale preposta a vigilare i contratti pubblici contrastando e prevenendo la corruzione","wrong1":"è l'autorià preposta a garantire la libera concorrenza del mercato","wrong2":"è l'autorità preposta alla vigilanza degli intermediari finanziari, sui mercati e sugli emittenti quotati","wrong3":"è l'autorità preposta a garantirela vigilanza sulle attività di trattamento dei dati personali"},{"id":871,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"L'Anac è in via esclusiva titolare:","correct":"della Banca dati nazionale dei contratti pubblici","wrong1":"del Repertorio nazionale dei dati territoriali","wrong2":"dell'indice delle Publiche Amministrazioni","wrong3":"del registro delle imprese"},{"id":872,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"All'Anac spettano funzioni:","correct":"di regolazione; di ispezione; di vigilanza; di raccomandazione; sanzionatorie; di amministrazione attiva","wrong1":"di regolazione; di ispezione; di vigilanza; di raccomandazione; sanzionatorie; di amministrazione attiva; di aggiudicazione","wrong2":"esclusivamente di vigilanza sui contratti pubblici","wrong3":"esclusivamente di vigilanza e regolazione sui contratti pubblici"},{"id":873,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"Il RUP:","correct":"il RUP svolge tutti i compiti relativi alle procedure di programmazione, progettazione, affidamento ed esecuzione previste dal Codice, non specificatamente attribuiti ad altri organi o soggetti","wrong1":"è un soggetto nominato tra i consiglieri di stato","wrong2":"non è responsabile di tutto l'intervento pubblico, ma solo di uno o più procedimenti","wrong3":"cessa le sue funzioni nella fase esecutiva della vicenda contrattuale"},{"id":874,"paragraph":"I contratti della PA - Contratti pubblici: ambito di applicazione soggettivo ed altri soggetti","question":"La figura del direttore dell'esecuzione:","correct":"è soggetto diverso dal RUP in caso di interventi particolarmente complessi sotto il profilo tecnologico","wrong1":"coincide sempre con quella del RUP","wrong2":"è un soggetto nominato tra i consiglieri di stato","wrong3":"svolge tutti i compiti relativi alle procedure di programmazione, progettazione, affidamento previste dal Codice"},{"id":875,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"La Direttiva del Consiglio delle Comunità Europee n.13 del 5 aprile 1993:","correct":"impose agli Stati membri di adottare una tutela contrattuale minima del consumatore nei confronti del professionista","wrong1":"facultizzò agli Stati membri di adottare una tutela contrattuale minima del consumatore nei confronti del professionista","wrong2":"invitò in modo non vincolante gli Stati membri di adottare una tutela contrattuale minima del consumatore nei confronti del professionista","wrong3":"impose agli Stati membri di adottare una tutela contrattuale minima del professionista nei confronti del consumatore"},{"id":876,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Tra gli scopi del codice del consumo rientrano:","correct":"l'armonizzazione e riordino delle normative concernenti i processi di acquisto e consumo","wrong1":"l'abrograzione di tutte le normative precedenti","wrong2":"l'armonizzazione ed l'abrogazione della normativa concernente acquisto e consumo","wrong3":"solo l'armonozzazione, non il riodino trattandosi di materia nuova imposta dall'Europa"},{"id":877,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Il professionista è:","correct":"la persona fisica o giuridica che agisce nell'esercizio della propria attività imprenditoriale, commerciale, artigianale o professionale, ovvero un suo intermediario","wrong1":"la persona fisica che agisce per scopi estranei all'attività imprenditoriale, commerciale, artigianale o professionale eventualmente svolta","wrong2":"i clienti, ossia coloro che agiscono per scopi estranei alla propria attività eventualmente esercitata","wrong3":"fatto salvo quanto stabilito nell'articolo 103, comma 1, lettera d), e nell'articolo 115, comma 2-bis, il fabbricante del bene o il fornitore del servizio, o un suo intermediario, nonché l'importatore del bene o del servizio nel territorio dell'Unione Europea o qualsiasi altra persona fisica o giuridica che si presenta come produttore identificando il bene o il servizio con il proprio nome, marchio o altro segno distintivo"},{"id":878,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Il consumatore o utente è:","correct":"persona fisica che agisce per scopi estranei all'attività imprenditoriale, commerciale, artigianale o professionale eventualmente svolta","wrong1":"la persona fisica o giuridica che agisce nell'esercizio della propria attività imprenditoriale, commerciale, artigianale o professionale, ovvero un suo intermediario","wrong2":"chi agisce nell'espletamento della propria attività","wrong3":"fatto salvo quanto stabilito nell'articolo 103, comma 1, lettera d), e nell'articolo 115, comma 2-bis, il fabbricante del bene o il fornitore del servizio, o un suo intermediario, nonché l'importatore del bene o del servizio nel territorio dell'Unione Europea o qualsiasi altra persona fisica o giuridica che si presenta come produttore identificando il bene o il servizio con il proprio nome, marchio o altro segno distintivo"},{"id":879,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"L'\"azione di classe\" è:","correct":"la procedura dinanzi al Tribunale finalizzata all'ottenimento del risarcimento del danno in capo a ciascun componente del gruppo di consumatori danneggiati da un medesimo fatto","wrong1":"la procedura dinanzi al Giudice di Pace finalizzata all'ottenimento del risarcimento del danno in capo a ciascun componente del gruppo di consumatori danneggiati da un medesimo fatto","wrong2":"la procedura dinanzi al Corte di Cassazione finalizzata all'ottenimento del risarcimento del danno in capo a ciascun componente del gruppo di consumatori danneggiati da un medesimo fatto","wrong3":"la procedura dinanzi al Tribunale penale finalizzata all'ottenimento della condanna agli effetti civili in capo a ciascun componente del gruppo di consumatori danneggiati da un medesimo fatto"},{"id":880,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"L'art. 1418 c.c. prevede:","correct":"tre diverse tipologie di nullità contrattuali: testuale (comma terzo), strutturale (comma secondo) e virtuale (comma primo)","wrong1":"due tre diverse tipologie di nullità contrattuali: testuale (comma secondo) e virtuale (comma primo)","wrong2":"un'unica tipologie di nullità contrattuali virtuale","wrong3":"che la nullità è virtuale quando la nullità del negozio è comminata direttamente dalla legge"},{"id":881,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Il codice civile ed il codice del consumo:","correct":"non si sovrappongono ma si integrano","wrong1":"sono autonome e non sovrapponibili","wrong2":"non possono integrarsi dato il principio di autonomia delle fonti","wrong3":"si sovrappongono e non si integrano"},{"id":882,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Tra le differenze tra le clausole vessatorie disciplinate dal c.c. e quelle del codice del consumo non rientra:","correct":"la rilevabilità d'ufficio sia nel c.c. che nel codice del consumo","wrong1":"le clausole civilistiche sono inefficaci quelle del codice del consumo nulle","wrong2":"la rilevabilità ex officio testualmente prevista dall'art. 36, comma 3, Codice del Consumo e preclusa nella disciplina codicistica.","wrong3":"l'art.35 del Decreto Legislativo n.206/2005 introduce il c.d. \"principio della trasparenza\" delle clausole, che devono essere formulate in modo chiaro e comprensibile, mentre non si rinviene un'analoga disposizione negli artt.1341 e 1342 c.c."},{"id":883,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"Con la nullità di protezione:","correct":"le clausole vessatorie sono nulle (e non più \"inefficaci\" come in passato), mentre il contratto rimane valido per il resto","wrong1":"le clausole vessatorie sono inefficaci ed il contratto a tutela del consumatore nullo","wrong2":"la nullità opera soltanto a vantaggio del professionista (per questo vessatoria).","wrong3":"la nullità opera soltanto a vantaggio del produttore (per questo è definita vessatoria)"},{"id":884,"paragraph":"I contratti della PA - Disciplina dei contratti del consumatore. Nullità di protezione","question":"L'art. 134 c. cons. prevede:","correct":"che è nullo ogni patto volto ad escludere i diritti riconosciuti al consumatore dalla disciplina relativa alla vendita di beni al consumo","wrong1":"che è valido ogni patto volto ad escludere i diritti riconosciuti al consumatore dalla disciplina relativa alla vendita di beni al consumo","wrong2":"che è annullabile ogni patto volto ad escludere i diritti riconosciuti al consumatore dalla disciplina relativa alla vendita di beni al consumo","wrong3":"che è escluso la disciplina relativa alla vendita di beni al consumo"},{"id":885,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Il raggruppamento temporaneo di impresa (RTI) costituisce una forma di collaborazione tra operatori:","correct":"caratterizzata da occasionalità e temporaneità, al fine di partecipare ad una specifica gara e gestire in caso di aggiudicazione la relativa commessa","wrong1":"caratterizzata dalla costituzione di una organizzazione di durata indefinita, stabilmente dedita alla partecipazione alle gare","wrong2":"caratterizzata dalla costituzione di un nuovo soggetto, con personalità giuridica differente da quella dei suoi membri, per la partecipazione ad una singola gara","wrong3":"caratterizzata dalla costituzione di una società di progetto, con oggetto sociale esclusivo, costituito per l'esecuzione del contratto pubblico messo a gara in caso di aggiudicazione"},{"id":886,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"La nozione di operatore economico:","correct":"va intesa in senso ampio, comprendendo tutti i soggetti che, indipendentemente dalla forma che assumono, sono abilitati alla realizzazione di lavori e alla fornitura di beni e servizi sul mercato","wrong1":"coincide con quella di società di capitali","wrong2":"comprende tutti i soggetti che esercitano un'attività economica, con la sola eccezione degli enti pubblici economici","wrong3":"va intesa in senso ampio, escludendo i soli soggetti che non perseguono un fine di lucro"},{"id":887,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Per consorzi stabili, l'art. 65 del Codice intende:","correct":"quelle aggregazioni di imprese formate da non meno di tre consorziati che abbiano stabilito di operare in modo congiunto nel settore dei contratti pubblici di lavori, servizi, forniture, per un periodo di tempo non inferiore a cinque anni, istituendo a tal fine una comune struttura di impresa","wrong1":"quelle aggregazioni di imprese formate da non meno di sei consorziati che abbiano stabilito di operare in modo congiunto nel settore dei contratti pubblici, per un periodo di tempo non inferiore a dieci anni, istituendo a tal fine una comune struttura di impresa","wrong2":"quelle aggregazioni di imprese formate da non meno di sette consorziati che abbiano stabilito di operare in modo occasionale nel settore dei contratti pubblici","wrong3":"quelle aggregazioni di imprese formate da non meno di dieci consorziati che abbiano stabilito di operare in modo congiunto nel settore dei contratti pubblici, per un periodo di tempo non inferiore a due anni, non istituendo a tal fine una comune struttura di impresa"},{"id":888,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"La stazione appaltante può imporre ai raggruppamenti temporanei:","correct":"di assumere una forma giuridica specifica dopo l'aggiudicazione del contratto, nel caso in cui tale trasformazione sia necessaria per la buona esecuzione del contratto","wrong1":"di sostituire l'impresa mandataria, nel caso sia priva dei requisiti di ordine generale","wrong2":"di assumere la forma di società consortile","wrong3":"di fondere le proprie organizzazioni dando vita ad un nuovo soggetto giuridico"},{"id":889,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Il mandatario del raggruppamento temporaneo di imprese:","correct":"è l'operatore economico al quale gli altri operatori del raggruppamento conferiscono mandato collettivo speciale con rappresentanza irrevocabile","wrong1":"è l'unico operatore legittimato ad impugnare gli atti di gara pregiudizievoli per il raggruppamento","wrong2":"è sempre l'operatore economico di maggiori dimensioni, in possesso dei requisiti per l'esecuzione della prestazione indicata come prevalente negli atti di gara","wrong3":"è responsabile in solido con gli altri operatori del raggruppamento soltanto in caso di raggruppamento verticale"},{"id":890,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"I raggruppamenti temporanei di imprese possono subire modifiche nella loro composizione:","correct":"in caso di mancanza dei requisiti in capo ad una o più delle imprese raggruppate","wrong1":"solo in caso di fallimento o di liquidazione del mandatario","wrong2":"solo in caso di fallimento o di liquidazione delle mandanti","wrong3":"solo in caso di recesso di una o più mandanti"},{"id":891,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"L'avvalimento si risolve nella possibilità per un operatore di partecipare a gare, provando di possedere i requisiti di partecipazione richiesti dalla stazione appaltante:","correct":"mediante ricorso alla capacità di un terzo, che disponga dei predetti requisiti","wrong1":"mediante ricorso ad agenzie di consulenza","wrong2":"mediante costituzione di raggruppamenti temporanei di impresa","wrong3":"mediante partecipazione a consorzi stabili"},{"id":892,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Il contratto di avvalimento:","correct":"è normalmente a titolo oneroso, richiede la forma scritta ad substantiam e deve contenere a pena di nullità la specifica indicazione dei mezzi e delle risorse messi a disposizione","wrong1":"richiede la forma scritta ad substantiam e deve contenere l'impegno a prestare i requisiti mancanti a titolo gratuito","wrong2":"è necessariamente a titolo oneroso, ma può essere stipulato anche oralmente, purché risulti da fatti univoci","wrong3":"è necessariamente a titolo oneroso, richiede la forma scritta ad probationem e deve contenere sempre la specifica indicazione dei mezzi e delle risorse messi a disposizione"},{"id":893,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Il soccorso istruttorio:","correct":"può essere utilizzato per acquisire il contratto di avvalimento e la dichiarazione di impegno mancanti, purché si tratti di atti aventi data certa anteriore alla scadenza del termine per la presentazione delle offerte","wrong1":"può essere sempre utilizzato per colmare le lacune di un contratto di avvalimento nullo","wrong2":"può essere utilizzato solo per acquisire la dichiarazione di impegno dell'impresa ausiliaria, purché l'impegno risulti comunque dal contratto tempestivamente prodotto unitamente all'offerta","wrong3":"non può mai essere utilizzato in relazione all'avvalimento, perché violerebbe la par condicio fra i concorrenti"},{"id":894,"paragraph":"I contratti della PA - Contratti pubblici: la nozione di operatore economico e la partecipazione in forma associata alle procedure di evidenza pubblica. Avvalimento e subappalto","question":"Il subappalto:","correct":"rileva in fase di esecuzione, ma non ai fini della partecipazione alla procedura","wrong1":"è una modalità di partecipazione associata alle procedure di gara, alternativa all'avvalimento e al raggruppamento temporaneo","wrong2":"può essere utilizzato nei limiti del 30% delle prestazioni oggetto del contratto di appalto","wrong3":"consente di affidare le prestazioni oggetto del contratto ad imprese che, non essendo in possesso dei requisiti di ordine generale, non potrebbero partecipare direttamente alla gara"},{"id":895,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"I requisiti generali per la partecipazione alle procedure di evidenza pubblica si distinguono in:","correct":"ad esclusione automatica e ad esclusione non automatica","wrong1":"penali e amministrativi","wrong2":"morali e di capacità tecnica","wrong3":"morali e speciali"},{"id":896,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Le condanne penali per i reati così detti \"ostativi\":","correct":"danno luogo ad esclusione automatica solo se passate in giudicato","wrong1":"danno luogo a esclusione anche se non sono definitive","wrong2":"danno luogo ad esclusione facoltativa, purché siano passate in giudicato","wrong3":"comportano l'esclusione solo in caso di condanna a non meno di cinque anni di reclusione"},{"id":897,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"I motivi di esclusione fondati su condanne penali o su misure antimafia sono rilevanti se:","correct":"riguardano esponenti aziendali che, per la posizione rivestita, possono esercitare un significativo potere di direzione o di controllo","wrong1":"riguardano un dipendente dell'azienda","wrong2":"riguardano il titolare dell'azienda","wrong3":"riguardano i soci dell'impresa, se trattasi di soggetto collettivo, o il titolare, se trattasi di impresa individuale"},{"id":898,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Le violazioni fiscali e contributive integrano cause di esclusione:","correct":"automatica o facoltativa, a seconda della definitività o meno dell'accertamento e della loro gravità","wrong1":"automatica","wrong2":"facoltativa","wrong3":"automatica, ma solo se si tratta di violazioni che superano la soglia di gravità prevista dalla legge"},{"id":899,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Le violazioni fiscali e contributive determinano l'esclusione del concorrente solo se:","correct":"superano la soglia di gravità prevista dalla legge, che varia a seconda della definitività o meno dell'accertamento","wrong1":"superano la soglia di gravità prevista dalla legge, non inferiore, in ogni caso, al 10% del valore dell'appalto","wrong2":"sono accertate definitivamente","wrong3":"non sono state oggetto di contestazione giudiziale"},{"id":900,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Il grave illecito professionale:","correct":"può essere integrato da una condanna penale, anche non definitiva e per reati diversi da quelli ostativi","wrong1":"non ha alcun punto di contatto con le condanne penali, perché le condanne penali sono rilevanti solo ai fini dell'esclusione automatica del concorrente","wrong2":"può essere integrato da una condanna penale, ma solo se riguarda gli stessi reati ostativi per i quali è disposta la comminatoria dell'esclusione","wrong3":"può essere integrato da una condanna penale, anche per reati diversi da quelli ostativi, purché si tratta di condanna definitiva, spettando alla Stazione appaltante valutarne la rilevanza ai fini della procedura di evidenza pubblica"},{"id":901,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Le ipotesi di grave illecito professionale sono:","correct":"tipiche e tassativamente previste dall'art. 98 del codice","wrong1":"atipiche e suscettibili di apprezzamento discrezionale da parte dell'amministrazione, secondo i criteri previsti dall'art. 98 del codice","wrong2":"esemplificativamente previste dall'art. 98, potendo l'amministrazione assumere come rilevanti fattispecie anche non espressamente contemplate, purché condividano la medesima ratio di quelle espressamente contemplate","wrong3":"da individuarsi a cura dell'ANAC con apposite linee guida"},{"id":902,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"I criteri di selezione:","correct":"si distinguono in requisiti di idoneità professionale, di capacità economico-finanziaria e di capacità tecnico-professionale","wrong1":"attengono alla sfera soggettiva del concorrente e non sono mai suscettibili di avvalimento","wrong2":"attengono alla capacità del concorrente e servono a selezionare i contraenti idonei all'esecuzione in subappalto delle prestazioni richieste dalla stazione appaltante","wrong3":"si distinguono in requisiti di capacità finanziaria e di capacità professionale"},{"id":903,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"I criteri di selezione:","correct":"devono essere proporzionati e attinenti all'oggetto della procedura","wrong1":"devono essere attinenti alla procedura e non eccedere il triplo del valore dell'appalto","wrong2":"devono essere proporzionati all'oggetto della procedura, ma non eccedere il valore dell'appalto","wrong3":"devono essere predeterminati, trasparenti e attinenti all'oggetto dell'appalto"},{"id":904,"paragraph":"I contratti della PA - Contratti pubblici: motivi di esclusione e requisiti di partecipazione alle procedure di gara. Il soccorso istruttorio","question":"Il soccorso istruttorio può essere utilizzato:","correct":"per sanare irregolarità anche essenziali della documentazione presentata, con l'eccezione dell'offerta tecnica e dell'offerta economica","wrong1":"per sanare irregolarità non essenziali della domanda di partecipazione","wrong2":"per sanare irregolarità essenziali, con l'eccezione dell'avvalimento nullo","wrong3":"per sanare le irregolarità attinenti all'offerta tecnica, purché non ciò non dia luogo ad una lesione della par condicio fra i candidati"},{"id":905,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"La decisione di contrarre:","correct":"deve contenere gli elementi essenziali del bando, i criteri di selezione degli operatori economici e delle loro offerte","wrong1":"è il bando","wrong2":"deve contenere solo gli elementi essenziali del contratto","wrong3":"è il provvedimento di aggiudicazione"},{"id":906,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Il bando:","correct":"costituisce l'atto iniziale della procedura di gara","wrong1":"è il provvedimento di aggiudicazione della gara","wrong2":"è il provvedimento con cui si esterna la volontà a contrarre","wrong3":"è un accordo tra pubblica amministrazione e privato"},{"id":907,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"La procedura aperta:","correct":"è una procedura in cui tutti gli operatori economici interessati possono prendere parte alla gara purchè in possesso dei requisiti di partecipazione previsti dal bando","wrong1":"è flessibile","wrong2":"è una procedura in cui tutti posso chiedere di partecipare, ma possono prendere parte alla gara solo gli operatori economici invitati dalla stazione appaltante","wrong3":"è una procedura di selezione senza pubblicazione del bando"},{"id":908,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"La procedura ristretta:","correct":"è una procedura di selezione in cui chiunque può chiedere di partecipare ma solo gli operatori economici invitati possono presentare una offerta","wrong1":"è una procedura di selezione senza pubblicazione del bando","wrong2":"è una procedura di selezione in cui non tutti gli operatori economici possono chiedere di partecipare","wrong3":"è una procedura di selezione in cui non tutti possono partecipare, ma tutti coloro che partecipano possono presentare una offerta"},{"id":909,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Le procedure negoziate:","correct":"sono procedure in cui le stazioni appaltanti possono scegliere gli operatori economici e negoziare con essi le condizioni del contratto","wrong1":"sono procedure in cui le stazioni appaltanti possono scegliere gli operatori e impongono, tuttavia, le condizioni del contratto","wrong2":"sono procedure in cui i requisiti minimi sono imposti dagli operatori economici","wrong3":"è una procedura di selezione in cui non tutti possono partecipare, ma tutti coloro che partecipano possono presentare una offerta"},{"id":910,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Le procedure negoziate:","correct":"possono essere senza pubblicazione del bando di gara nei casi tassativamente previsti dalla legge","wrong1":"possono essere aperte o ristrette","wrong2":"possono essere a titolo oneroso o gratuito","wrong3":"non possono essere senza pubblicazione del bando di gara"},{"id":911,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Il dialogo competitivo:","correct":"è una procedura di evidenza pubblica per la scelta del contraente, caratterizzata da un serrato confronto fra le parti nella fase progettuale","wrong1":"è una particolare forma di partenariato per l'innovazione","wrong2":"è una species del partenariato per l'innovazione","wrong3":"a differenza delle altre procedure di selezione non è ad evidenza pubblica"},{"id":912,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Il dialogo competitivo:","correct":"è una procedura in cui si applica unicamente il criterio dell'offerta con il miglior rapporto qualità/prezzo","wrong1":"è una procedura cui possono partecipare massimo tre operatori economici","wrong2":"è una procedura in cui si applica unicamente il criterio del minor prezzo","wrong3":"è una procedura in cui possono partecipare massimo quattro operatori economici"},{"id":913,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"Il partenariato per l'innovazione:","correct":"può essere utilizzato quando non vi sono soluzioni idonee disponibili sul mercato","wrong1":"può sempre essere applicato dalle stazioni appaltanti","wrong2":"può essere utilizzato quando vi sono troppe soluzioni disponibili sul mercato","wrong3":"non può più essere utilizzato da quando è entrato in vigore il Codice degli Appalti del 2023"},{"id":914,"paragraph":"I contratti della PA - Contratti pubblici: procedure di selezione del contraente e fasi della procedura di gara","question":"L'accordo quadro:","correct":"ha lo scopo di stabilire le clausole relative agli appalti da aggiudicare durante un dato periodo","wrong1":"è un particolare tipo di bando","wrong2":"non può più essere utilizzato da quando è entrato in vigore il Codice degli Appalti del 2023","wrong3":"è un requisito indispensabile affinchè sia emato il bando"},{"id":915,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"La simulazione è:","correct":"l'accordo delle parti di porre in essere deliberatamente dichiarazioni difformi dall'interno volere","wrong1":"l'accordo delle parti di porre in essere deliberatamente dichiarazioni identiche all'interno volere","wrong2":"la volontà di una delle parti di porre in essere deliberatamente dichiarazioni difformi dall'interno volere","wrong3":"la volontà delle parte di non adempiere al negozio giuridico stipulato"},{"id":916,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"La simulazione esige:","correct":"un accordo tra due soggetti pertanto anche se si tratta di atti unilaterali questi devono essere indirizzati ad una persona specifica","wrong1":"l'inadempimento di una delle parti","wrong2":"l'inadempimento di entrambe le parti","wrong3":"una dichiarazione scritta a pena di nullità"},{"id":917,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"La simulazione è assoluta quando:","correct":"le parti pongono in essere un negozio ma in realtà non ne vogliono nessuno","wrong1":"pongono in essere un negozio diverso come ad esempio nel caso di stipula di un compravendita ma in realtà le parti vogliono una donazione","wrong2":"pongono in essere un negozio parzialmente diverso","wrong3":"l'atto simulato ne nasconde un altro realmente voluto dalle parti"},{"id":918,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Quando ricorra un atto in frode e quando un atto simulato potrà dirsi:","correct":"solo caso per caso","wrong1":"non vi è alcuna distinzione","wrong2":"si cumulano","wrong3":"appare giuridicamente impossibile"},{"id":919,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Si ha simulazione totale o parziale:","correct":"a seconda che il negozio sia simulato per intero o parzialmente","wrong1":"a seconda che sia oggettiva come simulazione o soggettiva","wrong2":"la prima quando il negozio è parzialmente simulato, la seconda quando è per intero simulato","wrong3":"Non esiste tale distinzione perché sia per la simulazione assoluta che relativa sono ex se simulazioni parziali"},{"id":920,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Si ha interposizione di persone:","correct":"nel caso di simulazione soggettiva","wrong1":"solo nel caso di simulazione parziale","wrong2":"solo nel caso di simulazione totale","wrong3":"riguarda la causa del negozio e che ricorre quando un soggetto appare titolare di un diritto senza esserlo realmente"},{"id":921,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Gli elementi del negozio simulato sono:","correct":"il negozio simulato, il negozio dissimulato, l'accordo simulatorio o la volontà di simulare, una eventuale controdichiarazione","wrong1":"il negozio simulato ed il negozio dissimulato","wrong2":"l'accordo simulatorio o la volontà di simulare","wrong3":"il negozio simulato e una eventuale controdichiarazione"},{"id":922,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Il negozio simulato è:","correct":"quello apparente, cioè quello destinato ad avere effetti nei riguardi dei terzi","wrong1":"quello reale, cioè quello destinato ad avere effetti nei riguardi dei terzi.","wrong2":"che le parti vogliono effettivamente","wrong3":"si indentifica con il negozio dissimulato"},{"id":923,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"La disciplina della simulazione si applica:","correct":"a tutti i contratti, compresi quelli plurilaterali","wrong1":"a tutti i contratti esclusi quelli plurilaterali","wrong2":"solo a contratti plurilaterali","wrong3":"solo ai negozi giuridici recettizi"},{"id":924,"paragraph":"I contratti della PA - Accordo simulatorio e figure affini","question":"Rispetto al negozio simulato il negozio indiretto:","correct":"è un negozio realmente voluto, i cui effetti si producono effettivamente così come risulta dall'accordo delle parti, a differenza di quello simulato in cui gli effetti non sono voluti","wrong1":"è appunta una causa indiretta del contratto principale non voluta","wrong2":"i suoi effetti non si producono così come risulta dall'accordo delle parti","wrong3":"non vi è differenza avendo gli stessi effetti giuridici"},{"id":925,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"La forza di legge del contratto è:","correct":"solo tra le parti","wrong1":"diretta tra le parti, indiretta nei confronti di terzi","wrong2":"diretta tra le parti e per i terzi","wrong3":"indiretta per le parti e per i terzi"},{"id":926,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Nei contratti ad efficacia reale:","correct":"Il diritto reale si tramette in forza del consenso","wrong1":"Il diritto reale è trasmesso solo quando le parti esprimono il consenso per iscritto","wrong2":"Il diritto reale si trasmette in forza della consegna della cosa e del consenso","wrong3":"Il diritto reale si trasmette in forza della consegna della cosa"},{"id":927,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Nei contratti ad effetti obbligatori:","correct":"sorgere un obbligo in capo a un soggetto nell'interesse di un altro","wrong1":"Il diritto reale si tramette in forza del consenso","wrong2":"l'effetto è trasferimento della proprietà di un bene determinato","wrong3":"la costituzione o il trasferimento di un diritto su una cosa"},{"id":928,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Il contratto non può essere sciolto che:","correct":"per mutuo consenso o nei casi previsti dalla legge","wrong1":"per legge","wrong2":"per volontà unilaterale","wrong3":"per comportamento concludente"},{"id":929,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Il mutuo dissenso:","correct":"costituisce un atto di risoluzione convenzionale (o un accordo risolutorio), espressione dell'autonomia negoziale dei privati","wrong1":"può essere solo a titolo gratuito","wrong2":"può essere solo a titolo onerso","wrong3":"è espressione dell'autonomia patrimoniale dei privati"},{"id":930,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"La forma del mutuo dissenso:","correct":"dipende dalla forma che deve rivestire il contratto da sciogliere","wrong1":"è sempre libera","wrong2":"è sempre scritta ad substantiam","wrong3":"può sempre essere \"per comportamento concludente!"},{"id":931,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Il recesso:","correct":"può essere legale o convenzionale","wrong1":"può essere solo legale","wrong2":"può essere solo convenzionale","wrong3":"non è istituto contemplato nel nostro ordinamento giuridico"},{"id":932,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"La caparra penitenziale:","correct":"vale quale « corrispettivo » del diritto di recesso pattuito in favore di una o di entrambe le parti","wrong1":"è espressamente definita e disciplinata nel codice del consumatore","wrong2":"è una forma di risarcimento del danno per la mancata esecuzione del contratto","wrong3":"può essere prevista solo nei negozi a titolo gratuito"},{"id":933,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Nel contratto di appalto:","correct":"può recedere sia l'appaltatore sia il committente","wrong1":"può recedere solo il committente","wrong2":"può recedere solo l'appaltatore","wrong3":"non è contemplato l'istituto del recesso"},{"id":934,"paragraph":"I contratti della PA - Gli effetti del contratto. La forza vincolante del contratto: lo scioglimento convenzionale e il recesso","question":"Nei contratti a distanza:","correct":"Il consumatore può recedere dal contratto senza specificarne il motivo e sostenendo solo i costi per rispedire il bene all'impresa entro 14 giorni, da quando è stato concluso il contratto","wrong1":"Il consumatore può recedere dal contratto solo se ne specifica il motivo entro 7 giorni, da quando è stato concluso il contratto","wrong2":"Il consumatorenon può recedere dal contratto","wrong3":"Il consumatore può recedere dal contratto senza specificarne il motivo e sostenendo solo i costi per rispedire il bene all'impresa entro 10 giorni, da quando è stato concluso il contratto"},{"id":935,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Sono aleatori i contratti in cui:","correct":"la valutazione dei vantaggi e dei sacrifici che ne deriveranno non è possibile, in quanto i vantaggi o i sacrifici per entrambe le parti dipendono dalla sorte","wrong1":"fin dal momento della conclusione, le parti possono valutare i vantaggi e i sacrifici che ne deriveranno","wrong2":"una sola parte assume obbligazioni verso l'altra","wrong3":"non c'è attribuzione patrimoniale"},{"id":936,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Causa del contratto di compravendita è:","correct":"lo scambio della proprietà di un bene con il pagamento di una somma di danaro (prezzo)","wrong1":"la custodia della cosa","wrong2":"lo scambio del godimento di un immobile contro il pagamento di un canone","wrong3":"astratta"},{"id":937,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Nel contratto la causa:","correct":"serve a verificare se esso sia meritevole di tutela per l'ordinamento","wrong1":"è elemento accidentale","wrong2":"è sempre astratta","wrong3":"non può mai essere illecita"},{"id":938,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Nel codice attualmente vigente, la causa:","correct":"designa oggettivamente la funzione che contrassegna quel singolo contratto nel contesto più generale delle operazioni contrattuali","wrong1":"è espressamente definita","wrong2":"è riferita alle singole obbligazioni che da esso scaturiscono","wrong3":"può anche mancare senza che ciò incida sul profilo della validità"},{"id":939,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Secondo la teoria oggettiva della causa, questa è:","correct":"la funzione economico-sociale del contratto","wrong1":"l'interesse concreo che le parti perseguono nella conclusione del contratto","wrong2":"lo scopo pratico del contratto","wrong3":"la funzione economico individuale del contratto"},{"id":940,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"La causa in concreto:","correct":"è espressione della teoria soggettiva","wrong1":"identifica la causa con la funzione economico-sociale del contratto","wrong2":"è espressione della teoria oggettiva","wrong3":"è riferita alle singole obbligazioni che scaturiscono dal contratto"},{"id":941,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Con lo stabilire che ogni contratto abbia una \"causa\" :","correct":"si intende esigere che le parti, nella conclusione del contratto, perseguono un interesse meritevole di tutela","wrong1":"si intende rafforzare il principio dell'efficacia del puro consenso","wrong2":"si intende predisporre contratti tipici","wrong3":"si intende rafforzare il controllo reciproco dei contraenti a tutela dei loro esclusivi interessi"},{"id":942,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"I motivi:","correct":"in quanto rappresentazioni soggettive del contraente, sono destinati ad essere irrilevanti","wrong1":"non differiscono dalla causa","wrong2":"sono rilevanti solo se contrari al buon costume","wrong3":"sono sempre rilevanti"},{"id":943,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"Possono le parti realizzare attribuzioni che in qualche modo si sottraggono al principio causale?:","correct":"si, in ossequio alla esigenza di economia degli scambi","wrong1":"mai le prestazioni in un contratto possono essere collegate ad uno \"scopo\" ad esse esterno","wrong2":"solo con riferimeto ai contratti tipici","wrong3":"solo con riferimeto ai contratti atipicii"},{"id":944,"paragraph":"I contratti della PA - Gli elementi essenziali del contratto: la causa","question":"La causa è illecita:","correct":"quando è contraria a norme imperative, all'ordine pubblico al buon costume","wrong1":"quando è contraria al buon senso","wrong2":"quando è contrariaa norme derogabili","wrong3":"quando è illecito il motivo"},{"id":945,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"I criteri di aggiudicazione degli appalti:","correct":"sono i metodi che vengono utilizzati dalla stazione appaltante per individuare l'offerta migliore","wrong1":"sono i metodi che vengono utilizzati dalla stazione appaltante per individuare il prezzo più basso","wrong2":"sono i metodi che vengono utilizzati dalla stazione appaltante per individuare la procedura da seguire per la scelta del contraente","wrong3":"sono gli strumenti per la valutazione della serietà e attendibilità delle offerte"},{"id":946,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"All'interno dei criteri di aggiudicazione degli appalti, si distingue tra:","correct":"criterio del prezzo più basso e criterio dell'offerta economicamente più vantaggiosa","wrong1":"procedure aperte e procedure ristrette","wrong2":"criterio del prezzo più alto e il criterio del prezzo più basso","wrong3":"elementi che attengono alla convenienza ecomica e elementi che attengono alla sostenibilità dell'offerta"},{"id":947,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"Con il criterio dell'offerta economicamente più vantaggiosa si mira a ottenere:","correct":"l'offerta migliore individuata sulla base del miglior rapporto qualità/prezzo","wrong1":"il prezzo più basso","wrong2":"l'offerta migliore all'esito di un confronto fra due sole offerte","wrong3":"la massima concorrenza fra gli operatori economici"},{"id":948,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"Il criterio del prezzo più basso:","correct":"valorizza solo la componente economica dell'offerta","wrong1":"valorizza la componente tecnico - qualitativa dell'offerta","wrong2":"valorizza sia la componente tecnico - qualitativa dell'offerta, sia la componente economica","wrong3":"può essere utilizzato per ogni tipologia di appalto"},{"id":949,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"Il criterio del prezzo più basso:","correct":"si applica nelle ipotesi tassativamente previste dalla legge, essendovi una preferenza ordinamentale per il criterio dell'offerta economicamente più vantaggiosa","wrong1":"si applica in via preferenziale agli appalti ad alta intensità di manodopera","wrong2":"si applica solo se è andata deserta una procedura basata sul criterio dell'offerta economicamente più vantaggiosa","wrong3":"si applica agli appalti di lavori di importo superiore alla soglia comunitaria"},{"id":950,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"L'offerta anomala:","correct":"è un'offerta che, pur apparentemente vantaggiosa per l'amministrazione, rischia di condurre ad una esecuzione non idonea del contratto","wrong1":"è un'offerta di gran lunga migliore alle altre pervenute che obbliga la stazione appaltante ad aggiudicare l'appalto all'operatore economico che l'ha presentata","wrong2":"è un'offerta inesistente","wrong3":"è un'offerta rischiosa perché proveniente da soggetti giuridici interessati dall'adozione di misure interdittive"},{"id":951,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"La verifica della congruità di un'offerta:","correct":"ha natura globale e sintetica","wrong1":"ha per oggetto la ricerca di singole inesattezze dell'offerta economica","wrong2":"va valutata con riferimento alle singole voci di prezzo eventualmente ritenute incongrue","wrong3":"viene effettuata senza alcun esercizio di discrezionalità, ma sulla base di criteri automatici"},{"id":952,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"L'art 54 del Codice appalti consente l'esclusione automatica delle offerte anomale nell'aggiudicazione con il criterio del prezzo più basso dei contratti \"sottosoglia\", qualora:","correct":"l'esclusione sia stata prevista negli atti di gara e i contratti riguardino appalti di lavori o servizi ma non di forniture, e purché il contratto non presenti un interesse transfrontaliero certo e siano state ammesse almeno cinque offerte","wrong1":"i contratti presentano un interesse transfrontaliero certo","wrong2":"vi sono almeno cinque offerte ammesse","wrong3":"si tratti di procedure informatizzate per l'affidamento di appalti di forniture di valore inferiore a duecentomila euro"},{"id":953,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"L'art. 110 del Codice Appalti:","correct":"rimette alla discrezionalità della stazione appaltante l'individuazione delle offerte che appaiono anomale e che, dunque, andranno sottoposte a verifica, con conseguente adozione di atto motivato","wrong1":"è rubricato \"Esclusione automatica delle offerte anomale\"","wrong2":"prevede che in caso di accertata anomalia dell'offerta da parte della stazione appaltante si può procedere alla esclusione dell'operatore economico senza contradditorio procedimentale","wrong3":"è in parziale contrasto con i principi del risultato, della fiducia e di buona fede e affidamento"},{"id":954,"paragraph":"I contratti della PA - Criteri di aggiudicazione e verifica dell'offerta anomala","question":"Nel contraddittorio procedimentale che precede l'eventuale esclusione per anomalia dell'offerta:","correct":"La stazione appaltante deve richiedere per iscritto al candidato la presentazione di spiegazioni, entro un termine non superiore a 15 giorni salvo casi specifici individuati nel concreto","wrong1":"la stazione appaltante deve richiedere per iscritto al candidato la presentazione di spiegazioni, entro un termine non superiore a 60 giorni salvo casi specifici individuati nel concreto","wrong2":"sono ammesse giustificazioni in relazione a trattamenti salariali minimi inderogabili stabiliti dalla legge o da fonti autorizzate dalla legge","wrong3":"sono ammesse giustificazioni in relazione agli oneri di sicurezza di cui alla normativa vigente"},{"id":955,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"Il giudice amministrativo ha giurisdizione:","correct":"sulle controversie che attengono alla fase pubblicistica della procedura di evidenza pubblica","wrong1":"sulle controversie che attegono alla fase esecutiva del contratto","wrong2":"sulle controversie concernenti la fase pubblicistica ed esecutiva dell'appalto","wrong3":"sulle controversie concernenti la fase pubblicistica della procedura di gara, con esclusione di quelle aventi ad oggetto i provvedimenti di esclusione dei concorrenti"},{"id":956,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"L'inefficacia del contratto stipulato sulla base di un'aggiudicazione illegittima:","correct":"è una eventualità rimessa all'apprezzamento del giudice amministrativo","wrong1":"è una conseguenza automatica, di cui il giudice ordinario deve prendere atto","wrong2":"non può mai verificarsi, residuando in capo al concorrente che ha ottenuto l'annullamento dell'aggiudicazione il solo rimedio risarcitorio","wrong3":"è una evenienza limitata ai casi più gravi di omissione della procedura di evidenza pubblica"},{"id":957,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"Le sanzioni alternative:","correct":"trovano applicazione quando non venga dichiarata l'inefficacia del contratto in presenza di un vizio che, ai sensi dell'art. 121, la imporrebbe","wrong1":"trovano applicazione quando il contratto viene risolto per inadempimento del contraente","wrong2":"quando il contraente della p.a. rifiuta la risoluzione del contratto","wrong3":"quando, in mancanza della domanda di subentro, il giudice non può dichiarare l'inefficacia del contratto"},{"id":958,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"L'accelerazione del rito speciale in materia di appalti e concessioni:","correct":"si ottiene mediante la dimidiazione di tutti i termini, compresso quello per la proposizione del ricorso","wrong1":"si ottiene mediante la dimidiazione di tutti i termini, eccezion fatta per il termine di impugnazione dell'aggiudicazione","wrong2":"si ottiene mediante la dimidiazione dei termini per la fissazione delle udienze e per il deposito delle sentenze","wrong3":"si ottiene mediante l'attrubuzione delle controversie ad un giudice monocratico, in luogo di quello collegiale"},{"id":959,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"L'udienza per la decisione del ricorso in materia di appalti deve tenersi:","correct":"entro 45 giorni dalla scadenza del termine per la costituzione in giudizio delle parti diverse dal ricorrente","wrong1":"entro 45 giorni dalla scadenza del termine per la costituzione in giudizio del ricorrente","wrong2":"entro 30 giorni dalla decisione dell'istanza di misure cautelari","wrong3":"entro 60 giorni dalla notificazione del ricorso"},{"id":960,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"La procedura di accordo bonario:","correct":"si svolge in contraddittorio fra il RUP e il soggetto che ha iscritto le riserve","wrong1":"culmina in una proposta di accordo, che ha valore di lodo arbitrale","wrong2":"implica la rinuncia alla tutela giurisdizionale","wrong3":"non è applicabile agli appalti di lavori"},{"id":961,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"In caso di accordo bonario:","correct":"La proposta di accordo è formulata da un esperto nominato d'intesa fra le parti o direttamente dal RUP","wrong1":"la proposta di accordo è sempre rimessa ad un arbitro, nominato d'intesa fra le parti","wrong2":"la proposta di accordo è sempre formulata dal RUP, previo parere del direttore del lavori","wrong3":"La proposta di accordo è formulata congiuntamente dal RUP e dal soggetto che ha iscritto le riserve"},{"id":962,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"L'impresa che rifiuta la proposta di accordo bonario:","correct":"può adire il giudice ordinario o, se è previsto dal bando, gli arbitri","wrong1":"deve proporre ricorso entro 30 giorni dinanzi al giudice amministrativo","wrong2":"può instaurare un contenzioso fondato sull'art. 2043 c.c.","wrong3":"deve chiedere un parere all'Anac"},{"id":963,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"La transazione:","correct":"è utilizzabile solo per le controversie aventi ad oggetto diritti soggettivi derivanti dall'esecuzione di contratti di lavori, servizi e forniture","wrong1":"è uno strumento di risoluzione delle controversie aventi ad oggetto interessi legittimi e diritti soggettivi in materia di appalti di lavori, servizi e forniture","wrong2":"è un rimedio ordinario e preferibile agli altri rimedi di natura stragiudiziale","wrong3":"può essere utilizzata solo se è già stata instaurata una lite avente ad oggetto le spettanze dell'impresa per le prestazioni eseguite"},{"id":964,"paragraph":"I contratti della PA - La tutela in materia di contratti pubblici","question":"I pareri di c.d. precontenzioso Anac:","correct":"possono essere impugnati dall'operatore economico che li ha richiesti solo per violazione delle regole di diritto relative al merito della controversia","wrong1":"sono sempre vincolanti","wrong2":"precludono la proposizione di un ricorso giurisdizionale avente ad oggetto la medesima questione","wrong3":"devono essere resi entro 60 giorni dalla richiesta"},{"id":965,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Le funzioni amministrative relative alla materia “urbanistica” concernono:","correct":"La disciplina dell'uso del territorio comprensiva di tutti gli aspetti conoscitivi, normativi e gestionali riguardanti le operazioni di salvaguardia e di trasformazione del suolo nonché la protezione dell'ambiente","wrong1":"Esclusivamente la disciplina dell'uso del territorio","wrong2":"La disciplina dell'uso del territorio comprensiva di tutti gli aspetti conoscitivi, normativi e gestionali riguardanti le operazioni di sola salvaguardia del territorio","wrong3":"La disciplina dell'uso del territorio comprensiva dei soli aspetti conoscitivi riguardanti le operazioni di salvaguardia e di trasformazione del suolo nonché la protezione dell'ambiente"},{"id":966,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"L'edilizia:","correct":"Si occupa delle trasformazioni permanenti del territorio e in particolare delle condizioni in base alle quali le trasformazioni ammesse dalla normativa e dalla pianificazione urbanistica possano legittimamente concretizzarsi","wrong1":"Si occupa delle trasformazioni non irreversibili del territorio","wrong2":"Si occupa delle sole trasformazioni permanenti del territorio a fini ambientali","wrong3":"Si occupa di esclusivamente di tutti gli aspetti paesaggistico-ambientali connessi all'uso del territorio"},{"id":967,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Il base al divieto di parcellazione:","correct":"Il territorio non può essere frazionato in maniera irragionevole in micro-aree con destinazioni differenti","wrong1":"Il territorio può essere liberamente frazionato, salvo parere contrario dell'ANAC","wrong2":"Il territorio può essere liberamente frazionato, salvo parere contrario della Corte dei Conti","wrong3":"Il territorio può essere liberamente frazionato, salvo parere contrario degli uffici della ragioneria comunale"},{"id":968,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Ai sensi delle leggi in materia:","correct":"Ai Comuni spetta l'adozione dei piani regolatori, dei piani particolareggiati di esecuzione, dei regolamenti edilizi e dei piani di lottizzazione","wrong1":"Ai Comuni spetta l'adozione dei soli piani regolatori","wrong2":"Ai Comuni spetta l'adozione dei soli dei regolamenti edilizi","wrong3":"Ai Comuni spetta l'adozione dei piani regolatori e dei piani particolareggiati di esecuzione ma non anche dei regolamenti edilizi e dei piani di lottizzazione"},{"id":969,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Nell'ambito del Comune, l'adozione del piano regolatore è rimessa alla competenza:","correct":"Del Consiglio comunale","wrong1":"Dei dirigenti all'uopo preposti","wrong2":"Della Giunta comunale","wrong3":"Della Giunta Comunale previo parere favorevole e vincolante della ragioneria comunale"},{"id":970,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Il piano regolatore ha natura:","correct":"Mista di atto normativo e amministrativo","wrong1":"Di solo atto normativo","wrong2":"Di solo atto amministrativo","wrong3":"Di provvedimento amministrativo"},{"id":971,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Le N.T.A. (norme tecniche di attuazione) individuano:","correct":"I c.d. standard plano-volumetrici e le tipologie costruttive","wrong1":"I soli standard plano-volumetrici e non anche le tipologie costruttive","wrong2":"Le sole tipologie costruttive e non anche i c.d. standard plano-volumetrici","wrong3":"La suddivisione in zone del territorio"},{"id":972,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"A seguito della adozione del piano regolatore da parte del Consiglio comunale:","correct":"Il piano medesimo non è immediatamente efficace necessitando dell'approvazione regionale","wrong1":"Il piano medesimo è immediatamente efficace in tutte le sue prescrizioni a condizione che ottenga il visto degli uffici tecnici regionali","wrong2":"Il piano medesimo è immediatamente efficace in tutte le sue prescrizioni a condizione che ottenga il visto della ragioneria comunale","wrong3":"Il piano medesimo è immediatamente efficace in tutte le sue prescrizioni"},{"id":973,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Le misure di salvaguardia:","correct":"Comportano il divieto di rilasciare titoli edilizi che contrastino con i contenuti del piano adottato (ma non ancora approvato)","wrong1":"Sono prescrizioni di legge in materia ambietale che prevalgono sui piani regolatori contrastanti","wrong2":"Sono prescrizioni di legge in materia ambietale e paesaggistica che prevalgono sui piani regolatori contrastanti","wrong3":"Sono prescrizioni di legge in materia paesaggistica che prevalgono sui piani regolatori contrastanti"},{"id":974,"paragraph":"I contratti della PA - Il governo del territorio. Urbanistica","question":"Il piano di lottizzazione:","correct":"È un piano concertato che richiede il consenso dei soggetti privati interessati e si risolve anche nella possibilità di agevolare un ordinato coordinamento tra zone già urbanizzate e nuovi insediamenti. Esso culmina con la sottoscrizione di una convenzione, mediante la quale si definiscono tempi e modalità di realizzazione da parte dei privati della lottizzazione, ivi incluse le relative urbanizzazioni","wrong1":"E' il piano mediante il quale la zonizzazione del territorio è approvata previo accordo con la cittadinanza, fermo comunque il visto favorevole della ragioneria comunale e degli uffici tecnici competenti","wrong2":"E' il piano mediante il quale la zonizzazione del territorio è approvata previo accordo con la cittadinanza","wrong3":"E' un piano unilateralmente predisposto dal comune, che si risolve nell'obbligo per i privati di realizzare nuovi insediamenti. Esso si sostanzia nella sottoscrizione di un atto d'obbligo unilaterale, mediante il quale si definiscono tempi e modalità di realizzazione da parte dei privati della lottizzazione, ivi incluse le relative urbanizzazioni"},{"id":975,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Per privatizzazione formale si intende:","correct":"L'operazione di trasformazione di soggetti originariamente organizzati in forma pubblicistica in operatori formalmente di diritto privato","wrong1":"L'operazione di cessione a privati, senza gara, di quote societarie detenute da pubbliche amministrazioni","wrong2":"L'operazione di trasformazione di soggetti originariamente organizzati in forma pubblicistica in operatori sostanzialmente di diritto privato","wrong3":"L'operazione di cessione a privati, con gara, di quote societarie detenute da pubbliche amministrazioni"},{"id":976,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Per privatizzazione sostanziale si intende:","correct":"Il fenomeno della cessione a privati di partecipazioni pubbliche e quello dell'apertura alla concorrenza di attività tradizionalmente oggetto di riserva monopolistica in favore dei pubblici poteri","wrong1":"Il solo fenomeno dell'apertura alla concorrenza di attività tradizionalmente oggetto di riserva monopolistica in favore dei pubblici poteri","wrong2":"Il fenomeno della cessione a privati di partecipazioni pubbliche minoritarie","wrong3":"Il fenomeno della cessione a privati di partecipazioni pubbliche maggioritarie"},{"id":977,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Per liberalizzazione amministrativa:","correct":"Si intendono i processi legislativi volti alla totale o parziale eliminazione di regimi amministrativi autorizzatori per lo svolgimento di attività private","wrong1":"Si intendono i processi legislativi volti alla totale o parziale eliminazione di regimi amministrativi autorizzatori per lo svolgimento di attività pubbliche","wrong2":"Si intendono i processi legislativi volti alla sostituzione di privati alle pubbliche amministrazioni nell'esercizio di funzioni pubbliche, in coerenza con il principio di sussidiarietà","wrong3":"Si intendono i processi legislativi volti all'affiancamento dei privati alle pubbliche amministrazioni nell'esercizio di poteri autoritativi"},{"id":978,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Sono rifiuti urbani:","correct":"I rifiuti domestici, anche ingombranti, provenienti da locali e luoghi adibiti ad uso di civile abitazione","wrong1":"I rifiuti da lavorazioni industriali","wrong2":"i rifiuti domestici, esclusi quelli ingombranti, provenienti da locali e luoghi adibiti ad uso di civile abitazione","wrong3":"I rifiuti derivanti dalle attività di demolizione, costruzione, nonché i rifiuti che derivano dalle attività di scavo"},{"id":979,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Sono rifiuti urbani:","correct":"I rifiuti di qualunque natura o provenienza, giacenti sulle strade ed aree pubbliche","wrong1":"I rifiuti da lavorazioni artigianali","wrong2":"I rifiuti da attività commerciali","wrong3":"I rifiuti da attività sanitarie"},{"id":980,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Sono rifiuti urbani:","correct":"I rifiuti provenienti da esumazioni ed estumulazioni, nonché gli altri rifiuti provenienti da attività cimiteriale","wrong1":"I rifiuti provenienti da estumulazioni ma non da esumazioni, nonché gli altri rifiuti provenienti da attività cimiteriale","wrong2":"I rifiuti provenienti da esumazioni ma non da estumulazioni, nonché gli altri rifiuti provenienti da attività cimiteriale","wrong3":"i rifiuti da attività di servizio"},{"id":981,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Il servizio di gestione integrata da rifiuti:","correct":"È affidato ad un gestore unico, previa procedura di gara","wrong1":"E' affidato ad un gestore unico, senza procedura di gara","wrong2":"E' affidato ad una pluralità di gestori, onde massimizzare il pubblico interesse. I gestori sono selezionati con gara","wrong3":"E' affidato ad una pluralità di gestori, onde massimizzare il pubblico interesse. I gestori sono selezionati senza gara, trattandosi di contratti intuitus personae"},{"id":982,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Le imprese produttrici di olii usati sono obbligate a:","correct":"Cedere e trasferire tutti gli oli usati detenuti al consorzio obbligatorio degli oli usati direttamente ovvero ad imprese autorizzate alla raccolta e/o alla eliminazione, comunicando al cessionario tutti i dati relativi all'origine ed ai pregressi utilizzi degli oli usati","wrong1":"Cedere e trasferire tutti gli oli usati detenuti al consorzio obbligatorio degli oli usati direttamente ovvero ad imprese autorizzate alla raccolta e/o alla eliminazione, comunicando al cessionario tutti i dati relativi all'origine ed ai pregressi utilizzi degli oli usati","wrong2":"Cedere e trasferire tutti gli oli usati detenuti unicamente ad imprese autorizzate alla raccolta e/o alla eliminazione, comunicando al cessionario tutti i dati relativi all'origine ed ai pregressi utilizzi degli oli usati","wrong3":"Cedere e trasferire tutti gli oli usati detenuti al solo consorzio obbligatorio degli oli usati"},{"id":983,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Chiunque esercita l’attività di rivendita al dettaglio di oli è obbligato a:","correct":"Mettere a disposizione della propria clientela ed esercire un impianto attrezzato per lo stoccaggio dell'olio usato","wrong1":"Informare la clientela circa la sussistenza in capo a ciascun acquirente di olii dell'obbligo di smaltore i predetti olii contattando il relativo consorzio obbligatorio","wrong2":"Informare la Procura della Repubblica di ogni inadempienza da parte di acquirenti di olii rispetto all'obbligo su di essi gravante di smaltire i predetti olii","wrong3":"Informare l'Agenzia Regionale per la Protezione Ambientale di ogni inadempienza da parte di acquirenti di olii rispetto all'obbligo su di essi gravante di smaltire i predetti olii"},{"id":984,"paragraph":"I contratti della PA - Servizi pubblici. La gestione dei rifiuti","question":"Il consorzio obbligatorio per la gestione degli olii usati:","correct":"Non ha fini di lucro ed è retto da uno statuto approvato con decreto del Ministro dell'ambiente, di concerto con il Ministro dell'industria del commercio e dell'artigianato","wrong1":"Ha fini di lucro ed è retto da uno statuto approvato con decreto del Ministro dell'ambiente, di concerto con il Ministro dell'industria del commercio e dell'artigianato","wrong2":"Ha fini di lucro ed è retto da uno statuto approvato dall'ANAC","wrong3":"Non ha fini di lucro ed è retto da uno statuto approvato dall'ANAC"},{"id":985,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"La tutela dell'ambiente:","correct":"Ha fondamento costituzionale espresso nell'art. 117","wrong1":"Non ha fondamento costituzionale espresso","wrong2":"Ha esclusivamente fondamento costituzionale implicito ed è desunta dalle disposizioni in materia di paesaggio","wrong3":"Ha esclusivamente fondamento costituzionale implicito ed è desunta dalle disposizioni in materia di diritto alla salute"},{"id":986,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"Il principio di prevenzione:","correct":"È volto ad evitare che danni all'ambiente si verifichino","wrong1":"Impone di astenersi da condotte potenzialmente rischiose, senza che sia certa la loro pericolosità","wrong2":"Coincide con il principio 'chi inquina paga'","wrong3":"E' volto ad evitare che un danno prodottosi si diffonda incontrollabilmente"},{"id":987,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"Il principio di precauzione può essere invocato quando:","correct":"Un processo può avere effetti potenzialmente pericolosi, individuati tramite una valutazione scientifica e obiettiva, se questa valutazione non consente di determinare il rischio con sufficiente certezza","wrong1":"Un processo può avere effetti potenzialmente pericolosi, individuati tramite una valutazione scientifica e obiettiva, se questa valutazione consente di determinare il rischio con un elevatissimo grado di certezza","wrong2":"Un processo può avere effetti certamente pericolosi, individuati tramite una valutazione scientifica e obiettiva, se questa valutazione consente di determinare il rischio con sufficiente certezza","wrong3":"Un processo può avere effetti potenzialmente pericolosi, individuati tramite una valutazione opinabile e di sola plausibilità, se questa valutazione consente di determinare il rischio con sufficiente certezza"},{"id":988,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"Allo Stato, attraverso il Ministero dell'ambiente e della tutela del territorio e del mare, spetta:","correct":"L'individuazione di prescrizioni tecniche uniformi su tutto il territorio nazionale, quali metodi di campionamento, valori limite di emissione o criteri per la raccolta di dati ambientali","wrong1":"Il compito di supportare gli enti locali nell'individuazione di prescrizioni tecniche uniformi su tutto il territorio nazionale, quali metodi di campionamento, valori limite di emissione o criteri per la raccolta di dati ambientali","wrong2":"L'individuazione di prescrizioni tecniche uniformi su tutto il territorio nazionale, quali metodi di campionamento, valori limite di emissione o criteri per la raccolta di dati ambientali, sentite le Agenzie di Protezione Ambientale delle singole Regioni che emettono parere vincolante","wrong3":"L'individuazione di prescrizioni tecniche uniformi su tutto il territorio nazionale, quali metodi di campionamento, valori limite di emissione o criteri per la raccolta di dati ambientali, sentite almeno due Università (una pubblica, l'altra privata) che emettono parere vincolante"},{"id":989,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"Le autorizzazioni ambientali:","correct":"Debbono essere espresse ed hanno durata limitata nel tempo","wrong1":"Possono, su iniziativa delle singole Regioni, essere sostituite da SCIA e non hanno durata limitata nel tempo","wrong2":"Si intendono rilasciate per silenzio-assenso e hanno durata limitata nel tempo","wrong3":"Possono, su iniziativa delle singole Regioni, essere sostituite da SCIA e hanno durata limitata nel tempo"},{"id":990,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"L'accesso alle informazioni ambientali:","correct":"È garantito dalla legge a chiunque ne faccia richiesta, senza che questi debba dichiarare il proprio interesse","wrong1":"E' garantito dalla legge alle sole associazioni ambientaliste","wrong2":"E' garantito dalla legge a chiunque ne faccia richiesta, previa dimostrazione della titolarità di un interesse attuale e concreto","wrong3":"E' garantito dalla legge a chiunque ne faccia richiesta, previo parere favorevole del Ministero competente"},{"id":991,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"La Valutazione d'Impatto Ambientale:","correct":"È la procedura tecnico-amministrativa di verifica della compatibilità ambientale di un progetto, finalizzata all'individuazione, descrizione e quantificazione degli effetti che un determinato progetto, opera o azione, potrebbe avere sull'ambiente","wrong1":"E' la procedura tecnico-amministrativa di verifica della sola compatibilità paesaggistica di un progetto, finalizzata all'individuazione, descrizione e quantificazione degli effetti che un determinato progetto, opera o azione, potrebbe avere sul paesaggio","wrong2":"E' la procedura tecnico-amministrativa di verifica della compatibilità di un progetto con la salubrità pubblica","wrong3":"E' la procedura tecnico-amministrativa di verifica della compatibilità di un progetto con la salubrità pubblica ed il paesaggio"},{"id":992,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"L'AIA ha per oggetto:","correct":"La prevenzione e la riduzione dell'inquinamento proveniente dalle attività inquinanti e prevede misure intese a evitare, ove possibile, o a ridurre le emissioni nell'aria, nell'acqua e nel suolo, comprese le misure relative ai rifiuti, per conseguire un livello elevato di protezione dell'ambiente","wrong1":"La prevenzione e la riduzione dell'inquinamento proveniente dalle attività inquinanti e prevede misure intese a evitare, ove possibile, o a ridurre le emissioni nel solo suolo, comprese le misure relative ai rifiuti, per conseguire un livello elevato di protezione dell'ambiente","wrong2":"La prevenzione dei danni al paesaggio determinate da attività costruttive di particolare rilievo","wrong3":"La prevenzione e la riduzione dell'inquinamento proveniente dalle attività inquinanti e prevede misure intese a evitare, ove possibile, o a ridurre le emissioni nella sola aria"},{"id":993,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"La Valutazione di Incidenza:","correct":"È il procedimento di carattere preventivo al quale è necessario sottoporre qualsiasi piano o progetto che possa avere incidenze significative su un sito della rete Natura 2000","wrong1":"E' il procedimento di carattere successivo al quale è necessario sottoporre qualsiasi piano o progetto che possa avere incidenze significative su un sito della rete Natura 2000","wrong2":"E' il procedimento di carattere successivo al quale è necessario sottoporre qualsiasi piano o progetto che possa avere incidenze significative sulle sole aree marine protette","wrong3":"E' il procedimento di carattere preventivo al quale è necessario sottoporre qualsiasi piano o progetto che possa avere incidenze significative su parchi naturali transnazionali"},{"id":994,"paragraph":"I contratti della PA - Principi e legislazione ambientale","question":"È danno ambientale:","correct":"Qualsiasi deterioramento significativo e misurabile, diretto o indiretto, di una risorsa naturale o dell'utilità assicurata da quest'ultima","wrong1":"Qualsiasi deterioramento anche non misurabile, diretto o indiretto, di una risorsa naturale o dell'utilità assicurata da quest'ultima","wrong2":"Qualsiasi deterioramento anche non misurabile e solo diretto di una risorsa naturale o dell'utilità assicurata da quest'ultima","wrong3":"Qualsiasi cambiamento o modifica anche non misurabile e solo diretto di una risorsa naturale o dell'utilità assicurata da quest'ultima"},{"id":995,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"Ai sensi del Testo Unico, la gestione di partecipazioni societarie da parte di pubbliche amministrazioni avviene nel rispetto:","correct":"Dei principi di (i) efficienza; (ii) tutela e promozione della concorrenza e del mercato nonché (iii) razionalizzazione e riduzione della spesa pubblica","wrong1":"Dei principi di (i) efficiente gestione delle partecipazioni pubbliche e (ii) tutela e promozione della concorrenza e del mercato","wrong2":"Dei principi di (i) tutela e promozione della concorrenza e del mercato nonché (ii) razionalizzazione e riduzione della spesa pubblica","wrong3":"Dei principi di (i) tutela dei monopoli pubblici e di (ii) razionalizzazione e riduzione della spesa pubblica"},{"id":996,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"Laddove non derogato espressamente dal Testo Unico:","correct":"Alle società a partecipazione pubblica si applicano le norme sulle società contenute nel codice civile e le norme generali di diritto privato","wrong1":"Alle società a partecipazione pubblica si applicano le norme sulle aziende speciali del testo unico degli enti locali","wrong2":"Alle società a partecipazione pubblica si applicano le norme sulle società contenute nel solo codice civile","wrong3":"Alle società a partecipazione pubblica si applicano le norme sulle società contenute nel Codice dei Contratti Pubblici"},{"id":997,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"L'art. 4, co. 1 del Testo Unico stabilisce che:","correct":"Le amministrazioni pubbliche non possono, direttamente o indirettamente, costituire società aventi per oggetto attività di produzione di beni e servizi non strettamente necessarie per il perseguimento delle proprie finalità istituzionali, né acquisire o mantenere partecipazioni, anche di minoranza, in tali società","wrong1":"Le amministrazioni pubbliche possono, direttamente o indirettamente, costituire società aventi per oggetto attività di produzione di beni e servizi non strettamente necessarie per il perseguimento delle proprie finalità istituzionali, e acquisire o mantenere partecipazioni, anche di minoranza, in tali società","wrong2":"Le amministrazioni pubbliche non possono, direttamente o indirettamente, costituire società aventi per oggetto attività di produzione di beni e servizi non strettamente necessarie per il perseguimento delle proprie finalità istituzionali ma possono mantenere le partecipazioni, anche di minoranza, già detenute in tali società","wrong3":"Le amministrazioni pubbliche non possono giammai costituire società o acquisire e mantenere quote societarie sia direttamente che indirettamente"},{"id":998,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"L'art. 4, co. 2 del Testo Unico stabilisce che le pubbliche amministrazioni possono costituire società e acquisire o mantenere partecipazioni in società per lo svolgimento:","correct":"tra l'altro anche dell'attività di produzione di un servizio di interesse generale, ivi inclusa la realizzazione e la gestione delle reti e degli impianti funzionali ai servizi medesimi","wrong1":"Di qualunque attività economica","wrong2":"esclusivamente dell'attività di produzione di un servizio di interesse generale, ivi inclusa la realizzazione e la gestione delle reti e degli impianti funzionali ai servizi medesimi","wrong3":"esclusivamente dell'attività di produzione di servizio assistenziali ad anziani e bambini"},{"id":999,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"L'art. 4, co. 2 del Testo Unico stabilisce che le pubbliche amministrazioni possono costituire società e acquisire o mantenere partecipazioni in società per lo svolgimento:","correct":"Tra l'altro, di attività di autoproduzione di beni o servizi strumentali all'ente o agli enti pubblici partecipanti","wrong1":"Di qualunque attività economica","wrong2":"Esclusivamente dell'attività di produzione di un servizio di interesse generale, ivi inclusa la realizzazione e la gestione delle reti e degli impianti funzionali ai servizi medesimi","wrong3":"Esclusivamente dell'attività di produzione di servizi assistenziali ad anziani e bambini"},{"id":1000,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"Il co. 7 dell’art. 4 del Testo Unico ammette che pubbliche amministrazioni detengano:","correct":"Partecipazioni in società aventi per oggetto sociale prevalente la gestione di spazi fieristici e l'organizzazione di eventi fieristici","wrong1":"Partecipazioni in società aventi per oggetto sociale prevalente la gestione di sagre tipiche territoriali","wrong2":"Partecipazioni in società aventi per oggetto sociale anche non prevalente la gestione di spazi fieristici e l'organizzazione di eventi fieristici","wrong3":"Partecipazioni in società aventi per oggetto sociale esclusivo la gestione di stadi e palazzetti dello sport"},{"id":1001,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"Le pubbliche amministrazioni possono comunque:","correct":"Mantenere le partecipazioni in società quotate, detenute al 31 dicembre 2015","wrong1":"Mantenere le partecipazioni in società quotate, detenute al 31 dicembre 2002","wrong2":"Mantenere le partecipazioni in società quotate, detenute al 31 dicembre 2003","wrong3":"Mantenere le partecipazioni in società quotate, detenute al 31 dicembre 2004"},{"id":1002,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"L'atto deliberativo di costituzione di una società a partecipazione pubblica:","correct":"Deve essere analiticamente motivato con riferimento alla coerenza della scelta rispetto al perseguimento delle finalità istituzionali del socio pubblico, evidenziando, altresì, le ragioni e le finalità che giustificano tale scelta, anche sul piano della convenienza economica e della sostenibilità finanziaria","wrong1":"E' libero e non deve essere motivato","wrong2":"Deve essere sommariamente motivato con riferimento alla coerenza della scelta rispetto al perseguimento delle finalità istituzionali del socio pubblico, evidenziando, altresì, le ragioni e le finalità che giustificano tale scelta, anche sul piano della convenienza economica e della sostenibilità finanziaria","wrong3":"Necessita del parere prevenivo favorevole dell'ANAC e della Corte dei Conti"},{"id":1003,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"L'onere motivazionale da rispettare in sede di costituzione di una società pubblica:","correct":"Richiede un’istruttoria che verifichi la convenienza dell'iniziativa rispetto ad utilizzi alternativi del pubblico denaro, quali ad esempio la gestione diretta dei servizi affidati alla società pubblica da parte della stessa amministrazione oppure l’affidamento ad operatori terzi di quei servizi","wrong1":"Non richiede alcuna istruttoria","wrong2":"Richiede un'istruttoria attenta alle esigenze delle comunità di riferimento","wrong3":"Deve essere sommariamente motivato"},{"id":1004,"paragraph":"I contratti della PA - Le società pubbliche. Partecipazioni societarie e pubblico interesse","question":"La dottrina che ha indagato il significato del concetto di vincolo di scopo ha evidenziato che:","correct":"Lo strumento societario deve risultare indispensabile, nel senso che lo stesso deve risultare, alla luce di un’indagine basata sui fatti e motivata dell’ente pubblico, lo strumento più idoneo a consentire il perseguimento degli obiettivi di pubblico interesse","wrong1":"Il vincolo di scopo non è pregnante e costituisce espressione di un'indicazione solo tendenziale","wrong2":"Il vincolo di scopo non richiede alcuna istruttoria, né obbligo di motivazione analitica","wrong3":"Lo strumento societario deve risultare tra quelli genericamente plausibili per il perseguimento degli obiettivi di pubblico interesse"},{"id":1005,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"La costituzione di società (o l’acquisto di partecipazioni) obbliga gli enti locali:","correct":"A sottoporre lo schema di atto deliberativo a forme di consultazione pubblica","wrong1":"A sottoporre lo schema di atto deliberativo all'ANAC","wrong2":"A sottoporre lo schema di atto deliberativo alla Regione competente","wrong3":"A sottoporre lo schema di atto deliberativo al Consiglio di Stato in sede consultiva"},{"id":1006,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Il Testo Unico stabilisce che le società a controllo pubblico:","correct":"Definiscono, con propri provvedimenti, criteri e modalità per il reclutamento del personale nel rispetto dei principi di trasparenza, pubblicità e imparzialità","wrong1":"Possono selezionare liberamente il proprio personale, come qualunque società privata","wrong2":"Reclutano il proprio personale applicando obbligatoriamente il Codice dei Contratti Pubblici","wrong3":"Reclutano il proprio personale avvalendosi di società private di scouting, previa valutazione informale del CV di ogni singolo candidato"},{"id":1007,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Le società pubbliche:","correct":"Sono soggette alle disposizioni sul fallimento e sul concordato preventivo, nonché, se ne ricorrono i presupposti, a quelle in materia di amministrazione straordinaria delle grandi imprese insolventi","wrong1":"Sono soggette alle sole disposizioni sul fallimento, non anche a quelle sul concordato preventivo","wrong2":"Non sono soggette alle disposizioni sul fallimento ma a quelle sul concordato preventivo e, se ne ricorrono i presupposti, a quelle in materia di amministrazione straordinaria delle grandi imprese insolventi","wrong3":"Non sono soggette alle disposizioni sul fallimento e sul concordato preventivo, nonché a quelle in materia di amministrazione straordinaria delle grandi imprese insolventi"},{"id":1008,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Per un legittimo affidamento in favore di società in house è necessario, tra l'altro, che:","correct":"La società affidataria svolga oltre l'80% delle proprie attività in favore della stazione appaltante controllante","wrong1":"La società affidataria svolga non più dell'80% delle proprie attività in favore della stazione appaltante controllante","wrong2":"La società affidataria svolga oltre l'70% delle proprie attività in favore della stazione appaltante controllante","wrong3":"La società affidataria svolga il 100% delle proprie attività in favore della stazione appaltante controllante"},{"id":1009,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Per un legittimo affidamento in favore di società in house è necessario, tra l'altro, che:","correct":"La stazione appaltate eserciti sulla persona giuridica affidataria un controllo analogo a quello esercitato sui propri servizi","wrong1":"La stazione appaltate non eserciti sulla persona giuridica affidataria un controllo analogo a quello esercitato sui propri servizi","wrong2":"La stazione appaltate eserciti sulla persona giuridica affidataria il controllo sulla corretta esecuzione del contratto affidato","wrong3":"La stazione appaltate trasmetta preventivamente gli atti di affidamento alla Corte dei Conti per l'ottenimento di un parere di legittimità"},{"id":1010,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Per un legittimo affidamento in favore di società in house è necessario, tra l'altro, che:","correct":"Nella persona giuridica controllata non vi sia alcuna partecipazione diretta di capitali privati, ad eccezione di forme di partecipazione di capitali privati previste dalla legislazione nazionale, in conformità con i trattati europei, e che detti privati non esercitano un'influenza determinante sulla persona giuridica controllata","wrong1":"Nella persona giuridica controllata vi siano partecipazioni private di controllo","wrong2":"Nella persona giuridica controllata vi siano partecipazioni private di controllo ed il socio privato sia anche socio operativo","wrong3":"Nella persona giuridica controllata la stazione appaltante detenga l'intero capitale sociale"},{"id":1011,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"L’art. 5 del Testo Unico stabilisce che le stazioni appaltanti esercitano su una persona giuridica un controllo congiunto quando, oltre ad altri, sia soddisfatto il seguente requisito:","correct":"Gli organi decisionali della persona giuridica controllata sono composti da rappresentanti di tutte le stazioni appaltanti partecipanti","wrong1":"Gli organi decisionali della persona giuridica controllata sono composti da almeno il 70% dei rappresentanti di tutte le stazioni appaltanti partecipanti","wrong2":"Gli organi decisionali della persona giuridica controllata sono composti da almeno il 80% dei rappresentanti di tutte le stazioni appaltanti partecipanti","wrong3":"Gli organi decisionali della persona giuridica controllata sono composti da almeno il 50% dei rappresentanti di tutte le stazioni appaltanti partecipanti"},{"id":1012,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"L’art. 5 del Codice stabilisce che le stazioni appaltanti esercitano su una persona giuridica un controllo congiunto quando, oltre ad altri, sia soddisfatto il seguente requisito:","correct":"Tali stazioni appaltanti sono in grado di esercitare congiuntamente un'influenza determinante sugli obiettivi strategici e sulle decisioni significative della società affidataria","wrong1":"Tali stazioni appaltanti sono in grado di esercitare ciascuna autonomamente un'influenza determinante sugli obiettivi strategici e sulle decisioni significative della società affidataria","wrong2":"Tali stazioni appaltanti sono in grado di esercitare singolarmente un'influenza rilevante ma non determinante sugli obiettivi strategici e sulle decisioni significative della società","wrong3":"Tali stazioni appaltanti sono tenuti ad esprimere pareri non vincolanti sugli obiettivi strategici e sulle decisioni significative della società"},{"id":1013,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"La Corte dei Conti ha giurisdizione:","correct":"In caso di danno al patrimonio sociale causato dagli amministratori e dai dipendenti delle società in house","wrong1":"In caso di danno al patrimonio sociale delle sole società controllate da pubbliche amministrazioni, causato dagli amministratori e dai dipendenti di quelle società","wrong2":"In caso di danno al patrimonio sociale causato dagli amministratori e dai dipendenti di società pubbliche, quotate su mercati regolamentati","wrong3":"In caso di danno al patrimonio sociale di tutte le società partecipate da pubbliche amministrazioni causato dagli amministratori e dai dipendenti di quelle società"},{"id":1014,"paragraph":"I contratti della PA - Le società pubbliche. Costituzione, controlli e crisi di impresa","question":"Per un legittimo affidamento in favore di società in house è necessario, tra l'altro, che:","correct":"La società affidataria svolga oltre l'80% delle proprie attività in favore della stazione appaltante controllante","wrong1":"La società affidataria svolga almeno il 50% delle proprie attività in favore della stazione appaltante controllante","wrong2":"La società affidataria svolga oltre il 90% delle proprie attività in favore della stazione appaltante controllante","wrong3":"La società affidataria svolga il 100% delle proprie attività in favore della stazione appaltante controllante"},{"id":1015,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"L'autonomia contrattuale:","correct":"è il potere riconosciuto alle parti di determinare liberamente «il contenuto del contratto nei limiti imposti dalla legge» ed, eventualmente, di «concludere contratti che non appartengano ai tipi aventi una disciplina particolare, purché siano diretti a realizzare interessi meritevoli di tutela secondo l'ordinamento giuridico»","wrong1":"è l'incondizionato potere riconosciuto alle parti di determinare il contenuto del contratto ed, eventualmente, di «concludere contratti che non appartengano ai tipi aventi una disciplina particolare, purché siano diretti a realizzare interessi meritevoli di tutela secondo l'ordinamento giuridico»","wrong2":"è il potere riconosciuto alle parti di incidere nella sfera giuridica dei terzi","wrong3":"è l'obbligo delle parti di concludere contratti"},{"id":1016,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Dal combinato disposto degli artt. 1321 e 1322 c.c. si evince:","correct":"che l'accordo è qualificabile come contratto se il rapporto su cui verte ha carattere patrimoniale","wrong1":"che l'accordo è qualificabile come contratto se il rapporto su cui verte ha carattere non patrimoniale","wrong2":"che le parti non possono concludere contratti che non appartengono ai tipi legali aventi una disciplina particolare","wrong3":"che la patrimonialità deve necessariamente caratterizzare anche l'interesse della o delle parti"},{"id":1017,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Il codice civile:","correct":"riserva un'ampia e dettagliata disciplina al contratto e non al negozio giuridico","wrong1":"non disiplina né il contratto né il negozio giuridico","wrong2":"riserva un'ampia e dettagliata disciplina al negozio giuridico e non al contratto","wrong3":"riserva un'ampia e dettagliata disciplina sia il contratto che il negozio giuridico"},{"id":1018,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Il contratto di deposito di liquido seminale crioconservato presso struttura specializzata:","correct":"può legittimamente prevedere la distruzione del liquido seminale alla scadenza del contratto, purché: a) la relativa clausola sia formulata con sufficiente chiarezza; b) l'interessato sia stato debitamente informato e invitato a esprimere le proprie determinazioni; c) sia comunque decorso un congruo periodo di tempo senza che egli abbia manifestato la propria volontà","wrong1":"è vietato per legge","wrong2":"può legittimamente prevedere la distruzione del liquido seminale alla scadenza del contratto, purché: a) la relativa clausola sia formulata con sufficiente chiarezza senza che occorra informare l'interessato nè invitato ad esprimere le proprie opinioni; b) sia comunque decorso un congruo periodo di tempo senza che egli abbia manifestato la propria volontà.","wrong3":"può legittimamente prevedere incondizionatamente la distruzione del liquido seminale alla scadenza del contratto"},{"id":1019,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"La clausola che prevede la distruzione delle cellule riproduttive:","correct":"deve essere formulata in modo chiaro e comprensibile e adeguatamente illustrata all'interessato","wrong1":"deve essere verbale","wrong2":"deve essere formulata in modo chiaro e comprensibile ma non deve essere illustrata all'interessato","wrong3":"va eseguita appena è scaduto il termine, senza informare in anticipo il disponente sull'approssimarsi della scadenza"},{"id":1020,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"La previsione di un corrispettivo a favore della clinica per il deposito del liquido seminale da crioconservare:","correct":"è legittima limitatamente al corrispettivo che l'interessato ha versato per ottenere un servizio che gli consente di realizzare un suo intimo interesse meritevole di tutela che è quello di mantenere la capacità procreativa","wrong1":"è illegittima","wrong2":"è inefficace","wrong3":"è legittima limitatamente all'ipotesi di cessione onerosa del materiale biologico"},{"id":1021,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Gli accordi dispositivi del proprio corpo ex art. 5 c.c.:","correct":"sono validi ogniqualvolta non ledano in modo permanente l'integrità fisica o non travalichino la soglia dell'illiceità","wrong1":"sono sempre illegittimi","wrong2":"sono sempre legittimi","wrong3":"sono validi ogniqualvolta ledano in modo permanente l'integrità fisica o non travalichino la soglia dell'illiceità"},{"id":1022,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Le disposizioni anticipate di trattamento (D.A.T.):","correct":"possono essere disattese in tutto o in parte dal medico stesso, in accordo con il fiduciario, quando appaiono «palesemente incongrue», «non corrispondenti alla situazione clinica attuale» o quando «sussistano terapie non prevedibili all'atto della sottoscrizione»","wrong1":"non possono essere disattese dal medico stesso","wrong2":"possono essere disattese in tutto o in parte dal medico stesso, in accordo con il fiduciario, quando appaiono congruenti e corrispondenti alla situazione clinica attuale","wrong3":"sono irrilevanti giuridicamente"},{"id":1023,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Le regole poste alla base dei negozi a contenuto non patrimoniale:","correct":"sono impegnative e, dunque, vincolanti ancorché incoercibili","wrong1":"sono regole di cortesia non impegnative","wrong2":"sono vincolanti e coercibili","wrong3":"sono coercibili ma non vincolanti"},{"id":1024,"paragraph":"I contratti della PA - Autonomia negoziale a contenuto non patrimoniale","question":"Gli atti a contenuto non patrimoniali esigono tendenzialmente:","correct":"la capacità naturale di intendere e volere","wrong1":"la capacità di agire","wrong2":"che il soggetto che li compie sia in stato di interdizione","wrong3":"che il soggetto che li compie sia incapace di intendere e volere"},{"id":1025,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"La dottrina amministrativistica, soprattutto francese e italiana, distingue:","correct":"l'attività giuridica dall'attività sociale dello Stato e degli enti pubblici","wrong1":"le attività autoritative impositive da quelle autoritative consensuali","wrong2":"i servizi pubblici locali da quelli territoriali","wrong3":"i servizi pubblici essenziali da quelli soltanto eventuali"},{"id":1026,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"Quando la Pubblica Amministrazione eroga un servizio:","correct":"non esercita, di norma, un potere autoritativo","wrong1":"esercita un potere autoritativo","wrong2":"non esercita un potere autoritativo, in quanto la Pubblica Amministrazione in nessun caso può esercitarlo","wrong3":"chiede al cittadino, senza nessun caso di esenzione, un corrispettivo in denaro"},{"id":1027,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"La definizione che la dottrina amministrativistica francese ha fornito di servizio pubblico è:","correct":"ogni attività la cui esplicazione deve essere assicurata, regolata e controllata dai governanti in quanto indispensabile alla realizzazione e allo sviluppo dell'interdipendenza sociale e che è di natura tale da non poter essere completamente realizzata se non con l'intervento della forza di governo","wrong1":"ogni attività la cui esplicazione deve essere assicurata, regolata e controllata dai governanti in quanto indispensabile alla realizzazione e allo sviluppo sociale e che è di natura tale da poter essere completamente realizzata anche da un'impresa privato","wrong2":"quelle particolarissime attività la cui esplicazione deve essere erogata, soltanto in alcuni casi, dai governanti","wrong3":"ogni esercizio di pubblico potere indispensabile alla realizzazione e allo sviluppo economico e che è di natura tale da dover essere completamente realizzato con l'intervento della forza di governo"},{"id":1028,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"Municipalizzare un servizio vuol dire:","correct":"che il Comune si riserva di produrre quel servizio, o in forma di concessione ad un'impresa o direttamente","wrong1":"che lo deve erogare la polizia municiaple","wrong2":"che il servizio è erogato all'interno del Municipio","wrong3":"privatizzare un servizio che prima era gestito a livello regionale"},{"id":1029,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"La Costituzione indica alcuni \"servizi specifici\" senza però definirli \"servizi\" e, tra questi, vi è:","correct":"la previdenza sociale","wrong1":"la facoltà di emanare leggi","wrong2":"la possibilità di privatizzare un servizio","wrong3":"il Servizio Sanitario Nazionale"},{"id":1030,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"Un servizio può essere definito \"pubblico\":","correct":"anche se è gestito da un'impresa privata","wrong1":"soltanto se è gestito dallo Stato o da un Ente","wrong2":"solo quando è gratuito","wrong3":"se è un servizio gratuito per tutti i cittadini, anche stranieri"},{"id":1031,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"Il modello dell'impresa:","correct":"è applicabile soltanto ad alcuni servizi sociali, per altri è escluso per definizione","wrong1":"è applicabile a tutti i servizi","wrong2":"non è mai applicabile ai servizi","wrong3":"è imposto per alcuni servizi"},{"id":1032,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"A livello locale sono state sperimentate essenzialmente due forme di gestione del servizio:","correct":"la gestione indiretta a mezzo di appalto e la gestione a mezzo di azienda municipalizzata","wrong1":"la gestione indiretta a mezzo di impresa pubblica locale e la gestione a mezzo di azienda municipalizzata","wrong2":"la gestione indiretta a mezzo di appalto e la gestione a mezzo di Amministrazione periferica","wrong3":"la gestione appaltata e la gestione non appaltata"},{"id":1033,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"Vi sono due elementi che qualificano un servizio come \"pubblico”:","correct":"il dovere per l'Amministrazione di esplicare l'attività e l'impossibilità che un soggetto diverso dal potere pubblico possa erogare quel servizio","wrong1":"la spesa di denaro pubblico e l'erogazione attraverso un Ente","wrong2":"l'accessibilità a tutti i cittadini (anche stranieri) e la gratuità","wrong3":"la presenza di cariche politiche all'interno dell'impresa e la spesa di denaro pubblico"},{"id":1034,"paragraph":"I contratti della PA - Servizi pubblici: profili generali","question":"I servizi pubblici che non sono ritenuti essenziali (art. 43 Costituzione):","correct":"non sono suscettibili di nazionalizzazione, quindi non possono essere riservati ai pubblici poteri","wrong1":"sono suscettibili di nazionalizzazione, quindi possono essere riservati ai pubblici poteri","wrong2":"sono riservati allo Stato","wrong3":"sono riservati ai Comuni"},{"id":1035,"paragraph":"I contratti della PA - Servizi pubblici locali e servizi sociali","question":"In seguito alla sent. 195/2012 della Corte costituzionale:","correct":"la disciplina dei servizi pubblici locali è rimasta affidata alla disciplina del diritto U.E.","wrong1":"la materia dei servizi pubblici locali è rimasta priva di disciplina legislativa","wrong2":"ha continuato a trovare applicazione il d.l. n. 138/2011","wrong3":"la materia è rimasta regolata dalla Costituzione"},{"id":1036,"paragraph":"I contratti della PA - Servizi pubblici locali e servizi sociali","question":"Il d.lgs. n. 201 del 2022:","correct":"reca il riordino della disciplina dei servizi pubblici locali, introducendo disposizioni di carattere generale che si integrano con le normative di settore","wrong1":"ha profondamente innovato la disciplina dei servizi pubblici locali","wrong2":"reca il riordino della disciplina dei servizi sociali","wrong3":"introduce, per la prima volta, il principio di sussidiarietà"},{"id":1037,"paragraph":"I contratti della PA - Servizi pubblici locali e servizi sociali","question":"Gli enti del terzo settore:","correct":"sono enti che, previa iscrizione nel registro unico nazionale, esercitano attività di interesse generale senza scopo di lucro","wrong1":"sono enti che esercitano attività di impresa","wrong2":"sono enti iscritti nel Registro delle Imprese","wrong3":"sono enti che esercitano attività di interesse generale con scopo di lucro"},{"id":1038,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Il Comune disciplina l'assetto urbanistico dell'intero territorio comunale con:","correct":"Il Piano Regolatore Generale","wrong1":"Il Regolamento Edilizio Comunale","wrong2":"Le Norme Tecniche di Attuazione","wrong3":"Le determine dirigenziali"},{"id":1039,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Le previsioni del Piano Regolatore Generale hanno durata:","correct":"Indeterminata","wrong1":"Di 5 anni","wrong2":"Di 10 anni","wrong3":"Di 20 anni"},{"id":1040,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Il Piano Urbanistico Attuativo:","correct":"Va sempre approvato, salvo il caso del piccolo fondo intercluso","wrong1":"Va sempre approvato","wrong2":"Va approvato se su richiesta del privato","wrong3":"Non va mai approvato se non sussistono le opere di urbanizzazione"},{"id":1041,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"I vincoli preordinati alla espropriazione hanno durata:","correct":"Di 5 anni","wrong1":"Indeterminata","wrong2":"Di 10 anni","wrong3":"Di 20 anni"},{"id":1042,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Il Comune provvede sulla istanza di ritipizzazione urbanistica:","correct":"Con la adozione dell'atto di pianificazione urbanistica","wrong1":"Con risposte generiche, evasive, elusive, soprassessorie o interlocutorie","wrong2":"Entro due anni","wrong3":"Conferendo in ogni caso alla area depianificata una destinazione edificatoria"},{"id":1043,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Quali termini sono indicati nell'atto di permesso a costruire:","correct":"Sia i termini d'inizio che di ultimazione dei lavori","wrong1":"I termini relativi al costo dell'opera","wrong2":"I termini di ultimazione dei lavori","wrong3":"Esclusivamente i termini di inizio dei lavori"},{"id":1044,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Dalla data di presentazione della D.I.A. :","correct":"I lavori possono essere iniziati trascorsi 30 giorni","wrong1":"I lavori possono essere iniziati trascorsi 60 giorni","wrong2":"I lavori possono essere iniziati senza limitazioni di tempo","wrong3":"I lavori possono essere iniziati trascorsi 20 giorni"},{"id":1045,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Il ricorso alla S.C.I.A. è previsto per tutti gli interventi che:","correct":"Che siano conformi alle previsioni degli strumenti urbanistici e dei regolamenti edilizi e della disciplina urbanistico-edilizia vigente","wrong1":"Siano riconducibili all'elenco di cui all'art. 10 T.U. D.P.R. 380/2001","wrong2":"Siano riconducibili all'elenco di cui all'art. 6 T.U. D.P.R. 380/2001","wrong3":"Non è previsto per nessun tipo di intervento"},{"id":1046,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Il permesso di costruire una volta rilasciato:","correct":"Può essere annullato con provvedimento motivato","wrong1":"Non può essere annullato","wrong2":"Può essere annullato con provvedimento privo di motivazione","wrong3":"Deve essere annullato entro dieci giorni dal rilascio"},{"id":1047,"paragraph":"I contratti della PA - Il governo del territorio e titoli abilitativi in edilizia","question":"Con riguardo al procedimento di rilascio del permesso di costruire, il principio del silenzio assenso è stato introdotto dal:","correct":"Decreto legge 70/2011","wrong1":"Legge 241/1990","wrong2":"Decreto legge n. 40 del 25 marzo 2010","wrong3":"Legge 22 maggio 2010 n. 73"},{"id":1048,"paragraph":"Sistemi di elaborazione delle informazioni - 1) La pianificazione strategica e il conseguimento degli obiettivi aziendali","question":"Uno di questi fattori non è necessario per la formulazione di una strategia di successo:","correct":"L'accesso a risorse maggiori rispetto ai propri competitor","wrong1":"Implementazione strategica efficace","wrong2":"La presenza di obiettivi semplici, coerenti e di lungo termine","wrong3":"Profonda comprensione dell'ambiente competitivo"},{"id":1049,"paragraph":"Sistemi di elaborazione delle informazioni - 1) La pianificazione strategica e il conseguimento degli obiettivi aziendali","question":"I tre insiemi di caratteristiche cruciali dell'impresa sono costituiti da:","correct":"Obiettivi e valori / risorse e competenze / struttura e sistemi organizzativi","wrong1":"Obiettivi e valori/risorse/ competenze","wrong2":"Obiettivi/valori/struttura e sistemi organizzativi","wrong3":"Obiettivi e valori/risorse e competenze/concorrenti"},{"id":1050,"paragraph":"Sistemi di elaborazione delle informazioni - 1) La pianificazione strategica e il conseguimento degli obiettivi aziendali","question":"Uno solo dei seguenti termini è associabile alla definizione \"piano complessivo per lo spiegamento di risorse necessarie a una posizione di vantaggio\":","correct":"Strategia","wrong1":"Tattica","wrong2":"Visione","wrong3":"Obiettivi"},{"id":1051,"paragraph":"Sistemi di elaborazione delle informazioni - 2) Pianificazione e gestione strategica","question":"La pianificazione aziendale:","correct":"Fu concepita come strumento per coordinare le singole decisioni di investimento","wrong1":"Si concentra esclusivamente sulla concorrenza","wrong2":"Ha segnato la focalizzazione sulla resource based view","wrong3":"Non riveste alcun ruolo all'interno delle strategie dell'impresa"},{"id":1052,"paragraph":"Sistemi di elaborazione delle informazioni - 2) Pianificazione e gestione strategica","question":"La strategia di gruppo (o corporate strategy):","correct":"Definisce il campo d'azione dell'impresa attraverso la scelta dei settori e dei mercati in cui competere","wrong1":"Definisce il modo di competere all'interno di un determinato settore o mercato","wrong2":"Definisce obiettivi, valori e sistemi organizzativi","wrong3":"E' mirata a favorire la formazione e il potenziamento dei gruppi aziendali"},{"id":1053,"paragraph":"Sistemi di elaborazione delle informazioni - 2) Pianificazione e gestione strategica","question":"La strategia emergente:","correct":"È l'insieme di decisioni che emergono in merito alla strategia deliberata, per adattarla alle variazioni delle circostanze esterne","wrong1":"E' la strategia che viene effettivamente implementata","wrong2":"E' la strategia come viene concepita dal gruppo di dirigenti al vertice","wrong3":"E' la strategia che non ha alcun effetto sulla strategia che viene poi realizzata"},{"id":1054,"paragraph":"Sistemi di elaborazione delle informazioni - 3) La generazione del valore","question":"Il valore creato corrisponde a:","correct":"Surplus del consumatore + surplus del produttore","wrong1":"Surplus del consumatore - surplus del produttore","wrong2":"Ricavi delle vendite - costi delle vendite","wrong3":"Surplus del consumatore"},{"id":1055,"paragraph":"Sistemi di elaborazione delle informazioni - 3) La generazione del valore","question":"Il profitto è:","correct":"L'eccedenza del fatturato sui costi","wrong1":"Il fatturato dell'azienda","wrong2":"L'insieme dei ricavi della gestione caratteristica","wrong3":"La somma di tutti i costi dell'impresa"},{"id":1056,"paragraph":"Sistemi di elaborazione delle informazioni - 3) La generazione del valore","question":"Il ROCE è il rapporto tra:","correct":"Il risultato operativo e le attività totali al netto del passivo corrente","wrong1":"Utile netto e capitale azionario","wrong2":"Il risultato operativo e i ricavi","wrong3":"Utile netto e attività totali"},{"id":1057,"paragraph":"Sistemi di elaborazione delle informazioni - 4) Valutazione delle prestazioni aziendali","question":"Le misure di performance \"forward-looking\":","correct":"Servono per massimizzare il profitto lungo l'intera vita dell'impresa","wrong1":"Non si basano sul mercato azionario","wrong2":"Sono basate su indicatori contabili","wrong3":"Analizzano le performance delle risorse umane"},{"id":1058,"paragraph":"Sistemi di elaborazione delle informazioni - 4) Valutazione delle prestazioni aziendali","question":"Un passo fondamentale nella diagnosi della performance consiste nel:","correct":"Disaggregare il ROA in margine sulle vendite e rotazione del capitale","wrong1":"Sommare gli ammortamenti al capitale investito","wrong2":"Disaggregare l'utile netto","wrong3":"Sottrarre gli ammortamenti dal capitale investito"},{"id":1059,"paragraph":"Sistemi di elaborazione delle informazioni - 4) Valutazione delle prestazioni aziendali","question":"Adottando la strategia delle opzioni reali si può:","correct":"Identificare le opzioni che realmente creano valore aggiunto per l'impresa","wrong1":"Raggruppare le diverse fasi del progetto e ricondurle a un'unica opzione reale","wrong2":"Suddividere il progetto in fasi e impegnarsi nella fase successiva, sulla base della situazione del momento","wrong3":"Focalizzarsi sul NPV"},{"id":1060,"paragraph":"Sistemi di elaborazione delle informazioni - 5) Il modello delle 5 forze competitive di Porter: Analisi dell'ambiente","question":"Il nucleo centrale dell'ambiente di riferimento è costituito da:","correct":"Clienti, fornitori, concorrenti","wrong1":"Clienti, fornitori, concorrenti, organi di governo","wrong2":"Clienti, fornitori, concorrenti, banche","wrong3":"Clienti, fornitori, banche"},{"id":1061,"paragraph":"Sistemi di elaborazione delle informazioni - 5) Il modello delle 5 forze competitive di Porter: Analisi dell'ambiente","question":"Il livello di redditività è determinato da:","correct":"Influenza sistematica della struttura del settore","wrong1":"Livello di competitività delle imprese del settore","wrong2":"Quantità di domanda","wrong3":"Numero di imprese concorrenti"},{"id":1062,"paragraph":"Sistemi di elaborazione delle informazioni - 5) Il modello delle 5 forze competitive di Porter: Analisi dell'ambiente","question":"Secondo il modello delle 5 forze di Michael Porter:","correct":"Ci sono due fonti di competizione verticale e tre fonti di competizione orizzontale","wrong1":"Ci sono tre fonti di competizione verticale e tre fonti di competizione orizzontale","wrong2":"Ci sono tre fonti di competizione verticale e due fonti di competizione orizzontale","wrong3":"Ci sono una fonte di competizione verticale e quattro fonti di competizione orizzontale"},{"id":1063,"paragraph":"Sistemi di elaborazione delle informazioni - 6) La collocazione dell'impresa e la composizione del mercato","question":"Una fase necessaria alla previsione della redditività di un settore consiste nel:","correct":"individuare le tendenze del settore","wrong1":"esaminare i libvelli passati di concorrenza dei settori che offrono prodotti complementari","wrong2":"individuare la redditività dei clienti","wrong3":"individuare il livello di redditività dei competitor"},{"id":1064,"paragraph":"Sistemi di elaborazione delle informazioni - 6) La collocazione dell'impresa e la composizione del mercato","question":"I confini di un mercato sono definiti da:","correct":"la sostituibilità da parte della domanda e dell'offerta","wrong1":"l'area geografica","wrong2":"la sostituibilità da parte della domanda","wrong3":"la numerosità delle imprese concorrenti"},{"id":1065,"paragraph":"Sistemi di elaborazione delle informazioni - 6) La collocazione dell'impresa e la composizione del mercato","question":"Per individuare i fattori critici di successo bisogna chiedersi:","correct":"che cosa desiderano i nostri clienti e che cosa deve fare l'impresa per sopravvivere alla concorrenza","wrong1":"che cosa desiderano i nostri clienti","wrong2":"che cosa deve fare l'impresa per sopravvivere alla concorrenza","wrong3":"produrre prodotti/servizi perfetti"},{"id":1066,"paragraph":"Sistemi di elaborazione delle informazioni - 7) L'analisi del settore e della concorrenza","question":"L'incidenza dei fattori settoriali sulla redditività delle imprese è:","correct":"inferiore al 20%","wrong1":"superiore al 30%","wrong2":"inferiore al 5%","wrong3":"inferiore al 50%"},{"id":1067,"paragraph":"Sistemi di elaborazione delle informazioni - 7) L'analisi del settore e della concorrenza","question":"I prodotti sostitutivi:","correct":"riducono il valore di un prodotto","wrong1":"aumentano il valore di un prodotto","wrong2":"non hanno effetti sul valore di un prodotto","wrong3":"non vengono considerati nel modello delle 5 forze"},{"id":1068,"paragraph":"Sistemi di elaborazione delle informazioni - 7) L'analisi del settore e della concorrenza","question":"L'elemento centrale del business model canvas è:","correct":"la proposta di valore","wrong1":"i prodotti complemetari","wrong2":"le piattaforme rivali","wrong3":"le relazioni"},{"id":1069,"paragraph":"Sistemi di elaborazione delle informazioni - 8) Il modello della Teoria dei Giochi","question":"Le comunicazioni selettive di informazioni ai concorrenti destinate a influenzare la loro percezione sono dette:","correct":"segnali","wrong1":"messaggi","wrong2":"avvisaglie","wrong3":"pubblicità"},{"id":1070,"paragraph":"Sistemi di elaborazione delle informazioni - 8) Il modello della Teoria dei Giochi","question":"La raccolta di informazioni sui concorrenti è finalizzata a:","correct":"prevedere le loro strategie future; prevedere le loro reazioni a iniziative prese da altre imprese; determinare come può essere influenzato il loro comportamento","wrong1":"è un processo semmplice e breve","wrong2":"non incontra mai problematiche riferite al \"limite legale\"","wrong3":"serve solo per l'analisi del passato"},{"id":1071,"paragraph":"Sistemi di elaborazione delle informazioni - 8) Il modello della Teoria dei Giochi","question":"L'analisi di segmentazione:","correct":"utilizza le caratteristiche dei mercati come base per disaggregare i settori","wrong1":"segmenta il settore sulla base delle strategie delle azienda che ne fanno parte","wrong2":"segmenta il settore sulla base della redditività delle imprese","wrong3":"segmenta il settore sulla base della teoria dei giochi"},{"id":1072,"paragraph":"Sistemi di elaborazione delle informazioni - 9) Il potenziale dell'impresa: risorse e competenze","question":"La resource-based view of the firm è stata concettualizzata:","correct":"Nel corso degli anni '90","wrong1":"Nel 2000","wrong2":"Nel 2010","wrong3":"Nel 2020"},{"id":1073,"paragraph":"Sistemi di elaborazione delle informazioni - 9) Il potenziale dell'impresa: risorse e competenze","question":"I profitti derivanti da posizioni di supremazia nel mercato sono tipicamente chiamati:","correct":"Rendite monopolistiche","wrong1":"Rendite ricardiane","wrong2":"Rendite efficienti","wrong3":"Rendite esterne"},{"id":1074,"paragraph":"Sistemi di elaborazione delle informazioni - 9) Il potenziale dell'impresa: risorse e competenze","question":"Le risorse aziendali si suddividono in:","correct":"Tangibili, Intangibili, Umane","wrong1":"Tangibili e Intangibili","wrong2":"Tangibili, Finanziarie, Umane","wrong3":"Intangibili, Finanziarie, Umane"},{"id":1075,"paragraph":"Sistemi di elaborazione delle informazioni - 10) Le risorse, le competenze e il vantaggio competitivo","question":"L'analisi funzionale serve per:","correct":"identificare le competenze organizzative in relazione alle principali aree funzionali dell'impresa","wrong1":"distinguere le risorse tangibili da quelle intangibili","wrong2":"identificare una catena sequenziale delle principali attività dell'impresa","wrong3":"distinguere le risorse umane da quelle intangibili"},{"id":1076,"paragraph":"Sistemi di elaborazione delle informazioni - 10) Le risorse, le competenze e il vantaggio competitivo","question":"La gerarchia delle competenze si definisce in base:","correct":"alla genericità/specificità della competenza in esame","wrong1":"alla gerarchia del dipendente che ne fa capo","wrong2":"alla redditività relativa di ogni singola competenza","wrong3":"alla numerosità delle routine organizzative"},{"id":1077,"paragraph":"Sistemi di elaborazione delle informazioni - 10) Le risorse, le competenze e il vantaggio competitivo","question":"Tra queste vi è una modalità diffusa di gestione dei punti deboli:","correct":"il benchmarking","wrong1":"la manutenzione","wrong2":"l'esternalizzazione","wrong3":"l'integrazione orizzontale"},{"id":1078,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il diritto alla protezione dei dati personali:","correct":"attribuisce al soggetto il diritto di controllare la circolazione di dati e informazioni che lo riguardano, permettendo, così, di definirsi e determinarsi","wrong1":"significa diritto ad essere lasciati soli eprotegge la sfera individuale dalle intrusioni esterne","wrong2":"corrisponde al diritto all'uso delle tecnologie","wrong3":"è sinonimo del diritto di accesso ad Internet"},{"id":1079,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il diritto alla riservatezza:","correct":"significa diritto ad essere lasciati soli e protegge la sfera individuale dalle intrusioni esterne","wrong1":"è sinonimo del diritto di accesso ad Internet","wrong2":"attribuisce al soggetto il diritto di controllare la circolazione di dati e informazioni che lo riguardano, permettendo, così, di definirsi e determinarsi","wrong3":"corrisponde al diritto all'uso delle tecnologie"},{"id":1080,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"L'atto normativo che a livello europeo è dedicato attualmente a disciplinare la protezione dei dati personali è:","correct":"il regolamento UE 2016/679 relativo alla protezione delle persone fisiche con riguardo al trattamento dei dati personali, nonché alla libera circolazione di tali dati","wrong1":"la Convenzione europea per la salvaguardia dei diritti dell'uomo e delle libertà fondamentali (CEDU)","wrong2":"la direttiva 95/46/CE","wrong3":"il Codice in materia di protezione dei dati personali, d.lgs.196/2003 modificato dal d.lgs. 101/2018"},{"id":1081,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"L'atto normativo che a livello nazionale è dedicato attualmente a disciplinare la protezione dei dati personali è:","correct":"il Codice in materia di protezione dei dati personali, d.lgs.196/2003 modificato dal d.lgs. 101/2018","wrong1":"il regolamento UE 2016/679 relativo alla protezione delle persone fisiche con riguardo al trattamento dei dati personali, nonché alla libera circolazione di tali dati","wrong2":"la direttiva 95/46/CE","wrong3":"la Convenzione europea per la salvaguardia dei diritti dell'uomo e delle libertà fondamentali (CEDU)"},{"id":1082,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il regolamento europeo 2016/679 rispetto alla direttiva europea 95/46/CE:","correct":"prevede un modello di condivisione e cogestione dei dati, fin dall'origine destinati alla circolazione globale, fondato su una tutela preventiva e \"attiva\"","wrong1":"un modello statico di trattamento dei dati personali di carattere riparatorio","wrong2":"mantiene lo stesso modello di tutela","wrong3":"prevede un modello centrato sullo scambio di dati tra interessato e titolare, privo di social e motori di ricerca"},{"id":1083,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il regolamento europeo 2016/679:","correct":"stabilisce norme relative alla protezione delle persone fisiche con riguardo al trattamento dei dati personali, nonché norme relative alla libera circolazione di tali dati","wrong1":"stabilisce soltanto norme relative alla protezione delle persone fisiche con riguardo al trattamento dei dati personali","wrong2":"stabilisce soltanto norme relative alla libera circolazione di tali dati","wrong3":"stabilisce norme relative alla tutela della proprietà intellettuale del soggetto"},{"id":1084,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Ai sensi della normativa europea il trattamento dei dati personali dovrebbe essere:","correct":"al servizio dell'uomo","wrong1":"al servizio dello Stato","wrong2":"al servizio delle piattaforme digitali","wrong3":"gestito considerando il diritto alla protezione dei dati personali come una prerogativa assoluta"},{"id":1085,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il regolamento europeo 2016/679 si applica:","correct":"al trattamento interamente o parzialmente automatizzato di dati personali e al trattamento non automatizzato di dati personali","wrong1":"al trattamento non automatizzato di dati personali","wrong2":"solo al trattamento parzialmente automatizzato di dati personali","wrong3":"solo al trattamento interamente automatizzato di dati personali"},{"id":1086,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il regolamento europeo 2016/679 non si applica:","correct":"ai trattamenti di dati personali effettuati da una persona fisica per l'esercizio di attività a carattere esclusivamente personale o domestico","wrong1":"al trattamento interamente automatizzato di dati personali","wrong2":"al trattamento parzialmente automatizzato di dati personali","wrong3":"al trattamento non automatizzato di dati personali"},{"id":1087,"paragraph":"Sistemi di elaborazione delle informazioni - 11) Protezione dei dati personali: il diritto alla tutela dei dati personali, la disciplina di riferimento e l'ambito di applicazione","question":"Il regolamento europeo 2016/679 a livello territoriale:","correct":"al trattamento effettuato nell'ambito delle attività di uno stabilimento da parte di un titolare o di un responsabile nell'Unione, indipendentemente dal fatto che il trattamento sia effettuato o meno nell'Unione","wrong1":"in Italia","wrong2":"al trattamento effettuato nell'ambito delle attività di uno stabilimento da parte di un titolare o di un responsabile nell'Unione, solo se il trattamento è effettuato nell'Unione","wrong3":"In Italia, Germania e Francia"},{"id":1088,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Il dato personale è:","correct":"qualsiasi informazione riguardante una persona fisica, identificata o identificabile, direttamente o indirettamente con particolare riferimento a un identificativo come il nome, un numero di identificazione, dati relativi all'ubicazione, un identificativo online o a uno o più elementi caratteristici dell'identità fisica, fisiologica, genetica, psichica, economica, culturale o sociale","wrong1":"un dato che, in origine o a seguito di trattamento, non può essere riferito ad una persona fisica identificata o identificabile","wrong2":"qualsiasi informazione riguardante una persona fisica, che sia identificata direttamente","wrong3":"qualsiasi operazione o insieme di operazioni, compiute con o senza l'ausilio di processi automatizzati e applicate a dati personali o insiemi di dati personali"},{"id":1089,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Il dato anonimo è:","correct":"un dato che, in origine o a seguito di trattamento, non può essere riferito ad una persona fisica identificata o identificabile","wrong1":"qualsiasi operazione o insieme di operazioni, compiute con o senza l'ausilio di processi automatizzati e applicate a dati personali o insiemi di dati personali","wrong2":"qualsiasi informazione riguardante una persona fisica, identificata o identificabile, direttamente o indirettamente con particolare riferimento a un identificativo come il nome, un numero di identificazione, dati relativi all'ubicazione, un identificativo online o a uno o più elementi caratteristici dell'identità fisica, fisiologica, genetica, psichica, economica, culturale o sociale","wrong3":"qualsiasi informazione riguardante una persona fisica, che sia identificata indirettamente"},{"id":1090,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"La pseudonimizzazione è:","correct":"il trattamento in modo tale che i dati personali non possano più essere attribuiti a un interessato specifico senza l'utilizzo di informazioni aggiuntive, a condizione che tali informazioni aggiuntive siano conservate separatamente e soggette a misure tecniche e organizzative intese a garantire che tali dati personali non siano attribuiti a una persona fisica identificata o identificabile","wrong1":"dare conoscenza dei dati personali a soggetti indeterminati, in qualunque forma, anche mediante messa a disposizione o consultazione","wrong2":"dare conoscenza dei dati personali a uno o più soggetti determinati diversi da interessato, responsabile e persone autorizzate, in qualunque forma, anche mediante messa a disposizione, consultazione o interconnessione","wrong3":"qualsiasi operazione o insieme di operazioni, compiute con o senza l'ausilio di processi automatizzati e applicate a dati personali o insiemi di dati personali"},{"id":1091,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Trattamento dei dati personali significa:","correct":"qualsiasi operazione o insieme di operazioni, compiute con o senza l'ausilio di processi automatizzati e applicate a dati personali o insiemi di dati personali, come raccolta, registrazione, organizzazione, strutturazione, conservazione, adattamento o modifica, estrazione, consultazione, uso, comunicazione mediante trasmissione, diffusione o qualsiasi altra forma di messa a disposizione, raffronto o interconnessione, limitazione, cancellazione o distruzione","wrong1":"qualsiasi informazione riguardante una persona fisica, identificata o identificabile, direttamente o indirettamente con particolare riferimento a un identificativo come il nome, un numero di identificazione, dati relativi all'ubicazione, un identificativo online o a uno o più elementi caratteristici dell'identità fisica, fisiologica, genetica, psichica, economica, culturale o sociale","wrong2":"dare conoscenza dei dati personali a uno o più soggetti determinati diversi da interessato, responsabile e persone autorizzate, in qualunque forma, anche mediante messa a disposizione, consultazione o interconnessione","wrong3":"il trattamento in modo tale che i dati personali non possano più essere attribuiti a un interessato specifico senza l'utilizzo di informazioni aggiuntive, a condizione che tali informazioni aggiuntive siano conservate separatamente e soggette a misure tecniche e organizzative intese a garantire che tali dati personali non siano attribuiti a una persona fisica identificata o identificabile"},{"id":1092,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"La diffusione dei dati personali consiste in:","correct":"dare conoscenza dei dati personali a soggetti indeterminati, in qualunque forma, anche mediante messa a disposizione o consultazione","wrong1":"dare conoscenza dei dati personali a uno o più soggetti determinati diversi da interessato, responsabile e persone autorizzate, in qualunque forma, anche mediante messa a disposizione, consultazione o interconnessione","wrong2":"qualsiasi forma di trattamento automatizzato di dati personali consistente nell'utilizzo di dati personali per valutare determinati aspetti personali relativi a una persona fisica, in particolare per analizzare o prevedere aspetti riguardanti: il rendimento professionale; la situazione economica; la salute; le preferenze personali; gli interessi; l'affidabilità; il comportamento; l'ubicazione o gli spostamenti di detta persona fisica","wrong3":"qualsiasi informazione riguardante una persona fisica, identificata o identificabile, direttamente o indirettamente con particolare riferimento a un identificativo come il nome, un numero di identificazione, dati relativi all'ubicazione, un identificativo online o a uno o più elementi caratteristici dell'identità fisica, fisiologica, genetica, psichica, economica, culturale o sociale"},{"id":1093,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Profilazione significa:","correct":"qualsiasi forma di trattamento automatizzato di dati personali consistente nell'utilizzo di dati personali per valutare determinati aspetti personali relativi a una persona fisica, in particolare per analizzare o prevedere aspetti riguardanti: il rendimento professionale; la situazione economica; la salute; le preferenze personali; gli interessi; l'affidabilità; il comportamento; l'ubicazione o gli spostamenti di detta persona fisica","wrong1":"dare conoscenza dei dati personali a soggetti indeterminati, in qualunque forma, anche mediante messa a disposizione o consultazione","wrong2":"qualsiasi operazione o insieme di operazioni, compiute con o senza l'ausilio di processi automatizzati e applicate a dati personali o insiemi di dati personali","wrong3":"dare conoscenza dei dati personali a uno o più soggetti determinati diversi da interessato, responsabile e persone autorizzate, in qualunque forma, anche mediante messa a disposizione, consultazione o interconnessione"},{"id":1094,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Nella disciplina in materia di protezione dei dati personali l'interessato è:","correct":"persona fisica cui si riferiscono i dati personali","wrong1":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo eventualmente preposto dal titolare che tratta dati personali per conto del titolare","wrong2":"la persone fisica autorizzata a compiere operazioni di trattamento dal titolare o dal responsabile","wrong3":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo, che, singolarmente o insieme ad altri titolari, determina le finalità e i mezzi del trattamento di dati personali"},{"id":1095,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Il titolare del trattamento dei dati personali corrisponde a:","correct":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo, che, singolarmente o insieme ad altri titolari, determina le finalità e i mezzi del trattamento di dati personali","wrong1":"la persona fisica autorizzata a compiere operazioni di trattamento dal titolare o dal responsabile","wrong2":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo eventualmente preposto dal titolare che tratta dati personali per conto del titolare","wrong3":"la persona fisica cui si riferiscono i dati personali"},{"id":1096,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Il responsabile del trattamento dei dati personali corrisponde a:","correct":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo eventualmente preposto dal titolare che tratta dati personali per conto del titolare","wrong1":"la persone fisica autorizzata a compiere operazioni di trattamento dal titolare o dal responsabile","wrong2":"la persona fisica o giuridica, l'autorità pubblica, il servizio o altro organismo, che, singolarmente o insieme ad altri titolari, determina le finalità e i mezzi del trattamento di dati personali","wrong3":"la persona fisica cui si riferiscono i dati personali"},{"id":1097,"paragraph":"Sistemi di elaborazione delle informazioni - 12) Data Protection: dati, trattamento e soggetti","question":"Il Garante per la protezione dei dati personali è:","correct":"l'autorità di controllo indipendente, che a livello europeo sorveglia e assicura la corretta applicazione delle disposizioni","wrong1":"l'autorità di controllo indipendente, che a livello nazionale sorveglia e assicura la corretta applicazione delle disposizioni","wrong2":"l'autorità di controllo indipendente, che a livello internazionale sorveglia e assicura la corretta applicazione delle disposizioni","wrong3":"l'Autorità per le Garanzie nelle Comunicazioni"},{"id":1098,"paragraph":"Sistemi di elaborazione delle informazioni - 13) Elaborazione ed implementazione strategica","question":"Secondo Henry Mintzberg:","correct":"la strategia emerge dall'interazione tra formulazione e implementazione","wrong1":"la gestione strategica è un processo a due fasi: prima formulazione, poi implementazione","wrong2":"strategia deliberata e strategia emergente sono sinonimi","wrong3":"la strategia è solo quella deliberata"},{"id":1099,"paragraph":"Sistemi di elaborazione delle informazioni - 13) Elaborazione ed implementazione strategica","question":"I meccanismi di coordinamento sono:","correct":"adattamento reciproco/routine/norme e direttive","wrong1":"prezzo/adattamento reciproco/routine","wrong2":"prezzo/adattamento reciproco/routine/regole e direttive/minacce e segnali","wrong3":"prezzo/minacce e segnali"},{"id":1100,"paragraph":"Sistemi di elaborazione delle informazioni - 13) Elaborazione ed implementazione strategica","question":"Uno solo tra questi fattori non serve per l'integrazione di risorse e lo sviluppo di competenze:","correct":"valori condivisi","wrong1":"struttura","wrong2":"motivazione","wrong3":"processi"},{"id":1101,"paragraph":"Sistemi di elaborazione delle informazioni - 14) La struttura organizzativa","question":"I principali vantaggi delle strutture gerarchiche rispetto al coordinamento delle attività produttive sono:","correct":"risparmio sul coordinamento e adattabilità","wrong1":"contenimento dei costi e flessibilità","wrong2":"lo sviluppo di una comunicazione e flessibilità","wrong3":"maggior grado di libertà"},{"id":1102,"paragraph":"Sistemi di elaborazione delle informazioni - 14) La struttura organizzativa","question":"Le imprese che operano in una sola area d'affari tendono a essere organizzate per:","correct":"struttura funzionale","wrong1":"struttura multidivisionale","wrong2":"struttura a matrice","wrong3":"adhocrazia"},{"id":1103,"paragraph":"Sistemi di elaborazione delle informazioni - 14) La struttura organizzativa","question":"In quale di queste condizioni il modello organico è vantaggioso rispetto al modello meccanicistico:","correct":"quando i mercati sono turbolenti e l'innovazione è veloce","wrong1":"quando beni e servizi sono standardizzati","wrong2":"quando i dipendenti hanno piena fiducia nei superiori","wrong3":"quando l'offerta è superiore alla domanda"},{"id":1104,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Secondo il principio di limitazione della finalità:","correct":"i dati personali devono essere raccolti per finalità determinate, esplicite e legittime, e successivamente trattati in modo che non sia incompatibile con tali finalità","wrong1":"i dati personali devono essere adeguati, pertinenti e limitati a quanto necessario rispetto alle finalità per le quali sono trattati","wrong2":"i dati personali devono essere trattati in maniera da garantire adeguata sicurezza, compresa la protezione da trattamenti non autorizzati o illeciti e da perdita, distruzione o danno accidentali","wrong3":"i dati personali devono essere conservati in una forma che consenta l'identificazione degli interessati per un arco di tempo non superiore al conseguimento delle finalità per le quali sono trattati"},{"id":1105,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Secondo il principio di minimizzazione dei dati:","correct":"i dati personali devono essere adeguati, pertinenti e limitati a quanto necessario rispetto alle finalità per le quali sono trattati","wrong1":"i dati personali devono essere conservati in una forma che consenta l'identificazione degli interessati per un arco di tempo non superiore al conseguimento delle finalità per le quali sono trattati","wrong2":"i dati personali devono essere raccolti per finalità determinate, esplicite e legittime, e successivamente trattati in modo che non sia incompatibile con tali finalità","wrong3":"i dati personali devono essere trattati in maniera da garantire adeguata sicurezza, compresa la protezione da trattamenti non autorizzati o illeciti e da perdita, distruzione o danno accidentali"},{"id":1106,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Secondo il principio di limitazione della conservazione:","correct":"i dati personali devono essere conservati in una forma che consenta l'identificazione degli interessati per un arco di tempo non superiore al conseguimento delle finalità per le quali sono trattati","wrong1":"i dati personali devono essere raccolti per finalità determinate, esplicite e legittime, e successivamente trattati in modo che non sia incompatibile con tali finalità","wrong2":"i dati personali devono essere adeguati, pertinenti e limitati a quanto necessario rispetto alle finalità per le quali sono trattati","wrong3":"i dati personali devono essere trattati in maniera da garantire adeguata sicurezza, compresa la protezione da trattamenti non autorizzati o illeciti e da perdita, distruzione o danno accidentali"},{"id":1107,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Il principio di responsabilizzazione significa quanto segue:","correct":"il titolare del trattamento è competente per il rispetto dei principi applicabili al trattamento e deve essere in grado di comprovarlo","wrong1":"i dati personali devono essere adeguati, pertinenti e limitati a quanto necessario rispetto alle finalità per le quali sono trattati","wrong2":"i dati personali devono essere raccolti per finalità determinate, esplicite e legittime, e successivamente trattati in modo che non sia incompatibile con tali finalità","wrong3":"i dati personali devono essere trattati in maniera da garantire adeguata sicurezza, compresa la protezione da trattamenti non autorizzati o illeciti e da perdita, distruzione o danno accidentali"},{"id":1108,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Il consenso dell'interessato è una:","correct":"manifestazione di volontà libera, informata, specifica e inequivocabile, mediante dichiarazione o azione positiva","wrong1":"manifestazione di volontà libera, informata, generica e tacita","wrong2":"manifestazione di volontà libera, informata, specifica e inequivocabile, mediante dichiarazione o azione positiva o tacita o presunta","wrong3":"manifestazione di volontà libera, informata, specifica e inequivocabile, mediante dichiarazione tacita o presunta"},{"id":1109,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"L'interessato ha diritto di revocare il proprio consenso:","correct":"in qualsiasi momento","wrong1":"mai","wrong2":"in fattispecie previste dalle norme","wrong3":"solo se lo prevede il titolare del trattamento"},{"id":1110,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Nel caso di categorie particolari di dati personali:","correct":"il principio generale è il divieto di trattamento, a meno che non ricorrano le specifiche condizioni di liceità previste dal regolamento europeo","wrong1":"non ci sono particolari condizioni per poter procedere con il trattamento","wrong2":"si possono trattare alle stesse condizioni di liceità degli altri dati personali","wrong3":"esiste un limite insuperabile che consiste nel divieto di trattamento in ogni caso"},{"id":1111,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Le informazioni sono fornite all'interessato:","correct":"per iscritto o con altri mezzi, anche, se del caso, con mezzi elettronici; se richiesto dall'interessato, le informazioni possono essere fornite oralmente, purché sia comprovata con altri mezzi l'identità dell'interessato","wrong1":"solo per iscritto e non con mezzi elettronici","wrong2":"solo oralmente","wrong3":"per iscritto o oralmente nel modo che decide il titolare"},{"id":1112,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"Il titolare del trattamento adotta misure appropriate per fornire le informazioni all'interessato:","correct":"in forma concisa, trasparente, intelligibile e facilmente accessibile, con un linguaggio semplice e chiaro","wrong1":"in modo orale","wrong2":"nel modo che ritiene più opportuno secondo le esigenze della propria organizzazione","wrong3":"nel modo scelto dall'interessato"},{"id":1113,"paragraph":"Sistemi di elaborazione delle informazioni - 15) Principi e condizioni di liceità del trattamento dei dati personali; trasparenza e informazioni","question":"I dati personali da parte del titolare del trattamento:","correct":"possono essere raccolti presso l'interessato o possono non essere ottenuti presso l'interessato, ma cambiano le informazioni da fornire previste dalle norme","wrong1":"devono necessariamente essere raccolti presso l'interessato","wrong2":"non devono mai essere raccolti presso l'interessato","wrong3":"possono essere raccolti presso l'interessato o possono non essere ottenuti presso l'interessato, fornendo le stesse informazioni all'interessato in entrambi i casi"},{"id":1114,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Non rientra tra i diritti dell'interessato nei confronti del titolare del trattamento:","correct":"il diritto di segnalazione e rimozione del titolare del trattamento","wrong1":"il diritto di opposizione","wrong2":"il diritto di accesso ai dati","wrong3":"il diritto di rettifica"},{"id":1115,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","correct":"diritto di ottenere dal titolare del trattamento conferma che sia o meno in corso un trattamento di dati personali e ,in tal caso, una copia dei dati personali oggetto di trattamento e l'accesso a una serie di informazioni previste dalla norma","wrong1":"diritto di ottenere dal titolare del trattamento la rettifica dei dati personali inesatti che lo riguardano senza ingiustificato ritardo","wrong2":"diritto di ricevere in un formato strutturato, di uso comune e leggibile da dispositivo automatico i dati personali che lo riguardano forniti a un titolare del trattamento e il diritto di trasmettere tali dati a un altro titolare del trattamento senza impedimenti da parte del titolare del trattamento","wrong3":"diritto di ottenere dal titolare del trattamento la limitazione del trattamento quando ricorre una delle ipotesi previste dalle disposizioni del regolamento europeo"},{"id":1116,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto di rettifica dell'interessato consiste nel:","correct":"diritto di ottenere dal titolare del trattamento la rettifica dei dati personali inesatti che lo riguardano senza ingiustificato ritardo","wrong1":"diritto di ottenere dal titolare del trattamento conferma che sia o meno in corso un trattamento di dati personali e,in tal caso, una copia dei dati personali oggetto di trattamento e l'accesso a una serie di informazioni previste dalla norma","wrong2":"diritto di ottenere dal titolare del trattamento la limitazione del trattamento quando ricorre una delle ipotesi previste dalle disposizioni del regolamento europeo","wrong3":"diritto di ricevere in un formato strutturato, di uso comune e leggibile da dispositivo automatico i dati personali che lo riguardano forniti a un titolare del trattamento e ha diritto di trasmettere tali dati a un altro titolare del trattamento senza impedimenti da parte del titolare del trattamento"},{"id":1117,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto di limitazione del trattamento dei dati personali consiste nel:","correct":"diritto di ottenere dal titolare del trattamento la limitazione del trattamento quando ricorre una delle ipotesi previste dalle disposizioni del regolamento europeo","wrong1":"diritto di ottenere dal titolare del trattamento la rettifica dei dati personali inesatti che lo riguardano senza ingiustificato ritardo","wrong2":"diritto di ricevere in un formato strutturato, di uso comune e leggibile da dispositivo automatico i dati personali che lo riguardano forniti a un titolare del trattamento e il diritto di trasmettere tali dati a un altro titolare del trattamento senza impedimenti da parte del titolare del trattamento","wrong3":"diritto di ottenere dal titolare del trattamento conferma che sia o meno in corso un trattamento di dati personali e,in tal caso, una copia dei dati personali oggetto di trattamento e l'accesso a una serie di informazioni previste dalla norma"},{"id":1118,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto alla portabilità dei dati personali corrisponde al:","correct":"diritto di ricevere in un formato strutturato, di uso comune e leggibile da dispositivo automatico i dati personali che lo riguardano forniti a un titolare del trattamento e il diritto di trasmettere tali dati a un altro titolare del trattamento senza impedimenti da parte del titolare del trattamento","wrong1":"diritto di ottenere dal titolare del trattamento la limitazione del trattamento quando ricorre una delle ipotesi previste dalle disposizioni del regolamento europeo","wrong2":"diritto di ottenere dal titolare del trattamento conferma che sia o meno in corso un trattamento di dati personali e,in tal caso, una copia dei dati personali oggetto di trattamento e l'accesso a una serie di informazioni previste dalla norma","wrong3":"diritto di ottenere dal titolare del trattamento la rettifica dei dati personali inesatti che lo riguardano senza ingiustificato ritardo"},{"id":1119,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto alla portabilità dei dati personali non si applica al:","correct":"trattamento necessario per l'esecuzione di un compito di interesse pubblico o connesso all'esercizio di pubblici poteri di cui è investito il titolare del trattamento","wrong1":"trattamento che si basi sul consenso o su un contratto","wrong2":"trattamento che sia effettuato con mezzi automatizzati","wrong3":"trattamento che si basi sul consenso o su un contratto o trattamento che sia effettuato con mezzi automatizzati"},{"id":1120,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto di opposizione dell'interessato consiste nel:","correct":"diritto di opporsi in qualsiasi momento, per motivi connessi alla sua situazione particolare, al trattamento per l'esecuzione di un compito di interesse pubblico o connesso all'esercizio di pubblici poteri o per il perseguimento di un legittimo interesse, compresa la profilazione","wrong1":"diritto di ottenere dal titolare del trattamento la limitazione del trattamento quando ricorre una delle ipotesi previste dalle disposizioni del regolamento europeo","wrong2":"diritto di ottenere dal titolare del trattamento la rettifica dei dati personali inesatti che lo riguardano senza ingiustificato ritardo","wrong3":"diritto di ottenere dal titolare del trattamento conferma che sia o meno in corso un trattamento di dati personali e,in tal caso, una copia dei dati personali oggetto di trattamento e l'accesso a una serie di informazioni previste dalla norma"},{"id":1121,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Qualora i dati personali siano trattati per finalità di marketing diretto l'interessato:","correct":"ha diritto di opporsi in qualsiasi momento al trattamento dei dati personali che lo riguardano effettuato per tali finalità, compresa la profilazione nella misura in cui sia connessa a tale marketing diretto","wrong1":"deve esprimere il proprio consenso secondo il modello di opt-in","wrong2":"deve fornire preventivo consenso esplicito","wrong3":"non ha diritto di opporsi al trattamento dei dati personali che lo riguardano effettuato per tali finalità, compresa la profilazione nella misura in cui sia connessa a tale marketing diretto"},{"id":1122,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"In caso di processo decisionale automatizzato di norma l'interessato:","correct":"diritto di non essere sottoposto a una decisione basata unicamente sul trattamento automatizzato, compresa la profilazione, che produca effetti giuridici che lo riguardano o che incida in modo analogo significativamente sulla sua persona","wrong1":"non ha diritto di non essere sottoposto a una decisione basata unicamente sul trattamento automatizzato, compresa la profilazione, che produca effetti giuridici che lo riguardano o che incida in modo analogo significativamente sulla sua persona","wrong2":"non ha i diritti che normalmente gli spettano nei confronti del titolare","wrong3":"deve accettare le policy del titolare e i diritti che decide di concedergli"},{"id":1123,"paragraph":"Sistemi di elaborazione delle informazioni - 16) I diritti dell'interessato in materia di protezione dei dati personali","question":"Il diritto di non essere sottoposto a una decisione basata unicamente sul trattamento automatizzato, compresa la profilazione, non si applica nei seguenti casi:","correct":"la decisione sia necessaria per la conclusione o l'esecuzione di un contratto; sia autorizzata dal diritto dell'Unione o dello Stato membro; si basi sul consenso esplicito dell'interessato","wrong1":"diversa regolazione da parte del titolare del trattamento rispetto alle previsioni del regolamento europeo","wrong2":"la decisione si basi sul consenso anche non esplicito dell'interessato","wrong3":"la decisione serva per per l'esecuzione di un compito di interesse pubblico o connesso all'esercizio di pubblici poteri"},{"id":1124,"paragraph":"Sistemi di elaborazione delle informazioni - 17) Impiego della statistica per la gestione dell'azienda","question":"Affinché l'esperto di statistica possa capire come affrontare l'analisi del problema attraverso l'impiego della statistica, i quesiti manageriali:","correct":"devono essere tradotti in quesiti statistici ai quali deve essere data risposta","wrong1":"non devono essere tradotti in quesiti statistici ai quali deve essere data risposta","wrong2":"devono essere tradotti in quesiti statistici ai quali non deve essere data risposta","wrong3":"non devono essere tradotti in quesiti statistici ai quali non deve essere data risposta"},{"id":1125,"paragraph":"Sistemi di elaborazione delle informazioni - 17) Impiego della statistica per la gestione dell'azienda","question":"La valutazione delle potenzialità del mercato del prodotto dell'azienda (o di un nuovo prodotto) è effettuata:","correct":"sulla base delle vendite nei mercati interni e internazionali","wrong1":"solo sulla base delle vendite nei mercati interni","wrong2":"solo sulla base delle vendite nei mercati internazionali","wrong3":"sulla base degli acquisti dei mercati interni"},{"id":1126,"paragraph":"Sistemi di elaborazione delle informazioni - 17) Impiego della statistica per la gestione dell'azienda","question":"I metodi statistici sono utilizzabili per analizzare:","correct":"qualsiasi fenomeno o problema di gestione dell'azienda che sia suscettibile di misurazione","wrong1":"solo problema di gestione dell'azienda","wrong2":"solo fenomeni che siano suscettibili di misurazione","wrong3":"un problema di gestione dell'azienda"},{"id":1127,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Tra le misure, i principi e gli strumenti previsti dal regolamento europeo 2016/679 non rientra:","correct":"code is law, law is code","wrong1":"data protection by design","wrong2":"data protection by default","wrong3":"Data Protection Impact Assessment"},{"id":1128,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Il principio data protection by design significa che:","correct":"Il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate, quali la pseudonimizzazione, volte ad attuare in modo efficace i principi di protezione dei dati, quali la minimizzazione, e a integrare nel trattamento le necessarie garanzie al fine di soddisfare i requisiti del regolamento e tutelare i diritti degli interessati","wrong1":"il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate per garantire che siano trattati, per impostazione predefinita, solo i dati personali necessari per ogni specifica finalità del trattamento.","wrong2":"il titolare del trattamento, prima di procedere al trattamento, consulta l'autorità di controllo qualora la valutazione d'impatto sulla protezione dei dati indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio","wrong3":"quando un tipo di trattamento, allorché prevede in particolare l'uso di nuove tecnologie, considerati la natura, l'oggetto, il contesto e le finalità del trattamento, può presentare un rischio elevato per i diritti e le libertà delle persone fisiche, il titolare del trattamento effettua, prima di procedere al trattamento, una valutazione dell'impatto dei trattamenti previsti sulla protezione dei dati personali"},{"id":1129,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Il principio data protection by default significa che:","correct":"il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate per garantire che siano trattati, per impostazione predefinita, solo i dati personali necessari per ogni specifica finalità del trattamento","wrong1":"Il titolare del trattamento, prima di procedere al trattamento, consulta l'autorità di controllo qualora la valutazione d'impatto sulla protezione dei dati indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio","wrong2":"il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate, quali la pseudonimizzazione, volte ad attuare in modo efficace i principi di protezione dei dati, quali la minimizzazione, e a integrare nel trattamento le necessarie garanzie al fine di soddisfare i requisiti del regolamento e tutelare i diritti degli interessati","wrong3":"quando un tipo di trattamento, allorché prevede in particolare l'uso di nuove tecnologie, considerati la natura, l'oggetto, il contesto e le finalità del trattamento, può presentare un rischio elevato per i diritti e le libertà delle persone fisiche, il titolare del trattamento effettua, prima di procedere al trattamento, una valutazione dell'impatto dei trattamenti previsti sulla protezione dei dati personali"},{"id":1130,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Data Protection Impact Assessment (DPIA) significa che:","correct":"quando un tipo di trattamento, allorché prevede in particolare l'uso di nuove tecnologie, considerati la natura, l'oggetto, il contesto e le finalità del trattamento, può presentare un rischio elevato per i diritti e le libertà delle persone fisiche, il titolare del trattamento effettua, prima di procedere al trattamento, una valutazione dell'impatto dei trattamenti previsti sulla protezione dei dati personali","wrong1":"il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate, quali la pseudonimizzazione, volte ad attuare in modo efficace i principi di protezione dei dati, quali la minimizzazione, e a integrare nel trattamento le necessarie garanzie al fine di soddisfare i requisiti del regolamento e tutelare i diritti degli interessati","wrong2":"il titolare del trattamento deve mettere in atto misure tecniche e organizzative adeguate per garantire che siano trattati, per impostazione predefinita, solo i dati personali necessari per ogni specifica finalità del trattamento","wrong3":"il titolare del trattamento, prima di procedere al trattamento, consulta l'autorità di controllo qualora la valutazione d'impatto sulla protezione dei dati indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio"},{"id":1131,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"La Data Protection Impact Assessment (DPIA) è richiesta in particolare nei seguenti casi:","correct":"una valutazione sistematica e globale di aspetti personali relativi a persone fisiche, basata su un trattamento automatizzato;il trattamento su larga scala di categorie particolari di dati personali o di dati relativi a condanne penali e a reati; la sorveglianza sistematica su larga scala di una zona accessibile al pubblico","wrong1":"esecuzione di un compito di interesse pubblico o connesso all'esercizio di pubblici poteri di cui è investito il titolare del trattamento","wrong2":"consenso esplicito dell'interessato oppure presenza di un contratto tra titolare e interessato","wrong3":"perseguimento del legittimo interesse del titolare del trattamento"},{"id":1132,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"La Data Protection Impact Assessment (DPIA) non contiene:","correct":"la consultazione delle parti sociali","wrong1":"una descrizione sistematica dei trattamenti previsti e delle finalità del trattamento","wrong2":"una valutazione dei rischi per i diritti e le libertà degli interessati","wrong3":"una valutazione della necessità e proporzionalità dei trattamenti in relazione alle finalità"},{"id":1133,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Il registro del trattamento è tenuto:","correct":"in forma scritta, anche in formato elettronico","wrong1":"esclusivamente in forma orale","wrong2":"nelle modalità determinate dal titolare del trattamento","wrong3":"nelle modalità richieste dall'interessato"},{"id":1134,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Il titolare del trattamento, prima di procedere al trattamento, consulta l'autorità di controllo qualora:","correct":"la valutazione d'impatto sulla protezione dei dati indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio","wrong1":"la data protection by design indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio","wrong2":"la data protection by default indichi che il trattamento presenterebbe un rischio elevato in assenza di misure adottate dal titolare del trattamento per attenuare il rischio","wrong3":"sia avvenuto un data breach"},{"id":1135,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"In caso di violazione dei dati personali (data breach) il titolare:","correct":"notifica la violazione all'autorità di controllo competente senza ingiustificato ritardo e, ove possibile, entro 72 ore dal momento in cui ne è venuto a conoscenza","wrong1":"notifica la violazione al data protection officer senza ingiustificato ritardo e, ove possibile, entro 72 ore dal momento in cui ne è venuto a conoscenza","wrong2":"notifica la violazione alla polizia postale senza ingiustificato ritardo e, ove possibile, entro 72 ore dal momento in cui ne è venuto a conoscenza","wrong3":"notifica la violazione all'interessato senza ingiustificato ritardo e, ove possibile, entro 72 ore dal momento in cui ne è venuto a conoscenza"},{"id":1136,"paragraph":"Sistemi di elaborazione delle informazioni - 18) Gli strumenti giuridici della Data Protection","question":"Il titolare del trattamento comunica la violazione all'interessato senza ingiustificato ritardo con linguaggio semplice e chiaro quando:","correct":"la violazione è suscettibile di presentare un rischio elevato per i diritti e le libertà delle persone fisiche","wrong1":"è richiesto dal data protection officer","wrong2":"è richiesto dall'autorità di controllo","wrong3":"quando la violazione non è suscettibile di presentare un rischio elevato per i diritti e le libertà delle persone fisiche"},{"id":1137,"paragraph":"Sistemi di elaborazione delle informazioni - 19) Informazioni statistiche: concetti generali e fonti esterne","question":"Con l'espressione fonte dei dati si indica:","correct":"il database, la pubblicazione cartacea, il sito web, il file o altro supporto dal quale i dati sono stati estratti","wrong1":"solo la pubblicazione cartacea","wrong2":"solo il database","wrong3":"il database, la pubblicazione cartacea, ma non il sito web"},{"id":1138,"paragraph":"Sistemi di elaborazione delle informazioni - 19) Informazioni statistiche: concetti generali e fonti esterne","question":"Le fonti di dati esterne all'azienda sono costituite:","correct":"dall'insieme delle statistiche prodotte da soggetti sia pubblici che privati che operano nel sistema","wrong1":"dall'insieme delle statistiche prodotte da soggetti privati che operano nel sistema","wrong2":"dall'insieme delle statistiche prodotte da soggetti pubblici che operano nel sistema","wrong3":"dall'insieme delle statistiche prodotte da soggetti sia pubblici che privati che non operano nel sistema"},{"id":1139,"paragraph":"Sistemi di elaborazione delle informazioni - 19) Informazioni statistiche: concetti generali e fonti esterne","question":"Nella homepage del sito sono riportate le serie storiche aggiornate dei principali indicatori economici:","correct":"tra i quali PIL, tasso di disoccupazione, prezzi al consumo, retribuzioni","wrong1":"tra i quali ROI, tasso di disoccupazione, prezzi al consumo, retribuzioni","wrong2":"solo il tasso di disoccupazione","wrong3":"solo le retribuzioni"},{"id":1140,"paragraph":"Sistemi di elaborazione delle informazioni - 20) Informazioni statistiche: le fonti esterne e i big data","question":"Le fonti di dati esterne all'azienda sono costituite:","correct":"dall'insieme delle statistiche prodotte da soggetti sia pubblici che privati che operano nel sistema","wrong1":"dall'insieme delle statistiche prodotte da soggetti privati che operano nel sistema","wrong2":"dall'insieme delle statistiche prodotte da soggetti pubblici che operano nel sistema","wrong3":"dall'insieme delle statistiche prodotte da soggetti sia pubblici che privati che non operano nel sistema"},{"id":1141,"paragraph":"Sistemi di elaborazione delle informazioni - 20) Informazioni statistiche: le fonti esterne e i big data","question":"I Big Data sono tali se hanno tre caratteristiche fondamentali, sintetizzate dalle cosiddette \"3V\":","correct":"il volume; l'ampia varietà di formati; la velocità di generazione","wrong1":"solo il volume e l'ampia varietà di formati","wrong2":"solo il volume e la velocità di generazione","wrong3":"la varianza; l'ampia varietà di formati; la velocità di generazione"},{"id":1142,"paragraph":"Sistemi di elaborazione delle informazioni - 20) Informazioni statistiche: le fonti esterne e i big data","question":"Le tipologie di analytics si possono dividere in tre categorie:","correct":"analisi descrittiva-diagnostica; analisi predittiva; analisi prescrittiva","wrong1":"analisi diagnostica; analisi predittiva; analisi prescrittiva","wrong2":"analisi descrittiva-diagnostica; analisi non predittiva; analisi prescrittiva","wrong3":"analisi descrittiva-diagnostica; analisi predittiva; analisi pre-selettiva"},{"id":1143,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Tra le misure di sicurezza previste dal regolamento europeo 2016/679 non è annoverata esplicitamente:","correct":"l'intelligenza artificiale","wrong1":"la pseudonimizzazione","wrong2":"la cifratura","wrong3":"la capacità di ripristino tempestivo"},{"id":1144,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"I codici di condotta:","correct":"sono destinati a contribuire alla corretta applicazione del regolamento europeo, in funzione delle specificità dei vari settori di trattamento e delle esigenze specifiche delle micro, piccole e medie imprese","wrong1":"sono destinati a dimostrare la conformità al regolamento europeo dei trattamenti effettuati dai titolari e dai responsabili","wrong2":"sono icone standardizzate per dare, in modo facilmente visibile, intelligibile echiaramente leggibile, un quadro d'insieme del trattamento previsto","wrong3":"sono le misure di sicurezza"},{"id":1145,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"I meccanismi di certificazione:","correct":"sono destinati a dimostrare la conformità al regolamento europeo dei trattamenti effettuati dai titolari e dai responsabili","wrong1":"sono le misure di sicurezza","wrong2":"sono icone standardizzate per dare, in modo facilmente visibile, intelligibile echiaramente leggibile, un quadro d'insieme del trattamento previsto","wrong3":"sono destinati a contribuire alla corretta applicazione del regolamento europeo, in funzione delle specificità dei vari settori di trattamento e delle esigenze specifiche delle micro, piccole e medie imprese"},{"id":1146,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Non rientra tra le tutele previste a favore dell'interessato in materia di data protection:","correct":"segnalazione al Responsabile per la transizione digitale","wrong1":"reclamo al Garante per la protezione dei dati personali","wrong2":"segnalazione al Garante per la protezione dei dati personali","wrong3":"ricorso all'autorità giudiziaria"},{"id":1147,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Il reclamo al Garante per la protezione dei dati personali:","correct":"è un atto dell'interessato con il quale si rappresenta una violazione della disciplina in materia di protezione dei dati personali","wrong1":"è un atto del Data Protection Officer nei confronti dell'interessato per violazione delle policy","wrong2":"è un ricorso all'autorità giudiziaria","wrong3":"è un atto del titolare del trattamento nei confronti dell'interessato per violazione delle policy"},{"id":1148,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Avverso la decisione del Garante per la protezione dei dati personali:","correct":"è ammesso il ricorso giurisdizionale","wrong1":"è ammessa la segnalazione al Data Protection Officer","wrong2":"non è ammesso il ricorso giurisdizionale","wrong3":"è ammesso il reclamo al titolare del trattamento"},{"id":1149,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Chiunque subisca un danno materiale o immateriale causato da una violazione del regolamento:","correct":"ha il diritto di ottenere il risarcimento del danno dal titolare o dal responsabile del trattamento","wrong1":"non ha il diritto di ottenere il risarcimento del danno dal titolare o dal responsabile del trattamento","wrong2":"ha il diritto di ottenere un provvedimento del titolare del trattamento","wrong3":"ha il diritto di ottenere un provvedimento del Data Protection Officer"},{"id":1150,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Il trasferimento di dati personali verso un paese terzo o un'organizzazione internazionale:","correct":"è vietato, salvi i casi previsti dalla normativa","wrong1":"è deciso con provvedimento del Data Protection Officer","wrong2":"è deciso dal titolare del trattamento","wrong3":"è sempre permesso"},{"id":1151,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Con la sentenza Schrems I:","correct":"la Corte invalida la decisione della Commissione europea 2000/520 e, di conseguenza, l'accordo \"Safe Harbour\"","wrong1":"la Corte conferma la decisione 2016/1250 sull'adeguatezza della protezione offerta dal EU-US Privacy Shield","wrong2":"la Corte conferma la decisione della Commissione europea 2000/520 e, di conseguenza, l'accordo \"Safe Harbour\"","wrong3":"la Corte dichiara invalida la decisione 2016/1250 sull'adeguatezza della protezione offerta dal EU-US Privacy Shield"},{"id":1152,"paragraph":"Sistemi di elaborazione delle informazioni - 21) Obblighi e responsabilità del titolare del trattamento dei dati personali","question":"Con la sentenza Schrems II:","correct":"la Corte dichiara invalida la decisione 2016/1250 sull'adeguatezza della protezione offerta dal EU-US Privacy Shield","wrong1":"la Corte conferma la decisione 2016/1250 sull'adeguatezza della protezione offerta dal EU-US Privacy Shield","wrong2":"la Corte conferma la decisione della Commissione europea 2000/520 e, di conseguenza, l'accordo \"Safe Harbour\"","wrong3":"la Corte invalida la decisione della Commissione europea 2000/520 e, di conseguenza, l'accordo \"Safe Harbour\""},{"id":1153,"paragraph":"Sistemi di elaborazione delle informazioni - 22) La produzione di dati: l'indagine campionaria","question":"L'indagine campionaria è un tipo specifico di rilevazione parziale:","correct":"in cui la parte di popolazione osservata è selezionata in modo da essere rappresentativa dell'intera popolazione","wrong1":"in cui la parte di popolazione non osservata è selezionata in modo da essere rappresentativa dell'intera popolazione","wrong2":"in cui la parte di popolazione osservata è selezionata in modo da essere rappresentativa di una parte della popolazione","wrong3":"in cui la parte di popolazione osservata è selezionata in modo da non essere rappresentativa dell'intera popolazione"},{"id":1154,"paragraph":"Sistemi di elaborazione delle informazioni - 22) La produzione di dati: l'indagine campionaria","question":"L'errore campionario può essere stimato:","correct":"se il campione è stato selezionato con meccanismo casuale ossia campioni probabilistici","wrong1":"se il campione non è stato selezionato con meccanismo casuale ossia campioni probabilistici","wrong2":"se il campione è stato selezionato con meccanismo occasionale ossia campioni probabilistici","wrong3":"se il campione è stato selezionato con meccanismo casuale ossia campioni non probabilistici"},{"id":1155,"paragraph":"Sistemi di elaborazione delle informazioni - 22) La produzione di dati: l'indagine campionaria","question":"Il primo requisito di qualità di un'indagine è:","correct":"la chiarezza ovvero la possibilità di accedere a tutte le informazioni relative agli strumenti di indagine utilizzati","wrong1":"la chiarezza ovvero la possibilità di accedere a poche informazioni relative agli strumenti di indagine utilizzati","wrong2":"la chiarezza ovvero la possibilità di accedere a tutte le informazioni relative agli strumenti di indagine non utilizzati","wrong3":"la chiarezza ovvero la possibilità di accedere a tutte le tecniche relative agli strumenti di indagine utilizzati"},{"id":1156,"paragraph":"Sistemi di elaborazione delle informazioni - 23) Interpretazione e comparazione dei dati aziendali","question":"La prima e più semplice analisi statistica consiste:","correct":"nell'interpretare il significato del dato e nel cercare di capire il \"messaggio\" che dallo stesso deriva","wrong1":"nell'interpretare il significato del dato e nel cercare di capire il \"numero\" che dallo stesso deriva","wrong2":"nell'interpretare il significato del dato e nel cercare di capire il \"messaggio\" che dallo stesso non deriva","wrong3":"nell'interpretare il significato del dato e nel cercare di capire il \"dato\" che dallo stesso deriva"},{"id":1157,"paragraph":"Sistemi di elaborazione delle informazioni - 23) Interpretazione e comparazione dei dati aziendali","question":"Il primo obiettivo delle comparazioni è:","correct":"evidenziare le differenze nel tempo o nello spazio dell'intensità (o frequenza) con cui un fenomeno X si è manifestato nelle due diverse circostanze","wrong1":"evidenziare le differenze nel tempo con cui un fenomeno X si è manifestato nelle due diverse circostanze","wrong2":"evidenziare le differenze nello spazio dell'intensità (o frequenza) con cui un fenomeno X si è manifestato nelle due diverse circostanze","wrong3":"evidenziare le differenze nel tempo o nello spazio dell'intensità (o frequenza) con cui un fenomeno X non si è manifestato nelle due diverse circostanze"},{"id":1158,"paragraph":"Sistemi di elaborazione delle informazioni - 23) Interpretazione e comparazione dei dati aziendali","question":"I numeri indici sono:","correct":"un particolare tipo di rapporto statistico che serve a misurare le variazioni relative di un certo fenomeno quantitativo","wrong1":"un particolare tipo di rapporto statistico che serve a valutare le variazioni relative di un certo fenomeno quantitativo","wrong2":"un particolare tipo di rapporto statistico che serve a misurare le variazioni relative di un certo fenomeno qualitativo","wrong3":"un particolare tipo di rapporto statistico che serve a valutare caratteristiche qualitative"},{"id":1159,"paragraph":"Sistemi di elaborazione delle informazioni - 24) I numeri indici sintetici: caratteristiche e interpretazione","question":"La costruzione dell'indice sintetico dei prezzi:","correct":"l'indice è ottenuto come rapporto tra aggregati in valore (costo, spesa ecc.), metodo che consente di coglierne meglio il significato economico","wrong1":"l'indice è ottenuto come differenza tra aggregati in valore (costo, spesa ecc.), metodo che consente di coglierne meglio il significato economico","wrong2":"l'indice è ottenuto come somma tra aggregati in valore (costo, spesa ecc.), metodo che consente di coglierne meglio il significato economico","wrong3":"l'indice è ottenuto come prodotto tra aggregati in valore (costo, spesa ecc.), metodo che consente di coglierne meglio il significato economico;"},{"id":1160,"paragraph":"Sistemi di elaborazione delle informazioni - 24) I numeri indici sintetici: caratteristiche e interpretazione","question":"Le proprietà di transitività delle basi e di scomposizione delle cause:","correct":"devono essere soddisfatte quando si vuole, rispettivamente, effettuare uno slittamento della base o un'operazione di concatenamento, oppure scomporre la variazione di valore in variazioni imputabili ai prezzi e alle quantità","wrong1":"devono essere soddisfatte quando si vuole, rispettivamente, effettuare uno slittamento della base o un'operazione di concatenamento, oppure scomporre la varianza di valore in variazioni imputabili ai prezzi e alle quantità","wrong2":"devono essere soddisfatte quando si vuole, rispettivamente, effettuare uno slittamento della base o un'operazione di concatenamento, oppure scomporre la variazione di valore in variazioni non imputabili ai prezzi e alle quantità","wrong3":"devono essere soddisfatte quando si vuole, rispettivamente, effettuare uno slittamento della base o un'operazione di concatenamento, oppure scomporre la variazione di valore in variazioni imputabili solo ai prezzi"},{"id":1161,"paragraph":"Sistemi di elaborazione delle informazioni - 24) I numeri indici sintetici: caratteristiche e interpretazione","question":"I numeri indici del commercio al dettaglio misurano:","correct":"la variazione, in valore e in volume, delle vendite registrate dalle imprese che svolgono come attività prevalente la vendita al dettaglio, così come definita dalla classificazione ATECO","wrong1":"la variazione, in valore e in volume, delle vendite registrate dalle imprese che svolgono come attività prevalente la vendita all'ingrosso, così come definita dalla classificazione ATECO","wrong2":"la variazione, in stima e in volume, delle vendite registrate dalle imprese che svolgono come attività prevalente la vendita al dettaglio, così come definita dalla classificazione ATECO","wrong3":"la variazione, in valore e in logaritmo, delle vendite registrate dalle imprese che svolgono come attività prevalente la vendita al dettaglio, così come definita dalla classificazione ATECO"},{"id":1162,"paragraph":"Sistemi di elaborazione delle informazioni - 25) Data Warhousing: metodologia e architettura","question":"Con il termine data warehousing intendiamo:","correct":"una collezione di metodi, tecnologie e strumenti di ausilio al cosiddetto \"lavoratore della conoscenza\"","wrong1":"solo una collezione di metodi di ausilio al cosiddetto \"lavoratore della conoscenza\"","wrong2":"solo una collezione di tecnologie di ausilio al cosiddetto \"lavoratore della conoscenza\"","wrong3":"una collezione di metodi, tecnologie e strumenti di ausilio al cosiddetto \"lavoratore della varianza\""},{"id":1163,"paragraph":"Sistemi di elaborazione delle informazioni - 25) Data Warhousing: metodologia e architettura","question":"Scomponendo l'acronimo FASMI, le caratteristiche principali che rendono un sistema adatto all'analisi interattiva dei dati sono le seguenti:","correct":"Veloce; Analitico; Condiviso; Multidimensionale; Informativo","wrong1":"lento; Analitico; Condiviso; Multidimensionale; Informativo.","wrong2":"Veloce; Analitico; Condiviso; bidimensionale; Informativo.","wrong3":"Veloce; Analitico; Condiviso; Multidimensionale; collettivo."},{"id":1164,"paragraph":"Sistemi di elaborazione delle informazioni - 25) Data Warhousing: metodologia e architettura","question":"I sistemi di data warehousing a due livelli presentano i seguenti elementi:","correct":"Il primo livello è costituito dalle sorgenti dei dati; Il secondo livello è costituito dalle aree di memorizzazione dei dati informazionali","wrong1":"Il primo livello è costituito dalle sorgenti dei dati; Il secondo livello è costituito dalle aree di memorizzazione dei dati non informazionali","wrong2":"Il primo livello è costituito dalle matrici; Il secondo livello è costituito dalle aree di memorizzazione dei dati informazionali","wrong3":"Il primo livello è costituito dalle sorgenti dei dati; Il secondo livello è costituito dalle aree architettoniche"},{"id":1165,"paragraph":"Sistemi di elaborazione delle informazioni - 26) Data Warhousing: modelli concettuali e ciclo di vita dei sistemi","question":"Il Dimensional Fact Model (DFM), proposto da Golfarelli nel 1988:","correct":"si tratta di un modello multidimensionale grafico definito in funzione delle problematiche tipiche del data warehousing","wrong1":"si tratta di un modello bidimensionale grafico definito in funzione delle problematiche tipiche del data warehousing","wrong2":"si tratta di un modello tridimensionale grafico definito in funzione delle problematiche tipiche del data warehousing","wrong3":"si tratta di un modello multidimensionale grafico definito in funzione delle problematiche atipiche del data warehousing"},{"id":1166,"paragraph":"Sistemi di elaborazione delle informazioni - 26) Data Warhousing: modelli concettuali e ciclo di vita dei sistemi","question":"Nell'approccio puramente ROLAP:","correct":"la struttura intrinsecamente multidimensionale dei fatti viene realizzata completamente su database relazionali","wrong1":"la struttura intrinsecamente multidimensionale dei fatti viene realizzata completamente su database polarizzati","wrong2":"la struttura intrinsecamente bidimensionale dei fatti viene realizzata completamente su database relazionali","wrong3":"la struttura intrinsecamente multidimensionale dei fatti viene realizzata completamente su database panel"},{"id":1167,"paragraph":"Sistemi di elaborazione delle informazioni - 26) Data Warhousing: modelli concettuali e ciclo di vita dei sistemi","question":"L'approccio iterativo consiste in:","correct":"cicli di espansione e revisione del sistema che permettono di tarare al meglio le gerarchie dimensionali e le misure dei fatti","wrong1":"cicli di espansione e revisione del sistema che non permettono di tarare al meglio le gerarchie dimensionali e le misure dei fatti","wrong2":"cicli di espansione e revisione del sistema che permettono di tarare al meglio le gerarchie tridimensionali e le misure dei fatti","wrong3":"cicli di espansione e revisione del sistema che permettono di tarare al meglio le gerarchie dimensionali e le misure dei corpi"},{"id":1168,"paragraph":"Sistemi di elaborazione delle informazioni - 27) Data Mining: processi di mining e analisi associative","question":"Ogni analisi di mining dei dati richiede l'indicazione dei parametri:","correct":"insieme dei dati di analisi; tipo di informazioni da ricercare; misure di interesse; base di conoscenza; presentazione dei pattern","wrong1":"solo insieme dei dati di analisi","wrong2":"solo tipo di informazioni da ricercare","wrong3":"solo misure di interesse"},{"id":1169,"paragraph":"Sistemi di elaborazione delle informazioni - 27) Data Mining: processi di mining e analisi associative","question":"Nell'ambito della generalizzazione esistono due approcci principali per definire quale sia un attributo da ridurre:","correct":"definire un valore di soglia V per l'attributo; definire un valore di soglia R per la relazione","wrong1":"definire un valore di soglia X per l'attributo; definire un valore di soglia R per la relazione;","wrong2":"definire un valore di soglia V per l'archetipo; definire un valore di soglia R per la relazione;","wrong3":"definire un valore di soglia V per l'attributo; definire un valore di soglia T per la relazione;"},{"id":1170,"paragraph":"Sistemi di elaborazione delle informazioni - 27) Data Mining: processi di mining e analisi associative","question":"I meccanismi di associazione permettono di:","correct":"identificare le condizioni che tendenzialmente si verificano contemporaneamente","wrong1":"identificare le condizioni che tendenzialmente si verificano singolarmente","wrong2":"identificare le variabili che tendenzialmente si verificano contemporaneamente","wrong3":"identificare le condizioni che saltuariamente si verificano contemporaneamente"},{"id":1171,"paragraph":"Sistemi di elaborazione delle informazioni - 28) Data Mining: meccanismi di classificazione e clustering","question":"L'attività di modellazione lavora principalmente su due linee:","correct":"L'identificazione di criteri; Il calcolo di funzioni di tendenza","wrong1":"L'identificazione di criteri; Il calcolo di logaritmi di tendenza","wrong2":"L'identificazione di paradigmi; Il calcolo di funzioni di tendenza","wrong3":"L'identificazione di criteri; Il calcolo di funzioni di devianza"},{"id":1172,"paragraph":"Sistemi di elaborazione delle informazioni - 28) Data Mining: meccanismi di classificazione e clustering","question":"I metodi di clustering hanno come effetto secondario l'identificazione degli outlier:","correct":"cioè di quegli elementi che restano al di fuori dei raggruppamenti e si presentano come punti isolati","wrong1":"cioè di quegli elementi che restano al di fuori delle distanze e si presentano come punti isolati","wrong2":"cioè di quegli elementi che restano dentro ai raggruppamenti e si presentano come punti isolati","wrong3":"cioè di quegli elementi che restano al di fuori dei raggruppamenti e si presentano come linee isolate"},{"id":1173,"paragraph":"Sistemi di elaborazione delle informazioni - 28) Data Mining: meccanismi di classificazione e clustering","question":"Di solito, in azienda:","correct":"il settore che si occupa del marketing è uno dei primi a beneficiare dei risultati del mining dei dati","wrong1":"il settore che si occupa del marketing è uno degli ultimi a beneficiare dei risultati del mining dei dati","wrong2":"il settore che si occupa del marketing è uno dei primi a deficitare dei risultati del mining dei dati","wrong3":"il settore che si occupa del marketing è uno dei primi a beneficiare dei risultati del timing dei dati"},{"id":1174,"paragraph":"Sistemi di elaborazione delle informazioni - 29) Big Data: aree di applicazione e impatti aziendali","question":"L'azienda ha un sistema che:","correct":"elabora, come big data, un set relativamente contenuto di oggetti complessi (immagini) per controllare la qualità","wrong1":"elabora, come somma, un set relativamente contenuto di oggetti complessi (immagini) per controllare la qualità","wrong2":"elabora, come big data, un set relativamente ampio di oggetti complessi (immagini) per controllare la qualità","wrong3":"elabora, come big data, un set relativamente contenuto di oggetti complessi (immagini) per controllare la variabilità"},{"id":1175,"paragraph":"Sistemi di elaborazione delle informazioni - 29) Big Data: aree di applicazione e impatti aziendali","question":"L'applicazione di soluzioni basate su big data aumenta l'efficienza dei reparti produttivi:","correct":"per esempio, dove il sistema di fabbrica è già integrato","wrong1":"per esempio, dove il sistema statistico è già integrato","wrong2":"per esempio, dove il sistema di fabbrica è già controllato","wrong3":"per esempio, dove il sistema sindacale è già integrato"},{"id":1176,"paragraph":"Sistemi di elaborazione delle informazioni - 29) Big Data: aree di applicazione e impatti aziendali","question":"L'introduzione di soluzioni basate su big data ha un impatto sull'organizzazione aziendale:","correct":"che si riflette in cambiamenti di modelli di lavoro e di modelli di business","wrong1":"che si riflette in cambiamenti di modelli di lavoro e di modelli statistici","wrong2":"che si riflette in variabili di modelli di lavoro e di modelli di business","wrong3":"che si riflette in cambiamenti di modelli di lavoro e di volume"},{"id":1177,"paragraph":"Sistemi di elaborazione delle informazioni - 30) Big Data: caratteristiche e peculiarità","question":"L'architettura di archiviazione che intercetta e memorizza i dati deve:","correct":"di conseguenza avere caratteristiche di bassa latenza, per tener testa alla velocità di generazione","wrong1":"di conseguenza avere caratteristiche di alta latenza, per tener testa alla velocità di generazione","wrong2":"di conseguenza avere caratteristiche di bassa latenza, per tener testa alla velocità di aggregazione","wrong3":"di conseguenza non avere caratteristiche di bassa latenza, per tener testa alla velocità di generazione"},{"id":1178,"paragraph":"Sistemi di elaborazione delle informazioni - 30) Big Data: caratteristiche e peculiarità","question":"I sistemi di archiviazione di tipo Complex Event Processing:","correct":"sono in grado di riconoscere molteplici tipologie di evento all'interno di un ambito digitale complesso e memorizzarne i dati salienti","wrong1":"sono in grado di riconoscere molteplici tipologie di numeri all'interno di un ambito digitale complesso e memorizzarne i dati salienti","wrong2":"sono in grado di riconoscere molteplici tipologie di evento all'interno di un ambito fisico complesso e memorizzarne i dati salienti","wrong3":"sono in grado di riconoscere molteplici tipologie di evento all'interno di un ambito digitale semplice e memorizzarne i dati salienti"},{"id":1179,"paragraph":"Sistemi di elaborazione delle informazioni - 30) Big Data: caratteristiche e peculiarità","question":"Dati come flusso:","correct":"nei data warehouse e nelle analisi che su questo si basano si privilegia l'osservazione degli eventi passati attraverso set di dati stabilizzati","wrong1":"nei data warehouse e nelle analisi che su questo si basano si privilegia l'indicizzazione degli eventi passati attraverso set di dati stabilizzati","wrong2":"nei data warehouse e nelle analisi che su questo si basano si privilegia l'osservazione degli eventi presenti attraverso set di dati stabilizzati","wrong3":"nei data warehouse e nelle analisi che su questo si basano si privilegia l'osservazione degli eventi passati attraverso set di dati normalizzati"},{"id":1180,"paragraph":"Sistemi di elaborazione delle informazioni - 31) La natura giuridica dell'algoritmo","question":"Con il termine intelligenza artificiale si intende:","correct":"un sistema basato su macchine progettato per funzionare con diversi livelli di autonomia e che può mostrare adattività dopo l'implementazione e che, per obiettivi espliciti o impliciti, deduce, dall'input che riceve, come generare output quali previsioni, contenuti, raccomandazioni o decisioni che possono influenzare ambienti fisici o virtuali","wrong1":"un software basato sull'impostazione deterministica if this, than that: indica un funzionamento predeterminato nel programma, che prevede input e output","wrong2":"un insieme di tecnologie che permettono l'accesso e l'utilizzo in base alle proprie esigenze di un insieme di risorse distribuite e accessibili in remoto tramite rete","wrong3":"enormi volumi di dati detenuti da grandi organizzazioni (governi, colossi tecnologici) provenienti da diverse fonti"},{"id":1181,"paragraph":"Sistemi di elaborazione delle informazioni - 31) La natura giuridica dell'algoritmo","question":"Tra le seguenti qual è la strada che non è richiamata per ricostruire la responsabilità in caso di intelligenza artificiale:","correct":"assenza di responsabilità","wrong1":"responsbailità del produttore","wrong2":"responsabilità per l'esercizio di attività pericolose","wrong3":"responsabilità dei proprietari per i danni cagionati da animali"},{"id":1182,"paragraph":"Sistemi di elaborazione delle informazioni - 31) La natura giuridica dell'algoritmo","question":"Sotto il profilo della natura giuridica dei sistemi di intelligenza artificiale quale tra le seguenti affermazioni è sostenuta dal Parlamento europeo:","correct":"sistemi agenti","wrong1":"mero prodotto","wrong2":"persona giuridica","wrong3":"soggetto giuridico dotato di autonomia paragonabile a persona giuridica"},{"id":1183,"paragraph":"Sistemi di elaborazione delle informazioni - 32) Sicurezza informatica: Cyber Risk e Cybersecurity","question":"La definizione normativa di cybersecurity del regolamento UE 2019/881 è:","correct":"l'insieme delle attività necessarie per proteggere la rete e i sistemi informativi, gli utenti di tali sistemi e altre persone interessate dalle minacce informatiche","wrong1":"qualsiasi circostanza, evento o azione che potrebbe danneggiare, perturbare o avere un impatto negativo di altro tipo sulla rete e sui sistemi informativi, sugli utenti di tali sistemi e altre persone","wrong2":"la potenziale perdita o perturbazione causata da un incidente","wrong3":"un evento che compromette la disponibilità, l'autenticità, l'integrità o la riservatezza di dati conservati, trasmessi o elaborati o dei servizi offerti dai sistemi informatici e di rete o accessibili attraverso di essi"},{"id":1184,"paragraph":"Sistemi di elaborazione delle informazioni - 32) Sicurezza informatica: Cyber Risk e Cybersecurity","question":"Il ransomware consiste in:","correct":"tipologia di malware che, talvolta anche senza bisogno di installarsi sul sistema, cifra i dati rendendoli inaccessibili e richiede un riscatto per fornire la chiave di decrittazione e rimuovere la limitazione","wrong1":"tentativo di far abboccare un soggetto al fine di fargli rivelare informazioni riservate: aggressione della sfera patrimoniale altrui mediante lo sfruttamento di tecniche informatiche","wrong2":"attacchi distribuiti per sovraccaricare e saturare servizi, server o reti e renderli inaccessibili tramite numerose richieste e sollecitazioni che portano il sistema a disconnettersi o a spegnersi per proteggersi","wrong3":"qualsiasi circostanza, evento o azione che potrebbe danneggiare, perturbare o avere un impatto negativo di altro tipo sulla rete e sui sistemi informativi, sugli utenti di tali sistemi e altre persone"},{"id":1185,"paragraph":"Sistemi di elaborazione delle informazioni - 32) Sicurezza informatica: Cyber Risk e Cybersecurity","question":"Nel caso dell'attacco alla società Colonial Pipeline da parte del gruppo DarkSide nel 2021 l'attacco di che tipologia era:","correct":"ransomware","wrong1":"phishing","wrong2":"DDoS (Distributed Denial of Service)","wrong3":"supply chain attack"},{"id":1186,"paragraph":"Sistemi di elaborazione delle informazioni - 33) Il framework giuridico europeo in materia di Cybersecuirty","question":"Il Regolamento (UE) 2023/2841 - EUIBAs si occupa di:","correct":"misure per un livello comune elevato di cibersicurezza nelle istituzioni, negli organi e negli organismi dell'Unione","wrong1":"misure per un livello comune elevato di sicurezza delle reti e dei sistemi informativi (Network and Information Security)","wrong2":"resilienza delle entità critiche nell'Unione Europea","wrong3":"cybersecurity dei prodotti con elementi digitali"},{"id":1187,"paragraph":"Sistemi di elaborazione delle informazioni - 33) Il framework giuridico europeo in materia di Cybersecuirty","question":"La Direttiva (UE) 2022/2555 - NIS 2 non ha tra i suoi obiettivi:","correct":"delegare maggiormente agli Stati membri e a diminuire il coordinamento","wrong1":"superare i limiti della NIS1","wrong2":"rafforzare la resilienza cibernetica di infrastrutture e servizi","wrong3":"maggiore armonizzazione e coordinamento nell'approccio"},{"id":1188,"paragraph":"Sistemi di elaborazione delle informazioni - 33) Il framework giuridico europeo in materia di Cybersecuirty","question":"I due pilastri del Regolamento (UE) 2019/881Cybersecurity Act consistono in:","correct":"rafforzamento dell'Agenzia dell'UE per la cybersicurezza (ENISA) e creazione di un EU Cybersecurity Certification Framework","wrong1":"superare i limiti della NIS1 e rafforzare la resilienza cibernetica di infrastrutture e servizi","wrong2":"stabilire requisiti obbligatori di cybersecurity per tutti i prodotti con elementi digitali emigliorare la sicurezza lungo l'intero ciclo di vita del prodotto","wrong3":"rafforzare la solidarietà e capacità dell'UE di rilevare, prepararsi e rispondere a minacce informatiche significative e su vasta scala, fornendo uno scudo europeo"},{"id":1189,"paragraph":"Sistemi di elaborazione delle informazioni - 34) Intelligenza artificiale e regolazione europea: l'Artificial Intelligence Act (Regolamento UE 2024/1689)","question":"Quale tra i seguenti non rientra fra gli atti di soft law dedicati dall'Unione europea all'intelligenza artificiale:","correct":"Regulation on a framework for the free flow of non-personal data (regolamento UE 2018/1807)","wrong1":"Risoluzione recante «raccomandazioni alla Commissione concernenti norme di diritto civile sulla robotica» del Parlamento europeo, 16 febbraio 2017","wrong2":"«Libro Bianco sull'intelligenza artificiale - Un approccio europeo all'eccellenza e alla fiducia » della Commissione europea, COM(2020) 65 final, 19 febbraio 2020","wrong3":"Comunicazione «L'intelligenza artificiale per l'Europa» della Commissione europea, COM(2018) 237 final, 25 aprile 2018"},{"id":1190,"paragraph":"Sistemi di elaborazione delle informazioni - 34) Intelligenza artificiale e regolazione europea: l'Artificial Intelligence Act (Regolamento UE 2024/1689)","question":"Quali sono i livelli di rischio previsti dall'Artificial Intelligence Act:","correct":"sistemi a rischio inaccettabile; sistemi ad alto rischio; sistemi a basso rischio o rischio limitato; sistemi a rischio minimo o nullo","wrong1":"sistemi a rischio inaccettabile; sistemi ad alto rischio; sistemi a basso rischio o rischio limitato","wrong2":"sistemi a rischio inaccettabile; sistemi ad alto rischio; sistemi a rischio minimo o nullo","wrong3":"sistemi ad alto rischio; sistemi a basso rischio o rischio limitato; sistemi a rischio minimo o nullo"},{"id":1191,"paragraph":"Sistemi di elaborazione delle informazioni - 34) Intelligenza artificiale e regolazione europea: l'Artificial Intelligence Act (Regolamento UE 2024/1689)","question":"Quali sono gli strumenti più significativi previsti dall'IA Act:","correct":"umanesimo tecnologico; approccio sistematico, preventivo, proattivo e tecnico; trasparenza algoritmica, diritto alla comprensione, explainability; supervisione e sorveglianza umana","wrong1":"umanesimo tecnologico; approccio sistematico, preventivo, proattivo e tecnico; sovranità tecnologica; controllo sulla rete","wrong2":"approccio tecnocratico; approccio sistematico, preventivo, proattivo e tecnico; trasparenza algoritmica, diritto alla comprensione, explainability; supervisione e sorveglianza delle macchine.","wrong3":"approccio sistematico, preventivo, proattivo e tecnico; logica proprietaria; trasparenza algoritmica, diritto alla comprensione, explainability; autodeterminazione della macchina."},{"id":1192,"paragraph":"Sistemi di elaborazione delle informazioni - 35) Norme e strategie italiane sulla sicurezza informatica","question":"Il perimetro di sicurezza nazionale cibernetica è costituito da:","correct":"reti, sistemi informativi e servizi informatici di PPAA, enti e operatori pubblici e privati, aventi una sede nel territorio nazionale, da cui dipende l'esercizio di una funzione essenziale dello Stato, ovvero la prestazione di un servizio essenziale, dal cui malfunzionamento, interruzione, anche parziali, ovvero utilizzo improprio, possa derivare un pregiudizio per la sicurezza nazionale","wrong1":"soggetti pubblici e privati chesvolgono funzioni o servizi essenziali per il mantenimento di attività civili, sociali o economiche fondamentali per gli interessi dello Stato","wrong2":"rischio grave e imminente per la sicurezza nazionale connesso alla vulnerabilità di reti, sistemi informativi e servizi informatici.","wrong3":"reti, sistemi informativi e servizi informatici di PPAA, enti e operatori pubblici e privati, aventi sede fuori dall'Italia, da cui dipende l'esercizio di una funzione essenziale dello Stato, ovvero la prestazione di un servizio essenziale, dal cui malfunzionamento, interruzione, anche parziali, ovvero utilizzo improprio, possa derivare un pregiudizio per la sicurezza nazionale"},{"id":1193,"paragraph":"Sistemi di elaborazione delle informazioni - 35) Norme e strategie italiane sulla sicurezza informatica","question":"La legge 90/2024 in materia di cybersicurezza:","correct":"è la legge organica in materia, che pone disposizioni in materia di rafforzamento della cybersicurezza nazionale e di reati informatici","wrong1":"si tratta del recepimento della direttiva UE 2016/114 NIS","wrong2":"si tratta della legge perimetro","wrong3":"istituisce l'Agenzia per la Cybersicurezza Nazionale - ACN"},{"id":1194,"paragraph":"Sistemi di elaborazione delle informazioni - 35) Norme e strategie italiane sulla sicurezza informatica","question":"La Strategia nazionale di cybersicurezza 2022-2026 è:","correct":"uno strumento di programmazione e coordinamento redatto da ACN, approvato con d.p.c.m. dalla Presidenza del Consiglio","wrong1":"un atto normativo","wrong2":"un atto europeo","wrong3":"uno strumento di programmazione e coordinamento redatto da AgID, in collaborazione con il Garante per la protezione dei dati personali"},{"id":1195,"paragraph":"Sistemi di elaborazione delle informazioni - 36) Strategia italiana per l'intelligenza artificiale","question":"Il framework nazionale in materia di intelligenza artificiale si compone di:","correct":"Libro Bianco «L'intelligenza artificiale al servizio del cittadino» del 2018, Strategia italiana per l'intelligenza artificiale 2020, Strategia italiana per l'intelligenza artificiale 2024-2026, linee guida in materia per l'adozione dell'IA nella PA del 2025 e un disegno di legge nel 2024","wrong1":"solo un disegno di legge in materia di intelligenza artificiale 2024","wrong2":"Libro Bianco «L'intelligenza artificiale al servizio del cittadino» del 2018 e Strategia italiana per l'intelligenza artificiale 2020","wrong3":"Strategia italiana per l'intelligenza artificiale 2024-2026"},{"id":1196,"paragraph":"Sistemi di elaborazione delle informazioni - 36) Strategia italiana per l'intelligenza artificiale","question":"Le aree della Strategia italiana per l'intelligenza artificiale 2024-2026 sono:","correct":"ricerca scientifica; pubblica amministrazione; imprese; formazione","wrong1":"ricerca scientifica;pubblica amministrazione; imprese","wrong2":"ricerca scientifica;pubblica amministrazione; formazione","wrong3":"ricerca scientifica;pubblica amministrazione; imprese; infrastrutture"},{"id":1197,"paragraph":"Sistemi di elaborazione delle informazioni - 36) Strategia italiana per l'intelligenza artificiale","question":"Il disegno di legge nazionale sull'intelligenza artificiale quali organismi prevede come governance in materia:","correct":"Agenzia per l'Italia digitale (AgID) e Agenzia per la cybersicurezza nazionale (ACN)","wrong1":"Agenzia per l'Italia digitale (AgID) e Garante per la protezione dei dati personali","wrong2":"Agenzia per l'Italia digitale (AgID), Agenzia per la cybersicurezza nazionale (ACN) e Garante per la protezione dei dati personali","wrong3":"Agenzia per l'Italia digitale (AgID) e Autorità per le garanzie nelle comunicazioni (Agcom)"},{"id":1198,"paragraph":"Sistemi di elaborazione delle informazioni - 37) Artificial Intelligence, Bias e discriminazione delle PA","question":"I bias nei sistemi di intelligenza artificiale si possono definire:","correct":"pregiudizi sistematici presenti nei dati, nei modelli o nei processi umani che influenza i risultati cui perviene l'intelligenza artificiale","wrong1":"modelli di intelligenza artificiale basati su reti neurali, progettati e addestrati su grandi quantità di testo per comprendere, generare e manipolare il linguaggio naturale umano","wrong2":"impostazione deterministica if this, than that indica un funzionamento predeterminato nel programma, che prevede input e output","wrong3":"sistemi che mostrano un comportamento intelligente analizzando il proprio ambiente e compiendo azioni, con un certo grado di autonomia, per raggiungere specifici obiettivi"},{"id":1199,"paragraph":"Sistemi di elaborazione delle informazioni - 37) Artificial Intelligence, Bias e discriminazione delle PA","question":"Il caso Eric Loomis riguarda:","correct":"il caso riguarda l'impiego di un software di algoritmi predittivi, utilizzato per valutare il rischio di recidiva e pericolosità sociale","wrong1":"caso afferente all'algoritmo usato dal MIUR nella procedura di assegnazione delle sedi disponibili nei procedimenti di mobilità dei docenti nelle sedi disponibili nell'organico della scuola","wrong2":"algoritmo di sorveglianza predittiva impiegata dall'amministrazione olandese dal 2014 al fine di valutare l'attitudine a commettere frodi o abusi da parte dei beneficiari di sussidi statali","wrong3":"sistema sviluppato per automatizzare la selezione del personale: impiegava IA per fornire punteggi ai candidati"},{"id":1200,"paragraph":"Sistemi di elaborazione delle informazioni - 37) Artificial Intelligence, Bias e discriminazione delle PA","question":"I Large Language Models (LLM) sono definibili:","correct":"modelli di intelligenza artificiale basati su reti neurali, progettati e addestrati su grandi quantità di testo per comprendere, generare e manipolare il linguaggio naturale umano","wrong1":"impostazione deterministica if this, than that indica un funzionamento predeterminato nel programma, che prevede input e output","wrong2":"pregiudizi sistematici presente nei dati, nei modelli o nei processi umani che influenza i risultati cui perviene l'intelligenza artificiale","wrong3":"sistemi che mostrano un comportamento intelligente analizzando il proprio ambiente e compiendo azioni, con un certo grado di autonomia, per raggiungere specifici obiettivi"},{"id":1201,"paragraph":"Sistemi di elaborazione delle informazioni - 38) I diritti digitali dei cittadini e le responsabilità delle PA","question":"Con il concetto di cittadinanza digitale si intende:","correct":"la configurazione stessa dei diritti dei cittadini nei confronti delle istituzioni, resa possibile dalle nuove tecnologie","wrong1":"l'organizzazione delle attività delle pubbliche amministrazioni fondata sull'impiego esteso e integrato delle tecnologie dell'informazione e della comunicazione (ICT) nello svolgimento delle funzioni e nell'erogazione dei servizi","wrong2":"gli interessati cui i dati personali si riferiscono","wrong3":"divario tra chi accede, fruisce e utilizza le tecnologie informatiche e chi ne è escluso, in modo parziale o totale"},{"id":1202,"paragraph":"Sistemi di elaborazione delle informazioni - 38) I diritti digitali dei cittadini e le responsabilità delle PA","question":"L'atto normativo nazionale che prevede i diritti digitali dei cittadini è:","correct":"il d.lgs. 82/2005","wrong1":"il d.lgs. 30/2005","wrong2":"il regolamento UE 2016/679","wrong3":"la legge 633/1941"},{"id":1203,"paragraph":"Sistemi di elaborazione delle informazioni - 38) I diritti digitali dei cittadini e le responsabilità delle PA","question":"In caso di violazione degli obblighi di transizione digitale:","correct":"AgID, ove accerti le violazioni, le contesta, assegna ai trasgressori un congruo termine perentorio per conformare la condotta agli obblighi previsti e, in caso di mancata ottemperanza, irroga le sanzioni previste","wrong1":"Agcom, ove accerti le violazioni, le contesta, assegna ai trasgressori un congruo termine perentorio per conformare la condotta agli obblighi previsti e, in caso di mancata ottemperanza, irroga le sanzioni previste","wrong2":"il Garante per la protezione dei dati personali, ove accerti le violazioni, le contesta, assegna ai trasgressori un congruo termine perentorio per conformare la condotta agli obblighi previsti e, in caso di mancata ottemperanza, irroga le sanzioni previste","wrong3":"non comporta alcuna conseguenza"},{"id":1204,"paragraph":"Sistemi di elaborazione delle informazioni - 39) La Governance in materia di Cybersecurity","question":"La governance in materia di cybersecurity è:","correct":"multilivello europea e nazionale","wrong1":"inizialmente multilivello europea e nazionale, ma attualmente solo europea per esigenze di uniformazione","wrong2":"solo nazionale","wrong3":"solo europea"},{"id":1205,"paragraph":"Sistemi di elaborazione delle informazioni - 39) La Governance in materia di Cybersecurity","question":"Tra i diversi organismi a livello europeo qual è il polo permanente strategico e operativo dell'UE:","correct":"European Union Agency for Cybersecurity (ENISA)","wrong1":"EU CSIRTs Network","wrong2":"EU CyCLONe","wrong3":"Commissione europea"},{"id":1206,"paragraph":"Sistemi di elaborazione delle informazioni - 39) La Governance in materia di Cybersecurity","question":"In Italia il punto unico di contatto nazionale è:","correct":"Agenzia per la Cybersicurezza Nazionale – ACN","wrong1":"Presidenza del Consiglio dei Ministri","wrong2":"Computer Security Incident Response Team - CSIRT Italia","wrong3":"Comitato interministeriale per la cybersicurezza (CIC)"},{"id":1207,"paragraph":"Sistemi di elaborazione delle informazioni - 40) Cyberwar e Cyberweapons: la guerra cibernetica","question":"Con cyberwar si intende:","correct":"conflitto tra Stati (o attori statali e non) nel dominio cibernetico, in cui operazioni digitali offensive sono utilizzate per ottenere vantaggi militari, politici o strategici","wrong1":"tattiche, tecniche e procedure di uso militare del cyberspazio","wrong2":"strumento software, hardware o combinazioni di entrambi, progettati o adattati per danneggiare, interrompere, degradare o distruggere sistemi, reti o infrastrutture, con un impatto paragonabile a quello di armi convenzionali in contesti militari o strategici","wrong3":"conflitto tra Stati (o attori statali e non) nel dominio marittimo per ottenere vantaggi militari, politici o strategici"},{"id":1208,"paragraph":"Sistemi di elaborazione delle informazioni - 40) Cyberwar e Cyberweapons: la guerra cibernetica","question":"Cyberweapons significa:","correct":"strumenti software, hardware o combinazioni di entrambi, progettati o adattati per danneggiare, interrompere, degradare o distruggere sistemi, reti o infrastrutture, con un impatto paragonabile a quello di armi convenzionali in contesti militari o strategici","wrong1":"tattiche, tecniche e procedure di uso militare del cyberspazio","wrong2":"conflitti tra Stati (o attori statali e non) nel dominio cibernetico, in cui operazioni digitali offensive sono utilizzate per ottenere vantaggi militari, politici o strategici","wrong3":"combattenti che conducono operazioni offensive o difensive nel dominio cibernetico, facendo uso di armi cibernetiche nonché di altre tecniche"},{"id":1209,"paragraph":"Sistemi di elaborazione delle informazioni - 40) Cyberwar e Cyberweapons: la guerra cibernetica","question":"Il cyberwarrior è:","correct":"combattente che conduce operazioni offensive o difensive nel dominio cibernetico, facendo uso di armi cibernetiche nonché di altre tecniche","wrong1":"strumento software, hardware o combinazioni di entrambi, progettati o adattati per danneggiare, interrompere, degradare o distruggere sistemi, reti o infrastrutture, con un impatto paragonabile a quello di armi convenzionali in contesti militari o strategici","wrong2":"tattiche, tecniche e procedure di uso militare del cyberspazio","wrong3":"conflitto tra Stati (o attori statali e non) nel dominio cibernetico, in cui operazioni digitali offensive sono utilizzate per ottenere vantaggi militari, politici o strategici"},{"id":1210,"paragraph":"Sistemi di elaborazione delle informazioni - 41) Intelligenza artificiale generativa: ChatGPT tra opportunità, rischi e \"allucinazioni\"","question":"L'intelligenza artificiale generativa si riferisce a:","correct":"tipologia avanzata di intelligenza artificiale basata su modelli di deep learning, in grado di apprendere dai dati sui cui è stata addestrata e di generare nuovi contenuti originali su richiesta","wrong1":"insieme delle istruzioni, codificate in un linguaggio formale leggibile da una macchina, che consente a un sistema informatico di eseguire specifiche operazioni o compiti","wrong2":"tecnica di interazione con modelli di IA generativa, appartenente al prompt engineering, finalizzata a ottenere risposte affidabili e giuridicamente corrette, mediante la formulazione precisa di istruzioni (prompt), la contestualizzazione di norme, clausole e casi, e l'uso di fonti normative certe per mitigare il rischio di errori o allucinazioni","wrong3":"sistemi che mostrano un comportamento intelligente analizzando il proprio ambiente e compiendo azioni, con un certo grado di autonomia, per raggiungere specifici obiettivi"},{"id":1211,"paragraph":"Sistemi di elaborazione delle informazioni - 41) Intelligenza artificiale generativa: ChatGPT tra opportunità, rischi e \"allucinazioni\"","question":"Tra le tipologie di modelli di intelligenza artificiale generativa non rientra:","correct":"modelli discriminativi","wrong1":"modelli di testo","wrong2":"modelli audio e video","wrong3":"modelli multimodali"},{"id":1212,"paragraph":"Sistemi di elaborazione delle informazioni - 41) Intelligenza artificiale generativa: ChatGPT tra opportunità, rischi e \"allucinazioni\"","question":"Il Tribunale delle Imprese di Firenze nella ordinanza n. 11053/2024 del 14 marzo 2025 cosa ha sostenuto riguardo all'uso di ChatGPT e alle relative allucinazioni portate in processo:","correct":"assenza di malafede, in quanto solo diretta a rafforzare un apparato difensivo già noto","wrong1":"presenza di malafede della parte che se ne è servita","wrong2":"responsabilità aggravata della parte che se ne è servita","wrong3":"applicazione dell'art. 96 c.p.c. alla parte che se ne è servita"},{"id":1213,"paragraph":"Sistemi di elaborazione delle informazioni - 42) Open Data: caratteristiche, finalità e profili giuridici, tecnici ed economici","question":"Con il termine open government si intende:","correct":"governi e amministrazioni devono essere trasparenti a tutti i livelli e le loro attività aperte e disponibili per favorire così azioni efficaci e garantire un controllo pubblico del proprio operato mediante le nuove tecnologie","wrong1":"i dati resi disponibili con le caratteristiche tecniche e legali necessarie per essere liberamente utilizzati, riutilizzati e ridistribuiti da chiunque, in qualsiasi momento e ovunque","wrong2":"l'adozione estesa e integrata delle tecnologie informatiche nello svolgimento delle funzioni e nell'erogazione dei servizi della pubblica amministrazione","wrong3":"governi e amministrazioni non devono essere trasparenti e le loro attività non possono essere aperte e disponibili al fine di evitare un controllo pubblico generalizzato del proprio operato"},{"id":1214,"paragraph":"Sistemi di elaborazione delle informazioni - 42) Open Data: caratteristiche, finalità e profili giuridici, tecnici ed economici","question":"La classificazione di Tim Berners-Lee in merito al grado di apertura quante \"stelle\" ossia livelli prevede:","correct":"classificazione a 5 stelle","wrong1":"classificazione a 2 stelle","wrong2":"classificazione a 4 stelle","wrong3":"classificazione a 3 stelle"},{"id":1215,"paragraph":"Sistemi di elaborazione delle informazioni - 42) Open Data: caratteristiche, finalità e profili giuridici, tecnici ed economici","question":"Le finalità perseguite con gli open data sono:","correct":"sviluppo economico; maggiore trasparenza e controllo democratico; miglioramento della qualità di vità dei cittadini","wrong1":"solo lo sviluppo economico","wrong2":"maggiore controllo sui dati da parte delle amministrazioni e freno al riutilizzo","wrong3":"solo trasparenza"},{"id":1216,"paragraph":"Sistemi di elaborazione delle informazioni - 43) Open Data: norme, strategie e iniziative","question":"Il principio open data by default cosa significa:","correct":"i dati e i documenti che le amministrazioni titolari pubblicano, con qualsiasi modalità, senza l'espressa adozione di una licenza si intendono rilasciati come dati di tipo aperto, ad eccezione dei casi in cui la pubblicazione riguardi dati personali","wrong1":"i dati e i documenti che le amministrazioni titolari pubblicano, con qualsiasi modalità, senza l'espressa adozione di una licenza si intendono rilasciati come dati di tipo chiuso e non possono essere riutilizzati","wrong2":"governi e amministrazioni non devono essere trasparenti e le loro attività non possono essere aperte e disponibili al fine di evitare un controllo pubblico generalizzato del proprio operato","wrong3":"l'adozione estesa e integrata delle tecnologie informatiche nello svolgimento delle funzioni e nell'erogazione dei servizi della pubblica amministrazione"},{"id":1217,"paragraph":"Sistemi di elaborazione delle informazioni - 43) Open Data: norme, strategie e iniziative","question":"Esiste un portale europeo di open data:","correct":"sì","wrong1":"no","wrong2":"esistono solo il portale nazionale e quelli territoriali","wrong3":"non esiste più"},{"id":1218,"paragraph":"Sistemi di elaborazione delle informazioni - 43) Open Data: norme, strategie e iniziative","question":"Quale tra i seguenti non è un aspetto problematico degli open data:","correct":"garantire il libero riutilizzo","wrong1":"resistenze culturali e scarsa consapevolezza","wrong2":"motivazioni economiche","wrong3":"limitazioni di ordine giuridico"},{"id":1219,"paragraph":"Sistemi di elaborazione delle informazioni - 44) Governo dei dati e degli algoritmi: i Big Data (caratteristiche, finalità e valore)","question":"Cosa si intende per data society:","correct":"la società contemporanea non è soltanto fondata sui dati come nel suo avvento, ma ne è intimamente pervasa fino a coinvolgere e plasmare l'uomo stesso come un data subject","wrong1":"un'impresa o azienda privata che si avvale di open data","wrong2":"governi e amministrazioni non devono essere trasparenti e le loro attività non possono essere aperte e disponibili al fine di evitare un controllo pubblico generalizzato del proprio operato","wrong3":"l'adozione estesa e integrata delle tecnologie informatiche nello svolgimento delle funzioni e nell'erogazione dei servizi della pubblica amministrazione"},{"id":1220,"paragraph":"Sistemi di elaborazione delle informazioni - 44) Governo dei dati e degli algoritmi: i Big Data (caratteristiche, finalità e valore)","question":"I big data consistono in:","correct":"enormi volumi di dati detenuti da grandi organizzazioni (governi, colossi tecnologici) provenienti da diverse fonti e analizzati per mezzo di algoritmi e tecniche specifiche","wrong1":"i dati resi disponibili con le caratteristiche tecniche e legali necessarie per essere liberamente utilizzati, riutilizzati e ridistribuiti da chiunque, in qualsiasi momento e ovunque","wrong2":"i dati detenuti da piccole organizzazioni provenienti da diverse fonti e analizzati per mezzo di software tradizionali","wrong3":"i dati protetti con le caratteristiche tecniche e legali necessarie per evitare il libero riuso e il riutilizzo"},{"id":1221,"paragraph":"Sistemi di elaborazione delle informazioni - 44) Governo dei dati e degli algoritmi: i Big Data (caratteristiche, finalità e valore)","question":"Quale tra le seguenti non fa parte delle caratteristiche dei big data secondo il paradigma delle V:","correct":"visibilità","wrong1":"velocità","wrong2":"volume","wrong3":"varietà"},{"id":1222,"paragraph":"Sistemi di elaborazione delle informazioni - 45) Big Data: profili giuridici, etici e sociali","question":"Cosa di intende con big data divide:","correct":"l'asimmetria tra pochi \"signori\" dei dati (colossi digitali e poteri pubblici), che raccolgono ed elaborano big data, e gli altri soggetti","wrong1":"il divario tra Stati che usano i big data e quelli che non li usano","wrong2":"è sinonimo di alfabetizzazione informatica","wrong3":"il divario tra chi utilizza le tecnologie e chi ne è escluso in tutto o in parte"},{"id":1223,"paragraph":"Sistemi di elaborazione delle informazioni - 45) Big Data: profili giuridici, etici e sociali","question":"Quale tra le seguenti non è una prospettiva ricostruttiva in merito all'aspetto di ownership dei big data:","correct":"protezione dei dati personali","wrong1":"proprietà tradizionale","wrong2":"prospettiva contrattuale","wrong3":"proprietà intellettuale"},{"id":1224,"paragraph":"Sistemi di elaborazione delle informazioni - 45) Big Data: profili giuridici, etici e sociali","question":"Quale tra i seguenti aspetti della disciplina in materia di protezione dei dati personali non crea peculiari problematiche per quanto attiene ai big data:","correct":"la figura dell'interessato","wrong1":"rispetto dei principi applicabili al trattamento","wrong2":"informazioni e consenso","wrong3":"la definizione stessa di dato personale"},{"id":1225,"paragraph":"Sistemi di elaborazione delle informazioni - 46) Framework di riferimento e strumenti di governance","question":"Il Data Governance Act è:","correct":"un regolamento europeo","wrong1":"una norma nazionale","wrong2":"una risoluzione del Parlamento europeo","wrong3":"un atto del Garante per la protezione dei dati personali"},{"id":1226,"paragraph":"Sistemi di elaborazione delle informazioni - 46) Framework di riferimento e strumenti di governance","question":"Il quadro normativo europeo sulla dimensione digitale mira a:","correct":"una disciplina complessivamente sostenibile e, a tal fine, tesa a garantire allo stesso tempo prevedibilità e certezza del diritto, ma anche flessibilità e adattabilità all'evoluzione e ai cambiamenti della tecnologia","wrong1":"garantire maggior controllo sui dati e affermare una prospettiva proprietaria al riguardo, fondata sulla chiusura dei dati","wrong2":"garantire esclusivamente prevedibilità e certezza del diritto","wrong3":"garantire esclusivamente flessibilità e adattabilità all'evoluzione e ai cambiamenti della tecnologia"},{"id":1227,"paragraph":"Sistemi di elaborazione delle informazioni - 46) Framework di riferimento e strumenti di governance","question":"Quale tra i seguenti non rientra tra gli strumenti di governance e gli scenari futuri in materia di data governance:","correct":"maggior controllo dei dati e chiusura degli stessi","wrong1":"data ethics e centralità della persona","wrong2":"apertura e diritto al riutilizzo - open & big data","wrong3":"trasparenza algoritmica e diritto alla comprensione"},{"id":1228,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"L'assunzione nelle amministrazioni pubbliche avviene:","correct":"mediante procedure selettive, oppure mediante l'avviamento degli iscritti alle liste di collocamento","wrong1":"mediante procedure selettive","wrong2":"mediante il solo l'avviamento degli iscritti alle liste di collocamento","wrong3":"secondo le modalità di assunzione alle dipendenze di soggetti privati"},{"id":1229,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"Chi può accedere alle procedure concorsuali:","correct":"coloro che posseggono i requisiti generali, di cui all'art. 2 D.P.R. 487/1994","wrong1":"chiunque","wrong2":"i soli soggetti appartenenti a categorie protette","wrong3":"coloro che parlino la sola lingua italiana"},{"id":1230,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"Le Pubbliche Amministrazioni assumono:","correct":"con contratti di lavoro a tempo indeterminato; con contratti di lavoro a tempo determinato o tipologie contrattuali flessibili, per comprovate esigenze di carattere temporaneo o eccezionale; con attribuzione di incarichi individuali esterni","wrong1":"esclusivamente con contratti di lavoro subordinato a tempo indeterminato","wrong2":"esclusivamente con contratti di lavoro a tempo determinato o tipologie contrattuali flessibili disciplinate dal codice civile","wrong3":"può ricorrere alla sola attribuzione di incarichi individuali esterni"},{"id":1231,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"La disciplina delle mansioni nel pubblico impiego:","correct":"ricade sotto la sfera di applicazione del d.lgs. 165/2001, art. 52","wrong1":"è anch'essa dettata dall'art. 2013 c.c","wrong2":"è rimessa alla contrattazione collettiva nazionale","wrong3":"non vi è alcuna specifica disciplina"},{"id":1232,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"Per assegnazione temporanea si intendela possibilità per il prestatore di lavoro di:","correct":"essere temporaneamente adibito a mansioni proprie della qualifica immediatamente superiore nel caso di vacanza di posto in organico o nel caso di sostituzione di altro dipendente assente","wrong1":"essere adibito temporaneamente alle mansioni per le quali è stato assunto","wrong2":"essere adibito a mansioni equivalenti nell'ambito dell'area di inquadramento","wrong3":"essere adibito a mansioni corrispondenti alla qualifica superiore successivamente acquisite per effetto di procedure selettive"},{"id":1233,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"Tra modificazioni che possono interessare il rapporto lavorativo del pubblico dipendente, per distacco si intende:","correct":"ipotesi di trasferimento della sede di servizio presso un ente diverso dalle pubbliche amministrazioni","wrong1":"l'ipotesi in cui il dipendente viene chiamato a prestare temporaneamente servizio presso una Amministrazione Statale diversa da quella d'appartenenza","wrong2":"ipotesi di disimpegno di funzioni dello Stato o di altri Enti Pubblici che perseguono gli stessi interessi perseguiti dell'amministrazione che lo dispone","wrong3":"ipotesi in cui le pubbliche amministrazioni favoriscono e incentivano le esperienze del proprio personale all'estero"},{"id":1234,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"Per mobilità volontaria si intende:","correct":"il passaggio di singoli dipendenti, che ne facciano richiesta, da un'amministrazione ad un'altra","wrong1":"nel caso in cui contratti di lavoro dei dipendenti in soprannumero verranno risolti unilateralmente dall'amministrazione datrice o si verificheranno possibilità di ricollocazione","wrong2":"il passaggio di singoli dipendenti da un'amministrazione ad un'altra, su accordo delle amministrazioni interessate","wrong3":"il passaggio di singoli dipendenti, che ne facciano richiesta, presso un'instituzione europea"},{"id":1235,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"La responsabilità disciplinare del pubblico dipendente discende:","correct":"da un'azione od omissione, compiuta in violazione di legge, regolamento o contratto e dei doveri previsti da quest'ultimo","wrong1":"dalla trasgressione dei doveri di ufficio da parte dell'impiegato che assume il carattere di violazione dell'ordine giuridico generale e si concreta nella figura del reato","wrong2":"dalla trasgressione dei doveri d'ufficio che arrechino un danno patrimoniale per l'ente pubblico","wrong3":"dal mancato rispetto degli orari lavorativi"},{"id":1236,"paragraph":"Diritto del lavoro e pubblico impiego - 1) L'accesso al pubblico impiego","question":"L'estinzione del rapporto di lavoro può avvenire:","correct":"per collocamento a riposo del dipendente pubblico; per licenziamento disciplinare o per inidoneità permanente psicofisica al servizio","wrong1":"per decesso del pubblico impiegato","wrong2":"nella sola ipotesi di licenziamento disciplinare","wrong3":"per collocamento a riposo del dipendente pubblico"},{"id":1237,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Qual è il numero massimo delle proroghe del contratto a tempo determinato:","correct":"quattro","wrong1":"otto","wrong2":"cinque","wrong3":"venti"},{"id":1238,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"In che misura un'azienda può assumere lavoratori a tempo determinato:","correct":"al 20%","wrong1":"al 100%","wrong2":"al 75%","wrong3":"al 99%"},{"id":1239,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Il lavoratore a tempo determinato può essere licenziato prima della scadenza del termine:","correct":"no, se non per giusta causa cioè per un fatto così grave da rendere impossibile la prosecuzione del rapporto di lavoro","wrong1":"no, mai","wrong2":"si, in ogni caso","wrong3":"si, solo se il contratto ha durata inferiore a 1 mese"},{"id":1240,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Qual è il termine per l'impugnazione del contratto a tempo determinato:","correct":"centottanta giorni","wrong1":"sessanta giorni","wrong2":"tre anni","wrong3":"centoventi giorni"},{"id":1241,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Qual è la durata masima del contratto di lavoro a termine:","correct":"ventiquattro mesi","wrong1":"trentasei mesi","wrong2":"8 anni","wrong3":"sei mesi"},{"id":1242,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Il contratto a tempo determinato si considera a tempo indeterminato dopo quale proroga:","correct":"la quinta","wrong1":"la sesta","wrong2":"la ventesima","wrong3":"la seconda"},{"id":1243,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Può essere stipulato un contratto di lavoro a tempo determinato per sostiture lavoratori in sciopero:","correct":"no, non si può assumere per tale causale","wrong1":"si, lo prevede la legge","wrong2":"si, solo per 2 ore","wrong3":"si, solo se lo sciperoo dura più di 5 ore"},{"id":1244,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Il lavoratore a tempo determinato può dimettersi:","correct":"per giusta causa","wrong1":"in casi del tutto particolari","wrong2":"no","wrong3":"con il consenso del sindacato"},{"id":1245,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Il contratto a tempo determinato può essere orale:","correct":"no, assolutamente","wrong1":"si, quando è previsto dalla legge","wrong2":"si, se per il datore di lavoro è più comodo","wrong3":"si, quando ci sono tre testimoni"},{"id":1246,"paragraph":"Diritto del lavoro e pubblico impiego - 2) Il contratto a tempo indeterminato","question":"Il contratto di lavoro a tempo determinato può essere prorogato dopo 12 mesi:","correct":"si, solo in presenza di determinate causali","wrong1":"no, assolutamente","wrong2":"si, anche quando non c'è una causale","wrong3":"solo per i contratti di lavoro che hanno una durata inferiore a sei mesi"},{"id":1247,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"Il rapporto di lavoro alle dipendenze del somministratore è:","correct":"un sottotipo del rapporto di lavoro, definito dall'art. 2094 c.c.","wrong1":"un rapporto speciale di lavoro","wrong2":"un rapporto di lavoro autonomo","wrong3":"un rapporto di lavoro parasubordinato"},{"id":1248,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"Il rapporto di lavoro alle dipendenze del somministratore:","correct":"può essere sia a tempo determinato sia a tempo indeterminato","wrong1":"può essere solo a tempo determinato","wrong2":"può essere solo a tempo indeterminato","wrong3":"non può essere nè a tempo determinato, né a tempo indeterminato"},{"id":1249,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"Nella somministrazione di lavoro:","correct":"il Datore sostanziale è l'utilizzatore","wrong1":"il lavoratore non è computato nell'organico dell'utilizzatore ai fini dell'applicazione di normative di legge e di contratto collettivo","wrong2":"il Datore sostanziale è il somministratore","wrong3":"il Datore formale è l'utilizzatore"},{"id":1250,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"Nella somministrazione di lavoro:","correct":"il potere direttivo e il potere di controllo spettano all'utilizzatore","wrong1":"lo ius variandi spetta al somministratore","wrong2":"il potere disciplinare spetta all'utilizzatore","wrong3":"il potere di recesso spetta all'utilizzatore"},{"id":1251,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"I lavoratori dipendenti dal somministratore hanno diritto ad un trattamento economico e normativo:","correct":"complessivamente non inferiore a quello dei dipendenti dell'utilizzatore","wrong1":"inferiore a quello dei dipendenti dell'utilizzatore","wrong2":"superiore a quello dei dipendenti dell'utilizzatore","wrong3":"del tutto svincolato da quello dei dipendenti dell'utilizzatore"},{"id":1252,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"L'utilizzatore risponde verso il prestatore di lavoro:","correct":"solidalmente con il somministratore dei trattamenti retributivi e dei contributi previdenziali dovuti","wrong1":"dei trattamenti retributivi e dei contributi previdenziali, nei limiti di quanto dovuto al somministratore","wrong2":"solidalmente con il somministratore dei soli trattamenti retributivi","wrong3":"solidalmente con il somministratore dei soli contributi previdenziali"},{"id":1253,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"La somministrazione irregolare è un'ipotesi di somministrazione:","correct":"che non rispetta i requisiti ed i limiti fissati dalla legge","wrong1":"posta in essere con la specifica finalità di eludere norme inderogabili di legge o di contratto collettivo applicato al lavoratore","wrong2":"lecita","wrong3":"per la quale non sono versati i contributi previdenziali"},{"id":1254,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"In caso di somministrazione irregolare:","correct":"il lavoratore può chiedere la costituzione di un rapporto di lavoro alle dipendenze dell'utilizzatore","wrong1":"il lavoratore ha diritto al solo risarcimento del danno","wrong2":"viene costituito un rapporto di lavoro a tempo indeterminato alle dipendenze del somministratore","wrong3":"viene costituito un rapporto di lavoro a tempo indeterminato alle dipendenze dell'utilizzatore"},{"id":1255,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"In caso di somministrazione irregolare, la costituzione di un rapporto di lavoro può essere richiesta:","correct":"solo dopo il decorso dei termini di 60 giorni e di 180giorni previsti in materia di impugnazione dei licenziamenti individuali","wrong1":"in ogni tempo","wrong2":"nel rispetto del regime delle decadenze previste per l'impugnazione dei licenziamenti individuali","wrong3":"solo dopo che il lavoratore sia stato licenziato"},{"id":1256,"paragraph":"Diritto del lavoro e pubblico impiego - 3) La somministrazione di lavoro: disciplina e sanzioni","question":"La somministrazione di lavoro è fraudolenta quando:","correct":"è posta in essere con la specifica finalità di eludere norme inderogabili di legge o di contratto collettivo applicato al lavoratore","wrong1":"non rispetta i requisiti ed i limiti fissati dalla legge","wrong2":"è carente della forma scritta","wrong3":"è posta in esser da un soggetto diverso dall'agenzia di somministrazione"},{"id":1257,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"La somministrazione di lavoro:","correct":"è una forma di interposizione lecita, perché autorizzata","wrong1":"è una forma di appalto","wrong2":"è una forma di appalto illecita","wrong3":"è una forma di accentramento produttivo"},{"id":1258,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Il somministratore è:","correct":"l'agenzia di somministrazione di lavoro debitamente autorizzata","wrong1":"un appaltatore","wrong2":"l'impresa che utilizza le prestazioni di lavoro","wrong3":"un lavoratore dipendente"},{"id":1259,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Per tutta la durata della somministrazione i lavoratori:","correct":"svolgono la propria attività nell'interesse nonché sotto la direzione e il controllo dell'utilizzatore","wrong1":"svolgono la propria attività nell'interesse nonché sotto la direzione e il controllo del somministratore","wrong2":"sono assunti direttamente dall'utilizzatore","wrong3":"non svolgono alcuna attività lavorativa"},{"id":1260,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Il contratto di somministrazione è il contratto con il quale il somministratore:","correct":"si obbliga a fornire all'utilizzatore prestazioni di lavoro subordinato","wrong1":"assume con organizzazione dei mezzi necessari e gestione a proprio rischio il compimento di un'opera o di un servizio","wrong2":"cede definitivamente all'utilizzatore dei contratti di lavoro","wrong3":"cede all'utilizzatore un ramo di azienda"},{"id":1261,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Il contratto di somministrazione di lavoro può essere concluso:","correct":"a termine o a tempo indeterminato","wrong1":"solo a termine","wrong2":"solo a tempo indeterminato","wrong3":"in forma orale"},{"id":1262,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"La somministrazione di lavoro a tempo indeterminato:","correct":"è tassativamente vietata per la P.A.","wrong1":"è previsto l'utilizzo sia per la P.A. sia per i privati","wrong2":"è prevista solo per il settore dell'industria","wrong3":"è prevista solo per un numero minimo di 6 contratti sottoscritti"},{"id":1263,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"La somministrazione di lavoro:","correct":"coinvolge tre soggetti","wrong1":"coinvolge due soggetti","wrong2":"può coinvolgere un numero indeterminato di soggetti","wrong3":"coinvolge un soggetto"},{"id":1264,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Il contratto di somministrazione:","correct":"richiede l'obbligo di forma scritta","wrong1":"richiede l'obbligo della forma verbale","wrong2":"non richiede né la forma scritta né quella verbale","wrong3":"richiede ai soli fini della prova, la forma scritta"},{"id":1265,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Per lo svolgimento dell'attività di somministrazione di lavoro:","correct":"è necessario il rispetto di specifici requisiti giuridici e finanziari","wrong1":"è necessaria l'autorizzazione del Presidente della Repubblica","wrong2":"è necessaria l'autorizzazione del Presidente della Giunta Regionale","wrong3":"è necessario avere la forma di impresa familiare"},{"id":1266,"paragraph":"Diritto del lavoro e pubblico impiego - 4) La somministrazione di lavoro: nozione e condizioni di liceità","question":"Il contratto di somministrazione:","correct":"deve contenere indicazioni obbligatorie sui soggetti e l'oggetto del contratto di somministrazione","wrong1":"deve essere stipulato davanti ad un notaio","wrong2":"deve contenere clausole finalizzate a limitare la facoltà dell'utilizzatore di assumere il lavoratore al termine del contratto di somministrazione","wrong3":"deve essere stipulato davanti a 2 testimoni"},{"id":1267,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"L'appalto è il contratto con il quale una parte:","correct":"Assume, con organizzazione di mezzi necessari, e con gestione a proprio rischio, il compimento di un'opera o di un servizio verso un corrispettivo in danaro","wrong1":"Assume, con organizzazione di mezzi necessari, ma senza gestione a proprio rischio, il compimento di un'opera o di un servizio verso un corrispettivo in danaro","wrong2":"Si limita ad assumere e retribuire i lavoratori, mettendoli a disposizione di un altro imprenditore","wrong3":"Cede all'altra il complesso dei beni organizzato per l'esercizio dell'impresa"},{"id":1268,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"L'appalto si distingue dalla somministrazione perché:","correct":"È caratterizzato dall'effettiva sussistenza dei requisiti della organizzazione dei mezzi necessari e della gestione a proprio rischio","wrong1":"Nell'appalto il potere organizzativo e direttivo verso i lavoratori è esercitato dal committente","wrong2":"E' caratterizzato dalla mancanza dei requisiti della organizzazione dei mezzi necessari e della gestione a prorio rischio","wrong3":"L'appaltatore non è un vero imprenditore"},{"id":1269,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"In caso di appalto privo di requisiti il lavoratore può chiedere:","correct":"La costituzione di un rapporto di lavoro alle dipendenze dell'utilizzatore","wrong1":"Il solo risarcimento del danno","wrong2":"La costituzione di un rapporto di lavoro a tempo indeterminato alle dipendenze dell'appaltatore","wrong3":"Il trasferimento ad altra unità produttiva dell'appaltatore"},{"id":1270,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"Nel caso di cessione del ramo di azienda:","correct":"La successione nell'appalto integra il trasferimento di azienda","wrong1":"Cessa definitivamente il contratto di appalto","wrong2":"Il lavoratore può chiedere la costituzione di un rapporto di lavoro alle dipendenze dell'utilizzatore","wrong3":"Il lavoratore ha diritto a un trattamento economico equivalente a quello spettante ai dipendenti del committente"},{"id":1271,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"L'azione di cui all'art. 1676 c.c.:","correct":"È diretta solo nei confronti del committente","wrong1":"E' esperibile sia nei confronti del committente, sia nei confronti dell'appaltatore","wrong2":"E' diretta nei confronti del solo appaltatore","wrong3":"Può essere esperita anche dai dai dipendenti del committente"},{"id":1272,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"L'azione di responsabilità di cui all'art. 29 d.lgs. 276/2003:","correct":"Prevede l'obbligo solidale di committente ed appaltatore di corrispondere trattamenti retributivi, quote di TFR, i contributi previdenziali e i premi assicurativi","wrong1":"Riconosce condizioni non niferiori a quelle risultanti dai contratti collettivi di lavoro della categoria e della zona","wrong2":"Riconosce condizioni superiori a quelle risultanti dai contratti collettivi di lavoro della categoria e della zona","wrong3":"Riconosce condizioni non inferiori a quelle spettanti ai dipendenti del committente"},{"id":1273,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"L'azione di responsabilità di cui all'art. 276/2003 è soggetta:","correct":"Alla decadenza","wrong1":"Alla prescrizione","wrong2":"Alla prescrizione e decadenza","wrong3":"A nessun termine decadenziale o prescrizionale"},{"id":1274,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"Il distacco si realizza quando un datore di lavoro:","correct":"Pone temporaneamente uno o più lavoratori a disposizione di altro soggetto per l'esecuzione di una determinata attività","wrong1":"Trasferisce temporaneamente uno o più lavoratori da un'unità produttiva ad un'altra all'interno della sua azienda","wrong2":"Pone definitivamente uno o più lavoratori a disposizione di altro soggetto per l'esecuzione di una determinata attività","wrong3":"Assume con organizzazione dei mezzi necessari e con gestione a proprio rischio, il compimento di un'opera o di un servizio verso un corrispettivo in danaro"},{"id":1275,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"In generale, il distacco può dirsi lecito quando:","correct":"È temporaneo e risponde ad un interesse del datore di lavoro","wrong1":"Vi è il consenso del lavoratore","wrong2":"Sussistono comprovate ragioni tecniche, organizzative, produttive o sostitutive","wrong3":"E' temporaneo, anche se non risponde ad un interesse del datore di lavoro distaccante"},{"id":1276,"paragraph":"Diritto del lavoro e pubblico impiego - 5) Appalto e distacco","question":"Il distacco che comporti un trasferimento ad un'unità produttiva sita a più di 50 Km da quella in cui il lavoratore è adibito può avvenire:","correct":"Soltanto per comprovate ragioni tecniche, organizzative, produttive o sostitutive","wrong1":"Solo con il consenso del lavoratore","wrong2":"Se è temporaneo e risponde ad un interesse del datore di lavoro distaccante, anche se sussistono comprovate ragioni tecniche, organizzative, produttive o sostitutive","wrong3":"Soltanto per comprovate ragioni tecniche, organizzative, produttive o sostitutive e comunque con il consenso del lavoratore"},{"id":1277,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"La contrattazione collettiva nel settore pubblico è disciplinata:","correct":"dall'art. 40 del d.lgs. 165/2001, come modificato dal d.lgs. 75/2017","wrong1":"dall'art. 45, comma 2^, d.lgs. 165/2001","wrong2":"dall'art. 97 Cost.","wrong3":"non trova alcuna specifica disciplina legislativa"},{"id":1278,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"Il sistema della contrattazione nel nostro ordinamento è composto:","correct":"dalla contrattazione collettiva nazionale di comparto e dalla contrattazione collettiva integrativa o decentrata","wrong1":"dalla sola contrattazione collettiva nazionale di comparto","wrong2":"dalla sola contrattazione collettiva integrativa o decentrata","wrong3":"dalla contrattazione collettiva nazionale di comparto e dalla contrattazione collettiva internazionale"},{"id":1279,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"La contrattazione collettiva nazionale di comparto:","correct":"disciplina i singoli comparti del pubblico impiego","wrong1":"è posta a livello di singola amministrazione","wrong2":"disciplina il rapposrto di lavoro dei pubblici dipendenti","wrong3":"concerne l'organizzazione dei singoli uffici"},{"id":1280,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"Chi detiene la rappresentanza dei lavoratori nella stipula dei contratti collettivi nazionali:","correct":"le organizzazioni sindacali","wrong1":"dall'ARAN","wrong2":"le amministrazioni di appartenenza","wrong3":"non necessitano di alcuna rappresentanza"},{"id":1281,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"La rappresentanza legale delle PP. AA. è affidata:","correct":"all'ARAN","wrong1":"ad un organo di autorapppresentanza interno a ciascuna amministrazione","wrong2":"non necessitano di alcuna rappresentanza","wrong3":"alle organizzazioni sindacali"},{"id":1282,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"Di quali organi è dotato l'ARAN:","correct":"di un Presidente e di un Collegio di indirizzo e di controllo","wrong1":"del solo Collegio di indirizzo e di controllo","wrong2":"del solo Presidente","wrong3":"non è dotato di alcun organo"},{"id":1283,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"Quali sono i comparti della contrattazione collettiva nazionale:","correct":"funzioni centrali, funzioni locali, sanità, istruzione e ricerca","wrong1":"funzioni centrali, funzioni locali, sanità, istruzione e ricerca, dirigenti","wrong2":"non vi è una divisione in comparti","wrong3":"ministeri; enti pubblici non economici; regioni e autonomie locali; servizio sanitario nazionale; scuola; niversità; presidenza del onsiglio; agenzie fiscali; istituti di alta formazione e specializzazione artistica e musicale; istituzioni ed enti di ricerca e sperimentazione"},{"id":1284,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"La categoria dei dirigenti:","correct":"è confluita nelle quattro aree introdotte dalla riforma Brunetta, mediante la riformulazione del comma 2 dell'art. 40, d.lgs. 165/2001","wrong1":"è suddivisa in otto aree corrispondenti ad analoghi comparti di contrattazione o raggruppamenti","wrong2":"non è corredata di suddivisioni in aree","wrong3":"è suddivisa in due aree corrispondenti ad analoghi comparti di contrattazione"},{"id":1285,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"In quale area sono confluiti ministeri; enti pubblici non economici:","correct":"funzioni centrali","wrong1":"funzioni locali","wrong2":"sanità","wrong3":"istruzione e ricerca"},{"id":1286,"paragraph":"Diritto del lavoro e pubblico impiego - 6) La contrattazione collettiva","question":"In quale area sono confluite regioni ed autonomie locali:","correct":"funzioni locali","wrong1":"sanità","wrong2":"istruzione e ricerca","wrong3":"funzioni centrali"},{"id":1287,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"La possibilità di stipulare contratti di durata inferiore a dodici mesi è subordinata:","correct":"a nessuna condizione","wrong1":"alla compresenza di esigenze temporanee e oggettive, estranee all'ordinaria attività; esigenze di sostituzione di altri lavoratori;esigenze connesse a incrementi temporanei, significativi e non programmabili, dell'attività ordinaria","wrong2":"alla presenza esclusiva di esigenze di sostituzione di altri lavoratori","wrong3":"alla presenza di solo una tra le seguenti condizioni: di esigenze temporanee e oggettive, estranee all'ordinaria attività; esigenze di sostituzione di altri lavoratori;esigenze connesse a incrementi temporanei, significativi e non programmabili, dell'attività ordinaria"},{"id":1288,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"L'indicazione della causale per relationem, all'indomani del d.lgs. N. 81/2015 è:","correct":"consentita","wrong1":"vietata","wrong2":"consentita in ipotesi tassative indicate nei ccnl","wrong3":"consentita nelle ipotesi tassative indicate nei contratti aziendali"},{"id":1289,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"La disciplina del contratto a tempo determinato nel pubblico impiego:","correct":"continuano ad applicarsi le norme di cui agli artt. 19 e ss. d.lgs. 15 giugno 2015, n. 81","wrong1":"è stata interamente oggetto di modificazione da parte del Decreto Dignità","wrong2":"è rimessa alla contrattazione collettiva","wrong3":"i pubblici impiegati non possono essere assunti con contratto a termine"},{"id":1290,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"Per il contratto a termine è richiesta la sussistenza delle causali in caso di:","correct":"stipulazione di un contratto a termine di durata superiore a dodici mesi","wrong1":"stipulazione di un contratto a termine di durata inferiore ai dodici mesi","wrong2":"mai","wrong3":"stipulazione di un contratto con termine superiore a sei mesi"},{"id":1291,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"I contratti collettivi nazionali stipulati dall'Aran:","correct":"non sono chiamati a recepire la delega ex art. 19, co. 1, lett. b-bis, d.lgs. 81/2015","wrong1":"sono chiamati a recepire la delega ex art. 19, co. 1, lett. b-bis, d.lgs. 81/2015","wrong2":"l'Aran non è competente a stipulare contratti collettivi","wrong3":"sono validi solo per i dirigenti"},{"id":1292,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"La delega alla contrattazione collettiva di cui al decreto Dignità bis:","correct":"ha natura di delega in bianco","wrong1":"le parti sociali sono vincolate nell'individuazione delle condizioni di legittima apposizione del termine","wrong2":"è limitata ai soli aspetti retributivi","wrong3":"il decreto Dignità bis non ha emendato l'art. 19 d.lgs. N. 81/2015"},{"id":1293,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"La giurisprudenza di legittimità consolidatasi sulla motivazione per relationem è venuta a delinearsi:","correct":"allorquando la disciplina applicabile ratione temporis era il d.lgs. n. 81/2015","wrong1":"allorquando la disciplina applicabile ratione temporis era il cd. Decreto Dignità","wrong2":"allorquando la disciplina applicabile ratione temporis era la l. 56/1987","wrong3":"la giurisprudenza di legittimità non ha mai emesso statuizioni sul \"termine per relationem\""},{"id":1294,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"L'aggiunta, dopo il comma 1 dell'art. 19 del d.lgs. 81/2015, del comma 1.1 ha determinato:","correct":"circoscrizione temporale degli effetti dell'emendamento al 30 settembre 2022","wrong1":"non è stato aggiunto, dopo il comma 1, art. 19, d.lgs. N. 81/2015, il comma 1.1","wrong2":"la delega, senza imporvi un limite temporale, alla contrattazione collettiva l'individuazione di nuove causali","wrong3":"l'imposizione, alla contrattazione collettiva, criteri di massima per l'idividuazione di nuove causali"},{"id":1295,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"L'indicazione della causale per relationem, all'indomani del Decreto Dignità:","correct":"è consentita limitatamente ad esigenze di carattere sostitutivo","wrong1":"non è consentita","wrong2":"è sempre consentita","wrong3":"è apponibile solo laddove previsto dalla contrattazione collettiva"},{"id":1296,"paragraph":"Diritto del lavoro e pubblico impiego - 7) Indici di genuità del contratto a termine","question":"L'aggiunta al comma 1 dell'art. 19 del d.lgs. 81/2015 la lettera b-bis ha determinato:","correct":"un cedimento della rigidità delle condizioni introdotte dal Decreto Dignità","wrong1":"il ripristino del regime della a-causalità nella disciplina del contratto a termine","wrong2":"un irrigidimento delle condizioni introdotte dal Decreto Dignità","wrong3":"la lett. b-bis non è mai stata aggiunta al co. 1 dell'art. 19 in questione"},{"id":1297,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"L'appalto è il contratto con il quale una parte:","correct":"assume, con organizzazione di mezzi necessari, e con gestione a proprio rischio, il compimento di un'opera o di un servizio verso un corrispettivo in danaro","wrong1":"assume, con organizzazione di mezzi necessari, ma senza gestione a proprio rischio, il compimento di un'opera o di un servizio verso un corrispettivo in danaro","wrong2":"si limita ad assumere e retribuire i lavoratori, mettendoli a disposizione di un altro imprenditore","wrong3":"cede all'altra il complesso dei beni organizzato per l'esercizio dell'impresa"},{"id":1298,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"L'appalto si distingue dalla somministrazione perché:","correct":"È caratterizzato dall'effettiva sussistenza dei requisiti della organizzazione dei mezzi necessari e della gestione a proprio rischio","wrong1":"nell'appalto il potere organizzativo e direttivo verso i lavoratori è esercitato dal committente","wrong2":"è caratterizzato dalla mancanza dei requisiti della organizzazione dei mezzi necessari e della gestione a prorio rischio","wrong3":"l'appaltatore non è un vero imprenditore"},{"id":1299,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"In caso di appalto privo di requisiti il lavoratore può chiedere:","correct":"La costituzione di un rapporto di lavoro alle dipendenze dell'utilizzatore","wrong1":"il solo risarcimento del danno","wrong2":"la costituzione di un rapporto di lavoro a tempo indeterminato alle dipendenze dell'appaltatore","wrong3":"il trasferimento ad altra unità produttiva dell'appaltatore"},{"id":1300,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"Nel caso di cessione del ramo di azienda:","correct":"La successione nell'appalto integra il trasferimento di azienda","wrong1":"cessa definitivamente il contratto di appalto","wrong2":"il lavoratore può chiedere la costituzione di un rapporto di lavoro alle dipendenze dell'utilizzatore","wrong3":"il lavoratore ha diritto a un trattamento economico superiore"},{"id":1301,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"L'azione di cui all'art. 1676 c.c.:","correct":"È diretta solo nei confronti del committente","wrong1":"è esperibile sia nei confronti del committente, sia nei confronti dell'appaltatore","wrong2":"è diretta nei confronti del solo appaltatore","wrong3":"può essere esperita anche dai dai dipendenti del committente"},{"id":1302,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"L'azione di responsabilità di cui all'art. 29 d.lgs. 276/2003:","correct":"prevede l'obbligo solidale di committente ed appaltatore di corrispondere trattamenti retributivi, quote di TFR, i contributi previdenziali e i premi assicurativi","wrong1":"riconosce condizioni non inferiori a quelle risultanti dai contratti collettivi di lavoro della categoria e della zona","wrong2":"riconosce condizioni superiori a quelle risultanti dai contratti collettivi di lavoro della categoria e della zona","wrong3":"prevede l'obbligo esclusivo dell'appaltatore di corrispondere trattamenti retributivi, quote di TFR, i contributi previdenziali e i premi assicurativi"},{"id":1303,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"è esperibile sia nei confronti del committente, sia nei confronti dell'appaltatore","correct":"alla decadenza","wrong1":"alla prescrizione","wrong2":"alla prescrizione e decadenza","wrong3":"a nessun termine decadenziale o prescrizionale"},{"id":1304,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"La certificazione del contratto di appalto:","correct":"è finalizzata ad assicurare una tenuta giuridica","wrong1":"serve per dare prova del contratto","wrong2":"disciplina il contratto di appalto","wrong3":"disciplina i diritti e doveri del lavoratore"},{"id":1305,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"La certificazione del contratto di appalto:","correct":"è fatta da apposite commissioni","wrong1":"è fatta dal committente","wrong2":"è fatta dall'appaltatore","wrong3":"è fatta dall'appaltatore e dal committente"},{"id":1306,"paragraph":"Diritto del lavoro e pubblico impiego - 8) L'appalto ed i riflessi giuslavoristici","question":"Il regime della responsabilità solidale nell'appalto:","correct":"è modificabile con i contratti di prossimità","wrong1":"è immodificabile","wrong2":"è parzialmente modificabile","wrong3":"è modificabile dal solo committente"},{"id":1307,"paragraph":"Diritto tributario - 1) Le fonti del diritto tributario e la riserva di legge","question":"Cosa si intende per \"principio di riserva di legge\" e quale tipologia di riserva di legge è applicabile al diritto tributario:","correct":"si tratta di un principio costituzionale disciplinato dall'art. 23 della Costituzione secondo cui l'obbligazione tributaria, almeno nella definizione degli elementi essenziali (presupposto, soggetto passivo, base imponibile, aliquota massima e minima) deve essere prevista dalla legge ordinaria oppure da un atto ad essa equiparato. L'art. 23, infatti, dispone che «nessuna prestazione personale o patrimoniale può essere imposta se non in base alla legge» ossia per effetto di norme emanate in ottemperanza dello specifico procedimento legislativo. Trattandosi della tipologia di riserva relativa (e non assoluta a differenza di quanto previsto in materia penale) è possibile adottare poi regolamenti/decreti ministeriali o comunque atti amministrativi che forniscano poi maggiori istruzioni sulla materia","wrong1":"La riserva di legge è di tipo assoluto e si verifica inquanto la Costituzione o impone esclusivamente alla legge di disciplinare una materia, escludendo altre fonti subordinate. Questo principio è sancito dalla Costituzione italiana e limita il potere normativo di fonti secondarie come i regolamenti","wrong2":"Il principio di riserva di legge esprime il divieto di punire un determinato fatto in assenza di una legge preesistente che lo configuri come tributo. Esso in particolare, tende a sottrarre la competenza in materia tributaria, al potere esecutivo in ossequio del principio \"no taxation without representation\". Atti esecutivi e amministrativi non possono in alcun modo integrare la materia tribuaria","wrong3":"si tratta di un principio costituzionale disciplinato dall'art. 53 della Costituzione secondo cui l'obbligazione tributaria, almeno nella definizione degli elementi essenziali (presupposto, soggetto passivo, base imponibile, aliquota massima e minima) deve essere prevista dalla legge ordinaria oppure da un atto ad essa equiparato. L'art. 53, infatti, dispone che «nessuna prestazione personale o patrimoniale può essere imposta se non in base alla legge» ossia per effetto di norme emanate in ottemperanza dello specifico procedimento legislativo. Trattandosi della tipologia di riserva relativa (e non assoluta a differenza di quanto previsto in materia penale) è possibile adottare poi regolamenti/decreti ministeriari o comunque atti amministrativi che forniscano poi maggiori istruzioni sulla materia."},{"id":1308,"paragraph":"Diritto tributario - 1) Le fonti del diritto tributario e la riserva di legge","question":"Può una norma interna essere in contrasto con una norma europea:","correct":"Nel rispetto del processo di integrazione europea che caratterizza l'ordinamento italiano non è possibile che una norma interna contrasti lo stesso ordinamento europeo. Infatti nel caso di contrasto di una disposizione interna con norme del Trattato UE e atti derivanti cioè regolamenti, direttive e decisioni del Consiglio e della Commissione - atti dotati spesso anche di efficacia diretta- il giudice interno dovrà disapplicare la norma in contrasto","wrong1":"Nel rispetto del processo di integrazione europea che caratterizza l'ordinamento italiano è comunque possibile che una norma interna contrasti lo stesso. Infatti nel caso di contrasto di una disposizione interna con norme del Trattato UE e atti derivanti cioè regolamenti, direttive e decisioni del Consiglio e della Commissione - atti dotati spesso anche di efficacia diretta- il giudice interno non è tenuto a disapplicare la norma in contrasto","wrong2":"E' possibile parlare di integrazione a proposito della progressiva intensificazione dei vincoli che ormai coinvolgono la maggior parte dei Paesi europei, tuttavia non può il giudice italiano disapplicare le norme interne in virtù di un contrasto con la disciplina europea poichè la norma interna prevale rispetto alle disposizioni unionali","wrong3":"No.L'idea di una dissoluzione della sovranità statale e di un'integrazione di principi europei non è sostenibile"},{"id":1309,"paragraph":"Diritto tributario - 1) Le fonti del diritto tributario e la riserva di legge","question":"Quale efficacia esplicano documenti di prassi (es. circolari, interpelli) dell'Agenzia delle Entrate:","correct":"Le circolari sono documenti di prassi con cui l'Amministrazione impartisce istruzioni all'ufficio, ponendo regole di comportamento e fornendo interpretazioni relative a disposizioni di legge. Non hanno assolutamente effetto vincolante per il contribuente. Infatti, secondo la pronuncia T.A.R. Roma, Lazio, sez. III, 06/06/2024 n.11520 le circolari amministrative \"non possono spiegare alcun effetto giuridico nei confronti di soggetti estranei all'amministrazione, né acquistare efficacia vincolante per quest'ultima, essendo destinate solo a esercitare una funzione direttiva nei confronti degli uffici dipendenti\". Anche gli altri documenti di prassi, come gli interpelli, non hanno efficacia vincolante nei confronti di terzi soggetti. Gli interpelli, infatti, vengono proposti dal contribuente per richiedere chiarimenti all'Agenzia Finanziaria e questi chiarimenti hanno effetto solo in relazione al caso specifico e non hanno un'efficacia generalizzata","wrong1":"Le circolari sono documenti di prassi con cui l'Amministrazione impartisce istruzioni all'ufficio, ponendo regole di comportamento e fornendo interpretazioni relative a disposizioni di legge. Hanno effetto vincolante per il contribuente.Infatti, secondo la pronuncia T.A.R. Roma, Lazio, sez. III, 06/06/2024 n.11520 le circolari amministrative \"possono spiegare effetto giuridico nei confronti di soggetti estranei all'amministrazione, acquistare efficacia vincolante per quest'ultima,non essendo destinate solo a esercitare una funzione direttiva nei confronti degli uffici dipendenti\". Anche gli altri documenti di prassi, come gli interpelli, hanno efficacia vincolante nei confronti di terzi soggetti. Gli interpelli infatti, vengono proposti dal contribuente per richiedere chiarimenti all'Agenzia Finanziaria e questi chiarimenti hanno effetto non solo in relazione al caso specifico ma hanno un'efficacia generalizzata","wrong2":"Le circolari e le risoluzioni dell'Agenzia delle Entrate o del Ministero dell'Economia e delle Finanze sono vincolanti sia per il contribuente che per il giudice e costituiscono fonte del diritto","wrong3":"Le circolari e le risoluzioni dell'Agenzia delle Entrate o del Ministero dell'Economia e delle Finanze non sono vincolanti per il contribuente ma per il giudice e costituiscono fonte del diritto. Il giudice può quindi disapplicare la norma interna perché in contrasto con una circolare emessa dall'Agenzia delle Entrate o anche perchè in contrato con la risposta resa dall'Agenzia ad un'istanza di interpello"},{"id":1310,"paragraph":"Diritto tributario - 2) L'efficacia delle norme tributarie nel tempo e nello spazio","question":"Quando entra in vigore la legge e può l'efficacia della legge differire dalla sua entrata in vigore:","correct":"ai sensi dell'art. 73 della Costituzione , \"le leggi sono pubblicate subito dopo la promulgazione ed entrano in vigore 15 gg. dopo la loro pubblicazione, salvo che le leggi stesse stabiliscano un termine diverso\". Entra in vigore, è perfetta e vale come tale ma la sua efficacia può non coincidere con la data di entrata in vigore se gli effetti della legge sono differiti o retroagiscono","wrong1":"ai sensi dell'art. 23 della Costituzione , \"le leggi sono pubblicate subito dopo la promulgazione ed entrano in vigore 15 gg. dopo la loro pubblicazione, salvo che le leggi stesse stabiliscano un termine diverso\". Entra in vigore, è perfetta e vale come tale ma la sua efficacia può non coincidere con la data di entrata in vigore se gli effetti della legge sono differiti o retroagiscono","wrong2":"ai sensi dell'art. 3 della Costituzione , \"le leggi sono pubblicate subito dopo la promulgazione ed entrano in vigore 15 gg. dopo la loro pubblicazione, salvo che le leggi stesse stabiliscano un termine diverso\". Entra in vigore, è perfetta e vale come tale ma la sua efficacia può non coincidere con la data di entrata in vigore se gli effetti della legge sono differiti o retroagiscono","wrong3":"ai sensi dell'art. 73 della Costituzione , \"le leggi sono pubblicate subito dopo la promulgazione ed entrano in vigore il giorno della loro pubblicazione, salvo che le leggi stesse stabiliscano un termine diverso\". Entra in vigore, è perfetta e vale come tale ma la sua efficacia può non coincidere con la data di entrata in vigore se gli effetti della legge sono differiti o retroagiscono"},{"id":1311,"paragraph":"Diritto tributario - 2) L'efficacia delle norme tributarie nel tempo e nello spazio","question":"Può una norma tributaria cessare di efficacia perché incostituzionale e quali effetti ha eventualmente la declaratoria di incostituzionalità:","correct":"si una norma può essere dichiarata incostituzionale. L’art. 136 della Costituzione stabilisce che quando la Corte Costituzionale dichiara l'illegittimità costituzionale di una norma di legge, di un decreto legge o un decreto legislativo, la norma cessa di avere efficacia dal giorno successivo alla pubblicazione della sentenza. La declaratoria ha effetto ex tunc o ex nunc se espressamente motivato dalla Corte e a partire dal giorno successivo alla pubblicazione della sentenza","wrong1":"no una norma non può essere dichiarata incostituzionale.L'art. 136 della Costituzione stabilisce che quando la Corte Costituzionale non può dichiararne l'illegittimità costituzionale.","wrong2":"si una norma può essere dichiarata incostituzionale.L'art. 53 della Costituzione stabilisce che quando la Corte Costituzionale dichiara l'illegittimità costituzionale di una norma di legge, di un decreto legge o un decreto legislativo, la norma cessa di avere efficacia dal giorno successivo alla pubblicazione della sentenza. La declaratoria ha effetto ex nunc a partire dal 15esimo giorno successivo alla pubblicazione della sentenza","wrong3":"si una norma può essere dichiarata incostituzionale.L'art. 136 della Costituzione stabilisce che quando la Corte Costituzionale dichiara l'illegittimità costituzionale di una norma di legge, di un decreto legge o un decreto legislativo, la norma cessa di avere efficacia dal giorno successivo alla pubblicazione della sentenza. La declaratoria ha effetto ex nunc a partire dal 15esimo giorno successivo alla pubblicazione della sentenza"},{"id":1312,"paragraph":"Diritto tributario - 2) L'efficacia delle norme tributarie nel tempo e nello spazio","question":"A cosa rileva il concetto di residenza fiscale ed è stato questo concetto oggetto di modifiche legislative negli ultimi anni:","correct":"il concetto rileva al fine di determinare se un soggetto persona fisica o giuridica è tassabile in Italia ed è stato oggetto di revisione per opera del D.Lgs. 209 del 2023","wrong1":"il concetto rileva al fine di determinare il reddito imponibile insieme al principio di capacità contributiva di cui all'art. 53 della Costituzione e non è stato mai revisionato sin dalla prima formulazione del Legislatore.","wrong2":"il concetto rileva al fine di determinare il reddito imponibile insieme al principio di capacità contributiva di cui all'art. 53 della Costituzione ed è stato oggetto di revisione per opera del D.Lgs. 209 del 2023","wrong3":"il concetto rileva al fine di determinare se un soggetto persona fisica o giuridica è tassabile in Italia e non è stato oggetto di revisione rispetto all'originaria formulazione del Legislatore"},{"id":1313,"paragraph":"Diritto tributario - 3) La residenza fiscale: il principio della WorldWide Taxation, Source Taxation e la riforma post L. 111/2023","question":"Cosa si intende per 'principio worldwide taxation':","correct":"il principio c.d. worldwide taxation stabilisce che tutti i residenti in un dato paese devono pagare le tasse su tutte le fonti di reddito, sia quelle che hanno origine nel territorio dello Stato che quelle originate fuori dal territorio dello Stato","wrong1":"il principio c.d. source taxation stabilisce che tutti i residenti in un dato paese devono pagare le tasse su tutte le fonti di reddito, sia quelle che hanno origine nel territorio dello Stato che quelle originate fuori dal territorio dello Stato","wrong2":"il principio c.d. worldwide taxation stabilisce che tutti i soggetti non residenti residenti in un dato paese devono pagare le tasse su tutte le fonti di reddito, sia quelle che hanno origine nel territorio dello Stato che quelle originate fuori dal territorio dello Stato","wrong3":"il principio c.d. worldwide taxation stabilisce che tutti i soggetti residenti residenti in un dato paese devono pagare le tasse su tutte le fonti di reddito,ma solo sulle tasse quelle che hanno origine nel territorio dello Stato"},{"id":1314,"paragraph":"Diritto tributario - 3) La residenza fiscale: il principio della WorldWide Taxation, Source Taxation e la riforma post L. 111/2023","question":"Quali sono i criteri che si applicano per considerare residenti le persone fisiche e sono questi alternativi:","correct":"l' art. 2, co.2, D.P.R. 917/86 (TUIR) chiarisce che si considerano fiscalmente residenti nel territorio dello Stato i soggetti che per più di 183 giorni alternativamente: (i) abbiano il domicilio nel territorio del Paese;(ii) abbiano in Italia la residenza, così come disciplinata ai sensi dell'art. 43 cod. civ., ovvero (iii) siano fisicamente presenti in Italia. i tre criteri sono alternativi","wrong1":"l' art. 23 della Costituzione chiarisce che che si considerano fiscalmente residenti nel territorio dello Stato i soggetti che per più di 183 giorni alternativamente:_x000b_ (i) abbiano il domicilio nel territorio del Paese;_x000b_(ii) abbiano in Italia la residenza, così come disciplinata ai sensi dell'art. 43 cod. civ., ovvero (iii) siano fisicamente presenti in Italia. i tre criteri sono alternativi","wrong2":"l' art. 53 della Costituzione chiarisce che che si considerano fiscalmente residenti nel territorio dello Stato i soggetti che per più di 183 giorni alternativamente:_x000b_ (i) abbiano il domicilio nel territorio del Paese;_x000b_(ii) abbiano in Italia la residenza, così come disciplinata ai sensi dell'art. 43 cod. civ., ovvero (iii) siano fisicamente presenti in Italia. i tre criteri sono alternativi","wrong3":"l' art. 2, co.2, D.P.R. 917/86 (TUIR) chiarisce che che si considerano fiscalmente residenti nel territorio dello Stato i soggetti che per più di 183 giorni alternativamente:_x000b_ (i) abbiano il domicilio nel territorio del Paese;_x000b_(ii) abbiano in Italia la residenza, così come disciplinata ai sensi dell'art. 43 cod. civ., ovvero (iii) siano fisicamente presenti in Italia. i tre criteri devono sussistere contemporaneamente"},{"id":1315,"paragraph":"Diritto tributario - 3) La residenza fiscale: il principio della WorldWide Taxation, Source Taxation e la riforma post L. 111/2023","question":"Quali sono i criteri che si applicano per considerare residenti le persone giuridiche e sono questi alternativi:","correct":"l'art. 73 del TUIR relativo alle società (e l'art. 5 del TUIR per le società di persone) considerano rilevanti al fine di determinare se un soggetto è o meno residente nel territorio dello Stato : (i)la sede legale(ii) la 'sede di direzione effettiva' (iii) la 'gestione ordinaria in via principale'","wrong1":"l'art. 23 della Costituzione relativo alle società considerano rilevanti al fine di determinare se un soggetto è o meno residente nel territorio dello Stato : (i)la sede legale(ii) la 'sede di direzione effettiva' (iii) la 'gestione ordinaria in via principale'","wrong2":"l'art. 53 della Costituzione considerano rilevanti al fine di determinare se un soggetto è o meno residente nel territorio dello Stato : (i)la sede legale(ii) la 'sede di direzione effettiva' (iii) la 'gestione ordinaria in via principale'","wrong3":"l'art. 73 del TUIR relativo alle società (e l'art. 5 del TUIR per le società di persone) considerano rilevanti al fine di determinare se un soggetto è o meno residente nel territorio dello Stato : (i) la localizzazione della sede legale; (ii)della sede dell'amministrazione (iii)dell'oggetto principale"},{"id":1316,"paragraph":"Diritto tributario - 4) L'art. 53 della Costituzione","question":"Il dovere di concorrere a sostenere la spesa statale è espressione di:","correct":"il dovere di concorrere a sostenere la spesa statale è espressione di un generale dovere di solidarietà (2 Cost.), e dell'obbligo di contribuire ad assicurare eguaglianza (3 Cost. così detta orizzontale) ed a creare un sistema in grado di prevedere dei servizi per tutti, anche i meno abbienti","wrong1":"Non è previsto dall'ordinamento italiano un dovere il tale senso","wrong2":"E' espressione del principio antielusivo pone il divieto di aggirare il sistema tributario traendo vantaggi illeciti, anche in forma non esclusiva","wrong3":"il dovere di concorrere a sostenere la spesa statale è espressione di un generale dovere di solidarietà morale, non previsto da alcuna norma costituzionale, e dell'obbligo di contribuire ad assicurare eguaglianza (3 Cost. così detta orizzontale) ed a creare un sistema in grado di prevedere dei servizi per tutti, anche i meno abbienti"},{"id":1317,"paragraph":"Diritto tributario - 4) L'art. 53 della Costituzione","question":"A quali esigenze risponde lil vincolo del prelievo alla capacità contributiva e può essere utilizzato come parametro di incostituzionalità di una norma:","correct":"il vincolo del prelievo alla capacità contributiva, risponde all'esigenza di garantire che ogni prelievo tributario abbia causa giustificativa in presupposti che siano indici concretamente rilevatori di ricchezza dai quali sia deducibile l'idoneità soggettiva all'obbligazione d'imposta. Sulla base di questo parametro la stessa Corte Costituzionale è chiamata a sindacare la legittimità delle leggi ordinarie che impongono tributi","wrong1":"il vincolo del prelievo alla capacità contributiva, risponde all'esigenza di garantire che ogni prelievo tributario abbia causa giustificativa in presupposti che siano indici concretamente rilevatori di ricchezza dai quali sia deducibile l'idoneità soggettiva all'obbligazione d'imposta.Sulla base di questo parametronon è ammesso un sindacato di legittimità delle leggi","wrong2":"il vincolo del prelievo alla capacità contributiva, risponde all'esigenza di garantire la materia tributaria sia disciplinata, almeno nei suoi elementi essenziali, da una legge.Sulla base di questo parametro la stessa Corte Costituzionale è chiamata a sindacare la legittimità delle leggi ordinarie che impongono tributi","wrong3":"il vincolo del prelievo alla capacità contributiva, risponde all'esigenza solidarietà.Sulla base di questo parametro la stessa Corte Costituzionale è chiamata a sindacare la legittimità delle leggi ordinarie che impongono tributi"},{"id":1318,"paragraph":"Diritto tributario - 4) L'art. 53 della Costituzione","question":"Cosa si intende per imposta progressiva ed è il Legislatore obbligato ad adottarla:","correct":"Si intende che il valore dell'imposta è variabile e si esprime attraverso l'aliquota che aumenta in maniera più che proporzionale rispetto all'aumentare della base imponibile. IL Legislatore non è obbligato in quanto si tratta solo di un indiritto e si può anche prevedere che un'imposta sia proporzionale, il cui valore è costante (sempre uguale) e non varia all'aumentare della base imponibile, come l'imposta sul reddito delle società (IRES)","wrong1":"Si intende che il valore dell'imposta è variabile e si esprime attraverso l'aliquota che aumenta in maniera più che proporzionale rispetto all'aumentare della base imponibile. Il Legislatore è obbligato ad adottare questo tipo di imposta","wrong2":"Si intende che il valore dell'imposta è sempre uguale. Il Legislatore è obbligato ad adottare questo tipo di imposta","wrong3":"Si intende che il valore dell'imposta è sempre uguale. Il Legislatore non è obbligato in quanto si tratta solo di un indiritto e si può anche prevedere che un'imposta sia proporzionale, il cui valore è costante (sempre uguale) e non varia all'aumentare della base imponibile, come l'imposta sul reddito delle società (IRES)"},{"id":1319,"paragraph":"Diritto tributario - 5) La capacità contributiva quale limite per il potere impositivo e garanzia per il contribuente","question":"Il principio di capacità contributiva rappresenta un limite al potere dell'Amministrazione Finanziaria:","correct":"La capacità contributiva rappresenta quindi un evidente vincolo per il Legislatore, in quanto restringe il suo campo di discrezionalità, non consentendogli di tipizzare come presupposti di imposta certi comportamenti sociali che, di per sé, non risultano essere manifestazioni di forza economica, di ricchezza","wrong1":"No, il principio di capacità contributiva non rappresentavincolo per il Legislatore,non restringe il suo campo di discrezionalità, egli può anzi tipizzare come presupposti di imposta certi comportamenti sociali che, di per sé, non risultano essere manifestazioni di forza economica, di ricchezza","wrong2":"La capacità contributiva rappresenta quindi un evidente vincolo l'Amministrazione che essa stessa approva le leggi e non per il Legislatore","wrong3":"La capacità contributiva non è un limite ma solo una garanzia per l'Amministrazione Finanziaria"},{"id":1320,"paragraph":"Diritto tributario - 5) La capacità contributiva quale limite per il potere impositivo e garanzia per il contribuente","question":"Nella prospettiva di garanzia del contribuente è possibile collegare il principio di capacità contributiva ad altri principi costituzionali, se sì quali:","correct":"si il principio va collegato con i principi costituzionali di legalità delle ispezioni fiscali (artt. 13 e 14), con l'irrilevanza del carattere ecclesiastico e del fine religioso o di culto sotto il profilo fiscale (art. 20), col diritto di difesa (art. 24), con l'espropriazione di pubblica utilità (art. 42, comma 3), col divieto di referendum in materia fiscale (art. 75, comma 2), con la finanza regionale (art. 119, comma 2)","wrong1":"no il principio non va collegato con altri principi costituzionali perché autonomo","wrong2":"si il principio va collegato con i principi costituzionali di tutela ambientale e riverva di legge assoluta","wrong3":"si il principio va collegato con i principi del TUIR (Testo Unico dell'Imposta sui Redditi) di legalità delle ispezioni fiscali (artt. 13 e 14), con l'irrilevanza del carattere ecclesiastico e del fine religioso o di culto sotto il profilo fiscale (art. 20), col diritto di difesa (art. 24), con l'espropriazione di pubblica utilità (art. 42, comma 3), col divieto di referendum in materia fiscale (art. 75, comma 2), con la finanza regionale (art. 119, comma 2)"},{"id":1321,"paragraph":"Diritto tributario - 5) La capacità contributiva quale limite per il potere impositivo e garanzia per il contribuente","question":"Il concetto di capacità contributiva è statico ed è rimasto immutato nell'interpretazione giurisprudenziale nel corso degli anni:","correct":"il concetto è definito in dottrina come una scatola vuota riempibile con qualsiasi contenuto. Nel corso degli anni ha subito un'evoluzione ed è importante, quindi, valutare le interpretazioni date dalla Corte Costituzionale","wrong1":"il concetto è definito in dottrina come una scatola vuota riempibile con qualsiasi contenuto. Nel corso degli anni però non ha subito un'evoluzione ed è importante","wrong2":"il concetto è definito in dottrina come una scatola vuota riempibile con qualsiasi contenuto. Nel corso degli anni le uniche interpretazioni sono state della Corte di Giustizia Europea","wrong3":"il concetto è definito in dottrina come una scatola vuota riempibile con qualsiasi contenuto. Nel corso degli anni le uniche interpretazioni sono state della Corte Europea dei Diritti dell'uomo"},{"id":1322,"paragraph":"Diritto tributario - 6) La tutela dell'affidamento, la buona fede e l'imparzialità della PA","question":"La tutela del legittimo affidamento e dei diritti acquisiti è un principio fondamentale del diritto e se si cosa mira a garantire:","correct":"la stabilità dei rapporti giuridici e a tutelare le aspettative legittime delle persone ed è finalizzata a protegge il contribuente dai comportamenti irragionevoli e contraddittori dell'Ufficio","wrong1":"l'instabilità dei rapporti giuridici e a tutelare le aspettative legittime delle persone ed è finalizzata a protegge il contribuente dai comportamenti irragionevoli e contraddittori dell'Ufficio","wrong2":"la stabilità dei rapporti giuridici ma non anche tutelare le aspettative legittime delle persone ed è finalizzata a protegge il contribuente dai comportamenti irragionevoli e contraddittori dell'Ufficio","wrong3":"la stabilità del giudizio della Corte Tributaria e a tutelare le aspettative legittime delle persone ed è finalizzata a protegge il contribuente dai comportamenti irragionevoli e contraddittori dell'Ufficio"},{"id":1323,"paragraph":"Diritto tributario - 6) La tutela dell'affidamento, la buona fede e l'imparzialità della PA","question":"Il principio di buona fede è espressamente richiamato da una norma tributaria ovvero:","correct":"l'art. 10 dello Statuto del contribuente (l. 212/2000) rubricato «Tutela dell'affidamento e della buona fede. Errori del contribuente» al comma 1 stabilisce che: «I rapporti tra contribuente e amministrazione finanziaria sono improntati al principio della collaborazione e della buona fede.»","wrong1":"l'art. 10 della l.. 2 del 2001) rubricato «Tutela dell'affidamento e della buona fede. Errori del contribuente» al comma 1 stabilisce che:«I rapporti tra contribuente e amministrazione finanziaria sono improntati al principio della collaborazione e della buona fede.»","wrong2":"l'art. 10 della Costituzione rubricato «Tutela dell'affidamento e della buona fede. Errori del contribuente» al comma 1 stabilisce che:«I rapporti tra contribuente e amministrazione finanziaria sono improntati al principio della collaborazione e della buona fede.»","wrong3":"l'53 della Costituzione rubricato «Tutela dell'affidamento e della buona fede. Errori del contribuente» al comma 1 stabilisce che:«I rapporti tra contribuente e amministrazione finanziaria sono improntati al principio della collaborazione e della buona fede.»"},{"id":1324,"paragraph":"Diritto tributario - 6) La tutela dell'affidamento, la buona fede e l'imparzialità della PA","question":"Il principio di imparzialità implica che:","correct":"Il principio implica che gli amministratori pubblici agiscano senza pregiudizi o interessi personali, ma unicamente nell'interesse generale e nel rispetto delle leggi","wrong1":"Il principio implica che gli amministratori pubblici agiscano con pregiudizi o interessi personali","wrong2":"Il principio implica che i contribuenti agiscano senza pregiudizi o interessi personali, ma unicamente nell'interesse generale e nel rispetto delle leggi","wrong3":"Il principio implica che gli amministratori privati agiscano senza pregiudizi o interessi personali, ma unicamente nell'interesse generale e nel rispetto delle leggi"},{"id":1325,"paragraph":"Diritto tributario - 7) L'autonomia finanziaria degli enti locali e il coordinamento dei tributi propri","question":"Il federalismo fiscale, come modificato a seguito della riforma del Titolo V, è disciplinato in attuazione di:","correct":"dell'art. 119 della Costituzione al comma 1 prevede che: «I Comuni, le Province, le Città metropolitane e le Regioni hanno autonomia finanziaria di entrata e di spesa, nel rispetto dell'equilibrio dei relativi bilanci, e concorrono ad assicurare l'osservanza dei vincoli economici e finanziari derivanti dall'ordinamento dell'Unione europea.»","wrong1":"dell'art. 119 del TUIR al comma 1 prevede che: «I Comuni, le Province, le Città metropolitane e le Regioni hanno autonomia finanziaria di entrata e di spesa, nel rispetto dell'equilibrio dei relativi bilanci, e concorrono ad assicurare l'osservanza dei vincoli economici e finanziari derivanti dall'ordinamento dell'Unione europea.»","wrong2":"dell'art. 23 della Costituzione al comma 1 prevede che: «I Comuni, le Province, le Città metropolitane e le Regioni hanno autonomia finanziaria di entrata e di spesa, nel rispetto dell'equilibrio dei relativi bilanci, e concorrono ad assicurare l'osservanza dei vincoli economici e finanziari derivanti dall'ordinamento dell'Unione europea.»","wrong3":"dell'art. 23 della Costituzione al comma 1 prevede che: «I Comuni, le Province, le Città metropolitane e le Regioni hanno autonomia finanziaria di entrata e di spesa, nel rispetto dell'equilibrio dei relativi bilanci, e concorrono ad assicurare l'osservanza dei vincoli economici e finanziari derivanti dall'ordinamento dell'Unione europea.»"},{"id":1326,"paragraph":"Diritto tributario - 7) L'autonomia finanziaria degli enti locali e il coordinamento dei tributi propri","question":"Entro quali limiti la fiscalità locale può operare:","correct":"i limiti all'autonomia tributaria sono previsti dalla Costituzione agli articoli 23, 53 e 119 e dall'articolo 12 della Legge 42/2009 secondo cui la legge statale individua i tributi propri dei Comuni e attribuisce agli stessi compartecipazioni ai tributi erariali riferibili al loro territorio. In ordine ai tributi, la legge statale definisce: i presupposti; i soggetti passivi; le basi imponibili; le aliquote di riferimento, flessibili, valide per tutto il territorio nazionale","wrong1":"non sono previsti limiti all'autonomia tributaria","wrong2":"i limiti all'autonomia tributaria sono previsti solo dagli enti locali stessi","wrong3":"i limiti all'autonomia tributaria sono previsti solo dal Presidente della Repubblica"},{"id":1327,"paragraph":"Diritto tributario - 7) L'autonomia finanziaria degli enti locali e il coordinamento dei tributi propri","question":"Da quale norma sono disciplinati dell'imposta di soggiorno e del contributo di sbarco e quale  soggetto passivo includono:","correct":"sono disciplinati dall'art. 4 del D.lgs 23 del 2011 e si applicano il primo a coloro che pernottano nelle strutture localizzate nei territori il cui Comune ha regolamentato la disciplina (aderendo alla possibilità di adottare questa tassazione); il secondo a coloro che transitano sulle isole","wrong1":"sono disciplinati dall'art. 4 della Costituzione e si applicano il primo a coloro che pernottano nelle strutture localizzate nei territori il cui Comune ha regolamentato la disciplina (aderendo alla possibilità di adottare questa tassazione); il secondo a coloro che transitano sulle isole.","wrong2":"sono disciplinati dall'art. 4 del D.lgs 23 del 2011 e si applicano a coloro che producono reddito nelle isole","wrong3":"sono disciplinati dall'art. 4 del D.lgs 23 del 2011 e si applicano entrambi a coloro che pernottano"},{"id":1328,"paragraph":"Diritto tributario - 8) I principi di diritto europeo in materia fiscale","question":"Cosa si intende per armonizzazione legislativa:","correct":"L'armonizzazione legislativa, in ambito comunitario, viene definita come una procedura attraverso la quale è possibile rendere affini gli ordinamenti giuridici nazionali o più specificamente le discipline normative e le disposizioni regolamentari nazionali per la realizzazione di un fine comune","wrong1":"L'armonizzazione legislativa, in ambito internazionale, viene definita come una procedura attraverso la quale è possibile rendere affini gli ordinamenti giuridici nazionali o più specificamente le discipline normative e le disposizioni regolamentari nazionali per la realizzazione di un fine comune","wrong2":"L'armonizzazione legislativa, in ambito comunitario, viene definita come una procedura attraverso la quale è possibile che le Regioni adottino tributi propri","wrong3":"L'armonizzazione legislativa, in ambito comunitario, viene definita come una procedura attraverso la quale è possibile che le Regioni armonizzino la propria fiscalità locale"},{"id":1329,"paragraph":"Diritto tributario - 8) I principi di diritto europeo in materia fiscale","question":"Cosa si intende per principio di non discriminazione fiscale:","correct":"Il principio di non discriminazione fiscale è un principio del diritto comunitario che vieta agli Stati membri di riservare alle merci o ai redditi degli altri Stati membri un trattamento fiscale deteriore rispetto ai prodotti o ai soggetti nazionali. Il principio è previsto dagli art. 90 e seg. e dall'art. 110 del Trattato CE","wrong1":"Il principio di non discriminazione fiscale è un principio del diritto comunitario che consente agli Stati membri di riservare alle merci o ai redditi degli altri Stati membri un trattamento fiscale deteriore rispetto ai prodotti o ai soggetti nazionali. Il principio è previsto dagli art. 90 e seg. e dall'art. 110 del Trattato CE","wrong2":"Il principio di non discriminazione fiscalenon si applica nell'ordinamento italiano","wrong3":"Il principio di non discriminazione fiscale è un principio del diritto italiano che vieta agli Stati membri di riservare alle merci o ai redditi degli altri Stati membri un trattamento fiscale deteriore rispetto ai prodotti o ai soggetti nazionali. Il principio è previsto dagli art. 90 e seg. e dall'art. 110 del Trattato CE"},{"id":1330,"paragraph":"Diritto tributario - 8) I principi di diritto europeo in materia fiscale","question":"Come avviene principalmente l'integrazione delle disposizioni del Trattati UE sulle libertà:","correct":"L'integrazione delle disposizioni del Trattato UE sulla libera circolazione di capitali, come l'integrazione del Trattato sulla libera circolazione di servizi e sulla liberà di stabilimento di società e imprenditori avviene spesso per il ricorso da parte della Corte di giustizia in fase di interpretazione di norme nazionali in materia tributaria","wrong1":"L'integrazione delle disposizioni del Trattato UE sulla libera circolazione di capitali, come l'integrazione del Trattato sulla libera circolazione di servizi e sulla liberà di stabilimento di società e imprenditori avviene spesso per il ricorso da parte della Corte Costituzionale in fase di interpretazione di norme nazionali in materia tributaria","wrong2":"L'integrazione delle disposizioni del Trattato UE sulla libera circolazione di capitali, come l'integrazione del Trattato sulla libera circolazione di servizi e sulla liberà di stabilimento di società e imprenditori avviene spesso per il ricorso da parte del Presidente della Repubblica in fase di interpretazione di norme nazionali in materia tributaria","wrong3":"L'integrazione delle disposizioni del Trattato UE sulla libera circolazione di capitali, come l'integrazione del Trattato sulla libera circolazione di servizi e sulla liberà di stabilimento di società e imprenditori avviene spesso per il ricorso da parte della Commissione Europea in fase di interpretazione di norme nazionali in materia tributaria"},{"id":1331,"paragraph":"Diritto tributario - 9) Aiuti di Stato, principio di effettività ed equivalenza","question":"Agevolazioni o incentivi fiscali sono sempre vietati in virtù del divieto di aiuti di Stato:","correct":"Non necessariamente. Ai sensi dell'art. 108 TFUE è prevista una procedura che culmina nella decisione finale della Commissione la quale stabilisce se le agevolazioni o gli incentivi fiscali possono potenzialmente essere considerati aiuti di Stato oppure se non entrano nella sfera di applicazione del divieto","wrong1":"Non necessariamente. Ai sensi dell'art. 10 Costituzione è prevista una procedura che culmina nella decisione finale della Commissione la quale stabilisce se le agevolazioni o gli incentivi fiscali possono potenzialmente essere considerati aiuti di Stato oppure se non entrano nella sfera di applicazione del divieto","wrong2":"Si sono sempre vietati","wrong3":"Non necessariamente. Ai sensi dell'art. 108 TFUE è prevista una procedura che culmina nella decisione finale del Presidente della Repubblica il quale stabilisce se le agevolazioni o gli incentivi fiscali possono potenzialmente essere considerati aiuti di Stato oppure se non entrano nella sfera di applicazione del divieto"},{"id":1332,"paragraph":"Diritto tributario - 9) Aiuti di Stato, principio di effettività ed equivalenza","question":"Il principio di effettività prevede che:","correct":"le norme di diritto interno, rilevanti sul piano processuale, non devono rendere praticamente impossibile o eccessivamente difficile la tutela dei diritti spettanti in forza del diritto UE, assicurando, di fatto, una garanzia minima ed adeguata, il che favorisce, altresì, l'implementazione e l'applicazione delle norme UE a livello nazionale","wrong1":"le norme di diritto internazionale non devono rendere praticamente impossibile o eccessivamente difficile la tutela dei diritti spettanti in forza del diritto UE, assicurando, di fatto, una garanzia minima ed adeguata, il che favorisce, altresì, l'implementazione e l'applicazione delle norme UE a livello nazionale","wrong2":"le sentenze del giudice non devono rendere praticamente impossibile o eccessivamente difficile la tutela dei diritti spettanti in forza del diritto UE, assicurando, di fatto, una garanzia minima ed adeguata, il che favorisce, altresì, l'implementazione e l'applicazione delle norme UE a livello nazionale","wrong3":"i regolamenti amministrativi non devono rendere praticamente impossibile o eccessivamente difficile la tutela dei diritti spettanti in forza del diritto UE, assicurando, di fatto, una garanzia minima ed adeguata, il che favorisce, altresì, l'implementazione e l'applicazione delle norme UE a livello nazionale"},{"id":1333,"paragraph":"Diritto tributario - 9) Aiuti di Stato, principio di effettività ed equivalenza","question":"In base al principio di equivalenza, gli individui che fanno valere diritti conferiti dall'ordinamento dell'Unione non devono essere svantaggiati rispetto a quelli che invocano situazioni giuridiche soggettive nazionali, quale tipo di accertamento è richiesto a tal fine:","correct":"Tale principio richiede, un accertamento interno, avente ad oggetto la normativa dello Stato membro e, dunque, la verifica dell'assenza di discriminazione tra i rimedi apprestati da quest'ultima nei casi di violazione della normativa nazionale e di quelli previsti a tutela di prerogative europee","wrong1":"Tale principio richiede,una accertamento da parte della Corte Costituzionale avente ad oggetto la normativa dello Stato membro e, dunque, la verifica dell'assenza di discriminazione tra i rimedi apprestati da quest'ultima nei casi di violazione della normativa nazionale e di quelli previsti a tutela di prerogative europee","wrong2":"Tale principio richiede, pertanto, un accertamento interno, avente ad oggetto la normativa dello Stato membro e, dunque, la verifica dell'esistenza dell'irregolarità fiscale","wrong3":"Tale principio richiede, pertanto, un accertamento interno, avente ad oggetto la normativa dello Stato membro e, dunque, la verifica degli elementi costitutivi della capacità contributiva"},{"id":1334,"paragraph":"Diritto tributario - 10) Il genus dei tributi e la differenza tra imposta, tassa e contributi","question":"L'imposta è:","correct":"l'imposta è un tributo essenzialmente contributivo nel senso che è acausale e le spesa che questo va a sostenere non sono collegate all'attività dell'ente che ne è il soggetto attivo-creditore. Trae fondamento dal criterio di riparto delle spese pubbliche e il suo scopo è semplicemente quello di dividere tra i contribuenti il carico finanziario delle attività pubbliche","wrong1":"è un tributo che si distingue dal corrispettivo (o «prezzo pubblico») in quanto,la prestazione patrimoniale è imposta e lo «scambio» viene coattivamente imposto dalla legge","wrong2":"è una particolare tipologia di tributo, cioè un prelievo di ricchezza coattivo rientrante nel campo delle prestazioni patrimoniali imposte che si potrebbe collocare idealmente come ordine intermedio tra la figura dell'imposta e quella della tassa","wrong3":"l'imposta è il genere nella cui specie rientrano i tributi"},{"id":1335,"paragraph":"Diritto tributario - 10) Il genus dei tributi e la differenza tra imposta, tassa e contributi","question":"Quale tra le seguenti ipotesi è una tassa:","correct":"la TARI (per la raccolta dei rifiuti), la Tassa sull'occupazione di suolo pubblico, la Tassa di registro sul contratto di locazione","wrong1":"il pagamento del biglietto del biglietto di un concerto","wrong2":"per far fronte a lavori di pubblica utilità","wrong3":"per la manutenzione delle fognature"},{"id":1336,"paragraph":"Diritto tributario - 10) Il genus dei tributi e la differenza tra imposta, tassa e contributi","question":"Relativamente ai contributi, secondo le teorie più recenti:","correct":"il contributo ricopre un ruolo discusso, si tratta di una figura giuridica generica ed equivoca","wrong1":"il contributo è il genus di cui tributo imposta e tassa sono le sottocategorie","wrong2":"il contributo non è costituzionale","wrong3":"il contributo sta assumendo un ruolo sempre più importante nell'ordinamento italiano"},{"id":1337,"paragraph":"Diritto tributario - 11) Altre tipologie di tributi","question":"La natura giuridica delle tariffe non è sempre chiara:","correct":"vero, la Corte Costituzionale si è trovata a dover analizzare in base alle caratteristiche strutturali delle tariffe, se queste effettivamente avessero natura tributaria, come nel caso della questione relativa alla TIA (tariffa igiene ambientale). Anche la Cassazione si è pronunciata in merito","wrong1":"falso, è sempre chiaro quale sia la natura giurdica delle tariffe","wrong2":"vero, la Corte dei Diritti dell'Uomo si è trovata a dover analizzare in base alle caratteristiche strutturali delle tariffe, se queste effettivamente avessero natura tributaria, come nel caso della questione relativa alla TIA (tariffa igene ambientale)","wrong3":"errato, in passato si erano poste delle questioni relative alla natura giuridica ma oggi queste non hanno ragione di esistere"},{"id":1338,"paragraph":"Diritto tributario - 11) Altre tipologie di tributi","question":"I tributi di scopo sono strumenti che tendono a realizzare:","correct":"una logica di compensazione/pagamento/concorso per i benefici ottenuti o per i costi generati dai soggetti contribuenti , spesso riguardanti la fruizione di servizi indivisibili o di beni che hanno natura non escludibile (parchi, strade, illuminazione, pubblica sicurezza, igiene urbana, ecc.)","wrong1":"una logica di compensazione/pagamento/concorso per i benefici ottenuti o per i costi generati dai soggetti contribuenti , spesso riguardanti la fruizione di servizi divisibili o di beni che hanno natura escludibile.","wrong2":"una logica sinallagmatica","wrong3":"una logica di risarcitoria"},{"id":1339,"paragraph":"Diritto tributario - 11) Altre tipologie di tributi","question":"I dazi doganali sono:","correct":"I dazi doganali sono dei tributi applicati ai prodotti importati. Si paga, come suggerisce il nome stesso, alla dogana del paese in cui risiede l'azienda che importa. La caratteristica strutturale del dazio è che viene utilizzato per proteggere l'economia nazionale. Nello specifico, si usa per scoraggiare l'importazione di merci che vengono già prodotte sul territorio di chi impone il dazio","wrong1":"I dazi doganali sono dei tributi applicati ai prodotti esportati.Si paga, come suggerisce il nome stesso, alla dogana del paese in cui risiede l'azienda che importa. Nello specifico, si usa per scoraggiare l'esportazione di merci che vengono già prodotte sul territorio di chi impone il dazio","wrong2":"i dazi doganali sono dei tributi applicati ai prodotti importati.Si paga, alla dogana del paese di origine. La caratteristica strutturale del dazio è che viene utilizzato per proteggere l'economia nazionale. Nello specifico, si usa per scoraggiare l'importazione di merci che vengono già prodotte sul territorio di chi impone il dazio","wrong3":"i dazi doganali sono dei tributi applicati ai prodotti importati.Si pagano anche all'interno dell'Unione Europea"},{"id":1340,"paragraph":"Diritto tributario - 12) La struttura della norma tributaria","question":"L'obbligazione tributaria:","correct":"utilizza lo schema di carattere obbligatorio modellato su quello di diritto civile ma si differenzia da questo perché la fonte dell'obbligazione tributaria è la legge e non ha rilevanza la volontà dei soggetti coinvolti nello schema obbligatorio","wrong1":"utilizza lo schema di carattere obbligatorio modellato su quello di diritto commerciale ma si differenzia da questo perché la fonte dell'obbligazione tributaria è la legge e non ha rilevanza la volontà dei soggetti coinvolti nello schema obbligatorio","wrong2":"è disponibile e rimessa alla volontà dei soggetti contraenti","wrong3":"è indisponibile e tuttavia può essere prevista una deroga che rimetta alla volontà dei soggetti contraenti la statuizione degli elementi accessori"},{"id":1341,"paragraph":"Diritto tributario - 12) La struttura della norma tributaria","question":"Il presupposto dell'obbligazione tributaria è:","correct":"è il fatto o requisito al cui verificarsi sorge l'obbligazione tributaria, ovvero l'obbligo di provvedere al pagamento del tributo","wrong1":"oggetto che è costituito dalla ricchezza ovvero dalla capacità economica","wrong2":"il coefficiente da applicare allabase imponibile per ricavare da essa l'ammontare dell'imposta.","wrong3":"è la grandezza economica che rappresenta la capacità contributiva manifestata dal presupposto ovvero l'oggetto del tributo"},{"id":1342,"paragraph":"Diritto tributario - 12) La struttura della norma tributaria","question":"L'aliquota è:","correct":"è il coefficiente da applicare alla base imponibile per ricavare da essa l'ammontare dell'imposta.","wrong1":"oggetto che è costituito dalla ricchezza ovvero dalla capacità economica","wrong2":"è la grandezza economica che rappresenta la capacità contributiva manifestata dal presupposto ovvero l'oggetto del tributo","wrong3":"è il fatto o requisito al cui verificarsi sorge l'obbligazione tributaria, ovvero l'obbligo di provvedere al pagamento del tributo"},{"id":1343,"paragraph":"Diritto tributario - 13) L'interpretazione della norma tributaria","question":"L'interpretazione autentica:","correct":"Proveniente dallo stesso legislatore, il quale talvolta emana apposite disposizioni al fine di chiarire il preciso significato di norme preesistenti","wrong1":"Proveniente dalla Corte di Giustizia europea, la quale talvolta emana appositedisposizioni al fine di chiarire il preciso significato di norme preesistenti","wrong2":"Proveniente dal Presidente della Repubblica, il quale talvolta emana appositedisposizioni al fine di chiarire il preciso significato di norme preesistenti","wrong3":"Proveniente dagli uffici dell'Agenzia delle Entrate, i quali talvolta emanano appositedisposizioni al fine di chiarire il preciso significato di norme preesistenti"},{"id":1344,"paragraph":"Diritto tributario - 13) L'interpretazione della norma tributaria","question":"Quali norme in materia tributaria sono suscettibili di interpretazione analogica:","correct":"le norme procedurali e processuali sono, in via generale, suscettibili di applicazione analogica; alle norme penali tributarie non è applicabile l'analogia ai sensi dell'art. 25 Cost. (riserva assoluta di legge)","wrong1":"le norme procedurali e processuali, in via generale, sono suscettibili di applicazione analogica e norme penali tributarie ai sensi dell'art. 25 Cost. (riserva assoluta di legge)","wrong2":"nessuna norma in materia tributaria","wrong3":"solo le norme penali tributarie"},{"id":1345,"paragraph":"Diritto tributario - 13) L'interpretazione della norma tributaria","question":"Le circolari dell'Agenzia delle Entrate hanno la funzione di:","correct":"Le circolari svolgono due funzioni: sono di ausilio a contribuenti e operatori nell'interpretazione delle norme tributarie; sono uno strumento di uniformazione e orientamento delle interpretazioni dei singoli uffici periferici","wrong1":"hanno valore vincolante quindi il contribuente non può discostarsi da essi","wrong2":"Le circolari svolgono due funzioni: sono di ausilio a contribuenti e non anche agli operatori","wrong3":"Le circolari svolgono due funzioni: sono di ausilio a contribuenti e operatori nell'interpretazione delle norme tributarie; sono uno strumento di uniformazione e orientamento delle interpretazioni dei singoli uffici periferici. Queste sono vincolanti per i contribuenti."},{"id":1346,"paragraph":"Diritto tributario - 14) L'interpello","question":"La risposta all'interpello è vincolante:","correct":"la risposta ad interpello resa dalla AF è vincolante solo per la stessa AF e non anche per il contribuente che ben può discostarsene","wrong1":"la risposta ad interpello resa dalla AF è vincolante solo per il contribuente","wrong2":"la risposta ad interpello resa dalla AF non è vincolante nè per la stessa AF e ne per il contribuente","wrong3":"la risposta ad interpello se resa dalla AF è vincolante per il Legislatore"},{"id":1347,"paragraph":"Diritto tributario - 14) L'interpello","question":"L'interpello qualificatorio:","correct":"concerne la qualificazione di un certo fatto o di un'operazione economica (ad es. qualificazione di un insieme di beni come azienda). In merito a quest'ultima tipologia di interpello il 'dubbio' del contribuente non riguarda l'interpretazione della norma tributaria, ma riguarda la corretta qualificazione del fatto che potrebbe comportare l'applicazione di una norma fiscale in luogo di un'altra","wrong1":"concerne la qualificazione di un certo fatto o di una norma. In merito a quest'ultima tipologia di interpello il 'dubbio' del contribuente non riguarda l'interpretazione della norma tributaria, ma riguarda la corretta qualificazione del fatto che potrebbe comportare l'applicazione di una norma fiscale in luogo di un'altra","wrong2":"concerne la qualificazione di una norma","wrong3":"concerne la qualificazione di un'operazione economica ma non ci un fatto"},{"id":1348,"paragraph":"Diritto tributario - 14) L'interpello","question":"La tipizzazione delle ipotesi di interpello:","correct":"è frutto della riscrittura dell'art. 11 dello Statuto, in materia di interpelli avvenuta per opera della riforma fiscale ex Legge 9 agosto 2023","wrong1":"non è mai cambiata negli anni","wrong2":"è frutto della riscrittura dell'art. 11 della Costituzione, in materia di interpelli avvenuta per opera della riforma fiscale ex Legge 9 agosto 2023","wrong3":"è frutto della riscrittura dell'art. 53 della Costituzione, in materia di interpelli avvenuta per opera della riforma fiscale ex Legge 9 agosto 2023"},{"id":1349,"paragraph":"Diritto tributario - 15) Evasione, elusione e abuso del diritto","question":"L'evasione fiscale:","correct":"in base alla gravità, sono previste sanzioni più contenute o più rilevanti che, in alcuni casi e al superamento di talune soglie, sfociano nel penale, comportando anche il carcere","wrong1":"non è punita né con sanzioni amministrative né penali","wrong2":"in base alla gravità, sono previste sanzioni più contenute o più rilevanti che, in alcuni casi e al superamento di talune soglie che mai sfociano nel penale","wrong3":"in base alla gravità, sono previste sanzioni più contenute o più rilevanti che, in alcuni casi e al superamento di talune soglie che sempre sfociano nel penale"},{"id":1350,"paragraph":"Diritto tributario - 15) Evasione, elusione e abuso del diritto","question":"I requisiti che caratterizzano l'elusione sono:","correct":"1.l'individuazione di una o più operazioni prive di sostanza economica; 2. il conseguimento, da parte del contribuente, di vantaggi fiscali indebiti; 3. l'assenza di valide ragioni extrafiscali in grado di giustificare le operazioni svolte","wrong1":"1.l'individuazione di una o più operazioni prive di sostanza economica;2.il conseguimento, da parte del contribuente, di vantaggi fiscali indebiti","wrong2":"1.l'individuazione di una o più operazioni prive di sostanza economica;2. l'assenza di valide ragioni extrafiscali in grado di giustificare le operazioni svolte","wrong3":"1.l'individuazione di una o più operazioni prive di sostanza economica;2.presenza di valide ragioni extrafiscali in grado di giustificare le operazioni svolte"},{"id":1351,"paragraph":"Diritto tributario - 15) Evasione, elusione e abuso del diritto","question":"Il fenomeno dell'elusione fiscale è contemplato:","correct":"a livello di legislazione ordinaria, il fenomeno dell'elusione fiscale è oggi contemplato dall'art. 10-bis della L. 212-2000 (Statuto dei diritti del contribuente), norma di carattere generale e da altre norme speciali","wrong1":"a livello di legislazione ordinaria non è ancora disciplinato il fenomeno generale","wrong2":"a livello di legislazione ordinaria, il fenomeno dell'elusione fiscale è oggi contemplato dall'art. 10-bis della Costituzione, norma di carattere generale e da altre norme speciali","wrong3":"a livello di legislazione ordinaria, il fenomeno dell'elusione fiscale è oggi contemplato solo da norme speciali"},{"id":1352,"paragraph":"Diritto tributario - 16) La soggettività tributaria attiva","question":"Per soggetto attivo del rapporto tributario si intende:","correct":"soggetto creditore del tributo ( c.d. soggetto attivo). Generalmente, il soggetto titolare del credito coincide con il soggetto che dispone della titolarità di poteri attuativi volti alla realizzazione coattiva del tributo","wrong1":"il soggetto debitore che è tenuto all'adempimento del tributo per effetto della titolarità della manifestazione di ricchezza sottoposta a imposizione","wrong2":"il soggetto che è tenuto all'adempimento del tributo per effetto della titolarità della manifestazione di ricchezza sottoposta a imposizione","wrong3":"il soggeto che ha competenza in materia di politica economica, politica finanziaria, bilancio e fisco."},{"id":1353,"paragraph":"Diritto tributario - 16) La soggettività tributaria attiva","question":"Le agenzie fiscali:","correct":"hanno personalità giuridica di diritto pubblico e il loro operato è sempre sottoposto alla vigilanza del MEF","wrong1":"non hanno personalità giuridica di diritto pubblico e il loro operato è sempre sottoposto alla vigilanza del MEF","wrong2":"hanno personalità giuridica di diritto pubblico e il loro operato non è sottoposto alla vigilanza del MEF","wrong3":"hanno personalità giuridica di diritto pubblico e il loro operato è sempre sottoposto alla vigilanza del Ministero del Turismo"},{"id":1354,"paragraph":"Diritto tributario - 16) La soggettività tributaria attiva","question":"La Guardia di Finanza:","correct":"in qualità di organo di polizia tributaria, collabora con gli uffici finanziari nell'attività di accertamento delle imposte nonché di repressione delle relative violazioni. In qualità di organo di polizia giudiziaria, può essere di ausilio agli uffici finanziari attraverso la trasmissione, previa autorizzazione dell'autorità giudiziaria, di documenti, dati e notizie acquisiti direttamente o per mezzo altre forze di polizia","wrong1":"non collabora con gli uffici finanziari nell'attività di accertamento delle imposte . come organo di polizia giudiziaria però può essere di ausilio agli uffici finanziari attraverso la trasmissione, previa autorizzazione dell'autorità giudiziaria, di documenti, dati e notizie acquisiti direttamente o per mezzo altre forze di polizia","wrong2":"In qualità di organo di polizia giudiziaria, senza essere di ausilio agli uffici finanziari attraverso la trasmissione, previa autorizzazione dell'autorità giudiziaria, di documenti, dati e notizie acquisiti direttamente o per mezzo altre forze di polizia","wrong3":"in qualità di organo di polizia tributaria, collabora con gli uffici finanziari nell'attività di accertamento delle imposte nonché di repressione delle relative violazioni. In qualità di organo di polizia giudiziaria, può essere di ausilio agli uffici finanziari attraverso la trasmissione, senza autorizzazione dell'autorità giudiziaria, di documenti, dati e notizie acquisiti direttamente o per mezzo altre forze di polizia"},{"id":1355,"paragraph":"Diritto tributario - 17) La soggettività tributaria passiva","question":"Il soggetto passivo:","correct":"è colui al quale è riferibile la manifestazione di capacità contributiva che il legislatore intende assoggettare al prelievo e che, pertanto, è titolare dell'obbligazione d'imposta","wrong1":"è colui al quale è riferibile la pretesa creditizia","wrong2":"è colui al quale è riferibile la manifestazione di capacità contributiva che il legislatore intende assoggettare al prelievo ma non è titolare dell'obbligazione d'imposta","wrong3":"è colui al quale è riferibile la manifestazione di capacità contributiva che l'amministrazione intende assoggettare al prelievo e che, pertanto, ma non è titolare dell'obbligazione d'imposta"},{"id":1356,"paragraph":"Diritto tributario - 17) La soggettività tributaria passiva","question":"La solidarietà tributaria è un istituto che consente:","correct":"la realizzazione dell'obbligazione d'imposta riferibile a più soggetti mediante l'aggressione di uno soltanto, con effetti liberatori per tutti","wrong1":"la realizzazione dell'obbligazione d'imposta riferibile a più soggetti mediante l'aggressione di uno soltanto, con effetti liberatori solo verso quel soggetto","wrong2":"la realizzazione dell'obbligazione d'imposta riferibile a più soggetti mediante l'aggressione di uno soltanto ma senza alcun effetto liberatorio","wrong3":"la realizzazione dell'obbligazione d'imposta riferibile a un solo soggetto mediante l'aggressione di uno soltanto"},{"id":1357,"paragraph":"Diritto tributario - 17) La soggettività tributaria passiva","question":"Secondo l'orientamento maggioritario in caso di solidarietà nella disciplina processuale sarebbero utilizzabili quali dei seguenti strumenti processuali sarebbero utilizzabili:","correct":"litisconsorzio necessario; riunione dei processi; chiamata in garanzia","wrong1":"si tratta riunione dei processi; chiamata in garanzia","wrong2":"si tratta di litisconsorzio facoltativo; riunione dei processi; chiamata in garanzia","wrong3":"si tratta di litisconsorzio necessario ma non anche riunione dei processi"},{"id":1358,"paragraph":"Diritto tributario - 18) Il sostituto, il responsabile d'imposta e la traslazione e l'accollo","question":"Il sostituto d'imposta è:","correct":"ai sensi dell'art. 64, c. 1, Dpr. n. 600/73, «chi, in forza di disposizioni di legge, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili ed anche a titolo di acconto, deve effettuare la rivalsa salvo che sia diversamente stabilito in modo espresso»","wrong1":"ai sensi dell'art. 64, della Costituzione, «chi, in forza di disposizioni di legge, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili ed anche a titolo di acconto, deve effettuare la rivalsa salvo che sia diversamente stabilito in modo espresso","wrong2":"ai sensi dell'art. 64, c. 1, Dpr. n. 600/73, «chi, in forza di disposizioni di regolamenti amministrativi, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili ed anche a titolo di acconto, deve effettuare la rivalsa salvo che sia diversamente stabilito in modo espresso»","wrong3":"ai sensi dell'art. 64, c. 1, Dpr. n. 600/73, «chi, in forza di disposizioni di legge, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili ma non anche a titolo di acconto, deve effettuare la rivalsa salvo che sia diversamente stabilito in modo espresso»"},{"id":1359,"paragraph":"Diritto tributario - 18) Il sostituto, il responsabile d'imposta e la traslazione e l'accollo","question":"Il responsabile d'imposta è:","correct":"ai sensi dell'art. 64, comma 3, D.P.R. n. 600/1973, «Chi, in forza di disposizioni di legge, è obbligato al pagamento dell'imposta insieme con altri, per fatti o situazioni esclusivamente riferibili a questi, ha diritto di rivalsa»","wrong1":"ai sensi dell'art. 64, c. 1, Dpr. n. 600/73, «chi, in forza di disposizioni di legge, è obbligato al pagamento di imposte in luogo di altri, per fatti o situazioni a questi riferibili ed anche a titolo di acconto, deve effettuare la rivalsa salvo che sia diversamente stabilito in modo espresso»","wrong2":"ai sensi dell'art. 64 della Costituzione «Chi, in forza di disposizioni di legge, è obbligato al pagamento dell'imposta insieme con altri, per fatti o situazioni esclusivamente riferibili a questi, ha diritto di rivalsa»","wrong3":"ai sensi dell'art. 64, comma 3, D.P.R. n. 600/1973, «Chi, in forza di disposizioni di regolamenti amministrativi, è obbligato al pagamento dell'imposta insieme con altri, per fatti o situazioni esclusivamente riferibili a questi, ha diritto di rivalsa»"},{"id":1360,"paragraph":"Diritto tributario - 18) Il sostituto, il responsabile d'imposta e la traslazione e l'accollo","question":"L'accollo è ammesso, se sì a quali condizioni:","correct":"ai sensi dell'art. 8, comma 2, L. n. 212/00, «È ammesso l'accollo del debito d'imposta altrui senza liberazione del contribuente originario»","wrong1":"ai sensi dell'art. 8, comma 2, L. n. 212/00, «Non ammesso l'accollo del debito d'imposta altrui»","wrong2":"ai sensi dell'art. 8, comma 2, L. n. 212/00, «È ammesso l'accollo del debito d'imposta altrui con liberazione del contribuente originario»","wrong3":"ai sensi dell'art. 8, comma 2, L. n. 212/00, «È ammesso l'accollo del debito d'imposta senza condizioni»"},{"id":1361,"paragraph":"Diritto tributario - 19) Alcune fattispecie peculiari di soggettività passiva","question":"Il consolidato nazionale è:","correct":"un particolare regime di tassazione opzionale, disciplinato dagli articoli da 117 a 129 del TUIR, che consente di determinare, in capo alla controllante, un'unica base imponibile data dalla somma algebrica degli imponibili delle società del gruppo che vi aderiscono","wrong1":"un particolare regime di tassazione obbligatoria disciplinato dagli articoli da 117 a 129 del TUIR, che consente di determinare, in capo alla controllante, un'unica base imponibile data dalla somma algebrica degli imponibili delle società del gruppo che vi aderiscono","wrong2":"un particolare regime di tassazione opzionale, disciplinato da un regolamento regionale, che consente di determinare, in capo alla controllante, un'unica base imponibile data dalla somma algebrica degli imponibili delle società del gruppo che vi aderiscono","wrong3":"un particolare regime di tassazione opzionale, disciplinato dagli articoli da 117 a 129 della Costituzione, che consente di determinare, in capo alla controllante, un'unica base imponibile data dalla somma algebrica degli imponibili delle società del gruppo che vi aderiscono"},{"id":1362,"paragraph":"Diritto tributario - 19) Alcune fattispecie peculiari di soggettività passiva","question":"Un avviso di accertamento ad oggetto crediti i cui presupposti si siano verificati prima della dichiarazione di fallimento deve essere notificato:","correct":"deve essere notificato, a pena di nullità, non solo al curatore ma anche al contribuente essendo egli, appunto, soggetto passivo d'imposta resta esposto alle conseguenze patrimoniali e sanzionatorie scaturenti dalla definitività della pretesa tributaria","wrong1":"solo al curatore della società fallita","wrong2":"deve essere notificato, a pena di annullabilità anche al contribuente essendo egli, appunto, soggetto passivo d'imposta resta esposto alle conseguenze patrimoniali e sanzionatorie scaturenti dalla definitività della pretesa tributaria","wrong3":"deve essere notificato, a pena di nullità, soloal contribuente essendo egli, appunto, soggetto passivo d'imposta resta esposto alle conseguenze patrimoniali e sanzionatorie scaturenti dalla definitività della pretesa tributaria"},{"id":1363,"paragraph":"Diritto tributario - 19) Alcune fattispecie peculiari di soggettività passiva","question":"Il trust:","correct":"è caratterizzato dal riconoscimento di autonoma soggettività tributaria","wrong1":"non è caratterizzato dal riconoscimento di autonoma soggettività tributaria","wrong2":"non è un istituto che si applica in Italia","wrong3":"è caratterizzato da soggettività giuridica ma solo previa approvazione del garante dei contribuenti"},{"id":1364,"paragraph":"Diritto tributario - 20) Gli obblighi strumentali del contribuente","question":"La tenuta delle scritture contabili consiste:","correct":"la tenuta delle scritture contabili consiste nella conservazione di documenti che la legge prescrive, ai fini delle imposte diretti nonchè dell'IVA, ai soggetti titolari di redditi d'impresa o di lavoro autonomo","wrong1":"la tenuta delle scritture contabili consiste nella conservazione dei documenti che i decreti ministeriali prescrivono","wrong2":"la tenuta delle scritture contabili consiste nella conservazione delle visure camerali","wrong3":"la tenuta delle scritture contabili consiste nella conservazione di documenti che la legge prescrive, ai fini delle imposte diretti nonché dell'IVA, solo ai soggetti titolari di redditi d'impresa"},{"id":1365,"paragraph":"Diritto tributario - 20) Gli obblighi strumentali del contribuente","question":"È possibile presentare la dichiarazione dei redditi in iva telematica:","correct":"si, è previsto l'invio telematico all'Agenzia delle Entrate essendo ormai quasi in disuso la consegna cartacea presso gli Uffici Postali","wrong1":"no, è prevista la consegna cartacea presso gli Uffici Postali","wrong2":"si ma solo per le società","wrong3":"si ma solo per le persone fisiche"},{"id":1366,"paragraph":"Diritto tributario - 20) Gli obblighi strumentali del contribuente","question":"La dichiarazione dei redditi ha una natura giuridica di tipo:","correct":"è dichiarazione di scienza, un atto giuridico non negoziale con cui un soggetto dichiara la conoscenza che ha di un determinato fatto","wrong1":"è manifestazione di volontà e produce effetti assimilabili a quelli di una confessione giudiziale o stragiudiziale","wrong2":"è dichiarazione di scienza ma non è emendabile","wrong3":"è dichiarazione di scienza, tuttavia può essere emendata solo in particolari casi previsti dalla legge"},{"id":1367,"paragraph":"Diritto tributario - 21) L'indisponibilità dell'obbligazione e la c.d. compliance","question":"Secondo il principio di indisponibilità:","correct":"credito erariale ha il suo fondamento giuridico nella legge, in modo che una volta accertati i fatti ed applicate ad essi le norme, all'Amministrazione non restano spazi per privilegiare o sacrificare qualcuno degli interessi privati in conflitto","wrong1":"credito erariale ha il suo fondamento giuridico nel regolamento, in modo che una volta accertati i fatti ed applicate ad essi le norme, all'Amministrazione non restano spazi per privilegiare o sacrificare qualcuno degli interessi privati in conflitto","wrong2":"credito erariale ha il suo fondamento giuridico nella legge, in modo che una volta accertati i fatti ed applicate ad essi le norme, all'Amministrazione restano spazi per privilegiare o sacrificare qualcuno degli interessi privati in conflitto","wrong3":"credito erariale ha il suo fondamento giuridico nella legge, in modo che una volta accertati i fatti ed applicate ad essi le norme, all'Amministrazione non restano spazi per privilegiare qualcuno degli interessi privati in conflitto ma è consentito sacrificare alcuni interessi ove necessario"},{"id":1368,"paragraph":"Diritto tributario - 21) L'indisponibilità dell'obbligazione e la c.d. compliance","question":"Nell'ordinamento tributario un obbligo generalizzato è stato finalmente introdotto:","correct":"con il D.Lgs. n. 219/2023 all'art. 6-bis della L. n. 212/2000, secondo cui: «Salvo quanto previsto dal comma 2, tutti gli atti autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria sono preceduti, a pena di annullabilità, da un contraddittorio informato ed effettivo ai sensi del presente articolo...'","wrong1":"è sempre stato previsto nello statuto dei diritti del contribuente","wrong2":"con il D.Lgs. n. 219/2023 all'art. 6-bis della Costituzione, secondo cui:«Salvo quanto previsto dal comma 2, tutti gli atti autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria sono preceduti, a pena di annullabilità, da un contraddittorio informato ed effettivo ai sensi del presente articolo...'","wrong3":"con il D.Lgs. n. 219/2023 all'art. 6-bis della L. n. 212/2000, secondo cui:«Salvo quanto previsto dal comma 2, alcuni atti autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria sono preceduti, a pena di nullità, da un contraddittorio informato ed effettivo ai sensi del presente articolo...'"},{"id":1369,"paragraph":"Diritto tributario - 21) L'indisponibilità dell'obbligazione e la c.d. compliance","question":"Le numerose facoltà garantite ai privati dalla citata Legge n. 241/1990 in ambito tributario:","correct":"non subiscono deroghe nel diritto tributario","wrong1":"limitazioni volte ad escludere, in capo ai contribuenti, le numerose facoltà garantite ai privati dalla citata Legge n. 241/1990","wrong2":"possono essere derogate","wrong3":"sono talvolta derogate"},{"id":1370,"paragraph":"Diritto tributario - 22) Principi applicabili in fase di istruttoria e l'autotutela","question":"Il principio di proporzionalità:","correct":"è stato recepito nell'articolo 10 ter Statuto del contribuente","wrong1":"è stato recepito nell'articolo 10 della Costituzione","wrong2":"non è stato recepito da una norma interna ma è applicabile solo a livello giurisprudenzale","wrong3":"non si applica al diritto tributario"},{"id":1371,"paragraph":"Diritto tributario - 22) Principi applicabili in fase di istruttoria e l'autotutela","question":"Ai sensi dell'art. 7 dello statuto dei diritti del contribuente, gli atti dell'A.F. e dei concessionari della riscossione devono tassativamente indicare:","correct":"«a) l'ufficio presso il quale è possibile ottenere informazioni complete in merito all'atto notificato o comunicato e il responsabile del procedimento; b) l'organo o l'autorità amministrativa presso i quali è possibile promuovere un riesame anche nel merito dell'atto in sede di autotutela; c) le modalità, il termine, l'organo giurisdizionale o l'autorità amministrativa cui è possibile ricorrere in caso di atti impugnabili.»","wrong1":"l'ufficio presso il quale è possibile ottenere informazioni complete in merito all'atto notificato o comunicato e il responsabile del procedimento e le modalità, il termine, l'organo giurisdizionale o l'autorità amministrativa cui è possibile ricorrere in caso di atti impugnabili'","wrong2":"«a) l'ufficio presso il quale è possibile ottenere informazioni complete in merito all'atto notificato o comunicato e il responsabile del procedimento;b) l'organo o l'autorità amministrativa presso i quali ènon possibile promuovere un riesame anche nel merito dell'atto in sede di autotutela; c) le modalità, il termine, l'organo giurisdizionale o l'autorità amministrativa cui è possibile ricorrere in caso di atti impugnabili.»","wrong3":"«a) l'ufficio presso il quale è possibile ottenere informazioni complete in merito all'atto notificato o comunicato e il responsabile del procedimento;b) l'organo o l'autorità amministrativa presso i quali è possibile promuovere un riesame anche nel merito dell'atto in sede di autotutela; c) le modalità, ma non anche il termine e l'organo giurisdizionale o l'autorità amministrativa cui è possibile ricorrere in caso di atti impugnabili.»"},{"id":1372,"paragraph":"Diritto tributario - 22) Principi applicabili in fase di istruttoria e l'autotutela","question":"Quali tipologie di autotutela sono previste dal nostro ordinamento:","correct":"di tipo obbligatorio nelle ipotesi tassative di cui all'art. 10 quater della L. 212 del 2000. Fuori dai casi disciplinati dall'art. 10 quater della L. 212 del 2000 l'amministrazione finanziaria può comunque procedere all'annullamento in presenza degli elementi di cui all'art. 10 quinquies (autotutela facoltativa)","wrong1":"solo di tipo obbligatorio, l'A.F. è sempre tenuta a procedere in autotutela","wrong2":"di tipo obbligatorio e facoltativo ma solo per le ipotesi disciplinate dall'art. 10 quater della L. 212 del 2000","wrong3":"di tipo obbligatorio nelle ipotesi tassative di cui all'art. 10 quater della L. 212 del 2000. Fuori dai casi disciplinati dall'art. 10 quater della L. 212 del 2000 l'amministrazione finanziaria può comunque procedere all'annullamento previo parare del Presidente della Repubblica"},{"id":1373,"paragraph":"Diritto tributario - 23) I poteri istruttori della A.F.","question":"L'esercizio dei poteri istruttori può essere effettuato:","correct":"in via diretta, nei confronti del contribuente soggetto passivo dell'obbligazione tributaria oppure in via mediata, nei confronti di terzi con cui il contribuente soggetto a controllo abbia relazioni economico-professionali","wrong1":"solo in via diretta, nei confronti del contribuente soggetto passivo dell'obbligazione tributaria","wrong2":"solo in via mediata, nei confronti di terzi con cui il contribuente soggetto a controllo abbia relazioni economico-professionali","wrong3":"sempre in via diretta, nei confronti del contribuente soggetto passivo dell'obbligazione tributaria oppurein via mediata, su autorizzazione del direttore dell'Agenzia delle Entrate anche nei confronti di terzi con cui il contribuente soggetto a controllo abbia relazioni economico-professionali"},{"id":1374,"paragraph":"Diritto tributario - 23) I poteri istruttori della A.F.","question":"Nel caso di accesso ai locali destinati all'esercizio dell'attività commerciale è necessaria apposita autorizzazione, se sì quale:","correct":"per tali accessi è sufficiente l'autorizzazione del Dirigente dell'Ufficio procedente","wrong1":"non è necessaria alcuna autorizzazione, al contrario è necessaria l'autorizzazione nel caso di accesso a dimore private","wrong2":"per tali accessi è necessaria l'autorizzazione del PM","wrong3":"è sufficiente l'autorizzazione del Direttore di un ufficio dell'Agenzia delle Entrate"},{"id":1375,"paragraph":"Diritto tributario - 23) I poteri istruttori della A.F.","question":"L'ispezione e verifica sono:","correct":"sono attività istruttorie volte l'una al controllo della regolarità sostanziale l'altra al controllo degli elementi soggettivi ed oggettivi constatati nell'ambito dell'attività ispettiva","wrong1":"sono attività istruttorie volte l'una al controllo della regolarità formale l'altra al controllo degli elementi soggettivi ed oggettivi constatati nell'ambito dell'attività ispettiva","wrong2":"sono attività istruttorie identiche","wrong3":"sono attività processuali volte l'una al controllo della regolarità sostanziale l'altra al controllo degli elementi soggettivi ed oggettivi constatati nell'ambito dell'attività ispettiva"},{"id":1376,"paragraph":"Diritto tributario - 24) Diritti e garanzia del contribuente sottoposto a verifiche fiscali","question":"La disciplina i diritti e le garanzie del contribuente sottoposto a verifiche fiscali è delineata dalla fonte:","correct":"art. 12 della legge n. 212 del 27/07/2000 (c.d. Statuto dei Diritti del Contribuente)","wrong1":"art. 12 della Costituzione","wrong2":"non esiste una disposizione specifica che disciplina i diritti e le garanzie del contribuente sottoposto a verifiche fiscali","wrong3":"non esiste una disposizione specifica che disciplina i diritti e le garanzie del contribuente sottoposto a verifiche fiscali ma solo una pronuncia della Corte EDU"},{"id":1377,"paragraph":"Diritto tributario - 24) Diritti e garanzia del contribuente sottoposto a verifiche fiscali","question":"Il profilo del Garante dei contribuenti:","correct":"è un organo monocratico presente in ogni regione con il compito di tutelare i diritti del contribuente e garantire un rapporto di fiducia tra cittadini e Amministrazione finanziaria","wrong1":"è un organo collegiale presente in ogni regione con il compito di tutelare i diritti del contribuente e garantire un rapporto di fiducia tra cittadini e Amministrazione finanziaria","wrong2":"è un organo monocratico presente in ogni comune con il compito di tutelare i diritti del contribuente e garantire un rapporto di fiducia tra cittadini e Amministrazione finanziaria","wrong3":"è un organo monocratico presente in ogni regione con il compito di tutelare i diritti del contribuente ma non anche di garantire un rapporto di fiducia tra cittadini e Amministrazione finanziaria"},{"id":1378,"paragraph":"Diritto tributario - 24) Diritti e garanzia del contribuente sottoposto a verifiche fiscali","question":"All'esito della sentenza della Corte EDU nel caso Italgomme Pneumatici S.r.l.:","correct":"l'Italia deve riformare il quadro normativo relativo alle visite ispettive di natura fiscale compiute in aziende","wrong1":"l'Italia non deve riformare il quadro normativo relativo alle visite ispettive di naturafiscale compiute in aziende","wrong2":"l'Italia è premiata per il quadro normativo relativo alle visite ispettive di naturafiscale compiute in aziende","wrong3":"l'Italia può riformare quadro normativo relativo alle visite ispettive di naturafiscale compiute in aziende"},{"id":1379,"paragraph":"Diritto tributario - 25) Il controllo automatico e formale della dichiarazione","question":"In presenza di un controllo diverso da quello sostanziale:","correct":"in presenza del controllo formale delle dichiarazioni, questo si conclude con la richiesta delle somme dovute, senza la necessità che vengano emanati avvisi di accertamento","wrong1":"in presenza del controllo formale delle dichiarazioni, questo si conclude con la richiesta delle somma dovute e l'emanazione degli avvisi di accertamento","wrong2":"in presenza del controllo formale delle dichiarazioni, questo si conclude con la richiesta delle somma dovute e, nel caso in cui il valore superi 5.000 euro, l'emanazione degli avvisi di accertamento","wrong3":"in presenza del controllo formale delle dichiarazioni, questo si conclude con la richiesta delle somma dovute e, nel caso in cui il valore superi 50.000 euro, l'emanazione degli avvisi di accertamento"},{"id":1380,"paragraph":"Diritto tributario - 25) Il controllo automatico e formale della dichiarazione","question":"Se il contribuente riconosce la correttezza degli esiti del controllo automatizzato:","correct":"il contribuente che riconosce la correttezza degli esiti del controllo può regolarizzare la propria posizione pagando, entro un certo termine, una sanzione ridotta, oltre all'imposta oggetto della rettifica e i relativi interessi","wrong1":"può impugnali avanti alla Corte di Giustizia tributaria","wrong2":"il contribuente che riconosce la correttezza degli esiti del controllo può regolarizzare la propria posizione pagando, senza termini, una sanzione ridotta, oltre all'imposta oggetto della rettifica e i relativi interessi","wrong3":"il contribuente che riconosce la correttezza degli esiti del controllo può regolarizzare la propria posizione pagando, senza termini, la sanzione piena"},{"id":1381,"paragraph":"Diritto tributario - 25) Il controllo automatico e formale della dichiarazione","question":"Cosa prevede il controllo formale delle dichiarazioni dei redditi è effettuato ai sensi dell'articolo 36-ter del Dpr n. 600/1973:","correct":"che l'Agenzia verifichi che i dati esposti in dichiarazione siano conformi alla documentazione conservata dal contribuente e ai dati rilevabili nelle dichiarazioni presentate da altri soggetti o a quelli forniti da enti esterni","wrong1":"che l'Agenzia verifichi che i dati esposti in dichiarazione siano conformi a quelli relativi alla dichiarazione dell'anno precendete","wrong2":"che l'Agenzia verifichi che i dati esposti in dichiarazione siano conformi alla documentazione del contribuente anche se non conservata e ai dati rilevabili nelle dichiarazioni presentate da altri soggetti o a quelli forniti da enti esterni","wrong3":"che l'Agenzia verifichi che i dati esposti in dichiarazione siano conformi alle informazioni conservate nell'anagrafe tributario"},{"id":1382,"paragraph":"Diritto tributario - 26) Il processo verbale di constatazione e l'adesione","question":"Ogni attività istruttoria si conclude con la redazione di:","correct":"un verbale di verifica, che offre una descrizione analitica delle operazioni compiute dall'organo procedente e verbale di constatazione (pvc), nel quale vi è l'esposizione dei rilievi effettuati e l'individuazione delle sanzioni applicabili","wrong1":"verbale di verifica, che offre una descrizione analitica delle operazioni compiute dall'organo procedente","wrong2":"un verbale di verifica, che offre una descrizione sommaria delle operazioni compiute dall'organo procedente e verbale di constatazione (pvc), nel quale vi è l'esposizione dei rilievi effettuati e l'individuazione delle sanzioni applicabili","wrong3":"un verbale di verifica, che offre una descrizione analitica delle operazioni compiute dall'organo procedente e verbale di contestazione"},{"id":1383,"paragraph":"Diritto tributario - 26) Il processo verbale di constatazione e l'adesione","question":"Il contribuente può aderire al PVC:","correct":"sì, a seguito della riforma tributaria del 2024, il contribuente può aderire alle risultanze del PVC, entro 30 giorni dalla consegna","wrong1":"no, è ammessa solo l'adesione all'avviso di accertamento successivo","wrong2":"si, a seguito della riforma tributaria del 2024, il contribuente può aderire alle risultanze del PVC, entro 5 giorni dalla consegna","wrong3":"si, a seguito della riforma tributaria del 2024, il contribuente può aderire alle risultanze del PVC, entro 15 giorni dalla consegna"},{"id":1384,"paragraph":"Diritto tributario - 26) Il processo verbale di constatazione e l'adesione","question":"Nel caso in cui le contestazioni siano infondate:","correct":"il contribuente può presentare osservazioni e richieste all'Agenzia delle Entrate entro 60 giorni dalla notifica del pvc","wrong1":"il contribuente può presentare osservazioni e richieste all'Agenzia delle Entrate entro 10 giorni dalla notifica del pvc","wrong2":"il contribuente non può presentare osservazioni e richieste all'Agenzia delle Entrate fino alla notifica dell'avviso di accetamento","wrong3":"il contribuente può presentare osservazioni e richieste all'Agenzia delle Entrate entro 60 giorni dalla notifica del pvc ma solo nel caso in cui sia presente un errore materiale nei rilievi"},{"id":1385,"paragraph":"Diritto tributario - 27) L'avviso di accertamento","question":"Quali sono le caratteristiche dell'avviso di accertamento:","correct":"autoritarietà ovvero incide nella sfera del contribuente a prescindere dal consenso dello stesso; inoppugnabilità ovvero una volta decorsi i termini per l'impugnazione il provvedimento, pur se errato nel merito, diviene definitivo ed incontestabile); esecutorietà la parte pubblica che ha emanato il provvedimento ha la possibilità di portarlo ad esecuzione senza necessità di un previo vaglio giurisdizionale e di soddisfare in maniera coattiva i propri interessi","wrong1":"autoritarietà ovvero incide nella sfera del contribuente a prescindere dal consenso dello stesso; esecutorietà la parte pubblica che ha emanato il provvedimento ha la possibilità di portarlo ad esecuzione senza necessità di un previo vaglio giurisdizionale e di soddisfare in maniera coattiva i propri interessi","wrong2":"inoppugnabilità ovvero una volta decorsi i termini per l'impugnazione il provvedimento, pur se errato nel merito, diviene definitivo ed incontestabile); esecutorietà la parte pubblica che ha emanato il provvedimento ha la possibilità di portarlo ad esecuzione senza necessità di un previo vaglio giurisdizionale e di soddisfare in maniera coattiva i propri interessi","wrong3":"autoritarietà ovvero incide nella sfera del contribuente a prescindere dal consenso dello stesso; inoppugnabilità ovvero una volta decorsi i termini per l'impugnazione il provvedimento, pur se errato nel merito, diviene definitivo ed incontestabile)"},{"id":1386,"paragraph":"Diritto tributario - 27) L'avviso di accertamento","question":"Ai sensi dell'art. 7 della L. 212/2000, intitolato «Chiarezza e motivazione degli atti»:","correct":"gli atti dell'amministrazione finanziaria, autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria, sono motivati , a pena di annullabilità, indicando specificamente i presupposti, i mezzi di prova e le ragioni giuridiche su cui si fonda la decisione","wrong1":"gli atti dell'amministrazione finanziaria, anche se non autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria, sono motivati , a pena di annullabilità, indicando specificamente i presupposti, i mezzi di prova e le ragioni giuridiche su cui si fonda la decisione","wrong2":"gli atti dell'amministrazione finanziaria, anche se non autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria, sono motivati , a pena di nullità, indicando specificamente i presupposti, i mezzi di prova e le ragioni giuridiche su cui si fonda la decisione","wrong3":"gli atti dell'amministrazione finanziaria, autonomamente impugnabili dinanzi agli organi della giurisdizione tributaria, sono motivati , a pena di annullabilità, indicando i presupposti, ma non anche i mezzi di prova nè le ragioni giuridiche su cui si fonda la decisione"},{"id":1387,"paragraph":"Diritto tributario - 27) L'avviso di accertamento","question":"Quale natura ha l'avviso di accertamento:","correct":"è un atto di natura recettizia ed è quindi necessario che raggiunga - quantomeno - una legale conoscenza da parte del destinatario","wrong1":"è un atto di natura recettizia ed è quindi necessario che raggiunga una sostanziale conoscenza da parte del destinatario","wrong2":"è un atto di natura recettizia ed è quindi necessario che raggiunga - quantomeno - una legale conoscenza da parte del difensore","wrong3":"è un atto di natura semi-recettizia ed è quindi necessario che raggiunga - quantomeno - una legale conoscenza da parte del destinatario salvo che ricorrano motivi urgenti"},{"id":1388,"paragraph":"Diritto tributario - 28) I singoli di avvisi di accertamento","question":"Secondo il principio di unicità dell'avviso di accertamento:","correct":"accertamento ordinario può essere integrato con la notifica, entro il termine di decadenza, solo se sopravvengono nuovi elementi e alle condizioni previste dalla legge. L'art. 41-bis, D.P.R. n. 600/1973 in deroga disciplina l'accertamento parziale","wrong1":"accertamento ordinario può essere integrato sempre","wrong2":"accertamento ordinario può essere integrato con la notifica, senza termine di decadenza, se sopravvengono nuovi elementi e alle condizioni previste dalla legge. L'art. 41-bis, D.P.R. n. 600/1973 in deroga disciplina l'accertamento parziale","wrong3":"accertamento ordinario può essere integrato con la notifica, entro il termine di decadenza, solo se sopravvengono nuovi elementi e alle condizioni previste dalla legge. Non esiste alcuna deroga alla disciplina"},{"id":1389,"paragraph":"Diritto tributario - 28) I singoli di avvisi di accertamento","question":"L'avviso di accertamento catastale:","correct":"è una particolare tipologia di accertamento attraverso cui si predetermina in astratto il reddito medio dei terreni e dei fabbricati presenti sul territorio dello Stato (a seconda ovviamente della loro ubicazione), al fine di utilizzare tale valore in concreto in relazione ai singoli periodi di imposta","wrong1":"è una particolare tipologia di accertamento attraverso cui si predetermina l'imposta dei terreni e dei fabbricati presenti sul territorio dello Stato (a seconda ovviamente della loro ubicazione), al fine di utilizzare tale valore in concreto in relazione ai singoli periodi di imposta","wrong2":"è una particolare tipologia di accertamento attraverso cui si predetermina in astratto il reddito medio dei terreni ma non dei fabbricati presenti sul territorio dello Stato (a seconda ovviamente della loro ubicazione), al fine di utilizzare tale valore in concreto in relazione ai singoli periodi di imposta","wrong3":"è una particolare tipologia di accertamento attraverso cui si predetermina in astratto il reddito medio dei terreni e dei fabbricati presenti sul territorio dello Stato (a seconda ovviamente della loro ubicazione), al senza alcuna finalità tributaria"},{"id":1390,"paragraph":"Diritto tributario - 28) I singoli di avvisi di accertamento","question":"L'avviso di liquidazione:","correct":"ha natura di atto impositivo autoritativo, in caso di mancata impugnazione nei termini di legge si determinerebbe l'impossibilità di eventuali contestazioni postume, assumendo l'atto la sua definitività","wrong1":"ha natura di atto impositivo non autoritativo, in caso di mancata impugnazione nei termini di legge non si determinerebbe l'impossibilità di eventuali contestazioni postume, assumendo l'atto la sua definitività","wrong2":"non è un atto impugnabile","wrong3":"ha natura di atto impositivo autoritativo,tuttavia non è impugnabile"},{"id":1391,"paragraph":"Diritto tributario - 29) Le tipologie di avviso di accertamento","question":"L'accertamento sintetico:","correct":"è uno strumento di determinazione sintetica del reddito complessivo del contribuente, sulla base della capacità di spesa del medesimo. Appartenenza","wrong1":"intende rettificare le singole componenti del reddito risultanti dalla contabilità","wrong2":"è una metodologia di accertamento basata sulla considerazione puntuale di ogni singola categoria reddituale «con riferimento ai redditi delle varie categorie di cui all'art. 6 D.P.R. 597/1973».","wrong3":"è una metodologia di accertamento basata su presunzioni"},{"id":1392,"paragraph":"Diritto tributario - 29) Le tipologie di avviso di accertamento","question":"L'accertamento analitico-contabile:","correct":"intende rettificare le singole componenti del reddito risultanti dalla contabilità aziendale ritenuta, comunque, attendibile","wrong1":"desumere l'esistenza di attività non dichiarate o inesistenza di passività dichiarate","wrong2":"intende rettificare le singole componenti del reddito risultanti dalla contabilità aziendale ritenuta però inaffidabile","wrong3":"è uno strumento di determinazione sintetica del reddito complessivo del contribuente, sulla base della capacità di spesa del medesimo"},{"id":1393,"paragraph":"Diritto tributario - 29) Le tipologie di avviso di accertamento","question":"L'accertamento bancario:","correct":"è subordinato al rilascio di una previa 'autorizzazione' da parte dell'autorità amministrativa competente","wrong1":"è subordinato al rilascio di una previa 'autorizzazione' da parte del Presidente della Repubblica","wrong2":"non è subordinato al rilascio di alcuna autorizzazione","wrong3":"è subordinato al rilascio di una previa 'autorizzazione' da parte del PM"},{"id":1394,"paragraph":"Diritto tributario - 30) L'accertamento con adesione, acquiescenza e i vizi dell'atto","question":"L'accertamento con adesione è:","correct":"un 'accordo' tra contribuente e ufficio che può essere raggiunto sia prima dell'emissione di un avviso di accertamento, che dopo, sempre che il contribuente non presenti ricorso davanti al giudice tributario","wrong1":"un 'accordo' tra contribuente e ufficio che può essere raggiunto sia prima dell'emissione di un avviso di accertamento, che dopo, sempre che il contribuente presenti ricorso davanti al giudice tributario","wrong2":"un 'accordo' tra contribuente e il giudice","wrong3":"atto impositivo dell' ufficio"},{"id":1395,"paragraph":"Diritto tributario - 30) L'accertamento con adesione, acquiescenza e i vizi dell'atto","question":"Il pagamento delle somme dovute a seguito dell'accertamento con adesione è versato:","correct":"in unica soluzione, entro i 20 giorni successivi alla redazione dell'atto oppure in forma rateale in un massimo di 8 rate trimestrali di uguale importo delle quali la prima da versare entro il termine di 20 giorni dalla redazione dell'atto","wrong1":"in unica soluzione, entro i 5 giorni successivi alla redazione dell'atto oppurein forma rateale in un massimo di 8 rate trimestrali di uguale importo delle quali la prima da versare entro il termine di 5 giorni dalla redazione dell'atto","wrong2":"in unica soluzione, entro i 2 giorni successivi alla redazione dell'atto oppurein forma rateale in un massimo di 8 rate trimestrali di uguale importo delle quali la prima da versare entro il termine di 2 giorni dalla redazione dell'atto","wrong3":"in unica soluzione, entro i 90 giorni successivi alla redazione dell'atto oppurein forma rateale in un massimo di 8 rate trimestrali di uguale importo delle quali la prima da versare entro il termine di 90 giorni dalla redazione dell'atto"},{"id":1396,"paragraph":"Diritto tributario - 30) L'accertamento con adesione, acquiescenza e i vizi dell'atto","question":"Nel caso in cui il contribuente presti acquiescenza all'atto:","correct":"egli rinuncia ad impugnare l'avviso di accertamento o a presentare istanza di accertamento con adesione ed è tenuto a pagare le somme dovute entro 60 giorni con sanzioni ridotte ad 1/3","wrong1":"egli rinuncia ad impugnare l'avviso di accertamento ma non a presentare istanza di accertamento con adesione ed è tenuto a pagare le somme dovute entro 60 giorni con sanzioni ridotte ad 1/3","wrong2":"egli rinuncia ad impugnare l'avviso di accertamento e a presentare istanza di accertamento con adesione ed è tenuto a pagare le somme dovute entro 20 giorni con sanzioni ridotte ad 1/3","wrong3":"egli rinuncia ad impugnare l'avviso di accertamento e a presentare istanza di accertamento con adesione ed è tenuto a pagare le somme dovute entro 60 giorni senza alcuno sconto"},{"id":1397,"paragraph":"Diritto tributario - 31) Il sistema delle invalidità tributarie","question":"La riforma dello Statuto del Contribuente (Legge n 212/2000) attuata in ragione della Legge n 111/2023 Legge di Delega al Governo per la Riforma fiscale, con il Decreto Legislativo n 219/2023 introduce:","correct":"una disciplina organica sul regime di validità e sui vizi degli atti dell'Amministrazione finanziaria che include ipotesi di: i) 'nullità' in senso proprio (articolo 7-ter) ; ii) 'annullabilità' (articolo 7-bis), iii) 'irregolarità' (art. 7-quater) e una disciplina specifica del vizi dell'attività istruttoria (articolo 7-quinquies) e della notificazione degli atti impositivi e della riscossione (7-sexies)","wrong1":"una disciplina organica sul regime di validità e sui vizi degli atti dell'Amministrazione finanziaria che inlcude ipotesi di: i) 'nullità' in senso proprio (articolo 7-ter) e ii) 'annullabilità' (articolo 7-bis)","wrong2":"una disciplina organica sul regime di validità e sui vizi degli atti dell'Amministrazione finanziaria che inlcude ipotesi di: i) 'nullità' in senso proprio (articolo 7-ter) ;ii) 'irregolarità' (art. 7-quater) e una disciplina specifica del vizi dell'attività istruttoria (articolo 7-quinquies) e della notificazione degli atti impositivi e della riscossione (7-sexies)","wrong3":"una disciplina organica sul regime di validità e sui vizi degli atti dell'Amministrazione finanziaria che inlcude ipotesi di: 'annullabilità' (articolo 7-bis), iii) 'irregolarità' (art. 7-quater) e una disciplina specifica del vizi dell'attività istruttoria (articolo 7-quinquies) e della notificazione degli atti impositivi e della riscossione (7-sexies)"},{"id":1398,"paragraph":"Diritto tributario - 31) Il sistema delle invalidità tributarie","question":"Ai sensi dell'art. 7-bis della L. 212/2000:","correct":"gli atti dell'amministrazione finanziaria impugnabili dinanzi agli organi di giurisdizione tributaria sono annullabili per violazione di legge, ivi incluse le norme sulla competenza, sul procedimento, sulla partecipazione del contribuente e sulla validità degli atti. I motivi di annullabilità e di infondatezza dell'atto sono dedotti, a pena di decadenza, con il ricorso introduttivo del giudizio dinanzi alla Corte di giustizia tributaria di primo grado e non sono rilevabili d'ufficio","wrong1":"gli atti dell'amministrazione finanziaria impugnabili dinanzi agli organi di giurisdizione tributaria sono annullabili per violazione di legge, ivi incluse le norme sulla competenza, sul procedimento, sulla partecipazione del contribuente e sulla validità degli atti.I motivi di annullabilità e di infondatezza dell'atto sono dedotti, a pena di decadenza, entro 10 anni dalla notifica dell'atto","wrong2":"gli atti dell'amministrazione finanziaria impugnabili dinanzi agli organi di giurisdizione tributaria sono annullabili per violazione di legge, ivi incluse le norme sulla competenza, sul procedimento, sulla partecipazione del contribuente e sulla validità degli atti.I motivi di annullabilità e di infondatezza dell'atto sono dedotti, a pena di decadenza, con il ricorso introduttivo del giudizio dinanzi alla Corte di giustizia tributaria di primo grado e sono rilevabili d'ufficio","wrong3":"gli atti dell'amministrazione finanziaria impugnabili dinanzi agli organi di giurisdizione amministrativa sono annullabili per violazione di legge, ivi incluse le norme sulla competenza, sul procedimento, sulla partecipazione del contribuente e sulla validità degli atti.I motivi di annullabilità e di infondatezza dell'atto sono dedotti, a pena di decadenza, con il ricorso introduttivo del giudizio dinanzi alla Corte di giustizia tributaria di primo grado e non sono rilevabili d'ufficio"},{"id":1399,"paragraph":"Diritto tributario - 31) Il sistema delle invalidità tributarie","question":"Ai sensi dell'art. 7-ter:","correct":"gli atti dell'amministrazione finanziaria sono nulli se viziati per difetto assoluto di attribuzione, adottati in violazione o elusione di giudicato, ovvero se affetti da altri vizi di nullità qualificati espressamente come tali da disposizioni entrate in vigore successivamente al presente decreto. I vizi di nullità di cui al presente articolo possono essere eccepiti in sede amministrativa o giudiziaria, sono rilevabili d'ufficio in ogni stato e grado del giudizio e danno diritto alla ripetizione di quanto versato, fatta salva la prescrizione del credito","wrong1":"gli atti dell'amministrazione finanziaria sono nulli ù adottati in violazione o elusione di giudicato. I vizi di nullità di cui al presente articolo possono essere eccepiti in sede amministrativa o giudiziaria, sono rilevabili d'ufficio in ogni stato e grado del giudizio e danno diritto alla ripetizione di quanto versato, fatta salva la prescrizione del credito","wrong2":"gli atti dell'amministrazione finanziaria sono nulli se viziati per difetto assoluto di attribuzione, ovvero se affetti da altri vizi di nullità qualificati espressamente come tali da disposizioni entrate in vigore successivamente al presente decreto. I vizi di nullità di cui al presente articolo possono essere eccepiti in sede amministrativa o giudiziaria, sono rilevabili d'ufficio in ogni stato e grado del giudizio e danno diritto alla ripetizione di quanto versato, fatta salva la prescrizione del credito","wrong3":"gli atti dell'amministrazione finanziaria sono nulli se viziati per difetto assoluto di attribuzione, adottati in violazione o elusione di giudicato, ovvero se affetti da altri vizi di nullità qualificati espressamente come tali da disposizioni entrate in vigore successivamente al presente decreto. I vizi di nullità di cui al presente articolo non possono essere eccepiti in sede amministrativa o giudiziaria, sono rilevabili d'ufficio in ogni stato e grado del giudizio e danno diritto alla ripetizione di quanto versato, fatta salva la prescrizione del credito"},{"id":1400,"paragraph":"Diritto tributario - 32) L'illecito amministrativo tributario, il principio di legalità e di proporzionalità","question":"Al verificarsi dell'illecito tributario l'ordinamento può prevedere:","correct":"l'illecito tributario si distingue in amministrativo o penale in base al tipo di sanzione prevista ed è comunque punito","wrong1":"che non sia applicabile alcuna sanzione","wrong2":"l'applicazione della sanzione solo amministrativa","wrong3":"l'applicazione della sanzione solo penale"},{"id":1401,"paragraph":"Diritto tributario - 32) L'illecito amministrativo tributario, il principio di legalità e di proporzionalità","question":"I principi di legalità e di proporzionalità sono disciplinati dal Legislatore:","correct":"entrambi dall'art. 3 del D.lgs. 472/1997 come modificato a seguito del Decreto legislativo del 05/11/2024 n. 173","wrong1":"entrambi dall'art. 3 dello statuto dei diritti del contribuente come modificato a seguito del Decreto legislativo del 05/11/2024 n. 173","wrong2":"il principio di proporzionalità non trova espressa previsione normativa, quello di legalità invece dall'art. 3 del D.lgs. 472/1997","wrong3":"il principio di legalità non trova espressa previsione normativa, quello di proporzionalità invece dall'art. 3 del D.lgs. 472/1997"},{"id":1402,"paragraph":"Diritto tributario - 32) L'illecito amministrativo tributario, il principio di legalità e di proporzionalità","question":"Nell'applicazione del principio di proporzionalità delle sanzioni tributarie non penali, a chi spetta ricondurre a ragionevolezza l'eventuale non ponderata reazione punitiva dell'amministrazione finanziaria:","correct":"spetta al giudice tributario ricondurre a ragionevolezza l'eventuale non ponderata reazione punitiva dell'amministrazione finanziaria","wrong1":"spetta al legislatore ricondurre a ragionevolezza l'eventuale non ponderata reazione punitiva dell'amministrazione finanziaria","wrong2":"spetta al Presidente della Repubblica a ragionevolezza l'eventuale non ponderata reazione punitiva dell'amministrazione finanziaria","wrong3":"spetta al Garante dei diritti del contribuente ricondurre a ragionevolezza l'eventuale non ponderata reazione punitiva dell'amministrazione finanziaria"},{"id":1403,"paragraph":"Diritto tributario - 33) Sanzioni: principio di personalità ed elemento soggettivo","question":"Il principio di personalità implica che:","correct":"le sanzioni amministrative tributarie non possono essere trasmesse agli eredi","wrong1":"le sanzioni amministrative tributarie possono essere trasmesse agli eredi","wrong2":"le sanzioni amministrative tributarie possono essere trasmesse agli eredi ma solo di primo grado","wrong3":"le sanzioni amministrative tributarie possono essere trasmesse agli eredi ma solo se partenti diretti"},{"id":1404,"paragraph":"Diritto tributario - 33) Sanzioni: principio di personalità ed elemento soggettivo","question":"L'imputabilità e la colpevolezza sono due componenti relative al soggetto agente che devono:","correct":"essere entrambe valutate attentamente nell'ambito del sistema sanzionatorio tributario","wrong1":"possono essere entrambe valutate nell'ambito del sistema sanzionatorio tributario ma non sono caratteristiche essenziali","wrong2":"sono elementi del diritto penale ma non si applicano alle sanzioni amministrative tributarie","wrong3":"essere valutate solo al di sopra di una certa soglia determinata dalla legge"},{"id":1405,"paragraph":"Diritto tributario - 33) Sanzioni: principio di personalità ed elemento soggettivo","question":"Sono previste cause di non punibilità e nel caso dove è specificata la disciplina:","correct":"si, l'art. 6 del D.lgs. 472 del 1997 disciplina le cause di non punibilità, ovvero le circostanze al verificarsi delle quali l'agente non è punibile","wrong1":"non sono applicabili all'illecito tributario","wrong2":"si, l'art. 6 della Costituzione isciplina le cause di non punibilità, ovvero le circostanze al verificarsi delle quali l'agente non è punibile","wrong3":"si, tuttavia una disciplina delle cause di non punibilità non è espressamente prevista dal Legislatore"},{"id":1406,"paragraph":"Diritto tributario - 34) Concorso di persone, di violazioni e ravvedimento operoso","question":"L'art. 9 del D.Lgs. n. 472/1997 prevede che il concorso di più soggetti nel compimento di una violazione comporta:","correct":"per ciascuno dei partecipanti la punibilità del fatto con la sanzione prevista per la fattispecie violata","wrong1":"per il solo autore principale la punibilità del fatto con la sanzione prevista per la fattispecie violata","wrong2":"per ciascuno dei partecipanti la non punibilità del fatto","wrong3":"per ciascuno dei partecipanti la punibilità del fatto con la sanzione prevista per la fattispecie violata ma solo se vi è un legame di parentela tra i soggetti"},{"id":1407,"paragraph":"Diritto tributario - 34) Concorso di persone, di violazioni e ravvedimento operoso","question":"Chi con una sola azione od omissione, viola diverse disposizioni anche relative a tributi diversi (concorso formale) oppure con più azioni od omissioni, commette diverse violazioni formali della medesima disposizione (concorso materiale):","correct":"ai sensi dell'art. 12 del D.Lgs. n. 472/1997 è punito con la sanzione che dovrebbe infliggersi per la violazione più grave aumentata da un quarto fino al doppio (c.d. cumulo giuridico)","wrong1":"ai sensi dell'art. 12 dello statuto dei diritti del contribuente è punito con la sanzione che dovrebbe infliggersi per la violazione più grave aumentata da un quarto fino al doppio (c.d. cumulo giuridico)","wrong2":"ai sensi dell'art. 12 del D.Lgs. n. 472/1997 è punito con la somma delle singole sanzioni (c.d. cumulo materiale)","wrong3":"ai sensi dell'art. 12 del D.Lgs. n. 472/1997 è punito con la sanzione che dovrebbe infliggersi per la violazione più grave"},{"id":1408,"paragraph":"Diritto tributario - 34) Concorso di persone, di violazioni e ravvedimento operoso","question":"Il ravvedimento operoso:","correct":"consiste in un trattamento premiale in favore del contribuente che, pur avendo commesso una violazione, ponga rimedio attraverso la regolarizzazione degli adempimenti omessi o irregolarmente effettuali","wrong1":"consiste in un trattamento premiale in favore del contribuente che, pur avendo commesso una violazione, non ne pone più in futuro","wrong2":"consiste nella possibilità di rimediare attraverso la regolarizzazione degli adempimenti omessi o irregolarmente effettuali senza alcun trattamento premiale","wrong3":"consiste in un obbligo del contribuente che, pur avendo commesso una violazione, regolarizza gli adempimenti omessi o irregolarmente effettuali"},{"id":1409,"paragraph":"Diritto tributario - 35) Il procedimento di irrogazione delle sanzioni","question":"Il contribuente ha la possibilità di definire l'atto:","correct":"entro 60 giorni dalla notifica dell'atto di contestazione si può procedere con:  definizione agevolata dell'atto (pagamento di 1/3 della sanzione purché non sia inferiore a 1/3 del minimo edittale)","wrong1":"entro 90 giorni dalla notifica dell'atto di contestazione si può procedere con:definizione agevolata dell'atto (pagamento di 1/3 della sanzione purché non sia inferiore a 1/3 del minimo edittale)","wrong2":"entro 60 mesi dalla notifica dell'atto di contestazione si può procedere con:definizione agevolata dell'atto (pagamento di 1/3 della sanzione purché non sia inferiore a 1/3 del minimo edittale)","wrong3":"entro120 giorni dalla notifica dell'atto di contestazione si può procedere con:definizione agevolata dell'atto (pagamento di 1/3 della sanzione purché non sia inferiore a 1/3 del minimo edittale)"},{"id":1410,"paragraph":"Diritto tributario - 35) Il procedimento di irrogazione delle sanzioni","question":"Il procedimento accelerato (art. 16-bis del D.lg.s 472/97) si applica:","correct":"a specifiche violazioni tra cui: mancata, intempestiva o incompleta memorizzazione o trasmissione dei dati dei corrispettivi (art. 6, c. 2-bis, D. Lgs. n. 471/1997 > art. 2, c. 1, 1-bis e 2, D. Lgs. n. 127/2015) mancata o infedele emissione di ricevute fiscali, di scontrini fiscali o di documenti di trasporto (art. 6, c. 3, D. Lgs. 471/1997)","wrong1":"indistintamente a tutte le tipologie di sanzioni","wrong2":"ai controlli automatizzati e formali ex artt. 36-bis, 36- ter D.P.R. 600/1973 delle dichiarazioni dei redditi ed ai controlli automatizzati delle dichiarazioni IVA e in caso di IVA dichiarata e non versata ex art. 54-bis e art. 60, c. 6, D.P.R. 633/1972","wrong3":"ai controlli formali ex art 36- ter D.P.R. 600/1973 delle dichiarazioni dei redditi ed ai controlli automatizzati delle dichiarazioni IVA e in caso di IVA dichiarata e non versata ex art. 54-bis e art. 60, c. 6, D.P.R. 633/1972"},{"id":1411,"paragraph":"Diritto tributario - 35) Il procedimento di irrogazione delle sanzioni","question":"Nell'ipotesi di c.d. procedimento ultrasemplificato previsto dall'art. 17 co. 3:","correct":"insieme alle sanzioni è effettuata l'iscrizione a ruolo dei tributi","wrong1":"insieme alle sanzioni non è effettuata l'iscrizione a ruolo dei tributi","wrong2":"insieme alle sanzioni non è effettuata l'iscrizione a ruolo dei tributi salvo che si tratti di alcune tipologie di sanzioni espressamente indicate dal legislatore","wrong3":"insieme alle sanzioni può essere effettuata l'iscrizione a ruolo dei tributi"},{"id":1412,"paragraph":"Diritto tributario - 36) Le misure cautelari a favore dell'amministrazione finanziaria in ambito fiscale","question":"L'Amministrazione finanziaria, sulla base del combinato disposto dell'art. 27, comma 5, del D.L. 29 novembre 2008, n° 185 e dell'art. 22 del D. Lgs. 18 dicembre 1997, n° 472 può chiedere l'applicazione di misure cautelari, a garanzia dei crediti che vanta nei confronti dei contribuenti:","correct":"con apposita istanza indirizzata al presidente della Corte di Giustizia Tributaria di primo grado competente","wrong1":"con apposita istanza indirizzata al presidente della Corte di Cassazione","wrong2":"con apposita istanza indirizzata al presidente della Corte Costituzionale","wrong3":"con apposita istanza indirizzata alla segreteria della Corte di Giustizia Tributaria di primo grado competente"},{"id":1413,"paragraph":"Diritto tributario - 36) Le misure cautelari a favore dell'amministrazione finanziaria in ambito fiscale","question":"L'iscrizione di ipoteca ha il fine:","correct":"di garantire la pretesa tributaria costituendo una prelazione, attribuendo all'Agenzia il diritto (esercitabile anche nei confronti del terzo acquirente) di espropriare i beni vincolati a garanzia del suo credito e di essere soddisfatta con preferenza sul prezzo ricavato dall'espropriazione","wrong1":"di garantire la pretesa tributaria attribuendo all'Agenzia il diritto di uso dei beni vincolati a garanzia del suo credito","wrong2":"di garantire la pretesa tributaria attribuendo all'Agenzia il diritto di uso dei beni vincolati a garanzia del suo credito oppure in alternativa di essere soddisfatta con preferenza sul prezzo ricavato dall'espropriazione","wrong3":"di garantire la pretesa tributaria costituendo una prelazione, attribuendo al giudice il diritto (esercitabile anche nei confronti del terzo acquirente) di espropriare i beni vincolati a garanzia del suo credito e di essere soddisfatta con preferenza sul prezzo ricavato dall'espropriazione"},{"id":1414,"paragraph":"Diritto tributario - 36) Le misure cautelari a favore dell'amministrazione finanziaria in ambito fiscale","question":"Possono essere oggetto di sequestro:","correct":"beni mobili (compresi crediti, depositi bancari, quote sociali, azioni, obbligazioni, titoli, eccetera), beni mobili registrati, beni immobili, somme o cose dovute al debitore (nei limiti ammessi per il pignoramento) e, per espressa previsione normativa, anche l'azienda","wrong1":"beni mobili (esclusi crediti, depositi bancari, quote sociali, azioni, obbligazioni, titoli, eccetera), beni mobili registrati, beni immobili, somme o cose dovute al debitore (nei limiti ammessi per il pignoramento)","wrong2":"beni mobili (compresi crediti, depositi bancari, quote sociali, azioni, obbligazioni, titoli, eccetera) ma non beni mobili registrati, beni immobili, somme o cose dovute al debitore (nei limiti ammessi per il pignoramento) e, per espressa previsione normativa, anche l'azienda","wrong3":"beni mobili (compresi crediti, depositi bancari, quote sociali, azioni, obbligazioni, titoli, eccetera) ma non beni mobili registrati, beni immobili, somme o cose dovute al debitore (senza alcun limite) e, per espressa previsione normativa, anche l'azienda"},{"id":1415,"paragraph":"Diritto tributario - 37) Le sanzioni penali tributarie","question":"Secondo il principio di specialità:","correct":"quando uno stesso fatto è punito da una delle disposizioni che prevede sanzione penale e da una disposizione che prevede una sanzione amministrativa, si applica la disposizione speciale","wrong1":"quando uno stesso fatto è punito da una delle disposizioni che prevede sanzione penale e da una disposizione che prevede una sanzione amministrativa, si applica la disposizione amministrativa","wrong2":"quando uno stesso fatto è punito da una delle disposizioni che prevede sanzione penale e da una disposizione che prevede una sanzione amministrativa, non si applica alcuna disposizione","wrong3":"quando uno stesso fatto è punito da una delle disposizioni che prevede sanzione penale e da una disposizione che prevede una sanzione amministrativa, non si applica alcuna disposizione, salvo che il giudice ritenga di applicare la disposizione speciale"},{"id":1416,"paragraph":"Diritto tributario - 37) Le sanzioni penali tributarie","question":"Il principio ne bis in idem applicato al diritto tributario, garantisce che:","correct":"nessun contribuente possa essere sottoposto a una duplice sanzione o procedura per lo stesso fatto impositivo","wrong1":"tutti i contribuenti possano essere sottoposti a una duplice sanzione o procedura per lo stesso fatto impositivo","wrong2":"nessun contribuente possa essere sottoposto a una duplice sanzione o procedura per lo stesso fatto impositivo salvo espressa autorizzazione del giudice","wrong3":"nessun contribuente possa essere sottoposto a una duplice sanzione o procedura per lo stesso fatto impositivo salvo espressa autorizzazione del Presidente della Repubblica"},{"id":1417,"paragraph":"Diritto tributario - 37) Le sanzioni penali tributarie","question":"I principali reati tributari sono disciplinati:","correct":"dal D.lgs. n. 74 del 2000 sostituito da novembre 2024 dal D.Lgs. 5 novembre 2024, n. 173 «Testo unico delle sanzioni tributarie amministrative e penali»","wrong1":"dal D.lgs. n. 74 del 2000","wrong2":"dalla Costituzione","wrong3":"dal D.lgs. n. 472 del 1997 sostituito da novembre 2024 dallo statuto dei diritti del contribuente"},{"id":1418,"paragraph":"Diritto tributario - 38) La riscossione e l'adempimento spontaneo","question":"La riscossione dei tributi rappresenta:","correct":"l'ultima fase del procedimento impositivo finalizzata alla concreta acquisizione di risorse finanziarie per lo Stato e per gli enti pubblici","wrong1":"l'ultima fase del procedimento impositivo finalizzata all' utilizzo di risorse finanziarie per lo Stato e per gli enti pubblici","wrong2":"l'ultima fase del procedimento impositivo finalizzata alla concreta acquisizione di risorse finanziarie per lo Stato ma non per gli enti pubblici","wrong3":"l'ultima fase del procedimento impositivo finalizzata alla concreta acquisizione di risorse finanziarie per le società"},{"id":1419,"paragraph":"Diritto tributario - 38) La riscossione e l'adempimento spontaneo","question":"Nel meccanismo della ritenuta diretta:","correct":"il sostituto ha l'obbligo di attuare il prelievo nel momento in cui viene realizzato il presupposto d'imposta mentre il sostituito sopporta il prelievo e, quindi, è il soggetto inciso da detto prelievo","wrong1":"il sostituto ha l'obbligo di attuare il prelievo nel momento in cui viene realizzato il presupposto d'imposta mentre il sostituito sopporta il prelievo salvo che egli decida diversamente","wrong2":"il sostituito ha l'obbligo di attuare il prelievo nel momento in cui viene realizzato il presupposto d'imposta mentre il sostituto sopporta il prelievo e, quindi, è il soggetto inciso da detto prelievo","wrong3":"il sostituto ha la possibilità di attuare il prelievo nel momento in cui viene realizzato il presupposto d'imposta mentre il sostituito sopporta il prelievo e, quindi, è il soggetto inciso da detto prelievo"},{"id":1420,"paragraph":"Diritto tributario - 38) La riscossione e l'adempimento spontaneo","question":"I versamenti d'imposta possono essere effettuati:","correct":"in maniera parziale pagando gli acconti d'imposta","wrong1":"solo per intero","wrong2":"in maniera parziale pagando le ritenute d'imposta","wrong3":"in maniera parziale pagando gli acconti d'imposta, a condizione che il contribuente si dimostri adempiente"},{"id":1421,"paragraph":"Diritto tributario - 39) La riscossione coattiva e il rimborso","question":"La cartella di pagamento rappresenta:","correct":"l'atto riscossivo con cui si porta a conoscenza del contribuente il ruolo limitatamente alla partita iscritta a suo carico e si avanza la pretesa tributaria, come disciplinato dagli articoli 25 e 26 del D.P.R. 602/1973","wrong1":"l'atto riscossivo con cui si porta a conoscenza del contribuente il credito limitatamente alla partita iscritta a suo caricoù, come disciplinato dgli articoli 25 e 26 del D.P.R. 602/1973","wrong2":"l'atto riscossivo con cui si porta a conoscenza del contribuente l'imposta dovuta limitatamente alla partita iscritta a suo carico, come disciplinato dagli articoli 25 e 26 del D.P.R. 602/1973","wrong3":"l'atto riscossivo con cui si porta a conoscenza dell'amministrazione finanziaria il ruolo limitatamente alla partita iscritta a suo carico e si avanza la pretesa tributaria, come disciplinato dagli articoli 25 e 26 del D.P.R. 602/1973"},{"id":1422,"paragraph":"Diritto tributario - 39) La riscossione coattiva e il rimborso","question":"Trascorsi quale termine dalla notifica della cartella di pagamento, dell'accertamento esecutivo e dell'ingiunzione fiscale, se non vi è impugnazione questi atti diventano definitivi e titoli esecutivi ai fini delle azioni cautelari, conservative ed espropriative:","correct":"60 giorni","wrong1":"10 giorni","wrong2":"mai","wrong3":"6 mesi"},{"id":1423,"paragraph":"Diritto tributario - 39) La riscossione coattiva e il rimborso","question":"Alla domanda di rimborso presentata possono seguire due risultati:","correct":"la domanda è accolta. In questo caso, il rimborso sarà erogato con le modalità descritte nella sezione 'Come sono pagati i rimborsi'; la domanda è respinta. Potrà essere notificato un provvedimento di diniego avverso il quale il contribuente può presentare ricorso; anche nel caso di 'silenzio rifiuto', trascorsi 90 giorni dalla presentazione dell'istanza di rimborso, il contribuente può opporsi presentando ricorso (Home - Cittadini - Accertamenti e regolarizzazioni - Contenzioso e strumenti deflativi)","wrong1":"la domanda è accolta. In questo caso, il rimborso sarà erogato solo se il contribuente ne fa ulteriore richiesta; la domanda è respinta. Potrà essere notificato un provvedimento di diniego avverso il quale il contribuente può presentare ricorso; anche nel caso di 'silenzio rifiuto', trascorsi 90 giorni dalla presentazione dell'istanza di rimborso, il contribuente può opporsi presentando ricorso (Home - Cittadini - Accertamenti e regolarizzazioni - Contenzioso e strumenti deflativi).","wrong2":"la domanda è accolta. In questo caso, il rimborso sarà erogato con le modalità descritte nella sezione 'Come sono pagati i rimborsi'; la domanda è respinta. Potrà essere notificato un provvedimento di diniego avverso il quale il contribuente può presentare ricorso; anche nel caso di 'silenzio rifiuto', trascorsi 9 mesi giorni dalla presentazione dell'istanza di rimborso, il contribuente può opporsi presentando ricorso (Home - Cittadini - Accertamenti e regolarizzazioni - Contenzioso e strumenti deflativi)","wrong3":"la domanda è accolta. In questo caso, il rimborso sarà erogato con le modalità descritte nella sezione 'Come sono pagati i rimborsi'; la domanda è respinta. Potrà essere notificato un provvedimento di diniego avverso il quale il contribuente non può presentare ricorso; anche nel caso di 'silenzio rifiuto', trascorsi 90 giorni dalla presentazione dell'istanza di rimborso, il contribuente può opporsi presentando ricorso (Home - Cittadini - Accertamenti e regolarizzazioni - Contenzioso e strumenti deflativi)"},{"id":1424,"paragraph":"Diritto tributario - 40) I caratteri del processo tributario","question":"Il processo tributario:","correct":"può iniziare solo a seguito della notifica di un atto al contribuente che ne effettua l'impugnazione","wrong1":"può iniziare anche con un'azione di accertamento negativo da parte del contribuente.","wrong2":"può iniziare anche senza la notifica di un atto al contribuente","wrong3":"a volte, ma non sempre, può iniziare a seguito della notifica di un atto al contribuente."},{"id":1425,"paragraph":"Diritto tributario - 40) I caratteri del processo tributario","question":"Per ottenere l'annullamento, totale o parziale, dell'atto:","correct":"il contribuente deve sempre rispettare il termine decadenziale previsto dal D.Lgs. n. 546/1992","wrong1":"il contribuente può proporre, quando vuole, il ricorso.","wrong2":"il contribuente può decidere se rispettare o meno il termine decadenziale stabilito dal D.Lgs. n. 546/1992.","wrong3":"il contribuente, solo con riferimento ad alcune tipologie di contestazione, deve rispettare il termine decadenziale."},{"id":1426,"paragraph":"Diritto tributario - 40) I caratteri del processo tributario","question":"Con riferimento al rapporto tra cpc e codice del processo tributario:","correct":"i Giudici sono tenuti, «per quanto non disposto» e «per quanto compatibile», ad applicare le norme del codice di procedura civile","wrong1":"il giudice tributario può sempre applicare le norme del cpc.","wrong2":"il giudice tributario può scegliere quando applicare le norme del codice del cpc.","wrong3":"il giudice tributario non può mai applicare le norme del codice del cpc."},{"id":1427,"paragraph":"Diritto tributario - 41) La giurisdizione in materia tributaria","question":"La giurisdizione tributaria:","correct":"è generale, giacché riguarda tutte le controversie aventi ad oggetto tributi di ogni genere e specie, comunque denominati, nonché le sovraimposte e le addizionali, le sanzioni amministrative","wrong1":"è speciale, perché riguarda esclusivamente le controversie aventi ad oggetto le sanzioni amministrative","wrong2":"è speciale, perché riguarda esclusivamente le controversie aventi ad oggetto le sovraimposte","wrong3":"è speciale, perché riguarda esclusivamente le controversive aventi ad oggetto le addizionali"},{"id":1428,"paragraph":"Diritto tributario - 41) La giurisdizione in materia tributaria","question":"Il difetto di giurisdizione delle Corti di giustizia tributarie","correct":"è rilevabile, anche d'ufficio, in ogni stato e grado del processo","wrong1":"non è mai rilevabile","wrong2":"è rilevabile, solo su istanza di parte, in ogni stato e grado del processo","wrong3":"è rilevabile solo nel corso del primo grado"},{"id":1429,"paragraph":"Diritto tributario - 41) La giurisdizione in materia tributaria","question":"Le questioni incidentali non tributarie:","correct":"rientrano nella giurisdizione tributaria","wrong1":"non rientrano nella giurisdizione tributaria","wrong2":"rientrano nella giurisdizione ordinaria","wrong3":"rientrano nella giurisdizione penale"},{"id":1430,"paragraph":"Diritto tributario - 42) Gli atti impugnabili nel processo tributario","question":"Gli atti impugnabili in materia tributaria:","correct":"sono gli atti, in relazione ai quali il contribuente può instaurare un giudizio, rivolgendosi al giudice competente in materia fiscale, per ottenerne l'annullamento","wrong1":"sono gli atti che non si possono contestare in materia tributaria","wrong2":"sono gli atti per i quali non è possibile instuarare un giudizio","wrong3":"sono gli atti per i quali ci si può rivolgere al giudice ordinario"},{"id":1431,"paragraph":"Diritto tributario - 42) Gli atti impugnabili nel processo tributario","question":"Gli atti impugnabili in via differita:","correct":"sono impugnabili insieme con il primo atto impugnabile che sia successivamente notificato","wrong1":"sono impugnabili entro 60 giorni dalla loro notifica","wrong2":"sono impugnabili entro 90 giorni dalla loro notifica","wrong3":"non sono mai impugnabili"},{"id":1432,"paragraph":"Diritto tributario - 42) Gli atti impugnabili nel processo tributario","question":"Gli atti ad impugnazione facoltativa:","correct":"sono stati creati dalla giurisprudenza, in via interpretativa","wrong1":"sono disciplinati dall'art. 19 del D.Lgs. n. 546/1992.","wrong2":"sono disciplinati dallo Statuto dei Diritti del contribuente","wrong3":"non esistono"},{"id":1433,"paragraph":"Diritto tributario - 43) Il giudice tributario: la competenza e le pronunce","question":"La competenza territoriale delle Corti di giustizia tributarie di primo grado:","correct":"è determinata dalla sede dell'Ufficio e/o dell'Ente che ha emesso l'atto che si impugna","wrong1":"varia caso per caso","wrong2":"è stabilita in base ad una norma della Costituzione","wrong3":"è stabilita in base ad una norma del codice di procedura civile"},{"id":1434,"paragraph":"Diritto tributario - 43) Il giudice tributario: la competenza e le pronunce","question":"I provvedimenti del giudice tributario:","correct":"sono sentenza, ordinanza e decreto","wrong1":"possono essere solo sentenze e decreti","wrong2":"solo solo decreti","wrong3":"sono solo ordinanze e decreti"},{"id":1435,"paragraph":"Diritto tributario - 43) Il giudice tributario: la competenza e le pronunce","question":"Il decreto emesso dal Giudice tributario:","correct":"non è motivato, salvo sia espressamente previsto","wrong1":"non può essere, per nessuna ragione, motivato","wrong2":"è sempre motivato.","wrong3":"è motivato se l'organo giudicante lo ritiene opportuno"},{"id":1436,"paragraph":"Diritto tributario - 44) I più rilevanti principi processuali delle fonti interne sovranazionali","question":"La CEDU:","correct":"è una normativa interposta, giacché si trova, nel sistema della gerarchia delle fonti, tra Costituzione e norme interne","wrong1":"è una normativa interna, equiparata alle norme domestiche","wrong2":"è una normativa equiparabile alla Costituzione","wrong3":"non è inserita nella gerarchia delle fonti"},{"id":1437,"paragraph":"Diritto tributario - 44) I più rilevanti principi processuali delle fonti interne sovranazionali","question":"L'art. 1 del Protocollo aggiunto alla CEDU:","correct":"tutela il diritto di proprietà","wrong1":"tutela il diritto alla salute del contribuente","wrong2":"tutela il diritto ad un equo processo","wrong3":"tutela il diritto alla parità delle parti"},{"id":1438,"paragraph":"Diritto tributario - 44) I più rilevanti principi processuali delle fonti interne sovranazionali","question":"Il principio del giusto processo:","correct":"è disciplinato dall'art. 111 della Costituzione","wrong1":"è disciplinato dall'art. 53 della Costituzione","wrong2":"è disciplinato dall'art. 23 della Costituzione","wrong3":"è disciplinato dall'art. 25 della Costituzione"},{"id":1439,"paragraph":"Diritto tributario - 45) L'ordinamento delle Corti di giustizia tributarie","question":"Nel sistema tributario previgente (quando era in vigore la Legge del 20 marzo 1865 - c.d. All. E):","correct":"sulle controversie tributarie di diritto giudicava il giudice ordinario","wrong1":"sulle controversie tributarie di diritto giudicavano le Commissioni","wrong2":"sulle controversie tributarie di diritto giudicavano i giudici della Corte Costituzionale","wrong3":"sulle controversie tributarie di diritto giudicavano i giudici della Corte dei Conti"},{"id":1440,"paragraph":"Diritto tributario - 45) L'ordinamento delle Corti di giustizia tributarie","question":"La riforma del 1991-1992:","correct":"ha incrementato la giurisdizione del giudice speciale, mediante l'attribuzione allo stesso di nuove materie","wrong1":"ha ridotto la giurisdizione del giudice speciale, mediante l'eliminazione di alcune materie","wrong2":"ha lasciato intatta la giurisdizione del giudice speciale","wrong3":"non ha incrementato la giuridizione del giudice speciale"},{"id":1441,"paragraph":"Diritto tributario - 45) L'ordinamento delle Corti di giustizia tributarie","question":"La giurisdizione tributaria oggi è esercitata:","correct":"dalle Corti di giustizia tributaria di primo e secondo grado","wrong1":"dalle Commissioni tributarie priovinciali e regionali","wrong2":"dalla Corte Costituzionale","wrong3":"dal giudice amministrativo"},{"id":1442,"paragraph":"Diritto tributario - 46) Le parti","question":"La legitimatio ad causam:","correct":"è un presupposto processuale, necessario per giungere ad una decisione di merito","wrong1":"è un presupposto sostanziale, e non processuale","wrong2":"è un presupposto sostanziale, non necessario per giundere ad una decisione di merito","wrong3":"è un presupposto procedimentale"},{"id":1443,"paragraph":"Diritto tributario - 46) Le parti","question":"L'assistenza tecnica in giudizio:","correct":"è obbligatoria per la parte privata, ma non lo è per gli enti impositori, per l'agente della riscossione e per i gestori dei tributi locali","wrong1":"è sempre, e per tutte le tipologie di parti (privata e pubblica), obbligatoria","wrong2":"è sempre obbligatoria per gli enti impositori ma non lo è mai le parti private","wrong3":"è obbligatoria solo per l'Agente della Riscossione"},{"id":1444,"paragraph":"Diritto tributario - 46) Le parti","question":"La capacità di stare in giudizio:","correct":"è la capacità di agire riferita agli atti processuali","wrong1":"è l'incapacità di agire riferita agli atti processuali","wrong2":"è la capacità riferita agli atti procedimentali","wrong3":"è la capacità riferita all'emissione di provvedimenti amministrativi"},{"id":1445,"paragraph":"Diritto tributario - 47) Le prove","question":"In base alla natura dispositiva del processo tributario:","correct":"il giudice deve porre a fondamento della propria decisione le prove addotte dalle parti","wrong1":"il giudice non deve porre a fondamento della propria decisione le prove addotte dalle parti.","wrong2":"il giudice può, discrezionalmente, scegliere se porre o meno a fondamento della propria decisione le prove addotte dalle parti.","wrong3":"il giudice, solo se viene richiesto anche dall'Amministrazione finanziaria, deve porre a fondamento della propria decisione le prove addotte dalle parti."},{"id":1446,"paragraph":"Diritto tributario - 47) Le prove","question":"Nel processo tributario, il giuramento:","correct":"non è ammesso","wrong1":"è ammesso sempre.","wrong2":"è ammesso, in taluni casi.","wrong3":"è rimesso alla discrezionalità della parte ricorrente."},{"id":1447,"paragraph":"Diritto tributario - 47) Le prove","question":"La prova testimoniale scritta:","correct":"è ammessa dall'art. 7 del D.Lgs. n. 546/1992","wrong1":"non è mai ammessa.","wrong2":"è ammessa dall'art. 23 della Costituzione.","wrong3":"è ammessa dall'art. 53 della Costituzione."},{"id":1448,"paragraph":"Diritto tributario - 48) L'onere della prova","question":"Nel processo tributario, il giuramento:","correct":"l'Amministrazione è trattata come «attore in senso sostanziale», avendo emesso l'atto contestato in giudizio","wrong1":"l'Amministrazione è trattata come «attore in senso formale», avendo emesso l'atto contestato in giudizio.","wrong2":"l'Amministrazione non è trattata come «attore in senso sostanziale», avendo emesso l'atto contestato in giudizio.","wrong3":"l'Amministrazione è trattata come «convenuto in senso sostanziale», avendo emesso l'atto contestato in giudizio."},{"id":1449,"paragraph":"Diritto tributario - 48) L'onere della prova","question":"Ove l'Amministrazione rettifichi i costi:","correct":"è la stessa Amministrazione che deve fornire la prova","wrong1":"è il contribuente che deve fornire la prova.","wrong2":"sono il contribuente e l'Amministrazione che devono fornire, insieme, la prova.","wrong3":"è il giudice che deve fornire la prova."},{"id":1450,"paragraph":"Diritto tributario - 48) L'onere della prova","question":"L'art. 7, comma 5 bis, del D.Lgs. n. 546/1992:","correct":"attribuisce all'Amministrazione finanziaria la prova delle violazioni contestate","wrong1":"attribuisce al contribuente la prova delle violazioni contestate.","wrong2":"attribuisce al contribuente ed all'Amministrazione, insieme, la prova delle violazioni contestate.","wrong3":"non attribuisce all'Amministrazione finanziaria la prova delle violazioni contestate."},{"id":1451,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"L'art. 21 bis del D.Lgs. n. 74/2000:","correct":"riconosce efficacia alle sentenze penali assolutorie, rese al termine del dibattimento, nel processo tributario, compreso quello di Cassazione","wrong1":"non riconosce efficacia alle sentenze penali di assoluzione, da dibattimento, nel processo tributario.","wrong2":"riconosce efficacia alle sentenze penali assolutatorie, da dibattimento, nel processo tributario, ma solo in primo grado e non anche nei gradi successivi.","wrong3":"non riconosce efficacia alle sentenze penali assolutorie, rese al termine del dibattimento, nel giudizio in Cassazione."},{"id":1452,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"Secondo la sentenza n. 3800/2025 della Cassazione, la sentenza assolutoria penale dibattimentale produce effetti in materia tributaria ai fini dell'annullamento:","correct":"delle sole sanzioni","wrong1":"delle sole imposte","wrong2":"delle sanzioni e delle imposte","wrong3":"dei soli interessi"},{"id":1453,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"Prima dell'entrata in vigore del D.Lgs. n. 87 del 14 giugno 2024:","correct":"vigeva il principio del 'doppio binario' tra sistema penale e sistema tributario","wrong1":"non vigeva il principio del 'doppio binario' tra sistema penale e sistema tributario","wrong2":"vigeva il principio del 'doppio binario' tra sistema penale e sistema amministrativo","wrong3":"vigeva il principio del 'doppio binario' tra sistema penale e sistema del diritto del lavoro"},{"id":1454,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"Ai sensi dell'art. 20 del D.Lgs. n. 74/2000:","correct":"il procedimento amministrativo di accertamento ed il processo tributario non possono essere sospesi per la pendenza del procedimento penale","wrong1":"solo il procedimento amministrativo di accertamento tributario, e non anche il processo tributario, può essere sospeso per la pendenza del procedimento penale","wrong2":"il procedimento amministrativo di accertamento ed il processo tributario possono essere sospesi per la pendenza del procedimento penale","wrong3":"solo il processo tributario, e non anche il procedimento amministrativo di accertamento tributario, può essere sospeso per la pendenza del procedimento penale"},{"id":1455,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"L'art. 21 bis del D.Lgs. n. 74/2000:","correct":"esclude il decreto di archiviazione, la sentenza di non luogo a procedere e la sentenza da abbreviato","wrong1":"esclude il decreto di archiviazione e valorizza, invece, la sentenza di non luogo a procedere e la sentenza da abbreviato.","wrong2":"esclude la sentenza di non luogo a procedere e la sentenza da abbreviato e valorizza il decreto di archiviazione.","wrong3":"valorizza il decreto di archiviazione, la sentenza di non luogo a procedere e la sentenza da abbreviato."},{"id":1456,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"Sulla base dell'impostazione seguita dalla Cassazione nella pronuncia n. 3800/2025, in ragione della sentenza assolutoria dibattimentale penale:","correct":"vi sarebbe l'annullamento (automatico) delle sanzioni tributarie e l'autonoma e non condizionata valutazione, da parte del giudice tributario, del giudicato penale per le imposte","wrong1":"vi sarebbe l'annullamento (automatico) sia delle sanzioni che dell'imposta.","wrong2":"vi sarebbe l'annullamento (automatico) delle imposte e l'autonoma e non condizionata valutazione, da parte del giudice tributario, del giudicato penale per le sanzioni.","wrong3":"non vi sarebbe l'annullamento (automatico) né delle sanzioni e né dell'imposta."},{"id":1457,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"Con riferimento all'art. 530 cpp:","correct":"il primo comma riguarda il caso dell'assoluzione basata sulla prova positiva dell'innocenza dell'imputato ed il secondo comma la diversa ipotesi dell'assoluzione fondata sulla prova negativa della responsabilità dell'imputato","wrong1":"il secondo comma riguarda il caso dell'assoluzione basata sulla prova positiva dell'innocenza dell'imputato ed il primo comma la diversa ipotesi dell'assoluzione fondata sulla prova negativa della responsabilità dell'imputato.","wrong2":"sia primo che il secondo comma riguardano il caso dell'assoluzione basata sulla prova positiva dell'innocenza dell'imputato.","wrong3":"sia primo che il secondo comma riguardano il caso dell'assoluzione fondata sulla prova negativa della responsabilità dell'imputato."},{"id":1458,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"L'art. 21 bis del D.Lgs. n. 74/2000, secondo la dottrina:","correct":"sembra avere operato un'equiparazione tra le due formule (530 cpp, primo e secondo comma)","wrong1":"non sembra avere operato un'equiparazione tra le due formule (530 cpp, primo e secondo comma).","wrong2":"sembra riferirsi solo al primo comma dell'art. 530 cpp.","wrong3":"sembra riferirsi solo al secondo comma dell'art. 530 cpp."},{"id":1459,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"L'ordinanza di remissione n. 5714/2025 degli atti al Primo Presidente della Corte di Cassazione:","correct":"tenta di ricostruire lo 'stato dell'arte' sui rapporti tra processo tributario e processo penale, prima dell'intervento normativo; esamina il profilo della valenza degli effetti favorevoli nei confronti del contribuente derivanti dal giudicato penale, per le sole sanzioni ovvero per le sanzioni e l'imposta; pone il problema della rilevanza della sentenza penale assolutoria pronunciata ai sensi dell'art. 530 c.p.p., secondo comma","wrong1":"tenta, solo e soltanto, di ricostruire lo 'stato dell'arte' sui rapporti tra processo tributario e processo penale, prima dell'intervento normativo;","wrong2":"esamina, solo e soltanto, il profilo della valenza degli effetti favorevoli nei confronti del contribuente derivanti dal giudicato penale, per le sole sanzioni ovvero per le sanzioni e l'imposta.","wrong3":"pone, solo e soltato, il problema della rilevanza della sentenza penale assolutoria pronunciata ai sensi dell'art. 530 c.p.p., secondo comma."},{"id":1460,"paragraph":"Diritto tributario - 49) I rapporti tra il processo penale ed il processo tributario","question":"La necessità di attribuire la medesima valenza alle formule di assoluzione, previste al primo e secondo comma del richiamato art. 530 cpp:","correct":"rinviene un'importante conferma nel dettato normativo dell'art. 7, comma 5 bis, del D.Lgs. n. 546/1992","wrong1":"rinviene un'importante conferma nel dettato normativo dell'art. 23 della Costituzione.","wrong2":"non rinviene un'importante conferma nel dettato normativo dell'art. 7, comma 5 bis, del D.Lgs. n. 546/1992.","wrong3":"rinviene un'importante conferma nel dettato normativo dell'art. 53 della Costituzione."},{"id":1461,"paragraph":"Diritto tributario - 50) Introduzione del primo grado di giudizio","question":"Ai sensi dell'art. 18 del D.Lgs. n. 546/1992, il ricorso deve tassativamente indicare:","correct":"la Corte di Giustizia tributaria di primo grado a cui è diretto; il ricorrente e il suo legale rappresentante, la relativa residenza o sede legale o domicilio eventualmente eletto nel territorio dello Stato, il codice fiscale e l'indirizzo PEC; l'Ufficio nei cui confronti il ricorso è proposto; l'atto impugnato e l'oggetto della domanda (petitum); i motivi (causa petendi); la sottoscrizione del ricorrente o, quando previsto, del difensore del ricorrente; indicazione del valore della lite e la procura","wrong1":"il ricorrente e il suo legale rappresentante, la relativa residenza o sede legale o domicilio eventualmente eletto nel territorio dello Stato, il codice fiscale e l'indirizzo PEC; l'Ufficio nei cui confronti il ricorso è proposto; l'atto impugnato e l'oggetto della domanda (petitum); i motivi (causa petendi); la sottoscrizione del ricorrente o, quando previsto, del difensore del ricorrente; indicazione del valore della lite e la procura","wrong2":"la Corte di Giustizia tributaria di primo grado a cui è diretto; il ricorrente e il suo legale rappresentante, la relativa residenza o sede legale o domicilio eventualmente eletto nel territorio dello Stato, il codice fiscale e l'indirizzo PEC; l'Ufficio nei cui confronti il ricorso è proposto; la sottoscrizione del ricorrente o, quando previsto, del difensore del ricorrente; indicazione del valore della lite e la procura","wrong3":"la Corte di Giustizia tributaria di primo grado a cui è diretto; il ricorrente e il suo legale rappresentante, la relativa residenza o sede legale o domicilio eventualmente eletto nel territorio dello Stato, il codice fiscale e l'indirizzo PEC; l'Ufficio nei cui confronti il ricorso è proposto; l'atto impugnato e l'oggetto della domanda (petitum); i motivi (causa petendi); la sottoscrizione del ricorrente o, quando previsto, del difensore del ricorrente"},{"id":1462,"paragraph":"Diritto tributario - 50) Introduzione del primo grado di giudizio","question":"Entro quanto tempo deve essere proposto il ricorso:","correct":"il ricorso deve essere proposto, a pena di inammissibilità, entro sessanta giorni dalla data di notificazione dell'atto. In caso di rifiuto tacito della restituzione di tributi, sanzioni pecuniarie ed interessi o altri accessori non dovuti, può essere proposto dopo novanta giorni dalla domanda di restituzione (art. 21, D. Lgs. n° 546/92)","wrong1":"il ricorso deve essere proposto, a pena di inammissibilità, entro 6 mesi dalla data di notificazione dell'atto. In caso di rifiuto tacito della restituzione di tributi, sanzioni pecuniarie ed interessi o altri accessori non dovuti, può essere proposto dopo novanta giorni dalla domanda di restituzione (art. 21, D. Lgs. n° 546/92)","wrong2":"il ricorso deve essere proposto, a pena di inammissibilità, entro sessanta giorni dalla data di notificazione dell'atto. In caso di rifiuto tacito della restituzione di tributi, sanzioni pecuniarie ed interessi o altri accessori non dovuti, può essere proposto dopo 30 giorni dalla domanda di restituzione (art. 21, D. Lgs. n° 546/92)","wrong3":"il ricorso deve essere proposto, a pena di inammissibilità, entro novanta giorni dalla data di notificazione dell'atto. In caso di rifiuto tacito della restituzione di tributi, sanzioni pecuniarie ed interessi o altri accessori non dovuti, può essere proposto dopo sessanta giorni dalla domanda di restituzione (art. 21, D. Lgs. n° 546/92)"},{"id":1463,"paragraph":"Diritto tributario - 50) Introduzione del primo grado di giudizio","question":"Entro quanto tempo deve costituirsi in giudizio:","correct":"il ricorrente, entro trenta giorni dalla notifica del ricorso, deve costituirsi in giudizio depositando il fascicolo nella segreteria della Commissione ovvero trasmettendolo mediante il servizio postale (art. 22 , D. Lgs. n° 546/92)","wrong1":"il ricorrente, entro 3 mesi dalla notifica del ricorso, deve costituirsi in giudizio depositando il fascicolo nella segreteria della Commissione ovvero trasmettendolo mediante il servizio postale (art. 22 , D. Lgs. n° 546/92)","wrong2":"il ricorrente, entro 6 mesi dalla notifica del ricorso, deve costituirsi in giudizio depositando il fascicolo nella segreteria della Commissione ovvero trasmettendolo mediante il servizio postale (art. 22 , D. Lgs. n° 546/92)","wrong3":"il ricorrente, entro 60 giorni dalla notifica del ricorso, deve costituirsi in giudizio depositando il fascicolo nella segreteria della Commissione ovvero trasmettendolo mediante il servizio postale (art. 22 , D. Lgs. n° 546/92)"},{"id":1464,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Per sistema generale si intende:","correct":"Un insieme di elementi legati da un reciproco vincolo relazionale, unitariamente coordinati e integrati per il perseguimento di un obiettivo comune","wrong1":"Un insieme di elementi legati da un reciproco vincolo relazionale, diversamente coordinati e integrati per il perseguimento di un obiettivo comune","wrong2":"Un insieme di elementi legati da un reciproco vincolo relazionale, unitariamente coordinati e integrati per il perseguimento di un obiettivo diverso per ogni singolo elemento","wrong3":"Un insieme di elementi slegati tra loro, ma volti al perseguimento di un obiettivo comune"},{"id":1465,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Il sistema-azienda appartiene alla classe dei sistemi:","correct":"Socioeconomici","wrong1":"Ambientali","wrong2":"Fisici","wrong3":"Politici"},{"id":1466,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Secondo i nuovi schemi di analisi, il sistema-azienda viene riconosciuto come:","correct":"Un sistema complesso e non totalmente dominabile","wrong1":"Un sistema semplice e non totalmente dominabile","wrong2":"Un sistema semplice e totalmente dominabile","wrong3":"Un sistema complesso, ma totalmente dominabile"},{"id":1467,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"In relazione alla natura e al grado di astrazione, i sistemi si dividono in:","correct":"Sistemi fisici e sistemi socioeconomici","wrong1":"Sistemi deterministici e sistemi stocastici","wrong2":"Sistemi aperti e sistemi chiusi","wrong3":"Sistemi semplici e sistemi complessi"},{"id":1468,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Quale tra i seguenti non appartiene ai sub-sistemi di primo livello del sistema aziendale:","correct":"Subsistema dell'aspetto economico","wrong1":"Subsistema dell'organizzazione","wrong2":"Subsistema della gestione","wrong3":"Subsistema della rilevazione"},{"id":1469,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Il sub-sistema della rilevazione può essere anche definito come:","correct":"Subsistema informativo","wrong1":"Subsistema interattivo","wrong2":"Subsistema digitale","wrong3":"Subsistema finanziario"},{"id":1470,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Quale tra i seguenti sub-sistemi non deriva dalla scomposizione del sistema ambientale:","correct":"Subsistema della gestione","wrong1":"Subsistema dei mercati","wrong2":"Subsistema della innovazione","wrong3":"Subsistema dello stato delle istituzioni"},{"id":1471,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Il sub-sistema dell'innovazione attiene all'ambiente:","correct":"Tecnologico","wrong1":"Politico","wrong2":"Legislativo","wrong3":"Economico"},{"id":1472,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Il subsistema dei mercati attiene all'ambiente:","correct":"Economico","wrong1":"Politico","wrong2":"Legislativo","wrong3":"Tecnologico"},{"id":1473,"paragraph":"Economia delle aziende e delle PA - 1) Dal sistema in generale al sistema-azienda nei rapporti con il sistema-ambiente","question":"Quale tra i diversi sub-sistemi aziendali risente maggiormente dei condizionamenti ambientali:","correct":"Operativo","wrong1":"Legislativo","wrong2":"Economico","wrong3":"Tecnologico"},{"id":1474,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Di quale dei seguenti sub-sistemi si occupa la ragioneria:","correct":"subsistema del controllo","wrong1":"subsistema operativo","wrong2":"subsistema gestionale","wrong3":"subsistema organizzativo"},{"id":1475,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Quale dei seguenti sub-sistemi è oggetto di studio dell'economia aziendale:","correct":"subsistema organizzativo","wrong1":"subsistema informativo","wrong2":"subsistema del controllo","wrong3":"subsistema della rilevazione"},{"id":1476,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Quale tra i seguenti elementi che definiscono il subsistema organizzativo non attengono all'intera sfera aziendale:","correct":"la componente del personale","wrong1":"l'istituzione e la localizzazione dell'azienda","wrong2":"la struttura legale più conveniente da assumere","wrong3":"la dimensione aziendale ritenuta ideale"},{"id":1477,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Di norma, si decide di utilizzare come veste giuridica da assegnare al sistema-azienda quella di società in nome collettivo quando:","correct":"i soci sono in grado di procurarsi i mezzi e i capitali necessari, assumendosi i rischi della conduzione in modo illimitato e solidale","wrong1":"alcuni soci, disposti ad assumere la responsabilità illimitata per la loro ingerenza negli affari dell'impresa, non possiedono i capitali necessari, per cui si uniscono ad altri soci che conferiscono i mezzi occorrenti acquisendo la responsabilità limitata","wrong2":"i soci promotori non sono in possesso dell'intero capitale sociale e non intendono assumere una responsabilità illimitata, ricorrendo pertanto al capitale dei risparmiatori disposti a effettuare sottoscrizioni","wrong3":"i promotori si rivolgono a una ristretta cerchia di soggetti per integrare il proprio capitale di apporto"},{"id":1478,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Di norma, si decide di utilizzare come veste giuridica da assegnare al sistema-azienda quella di società in accomandita semplice quando:","correct":"alcuni soci, disposti ad assumere la responsabilità illimitata per la loro ingerenza negli affari dell'impresa, non possiedono i capitali necessari, per cui si uniscono ad altri soci che conferiscono i mezzi occorrenti acquisendo la responsabilità limitata","wrong1":"i soci sono in grado di procurarsi i mezzi e i capitali necessari, assumendosi i rischi della conduzione in modo illimitato e solidale","wrong2":"i soci promotori non sono in possesso dell'intero capitale sociale e non intendono assumere una responsabilità illimitata, ricorrendo pertanto al capitale dei risparmiatori disposti a effettuare sottoscrizioni","wrong3":"i promotori si rivolgono a una ristretta cerchia di soggetti per integrare il proprio capitale di apporto"},{"id":1479,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Di norma, si decide di utilizzare come veste giuridica da assegnare al sistema-azienda quella di società per azioni quando:","correct":"i soci promotori non sono in possesso dell'intero capitale sociale e non intendono assumere una responsabilità illimitata, ricorrendo pertanto al capitale dei risparmiatori disposti a effettuare sottoscrizioni","wrong1":"i soci sono in grado di procurarsi i mezzi e i capitali necessari, assumendosi i rischi della conduzione in modo illimitato e solidale","wrong2":"alcuni soci, disposti ad assumere la responsabilità illimitata per la loro ingerenza negli affari dell'impresa, non possiedono i capitali necessari, per cui si uniscono ad altri soci che conferiscono i mezzi occorrenti acquisendo la responsabilità limitata","wrong3":"i promotori si rivolgono a una ristretta cerchia di soggetti per integrare il proprio capitale di apporto"},{"id":1480,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"Di norma, si decide di utilizzare come veste giuridica da assegnare al sistema-azienda quella di società a responsabilità limitata quando:","correct":"i promotori si rivolgono a una ristretta cerchia di soggetti per integrare il proprio capitale di apporto","wrong1":"i soci sono in grado di procurarsi i mezzi e i capitali necessari, assumendosi i rischi della conduzione in modo illimitato e solidale","wrong2":"alcuni soci, disposti ad assumere la responsabilità illimitata per la loro ingerenza negli affari dell'impresa, non possiedono i capitali necessari, per cui si uniscono ad altri soci che conferiscono i mezzi occorrenti acquisendo la responsabilità limitata","wrong3":"i soci promotori non sono in possesso dell'intero capitale sociale e non intendono assumere una responsabilità illimitata, ricorrendo pertanto al capitale dei risparmiatori disposti a effettuare sottoscrizioni"},{"id":1481,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"In una azienda, le funzioni volitive sono quelle che:","correct":"interessano ogni ramo di attività e rappresentano il supremo governo amministrativo","wrong1":"interessano ogni ramo di attività ma non rappresentano il supremo governo amministrativo","wrong2":"svolgono un'azione di coordinamento e di accentramento ma in linea subordinata sia a quelle amministrative che a quelle tecniche","wrong3":"possono avere carattere più o meno qualificato o specializzato e richiedere personale più o meno specificamente preparato"},{"id":1482,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"In una azienda, le funzioni direttive sono quelle che:","correct":"svolgono un'azione di coordinamento e di accentramento ma in linea subordinata sia a quelle amministrative che a quelle tecniche","wrong1":"interessano ogni ramo di attività e rappresentano il supremo governo amministrativo","wrong2":"interessano ogni ramo di attività ma non rappresentano il supremo governo amministrativo","wrong3":"possono avere carattere più o meno qualificato o specializzato e richiedere personale più o meno specificamente preparato"},{"id":1483,"paragraph":"Economia delle aziende e delle PA - 2) Il subsistema organizzativo","question":"In una azienda, le funzioni esecutive sono quelle che:","correct":"possono avere carattere più o meno qualificato o specializzato e richiedere personale più o meno specificamente preparato","wrong1":"interessano ogni ramo di attività e rappresentano il supremo governo amministrativo","wrong2":"interessano ogni ramo di attività ma non rappresentano il supremo governo amministrativo","wrong3":"svolgono un'azione di coordinamento e di accentramento ma in linea subordinata sia a quelle amministrative che a quelle tecniche"},{"id":1484,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"Quale tra le seguenti attività non attiene alla gestione economica:","correct":"monetaria","wrong1":"tipica","wrong2":"accessoria","wrong3":"straordinaria"},{"id":1485,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"La gestione monetaria:","correct":"è volta a sincronizzare le entrate e le uscite monetarie generate dalle altre gestioni","wrong1":"conduce al collegamento interattivo tra il sistema aziendale e quello ambientale","wrong2":"riguarda l'impiego di risorse finanziarie momentaneamente eccedenti rispetto alle esigenze del normale funzionamento del sistema","wrong3":"comprende tutte le operazioni estranee ai normali accadimenti aziendali"},{"id":1486,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"La gestione economica tipica:","correct":"conduce al collegamento interattivo tra il sistema aziendale e quello ambientale","wrong1":"riguarda l'impiego di risorse finanziarie momentaneamente eccedenti rispetto alle esigenze del normale funzionamento del sistema","wrong2":"comprende tutte le operazioni estranee ai normali accadimenti aziendali","wrong3":"è volta a sincronizzare le entrate e le uscite monetarie generate dalle altre gestioni"},{"id":1487,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"La gestione economica accessoria:","correct":"riguarda l'impiego di risorse finanziarie momentaneamente eccedenti rispetto alle esigenze del normale funzionamento del sistema","wrong1":"conduce al collegamento interattivo tra il sistema aziendale e quello ambientale","wrong2":"comprende tutte le operazioni estranee ai normali accadimenti aziendali","wrong3":"è volta a sincronizzare le entrate e le uscite monetarie generate dalle altre gestioni"},{"id":1488,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"La gestione economica straordinaria:","correct":"comprende tutte le operazioni estranee ai normali accadimenti aziendali","wrong1":"conduce al collegamento interattivo tra il sistema aziendale e quello ambientale","wrong2":"riguarda l'impiego di risorse finanziarie momentaneamente eccedenti rispetto alle esigenze del normale funzionamento del sistema","wrong3":"è volta a sincronizzare le entrate e le uscite monetarie generate dalle altre gestioni"},{"id":1489,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"Il circuito della produzione:","correct":"ha inizio con l'acquisizione dei fattori produttivi e termina con la vendita dei prodotti","wrong1":"ha inizio con l'acquisizione dei fattori produttivi e termina con la combinazione dei prodotti","wrong2":"ha inizio con la vendita dei prodotti e termina con l'acquisizione dei fattori produttivi","wrong3":"ha inizio con la combinaizone dei fattori produttivi e termina con la vendita dei prodotti"},{"id":1490,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"Lo schema del circuito dei finanziamenti attinti con il vincolo del prestito:","correct":"ha inizio con l'accensione del debito e termina con la estinzione del debito","wrong1":"ha inizio con il conferimento del capitale di proprietà e termina con la restituzione del capitale proprio","wrong2":"ha inizio con la concessione del finanziamento e termina con la riscossione del finanziamento","wrong3":"ha inizio con l'acquisizione dei fattori produttivi e termina con la vendita dei prodotti"},{"id":1491,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"Lo schema del circuito dei finanziamenti attinti con il vincolo della proprietà:","correct":"ha inizio con il conferimento del capitale di proprietà e termina con la restituzione del capitale proprio","wrong1":"ha inizio con l'accensione del debito e termina con la estinzione del debito","wrong2":"ha inizio con la concessione del finanziamento e termina con la riscossione del finanziamento","wrong3":"ha inizio con l'acquisizione dei fattori produttivi e termina con la vendita dei prodotti"},{"id":1492,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"Lo schema del circuito dei finanziamenti concessi:","correct":"ha inizio con la concessione del finanziamento e termina con la riscossione del finanziamento","wrong1":"ha inizio con l'accensione del debito e termina con la estinzione del debito","wrong2":"ha inizio con il conferimento del capitale di proprietà e termina con la restituzione del capitale proprio","wrong3":"ha inizio con l'acquisizione dei fattori produttivi e termina con la vendita dei prodotti"},{"id":1493,"paragraph":"Economia delle aziende e delle PA - 3) Il subsistema gestionale","question":"I crediti e i debiti di finanziamento:","correct":"sorgono da operazioni di prestito concesso a terzi o ricevuto da terzi","wrong1":"attengono prettamente alla gestione economica tipica","wrong2":"sorgono per sostiuire temporaneamente la moneta","wrong3":"sorgono rispettivamente a seguito di dilazioni di pagamento concesse e ricevute"},{"id":1494,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"La finalità perseguita dal sistema-azienda è ravvedibile:","correct":"Nell'espletamento di un processo economico di trasformazione che consenta l'ottenimento di beni e/o servizi","wrong1":"Nell'espletamento di un processo non economico di trasformazione che consenta l'ottenimento di beni e/o servizi","wrong2":"Nell'espletamento di un processo non economico di combinazione che consenta l'ottenimento di beni e/o servizi","wrong3":"Nell'espletamento di un processo economico di trasformazione che consenta esclusivamente l'ottenimento di servizi"},{"id":1495,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"L'impresa può comunicare con i mercati con i quali entra in contatto in termini di:","correct":"Prezzi-costo e prezzi-ricavo","wrong1":"Solo di prezzi-costo","wrong2":"Solo di prezzi-ricavo","wrong3":"Prezzi-attività e prezzi-passività"},{"id":1496,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Il settore numerario accoglie:","correct":"Le variazioni del denaro e dei valori a esso assimilabili","wrong1":"I costi provocati dai processi di investimento e i ricavi generati dai processi di realizzo","wrong2":"Le variazione solo del denaro","wrong3":"Le variazione solo dei valori assimilabili al denaro"},{"id":1497,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Al settore degli investimenti e dei recuperi sono riconducibili:","correct":"I costi provocati dai processi di investimento e i ricavi generati dai processi di realizzo","wrong1":"Le variazione solo del denaro","wrong2":"Le variazione solo dei valori assimilabili al denaro","wrong3":"Le variazione del denaro e dei valori a esso assimilabili"},{"id":1498,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Il ciclo della produzione al momento dell'acquisizione dei fattori produttivi mostra:","correct":"Un flusso in uscita (outflow) dall'azienda di risorse monetarie (- denaro, + debiti di funzionamento, - crediti di funzionamento)","wrong1":"Un flusso in uscita (outflow) dall'azienda di risorse monetarie (+ denaro, - debiti di funzionamento, + crediti di funzionamento)","wrong2":"Un flusso in entrata (inflow) dall'azienda di risorse monetarie (+ denaro, - debiti di funzionamento, + crediti di funzionamento)","wrong3":"Sia un flusso in uscita (outflow) che un flusso in entrata (inflow)"},{"id":1499,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Il ciclo dei finanziamenti attinti con il vincolo del prestito al momento dell'accensione del debito di finanziamento si caratterizza:","correct":"Per un flusso in entrata di risorse monetarie correlato al ricavo, inteso in ampia accezione, di assunzione del prestito","wrong1":"Per un flusso in uscita di risorse monetarie correlato al costo di estinzione del prestito","wrong2":"Per un flusso in uscita di risorse monetarie","wrong3":"Sia per un flusso in uscita che per un flusso in entrata"},{"id":1500,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Per variazione finanziaria negativa intendiamo:","correct":"- denaro, + debiti di funzionamento, - crediti di funzionamento, + debiti di finanziamento, - crediti di finanziamento","wrong1":"Costi, - capitale netto, erogazione di utili","wrong2":"Ricavi, + capitale netto, reintegro di perdite","wrong3":"#ERROR!"},{"id":1501,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Per variazione finanziaria positiva intendiamo:","correct":"+ denaro, + crediti di funzionamento, - debiti di funzionamento, + crediti di finanziamento, - debiti di finanziamento","wrong1":"Costi, - capitale netto, erogazione di utili","wrong2":"Ricavi, + capitale netto, reintegro di perdite","wrong3":"- denaro, + crediti di funzionamento, - debiti di funzionamento, - crediti di finanziamento"},{"id":1502,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Per variazioni economiche negative intendiamo:","correct":"Costi, - capitale netto, erogazione di utili","wrong1":"Ricavi, + capitale netto, reintegro di perdite","wrong2":"- denaro, + crediti di funzionamento, - debiti di funzionamento, - crediti di finanziamento","wrong3":"+ denaro, + crediti di funzionamento, - debiti di funzionamento, + crediti di finanziamento, - debiti di finanziamento"},{"id":1503,"paragraph":"Economia delle aziende e delle PA - 4) Il subsistema gestionale (2 parte)","question":"Per variazione economiche positive intendiamo:","correct":"Ricavi, + capitale netto, reintegro di perdite","wrong1":"Costi, - capitale netto, erogazione di utili","wrong2":"- denaro, + crediti di funzionamento, - debiti di funzionamento, - crediti di finanziamento","wrong3":"+ denaro, + crediti di funzionamento, - debiti di funzionamento, + crediti di finanziamento, - debiti di finanziamento"},{"id":1504,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Il fabbisogno finanziario netto è generato:","correct":"dall'insieme degli investimenti in attesa di realizzo e delle risorse pronte a essere investite","wrong1":"esclusivamente dall'insieme degli investimenti in attesa di realizzo","wrong2":"esclusivamente dalle risorse pronte a essere investite","wrong3":"dai debiti assunti e dal capitale proprio conferito"},{"id":1505,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"In una prima approssimazione, il capitale lordo aziendale è dato:","correct":"dall'insieme dei fattori specifici e di quelli generici della produzione, che in un determinato istante sono a disposizione dell'azienda per lo svolgimento della gestione","wrong1":"dai soli fattori specifici che sono a disposizione dell'azienda per lo svolgimento della gestione","wrong2":"dai soli fattori generici della produzione, che sono a disposizione dell'azienda","wrong3":"dall'insieme dei fattori specifici e di quelli generici della produzione, che in un determinato istante sono a disposizione dell'azienda per lo svolgimento della gestione al netto del totale dei debiti assunti"},{"id":1506,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Il capitale netto aziendale è dato:","correct":"dall'insieme dei fattori specifici e di quelli generici della produzione, che in un determinato istante sono a disposizione dell'azienda per lo svolgimento della gestione al netto del totale dei debiti assunti","wrong1":"dai soli fattori specifici che sono a disposizione dell'azienda per lo svolgimento della gestione","wrong2":"dai soli fattori generici della produzione, che sono a disposizione dell'azienda","wrong3":"dall'insieme dei fattori specifici e di quelli generici della produzione, che in un determinato istante sono a disposizione dell'azienda per lo svolgimento della gestione"},{"id":1507,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Quale tra le seguenti non rappresenta una formula per il calcolo del reddito totale conseguito nell'intera vita aziendale:","correct":"Totale Attività acquisite meno Totale Attività vendute","wrong1":"Capitale finale meno Capitale iniziale","wrong2":"Totale ricavi conseguiti meno Totale costi conseguiti","wrong3":"Totale entrate meno Totale uscite di denaro"},{"id":1508,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Nel calcolo del reddito attribuibile ad un periodo intermedio di vita dell'impresa è necessario rigettare:","correct":"il solo principio della competenza temporale","wrong1":"il solo principio della competenza economica","wrong2":"sia il principio della competenza temporale che quello della competenza economica","wrong3":"in buona parte il principio della competenza temporale ed interamente quello della competenza economica"},{"id":1509,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"La struttura del reddito del primo periodo di vita di una impresa si chiude con la determinazione del:","correct":"risultato positivo (utile), ovvero negativo (perdita)","wrong1":"surplus ovvero deficit patrimoniale","wrong2":"avanzo ovvero disavanzo di gestione","wrong3":"valore aggiunto ovvero sottratto"},{"id":1510,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Al termine del primo periodo di vita di una impresa, nelle attività del settore finanziario è possibile trovare:","correct":"denaro, crediti di funzionamento, crediti di finanziamento","wrong1":"ricavi conseguiti in via anticipata da rinviare al futuro","wrong2":"debiti di funzionamento, debiti di finanziamento","wrong3":"costi sostenuti in via anticipata"},{"id":1511,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Al termine del primo periodo di vita di una impresa, nelle passività del settore finanziario è possibile trovare:","correct":"debiti di funzionamento, debiti di finanziamento","wrong1":"denaro, crediti di funzionamento, crediti di finanziamento","wrong2":"ricavi conseguiti in via anticipata da rinviare al futuro","wrong3":"costi sostenuti in via anticipata"},{"id":1512,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"La struttura del reddito riferita a un periodo intermedio di vita dell'impresa mostra:","correct":"una composizione qualitativa differente rispetto a quella assunta al termine sia del primo sia dell'ultimo periodo","wrong1":"una composizione qualitativa analoga rispetto a quella assunta al termine del primo periodo","wrong2":"una composizione qualitativa analoga rispetto a quella assunta al termine sia del primo sia dell'ultimo periodo","wrong3":"una composizione qualitativa analoga rispetto a quella assunta al termine dell'ultimo periodo"},{"id":1513,"paragraph":"Economia delle aziende e delle PA - 5) Il subsistema gestionale (parte 3)","question":"Il capitale economico rappresenta:","correct":"il valore riconosciuto all'azienda in funzionamento e viene determinato mediante l'attualizzazione del flusso di redditi futuri attesi","wrong1":"il valore riconosciuto all'azienda in funzionamento e viene determinato mediante la capitalizzazione del flusso di redditi passati","wrong2":"il valore riconosciuto all'azienda in liquidazione","wrong3":"il valore che scaturisce dal bilancio d'esercizio"},{"id":1514,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Il subsistema informativo viene anche definito:","correct":"subsistema di controllo","wrong1":"subsistema di gestione","wrong2":"subsistema di organizzazione","wrong3":"subsistema di attuazione"},{"id":1515,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Nel passaggio dalla raccolta dei dati grezzi alla produzione di informazioni grezze è possibile individuare il seguente percorso logico:","correct":"selezione dei dati-elaborazione dei dati-inserimento dei dati in procedimenti-trattamento dei dati","wrong1":"elaborazione dei dati-inserimento dei dati in procedimenti-trattamento dei dati-selezione dei dati","wrong2":"inserimento dei dati in procedimenti-trattamento dei dati-selezione dei dati-elaborazione dei dati","wrong3":"trattamento dei dati-selezione dei dati-elaborazione dei dati-inserimento dei dati in procedimenti"},{"id":1516,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Quale tra le seguenti non può essere annoverata tra le caratteristiche di rilievo dell'informazione:","correct":"la qualità dei dati da cui le informazioni sono elaborate","wrong1":"la dipendenza dalle esigenze dei vari centri decisionali","wrong2":"l'astrazione dai complessi fenomeni che influenzano una decisione","wrong3":"la quantità dei dati da cui le informazioni sono elaborate"},{"id":1517,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Nell'attività di analisi e di progettazione del sistema informativo non è possibile individuare la seguente fase:","correct":"astrazione dai complessi fenomeni che influenzano una decisione","wrong1":"analisi del subsistema operativo e individuazione dei collegati processi informativi e decisionali","wrong2":"individuazione e selezione dei dati elaborati idonei a produrre opportuni flussi informativi e delle procedure di trasmissione del messaggio (comunicazione)","wrong3":"definizione del grado di integrazione realizzabile nelle comunicazioni e nelle elaborazioni"},{"id":1518,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Il sistema informativo può essere definito come:","correct":"l'insieme coordinato di flussi informativi, ottenibili dall'applicazione di varie metodologie al processo di trasformazione di dati, miranti a supportare il sistema delle decisioni aziendali e a esercitare la funzione di comunicazione all'esterno","wrong1":"l'insieme coordinato di flussi informativi, ottenibili dall'applicazione di una singola e specifica metodologia al processo di trasformazione di dati, miranti a supportare il sistema delle decisioni aziendali e a esercitare la funzione di comunicazione all'esterno","wrong2":"l'insieme non coordinato di flussi informativi, ottenibili dall'applicazione di varie metodologie al processo di trasformazione di dati, miranti a supportare il sistema delle decisioni aziendali e a esercitare la funzione di comunicazione all'esterno","wrong3":"l'insieme non necessariamente coordinato di flussi informativi, ottenibili dall'applicazione di varie metodologie al processo di trasformazione di dati, miranti a supportare il sistema delle decisioni aziendali e a esercitare la funzione di comunicazione all'interno dell'azienda"},{"id":1519,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"I requisiti di un sistema informativo, che sanciscono la sua idoneità a supportare il processo decisione-azione sono:","correct":"selettività, elasticità, affidabilità, convenienza e accettabilità","wrong1":"selettività, autonomia, affidabilità, convenienza e accettabilità","wrong2":"selettività, elasticità, economicità, convenienza e accettabilità","wrong3":"selettività, elasticità, economicità, convenienza e coordinazione sistemica"},{"id":1520,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Il sistema informativo integrato concerne:","correct":"i flussi informativi sia verticali che orizzontali","wrong1":"solo i flussi informativi verticali","wrong2":"solo i flussi informativi orizzontali","wrong3":"i flussi informativi sia verticali che obliqui"},{"id":1521,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Per sistema informativo si intende:","correct":"quell'insieme di procedure contabili e matematico-statistiche, attuate con strumenti elettronici autoregolanti, che contengano gli aspetti qualitativi e quantitativi dell'analisi di fenomeni conoscitivi dell'andamento aziendale","wrong1":"quell'insieme di procedure esclusivamente contabili, attuate con strumenti elettronici autoregolanti, che contengano gli aspetti qualitativi e quantitativi dell'analisi di fenomeni conoscitivi dell'andamento aziendale","wrong2":"quell'insieme di procedure esclusivamente matematico-statistiche, attuate con strumenti elettronici autoregolanti, che contengano gli aspetti qualitativi e quantitativi dell'analisi di fenomeni conoscitivi dell'andamento aziendale","wrong3":"quell'insieme di procedure extracontabili e matematico-probabilistiche, attuati con strumenti elettronici autoregolanti, che contengano gli aspetti qualitativi e quantitativi dell'analisi di fenomeni conoscitivi dell'andamento aziendale"},{"id":1522,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Il contenuto del sistema informativo risulta essere:","correct":"più ampio di quello del subsistema delle rilevazioni aziendali","wrong1":"meno ampio di quello del subsistema delle rilevazioni aziendali","wrong2":"perfettamente coincidente con quello del subsistema delle rilevazioni aziendali","wrong3":"perfettamente coincidente con quello del subsistema delle rilevazioni extracontabili"},{"id":1523,"paragraph":"Economia delle aziende e delle PA - 6) Il subsistema del controllo","question":"Un sistema informativo può definirsi progredito quando:","correct":"trasmette i dati raccolti utilizzando appropriati e moderni mezzi di trasmissione e di elaborazione","wrong1":"trasmette i dati raccolti a prescindere dai mezzi di trasmissione e di elaborazione utilizzati","wrong2":"trasmette i dati raccolti entro un periodo corrispondente a 12 mesi","wrong3":"trasmette i dati raccolti entro un periodo corrispondente a 6 mesi"},{"id":1524,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Quale norma fornisce una definizione esauriente di Amministrazioni Pubbliche:","correct":"il D.lgs 165/2001","wrong1":"la Costituzione italiana","wrong2":"il D.lgs 150/2009","wrong3":"nessuna norma fornisce tale definizione"},{"id":1525,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Il Sistema europeo dei conti nazionali cosa consente di effettuare:","correct":"consente di effettuare comparazioni internazionali","wrong1":"consente di definire l'ammontare dei debiti degli enti","wrong2":"consente di analizzare benchmarking tra i vari enti","wrong3":"consente di effettuare elaborazioni statistiche"},{"id":1526,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Nella finanza pubblica da cosa è dato il saldo corrente:","correct":"dalle entrate correnti - le uscite correnti","wrong1":"dalle entrate totali - le uscite totali","wrong2":"dal saldo tra entrate di cassa ed uscite di cassa","wrong3":"dall'indebitamento netto"},{"id":1527,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Nella finanza pubblica da cosa è dato il saldo in conto capitale:","correct":"dalle entrate in c/capitale - uscite in c/capitale","wrong1":"dalle entrate correnti - le uscite correnti","wrong2":"dall'indebitamento netto","wrong3":"dal saldo tra entrate di cassa ed uscite di cassa"},{"id":1528,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Nella finanza pubblica da cosa è dato il saldo primario:","correct":"da entrate totali - uscite totali al netto degli interessi","wrong1":"dalle entrate correnti - le uscite correnti","wrong2":"dalle entrate in c/capitale - uscite in c/capitale","wrong3":"dall'indebitamento netto"},{"id":1529,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Nella finanza pubblica da cosa è dato l'indebitamento netto:","correct":"dall'entrate totali - uscite totali","wrong1":"dalle entrate in c/capitale - uscite in c/capitale","wrong2":"dall'indebitamento netto","wrong3":"dalle entrate correnti - le uscite correnti"},{"id":1530,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Cosa sono le Imprese Pubbliche Nazionali:","correct":"organismi pubblici nazionali che producono beni e servizi di pubblica utilità destinati alla vendita","wrong1":"organismi pubblici nazionali che non producono beni e servizi","wrong2":"organismi pubblici nazionali che producono beni e servizi non destinati alla vendita","wrong3":"sono sostanzialmente le Amministrazioni Centrali"},{"id":1531,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Cosa compone il Settore Pubblico Allargato:","correct":"è dato dal Settore delle Amministrazioni Pubbliche + il Settore Extra Amministrazioni Pubbliche","wrong1":"è dato dalle Public Utilities","wrong2":"è dato dall'Amministrazione Centrale","wrong3":"organismi pubblici nazionali che non producono beni e servizi"},{"id":1532,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Cosa sono le Imprese Pubbliche Locali:","correct":"organismi pubblici locali che producono beni e servizi di pubblica utilità destinati alla vendita","wrong1":"sono sostanzialmente le Amministrazioni Centrali","wrong2":"organismi pubblici locali che producono beni e servizi non destinati alla vendita","wrong3":"organismi pubblici nazionali che non producono beni e servizi"},{"id":1533,"paragraph":"Economia delle aziende e delle PA - 7) Le PA in una prospettiva economico-aziendale","question":"Cosa sono le Amministrazioni Pubbliche:","correct":"organismi pubblici nazionali e locali che producono beni e servizi di pubblica utilità non destinati alla vendita","wrong1":"organismi pubblici locali che producono beni e servizi non destinati alla vendita","wrong2":"organismi pubblici nazionali che non producono beni e servizi","wrong3":"sono sostanzialmente le Amministrazioni Centrali"},{"id":1534,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Dove si è sviluppato inizialmente l'orientamento manageriale nel settore pubblico:","correct":"negli USA","wrong1":"in Giappone","wrong2":"in Europa","wrong3":"in Italia"},{"id":1535,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Quale autore dimostra la dimostra la sostanziale non scientificità dei principi di amm.ne:","correct":"simon","wrong1":"taylor","wrong2":"fayol","wrong3":"weber"},{"id":1536,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Quale è la finalità ultima del New Public Management:","correct":"la responsabilizzazione sui risultati conseguiti","wrong1":"l'introduzione del controllo di gestione nel settore pubblico","wrong2":"lo sviluppo di processi formativi del personale","wrong3":"la privatizzazione del settore pubblico"},{"id":1537,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Il New Public Management cosa auspica nei rapporti tra organi di governo ed organi amministrativi:","correct":"la divisione nell'attribuzione delle funzioni tra organi di governo ed organi amministrativi","wrong1":"non tratta in alcun modo tale argomento","wrong2":"la gestione alternata delle funzioni tra organi di governo ed organi amministrativi","wrong3":"la comune attribuzione delle funzioni tra organi di governo ed organi amministrativi"},{"id":1538,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Il Public performance management come si realizza:","correct":"riconoscendo la discrezionalità all'azione del management","wrong1":"prevedendo concorsi pubblici per l'assunzione del personale","wrong2":"assicurando la formazione del management","wrong3":"assicurando l'adozione di contratti di lavoro di tipo privato"},{"id":1539,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Cosa comporta l'adozione della discrezionalità all'azione del management:","correct":"la verifica costante del rapporto tra performance conseguita e obiettivo di performance","wrong1":"la responsabilizzazione sull'output del processo operativo","wrong2":"la responsabilizzazione sulle procedure organizzative","wrong3":"la verifica costante del vincolo di bilancio"},{"id":1540,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Cosa sono gli indicatori:","correct":"misure capaci di fornire informazioni sintetiche e segnaletiche su singoli aspetti dei fenomeni gestionali","wrong1":"misure capaci di fornire informazioni sulle scelte gestionali da adottare","wrong2":"sono algoritmi collegati alle procedure organizzative","wrong3":"riferimenti gestionali stabiliti dal legislatore"},{"id":1541,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Cosa rende possibile il monitoraggio dell'attività del management pubblico:","correct":"l'adozione di un sistema informativo dedicato","wrong1":"l'adozione del bilancio","wrong2":"l'adozione di procedure amministrative","wrong3":"l'adozione di una gestione per processi"},{"id":1542,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Quando va misurata la performance:","correct":"in tutti i distinti momenti del processo di produzione/erogazione del servizio","wrong1":"prima di realizzare i processi di produzione","wrong2":"in sede di chiusura del bilancio","wrong3":"all'inizio ed al termine del processo di produzione/erogazione del servizio"},{"id":1543,"paragraph":"Economia delle aziende e delle PA - 8) Il management pubblico","question":"Cosa si intende per valutazione dell'outcome:","correct":"la valutazione del risultato di una prestazione","wrong1":"la valutazione dell'efficienza dei dirigenti","wrong2":"la valutazione fatta dal decisore politico","wrong3":"la valutazione fatta dal legislatore"},{"id":1544,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Cosa si intende per Pianificazione:","correct":"è il processo mediante il quale sono definiti gli obiettivi, le politiche e gli assetti delle combinazioni economiche dell'azienda","wrong1":"è il processo di definizione del budget","wrong2":"è il processo di analisi dei processi aziendali ed individuazione delel criticità","wrong3":"è il processo di analisi degli investimenti aziendali"},{"id":1545,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Cosa si intende per Programmazione:","correct":"i processi di programmazione assegnano alle unità organizzative gli obiettivi da realizzare in un certo arco temporale, nonché le rispettive risorse","wrong1":"si intende i processi di analisi degli investimenti da realizzari e la scelta delle relative fonti","wrong2":"si intende i processi di attribuzione delle risorse alle diverse unità aziendali","wrong3":"i processi di analisi e valutazione delle alternative strategiche che l'azienda ha a disposizione"},{"id":1546,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Quali ruoli può assumere la Regione rispetto alle Aziende Sanitarie pubbliche:","correct":"authority - regolatore - strategico - operativo","wrong1":"regolatore - strategico - neutrale - pubblico","wrong2":"il ruolo dipende dalle condizioni di indebitamento delle aziende sanitarie pubbliche","wrong3":"strategico - dirigistico"},{"id":1547,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Il sistema sanitario regionale secondo Mintzberg e Waters in quali tipologie di sistemi può farsi rientrare:","correct":"nei sistemi di pianificazione flessibili","wrong1":"nei sistemi a pianificazione rigidi","wrong2":"nei sistemi pubblici","wrong3":"nei sistemi autopoietici"},{"id":1548,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Il sistema di pianficazione definito da Mintzberg e Waters per il sistema sanitario regionale come è stato anche definito:","correct":"umbrella strategies","wrong1":"strategic management","wrong2":"for profit","wrong3":"public management"},{"id":1549,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"In quale tipo di sistema regionale le aziende sanitarie sono particolarmente libere:","correct":"authority","wrong1":"regolatore","wrong2":"strategico","wrong3":"operativo"},{"id":1550,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"In quale tipo di sistema regionale le aziende sanitarie non sono particolarmente libere:","correct":"operativo","wrong1":"authority","wrong2":"regolatore","wrong3":"strategico"},{"id":1551,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Quali autori hanno definito il concetto di Umbrella Strategy:","correct":"mintzberg e waters","wrong1":"lega e longo","wrong2":"mintzberg e longo","wrong3":"longo e lega"},{"id":1552,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Qual è il fattore che può condizionare molto la libertà strategica delle Aziende Sanitarie:","correct":"indebitamento","wrong1":"politica","wrong2":"formazione manageriale","wrong3":"le immobilizzazioni"},{"id":1553,"paragraph":"Economia delle aziende e delle PA - 9) La discrezionalità strategica delle AP: il caso delle aziende sanitarie","question":"Le Aziende Sanitarie pubbliche possono avere autonomia strategica:","correct":"hanno sempre degli spazi di autonomia","wrong1":"mai","wrong2":"hanno sempre piena libertà strategica","wrong3":"solo negli stati esteri"},{"id":1554,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Nel passato, quali fattori rendevano, oltre a quelli sociali, l'esigenza per un settore di istituire delle public utilities:","correct":"l'esistenza di processi produttivi e commerciali soggetti a particolari condizioni naturali, economico-finanziarie e tecnologiche","wrong1":"l'espressa previsione del legislatore fatta con leggi","wrong2":"la salvaguardia dell'occupazione","wrong3":"l'esigenza di evitare situazioni di eccessiva concorrenza"},{"id":1555,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Le condizioni gestionali tipiche del settore delle public utilities quali sono:","correct":"rilevanti investimenti finanziari e una prevalenza di costi di struttura e fissi sui costi totali","wrong1":"rilevanti costi per le risorse umane occupate","wrong2":"l'impossibilità di poter realizzare controlli sull'efficienza economica","wrong3":"l'espressa previsione del legislatore fatta con leggi"},{"id":1556,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Le condizioni di monopolio naturale, in genere, come si caratterizzavano sotto l'aspetto economico:","correct":"la forte decrescenza dei costi e costi marginali molto bassi e tendenzialmente nulli","wrong1":"la presenza di costi medi e costi marginali crescenti","wrong2":"la presenza di costi variabili molto elevati","wrong3":"la presenza di elevati costi del personale"},{"id":1557,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"L'esistenza di economie di scala e, nel caso in cui venivano offerti più servizi, di economie di scopo, nel passato cosa determinava per le attività economiche:","correct":"la preferenza per il monopolio naturale","wrong1":"la preferenza per politiche di esternalizzazione delle attività","wrong2":"la preferenza per politiche di privatizzazione delle public utilities","wrong3":"la preferenza per politiche di concorrenza nel settore delel public utilies"},{"id":1558,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"La struttura patrimoniale tipica delle aziende di servizi pubblici locali come si presenta per quanto attiene le immobilizzazioni e le attività correnti:","correct":"una prevalenza delle immobilizzazioni rispetto alle attività correnti","wrong1":"una presenza di percentuali simili per immobilizzazioni ed attività correnti","wrong2":"una prevalenza delle attività correnti rispetto alle immobilizzazioni","wrong3":"l'assenza totale di immobiizzazioni"},{"id":1559,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Cosa comporta la presenza di economie di scala:","correct":"il sostenimento di costi, via via migliori al crescere delle dimensioni dei singoli impianti di produzione nonché dell'impresa nel suo complesso","wrong1":"il sostenimento di costi, via via peggiori al crescere delle dimensioni dei singoli impianti di produzione nonché dell'impresa nel suo complesso","wrong2":"l'ottenimento di ricavi, via via peggiori al crescere delle dimensioni dei singoli impianti di produzione nonché dell'impresa nel suo complesso","wrong3":"l'ottenimento di ricavi, via via migliori al crescere delle dimensioni dei singoli impianti di produzione nonché dell'impresa nel suo complesso"},{"id":1560,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Cosa comporta la presenza di economie di esperienza:","correct":"l'accumulo di esperienza maturata col tempo e che consentono risparmi di risorse e/o riduzione di sprechi","wrong1":"il sostenimento di costi, via via peggiori al crescere dell'esperienza","wrong2":"l'ottenimento di ricavi, via via migliori al crescere del numero dei laureati tra il personale","wrong3":"il sostenimento di costi, via via migliori al crescere degli anni di funzionamento dell'impresa"},{"id":1561,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"Cosa sono le economie di integrazione:","correct":"sono tipiche dei settori nei quali l'integrazione verticale consente di conseguire economie nei cosiddetti costi di transazione","wrong1":"sono tipiche dei settori nei quali l'integrazione verticale consente di conseguire economie nei costi totali","wrong2":"sono tipiche dei settori nei quali l'integrazione verticale consente di conseguire economie nei costi variabili","wrong3":"sono tipiche dei settori nei quali l'integrazione verticale consente di conseguire economie nei costi medi"},{"id":1562,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"A cosa sono collegate le economie di densità:","correct":"sono collegate alla dimensione territoriale e spaziale del mercato ed alla densità dell'utenza","wrong1":"sono collegate alla dimensione degli impianti","wrong2":"sono collegate alla dimensione del fatturato","wrong3":"sono collegate alla dimensione del personale"},{"id":1563,"paragraph":"Economia delle aziende e delle PA - 10) La struttura e le condizioni economiche ed operative","question":"A cosa sono collegate le economie di scopo:","correct":"sono collegate alla produzione congiunta di più beni o servizi","wrong1":"sono collegate alla dimensione degli impianti","wrong2":"sono collegate alla dimensione dell'utenza","wrong3":"sono collegate alla dimensione del fatturato"},{"id":1564,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"A cosa è collegata la tematica dei sussidi incrociati nelle tariffe:","correct":"alla definizione in quale misura le differenti classi di utenti debbono partecipare alla copertura dell'aliquota di costo di produzione","wrong1":"alla definizione in quale misura le differenti classi di utenti debbono partecipare alla formazione dei ricavi aziendali","wrong2":"alla definizione in quale misura lo Stato deve partecipare alla copertura dei costi aziendali","wrong3":"alla definizione in quale misura lo Stato effettuare controlli incrociati sulla determinazione delle tariffe"},{"id":1565,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Nel passato, le tariffe hanno avuto il ruolo di controllare il potere del monopolista, gestore di servizi pubblici:","correct":"sì, costituiva una delle finalità delle politiche tariffarie prima della deregolamentazione","wrong1":"sì, ma solo per i servizi pubblici essenziali","wrong2":"no, il monopolista gestore di servizi è stato sempre libero di definire le sue tariffe","wrong3":"sì, ma solo per i servizi pubblici non essenziali"},{"id":1566,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"La molteplicità degli operatori e delle strutture dei costi cosa comporta per le tariffe:","correct":"la difficoltà di realizzare un efficace controllo delle tariffe stesse","wrong1":"la presenza di molteplici tariffe","wrong2":"la difficoltà di determinare la quota dei costi a carico dello Stato","wrong3":"la impossibilità di definire la struttura delle tariffe"},{"id":1567,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Quali sono le finalità delle politiche tariffarie:","correct":"l'espansione dell'utenza e dei consumi, l'orientamento ed il controllo della domanda, la discriminazione tariffaria","wrong1":"assicurare utili all'azienda pubblica erogatrice del servizio","wrong2":"evitare che la domanda del servizio si sviluppi troppo generando sprechi","wrong3":"la piena copertura dei costi di esercizio dei servizi pubblici"},{"id":1568,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Quali sono le finalità delle politiche tariffarie nell'accesso alle reti di servizio:","correct":"facilitare l'accesso anche degli operatori più deboli e lo sviluppo della concorrenza","wrong1":"consentire la piena copertura dei costi delle reti","wrong2":"facilitare la diffusione dei servizi negli utenti","wrong3":"consentire l'ammodernamento delle reti"},{"id":1569,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Gli enti locali possono regolare le tariffe:","correct":"sì, per i servizi pubblici locali come trasporti urbani e nettezza urbana","wrong1":"no, gli enti locali non possono regolare le tariffe","wrong2":"solo nei casi di espressa previsione di leggi","wrong3":"solo per i servizi pubblici non essenziali"},{"id":1570,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Le tariffe possono essere basate sui costi:","correct":"sì, sono previste per diverse figure di costi","wrong1":"le tariffe, per loro natura, non considerano mai i costi","wrong2":"sì, ma solo per i costi medi","wrong3":"sì, ma solo per i servizi pubblici non essenziali"},{"id":1571,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Su cosa si basa la tariffa a forfait:","correct":"si basa sul pagamento di un importo predeterminato indipendente dalla quantità di servizi utilizzata","wrong1":"si basa sul pagamento di un importo collegato ai costi medi dei servizi","wrong2":"si basa sul pagamento di un importo collegato al livello di reddito dell'utente","wrong3":"si basa sul pagamento di un importo collegato alla quantità di servizi utilizzata"},{"id":1572,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Su cosa si basa la tariffa a contatore:","correct":"il prezzo pagato dal fruitore cambia al variare del consumo","wrong1":"si basa sul pagamento di un importo collegato al livello di reddito dell'utente","wrong2":"si basa sul pagamento di un importo collegato ai costi medi dei servizi","wrong3":"si basa sul pagamento di un importo predeterminato indipendente dalla quantità di servizi utilizzata"},{"id":1573,"paragraph":"Economia delle aziende e delle PA - 11) Le politiche tariffarie nelle imprese pubbliche","question":"Su cosa si basa la tariffa a più parti:","correct":"le componenti del prezzo sono in parte fisse e in parte variabili","wrong1":"si basa sul pagamento di un importo predeterminato indipendente dalla quantità di servizi utilizzata","wrong2":"si basa sul pagamento di un importo collegato al livello di reddito dell'utente","wrong3":"il prezzo pagato dal fruitore cambia al variare del consumo"},{"id":1574,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Cosa consente l'attivazione di energie operative da parte del personale:","correct":"la motivazione","wrong1":"l'esistenza di procedure operative","wrong2":"la formazione","wrong3":"la retribuzione"},{"id":1575,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Perché è utile il modello aspettativa-valore nel settore pubblico:","correct":"perché può contribuire a spiegare le dinamiche motivazionali nel settore pubblico","wrong1":"perché fornisce indicazioni utili per la formazione del personale","wrong2":"perché contribuisce a definire il valore della retribuzione","wrong3":"perché può fornire indicazioni utili nella selezione del personale"},{"id":1576,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Nel modello aspettativa-valore cosa occorre assicurare:","correct":"che collegamento tra performance e ricompensa sia comunicato chiaramente","wrong1":"che siano fornite indicazioni utili per l'adempimento delle prestazioni lavorative","wrong2":"che ci sia nell'organizzazione una leadership riconosciuta","wrong3":"che il personale abbia le skills lavorative necessarie"},{"id":1577,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Come può essere definita la leadership:","correct":"il processo volto ad influenzare le attività di un individuo o di un gruppo che si impegna per il conseguimento di obiettivi in una determinata situazione","wrong1":"il processo volto ad influenzare i processi di comunicazione aziendale","wrong2":"il processo volto ad influenzare i modelli organizzativi adottati","wrong3":"il processo volto ad influenzare le attività di un individuo o di un gruppo nella realizzazione delle attività"},{"id":1578,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Nel modello di modello Hersey e Blanchard quali sono le variabili considerate ai fini della leadership:","correct":"il comportamento di guida ed il comportamento di sostegno","wrong1":"la formazione e la remunerazione","wrong2":"la selezione e la struttura organizzativa","wrong3":"il comportamento di guida e la comunicazione"},{"id":1579,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"Gli stili di leadership individuati da Hersey e Blanchard a quale fattore sono collegati:","correct":"al livello di maturità del personale","wrong1":"alla tipologia di comunicazione realizzata","wrong2":"alla tipologia di struttura organizzativa","wrong3":"al livello delle remunerazioni riconosciute"},{"id":1580,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"La programmazione del personale a cosa serve:","correct":"a garantire la disponibilità quantitativa e qualitativa del personale necessario alla realizzazione delle finalità istituzionali dell'azienda","wrong1":"a garantire un adeguato livello retributivo al personale collegato ai risultati","wrong2":"a garantire un adeguato livello di selezione del personale","wrong3":"a garantire un adeguato livello di sviluppo del persnale"},{"id":1581,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"A cosa è collegata l'efficacia del reclutamento:","correct":"l'efficacia del reclutamento è collegata alla capacità di attivare il mercato del lavoro","wrong1":"l'efficacia del reclutamento è collegata alla capacità di definire adeguate procedure di selezione","wrong2":"l'efficacia del reclutamento è collegata alla capacità di ridurre i costi della selezione","wrong3":"l'efficacia del reclutamento è collegata alla capacità di ridurre la tipologia dei profili di personale richiesti"},{"id":1582,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"L'addestramento a cosa serve:","correct":"l'addestramento tende a trasferire abilità definite e codificabili","wrong1":"l'addestramento tende a motivare adeguatamente il peronale","wrong2":"l'addestramento tende a favorire l'interpretazione di problemi complessi","wrong3":"l'addestramento tende a promuovere l'utilizzo di tecnologie evolute"},{"id":1583,"paragraph":"Economia delle aziende e delle PA - 12) La gestione delle risorse umane nel settore pubblico","question":"La formazione a cosa serve:","correct":"la formazione tende a favorire l'interpretazione di problemi complessi","wrong1":"l'addestramento tende a promuovere l'utilizzo di tecnologie evolute","wrong2":"l'addestramento tende a trasferire abilità definite e codificabili","wrong3":"l'addestramento tende a motivare adeguatamente il peronale"},{"id":1584,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"È possibile individuare degli stadi temporali delle public utilities:","correct":"è possibile individuare 4 stadi temporali delle public utilities","wrong1":"non è possibile individuare alcun stadio temporale delle public utilities","wrong2":"è possibile individura lo stadio della pubblicizzazione e quello della privatizzazione","wrong3":"gli stadi temporali delle pubblic utilities variano a seconda della tipologia di servizio considerato"},{"id":1585,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Cosa caratterizzò il Welfare State:","correct":"un progressivo aumento dell'intervento dello Stato nel settore economico e da un corrispondente aumento della domanda di servizi pubblici","wrong1":"lo sviluppo di servizi pubblici derivanti da investimenti di imprese estere","wrong2":"un progressivo aumento dell'intervento dello Stato nel settore dei servizi sociali","wrong3":"lo sviluppo di servizi pubblici gestiti da privati"},{"id":1586,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Quale ruolo assumeva lo Stato nel welfare state:","correct":"lo Stato veniva ad assumere il ruolo di imprenditore sempre più impegnato nella produzione di servizi ritenuti di pubblico interesse ed utilità","wrong1":"lo Stato veniva ad assumere il ruolo di regolatore sempre più impegnato nel regolamentare l'accesso ai servizi da parte dei cittadini","wrong2":"lo stato assumeva un ruolo sostanzialmente neutro nell'economia","wrong3":"lo Stato veniva ad assumere il ruolo di regolatore sempre più impegnato nel regolamentare l'accesso dei privati nei servizi pubblici"},{"id":1587,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Quale modello di Stato nei servizi pubblici è possibile individuare nei nostri anni:","correct":"il modello di Stato definibile della qualità della vita o dei servizi","wrong1":"il modello del welfare state","wrong2":"il modello dello Stato imprenditore","wrong3":"il modello dello Stato regolatore"},{"id":1588,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Quali sono le sottofasi dello Stato della qualità dei vita:","correct":"stato dei servizi e stato regolatore","wrong1":"stato imprenditore e stato deregolamentatore","wrong2":"stato investitore e stato regolatore","wrong3":"stato del benessere e Stato deregolamentatore"},{"id":1589,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Quali sono i caratteri specifici dei servizi pubblici:","correct":"i servizi pubblici non sono individuabili sulla base di definiti caratteri, ma derivano da un esplicito riconoscimento della P.A.","wrong1":"i servizi pubblici sono individuabili sulla base di definiti caratteri collegati all'evoluzione economica","wrong2":"i servizi pubblici sono individuabili dal loro carattere sociale","wrong3":"i servizi pubblici sono individuabili sulla base di definiti caratteri, come l'essenzialità e la socialità"},{"id":1590,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"In quale categoria possiamo far rientrare i servizi pubblici:","correct":"i servizi pubblici costituiscono una categoria aperta, poiché è soggetta, nel tempo, ad ampliarsi o a restringersi","wrong1":"i servizi pubblici costituiscono una categoria chiusa, poiché è non muta nel tempo","wrong2":"i servizi pubblici costituiscono una categoria chiusa, poiché collegata a specifiche leggi istitutive","wrong3":"i servizi pubblici costituiscono una categoria economica, poiché hanno un forte impatto sull'economia"},{"id":1591,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Il miglioramento delle condizioni culturali, economiche e di ricchezza dei consumatori ha impattato sui servizi pubblici:","correct":"sì, hanno generato delle spinte al cambiamento","wrong1":"sì, hanno generato delle spinte per la riduzione delle tariffe","wrong2":"no, non ha mai generato dei cambiamenti","wrong3":"sì, hanno generato delle spinte per ampliare l'intervento dello Stato"},{"id":1592,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Cosa caratterizza i servizi uti singoli:","correct":"sono caratterizzati da una domanda ed un godimento singolarmente individuabile","wrong1":"sono caratterizzati da una domanda variabile nel tempo","wrong2":"sono caratterizzati da specifiche normative collegate alla qualità dei servizi","wrong3":"sono caratterizzati da una domanda ed un godimento collettivo"},{"id":1593,"paragraph":"Economia delle aziende e delle PA - 13) I principi fondamentali delle Public Utilities","question":"Cosa caratterizza i servizi uti universi:","correct":"sono caratterizzati da prestazioni indivisibili offerte alla collettività e non danno luogo ad un rapporto di scambio","wrong1":"sono caratterizzati da una domanda ed un godimento singolarmente individuabile","wrong2":"sono caratterizzati da prestazioni indivisibili offerte alla collettività e danno luogo ad un rapporto di scambio","wrong3":"sono caratterizzati da specifiche normative collegate alla qualità dei servizi"},{"id":1594,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"La teoria economica nel passato a cosa collegava le ragioni dell'intervento pubblico nell'economia:","correct":"a situazioni di fallimento del mercato nei settori di pubblica utilità","wrong1":"all'esigenza di garantire adeguati ritorni degli investimenti nei settori di pubblica utilità","wrong2":"all'esigenza di garantire i livelli occupazionali nei settori di pubblica utilità","wrong3":"all'esigenza di garantire eque politiche tariffarie nei settori di pubblica utilità"},{"id":1595,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"A cosa si collegavano le ragioni che hanno determinato la scelta del monopolio nell'offerta di servizi pubblici:","correct":"a ragioni di natura economico-tecnica ed a ragioni politico-sociali","wrong1":"a ragioni di natura normativa ed a ragioni di efficacia","wrong2":"a ragioni di natura economica ed a ragioni di natura sociale","wrong3":"a ragioni di natura politica ed a ragioni di natura sociale"},{"id":1596,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"La riserva di monopolio a cosa si applica:","correct":"all'offerta del servizio e non alla soddisfazione del bisogno","wrong1":"alla soddisfazione del bisogno","wrong2":"alla tipologia di investimenti da realizzare","wrong3":"ai servizi pubblici di tipo universale"},{"id":1597,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"Nel monopolio, la proprietà di subadditività della funzione di costo cosa comporta:","correct":"che un'unica impresa è in grado di produrre a condizioni economiche più favorevoli rispetto a qualsiasi combinazione di due o più imprese","wrong1":"che la presenza di un'unica impresa nel settore dei servizi pubblici determina l'erogazione di servizi con tariffe più basse","wrong2":"che la compinazione di due o più imprese sono in grado di produrre a condizioni più favorevoli rispetto ad un'unica impresa","wrong3":"che la presenza di una combinazione di imprese nel settore dei servizi pubblici garantisce situazioni di concorrenza"},{"id":1598,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"Che tipologia di deregolamentazione è stata avviata dagli anni '90 nei servizi pubblici:","correct":"la deregolamentazione asimmetrica","wrong1":"la deregolamentazione economica","wrong2":"la deregolamentazione amministrativa","wrong3":"la deregolamentazione tariffaria"},{"id":1599,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"Le critiche all'intervento dello Stato nell'economia cosa ha evidenziato per i manager dei servizi pubblici:","correct":"l'inadeguatezza dei sistemi d'incentivo/sanzione dei manager","wrong1":"l'esistenza di retribuzioni troppo elevate","wrong2":"problematiche connesse ad una scarsa formazione","wrong3":"problematiche connesse a nomine eccessivamente di tipo politico"},{"id":1600,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"Le politiche per la concorrenza, quando non possono dare luogo ad una competizione nel mercato come si realizzano:","correct":"con politiche di concorrenza allo stato potenziale, a monte o in modo simulato","wrong1":"con politiche di concorrenza parziali e politiche di concorrenza simulata","wrong2":"con politiche di concorrenza sui finanziamenti","wrong3":"con politiche di concorrenza a valle e politiche di concorrenza simulata"},{"id":1601,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"Cosa caratterizza la concorrenza virtuale nei servizi pubblici:","correct":"non introduce una competizione sul piano del posizionamento o successo del mercato, ma svolge comunque una funzione di incentivo al miglioramento delle performance","wrong1":"introduce una competizione sul piano del posizionamento o successo di mercato","wrong2":"introduce una concorrenza di tipo parziale","wrong3":"introduce una concorrenza sulla natura del bisogno da soddisfare"},{"id":1602,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"La Legge 142/90 come distingueva i servizi pubblici:","correct":"distingueva tra i servizi gestiti in forma di impresa in quanto servizi commerciabili e servizi non commerciabili in quanto offerti o indistintamente a tutta la collettività","wrong1":"distingueva tra i servizi gestiti in forma uti singoli e uti universi","wrong2":"distingueva tra servizi materiali e servizi immateriali","wrong3":"distingueva tra servizi nazionali e servizi locali"},{"id":1603,"paragraph":"Economia delle aziende e delle PA - 14) I nuovi paradigmi teorici nelle Public Utilities","question":"L'art. 35 della legge 448/2001 come distingue, invece, i servizi pubblici:","correct":"distingue tra servizi a rilevanza industriale e servizi privi di rilevanza industriale","wrong1":"distingue tra i servizi gestiti in forma uti singoli e uti universi","wrong2":"distingueva tra servizi materiali e servizi immateriali","wrong3":"distingue tra servizi nazionali e servizi locali"},{"id":1604,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Qual è stato nel passato l'aspetto tipico delle imprese di servizi pubblici, rispetto ad altri settori:","correct":"la competenza territoriale","wrong1":"la mancanza del carattere industriale dei servizi","wrong2":"il forte collegamento con le politiche del governo","wrong3":"l'aspetto sociale dei servizi erogati"},{"id":1605,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Per le imprese operanti a livello locale, cosa ha determinato spesso la competenza territoriale:","correct":"la rigida definizione di un ambito territoriale ha determinato un grande ostacolo alla crescita ed allo sviluppo di tali imprese","wrong1":"la rigida definizione di un ambito territoriale ha determinato un grande ostacolo all'adozione di politiche concorrenziali","wrong2":"la rigida definizione di un ambito territoriale ha determinato un grande ostacolo all'adozione di politiche di marketing","wrong3":"la rigida definizione di un ambito territoriale ha determinato un grande ostacolo alla determinazione di tariffe remunerative"},{"id":1606,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Quali sono in sintesi i cambiamenti in atto nel settore dei servizi pubblici:","correct":"deregolamentazione, privatizzazione ed apertura alla concorrenza","wrong1":"processi di adozione di sistemi contabili di tipo avanzato","wrong2":"minore attenzione agli aspetti sociali rispetto a quelli economici","wrong3":"adozione di nuovi processi di governance"},{"id":1607,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"I cambiamenti in atto che cosa hanno determinato in termini di politiche di diversificazione:","correct":"nuove opportunità di partecipazione o di investimento a livello locale e/o nazionale ed internazionale","wrong1":"nuove opportunità per l'adozione di processi di governance innovativi","wrong2":"nuove opportunità per l'adozione di politiche formative innovative per i manager","wrong3":"nuove opportunità per l'adozione di tecnologie innovative"},{"id":1608,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Come possono essere le modalità di gestione dei servizi pubblici:","correct":"gestione diretta e gestione indiretta","wrong1":"gestione uti singoli e gestione uti universi","wrong2":"gestione industriale e gestione sociale","wrong3":"gestione industriale e gestione in concessione"},{"id":1609,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"La modalità di gestione diretta statale come può essere:","correct":"a regia diretta e regia indiretta","wrong1":"gestione uti singoli e gestione uti universi","wrong2":"gestione industriale e gestione in concessione","wrong3":"gestione industriale e gestione sociale"},{"id":1610,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Cosa è la modalità di gestione indiretta:","correct":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto e sotto il proprio controllo una attività nettamente distinta dall'Ente pubblico concedente","wrong1":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto un servizio pubblico essenziale","wrong2":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto una serie di servizi pubblici locali","wrong3":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto e sotto il proprio controllo una attività propria ed indistinta dell'Ente concedente"},{"id":1611,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Cosa è la concessione:","correct":"una convenzione per mezzo della quale un ente pubblico incarica una impresa di realizzare un pubblico servizio","wrong1":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto una serie di servizi pubblici locali","wrong2":"la p.a. concede ad un ente terzo il diritto di gestire per proprio conto e sotto il proprio controllo una attività propria ed indistinta dell'Ente concedente","wrong3":"una convenzione per mezzo della quale un ente pubblico incarica una impresa di stipulare contratti in nome e per conto dell'ente pubblico"},{"id":1612,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Come possono essere le società per azioni miste:","correct":"con partecipazione pubblica maggioritaria o minoritaria","wrong1":"nazionali o internazionali","wrong2":"industriali o non industriali","wrong3":"controllate o non controllate"},{"id":1613,"paragraph":"Economia delle aziende e delle PA - 15) La trasformazione dei mercati delle Public Utilities","question":"Come possono essere le tipologie di Organi ed aziende di servizi pubblici locali non costituite sotto forma di SpA:","correct":"aziende speciali, aziende consortili, istituzioni","wrong1":"industriali o non industriali","wrong2":"controllate o non controllate","wrong3":"con partecipazione pubblica maggioritaria o minoritaria"},{"id":1614,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"A cosa fa riferimento il concetto di impresa pubblica come istituto post-crisi:","correct":"al fatto che nel passato molte imprese pubbliche sono nate in conseguenza di fallimenti del settore privato","wrong1":"al fatto che nel passato molte imprese pubbliche uscivano dal mercato per situazioni di crisi economica","wrong2":"al fatto che nel passato molte imprese pubbliche generavano situazioni di crisi economica","wrong3":"al fatto che nel passato molte imprese pubbliche operavano in situazioni di crisi economica"},{"id":1615,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"L'iniziativa pubblica ha mai dovuto supplire alle deficienze dell'iniziativa privata:","correct":"sì, è accaduto spesso nel passato per la mancanza di iniziativa privata in alcuni settori","wrong1":"sì, è accaduto spesso nel passato quando il settore privato chiedeva di essere supportato dl pubblico","wrong2":"no, tale situazione non si è mai verificata","wrong3":"sì, ma solo in situazioni di crisi economica"},{"id":1616,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"Il soddisfacimento di esigenze e bisogni di primario interesse collettivo cosa poteva comportanre nel passato:","correct":"l'intervento del settore pubblico nell'economia","wrong1":"l'erogazione di sussidi da parte dello Stato ad alcune imprese private","wrong2":"la concorrenza tra imprese di servizi pubblici ed imprese di servizi privati","wrong3":"l'adozione di tariffe più basse per determinate classi di utenti"},{"id":1617,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"Quando è iniziato il processo di cambiamento nel settore pubblico:","correct":"agli inizi degli anni '90","wrong1":"dopo la seconda guerra mondiale","wrong2":"con gli anni 2000","wrong3":"dopo la crisi finanziaria del 2008"},{"id":1618,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"La mancanza di meccanismi di incentivazione e di valutazione efficaci del management pubblico cosa ha generato:","correct":"le spinte al cambiamento nella gestione del settore pubblico","wrong1":"la riduzione dei compensi dei manager pubblici","wrong2":"l'attivazione di processi di formazione per il settore pubblico","wrong3":"la privatizzazione del rapporto di pubblico impiego"},{"id":1619,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"Le spinte al cambiamento nel settore pubblico cosa hanno generato:","correct":"l'avvio del processo di deregolamentazione","wrong1":"l'introduzione di imprese estere concorrenti nel settore pubblico","wrong2":"sostanzialmente, non hanno generato alcun cambiamento","wrong3":"la riduzione dei compensi dei manager pubblici"},{"id":1620,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"Qual è stato uno degli effetti del processo di deregolamentazione del settore pubblico:","correct":"l'avvio di processi di esternalizzazione dei servizi","wrong1":"una maggiore attenzione ai problemi generati dalla concorrenza","wrong2":"l'introduzione di imprese estere concorrenti nel settore pubblico","wrong3":"un maggiore investimento del settore pubblico nell'ambito dei servizi"},{"id":1621,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"La libertà di accesso nel settore pubblico a cosa deve essere imputata:","correct":"al processo di deregolamentazione","wrong1":"una maggiore attenzione ai problemi generati dalla concorrenza","wrong2":"un maggiore investimento del settore pubblico nell'ambito dei servizi","wrong3":"allo sviluppo del welfare state"},{"id":1622,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"La libertà di accesso nel settore pubblico cosa ha comportato:","correct":"la presenza di una pluralità di operatori nel settore dei servizi pubblici","wrong1":"la riduzione dei compensi dei manager pubblici","wrong2":"allo sviluppo del Welfare State","wrong3":"sostanzialmente, non hanno generato alcun cambiamento"},{"id":1623,"paragraph":"Economia delle aziende e delle PA - 16) I processi di trasformazione dell'impresa pubblica","question":"I piani di risanamento nel settore dei servizi pubblici, in alcuni casi cosa ha determinato:","correct":"la cessione di attività non strategiche","wrong1":"la presenza di una pluralità di operatori nel settore dei servizi pubblici","wrong2":"una maggiore attenzione ai problemi generati dalla concorrenza","wrong3":"un maggiore investimento del settore pubblico nell'ambito dei servizi"},{"id":1624,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"Il processo di privatizzazione in Italia quando ha avuto inizio:","correct":"primi anni '90","wrong1":"dopo la seconda guerra mondiale","wrong2":"primi anni '70","wrong3":"primi anni 2000"},{"id":1625,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"In Italia il processo di privatizzazione si è sviluppato in modo omogeneo per tutti i settori economici:","correct":"i processi di privatizzazione sono stati realizzati in modo differenziato a seconda del settore economico","wrong1":"sostanzialmente si è realizzato in modo omogeneo nei diversi settori economici","wrong2":"i processi di privatizzazione sono stati realizzati in modo differenziato in relazione alle epoche in cui si sono realizzati","wrong3":"i processi di privatizzazione sono stati realizzati in modo differenziato a seconda dei diversi governi che li realizzavano"},{"id":1626,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"Quali sono le diverse tipologie di privatizzazione:","correct":"formale, sostanziale, funzionale, indiretta","wrong1":"formale, burocratica, economica","wrong2":"diretta ed Indiretta","wrong3":"dei Monopoli e delle Public Utilities"},{"id":1627,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"In cosa consiste la privatizzazione formale:","correct":"consiste nella trasformazione della natura e caratteristiche giuridiche dell'ente pubblico","wrong1":"consiste nella privatizzazione delle Public Utilities","wrong2":"consiste nella privatizzazione dei Monopoli di Stato","wrong3":"consiste nella trasformazione della natura e caratteristiche economiche dell'ente pubblico"},{"id":1628,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"In cosa consiste la privatizzazione sostanziale:","correct":"consiste nel trasferimento della proprietà di enti o aziende pubbliche, già privatizzate dal punto di vista formale in società per azioni, dallo Stato ai soggetti privati","wrong1":"consiste nella privatizzazione dei Monopoli di Stato","wrong2":"consiste nella privatizzazione delle Public Utilities","wrong3":"consiste nella trasformazione della natura e caratteristiche giuridiche dell'ente pubblico"},{"id":1629,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"In cosa consiste la privatizzazione funzionale:","correct":"consiste nel trasferimento al privato di una determinata funzione svolta in precedenza dall'operatore pubblico","wrong1":"consiste nella trasformazione della natura e caratteristiche giuridiche dell'ente pubblico","wrong2":"consiste nel trasferimento della proprietà di enti o aziende pubbliche, già privatizzate dal punto di vista formale in società per azioni, dallo Stato ai soggetti privati.","wrong3":"consiste nella trasformazione della natura e caratteristiche economiche dell'ente pubblico"},{"id":1630,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"In cosa consiste la privatizzazione indiretta:","correct":"consiste nell'introduzione di obiettivi e criteri di tipo privatistico nella gestione dell'impresa pubblica","wrong1":"consiste nella trasformazione della natura e caratteristiche economiche dell'ente pubblico","wrong2":"consiste nel trasferimento al privato di una determinata funzione svolta in precedenza dall'operatore pubblico","wrong3":"consiste nella trasformazione della natura e caratteristiche giuridiche dell'ente pubblico"},{"id":1631,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"Il modello Britannico diprivatizzazione a cosa ha fatto soprattutto ricorso:","correct":"allo strumento della golden share","wrong1":"alla trasformazione della natura e caratteristiche giuridiche dell'ente pubblico","wrong2":"alla cessione dei Monopoli","wrong3":"alla trasformazione della natura e caratteristiche economiche dell'ente pubblico"},{"id":1632,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"Il modello Francese diprivatizzazione a cosa ha fatto soprattutto ricorso:","correct":"alla creazione di un nucleo stabile di azionisti di riferimento nell'intento di assicurare alle società privatizzate un controllo accentrato e stabile nel tempo","wrong1":"allo strumento della golden share","wrong2":"alla trasformazione della natura e caratteristiche economiche dell'ente pubblico","wrong3":"alla trasformazione della natura e caratteristiche economiche dell'ente pubblico"},{"id":1633,"paragraph":"Economia delle aziende e delle PA - 17) I processi di privatizzazione","question":"Il modello Italiano diprivatizzazione a cosa ha fatto soprattutto ricorso:","correct":"al modello misto, nel quale sono contemporaneamente presenti gli elementi distintivi sia del modello britannico che di quello francese","wrong1":"alla trasformazione della natura e caratteristiche economiche dell'ente pubblico","wrong2":"alla trasformazione della natura e caratteristiche economiche dell'ente pubblico","wrong3":"alla cessione dei Monopoli"},{"id":1634,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Il concetto di sostenibilità affiancato a quello di sviluppo sostenibile è richiamato per la prima volta nel:","correct":"Brundtland Report","wrong1":"Agenda 2030","wrong2":"Transforming our world","wrong3":"European Green Deal 2050"},{"id":1635,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Le tre dimensioni in cui si articola il concetto di sostenibilità sono:","correct":"1) Economica; 2) Ambientale; 3) Sociale","wrong1":"1) Economica; 2) Ecologica; 3) Sociale","wrong2":"1) Finanziaria; 2) Ecologica; 3) Sociale","wrong3":"1) Economica; 2) Ambientale; 3) Finanziaria"},{"id":1636,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Le origini del concetto di Corporate Social Responsibility risalgono:","correct":"Ai secoli XVIII e XIX","wrong1":"Ai secoli XV e XVI","wrong2":"Ai secoli X e XI","wrong3":"Ai secoli XVI e XVII"},{"id":1637,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Il primo accademico a parlare di CSR è stato:","correct":"Howard R. Bowen","wrong1":"Archie B. Carroll","wrong2":"Keith Davis","wrong3":"Milton Friedman"},{"id":1638,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"L'espressione \"Triple Bottom Line\" è stata coniata da:","correct":"John Elkington","wrong1":"Howard R. Bowen","wrong2":"Milton Friedman","wrong3":"Archie B. Carroll"},{"id":1639,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Nell'Agenda 2030, le Nazioni Unite definiscono:","correct":"17 Sustainable Development Goals (SDG)","wrong1":"Una serie di iniziative per raggiungere una transizione ecologica tale da rendere il continente europeo il primo a impatto climatico zero","wrong2":"Un framework globale per contenere l'aumento della temperatura media globale al di sotto dei 2 °C e limitarne l'incremento a 1,5 °C","wrong3":"Due differenti tipologie di social responsibilities"},{"id":1640,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Nell'ambito dei criteri ESG, il criterio E (Environmental):","correct":"Fa riferimento a diversi parametri relativi all'ambiente","wrong1":"Prende in considerazione le relazioni delle imprese","wrong2":"Riguarda la struttura di governance delle imprese e la sua responsabilità","wrong3":"Non è essenziale per definire un'impresa come sostenibile"},{"id":1641,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Nell'ambito dei criteri ESG, il criterio S (Sociale):","correct":"Prende in considerazione le relazioni delle imprese","wrong1":"Riguarda la struttura di governance delle imprese e la sua responsabilità","wrong2":"Fa riferimento a diversi parametri relativi all'ambiente","wrong3":"Non è essenziale per definire un'impresa come sostenibile"},{"id":1642,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"La Non-Financial Reporting Directive (NFRD):","correct":"Fornisce regole sul reporting non finanziario","wrong1":"È stata abrogata nel 2021","wrong2":"Non è stata ancora recepita dall'Italia","wrong3":"Si applica a tutte le imprese quotate e agli enti pubblici con almeno 250 dipendenti"},{"id":1643,"paragraph":"Economia delle aziende e delle PA - 18) Il concetto di sostenibilità in ambito economico-aziendale","question":"Attualmente, lo standard di riferimento per la rendicontazione delle informazioni non finanziarie è:","correct":"Il GRI (Global Reporting Initiative)","wrong1":"L'European Green Deal 2050","wrong2":"L'Agenda 2030","wrong3":"Il Brundtland Report"},{"id":1644,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il bilancio d'esercizio:","correct":"è un documento obbligatorio che serve ad indicare i risultati economici, finanziari e patrimoniali di un'impresa","wrong1":"è un documento facoltativo che serve ad indicare i risultati economici, finanziari e patrimoniali di un'impresa","wrong2":"è un documento obbligatorio che serve ad indicare i soli risultati economici di un'impresa","wrong3":"è un documento obbligatorio che serve ad indicare i soli risultati patrimoniali di un'impresa"},{"id":1645,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il bilancio d'esercizio:","correct":"è uno strumento conoscitivo sia interno che esterno","wrong1":"è uno strumento conoscitivo solo interno","wrong2":"è uno strumento conoscitivo solo esterno","wrong3":"non è uno strumento conoscitivo"},{"id":1646,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il Conto Economico:","correct":"è uno degli elementi di cui si compone il bilancio d'esercizio","wrong1":"deve essere redatto dal Collegio Sindacale","wrong2":"è un documento alternativo allo Stato Patrimoniale","wrong3":"consente di analizzare la dinmica finanziaria di una azienda"},{"id":1647,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Le società di persone:","correct":"non devono utilizzare schemi prestabiliti nella redazione del bilancio d'esercizio","wrong1":"non possono redigere il bilancio d'esercizio","wrong2":"devono utilizzare schemi prestabiliti nella redazione del bilancio d'esercizio","wrong3":"devono far riferimento al Testo Unico delle Imposte sui Redditi (TUIR)per la redazione del bilancio d'esercizio"},{"id":1648,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Le società di capitali:","correct":"devono tenere obbligatoriamente sia il Libro Giornale che il Libro degli inventari","wrong1":"devono tenere obbligatoriamente o il Libro Giornale o il Libro degli inventari","wrong2":"devono tenere obbligatoriamente solo il Libro Giornale","wrong3":"devono tenere obbligatoriamente solo il Libro degli inventari"},{"id":1649,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Attraverso il bilancio d'esercizio è possibile:","correct":"valutare l'operato degli amministratori","wrong1":"valutare l'operato dei soci","wrong2":"valutare l'operato del collegio sindacale","wrong3":"valutare l'operato dei commercialisti"},{"id":1650,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il bilancio d'esercizio deve essere approvato:","correct":"entro 120 gg dalla chiusura dell'esercizio sociale","wrong1":"entro 60 gg dalla chiusura dell'esercizio sociale","wrong2":"entro 90 gg dalla chiusura dell'esercizio sociale","wrong3":"entro 30 gg dalla chiusura dell'esercizio sociale"},{"id":1651,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"In determinati casi, il bilancio d'esercizio può essere approvato:","correct":"entro 180 gg dalla chiusura dell'esercizio sociale","wrong1":"entro 1 anno dalla chiusura dell'esercizio sociale","wrong2":"entro 3 anno dalla chiusura dell'esercizio sociale","wrong3":"entro 5 anno dalla chiusura dell'esercizio sociale"},{"id":1652,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il bilancio d'esercizio deve essere reso pubblico:","correct":"entro 30 gg dalla sua approvazione","wrong1":"entro 180 gg dalla sua approvazione","wrong2":"entro 120 gg dalla sua approvazione","wrong3":"entro 60 gg dalla sua approvazione"},{"id":1653,"paragraph":"Economia delle aziende e delle PA - 19) Introduzione al bilancio d'esercizio alla luce del D.Lgs. 139/2015","question":"Il bilancio d'esercizio:","correct":"è uno strumento di conoscenza, di controllo e di comunicazione","wrong1":"è uno strumento di conoscenza e di controllo, ma non di comunicazione","wrong2":"è uno strumento di conoscenza e di comunicazione, ma non di controllo","wrong3":"è uno strumento di comunicazione e di controllo, ma non di conoscenza"},{"id":1654,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Secondo l'art. 2423 del c.c., il bilancio deve essere redatto:","correct":"deve essere redatto con chiarezza e rappresentare in modo veritiero e corretto la situazione patrimoniale-finanziaria della società ed il risultato economico d'esercizio","wrong1":"con chiarezza e rappresentare, secondo competenza finanziaria, la situazione patrimoniale della società ed il risultato economico d'esercizio","wrong2":"deve essere redatto con chiarezza e rappresentare in modo veritiero e corretto soltanto la situazione patrimoniale-finanziaria della società","wrong3":"deve essere redatto con chiarezza e rappresentare in modo veritiero e corretto unicamente il risultato economico d'esercizio"},{"id":1655,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"I principi di redazione del bilancio sono indicati:","correct":"dall'art. 2423 bis c.c.","wrong1":"dall'art. 2426 c.c.","wrong2":"dall'art. 2425 c.c.","wrong3":"dall'art. 2424 c.c."},{"id":1656,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di continuità implica che:","correct":"le valutazioni siano effettuate tenendo conto delle valutazioni che i beni oggetto di valutazione potranno avere nei futuri periodi amministrativi","wrong1":"i costi ed i ricavi siano rilevati secondo competenza economica","wrong2":"gli elementi eterogenei siano rappresentati e valutati secondo criteri differenti","wrong3":"le perdite vadano contabilizzate sempre, anche se ritenute incerte e/o presunte"},{"id":1657,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di separazione implica che:","correct":"gli elementi eterogenei siano rappresentati e valutati secondo criteri differenti","wrong1":"le valutazioni siano effettuate tenendo conto delle valutazioni che i beni oggetto di valutazione potranno avere nei futuri periodi amministrativi","wrong2":"i costi ed i ricavi siano rilevati secondo competenza economica","wrong3":"le perdite vadano contabilizzate sempre, anche se ritenute incerte e/o presunte"},{"id":1658,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di prudenza implica che:","correct":"le perdite vadano contabilizzate sempre, anche se ritenute incerte e/o presunte","wrong1":"gli elementi eterogenei siano rappresentati e valutati secondo criteri differenti","wrong2":"le valutazioni siano effettuate tenendo conto delle valutazioni che i beni oggetto di valutazione potranno avere nei futuri periodi amministrativi","wrong3":"i costi ed i ricavi siano rilevati secondo competenza economica"},{"id":1659,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio della prevalenza della sostanza sulla forma prevede:","correct":"di attribuire importanza alla sostanza degli accadimenti aziendali e non agli aspetti formali degli stessi","wrong1":"di effettuare le valutazioni, tenendo conto delle valutazioni che i beni oggetto di valutazione potranno avere nei futuri periodi amministrativi","wrong2":"di rappresentare gli elementi eterogenei secondo criteri differenti","wrong3":"di contabilizzare tutte le perdite, anche se incerte e/o presunte"},{"id":1660,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di comprensibilità di cui all'OIC 11 attiene:","correct":"alla necessità di informazioni analitiche in grado di distinguere diverse aree di gestione","wrong1":"alla necessità di comunque validare il bilancio, anche se presenta lievi imperfezioni contabili","wrong2":"all'indipendenza nelle valutazioni discrezionali","wrong3":"alla necessità di redigere il bilancio con un'unica valuta di conto"},{"id":1661,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di imparzialità indicato dall'OIC 11 attiene:","correct":"all'indipendenza nelle valutazioni discrezionali","wrong1":"alla necessità di comunque validare il bilancio, anche se presenta lievi imperfezioni contabili","wrong2":"alla necessità di informazioni analitiche in grado di distinguere diverse aree di gestione","wrong3":"alla necessità di redigere il bilancio con un'unica valuta di conto"},{"id":1662,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"Il principio di significatività indicato dall'OIC 11 attiene:","correct":"alla necessità di comunque validare il bilancio, anche se presenta lievi imperfezioni contabili","wrong1":"la necessità di informazioni analitiche in grado di distinguere diverse aree di gestione","wrong2":"l'indipendenza nelle valutazioni discrezionali","wrong3":"alla necessità di redigere il bilancio con un'unica valuta di conto"},{"id":1663,"paragraph":"Economia delle aziende e delle PA - 20) I principi che regolano la redazione del bilancio d'esercizio","question":"La disciplina del bilancio di cui al codice civile è stata recentemente modificata dal:","correct":"d.Lgs. 139/2015","wrong1":"d. Lgs. 127/1991","wrong2":"dalla Legge di Stabilità 2015","wrong3":"organismo Italiano di Contabilità"},{"id":1664,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"La disciplina del bilancio è stata modificata con l'emanazione del:","correct":"D. Lgs. 139/2015","wrong1":"D. Lgs. 127/2015","wrong2":"D. Lgs. 140/2015","wrong3":"D. Lgs. 138/2015"},{"id":1665,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. che ha modificato la disciplina del bilancio è stato pubblicato nella Gazzetta Ufficiale:","correct":"N. 205","wrong1":"N. 204","wrong2":"N. 206","wrong3":"N. 207"},{"id":1666,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. che ha modificato la disciplina del bilancio è stato emanato in attuazione della Direttiva:","correct":"2013/34/UE","wrong1":"78/660/CEE","wrong2":"83/349/CEE","wrong3":"2006/43/CE"},{"id":1667,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"La Direttiva europea, in attuazione della quale è stato emanato il D.Lgs. che ha modificato la disciplina del bilancio, ha recato modifiche alla Direttiva:","correct":"2006/43/CE","wrong1":"78/660/CEE","wrong2":"83/349/CEE","wrong3":"2013/34/UE"},{"id":1668,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. 173/1997 attiene:","correct":"le imprese di assicurazione","wrong1":"le disposizioni in materia di revisione legale dei conti","wrong2":"le disposizioni recante l'ambito di applicazione dei soggetti tenuti a redigere il bilancio sulla base dei principi IAS/IFRS","wrong3":"le imprese di servizi"},{"id":1669,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. 39/2010 attiene:","correct":"le disposizioni in materia di revisione legale dei conti","wrong1":"le imprese di assicurazione","wrong2":"le disposizioni recante l'ambito di applicazione dei soggetti tenuti a redigere il bilancio sulla base dei principi IAS/IFRS","wrong3":"le imprese di servizi"},{"id":1670,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. 38/2005 attiene:","correct":"le disposizioni recante l'ambito di applicazione dei soggetti tenuti a redigere il bilancio sulla base dei principi IAS/IFRS","wrong1":"le imprese di assicurazione","wrong2":"le disposizioni in materia di revisione legale dei conti","wrong3":"le imprese di servizi"},{"id":1671,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Le disposizioni del D.Lgs. del 2015 attinente la modifica della disciplina del bilancio:","correct":"sono entrate in vigore il 1 gennaio 2016","wrong1":"sono entrate in vigore il 1 aprile 2016","wrong2":"sono entrate in vigore il 1 marzo","wrong3":"sono entrate in vigore il 1 febbraio 2016"},{"id":1672,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. del 2015 che ha modificato la disciplina del bilancio non riguarda:","correct":"le imprese individuali","wrong1":"le società per azioni","wrong2":"le società in accomandita per azioni","wrong3":"le società a responsabilità limitata"},{"id":1673,"paragraph":"Economia delle aziende e delle PA - 21) Il nuovo bilancio d'esercizio","question":"Il D.Lgs. del 2015 che ha modificato la disciplina del bilancio ha introdotto importanti novità in tema di:","correct":"rendiconto finanziario","wrong1":"contabilizzazione dei costi di acquisto delle materie prime","wrong2":"contabilizzazione dei costi di energia","wrong3":"contabilizzazione delle rimanenze"},{"id":1674,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"La redazione del rendiconto finanziario:","correct":"non è obbligatoria per le società che redigono il bilancio in forma abbreviata","wrong1":"non è obbligatoria per le società a responsabilità limitata","wrong2":"non è obbligatoria per le società con patrimonio netto on superiore a € 500.000","wrong3":"non è obblgatoria per le società che hanno attivo patrimoniale non superiore a € 5.000.000"},{"id":1675,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"Secondo l'art. 2425 ter c.c., dal rendiconto finanziario devono risultare, per l'esercizio in chiusura e per quello precedente:","correct":"l'ammontare e la composizione delle disponibilità liquide all'inizio e alla fine dell'esercizio","wrong1":"l'ammontare e la composizione delle disponibilità liquide all'inizio ed a metà esercizio","wrong2":"soltanto l'ammontare e la composizione delle disponibilità liquide all'inizio dell'esercizio","wrong3":"soltanto l'ammontare e la composizione delle disponibilità liquide alla fine dell'esercizio"},{"id":1676,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"Secondo l'art. 2425 ter c.c., nel rendiconto finanziario:","correct":"devono essere indicati i flussi finanziari relativi alle operazioni con i soci","wrong1":"non devono essere indicati i flussi finanziari relativi alle operazioni con i soci","wrong2":"non devono essere indicati i flussi finanziari relativi alla gestione delle immobilizzazioni","wrong3":"devono essere indicati tutti i costi e solo i ricavi monetari di competenza"},{"id":1677,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito alla modifica dell'art. 2424 c.c., nello Stato patrimoniale:","correct":"le azioni proprie devono essere portate in diretta diminuzione del patrimonio netto","wrong1":"le azioni proprie continuano ad essere indicate tra le immobilizzazioni o nell'attivo circolante","wrong2":"le azioni proprie devono essere tutte indicate tra le immobilizzazioni","wrong3":"le azioni proprie devono essere tutte indicate nell'attivo circolante"},{"id":1678,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito alla modifica dell'art. 2424 c.c, tra le voci di patrimonio netto:","correct":"è stata introdotta la \"Riserva per operazione di copertura dei flussi finanziari attesi\"","wrong1":"non trova più indicazione il capitale sociale","wrong2":"non trova più indicazione il risultato di esercizio","wrong3":"è stata introdotta la \"Riserva per gli utili delle controllate\""},{"id":1679,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito alla modifica dell'art. 2424 c.c, le informazioni prima contenute nei conti d'ordine devono essere ora riportate, per espressa previsione normativa:","correct":"nella nota integrativa","wrong1":"nel conto economico","wrong2":"nel verbale assembleare di approvazione del bilancio","wrong3":"nel rendiconto finanziario"},{"id":1680,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito alla modifica dell'art. 2425 c.c., i proventi e gli oneri derivanti da imprese sottoposte al controllo delle controllanti:","correct":"devono essere indicati separatamente, nella classe C) Proventi e oneri finanziari","wrong1":"non vanno pù indicati nel conto economico","wrong2":"non vanno più indicati nel conto economico, solo se di ammontare non rilevante","wrong3":"devono essere indicati nel conto economico soltanto se di ammontare rilevante"},{"id":1681,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"I proventi e gli oneri finanziari:","correct":"devono essere indicati nella classe C) per l'importo netto","wrong1":"devono essere indicati nel conto economico soltanto se di ammontare rilevante","wrong2":"non vanno più indicati nel conto economico, dopo le modifiche del D. Lgs. 139/2015","wrong3":"devono essere indicati separatamente, nella classe C)"},{"id":1682,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito alla modifica dell'art. 2425 c.c., l'avviamento:","correct":"va ammortizzato secondo la sua vita utile","wrong1":"va ammortizzato sempre entro 10 anni","wrong2":"va ammortizzato sempre entro 5 anni","wrong3":"va ammortizzato sempre entro la durata giudicata congrua dall'assemblea dei soci"},{"id":1683,"paragraph":"Economia delle aziende e delle PA - 22) Le principali novità del D.Lgs. 139/2015","question":"In seguito al D.Lgs. 139/2015, la nota integrativa:","correct":"deve dare notizia dei fatti di rilievo avvenuti dopo la chiusura dell'esercizio","wrong1":"non ha subito modifiche","wrong2":"ha subito modifiche soltanto con riferimento alle informazioni attinenti gli elementi dello stato patrimoniale","wrong3":"ha subito modifiche soltanto con riferimento alle informazioni attinenti gli elementi del conto economico"},{"id":1684,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Il principio di Rilevanza:","correct":"Lascia immutato l'obbligo di regolare tenuta delle scritture contabili","wrong1":"Impone la regolare tenuta delle scritture contabili, limitatamente a quelle giudicate \"opportune\" dagli amministratori","wrong2":"Impone la regolare tenuta delle scritture contabili, limitatamente a quelle giudicate \"opportune\" dai soci","wrong3":"Riconosce l'esenzione dall'obbligo della regolare tenuta delle scritture contabili"},{"id":1685,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"In virtù del principio di Prevalenza:","correct":"La rilevazione delle voci di bilancio deve essere effettuata in considerazione della sostanza economica dell'operazione","wrong1":"La rilevazione delle voci di bilancio deve essere effettuata in considerazione della natura giuridica dell'operazione","wrong2":"La rilevazione delle voci di bilancio deve essere sempre effettuata secondo il criterio del costo storico","wrong3":"Il valore da assegnare alle poste di bilancio deve essere preventivamente deciso dall'organo di controllo"},{"id":1686,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Tra i criteri previsti dal D.Lgs. 139/2015 per la suddivisione delle imprese, vi è quello che considera:","correct":"Il totale dell'Attivo di stato patrimoniale","wrong1":"Esclusivamente il totale dell'Attivo immobilizzato di stato patrimoniale","wrong2":"Esclusivamente il totale del Passivo circolante di stato patrimoniale","wrong3":"Esclusivamente il totale dell'Attivo operativo di stato patrimoniale"},{"id":1687,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Tra i requisiti previsti dalla mormativa affinché un'impresa possa essere considerata \"microimpresa\", è previsto che:","correct":"I ricavi delle vendite e della prestazioni non siano superiori a € 350.000","wrong1":"I ricavi delle vendite e della prestazioni non siano superiori a € 50.000","wrong2":"I ricavi delle vendite e della prestazioni non siano superiori a € 150.000","wrong3":"I ricavi delle vendite e della prestazioni non siano superiori a € 250.000"},{"id":1688,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Le microimprese devono comunque redigere:","correct":"Lo stato patrimoniale","wrong1":"Il rendiconto finanziario","wrong2":"La nota integrativa","wrong3":"La relazione sulla gestione"},{"id":1689,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Tra i requisiti previsti dalla mormativa affinché un'impresa possa essere considerata \"piccola\", è previsto che:","correct":"Il totale dell'attivo dello stato patrimoniale non sia superiore a € 4.400.000","wrong1":"Il totale delle immobilizzazioni materiali non sia superiore a € 4.400.000","wrong2":"Il totale dell'attivo immobilizzato non sia superiore a € 4.400.000","wrong3":"Il totale dell'attivo operativo non sia superiore a € 4.400.000"},{"id":1690,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Tra i requisiti previsti dalla mormativa affinché un'impresa possa essere considerata \"piccola\", è previsto che:","correct":"Il totale dei ricavi delle vendite non sia superiore a € 8.800.000","wrong1":"Il totale dei ricavi delle vendite non sia superiore a € 9.800.000","wrong2":"Il totale dei costi di acquisto delle materie non sia superiore a € 8.800.000","wrong3":"Il totale dei costi di acquisto delle materie non sia superiore a € 9.800.000"},{"id":1691,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Le \"piccole imprese\" devono comunque redigere:","correct":"La nota integrativa","wrong1":"Il rendiconto finanziario","wrong2":"Lo stato patrimoniale, senza alcuna semplificazione e/o accorpamento","wrong3":"La relazione sulla gestione"},{"id":1692,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Per la valutazione dei crediti, le \"piccole imprese\":","correct":"Possono adottare il criterio del \"costo ammortizzato\"","wrong1":"Devono adottare il criterio del \"costo ammortizzato\"","wrong2":"Possono adottare il criterio del \"ricavo ammortizzato\"","wrong3":"Devono adottare il criterio del \"ricavo ammortizzato\""},{"id":1693,"paragraph":"Economia delle aziende e delle PA - 23) La suddivisione delle imprese secondo il D.Lgs. 139/2015","question":"Alle \"Grandi imprese\":","correct":"È richiesto di conformarsi, per quanto possibile, ai principi IAS/IFRS","wrong1":"E' preclusa, in modo assoluto, la applicazione dei principi IAS/IFRS","wrong2":"Non è richiesta la elaborazione del rendiconto finanziario","wrong3":"Non richiesta la elaborazione della Relazione sulla gestione, se i ricavi non sono superiori a € 8.800.000"},{"id":1694,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"La struttura dello Stato patrimoniale è indicata dall'art.:","correct":"2424 c.c.","wrong1":"2425 c.c.","wrong2":"2426 c.c","wrong3":"2427 c.c."},{"id":1695,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"La struttura del Conto economico è indicata dall'art.:","correct":"2425 c.c.","wrong1":"2424 c.c.","wrong2":"2426 c.c","wrong3":"2427 c.c."},{"id":1696,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"In virtù dell'art. 2423 del c.c., così come integrato dal D.Lgs. 139/2015, è parte integrante del bilancio:","correct":"Il rendiconto finanziario","wrong1":"La relazione del Collegio sindacale","wrong2":"La relazione sulla gestione","wrong3":"La delibera assembleare di approvazione del bilancio"},{"id":1697,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"Gli schemi di conto economico e di stato patrimoniale previsti dal codice civile:","correct":"Possono subire modifiche, soltanto in casi limitati","wrong1":"Non sono passibili di modificazioni e/o raggruppamenti nelle voci","wrong2":"Sono da intendersi linee guida non vincolanti e dunque liberamente modificabili","wrong3":"Sono documenti che non costituiscono parte integrante del bilancio"},{"id":1698,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"In seguito alle modifiche introdotte dal D.Lgs. 139/2015, nello stato patrimoniale:","correct":"I costi di ricerca e pubblicità non vanno più indicati tra le immobilizzazioni","wrong1":"Le disponibilità liquide non vanno più indicate nell'attivo circolante","wrong2":"I costi di sviluppo non vanno più indicati tra le immobilizzazioni","wrong3":"Il capitale sociale non va più indicato tra le poste di patrimonio netto"},{"id":1699,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"In seguito alle modifiche introdotte dal D.Lgs. 139/2015, le informazioni prima espresse dai conti d'ordine:","correct":"Vanno obbligatoriamente riportate in nota integrativa","wrong1":"Vanno obbligatoriamente riportate nel conto economico","wrong2":"Vanno obbligatoriamente riportate nella relazione del Collegio sindacale","wrong3":"Vanno obbligatoriamente riportate nel rendiconto finanziario"},{"id":1700,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"Gli strumenti finanziari derivati passivi sono classificati in una nuova voce indicata:","correct":"Tra i fondi rischi e oneri","wrong1":"Tra le poste del patrimonio netto","wrong2":"Tra i debiti finanziari","wrong3":"Tra le rimanenze"},{"id":1701,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"Del conto economico, sono state abrogate le voci:","correct":"E)20 e E)21","wrong1":"C)15 e C)16","wrong2":"D)18 e D)19","wrong3":"A)1 e B)6"},{"id":1702,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"In seguito alle modifiche introdotte dal D.Lgs. 139/2015, la natura e gli effetti dei fatti di rilievo avvenuti dopo la chiusura dell'esercizio vanno riportati:","correct":"In nota integrativa","wrong1":"Nella relazione sulla gestione","wrong2":"Nel rendiconto finanzirio dell'esercizio già chiuso","wrong3":"Nel conto economico e nello stato patrimoniale dell'esercizio già chiuso"},{"id":1703,"paragraph":"Economia delle aziende e delle PA - 24) La struttura del nuovo bilancio d'esercizio: lo stato patrimoniale, il conto economico e la nota integrativa","question":"In seguito alle modifiche introdotte dal D.Lgs. 139/2015, in nota integrativa non è più richiesta:","correct":"La composizione dei costi di ricerca e di pubblicità","wrong1":"La composizione dei ratei e risconti attivi","wrong2":"La composizione dei ratei e risconti passivi","wrong3":"La composizione della voce \"altri fondi\""},{"id":1704,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"Il rendiconto finanziario deve evidenziare:","correct":"l'ammontare e la composizione delle disponibilità liquide, ed i flussi di cassa","wrong1":"le attività e la passività dell'azienda ad un determinato istante temporale, oltre i flussi di cassa","wrong2":"tutti i costi e tutti i ricavi dell'azienda, nonché i flussi di cassa","wrong3":"soltanto l'ammontare e la composizione dei flussi di cassa, senza indicazione delle disponibilità liquide"},{"id":1705,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"In merito al rendiconto finanziario, il codice civile:","correct":"non ne definisce il contenuto minimo, ma ne indica gli obiettivi","wrong1":"ne definisce il contenuto, senza indicare gli obiettivi","wrong2":"ne definisce sia il contenuto che gli obiettivi","wrong3":"non ne definisce il contenuto, né i relativi obiettivi"},{"id":1706,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"Il tipo di rendiconto finanziario da utilizzare:","correct":"è liberamente scelto da chi lo redige, tenendo conto della complessità dell'azienda cui il rendiconto si riferisce","wrong1":"è indicato dal codice civile","wrong2":"è scelto da chi lo redige, tenendo conto del preventivo parere del collegio sindacale","wrong3":"è scelto da chi lo redige, tenendo conto del preventivo parere dei soci"},{"id":1707,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"Il virtù dell'art. 2425 ter del c.c., nel rendiconto finanziario vanno evidenziati i flussi attinenti:","correct":"l'attività operativa; l'attività di investimento; l'attività di finanziamento","wrong1":"soltanto l'attività operativa e l'attività di investimento","wrong2":"soltanto l'attività di investimento e l'attività di finanziamento","wrong3":"soltanto l'attività operativa e l'attività di finanziamento"},{"id":1708,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"La suddivisione per aree individuata dall'art 2425 ter c.c. richiama quella individuata dallo:","correct":"IAS 7","wrong1":"IAS 8","wrong2":"IAS 10","wrong3":"IAS 11"},{"id":1709,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"In ambito nazionale, è interamente dedicato all'analisi del rendiconto finanziario:","correct":"l'OIC 10","wrong1":"l'OIC 8","wrong2":"l'OIC 9","wrong3":"l'OIC 35"},{"id":1710,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"In virtù dell'art. 2425 ter c.c., vanno separatamente indicate:","correct":"le operazioni con i soci","wrong1":"le operazioni con le banche","wrong2":"soltanto le operazioni con i soci di minoranza","wrong3":"soltanto le operazioni con i soci di maggioranza"},{"id":1711,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"Dopo il D.Lgs. 139/2015, tra i requisiti richiesti per l'esonero dalla redazione del bilancio consolidato, è previsto che le imprese controllanti, unitamente alle controllate, non devono superare:","correct":"€ 20 milioni nel totale degli attivi degli stati patrimoniale","wrong1":"€ 17,5 milioni nel totale degli attivi degli stati patrimoniale","wrong2":"€ 15 milioni nel totale degli attivi degli stati patrimoniale","wrong3":"€ 12,5 milioni nel totale degli attivi degli stati patrimoniale"},{"id":1712,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"Dopo il D.Lgs. 139/2015, tra i requisiti richiesti per l'esonero dalla redazione del bilancio consolidato, è previsto che le imprese controllanti, unitamente alle controllate, non devono superare:","correct":"€ 40 milioni nel totale dei ricavi delle vendite e delle prestazioni","wrong1":"€ 30 milioni nel totale dei ricavi delle vendite e delle prestazioni","wrong2":"€ 35 milioni nel totale dei ricavi delle vendite e delle prestazioni","wrong3":"€ 45 milioni nel totale dei ricavi delle vendite e delle prestazioni"},{"id":1713,"paragraph":"Economia delle aziende e delle PA - 25) La struttura del nuovo bilancio d'esercizio: il rendiconto finanziario. Il bilancio consolidato","question":"In virtù dell'art. 28 del D.Lgs. 127/1991, le imprese controllate possono essere escluse dal consolidamento se:","correct":"la loro inclusione sarebbe irrilevante ai fini della chiarezza e rappresentatività del bilancio","wrong1":"la percentuale di controllo detenuta dalla controllante è inferiore all'80%","wrong2":"l'esercizio effettttivo dei diritti della controllante non è soggetto a gravi e durature restrizioni","wrong3":"vi è il consenso unanime dei soci"},{"id":1714,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"I principi contabili:","correct":"sono regole tecnico-ragionieristiche che individuano i fatti da registrare ed i criteri di valutazione ed esposizione dei valori in bilancio","wrong1":"sono formule utilizzate per il calcolo delle varie poste che compongono il bilancio d'esercizio","wrong2":"vengono utilizzati esclusivamente dalle società con azioni quotate nei mercati regolamentati","wrong3":"sono disciplinati dalla Costituzione"},{"id":1715,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"L'organismo Italiano di Contabilità:","correct":"emana i principi contabili e fornisce supporto all'attività del Parlamento e degli Organi Governativi in materia di normativa contabile","wrong1":"è una società che ha il compito di revisionare i bilanci a livello nazionale","wrong2":"è un'istituzione internazionale con sede in Italia","wrong3":"emana le direttive per le sole società per azioni"},{"id":1716,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"La stesura dei principi contabili da parte dell'OIC:","correct":"è un processo in costante aggiornamento e perfezionamento","wrong1":"viene aggiornata con cadenza annuale salvo diverse disposizioni","wrong2":"è ferma dalla data della sua costituzione (2001)","wrong3":"viene aggiornata ogni 4 anni"},{"id":1717,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"I principi contabili internazionali:","correct":"sono emanati dallo ISAB","wrong1":"sono emanati dalla Comunità Europea","wrong2":"sono disciplinati da una commissione composta da rappresentanti di Francia Germania e Italia","wrong3":"sono di origine anglosassone"},{"id":1718,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"I principi contabili internazionali:","correct":"sono stati elevati da parte della Unione Europea al rango di regole contabili obbligatorie","wrong1":"non sono riconosciuti dallo Stato Italiano","wrong2":"vengono applicati sono in determinati paesi dell'UE","wrong3":"sono obbligatori per tutte le società dell'UE a prescindere dalla loro natura"},{"id":1719,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"Lo scopo degli IFRS:","correct":"è l'armonizzazione mondiale della contabilità","wrong1":"è uniformare il metodo di valutazione dei crediti iscritti in bilancio","wrong2":"è alleggerire la pressione fiscale delle società che operano in mercati esteri","wrong3":"riguarda questioni di carattere prettamente socio-ambientale"},{"id":1720,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"Il Framework:","correct":"costituisce la base teorica del regolamento per i bilanci IFRS","wrong1":"è una tabella contenente i valori da attribuire alle varie poste di bilancio","wrong2":"viene aggiornato mensilmente","wrong3":"è un criterio di valutazione"},{"id":1721,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"Al primo posto nella gerarchia dei soggetti interessati al bilancio ci sono:","correct":"gli investitori","wrong1":"le banche","wrong2":"i clienti","wrong3":"le Istituzioni pubbliche"},{"id":1722,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"Gli IAS/IFRS:","correct":"prediligono una rappresentazione dinamica del bilancio e l'obbligo di redazione del rendiconto finanziario","wrong1":"prediligono una rappresentazione statica del bilancio","wrong2":"prediligono una valutazione quanto più prudenziale","wrong3":"non prevedono la redazione del rendiconto finanziario"},{"id":1723,"paragraph":"Economia delle aziende e delle PA - 26) I principi contabili internazionali IAS/IFRS e i principi contabili nazionali dell'OIC","question":"In Italia la redazione del rendiconto finanziario:","correct":"non è obbligatoria, salvo in alcuni casi","wrong1":"non è prevista per nessuna società","wrong2":"è obbligatoria per le sole SpA","wrong3":"è obbligatoria per tutte le società di capitali"},{"id":1724,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Con l'espressione \"accounting harmonization\":","correct":"si intende il processo con il quale si è inteso far convergere la prassi contabile di determinati Paesi","wrong1":"si intende un criterio di misurazione dei profitti aziendali","wrong2":"viene ripreso il concetto di continuità aziendale","wrong3":"si intende l'intenzione di uniformare il modello contabile italiano a quello inglese"},{"id":1725,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Il processo di armonizzazione all'interno della Comunità Europea:","correct":"è iniziato alla fine degli anni 70","wrong1":"è avvenuto nel 2015","wrong2":"è iniziato alla fine degli anni 50","wrong3":"è in fase di studio"},{"id":1726,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Il fenomeno della globalizzazione:","correct":"ha determinato a livello europeo una svolta nella strategia in materia di armonizzazione contabile","wrong1":"non risente direttamente del processo di armonizzazione contabile","wrong2":"non interessa la comunità europea ma solo i mercati asiatici","wrong3":"riguarda gli Usa"},{"id":1727,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Ad oggi in Italia l'applicazione dei principi IAS/IFRS:","correct":"costituisce un obbligo solo per le società quotate e talune realtà del mondo finanziario","wrong1":"è ancora in fase di sperimentazione","wrong2":"coinvolge tutte le realtà imprenditoriali","wrong3":"riguarda solo le compagnie assicurative"},{"id":1728,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"L'obiettivo del bilancio redatto secondo i principi contabili internazionali:","correct":"è quello di fornire informazioni sulla posizione finanziaria sul risultato economico e sui flussi di disponibilità liquide di un'impresa","wrong1":"è quello di poter investire all'estero","wrong2":"è quello di ottenere un importante vantaggio fiscale","wrong3":"si concretizza nella possibilità di ottenere fonti di finanziamento estere"},{"id":1729,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"L'adozione di un set di principi contabili comune e condiviso a livello internazionale:","correct":"può essere in grado di offrire un miglioramento della visibilità aziendale","wrong1":"comporta inevitabilmente una serie di rischi","wrong2":"comprometterebbe l'ottimizzazione dell'immagine aziendale","wrong3":"sfavorisce la comparazione fra le informazioni patrimoniali economiche e finanziarie"},{"id":1730,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Il legislatore italiano:","correct":"ha esteso la facoltà di adozione dei principi contabili internazionali anche alle società non quotate","wrong1":"ha vietato l'applicazione dei principi Ias/Ifrs a tutte le società","wrong2":"non si è espresso riguardo all'applicazione dei principi contabili internazionali","wrong3":"ha obbligato l'applicazione dei principi Ias/Ifrs a tutte le società che redigono il bilancio in forma abbreviata"},{"id":1731,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Banche e intermediari finanziari:","correct":"sono obbligate all'utilizzo degli Ias/Ifrs","wrong1":"redigono il bilancio secondo i principi contabili nazionali","wrong2":"non redigono il bilancio","wrong3":"hanno la facoltà di scegliere quale set di principi contabili adottare"},{"id":1732,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Con la legge comunitaria del 31/10/2003 n. 306:","correct":"è stata conferita delega al governo per emanare decreti contenenti disposizioni necessarie al fine di individuare i soggetti interessati all'applicazione degli IAS/IFRS","wrong1":"l'Italia è stata obbligata all'applicazione dei principi ias/Ifrs","wrong2":"sono stati aboliti i principi contabili emanati dall'OIC","wrong3":"i principi contabili nazionali si sono accorpati ai principi contabili internazionali"},{"id":1733,"paragraph":"Economia delle aziende e delle PA - 27) Il processo di armonizzazione e standardizzazione contabile","question":"Società emittenti strumenti finanziari diffusi tra il pubblico:","correct":"sono obbligate all'applicazione dei principi contabili internazionali a prescindere dalla tipologia di bilancio che redigono","wrong1":"sono obbligate all'applicazione dei principi contabili internazionali solo se redigono il bilancio consolidato","wrong2":"sono obbligate all'applicazione dei principi contabili internazionali solo se redigono il bilancio non consolidato","wrong3":"sono tenute a redigere il bilancio secondo la prassi nazionale"},{"id":1734,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"I framework degli OIC e quelli degli IFRS:","correct":"presentano tra di loro alcune differenze che possono riflettersi sulla presentazione delle proprie performances e sui ratios di bilancio","wrong1":"sono pressochè identici","wrong2":"non hanno alcun punto in comune","wrong3":"sono disciplinati e monitorati dallo stesso Organsimo"},{"id":1735,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"I principi contabili nazionali:","correct":"derivano dal Libro V del codice civile e integrati dalle regole contabili emanate dall'OIC","wrong1":"derivano dalla Costituzione","wrong2":"derivano esclusivamente dall'Organismo Italiano di Contabilità","wrong3":"vengono emanati dal Consiglio Nazionale dei Dottori Comercialisti"},{"id":1736,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"Gli IFRS:","correct":"sono principi contabili internazionali emessi da un organismo indipendente (IASB)","wrong1":"vengono emanati dalla Comunità Europea","wrong2":"si applicano solo alle società europee","wrong3":"sono disciplinati dal Codice Civile"},{"id":1737,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"I principi contabili nazionali:","correct":"hanno lo scopo di tutelare e misurare il patrimonio aziendale, servendosi così del bilancio d'esercizio come strumento di analisi","wrong1":"seguono una logica investor-oriented e cioè si pongono come obiettivo quello di rispondere alle esigenze informative degli investitori","wrong2":"si applicano prevalentemente ai bilanci consolidati","wrong3":"sono disciplinati dal Framework dello IASB"},{"id":1738,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"I principi contabili internazionali:","correct":"mirano principalmente a fornire un'informativa agli investitori e a tutti gli stakeholders in generale","wrong1":"si applicano prevalentemente ai bilanci consolidati","wrong2":"non seguono una logica investor-oriented","wrong3":"sono disciplinati dall'OIC 11"},{"id":1739,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"Lo IAS 7:","correct":"contiene le disposizioni per la redazione del rendiconto finanziario e la presentazione dell'informativa sui flussi finanziari","wrong1":"afferma che la redazione del rendiconto finanziario non è obbligatoria","wrong2":"disciplina il criterio di misurazione secondo la logica dell'impairment test","wrong3":"contiene le disposizioni generali per la redazione del bilancio"},{"id":1740,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"Gli IFRS:","correct":"si limitano a indicare una serie di informazioni minime da menzionare","wrong1":"non richiedo un'esplicita dichiarazione di conformità ai principi contabili internazionali in vigore alla data di bilancio","wrong2":"variano a seconda della paese in cui vengono applicati","wrong3":"prevedono uno standard che deve essere contenuto nei documenti di bilancio"},{"id":1741,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"La relazione sulla gestione:","correct":"è un documento obbligatorio richiesto dall'art. 2428 C.C.","wrong1":"è un documento obbligatorio richiesto dallo IAS 1","wrong2":"è redatto dai dipendenti della società","wrong3":"segue regole di pubblicità e approvazione diverse da quelle previste per il bilancio."},{"id":1742,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"La capitalizzazione dei costi pluriennali:","correct":"è consentita dall'OIC 24","wrong1":"è consentita dallo IAS 38","wrong2":"è ammessa in entrambi i set di principi contabili","wrong3":"non è ammessa mai, a prescindere dalla prassi contabile adottata"},{"id":1743,"paragraph":"Economia delle aziende e delle PA - 28) Modelli di bilancio (civilistico e internazionale) a confronto: scopo e destinatari; principi di redazione; schemi","question":"L'ammortamento per l'avviamento:","correct":"è vietato per i principi Ias/Ifrs","wrong1":"è vietato per la prassi nazionale","wrong2":"è ammesso in entrambi i set di principi contabili","wrong3":"non è ammesso mai, a prescindere dalla prassi contabile adottata"},{"id":1744,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"Il codice civile prevede:","correct":"che i criteri di valutazione non possano essere modificati da un esercizio all'altro se non in casi eccezionali","wrong1":"che i criteri di valutazione possano essere modificati da un esercizio all'altro","wrong2":"che nel caso di modifica dei criteri di valutazione non è necessario motivare tale accadimento in nota integrativa","wrong3":"che i criteri di valutazione non possano essere mai modificati"},{"id":1745,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"L'OIC 33:","correct":"disciplina il passaggio da IFRS a principi contabili nazionali","wrong1":"disciplina il passaggio da principi contabili nazionali a IFRS","wrong2":"non è applicabile nell'ordinamento italiano","wrong3":"non stabilisce il momento da cui le nuove disposizioni devono avere effetti sulle poste del bilanci"},{"id":1746,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"L'IFRS 1:","correct":"disciplina il passaggio da principi contabili nazionali a IFRS","wrong1":"è stato sostituito da altri principi contabili","wrong2":"è disciplinato anche dal Codice Civile","wrong3":"disciplina il passaggio da IFRS a principi contabili nazionali"},{"id":1747,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"Il ritorno agli OIC:","correct":"si effettua in modo retroattivo","wrong1":"è un'operazione che si conclude in più anni","wrong2":"è possibile per le sole società quotate","wrong3":"non è consentito per chi in precedenza applicava i pricipi contabili internazionali"},{"id":1748,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"Il passaggio da IFRS a principi contabili nazionali:","correct":"dev'essere debitamente motivato in nota integrativa","wrong1":"può essere motivato in nota integrativa, a discrezione degli amministratori","wrong2":"non produce alcuna riclassificazione delle poste di bilancio","wrong3":"non è necessario specificare la data di transizione"},{"id":1749,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"FTA sta per:","correct":"First Time Adopter","wrong1":"Funzione Tecnico Amministrativa","wrong2":"First Time Analysis","wrong3":"Free Trade Agreement"},{"id":1750,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"Nel passaggio da principi contabili nazionali a IFRS:","correct":"in nota integrativa va fornita un'ampia disclosure descrittiva delle principali operazioni messe in atto","wrong1":"la redazione della nota integrativa non è obbligatoria","wrong2":"non è necessario evidenziare le riconciliazioni richieste","wrong3":"non è necessario stabilire una data di transizione"},{"id":1751,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"L'articolo 13 del d.lgs 38/2005:","correct":"sancisce il principio di irrilevanza fiscale delle rettifiche da conversione","wrong1":"disciplina il passaggio da principi contabili nazionali a IFRS","wrong2":"disciplina le informazioni necessarie da inserire in nota integrativa","wrong3":"disciplina il passaggio da IFRS a principi contabili nazionali"},{"id":1752,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"L'adozione dei principi contabili internazionali:","correct":"porta con sé un miglioramento dell'accounting quality","wrong1":"non produce alcun effetto rilevante","wrong2":"comporta inevitabilmente un aumento degli asset patrimoniali","wrong3":"comporta per il primo anno di applicazione sempre una perdita d'esercizio"},{"id":1753,"paragraph":"Economia delle aziende e delle PA - 29) Il cambiamento dei principi contabili: dai principi contabili nazionali agli IFRS e dagli IFRS ai principi contabili nazionali","question":"L'earnings management:","correct":"è definibile come quell'asimmetria informativa presente fra manager dell'azienda e portatori di interesse","wrong1":"è incentivata se si adottano i prncipi contabili internazionali","wrong2":"consiste nell'attribuire più poter all'organo direttivo","wrong3":"è disciplinato dallo IAS 2"},{"id":1754,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Gli Ias/Ifrs:","correct":"prediligono l'utilizzo del fair value","wrong1":"prediligono l'utilizzo del costo storico","wrong2":"prediligono entrambi i criteri di valutazione a secondo dell'ambito di applicazione","wrong3":"vietano entrambi i criteri di valutazione"},{"id":1755,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il criterio del costo storico:","correct":"considera il costo di acquisto o produzione","wrong1":"non coinvolge anche eventuali costi accessori diretti","wrong2":"è un metodo non adottabile per prodotti ottenuti mediante fonti interne all'impresa","wrong3":"è un metodo utilizzato a pertire dagli anni 2000"},{"id":1756,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il criterio del costo storico:","correct":"non è adottabile dalle società che hanno titoli quotati in mercati regolamentati","wrong1":"è obbligatorio per tutte le società","wrong2":"è obbligatorio solo per le società quotate","wrong3":"è poco utilizzato a livello nazionale"},{"id":1757,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il metodo del fair value:","correct":"rientra tra i principi contabili internazionali","wrong1":"rientra tra i principi contabili nazionali","wrong2":"non può essere utilizzato all'interno dell'Unione Europea","wrong3":"non può essere utilizzato in Italia"},{"id":1758,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"La gerarchia dei parametri da prendere in considerazione per la determinazione del fair value è:","correct":"1Prezzi di mercato 2Valore di confronto 3Valore approssimativo","wrong1":"1Valore approssiativo 2Prezzi di mercato 3Valore di confronto","wrong2":"1Prezzi di mercato 2Valore approssimativo 3Valore di confronto","wrong3":"1Valore di confronto 2Valore approssimativo 3Prezzi di mercato"},{"id":1759,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il metodo della valutazione di mercato:","correct":"mira direttamente al mercato di riferimento e considera i parametri di base dei primi due livelli nella valutazione del fair value","wrong1":"è un procedimento di calcolo che non mira al mercato","wrong2":"è nota anche come Income Approach","wrong3":"determina il fair value sulla base di criteri di valutazione presenti sul terzo livello della gerarchia."},{"id":1760,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il metodo reddituale:","correct":"considera diversi fattori per poi attualizzare il valore con il reddito corrente","wrong1":"è noto anche come Market Approach","wrong2":"considera tutti i costi che sono necessari per rappresentare il valore del bene","wrong3":"è caratterizzato da stime tendenzialmente oggettive"},{"id":1761,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il metodo del costo:","correct":"è noto anche come Cost Approach","wrong1":"permette di rappresentare a futura resa commerciale","wrong2":"non considera i costi di produzione","wrong3":"comprende 3 approcci per la determinzione del fair value"},{"id":1762,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il costo storico:","correct":"è un metodo facilmente identificabile, poiché riferito a valori rilevati in passato","wrong1":"è un metodo soggettivo","wrong2":"non è coerente con il principio contabile della prudenza","wrong3":"è difficilmente applicabile"},{"id":1763,"paragraph":"Economia delle aziende e delle PA - 30) La logica del costo e del Fair Value nella redazione del bilancio","question":"Il fair value:","correct":"è coerente con il principio della coerenza","wrong1":"è un metodo oggettivo","wrong2":"in ambito applicativo comporta costi minori rispetto al metodo del costo storico","wrong3":"non necessita della valutazione di un perito"},{"id":1764,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Il Framework dell'International Accounting Standards Board (IASB):","correct":"è stato pubblicato allo scopo di sostenere il perseguimento dell'obiettivo della standardizzazione contabile internazionale","wrong1":"è stato pubblicato allo scopo di sostenere il perseguimento dell'obiettivo della suddivisione contabile internazionale","wrong2":"è stato pubblicato nel 1991","wrong3":"è stato pubblicato nel 2015"},{"id":1765,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Secondo il quadro concettuale:","correct":"i bilanci intendono fornire una rappresentazione fedele della gestione realizzata durante l'ultimo esercizio","wrong1":"i bilanci intendono fornire uno specifico livello di disclosure delle informazioni ritenute non rilevanti","wrong2":"i bilanci intendono fornire una rappresentazione dei soli costi della gestione realizzata durante l'ultimo esercizio","wrong3":"i bilanci intendono fornire una rappresentazione dei soli ricavi della gestione realizzata durante l'ultimo esercizio"},{"id":1766,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Gli elementi strutturali che all'interno del Framework vengono indicati come costitutivi del bilancio d'esercizio sono:","correct":"le attività, le passività, il capitale netto, i costi ed i ricavi","wrong1":"le attività e le passività","wrong2":"i costi ed i ricavi","wrong3":"le attività, le passività, il capitale netto"},{"id":1767,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"I prospetti che compongono il bilancio redatto in base ai principi contabili internazionali sono:","correct":"Situazione patrimoniale/finanziaria, conto economico complessivo, prospetto delle variazioni di patrimonio netto, rendiconto finanziario e note al bilancio","wrong1":"Situazione patrimoniale/finanziaria, conto economico e relazione sulla gestione","wrong2":"Stato patrimoniale, conto economico e nota integrativa","wrong3":"Stato patrimoniale, situazione economica, rendiconto finanziario e note al bilancio"},{"id":1768,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Le attività sono:","correct":"risorse controllate dall'azienda (risultato di operazioni svolte in passato) dalle quali sono attesi futuri benefici economici","wrong1":"risorse controllate dall'azienda (risultato di operazioni svolte in passato) dalle quali non sono attesi futuri benefici economici","wrong2":"sono obbligazioni attuali dell'azienda (nascenti da operazioni realizzate in passato) il cui regolamento condurrà all'uscita di risorse economiche che costituiscono benefici economici","wrong3":"sono costituite dal valore residuo delle passività dell'azienda dopo avere detratto il patrimonio netto"},{"id":1769,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Con il metodo del costo corrente:","correct":"le attività sono iscritte in bilancio indicando l'importo delle risorse finanziarie che dovrebbero essere impiegate per pagare un bene simile od uguale qualora esso fosse acquistato attualmente, ovvero il giorno della sua eventuale sostituzione (rimpiazzo)","wrong1":"le attività sono contabilizzate registrando l'ammontare di denaro che potrebbe essere ottenuto vendendo sul mercato la stessa attività in normali condizioni di funzionamento","wrong2":"le attività sono rilevate con l'ammontare di mezzi finanziari che occorrerebbe pagare per estinguere attualmente l'obbligazione, ovvero nel momento in cui viene redatto il bilancio","wrong3":"le attività figurano al valore delle risorse finanziarie che si prevede occorrano per estinguere il debito in normali condizioni di operatività."},{"id":1770,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Lo IAS 1:","correct":"richiede un'esplicita dichiarazione di conformità ai principi contabili internazionali in vigore alla data di bilancio","wrong1":"non richiede alcuna dichiarazione di conformità specifica","wrong2":"è stato sostituito negli anni dallo IAS 10","wrong3":"riguarda i criteri di valutazione delle immobilizzazioni"},{"id":1771,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Le informazioni in nota integrativa sono disciplinate dall'art.:","correct":"2427 cc","wrong1":"2423 cc","wrong2":"2420 cc","wrong3":"2430 cc"},{"id":1772,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"La relazione sulla gestione:","correct":"è un'analisi fedele, equilibrata ed esauriente della situazione della società e dell'andamento e del risultato della gestione nel suo complesso e nei vari settori in cui essa ha operato","wrong1":"è disciplinata dall'art. 2430 C.C.","wrong2":"contiene dati economico/finanziari","wrong3":"è un documento abolito dall'ordinamento italiano"},{"id":1773,"paragraph":"Economia delle aziende e delle PA - 31) Rilevazione, valutazione e rappresentazione delle principali poste di bilancio secondo i principi contabili nazionali e internazionali","question":"Le note al bilancio:","correct":"rappresentano una sezione che contiene una parte descrittiva del bilancio IFRS","wrong1":"rappresentano una sezione che illustra i costi e i ricavi che compongono l'utile o la perdita dell'esercizio","wrong2":"rappresentano una sezione che include le 'altre componenti' di conto economico, ossia costi e ricavi che si accumulano nelle riserve del patrimonio netto","wrong3":"illustrano le variazioni di valore di alcuni strumenti finanziari valutati a fair value"},{"id":1774,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"La continuità aziendale:","correct":"è la capacità dell'azienda di produrre risultati positivi e generare correlati flussi finanziari nel tempo","wrong1":"è la capacità dell'azienda di generare profitti","wrong2":"è la capacità dell'azienda di mantenere la propria quota di mercato nel tempo","wrong3":"è la capacità dell'azienda di durare per più di 20 anni"},{"id":1775,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Il presupposto della continuità aziendale è richiamato:","correct":"nell'OIC 11","wrong1":"nell'OIC 5","wrong2":"nell'OIC 29","wrong3":"nell'OIC 10"},{"id":1776,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Per i principi contabili internazionali, il presupposto della continuità aziendale è richiamato:","correct":"nello IAS 1","wrong1":"nello IAS 10","wrong2":"nello IAS 11","wrong3":"nello IAS 24"},{"id":1777,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Il nuovo OIC 11 è entrato in vigore:","correct":"nel 2018","wrong1":"nel 2010","wrong2":"nel 2012","wrong3":"nel 2017"},{"id":1778,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Il nuovo OIC 11:","correct":"focalizza l'attenzione sul concetto di rappresentazione veritiera e corretta della situazione patrimoniale e finanziaria dell'impresa nonché del risultato economico d'esercizio","wrong1":"contiene una serie di modifiche riguardanti la valutazione dei crediti immobilizzati","wrong2":"non richiama il concetto di continuità aziendale","wrong3":"si discosta dalle disposizione contenute nel Codice Civile"},{"id":1779,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Le modifiche principali ai postulati dell'OIC 11 riguardano:","correct":"1(la prevalenza della sostanza sulla forma 2) la rilevanza delle informazioni 3) la prospettiva della continuità aziendale","wrong1":"1) la prevalenza della forma sulla stanza 2) la rilevanza delle informazioni","wrong2":"1) i nuovi criteri di valutazione dei crediti immobilizzati 2) l'introduzione del metodo del fair value 3) il cambiamento dei criteri di valutazione adottati","wrong3":"1 l'informativa da fornire in nota integrativa 2 la prospettiva della continuità aziendale"},{"id":1780,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Secondo il nuovo OIC 11:","correct":"la \"continuità aziendale\" si sostanzia nella capacità dell'impresa di continuare a costituire un complesso economico funzionante destinato alla produzione di reddito per un prevedibile arco temporale futuro relativo ad un periodo di almeno 12 mesi dalla data di riferimento del bilancio","wrong1":"il presupposto della continuità aziendale si verifica nei momenti di crisi di impresa","wrong2":"la \"continuità aziendale\" si sostanzia nella capacità dell'impresa di continuare a costituire un complesso economico funzionante destinato alla produzione di reddito per un prevedibile arco temporale futuro relativo ad un periodo di almeno 8 mesi dalla data di riferimento del bilancio","wrong3":"la \"continuità aziendale\" si sostanzia nella capacità dell'impresa di continuare a costituire un complesso economico funzionante destinato alla produzione di reddito per un prevedibile arco temporale futuro relativo ad un periodo di almeno 24 mesi dalla data di riferimento del bilancio."},{"id":1781,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Tra i principali indicatori di rischio di continuità aziendale vanno evidenziati:","correct":"indicatori finanziari, indicatori gestionali, altri indicatori","wrong1":"indicatori economici, indicatori gestionali, indicatori finanziari","wrong2":"indicatori socio-economici, indicatori patrimoniali, altri indicatori","wrong3":"indicatori finanziari e economici"},{"id":1782,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"I principi di revisione ISA Italia affrontano il tema della continuità aziendale mediante il principio:","correct":"ISA Italia 570","wrong1":"ISA Italia 500","wrong2":"ISA Italia 315","wrong3":"ISA Italia 402"},{"id":1783,"paragraph":"Economia delle aziende e delle PA - 32) Il rischio di continuità aziendale nel bilancio OIC e IFRS","question":"Gli indicatori di rischio di continuità aziendale:","correct":"sono utili a sintetizzare le principali minacce che in genere possono generare dei rischi per la vita dell'azienda in una prospettiva durevole","wrong1":"misurano il rischio della perdita di capitale","wrong2":"sono utili a sintetizzare le principali opportunità per la vita dell'azienda in una prospettiva di liquidazione","wrong3":"sono utili a sintetizzare le principali opportunità per la vita dell'azienda in una prospettiva durevole"},{"id":1784,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Il report integrato si pone l'obiettivo di:","correct":"realizzare una rappresentazione delle performance aziendali, attraverso l'integrazione della rendicontazione finanziaria con quella non finanziaria","wrong1":"ilustrare gli obiettivi che l'azienda si prefigge di raggiungere nel medio-lungo periodo","wrong2":"informare gli stakeholder della capacità dell'azienda di generare profitto e correlati flussi finanziari nel tempo","wrong3":"analizzare le varie poste di bilancio attreverso una riclassificazione delle stesse"},{"id":1785,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Con il termine \"rendicontazione non-finanziaria\" si intende:","correct":"l'insieme degli strumenti di reporting che unitamente alle performance economico-finanziarie, restituiscono informazioni sulle variabili non-finanziarie presenti in azienda","wrong1":"rappresentare i dati di bilancio di un'azienda mediante forme di pubblicità innovatve","wrong2":"la rappresentazione, in chiave di lettura, dei principali asset patrimoniali di un'azienda","wrong3":"la rappresentazione che viene redatta dalle associazioni no-profit"},{"id":1786,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"In Italia, una forte spinta alla diffusione della rendicontazione non finanziaria è generata:","correct":"dal D.Lgs. 254/2016","wrong1":"dall'art. 2423 C.C.","wrong2":"dal D.Lgs 14/2019","wrong3":"dal D.Lgs 81/2008"},{"id":1787,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Due i principali modelli di rendicontazione non finanziaria:","correct":"bilancio di sostenibilità e report integrato","wrong1":"bilancio sociale e report integrato","wrong2":"bilancio sociale e di sostenibilità","wrong3":"report integrato e relazione sulla gestione"},{"id":1788,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Il report integrato è emanato da:","correct":"IIRC","wrong1":"ISAB","wrong2":"Codice Civile","wrong3":"Unione Europea"},{"id":1789,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Le aziende che oggi adottano il Bilancio Integrato intendono, tra l'altro:","correct":"migliorare la qualità delle informazioni disponibili al mercato e comunicare i fattori che influenzano la capacità dell'azienda di creare valore","wrong1":"ottenere vantaggi fiscali","wrong2":"sottrarsi agli obblighi di redazione del bilancio d'esercizio, in quanto più oneroso","wrong3":"comunicare i dati di bilancio delle società controllate e collegate"},{"id":1790,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Il Framework internazionale:","correct":"presenta i requisiti da applicare affinché un report integrato possa essere considerato conforme","wrong1":"stabilisce specifici indicatori di performance","wrong2":"introduce metodi di misurazione da utilizzare","wrong3":"stabilisce le singole questioni per le quali si devono fornire informazioni"},{"id":1791,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Un report integrato deve includere:","correct":"una dichiarazione di responsabilità in merito al report della governance","wrong1":"il bilancio d'esercizio","wrong2":"il rendiconto finanziario e la relazione sulla gestione","wrong3":"il bilancio d'esercizio redatto secondo i principi Ias/Ifrs"},{"id":1792,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Il report integrato:","correct":"può essere obbligatorio o facoltativo","wrong1":"è obbligatorio per tutte le società","wrong2":"è sempre facoltativo","wrong3":"è obbligatorio per le società per azioni"},{"id":1793,"paragraph":"Economia delle aziende e delle PA - 33) Comunicazione non finanziaria e reporting","question":"Tra i capitali individuati dal framework, si ricorda il capitale:","correct":"naturale","wrong1":"economico","wrong2":"ambientale","wrong3":"culturale"},{"id":1794,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Nelle amministrazioni pubbliche territoriali, quali nuclei produttivi si possono individuare:","correct":"il nucleo produttivo per il consumo, il nucleo produttivo patrimoniale, il nucleo produttivo d'impresa","wrong1":"il nucleo produttivo d'impresa, il nucleo produttivo per il consumo","wrong2":"il nucleo produttivo d'impresa, il nucleo produttivo economico","wrong3":"il nucleo produttivo per il consumo, il nucleo produttivo patrimoniale"},{"id":1795,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"In quali nuclei si svolgono processi produttivi finalizzati allo scambio di mercato:","correct":"nel nucleo produttivo patrimoniale e nel nucleo produttivo d'impresa","wrong1":"nel nucleo produttivo per il consumo e nel nucleo produttivo economico","wrong2":"il nucleo produttivo per il consumo, il nucleo produttivo patrimoniale","wrong3":"il nucleo produttivo d'impresa, il nucleo produttivo per il consumo"},{"id":1796,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"In cosa si concretizza la gestione aziendale:","correct":"la gestione aziendale si concretizza in operazioni attraverso le quali si acquisisce, si combina e si cede valore","wrong1":"la gestione aziendale si concretizza in operazioni attraverso le quali si realizza il processo produttivo","wrong2":"la gestione aziendale si concretizza in operazioni attraverso le quali si reperiscono fonti di finanziamento","wrong3":"la gestione aziendale si concretizza in operazioni attraverso le quali si acquistano e si vendono beni e servizi"},{"id":1797,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Le operazioni di gestione esterna in cosa si concretizzano:","correct":"all'acquisizione dei fattori produttivi (input) e alla cessione dei beni e/o servizi prodotti (output)","wrong1":"alle operazioni relative all'esercizio dell'attività principale o tipica dell'azienda","wrong2":"alle operazioni di reperimento di fonti di finanziamento","wrong3":"alle operazioni di erogazione di servizi pubblici"},{"id":1798,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Le operazioni di gestione caratteristica in cosa si concretizzano:","correct":"all'esercizio dell'attività principale o tipica dell'azienda","wrong1":"alle operazioni di reperimento di fonti di finanziamento","wrong2":"alle operazioni di erogazione di servizi pubblici","wrong3":"alle operazioni di analisi del settore pubblico"},{"id":1799,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Cosa sono i flussi di stock economici:","correct":"sono i flussi relativi ai beni materiali, diritti (o crediti) economici e obblighi (o debiti) economici","wrong1":"sono i flussi relativi alla accumulazione di beni o denaro","wrong2":"sono i flussi relativi alle analisi degli investimenti da realizzare","wrong3":"sono i flussi relativi alla accumulazione di crediti e debiti"},{"id":1800,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Cosa sono i flussi di stock finanziari:","correct":"sono i flussi relativi a mezzi liquidi disponibili, diritti (o crediti) finanziari, obblighi (o debiti) finanziari\"","wrong1":"sono i flussi relativi alla accumulazione di beni o denaro","wrong2":"sono i flussi relativi alle analisi degli investimenti da realizzare","wrong3":"sono i flussi relativi ai beni materiali, diritti (o crediti) economici e obblighi (o debiti) economici"},{"id":1801,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Quali sono le fasi della produzione per il consumo:","correct":"la raccolta delle risorse e l'impiego dei mezzi raccolti","wrong1":"l'acquisto dei fattori produttivi e la loro trasformazione","wrong2":"la produzione dei beni e la olro vendita sul mercato","wrong3":"l'analisi di mercato e la successiva produzione di beni e servizi"},{"id":1802,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Come possono essere i trasferimenti:","correct":"correnti ed in conto capitale","wrong1":"investibili e non investibili","wrong2":"esigibili e non esigibili","wrong3":"relativi alla gestione caratteristica o non caratteristica"},{"id":1803,"paragraph":"Economia delle aziende e delle PA - 34) Il finanziamento delle imprese pubbliche: la Teoria dei flussi e degli stocks e il nucleo produttivo per il consumo","question":"Cosa determinano i processi di acquisto di beni e servizi:","correct":"fatti di gestione esterna che individuano veri e propri scambi di mercato","wrong1":"fatti di gestione che determinano investimenti finanziari","wrong2":"fatti di gestione che influenzano la redditività","wrong3":"fatti di gestione interna di trasformazione degli input in output"},{"id":1804,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Le attività del nucleo produttivo patrimoniale su cosa sono focalizzate:","correct":"alle logiche dello scambio di mercato","wrong1":"alle logiche del consumo interno","wrong2":"alle logiche dele valutazioni di convenienza economica","wrong3":"alle logiche proprie delle condizioni di monopolio"},{"id":1805,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Le attività del nucleo produttivo patrimoniale da cosa traggono origine:","correct":"la formazione del nucleo tecnico patrimoniale ha origine, di solito, dal risparmio generatosi nell'ambito del nucleo tecnico per il consumo","wrong1":"la formazione del nucleo tecnico patrimoniale ha origine, di solito, da specifiche attività di finanziamento","wrong2":"la formazione del nucleo tecnico patrimoniale ha origine, di solito, da attività collegate alle tariffe definite per i servizi pubblici","wrong3":"la formazione del nucleo tecnico patrimoniale ha origine, di solito, da attività di investimento"},{"id":1806,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"La conduzione del patrimonio redditizio comporta il conseguimento di rendite e il sostenimento di costi che individuano quale gestione:","correct":"la gestione patrimoniale ordinaria","wrong1":"la gestione economica","wrong2":"la gestione straordinaria","wrong3":"la gestione finanziaria"},{"id":1807,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Le rendite ed i costi generati dalla gestione patrimoniale ordinaria quale valenza temporale hanno:","correct":"hanno valenza annuale","wrong1":"hanno valenza pluriennale","wrong2":"la valenza temporale è indifferente","wrong3":"hanno valenza infrannuale"},{"id":1808,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"I processi del nucleo produttivo d'impresa a cosa attengono:","correct":"a beni e servizi destinati alla vendita","wrong1":"ad attività puramente patrimoniali","wrong2":"ad attività finanziarie","wrong3":"ad attività di investimenti"},{"id":1809,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Nel nucleo produttivo d'impresa, lo svolgimento dei processi produttivi come può realizzarsi:","correct":"in modo diretto ed in modo indiretto (con o senza controllo finanziario)","wrong1":"solo in modo diretto","wrong2":"solo attraverso imprese in concessione","wrong3":"attraverso imprese che operano in monopolio"},{"id":1810,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"In quali situazioni si preferisce il ricorso a forme di monopolio:","correct":"quando condizioni tecniche e naturali rendono più efficiente la presenza di unico produttore","wrong1":"quando condizioni di remunerazione dei capitali investiti lo richiedono","wrong2":"quando il legislatore lo dispone espressamente","wrong3":"quando è preferibile evitare situazioni di concorrenza"},{"id":1811,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Nei processi del nucleo produttivo d'impresa, l'erogazione del servizio può essere svolta da più aziende in competizione regolata fra loro:","correct":"sì, dietro il pagamento di una tariffa per l'accesso alla rete","wrong1":"non è mai prevista tale situazione","wrong2":"sì, ma solo se tali aziende operano in monopolio nel proprio settore","wrong3":"sì, solo nelle situazioni di outsourcing"},{"id":1812,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"Nella prospettiva economico-aziendale, come può essere distinto il valore pubblico:","correct":"valore proposto e valore riconosciuto","wrong1":"valore economico e valore patrimoniale","wrong2":"valore economico e valore finanziario","wrong3":"valore monetario e valore finanziario"},{"id":1813,"paragraph":"Economia delle aziende e delle PA - 35) Il nucleo produttivo patrimoniale ed il nucleo produttivo d'impresa","question":"La misura del valore pubblico va riferita ad un periodo temporale:","correct":"va sempre riferita ad un periodo temporale","wrong1":"non è mai riferita ad un periodo temporale","wrong2":"il riferimento al periodo temporale è indifferente","wrong3":"dipende dalla tipologia di valore pubblico considerata"},{"id":1814,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Quando hanno avuto inizio le prime riforme in termini di autonomia nel settore pubblico italiano:","correct":"nei primi anni '90 con la legge 142/1990","wrong1":"nel periodo immediatamente successivo alla seconda guerra mondiale","wrong2":"con lo sviluppo del Welfare State","wrong3":"dopo gli anni 2000"},{"id":1815,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Su cosa si basava il previgente sistema finanziario prime delle spinte autonomistiche:","correct":"su un meccanismo di finanza derivata","wrong1":"sul sistema delle imposte e tasse","wrong2":"sull'esistenza di vincoli di spesa","wrong3":"sull'adozione delle tariffe"},{"id":1816,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Le disparità nell'erogazione dei servizi, come erano risolte:","correct":"con il principio della spesa storica","wrong1":"con l'utilizzo di risorse derivanti dalle tasse","wrong2":"con l'adozione di specifiche imposte aggiuntive","wrong3":"con il principio dei costi effettivi di gestione dei servizi"},{"id":1817,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Su cosa si basava il principio della spesa storica:","correct":"risorse venivano distribuite alle varie APT sulla base dei livelli di spesa storicamente effettuati","wrong1":"risorse venivano distribuite alle varie APT sulla base della popolazione servita","wrong2":"risorse venivano distribuite alle varie APT sulla base delle differenze di ricchezza delle Regioni","wrong3":"risorse venivano distribuite alle varie APT sulla base del numero di dipendenti in carico"},{"id":1818,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Il passaggio ad un sistema di finanza federale da quale normativa è previsto:","correct":"la riforma del Titolo V della Costituzione, ed in particolare nell'art. 119","wrong1":"la Legge 142/1990","wrong2":"il D.lgs 150/2009 c.d. Brunetta","wrong3":"il D.lgs 286/1999"},{"id":1819,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Con la legge n. 42 del 5 maggio 2009 (e successivi decreti) cosa si è realizzato:","correct":"si è conferito al governo la delega in materia di federalismo fiscale","wrong1":"si è conferito alle amministrazioni territoriali la liberta di definire il livello delle tariffe","wrong2":"la privatizzazione di molti dei sevizi pubblici territoriali","wrong3":"la privatizzazione del rapporto di pubblico impiego"},{"id":1820,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"In sanità il fondo perequativo a favore di chi opera:","correct":"a favore delle regioni con minore capacità fiscale per abitante","wrong1":"a favore delle regioni che hanno un minor numero di ospedali sul territorio","wrong2":"a favore delle regioni con maggiori debiti","wrong3":"a favore delle regioni maggiormente virtuose"},{"id":1821,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Il principio di perquazione in sanità cosa deve assicurare:","correct":"l'integrale copertura delle spese corrispondenti al fabbisogno standard per i livelli essenziali delle prestazioni","wrong1":"l'integrale copertura delle spese totali sanitarie regionali","wrong2":"solo la copertura dei costi degli ospedali","wrong3":"solo la copertura delle prestazioni erogate dalle ASL"},{"id":1822,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Cosa accade se il deficit di un Servizio Sanitario Regionale è di importo contenuto:","correct":"si applicano procedure di razionalizzazione","wrong1":"si applicano procedure di commissariamento","wrong2":"si applicano procedure di chiusura ospedali","wrong3":"si applicano procedure di riduzione delle prestazioni sanitarie erogate"},{"id":1823,"paragraph":"Economia delle aziende e delle PA - 36) Il federalismo fiscale: analisi nell'ottica delle imprese pubbliche e nell'ottica del settore sanitario","question":"Quando per un Sistema Sanitario Regionale si ha la procedura di piano di rientro:","correct":"nelle situazioni di deficit superiore al 7%","wrong1":"nelle situazioni di deficit superiore al 10%","wrong2":"nelle situazioni di deficit superiore al 15%","wrong3":"nelle situazioni di deficit superiore al 20%"},{"id":1824,"paragraph":"Economia delle aziende e delle PA - 37) L'attività di direzione e il sistema di misurazione dei costi: un quadro di riferimento introduttivo","question":"Dirigere un'impresa significa:","correct":"prendere decisioni di reperimento, allocazione e impiego di risorse (materiali, immateriali, finanziarie, umane, tecnologiche ecc.)","wrong1":"assumere una serie di rischi relativi all'andamento dell'attività imprenditoriale","wrong2":"prendere decisioni relative relative alla dimensione da conferire alle attività produttive da realizzare","wrong3":"assumere una serie di decisioni su come gestire le risorse umane"},{"id":1825,"paragraph":"Economia delle aziende e delle PA - 37) L'attività di direzione e il sistema di misurazione dei costi: un quadro di riferimento introduttivo","question":"Il sistema informativo alla base del controllo direzionale è costituito da:","correct":"un insieme ordinato di elementi diversi che raccolgono, elaborano, scambiano e archiviano dati relativi a fenomeni economici e attività gestionali dell'azienda","wrong1":"un insieme coordinato di tecnologie che consentono di elaborare i dati in tempo reale","wrong2":"un insieme coordinato di tecnologie che consentono di trarre informazioni dal mercato e comunicare con questo","wrong3":"un insieme ordinato di elementi che raccolgono, elaborano e producono informazioni ai fini delle scelte di produzione"},{"id":1826,"paragraph":"Economia delle aziende e delle PA - 37) L'attività di direzione e il sistema di misurazione dei costi: un quadro di riferimento introduttivo","question":"Gli elementi di criticità del sistema di controllo direzionale sono:","correct":"gli scopi per i quali le informazioni economiche sono richieste dal manager e le condizioni di contesto interno ed esterno all'azienda che possono vincolare l'operato degli stessi","wrong1":"il costo del processo di elaborazione delle informazioni economiche e la variabilità delle informazioni stesse","wrong2":"gli scopi per i quali le informazioni economiche sono richieste dal manager e le diverse esigenze conoscitive dei portatori di interesse","wrong3":"le condizioni di contesto interno ed esterno all'azienda che possono vincolare l'operato degli stessi"},{"id":1827,"paragraph":"Economia delle aziende e delle PA - 38) L'attività di direzione e il sistema di misurazione dei costi: il sistema di misurazione dei costi","question":"Il costo di produzione può essere definito come:","correct":"il valore monetario delle risorse impiegate per la realizzazione dei processi di produzione economica messi in atto dalle aziende","wrong1":"il valore monetario delle risorse impiegate per la realizzazione dei processi di vendita","wrong2":"il valore industriale delle risorse impiegate per la realizzazione dei processi di produzione economica messi in atto dalle aziende","wrong3":"il valore industriale delle risorse impiegate per la realizzazione dei prodotti"},{"id":1828,"paragraph":"Economia delle aziende e delle PA - 38) L'attività di direzione e il sistema di misurazione dei costi: il sistema di misurazione dei costi","question":"Per costo primo si intende:","correct":"il valore delle materie prime impiegate per la realizzazione della produzione","wrong1":"il valore di tutte le risorse impiegate per la realizzazione della produzione","wrong2":"il valore delle quote di ammortamento degli impianti impiegati per la realizzazione della produzione","wrong3":"il valore di tutti i costi del personale impiegati per la realizzazione della produzione"},{"id":1829,"paragraph":"Economia delle aziende e delle PA - 38) L'attività di direzione e il sistema di misurazione dei costi: il sistema di misurazione dei costi","question":"Gli scopi del calcolo del costo di produzione sono:","correct":"valutazione delle rimanenze, supporto decisionale, controllo dell'efficienza operativa","wrong1":"definire adeguati prezzi di vendita dei prodotti","wrong2":"definire il sistema di valorizzazione e remunerazione del personale","wrong3":"definire livelli adeguati di valorizzazione delle rimanenze aziendali"},{"id":1830,"paragraph":"Economia delle aziende e delle PA - 39) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse","question":"Il procedimento diretto di attribuzione dei costi all'unità di prodotto è:","correct":"si tratta di una misurazione oggettiva, in quanto la relazione che lega il consumo del fattore produttivo da parte dell'unità di prodotto è osservabile e misurabile","wrong1":"si tratta di una misurazione soggettiva, in quanto la relazione che lega il consumo del fattore produttivo da parte dell'unità di prodotto non è osservabile e misurabile","wrong2":"si tratta di una misurazione basata su stime","wrong3":"si tratta di una misurazione basata su valori presunti"},{"id":1831,"paragraph":"Economia delle aziende e delle PA - 39) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse","question":"Il Direct Cost si caratterizza per:","correct":"il costo di prodotto è costituito da soli costi diretti, la cui imputazione non necessita di alcuna base di ripartizione","wrong1":"il costo di prodotto è costituito da soli costi fissi","wrong2":"il costo di prodotto è costituito da soli costi standard","wrong3":"il costo di prodotto è costituito da soli costi del personale"},{"id":1832,"paragraph":"Economia delle aziende e delle PA - 39) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse","question":"Nel costo pieno il costo del prodotto è considerato:","correct":"composto dai costi diretti e da quote di costi indiretti attribuiti utilizzando delle basi di ripartizione","wrong1":"composto dai costi diretti e dalle quote di ammortamento delle strumentazioni produttive","wrong2":"composto solo dai costi indiretti attribuiti utilizzando basi di ripartizione","wrong3":"composto solo dai costi indiretti e dai costi di ammortamento dei fattori produttivi"},{"id":1833,"paragraph":"Economia delle aziende e delle PA - 40) La misurazione del costo pieno unitario di prodotto: il sistema dei centri di costo","question":"L'impostazione tradizionale di attribuzione dei costi indiretti al prodotto si basa:","correct":"sulla ricerca di un legame di consumo tra i fattori produttivi e l'unità di prodotto","wrong1":"sulla corretta rappresentazione dell'impiego dei fattori produttivi da parte dei sistemi informativi","wrong2":"sulla corretta rappresentazione dell'impiego dei fattori produttivi da parte dei contabili","wrong3":"sulla corretta rappresentazione dei costi e ricavi aziendali"},{"id":1834,"paragraph":"Economia delle aziende e delle PA - 40) La misurazione del costo pieno unitario di prodotto: il sistema dei centri di costo","question":"Quando si ha un centro di costo:","correct":"quando si ha un'unità organizzativa caratterizzata da un certo ammontare di risorse assegnate, una data tecnologia, un insieme omogeneo di risultati","wrong1":"quando si ha un'unità organizzativa caratterizzata da un certo ammontare di risorse assegnate","wrong2":"quando si ha un'unità organizzativa caratterizzata da un insieme omogeneo di risultati","wrong3":"quando si ha un'unità organizzativa caratterizzata da risorse che generano costi"},{"id":1835,"paragraph":"Economia delle aziende e delle PA - 40) La misurazione del costo pieno unitario di prodotto: il sistema dei centri di costo","question":"Cosa caratterizza i centri di produzione:","correct":"sono rappresentati dalle unità organizzative al cui interno si svolgono i processi di trasformazione vera e propria","wrong1":"sono esterni all'area della produzione e possono riguardare l'area commerciale, amministrativa, ecc","wrong2":"si riferiscono alle unità operative che, sebbene funzionalmente collocate nell'area della produzione, forniscono la loro utilità ad altri centri di costo","wrong3":"si riferiscono alle unità operative che, sebbene funzionalmente collocate nell'area della produzione, non forniscono alcuna utilità"},{"id":1836,"paragraph":"Economia delle aziende e delle PA - 41) Il sistema di misurazione del costo pieno basato sulle attività","question":"L'assunto dell'Activity Based Costing è:","correct":"i prodotti, i servizi, i clienti, consumano le attività del processo produttivo, e queste ultime, utilizzando i vari fattori produttivi, generano i costi","wrong1":"i costi sono generati dai diversi fattori produttivi attivati in azienda","wrong2":"i costi sono definiti sulla base dei centri di costo che è possibile individuare nell'azienda","wrong3":"i costi sono generati dai processi produttivi, soprattutto, per quanto attiene le attività del controllo di qualità"},{"id":1837,"paragraph":"Economia delle aziende e delle PA - 41) Il sistema di misurazione del costo pieno basato sulle attività","question":"Il riferimento alla struttura organizzativa nell'activity based costing rispetto al centro di costo è:","correct":"completamente assente nella definizione di attività mentre è presente come primo elemento distintivo del centro di costo","wrong1":"è presente nella definizione di attività mentre è assente nel centro di costo","wrong2":"è presente allo stesso modo in ambedue i modelli di costing","wrong3":"completamente assente in ambedue i modelli di costing"},{"id":1838,"paragraph":"Economia delle aziende e delle PA - 41) Il sistema di misurazione del costo pieno basato sulle attività","question":"Le quattro fasi dell'Activity Based Management sono:","correct":"identificare le attività che aggiungono valore e quelle che non ne aggiungono; reingegnerizzare l'azienda; fare benchmarking sulle attività che aggiungono valore; sviluppare un sistema di misure per il miglioramento continuo","wrong1":"reingegnerizzare l'azienda; fare il monitoraggio della qualità; sviluppare un sistema di misure per il miglioramento continuo","wrong2":"identificare le attività che non aggiungono valore per eliminarle; fare benchmarking sulle attività che aggiungono valore;","wrong3":"identificare le attività che presentano elevati costi per ridurre tali costi o eliminarle; monitorare tali attività nel tempo"},{"id":1839,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Il caso analizzato quanti prodotti considera:","correct":"2 tipologie di calcolatrici da ufficio","wrong1":"3 tipologie di calcolatrici da ufficio","wrong2":"2 tipologie di pc","wrong3":"2 tipologie di stampanti"},{"id":1840,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"In cosa si differenziano i processi produttivi:","correct":"si differenziano per la quantità di materiali richiesti ed il numero di ore della manodopera di personale","wrong1":"si differenziano per la complessità dei processi produttivi","wrong2":"si differenziano per la tipologia di impianti adottati","wrong3":"si differenziano per la quantità di investimenti richiesti"},{"id":1841,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Il processo produttivo dei due prodotti in quanti centri di costo è articolato:","correct":"in 6 centri di costo","wrong1":"in 2 centri di costo","wrong2":"in 8 centri di costo","wrong3":"in 1 centro di costo"},{"id":1842,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Il caso analizzato cosa chiede di determinare:","correct":"i costi di produzione unitari per ogni prodotto","wrong1":"i costi di distribuzione unitari per ogni prodotto","wrong2":"i costi variabili di produzione","wrong3":"i costi fissi impegnati"},{"id":1843,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Quali sono le componenti dell'Activity Based Costing:","correct":"le categorie di risorse, i driver di risorse, gli activity cost pool, i driver delle attività, gli oggetti di costo, gli input dei costi diretti","wrong1":"i costi fissi, i costi variabili ed i ricavi","wrong2":"i flussi moneteri ed i flussi di costo","wrong3":"le categorie di risorse, i driver di risorse, gli activity cost pool"},{"id":1844,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Quali sono le fasi di progettazione di un modello di costing ABC:","correct":"ricostruzione del processo e rilevazione del costo","wrong1":"rilevazione dei costi fissi e dei costi variabili","wrong2":"la rilevazione dei flussi monetari e dei flussi di costo","wrong3":"la rilevazione delle risorse e dei costi"},{"id":1845,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"La gestione delle attività cosa comporta:","correct":"l'analisi del costo e dell'efficienza delle attività, l'analisi del valore generato dalle attività, il miglioramento continuo della qualità, la re-ingegnerizzazione del processo","wrong1":"l'analisi dei ricavi e delle entrate ed uscite monetarie","wrong2":"l'analisi del miglioramento continuo della qualità, la re-ingegnerizzazione del processo","wrong3":"l'analisi del costo e dell'efficienza delle attività"},{"id":1846,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Che tipo di matrice viene adottata per il calcolo del costing:","correct":"la matrice risorse-attività","wrong1":"la matrice dei processi","wrong2":"la matrice di analisi dei tempi","wrong3":"la matrice delle attività"},{"id":1847,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Qual è l'activity driver del set-up:","correct":"il numero di set-up","wrong1":"il numero di metri quadri","wrong2":"il numero dei controlli","wrong3":"le ore impegnate"},{"id":1848,"paragraph":"Economia delle aziende e delle PA - 42) La misurazione del costo pieno unitario di prodotto: l'orientamento alle risorse e il sistema dei centri di costo - esercitazione","question":"Qual è l'activity driver del controllo qualità:","correct":"il numero di controlli","wrong1":"le ore impegnate","wrong2":"il numero di set-up","wrong3":"il numero di metri quadri"},{"id":1849,"paragraph":"Economia delle aziende e delle PA -  43) La misurazione dei costi di prodotto in differenti contesti produttivi: produzioni su commessa","question":"Nella produzione per singola unità:","correct":"l'oggetto della produzione è costituito da unità identificabili e fisicamente/logicamente distinguibili dalle altre","wrong1":"l'oggetto della produzione è costituito da prodotti fisicamente non individuabili a livello unitario, almeno fino ad una fase avanzata del processo di produzione","wrong2":"l'oggetto della produzione è costituito da prodotti fisicamente individuabili a livello unitario ma non distinguibili dagli altri della stessa tipologia","wrong3":"l'oggetto della produzione è costituito da un insieme di prodotti fisicamente individuabili a livello unitario"},{"id":1850,"paragraph":"Economia delle aziende e delle PA -  43) La misurazione dei costi di prodotto in differenti contesti produttivi: produzioni su commessa","question":"I costi diretti nella produzione su commessa sono:","correct":"i costi specifici direttamente attribuibili alla commessa","wrong1":"i costi specifici attribuibili a tutte le commesse","wrong2":"i costi comuni collegati alla singola commessa","wrong3":"i costi comuni di tutte le commesse"},{"id":1851,"paragraph":"Economia delle aziende e delle PA -  43) La misurazione dei costi di prodotto in differenti contesti produttivi: produzioni su commessa","question":"Nelle produzioni su commessa tutti i costi sono accumulati in uno specifico documento denominato:","correct":"scheda di commessa","wrong1":"scheda materiali","wrong2":"scheda cliente","wrong3":"scheda di processo"},{"id":1852,"paragraph":"Economia delle aziende e delle PA -  44) La misurazione dei costi di prodotto in differenti contesti produttivi: processi a flusso continui","question":"Quando un prodotto è completato in un reparto:","correct":"i costi vengono trasferiti al reparto successivo sulla base del costo unitario medio di reparto","wrong1":"i costi vengono trasferiti al reparto successivo sulla base del costo marginale di prodotto","wrong2":"i costi vengono trasferiti al reparto successivo sulla base del costo diretto di reparto","wrong3":"i costi vengono trasferiti al reparto successivo sulla base del costo indiretto di reparto"},{"id":1853,"paragraph":"Economia delle aziende e delle PA -  44) La misurazione dei costi di prodotto in differenti contesti produttivi: processi a flusso continui","question":"Per il calcolo del costo medio ponderato con il metodo MEP:","correct":"al numeratore vengono posti tutti i costi sostenuti (a prescindere dal periodo di produzione) e al denominatore le UEP complessive (a prescindere dal periodo di produzione)","wrong1":"al numeratore vengono posti tutti i costi diretti sostenuti e al denominatore tutti i costi indiretti sostenuti","wrong2":"al numeratore vengono posti tutti i costi variabile sostenuti e al denominatore tutti i costi fissi sostenuti","wrong3":"al numeratore vengono posti tutti i costi sostenuti riferiti all'ultimo periodo di produzione e al denominatore le UEP complessive riferite all'ultimo periodo di produzione"},{"id":1854,"paragraph":"Economia delle aziende e delle PA -  44) La misurazione dei costi di prodotto in differenti contesti produttivi: processi a flusso continui","question":"I prodotti congiunti in senso stretto:","correct":"sono prodotti che presentano valori di vendita relativamente comparabili","wrong1":"sono prodotti che presentano valori di vendita di tipo standard","wrong2":"sono prodotti che presentano valori di vendita non comparabili","wrong3":"sono prodotti che presentano costi di acquisto delle materie relativamente comparabili"},{"id":1855,"paragraph":"Economia delle aziende e delle PA -  45) Il sistema di misurazione dei costi a valori preventivi: i costi standard","question":"I costi standard:","correct":"sono parametri-obiettivo che riflettono condizioni operative, normali o ideali, di acquisizione e di impiego dei fattori produttivi","wrong1":"sono costi relativi all'acquisizione dei fattori produttivi al valore medio dell'anno solare","wrong2":"sono parametri-obiettivo che riflettono condizioni operative particolari inerenti l'impiego dei fattori produttivi ai costi sostenuti da tutto il settore di riferimento","wrong3":"sono valori di costo che riflettono condizioni operative attuali di impiego dei fattori produttivi"},{"id":1856,"paragraph":"Economia delle aziende e delle PA -  45) Il sistema di misurazione dei costi a valori preventivi: i costi standard","question":"Con la funzione di programmazione dello standard costing:","correct":"la misurazione degli standard consente di determinare analiticamente le risorse da acquisire ed impiegare","wrong1":"la misurazione degli standard consente di programmare l'attività complessiva dell'azienda","wrong2":"la misurazione degli standard consente di definire gli obiettivi aziendali","wrong3":"la misurazione degli standard consente di programmare i prezzi di vendita dei prodotti realizzati"},{"id":1857,"paragraph":"Economia delle aziende e delle PA -  45) Il sistema di misurazione dei costi a valori preventivi: i costi standard","question":"Nell'ambito delle tecniche di determinazione dei costi standard, l'approccio statistico:","correct":"la previsione viene basata sull'analisi dei dati storici","wrong1":"la previsione viene basata sull'analisi dei dati presunti","wrong2":"la previsione viene basata sull'analisi dei dati standard","wrong3":"la previsione viene basata sull'analisi dei dati attuali"},{"id":1858,"paragraph":"Economia delle aziende e delle PA -  46) Il sistema di misurazione dei costi a valori preventivi: l'analisi degli scostamenti","question":"L'analisi degli scostamenti si articola in:","correct":"rilevazione degli scostamenti globali, rilevazione degli scostamenti elementari e interpretazione degli scostamenti","wrong1":"rilevazione degli scostamenti globali, rilevazione degli scostamenti dei costi diretti e rilevazione degli scostamenti dei costi indiretti","wrong2":"rilevazione degli scostamenti globali, rilevazione degli scostamenti di costi diretti e rilevazione degli scostamenti di costi medi","wrong3":"rilevazione degli scostamenti di profitto, rilevazione degli scostamenti di costi diretti e interpretazione degli scostamenti"},{"id":1859,"paragraph":"Economia delle aziende e delle PA -  46) Il sistema di misurazione dei costi a valori preventivi: l'analisi degli scostamenti","question":"Nello scostamento dei costi fissi, lo scostamento di volume:","correct":"è uno scostamento di assorbimento che misura la differenza di assorbimento dei costi fissi derivanti da variazioni, rispetto a quanto preventivato, nelle condizioni operative di utilizzo della struttura","wrong1":"è uno scostamento di assorbimento che misura la differenza di assorbimento dei costi totali derivanti da variazioni, rispetto a quanto preventivato, nelle condizioni operative di utilizzo della struttura","wrong2":"è uno scostamento di assorbimento che misura la differenza di assorbimento dei costi collegati alla manodopera derivanti da variazioni, rispetto a quanto preventivato, nelle condizioni operative di utilizzo della struttura","wrong3":"è uno scostamento di assorbimento che misura la differenza di assorbimento delle amterie prime derivanti da variazioni, rispetto a quanto preventivato, nelle condizioni operative di utilizzo della struttura"},{"id":1860,"paragraph":"Economia delle aziende e delle PA -  46) Il sistema di misurazione dei costi a valori preventivi: l'analisi degli scostamenti","question":"Il normal costing è:","correct":"un sistema ibrido che accoglie sia valori preventivi che valori consuntivi","wrong1":"un sistema ibrido che accoglie sia valori fissi che variabili","wrong2":"un sistema ibrido che accoglie sia costi diretti che costi indiretti","wrong3":"un sistema ibrido che accoglie sia valori effettivi che valori standard"},{"id":1861,"paragraph":"Economia delle aziende e delle PA -  47) Le metodologie di rilevazione analitica:","question":"Il sistema del reddito si basa su:","correct":"rilevazioni analitiche periodiche e a complemento di quelle di contabilità generale","wrong1":"rilevazioni analitiche integrate e simultanee con quelle di contabilità generale","wrong2":"rilevazioni simultanee di costi fissi e costi variabili","wrong3":"rilevazioni simultanee di costi diretti e costi indiretti"},{"id":1862,"paragraph":"Economia delle aziende e delle PA -  47) Le metodologie di rilevazione analitica:","question":"I conti di magazzino:","correct":"accolgono i movimenti nelle consistenze inventariali di materie prime semilavorati e prodotti finti","wrong1":"accolgono i movimenti di vendita nelle unità operative addette alla vendita al cliente","wrong2":"accolgono i movimenti di acquisto e vendita dei prodotti","wrong3":"accolgono i movimenti nelle consistenze inventariali di prodotti finti"},{"id":1863,"paragraph":"Economia delle aziende e delle PA -  47) Le metodologie di rilevazione analitica:","question":"I sistemi integrati o Enterprise Resource Planning (ERP) sono:","correct":"supporti tecnologici costituiti da pacchetti software le cui applicazioni coprono le esigenze informative delle funzioni aziendali","wrong1":"supporti tecnologici le cui applicazioni sono utili per la pianificazione aziendale","wrong2":"supporti tecnologici le cui applicazioni sono utili per pianificare le vendite aziendali","wrong3":"software utili per le analisi di mercato"},{"id":1864,"paragraph":"Economia delle aziende e delle PA -  48) La sequenza delle rilevazioni contabili analitiche dei costi e dei ricavi in un sistema unico integrato","question":"L'acquisto di merci costituisce:","correct":"un incremento delle rimanenze di materiali (attività patrimoniale) a fronte di obbligazioni assunte nei confronti dei Fornitori (passività patrimoniale)","wrong1":"un incremento di debiti nei confronti dei Fornitori (passività patrimoniale)","wrong2":"un incremento degli acquisti a fronte di obbligazioni assunte nei confronti dei Clienti (passività patrimoniale)","wrong3":"un incremento delle rimanenze di immobili (attività patrimoniale) a fronte di obbligazioni assunte nei confronti delle Banche (passività patrimoniale)"},{"id":1865,"paragraph":"Economia delle aziende e delle PA -  48) La sequenza delle rilevazioni contabili analitiche dei costi e dei ricavi in un sistema unico integrato","question":"Con la vendita di un prodotto finito si rileva:","correct":"il credito verso i clienti (attività patrimoniale) e i ricavi di vendita (componente positiva di reddito)","wrong1":"il credito verso i fornitori (attività patrimoniale) e i ricavi di vendita (componente positiva di reddito)","wrong2":"il credito verso i clienti (attività patrimoniale) e i costi di vendita (componente positiva di reddito)","wrong3":"il credito verso i fornitori (attività patrimoniale) e i costi di vendita (componente positiva di reddito)"},{"id":1866,"paragraph":"Economia delle aziende e delle PA -  48) La sequenza delle rilevazioni contabili analitiche dei costi e dei ricavi in un sistema unico integrato","question":"Nell'ambito delle rilevazioni nei sistemi contabili integrati a valori standard e varianze, i processi di acquisizione del lavoro sono:","correct":"contestuali","wrong1":"da attivare","wrong2":"non contestuali","wrong3":"ipotetici"},{"id":1867,"paragraph":"Economia delle aziende e delle PA -  49) I sistemi di misurazione a costi diretti e variabili e le condizioni di rischio operativo","question":"Nella configurazione a direct costing, la scheda di costo unitario di prodotto considera:","correct":"le materie prime, la manodopera e gli altri costi diretti","wrong1":"le materie prime, la manodopera, gli altri costi diretti ed i costi fissi specifici","wrong2":"le materie prime, la manodopera, gli altri costi diretti variabili ed i costi indiretti variabili","wrong3":"le materie prime, la manodopera, gli altri costi diretti ed i costi indiretti variabili"},{"id":1868,"paragraph":"Economia delle aziende e delle PA -  49) I sistemi di misurazione a costi diretti e variabili e le condizioni di rischio operativo","question":"Nella configurazione a variable costing, la scheda di costo unitario di prodotto considera:","correct":"le materie prime, la manodopera, gli altri costi diretti variabili e i costi indiretti variabili","wrong1":"le materie prime, la manodopera ed i costi diretti variabili","wrong2":"le materie prime, la manodopera, gli altri costi diretti variabili e i costi figurativi variabili","wrong3":"le materie prime e i costi indiretti variabili"},{"id":1869,"paragraph":"Economia delle aziende e delle PA -  49) I sistemi di misurazione a costi diretti e variabili e le condizioni di rischio operativo","question":"Il rischio operativo:","correct":"è il rischio che l'impresa corre di generare delle perdite, a livello di reddito operativo, per effetto di variazioni nei livelli di attività connessi alla gestione caratteristica","wrong1":"è il rischio che l'impresa corre di generare delle perdite, a livello di reddito operativo, per effetto di variazioni nei livelli di attività connessi alla gestione straordinaria","wrong2":"è il rischio che l'impresa corre di generare delle perdite, a livello di reddito totale, per effetto di variazioni nei livelli di attività connessi alla gestione caratteristica","wrong3":"è il rischio che l'impresa corre di generare delle perdite, a livello di reddito operativo, per effetto di variazioni nei livelli di attività connessi alla gestione fiscale"},{"id":1870,"paragraph":"Economia delle aziende e delle PA -  50) La break even analysis","question":"Il punto di pareggio, break even point, rappresenta:","correct":"il livello di attività in corrispondenza del quale i costi totali aziendali coincidono con i ricavi totali di vendita","wrong1":"il livello di attività in corrispondenza del quale i costi fissi aziendali coincidono con i ricavi totali di vendita","wrong2":"il livello di attività in corrispondenza del quale i costi variabili aziendali coincidono con i ricavi totali di vendita","wrong3":"il livello di attività in corrispondenza del quale i costi totali aziendali coincidono con i ricavi unitari di vendita"},{"id":1871,"paragraph":"Economia delle aziende e delle PA -  50) La break even analysis","question":"La leva operativa rappresenta:","correct":"il rapporto tra la variazione percentuale del reddito operativo e quella delle unità vendute","wrong1":"il rapporto tra la variazione percentuale del reddito operativo e quella delle unità di prodotto programmate","wrong2":"il rapporto tra la variazione percentuale del costo variabile e quella delle unità vendute","wrong3":"il rapporto tra la variazione percentuale del costo fisso e quella delle unità vendute"},{"id":1872,"paragraph":"Economia delle aziende e delle PA -  50) La break even analysis","question":"La Break even analysis consente:","correct":"la valutazione degli effetti delle scelte aziendali sul rapporto costi-volumi-risultati","wrong1":"la valutazione degli effetti delle scelte aziendali sui costi","wrong2":"la valutazione degli effetti delle scelte aziendali sui ricavi","wrong3":"la valutazione degli effetti delle scelte aziendali in termini di strategia"},{"id":1873,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Cosa vuole realizzare l'Ospedale di Montefiorito:","correct":"vuole dotare la sua Divisione di Ostetrica e Ginecologia di un'unità attrezzata per la cardiotocografia","wrong1":"vuole raddoppiare il numero dei posti letto","wrong2":"vuole istituire un centro unico per le prenotazioni","wrong3":"vuole aumentare il numero del personale"},{"id":1874,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Il percorso di sviluppo dell'Ospedale Montefiorito inciderà sul livello dei costi totali:","correct":"aumenteranno i costi totali in seguito all'investimento previsto","wrong1":"i costi aumenteranno dal secondo esercizio","wrong2":"aumenteranno solo i ricavi","wrong3":"i costi totali resteranno invariati"},{"id":1875,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Le scelte operate dall'Ospedale Montefiorito come incideranno sui costi fissi:","correct":"i costi fissi aumenteranno per acquisto macchinario, personale e manutenzione","wrong1":"i costi fissi resteranno immutati nei primi 2 anni per poi aumentare","wrong2":"i costi fissi resteranno invariati","wrong3":"i costi fissi diminuiranno"},{"id":1876,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Le scelte operate dall'Ospedale Montefiorito come incideranno sui costi variabili:","correct":"i costi variabili aumenteranno per materiale di consumo e costi di energia elettrica","wrong1":"resteranno invariati","wrong2":"saranno invariati per i primi 2 anni per poi aumentare","wrong3":"i costi variabili diminuiranno"},{"id":1877,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Cosa è il Break even Point o punto di equilibrio:","correct":"rappresenta la quantità di produzione, e quindi di vendita, che consente di coprire i costi totali","wrong1":"rappresenta la quantità di produzione, e quindi di vendita, che consente di coprire i costi fissi","wrong2":"rappresenta la quantità di produzione, e quindi di vendita, che consente di coprire i costi variabili","wrong3":"rappresenta la quantità di produzione, e quindi di vendita, che consente di coprire i costi del personale"},{"id":1878,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Cosa caratterizza il punto di equilibrio finanziario:","correct":"come costi fissi e costi variabili si considerano solo quelli che generano esborsi monetari","wrong1":"come costi fissi e costi variabili si considerano solo quelli che non generano esborsi monetari","wrong2":"come costi fissi e costi variabili si considerano solo quelli certificabili","wrong3":"come costi fissi e costi variabili si considerano solo quelli che si verificano oltre l'anno di riferimento"},{"id":1879,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Cosa consente di misurare la potenzialità economico strutturale:","correct":"misura l'area delle perdite e quella dei profitti ed il conseguente grado di rischio","wrong1":"misura il grado di copertura dei semivariabili","wrong2":"misura il grado di copertura dei costi fissi","wrong3":"misura il grado di copertura dei costi variabili"},{"id":1880,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Cosa rappresenta il margine di contribuzione:","correct":"la parte del prezzo di vendita che residua dopo la copertura dei costi variabili ed è quindi destinata alla copertura dei costi fissi","wrong1":"la parte del prezzo di vendita che residua dopo la copertura dei costi fissi","wrong2":"la parte del prezzo di vendita che residua dopo la copertura dei costi totali","wrong3":"la parte del prezzo di vendita che residua dopo la copertura dei costi semivariabili"},{"id":1881,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Si raggiunge il punto di equilibrio:","correct":"si raggiunge il punto di equilibrio per valori inferiori alla capacità produttiva massima","wrong1":"il punto di equilibrio si raggiunge a valori superiori della capacità produttiva massima","wrong2":"il punto di equilibrio è pari alla capacità produttiva massima","wrong3":"non si raggiunge il punto di equilibrio"},{"id":1882,"paragraph":"Economia delle aziende e delle PA -  51) Esercitazione sulla break even analysis","question":"Si raggiunge il Break even point:","correct":"sì, corrisponde al punto di equilibrio","wrong1":"si raggiunge dopo del punto di equilibrio","wrong2":"si raggiunge prima del punto di equilibrio","wrong3":"non si raggiunge"},{"id":1883,"paragraph":"Economia delle aziende e delle PA -  52) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni in condizioni di certezza e di rischio","question":"Le decisioni operative si caratterizzano perché comportano:","correct":"assunzione di decisioni mediante le quali i manager si assicurano che le risorse siano acquisite ed utilizzate in maniera efficace ed efficiente, per conseguire le finalità aziendali","wrong1":"decisioni mediante le quali i manager definiscono gli obiettivi e i cambiamenti negli obiettivi dell'impresa, le risorse da impiegare per raggiungere tali obiettivi, le modalità di acquisizione, impiego e allocazione di tali risorse ai vari programmi strategici","wrong2":"assunzione di decisioni mediante le quali i manager si assicurano che le risorse siano acquisite ed utilizzate in coerenza con gli obiettivi di budget","wrong3":"decisioni mediante le quali i manager definiscono gli obiettivi e i cambiamenti negli obiettivi dell'impresa"},{"id":1884,"paragraph":"Economia delle aziende e delle PA -  52) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni in condizioni di certezza e di rischio","question":"L'analisi differenziale si fonda su:","correct":"sull'identificazione degli elementi del profitto (volumi, prezzi di vendita, costi variabili, costi fissi) rilevanti per valutare la convenienza della particolare decisione oggetto di analisi e valutazione","wrong1":"sull'identificazione degli andamenti del settore economico (volumi, prezzi di vendita, costi variabili, costi fissi) rilevanti per valutare le scelte di produzione","wrong2":"sull'identificazione degli elementi di costo utili per valutare la convenienza della particolare decisione oggetto di analisi e valutazione","wrong3":"sull'identificazione degli elementi di marketing utili per valutare la convenienza della particolare decisione di mercato"},{"id":1885,"paragraph":"Economia delle aziende e delle PA -  52) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni in condizioni di certezza e di rischio","question":"Il processo decisionale in condizioni di incertezza si caratterizza per:","correct":"assenza o insufficienza di informazioni rispetto a una situazione futura, che non consente di determinare delle probabilità, poiché non si conoscono risultati ed eventi","wrong1":"ambiente deterministico, caratterizzato da una situazione di informazione perfetta","wrong2":"assenza o insufficienza di informazioni rispetto a una situazione futura, che però consente di determinare delle probabilità, poiché si conoscono risultati ed eventi","wrong3":"ambiente deterministico, caratterizzato da una situazione di informazione quasi perfetta"},{"id":1886,"paragraph":"Economia delle aziende e delle PA -  53) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni operative e strategiche","question":"L'introduzione di un nuovo segmento risulta conveniente dal punto di vista economico se:","correct":"tale segmento genera un risultato economico positivo, in termini di margine a copertura dei costi variabili e fissi specifici incrementali, e contribuisce, di conseguenza, all'incremento del risultato operativo aziendale","wrong1":"tale segmento genera un risultato economico negativo, in termini di margine a copertura dei costi variabili e fissi specifici incrementali, non contribuendo, di conseguenza, all'incremento del risultato operativo aziendale","wrong2":"tale segmento genera un risultato economico positivo, in termini di margine a copertura dei costi diretti, e contribuisce, di conseguenza, all'incremento del risultato operativo aziendale","wrong3":"tale segmento genera un risultato economico positivo, in termini di margine a copertura dei costi variabili"},{"id":1887,"paragraph":"Economia delle aziende e delle PA -  53) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni operative e strategiche","question":"L'assunzione di decisioni in condizioni di rischio prevede che, a supporto dei processi decisionali, possano essere impiegate:","correct":"informazioni rappresentate attraverso distribuzioni di probabilità, dato che non si conoscono con certezza i valori esatti","wrong1":"informazioni basate su dati certi, dato che si conoscono con certezza i valori esatti","wrong2":"informazioni rappresentate attraverso distribuzioni di probabilità, dato che si conoscono con certezza i valori esatti","wrong3":"informazioni rappresentate attraverso dati certi e validati, dato che non si conoscono con certezza i valori esatti"},{"id":1888,"paragraph":"Economia delle aziende e delle PA -  53) Le informazioni economiche a supporto dei processi decisionali di breve periodo: decisioni operative e strategiche","question":"L'incertezza è:","correct":"l'assenza o insufficienza di informazioni rispetto a una situazione futura","wrong1":"la sufficienza di informazioni rispetto a una situazione futura","wrong2":"l'assenza o insufficienza di ricavi rispetto a una situazione ipotizzata","wrong3":"l'adeguatezza di informazioni rispetto a una situazione futura"},{"id":1889,"paragraph":"Economia delle aziende e delle PA -  54) Le decisioni di investimento e il Capital Budgeting","question":"Per capital budgeting si intende:","correct":"un processo di pianificazione delle decisioni di investimento di lungo termine, che impattano sulla gestione aziendale per più esercizi","wrong1":"un processo di pianificazione delle decisioni di investimento di breve termine, che impattano sulla gestione aziendale per un esercizio","wrong2":"un processo di pianificazione delle decisioni di investimento di lungo termine, che impattano sulla gestione aziendale per un esercizio","wrong3":"un processo di pianificazione delle decisioni di acquisto di risorse, che impattano sulla gestione aziendale per più esercizi"},{"id":1890,"paragraph":"Economia delle aziende e delle PA -  54) Le decisioni di investimento e il Capital Budgeting","question":"Il Valore attuale netto (VAN) si basa su:","correct":"si basa sul confronto tra il valore attuale dei cash flow futuri e il valore dell'investimento iniziale","wrong1":"si basa sul confronto tra il valore dei costi fissi futuri e il valore dell'investimento iniziale","wrong2":"si basa sul confronto tra il valore finale dei costi variabili e il valore dell'investimento iniziale","wrong3":"si basa sul confronto tra il valore attuale dei costi futuri e il valore dell'investimento iniziale"},{"id":1891,"paragraph":"Economia delle aziende e delle PA -  54) Le decisioni di investimento e il Capital Budgeting","question":"Il Tasso interno di rendimento (TIR) è:","correct":"il tasso che annulla il VAN","wrong1":"il tasso che rende positivo il VAN","wrong2":"il tasso che rende negativo il VAN","wrong3":"il tasso che moltiplica il VAN"},{"id":1892,"paragraph":"Economia delle aziende e delle PA -  55) La pianificazione strategica e il budget: aspetti metodologici","question":"Controllare un'impresa comporta una serie di fasi logiche:","correct":"l'identificazione degli obiettivi, la misurazione dei risultati ottenuti in seguito alle azioni, la valutazione del grado di raggiungimento degli obiettivi, la risposta ed inizio del successivo ciclo di controllo","wrong1":"l'identificazione degli obiettivi, la valutazione del grado di raggiungimento degli obiettivi, l'assegnazione delle ricompense, l'erogazione delle ricompense per il raggiungimento degli obiettivi, la risposta ed inizio del successivo ciclo di controllo","wrong2":"l'identificazione degli obiettivi, la valutazione del grado di raggiungimento degli obiettivi, la risposta ed inizio del successivo ciclo di controllo","wrong3":"l'identificazione degli obiettivi, la misurazione dei risultati ottenuti in seguito alle azioni, la valutazione del grado di raggiungimento degli obiettivi"},{"id":1893,"paragraph":"Economia delle aziende e delle PA -  55) La pianificazione strategica e il budget: aspetti metodologici","question":"Il Master Budget comprende:","correct":"conto economico, stato patrimoniale e rendiconto finanziario preventivi","wrong1":"le attività che generano reddito per l'impresa: costi, ricavi e consistenze dei magazzini","wrong2":"le entrate e le uscite di cassa, la posizione finanziaria dell'azienda e gli investimenti","wrong3":"conto economico e rendiconto finanziario"},{"id":1894,"paragraph":"Economia delle aziende e delle PA -  55) La pianificazione strategica e il budget: aspetti metodologici","question":"Le forme di revisione del budget hanno manifestazione tipica nel:","correct":"budget flessibile, revised budget, budget scorrevoli","wrong1":"budget mensile, budget produzione, budget autorizzativo","wrong2":"budget autorizzativo, budget finanziario, budget operativo","wrong3":"budget magazzino, budget finanziario, budget operativo"},{"id":1895,"paragraph":"Economia delle aziende e delle PA -  56) Il controllo economico e il ruolo del budget: aspetti organizzativi","question":"Nell'ambito del budget, il Centro di ricavo è:","correct":"unità organizzativa il cui responsabile è tenuto a massimizzare i ricavi di vendita","wrong1":"unità organizzativa dove i ricavi sono superiori ai costi","wrong2":"unità organizzativa dove sono allocati solo ricavi e non costi","wrong3":"unità organizzativa in cui sono allocati tutti i ricavi dell'impresa"},{"id":1896,"paragraph":"Economia delle aziende e delle PA -  56) Il controllo economico e il ruolo del budget: aspetti organizzativi","question":"Le finalità del processo di budgeting in riferimento alla dimensione comportamentale ed organizzativa sono:","correct":"responsabilizzazione e motivazione, valutazione delle performance, coordinamento e integrazione, formazione e apprendimento","wrong1":"definizione obiettivi, valutazione delle performance, calcolo dei costi, formazione e apprendimento","wrong2":"definire un piano di incentivi, valutazione dei costi, coordinamento e integrazione, formazione e apprendimento","wrong3":"responsabilizzazione e motivazione, valutazione dei costi, formazione e apprendimento"},{"id":1897,"paragraph":"Economia delle aziende e delle PA -  56) Il controllo economico e il ruolo del budget: aspetti organizzativi","question":"Nel processo di budgeting i responsabili delle unità organizzative:","correct":"identificano le azioni da compiere per il raggiungimento degli obiettivi e i piani di contingenza in caso di mancato raggiungimento degli stessi, esprimono, inoltre, il contenuto delle azioni in valori economico-finanziari","wrong1":"identificano le azioni da compiere per il raggiungimento dei volumi produttivi, esprimono, inoltre, i valori di costi dei diversi processi produttivi","wrong2":"identificano le azioni da compiere per il raggiungimento degli obiettivi e i piani di contingenza in caso di mancato raggiungimento degli stessi","wrong3":"identificano le azioni da compiere per migliorare i processi produttivi, ne valorizzano l'assorbimento delle risorse attraverso i sistemi di costing, esprimono, inoltre, il contenuto delle azioni in valori economico-finanziari"},{"id":1898,"paragraph":"Economia delle aziende e delle PA -  57) Il reporting per la misurazione delle performance aziendali","question":"Il sistema di reporting per la direzione è:","correct":"uno strumento di misurazione e di rappresentazione dei risultati dell'impresa o di sue parti componenti","wrong1":"uno strumento di misurazione dei valori di costo del prodotto","wrong2":"uno strumento di definizione e rappresentazione degli obiettivi da raggiungere nell'anno","wrong3":"uno strumento in grado di rappresentare gli obiettivi strategici aziendali nei prossimi 3 anni"},{"id":1899,"paragraph":"Economia delle aziende e delle PA -  57) Il reporting per la misurazione delle performance aziendali","question":"I costi specifici sono:","correct":"costi riferiti a fattori produttivi i cui processi di impiego/utilizzo possono attribuirsi in via esclusiva all'oggetto di calcolo preso in considerazione","wrong1":"costi riferiti a fattori produttivi i cui processi di impiego/utilizzo possono attribuirsi alla maggioranza dei prodotti realizzati dall'impresa","wrong2":"costi riferiti a fattori produttivi i cui processi di impiego/utilizzo possono attribuirsi in modo generalizzato e non esclusovo all'oggetto di calcolo preso in considerazione","wrong3":"costi riferiti a fattori produttivi i cui processi di impiego/utilizzo possono attribuirsi facendo riferimento alla specificità del settore produttivo"},{"id":1900,"paragraph":"Economia delle aziende e delle PA -  57) Il reporting per la misurazione delle performance aziendali","question":"Sottraendo dai ricavi di area i costi specifici di area si ottiene:","correct":"il margine di area","wrong1":"il profitto","wrong2":"il reddito prima delle imposte","wrong3":"il reddito operativo"},{"id":1901,"paragraph":"Economia delle aziende e delle PA -  58) Lo schema di conto economico a direct costing e full costing","question":"Lo schema di conto economico a direct costing consente:","correct":"di distinguere i costi variabili dai costi fissi e, all'interno di questi ultimi, i costi specifici dai costi comuni","wrong1":"di distinguere i costi variabili dai costi comuni","wrong2":"di distinguere i costi diretti di produzione dai costi indiretti di produzione","wrong3":"di distinguere i costi diretti totali dell'azienda dai costi indiretti totali"},{"id":1902,"paragraph":"Economia delle aziende e delle PA -  58) Lo schema di conto economico a direct costing e full costing","question":"Adottare una configurazione di costo variabile, piuttosto che di costo pieno, ha un diverso impatto sul risultato economico, a causa di due fenomeni:","correct":"la differente distinzione tra costi di prodotto e di periodo, adottata dai due sistemi di misurazione dei costi e la relazione tra volumi di produzione e di vendita del periodo","wrong1":"la differente distinzione tra costi fissi e variabili, adottata dai due sistemi di misurazione dei costi e la relazione tra volumi di produzione e di budget","wrong2":"la differente distinzione tra costi diretti e costi pieni, adottata dai due sistemi di misurazione dei costi e la relazione tra volumi di acquisto e di vendita del periodo","wrong3":"la differente distinzione tra costi di prodotto e di periodo, adottata dai due sistemi di misurazione dei costi e la relazione tra volumi di previsione di budget e di vendita del periodo"},{"id":1903,"paragraph":"Economia delle aziende e delle PA -  58) Lo schema di conto economico a direct costing e full costing","question":"Nel confronto tra sistemi a costi variabili e sistemi a costo pieno, se i volumi di produzione sono pari ai volumi di vendita:","correct":"il Risultato Operativo calcolato a costi pieni è uguale al Risultato Operativo calcolato a costo variabile","wrong1":"è possibile calcolare solo il Risultato Operativo a costo variabile","wrong2":"il Risultato Operativo calcolato a costi pieni è minore al Risultato Operativo calcolato a costo varibile","wrong3":"il Risultato Operativo calcolato a costi pieni è maggiore al Risultato Operativo calcolato a costo varibile"},{"id":1904,"paragraph":"Economia delle aziende e delle PA -  59) I reporting","question":"Lo scostamento di quota di mercato:","correct":"misura l'impatto sul risultato economico di una variazione della porzione di mercato servita","wrong1":"misura l'impatto sul risultato economico di un cambiamento nei volumi o nel valore del mercato di riferiment","wrong2":"misura l'impatto sul risultato economico di variazioni intervenute nel prezzo di vendita dei singoli prodotti/servizi","wrong3":"misura la variazione del risultato economico dovuta ad una diversa combinazione delle vendite di prodotti/servizi (mix)"},{"id":1905,"paragraph":"Economia delle aziende e delle PA -  59) I reporting","question":"Nell'esempio riportato nella lezione, il primo scostamento considerato è dato:","correct":"dalla differenza tra Budget e Budget flessibile","wrong1":"dalla differenza tra Budget e Consuntivo","wrong2":"dalla differenza tra Reddito Operativo e Margine di Contribuzione","wrong3":"dalla differenza tra Reddito Operativo e Risultato ante-imposte"},{"id":1906,"paragraph":"Economia delle aziende e delle PA -  59) I reporting","question":"Le proposte più convincenti e maggiormente diffuse nella pratica aziendale per misura del valore creato sono rappresentate da:","correct":"economic profit e economic value added","wrong1":"break eve analysis e balanced scorecard","wrong2":"budget tradizionale e budget evoluto","wrong3":"direct costing e full costing"},{"id":1907,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Qual è l'orizzonte temporale della Balanced Scorecard:","correct":"3 anni","wrong1":"1 anno","wrong2":"5 anni","wrong3":"10 anni"},{"id":1908,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Quale approccio alla performance adotta la Balanced Scorecard:","correct":"l'approccio olistico","wrong1":"l'approccio finanziario","wrong2":"l'approccio for profit","wrong3":"l'approccio manageriale"},{"id":1909,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Da quali autori è stata sviluppata la Balanced Scorecard:","correct":"kaplan e norton","wrong1":"kaplan e mintzberg","wrong2":"mintzberg e lega","wrong3":"lega e longo"},{"id":1910,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Nel 1996 quale cambiamento subisce la BSC:","correct":"si passa dalla Bsc intesa come scheda di misurazione delle performance aziendali alla Bsc intesa come processo di management strategico","wrong1":"si passa dalla BSC di breve termine alla BSC di lungo termine","wrong2":"si passa dalla BSC metodologica alla BSC Strategica","wrong3":"si passa dalla BSC intesa come scheda di misurazione dele performance aziendali alla BSC di bilancio"},{"id":1911,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Qual è il principale merito della BSC:","correct":"quello di collegare gli obiettivi operativi a breve termine con gli obiettivi strategici a lungo termine","wrong1":"quello di collegare gli obiettivi strategici a breve termine con il bilancio","wrong2":"quello di collegare gli obiettivi strategici a breve termine con il budget","wrong3":"quello di collegare gli obiettivi operativi a breve termine con il budget"},{"id":1912,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Quante sono le prospettive analizzate dalla BSC:","correct":"4","wrong1":"sono collegate al numero di aree aziendali","wrong2":"3","wrong3":"sono variabili"},{"id":1913,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Come devono essere le misure scelte dall'azienda:","correct":"chiare - semplici e dinamiche","wrong1":"chiare - semplici e collegate a valori storici","wrong2":"chiare - strategiche e di lungo periodo","wrong3":"variabili"},{"id":1914,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Qual è l'orizzonte temporale del Piano della Performance:","correct":"3 anni","wrong1":"5 anni","wrong2":"1 anno","wrong3":"10 anni"},{"id":1915,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Quale normativa prevede la Balanced Scorecard come strumento di controllo strategico:","correct":"delibera ANAC ex CIVIT 89/2010","wrong1":"il Piano Sanitario regionale","wrong2":"il Piano Sanitario Nazionale","wrong3":"nessuna normativa"},{"id":1916,"paragraph":"Economia delle aziende e delle PA -  60) La balanced scorecard: approfondimenti","question":"Cosa si intende per Piano della Performance:","correct":"una programmazione triennale degli obiettivi strategici dell'amministrazione","wrong1":"una programmazione triennale degli obiettivi strategici dell'azienda privata","wrong2":"si intende i processi di attribuzione delle risorse alle diverse unità aziendali","wrong3":"i processi di analisi e valutazione delle alternative strategiche che l'azienda ha a disposizione"}];
